static void clear_memory(u8 fill);
static u32 get_memory_big_endian_u32(fw_addr_t address);
static void set_memory_big_endian_u32_far(fw_addr_t address, u32 value);
static void reset_operating_response_observers(void);

static void test_load_read_acquisition_target_for_track_number(void)
{
    fw_addr_t tuple_address;

    clear_memory(0u);
    tuple_address = 0x00f2b9ul;
    firmware_memory[0x001132ul] = 0u;
    firmware_memory[0x000e42ul] = 0u;
    firmware_memory[tuple_address] = 1u;
    firmware_memory[tuple_address + 1ul] = 2u;
    firmware_memory[tuple_address + 2ul] = 3u;
    LoadReadAcquisitionTargetForTrackNumber();
    assert(get_memory_big_endian_u32(0x000e3bul) == 4653ul);
    assert(read_count == 6u);
    assert(read_trace[0] == 0x001132ul);
    assert(read_trace[1] == 0x000e42ul);
    assert(read_trace[2] == tuple_address);
    assert(read_trace[3] == tuple_address + 1ul);
    assert(read_trace[4] == tuple_address + 2ul);
    assert(read_trace[5] == 0x00102ful);
    assert(write_count == 4u);
    assert(write_trace[0] == 0x000e3bul && write_values[0] == 0u);
    assert(write_trace[1] == 0x000e3cul && write_values[1] == 0u);
    assert(write_trace[2] == 0x000e3dul && write_values[2] == 0x12u);
    assert(write_trace[3] == 0x000e3eul && write_values[3] == 0x2du);

    clear_memory(0u);
    tuple_address = 0x2bb042ul + 20ul;
    firmware_memory[0x001132ul] = 0xc0u;
    firmware_memory[0x000e42ul] = 2u;
    firmware_memory[tuple_address] = 2u;
    firmware_memory[tuple_address + 1ul] = 3u;
    firmware_memory[tuple_address + 2ul] = 4u;
    LoadReadAcquisitionTargetForTrackNumber();
    assert(get_memory_big_endian_u32(0x000e3bul) == 9229ul);
    assert(read_count == 6u);
    assert(read_trace[0] == 0x001132ul);
    assert(read_trace[1] == 0x000e42ul);
    assert(read_trace[2] == tuple_address);

    clear_memory(0u);
    tuple_address = 0x00f2b9ul + 1530ul;
    firmware_memory[0x001132ul] = 0x3fu;
    firmware_memory[0x000e42ul] = 0xffu;
    firmware_memory[tuple_address] = 0xffu;
    firmware_memory[tuple_address + 1ul] = 0xffu;
    firmware_memory[tuple_address + 2ul] = 0xffu;
    LoadReadAcquisitionTargetForTrackNumber();
    assert(get_memory_big_endian_u32(0x000e3bul) == 1166880ul);
    assert(read_trace[2] == tuple_address);

    clear_memory(0u);
    tuple_address = 0x2bb042ul + 2550ul;
    firmware_memory[0x001132ul] = 0x40u;
    firmware_memory[0x000e42ul] = 0xffu;
    firmware_memory[tuple_address] = 0u;
    firmware_memory[tuple_address + 1ul] = 59u;
    firmware_memory[tuple_address + 2ul] = 74u;
    LoadReadAcquisitionTargetForTrackNumber();
    assert(get_memory_big_endian_u32(0x000e3bul) == 4499ul);
    assert(read_trace[2] == tuple_address);
}

