u8 ObserveReadSfrForControllerSampleSeries(u8 address)
{
    unsigned f1_phase;

    controller_sample_series_sfr_read_trace[controller_sample_series_sfr_read_count++] = address;
    if(address == 0xf1u)
    {
        f1_phase = controller_sample_series_f1_read_count++;
        if(controller_sample_series_db_phase != 0u)
            return (f1_phase & 1u) == 0u ? 0u : 8u;
        switch(f1_phase & 3u)
        {
        case 0u:
        case 2u:
            return 0u;
        case 1u:
            return 1u;
        default:
            return 2u;
        }
    }
    if(address == 0xd8u)
        return controller_sample_series_d8_values[controller_sample_series_d8_index++];
    if(address == 0xd9u)
        return controller_sample_series_d9_values[controller_sample_series_d9_index++];
    if(address == 0xdbu)
        return controller_sample_series_db_values[controller_sample_series_db_index++];
    return sfr_memory[address];
}

void ObserveWriteSfrForControllerSampleSeries(u8 address, u8 value)
{
    controller_sample_series_sfr_write_trace[controller_sample_series_sfr_write_count] = address;
    controller_sample_series_sfr_write_values[controller_sample_series_sfr_write_count] = value;
    ++controller_sample_series_sfr_write_count;
    sfr_memory[address] = value;
    if(address == 0xe1u && value == 1u)
    {
        controller_sample_series_db_phase = 1u;
        controller_sample_series_f1_read_count = 0u;
    }
}

