static void test_resolve_drive_control_state_to_zero(void)
{
    static const u8 state8_events[] = { 1u, 2u, 3u, 4u, 5u };
    static const u8 state2_events[] = { 1u, 2u, 3u, 13u, 12u, 9u, 14u, 9u, 14u, 9u, 4u, 5u };
    static const u8 transition_events[] = { 1u, 2u, 3u, 6u, 7u, 15u, 8u, 9u, 10u, 11u, 12u, 13u, 12u, 9u, 14u, 9u, 14u, 9u, 4u, 5u };
    static const u8 state3_events[] = { 1u, 2u, 3u, 9u, 14u, 9u, 14u, 9u, 4u, 5u };
    static const u8 default_events[] = { 1u, 2u, 3u, 4u, 5u };

    clear_memory(0u);
    reset_drive_control_resolution_observers();
    drive_control_resolution_inherited_r15 = 0xa5u;
    firmware_memory[0x1300u] = 8u;
    firmware_memory[0x1301u] = 0xffu;
    ResolveDriveControlStateToZero();
    assert(drive_control_resolution_event_count == sizeof(state8_events) && memcmp(drive_control_resolution_events, state8_events, sizeof(state8_events)) == 0);
    assert(firmware_memory[0x1301u] == 0xfbu && firmware_memory[0x1300u] == 0u && firmware_memory[0x15c3u] == 1u);

    clear_memory(0u);
    reset_drive_control_resolution_observers();
    drive_control_resolution_inherited_r15 = 0x5au;
    firmware_memory[0x1300u] = 2u;
    ResolveDriveControlStateToZero();
    assert(drive_control_resolution_event_count == sizeof(state2_events) && memcmp(drive_control_resolution_events, state2_events, sizeof(state2_events)) == 0);
    assert(drive_control_resolution_finalize_value == 270000l && firmware_memory[0x0e43u] == 0x5au && firmware_memory[0x0e4fu] == 0x5au && firmware_memory[0x1300u] == 0u
           && firmware_memory[0x15c3u] == 0u);
    assert(drive_control_resolution_port_count == 1u && drive_control_resolution_port_addresses[0] == 0x0180a7ul && drive_control_resolution_port_values[0] == 1u);
    assert(drive_control_resolution_pulse_count == 2u && drive_control_resolution_pulse_durations[0] == 100u && drive_control_resolution_pulse_durations[1] == 300u);

    clear_memory(0u);
    reset_drive_control_resolution_observers();
    drive_control_resolution_inherited_r15 = 0x99u;
    firmware_memory[0x1300u] = 1u;
    firmware_memory[0x0e43u] = 0x24u;
    firmware_memory[0x0fadu] = 0xffu;
    firmware_memory[0x0fafu] = 1u;
    bit_0542 = 1u;
    ResolveDriveControlStateToZero();
    assert(drive_control_resolution_event_count == sizeof(transition_events) && memcmp(drive_control_resolution_events, transition_events, sizeof(transition_events)) == 0);
    assert(firmware_memory[0x0fadu] == 0xfbu && firmware_memory[0x18003u] == 0xfbu && bit_0542 == 0u && firmware_memory[0x0e4du] == 8u && firmware_memory[0x0e43u] == 0x24u
           && firmware_memory[0x0e4fu] == 0x24u && firmware_memory[0x1300u] == 0u && firmware_memory[0x15c3u] == 1u);
    assert(drive_control_resolution_port_count == 2u && drive_control_resolution_port_values[0] == 3u && drive_control_resolution_port_values[1] == 1u);

    clear_memory(0u);
    reset_drive_control_resolution_observers();
    firmware_memory[0x1300u] = 5u;
    firmware_memory[0x1304u] = 1u;
    firmware_memory[0x0e43u] = 0x31u;
    ResolveDriveControlStateToZero();
    assert(drive_control_resolution_event_count == sizeof(transition_events) && memcmp(drive_control_resolution_events, transition_events, sizeof(transition_events)) == 0
           && firmware_memory[0x0e43u] == 0x31u);

    clear_memory(0u);
    reset_drive_control_resolution_observers();
    firmware_memory[0x1300u] = 3u;
    ResolveDriveControlStateToZero();
    assert(drive_control_resolution_event_count == sizeof(state3_events) && memcmp(drive_control_resolution_events, state3_events, sizeof(state3_events)) == 0);

    clear_memory(0u);
    reset_drive_control_resolution_observers();
    firmware_memory[0x1300u] = 9u;
    ResolveDriveControlStateToZero();
    assert(drive_control_resolution_event_count == sizeof(default_events) && memcmp(drive_control_resolution_events, default_events, sizeof(default_events)) == 0 && firmware_memory[0x1300u] == 0u);
}

