static void test_reset_drive_control_state_to_eight(void)
{
    static const u8 already_eight_events[] = { 1u, 5u, 6u };
    static const u8 home_events[] = { 1u, 2u, 3u, 4u, 5u, 6u };
    static const u8 no_home_events[] = { 1u, 2u, 3u, 5u, 6u };

    clear_memory(0u);
    firmware_memory[0x1300u] = 8u;
    drive_control_reset_event_count = 0u;
    ResetDriveControlStateToEight();
    assert(drive_control_reset_event_count == sizeof(already_eight_events) && memcmp(drive_control_reset_events, already_eight_events, sizeof(already_eight_events)) == 0);
    assert(read_count == 1u && read_trace[0] == 0x1300ul && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0fb9u] = 0xa1u;
    drive_control_reset_event_count = 0u;
    ResetDriveControlStateToEight();
    assert(drive_control_reset_event_count == sizeof(home_events) && memcmp(drive_control_reset_events, home_events, sizeof(home_events)) == 0);
    assert(drive_control_reset_port_address == 0x01849dul && drive_control_reset_port_value == 0u);
    assert(read_count == 3u && read_trace[0] == 0x1300ul && read_trace[1] == 0x0fb9ul && read_trace[2] == 0x0fb9ul);
    assert(write_count == 2u && write_trace[0] == 0x0fb9ul && write_trace[1] == 0x1300ul && firmware_memory[0x0fb9u] == 0xa1u && firmware_memory[0x1300u] == 8u);

    clear_memory(0u);
    firmware_memory[0x0fb9u] = 0xa3u;
    drive_control_reset_event_count = 0u;
    ResetDriveControlStateToEight();
    assert(drive_control_reset_event_count == sizeof(no_home_events) && memcmp(drive_control_reset_events, no_home_events, sizeof(no_home_events)) == 0);
    assert(firmware_memory[0x0fb9u] == 0xa1u && firmware_memory[0x1300u] == 8u);
}

