void YieldCoroutine1(void)
{
    yield_coroutine1_count++;
    yield_coroutine1_seen_write_count = write_count;
    if(reset_idle_escape_after != 0u && yield_coroutine1_count >= reset_idle_escape_after)
        longjmp(reset_idle_escape, 1);
    if(yield_coroutine1_auto_signal_after != 0u && yield_coroutine1_count >= yield_coroutine1_auto_signal_after)
        firmware_memory[0x0e3fu] = 1u;
    if(yield_coroutine1_auto_countdown_after != 0u && yield_coroutine1_count >= yield_coroutine1_auto_countdown_after)
        firmware_memory[0x1215u] = 0u;
    if(yield_coroutine1_set_1302_bit5_after != 0u && yield_coroutine1_count >= yield_coroutine1_set_1302_bit5_after)
        firmware_memory[0x1302u] |= 0x20u;
    if(yield_coroutine1_expire_1217_after != 0u && yield_coroutine1_count >= yield_coroutine1_expire_1217_after)
        firmware_memory[0x1217u] = 0xffu;
    if(yield_coroutine1_expire_1209_after != 0u && yield_coroutine1_count >= yield_coroutine1_expire_1209_after)
        firmware_memory[0x1209u] = 0xffu;
    if(yield_coroutine1_clear_1220_after != 0u && yield_coroutine1_count >= yield_coroutine1_clear_1220_after)
        firmware_memory[0x1220u] = 0u;
    if(yield_coroutine1_clear_shared_timer != 0u)
    {
        firmware_memory[0x11fcu] = 0u;
        firmware_memory[0x11fdu] = 0u;
        firmware_memory[0x11feu] = 0u;
        firmware_memory[0x11ffu] = 0u;
    }
    if(yield_coroutine1_clear_controller_calibration_countdowns != 0u)
    {
        firmware_memory[0x120bu] = 0u;
        firmware_memory[0x1200u] = 0u;
        firmware_memory[0x1201u] = 0u;
    }
    if(yield_coroutine1_clear_controller_f8_after != 0u && yield_coroutine1_count >= yield_coroutine1_clear_controller_f8_after)
        firmware_memory[0x180f8u] &= 0x7fu;
}

void YieldCoroutine3(void)
{
    if(yield_coroutine3_count < sizeof(yield_coroutine3_seen_read_count) / sizeof(yield_coroutine3_seen_read_count[0]))
        yield_coroutine3_seen_read_count[yield_coroutine3_count] = read_count;
    yield_coroutine3_count++;
    if(yield_coroutine3_auto_complete_after != 0u && yield_coroutine3_count >= yield_coroutine3_auto_complete_after)
    {
        firmware_memory[0x0e40u] = 0u;
        firmware_memory[0x0e41u] = yield_coroutine3_auto_complete_result;
    }
    if(yield_coroutine3_auto_status_after != 0u && yield_coroutine3_count >= yield_coroutine3_auto_status_after)
        firmware_memory[0x0faeu] = yield_coroutine3_auto_status;
    if(controller_service_loop_escape_after != 0u && yield_coroutine3_count >= controller_service_loop_escape_after)
        longjmp(controller_service_loop_escape, 1);
}

