u8 FirmwareRead8(fw_addr_t address)
{
    assert(address < 0x1000000ul);
    if(read_count < sizeof(read_trace) / sizeof(read_trace[0]))
        read_trace[read_count] = address;
    read_count++;
    if(address == 0x180acul && controller_channel_ack_auto_clear)
        return 0;
    if(address == 0x18015ul && controller_capture_status_force_ready != 0u)
        return (u8)(firmware_memory[address] | 0x40u);
    if(address == 0x0014daul && controller_command80_complete_after != 0u)
    {
        controller_command80_completion_reads++;
        if(controller_command80_completion_reads >= controller_command80_complete_after)
            firmware_memory[address] = 1u;
    }
    if(address == 0x001215ul && service_disable_countdown_clear_after != 0u)
    {
        service_disable_countdown_read_count++;
        if(service_disable_countdown_read_count >= service_disable_countdown_clear_after)
            firmware_memory[address] = 0u;
    }
    if(address == 0x001220ul && timer_1220_auto_decrement != 0u)
    {
        u8 value = firmware_memory[address];

        firmware_memory[address] = (u8)(value - 1u);
        return value;
    }
    if(address == 0x00121aul && signal_status_countdown_auto_decrement != 0u)
    {
        u8 value = firmware_memory[address];

        firmware_memory[address] = 0u;
        return value;
    }
    return firmware_memory[address];
}

void FirmwareWrite8(fw_addr_t address, u8 value)
{
    assert(address < 0x1000000ul);
    if(write_count < sizeof(write_trace) / sizeof(write_trace[0]))
    {
        write_trace[write_count] = address;
        write_values[write_count] = value;
    }
    firmware_memory[address] = value;
    if(address == 0x00125aul)
        acknowledge_q_ram_write_seen_ex1 = bit_0542;
    if(write_count < sizeof(write_read_counts) / sizeof(write_read_counts[0]))
        write_read_counts[write_count] = read_count;
    write_count++;
    if(write_mutation_enabled && address == write_mutation_trigger)
    {
        firmware_memory[write_mutation_target] = write_mutation_value;
        write_mutation_enabled = 0u;
    }
}

