u8 FirmwareReadSfr8(u8 address)
{
    if(sfr_read_count < sizeof(sfr_read_trace))
        sfr_read_trace[sfr_read_count] = address;
    sfr_read_count++;
    if(address == 0x90u && p1_bit3_sample_index < p1_bit3_sample_count)
        return p1_bit3_samples[p1_bit3_sample_index++];
    if(address == 0xd8u && sfr_d8_sample_index < sfr_d8_sample_count)
    {
        u8 sample = sfr_d8_samples[sfr_d8_sample_index++];

        if(sfr_d8_countdown_after != 0u && sfr_d8_sample_index >= sfr_d8_countdown_after)
            firmware_memory[0x1215u] = 0u;
        return sample;
    }
    if(address == 0xf1u && sfr_f1_force_ready != 0u)
    {
        if(sfr_f1_complete_countdown != 0u)
            firmware_memory[0x1215u] = 0u;
        return 1u;
    }
    if(address == 0xd7u && (controller_status_auto_clear || controller_status_force_clear))
        return 0;
    /* Timer 1's TR1/TF1 state is in TCON (SFR:88), which is the same
     * volatile register read by RAM:f8b83f after it starts the window. */
    if(address == 0x88u && timer_status_auto_signal && (sfr_memory[address] & 0x40u) != 0)
        return (u8)(sfr_memory[address] | 0x80u);
    return sfr_memory[address];
}

void FirmwareWriteSfr8(u8 address, u8 value)
{
    if(sfr_write_count < sizeof(sfr_write_trace))
    {
        sfr_write_trace[sfr_write_count] = address;
        sfr_write_values[sfr_write_count] = value;
    }
    if(address == 0x91u)
        acknowledge_q_sfr_write_seen_ex1 = bit_0542;
    if(address == 0xd6u && controller_parameter_count < sizeof(controller_parameter_trace) / sizeof(controller_parameter_trace[0]))
        controller_parameter_trace[controller_parameter_count] = (u16)(((u16)sfr_memory[0xd5u] << 8) | value);
    if(address == 0xd6u)
        controller_parameter_count++;
    if(address == 0xd6u && mutate_operating_code_after_parameter != 0u)
    {
        firmware_memory[0x0e43u] = next_parameter_operating_code;
        mutate_operating_code_after_parameter = 0u;
    }
    sfr_write_count++;
    sfr_memory[address] = value;
}

