    adjusted_target_clear_bit34_at_yield = 1u;
    adjusted_target_set_result_at_yield = 1u;
    adjusted_target_result_at_yield = 5u;
    adjusted_target_stop_measurement_at_yield = 2u;
    adjusted_target_stop_measurement_value = 0u;
    adjusted_target_set_scale_at_yield = 2u;
    adjusted_target_scale_at_yield = 20u;
    firmware_memory[0xfb9fu] = 1u;
