static void test_boot_image(void)
{
    u16 sum;
    clear_memory(0);
    firmware_memory[0x100] = 1;
    firmware_memory[0x101] = 2;
    sum = additive(0x100, 0x102);
    WriteBigEndianU16(0x102, sum);
    assert(VerifyAdditiveChecksumRange(0x104, 0x100));
    firmware_memory[0x102] ^= 1;
    assert(!VerifyAdditiveChecksumRange(0x104, 0x100));

    clear_memory(0);
    firmware_memory[0xf00000] = 7;
    firmware_memory[0xf78000] = 9;
    sum = (u16)(additive(0xf00000, 0xf70000) + additive(0xf78000, 0xf79ffe));
    WriteBigEndianU16(0xf79ffe, sum);
    assert(VerifyAdditiveChecksumRange(0xf7a000, 0xf00000));
    clear_memory(0xff);
    assert(IsMemoryRangeErased(0x203, 0x200));
    firmware_memory[0x201] = 0;
    assert(!IsMemoryRangeErased(0x203, 0x200));

    clear_memory(0);
    firmware_memory[0xf7c000] = 0xff;
    memset(&firmware_memory[0xf7c001], 0xff, 0x5f);
    WriteBigEndianU16(0xf79ffe, 0);
    assert(ValidateBootAndConfigurationMemory());
    firmware_memory[0xf7c05f] = 0;
    assert(!ValidateBootAndConfigurationMemory());

    clear_memory(0xffu);
    for(sum = 0u; sum < 0x30u; sum++)
        firmware_memory[0xf80000ul + sum] = (u8)(sum + 1u);
    InitializeInquiryResponseBuffer();
    assert(firmware_memory[0xdcc5] == 5u && firmware_memory[0xdcc6] == 0x80u && firmware_memory[0xdcc8] == 0x21u && firmware_memory[0xdcc9] == 0x5bu);
    assert(memcmp(&firmware_memory[0xdccd], &firmware_memory[0xf80000], 8u) == 0 && memcmp(&firmware_memory[0xdcd5], &firmware_memory[0xf80008], 16u) == 0
           && memcmp(&firmware_memory[0xdce5], &firmware_memory[0xf80018], 4u) == 0 && memcmp(&firmware_memory[0xdce9], &firmware_memory[0xf8001c], 20u) == 0);
    for(sum = 0x38u; sum < 0x60u; sum++)
        assert(firmware_memory[0xdcc5u + sum] == 0u);
}

