static void test_refresh_inquiry_response_from_drive_configuration(void)
{
    static const u8 expected_product[16] = { 0x43u, 0x44u, 0x2du, 0x52u, 0x20u, 0x20u, 0x20u, 0x50u, 0x58u, 0x2du, 0x57u, 0x34u, 0x38u, 0x32u, 0x34u, 0x41u };
    static const u8 vendor[8] = { 'Z', 'L', 'E', 'X', 'T', 'O', 'R', ' ' };
    static const u8 default_vendor[8] = { 'D', 'E', 'F', 'A', 'U', 'L', 'T', '!' };
    static const u8 default_product[16] = { 'D', 'E', 'F', 'A', 'U', 'L', 'T', ' ', 'P', 'R', 'O', 'D', 'U', 'C', 'T', '!' };

    clear_memory(0u);
    inquiry_configuration_run_real = 1u;
    memcpy(&firmware_memory[0xf80000u], default_vendor, sizeof(default_vendor));
    memcpy(&firmware_memory[0xf80008u], default_product, sizeof(default_product));
    memcpy(&inquiry_configuration_bytes[2], vendor, sizeof(vendor));
    memcpy(&inquiry_configuration_bytes[10], expected_product, sizeof(expected_product));
    memcpy(&inquiry_configuration_bytes[26], "0002A", 5u);
    inquiry_configuration_validity = 7u;
    firmware_memory[0x0c84u] = 0x81u;
    RefreshInquiryResponseFromDriveConfiguration();
    assert(inquiry_response_refresh_call_count == 1u);
    assert(inquiry_configuration_read_count == 2u && inquiry_configuration_read_offsets[0] == 0u && inquiry_configuration_read_destinations[0] == 0x7000ul
           && inquiry_configuration_read_counts[0] == 0x20u && inquiry_configuration_read_offsets[1] == 0x46u && inquiry_configuration_read_destinations[1] == 0x7020ul
           && inquiry_configuration_read_counts[1] == 1u);
    assert(memcmp(&firmware_memory[0xdccdu], vendor, sizeof(vendor)) == 0);
    assert(memcmp(&firmware_memory[0xdcd5u], expected_product, sizeof(expected_product)) == 0);
    assert(memcmp(&firmware_memory[0xdd25u], "000042", 6u) == 0);
    assert((firmware_memory[0x0c84u] & 4u) != 0u && firmware_memory[0x0c7fu] == 6u && firmware_memory[0x88bau] == 1u);

    clear_memory(0u);
    inquiry_configuration_run_real = 1u;
    memcpy(&firmware_memory[0xf80000u], default_vendor, sizeof(default_vendor));
    memcpy(&firmware_memory[0xf80008u], default_product, sizeof(default_product));
    inquiry_configuration_bytes[2] = '@';
    memcpy(&inquiry_configuration_bytes[10], " PRODUCT-IDENTITY", 16u);
    memcpy(&inquiry_configuration_bytes[26], "FFFFF", 5u);
    RefreshInquiryResponseFromDriveConfiguration();
    assert(memcmp(&firmware_memory[0xdccdu], default_vendor, sizeof(default_vendor)) == 0);
    assert(memcmp(&firmware_memory[0xdcd5u], " PRODUCT-IDENTITY", 16u) == 0);
    assert(memcmp(&firmware_memory[0xdd25u], ":48575", 6u) == 0);
    assert(firmware_memory[0x88bau] == 0u);

    clear_memory(0u);
    inquiry_configuration_run_real = 1u;
    memcpy(&firmware_memory[0xf80000u], default_vendor, sizeof(default_vendor));
    memcpy(&firmware_memory[0xf80008u], default_product, sizeof(default_product));
    inquiry_configuration_bytes[2] = '[';
    inquiry_configuration_bytes[10] = ' ';
    inquiry_configuration_bytes[11] = '@';
    memcpy(&inquiry_configuration_bytes[26], "12", 2u);
    inquiry_configuration_bytes[28] = 0xffu;
    memcpy(&inquiry_configuration_bytes[29], "34", 2u);
    inquiry_configuration_validity = 0u;
    RefreshInquiryResponseFromDriveConfiguration();
    assert(memcmp(&firmware_memory[0xdccdu], default_vendor, sizeof(default_vendor)) == 0);
    assert(memcmp(&firmware_memory[0xdcd5u], default_product, sizeof(default_product)) == 0);
    assert(memcmp(&firmware_memory[0xdd25u], "      ", 6u) == 0);
    assert(firmware_memory[0x88bau] == 0u);
}

