    assert(raw_read_frame_prefix_call_count == 1u && raw_read_fixed_window_call_count == 1u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1463u, 9u);
    set_memory_big_endian_u32(0x0c4bu, 9ul);
    firmware_memory[0x14b5u] = 0xa5u;
