static void test_select_read_acquisition_target_for_direction_bit_clear(void)
{
    clear_memory(0u);
    FirmwareWrite8(0x0fbeul, 3u);
    FirmwareWrite8(0x125aul, 4u);
    FirmwareWrite8(0x0fc0ul, 9u);
    set_memory_big_endian_u32(0x0fc2u, 0x12345678ul);
    assert(SelectReadAcquisitionTargetForDirectionBitClear(0u) == 2u);
    assert(FirmwareRead8(0x0e42ul) == 9u && FirmwareRead8(0x0fbbu) == 9u && get_memory_big_endian_u32(0x0e3bu) == 0x12345678ul);

    clear_memory(0u);
    FirmwareWrite8(0x0fbeul, 4u);
    FirmwareWrite8(0x0fc0ul, 11u);
    set_memory_big_endian_u32(0x0fc2u, 0x00001000ul);
    set_memory_big_endian_u32(0x0fc6u, 500ul);
    set_memory_big_endian_u32(0x1235u, 499ul);
    assert(SelectReadAcquisitionTargetForDirectionBitClear(0u) == 0u);
    set_memory_big_endian_u32(0x1235u, 500ul);
    assert(SelectReadAcquisitionTargetForDirectionBitClear(0u) == 2u && FirmwareRead8(0x0e42ul) == 11u);

    clear_memory(0u);
    FirmwareWrite8(0x0fbeul, 0u);
    FirmwareWrite8(0x125aul, 4u);
    FirmwareWrite8(0x0fbf1ul, 1u);
    assert(SelectReadAcquisitionTargetForDirectionBitClear(0u) == 2u && get_memory_big_endian_u32(0x0e3bu) == 150ul && FirmwareRead8(0x0fbf1ul) == 3u);

    clear_memory(0u);
    FirmwareWrite8(0x0fbeul, 5u);
    set_memory_big_endian_u32(0x0fc6u, 700ul);
    set_memory_big_endian_u32(0x1235u, 701ul);
    FirmwareWrite8(0x0fbau, 0xffu);
    FirmwareWrite8(0x0faf2ul, 0x5au);
    assert(SelectReadAcquisitionTargetForDirectionBitClear(0u) == 1u && get_memory_big_endian_u32(0x0e3bu) == 701ul && FirmwareRead8(0x1245ul) == 0x5au && FirmwareRead8(0x0fbcu) == 0u
           && FirmwareRead8(0x0fafu) == 3u && FirmwareRead8(0x0fbau) == 0xf2u);
}

