static void test_converge_controller_operating_stage_index_to_target(void)
{
    unsigned index;

    clear_memory(0u);
    firmware_memory[0x103cu] = 0xa6u;
    firmware_memory[0x1041u] = 0xf0u;
    firmware_memory[0x1042u] = 0x10u;
    firmware_memory[0x1043u] = 0x10u;
    ConvergeControllerOperatingStageIndexToTarget();
    assert(stage_converge_submit_count == 1u && stage_converge_submit_codes[0] == 0xa0u && stage_converge_submit_words[0] == 0x0255u && stage_converge_wait_count == 0u);
    assert(read_count == 5u && read_trace[0] == 0x103cul && read_trace[1] == 0x1042ul && read_trace[2] == 0x1041ul && read_trace[3] == 0x1043ul && read_trace[4] == 0x1041ul);

    clear_memory(0u);
    firmware_memory[0x103cu] = 1u;
    firmware_memory[0x1041u] = 1u;
    firmware_memory[0x1043u] = 2u;
    firmware_memory[0x1044u] = 4u;
    stage_converge_mutate_globals = 1u;
    ConvergeControllerOperatingStageIndexToTarget();
    assert(stage_converge_submit_count == 7u && stage_converge_wait_count == 6u && read_count == 5u);
    for(index = 0u; index < 7u; ++index)
    {
        assert(stage_converge_submit_codes[index] == (u8)(0x87u + index));
        assert(stage_converge_submit_words[index] == 0x0255u);
        if(index < 6u)
        {
            assert(stage_converge_wait_durations[index] == 5u);
            assert(stage_converge_wait_yields[index] == 1u);
        }
    }

    clear_memory(0u);
    firmware_memory[0x103cu] = 0xffu;
    firmware_memory[0x1041u] = 1u;
    firmware_memory[0x1043u] = 4u;
    firmware_memory[0x1044u] = 2u;
    ConvergeControllerOperatingStageIndexToTarget();
    assert(stage_converge_submit_count == 7u && stage_converge_wait_count == 6u);
    for(index = 0u; index < 7u; ++index)
        assert(stage_converge_submit_codes[index] == (u8)(0x8du - index));
}

static void test_fill_controller_buffer_range(void)
{
    clear_memory(0xffu);
    FillControllerBufferRange(0x12345678ul, 0ul, 0x5au);
    assert(buffer_fill_chunk_call_count == 0u && write_count == 0u && firmware_memory[0x14dau] == 0xffu);

    clear_memory(0xffu);
    FillControllerBufferRange(0x00123456ul, 0x7ffful, 0xa5u);
    assert(buffer_fill_chunk_call_count == 1u && write_count == 1u && write_trace[0] == 0x14daul && write_values[0] == 0u);
    assert(buffer_fill_chunk_counts[0] == 0x7fffu && buffer_fill_chunk_addresses[0] == 0x00123456ul && buffer_fill_chunk_values[0] == 0xa5u && buffer_fill_chunk_seen_completion[0] == 0u);

    clear_memory(0xffu);
    FillControllerBufferRange(0x00abc000ul, 0x8000ul, 0x3cu);
    assert(buffer_fill_chunk_call_count == 1u && write_count == 1u && buffer_fill_chunk_counts[0] == 0x8000u && buffer_fill_chunk_addresses[0] == 0x00abc000ul);

    clear_memory(0xffu);
    FillControllerBufferRange(0xffff9000ul, 0x10001ul, 0x7eu);
    assert(buffer_fill_chunk_call_count == 3u && write_count == 3u);
    assert(buffer_fill_chunk_counts[0] == 0x8000u && buffer_fill_chunk_counts[1] == 0x8000u && buffer_fill_chunk_counts[2] == 1u);
    assert(buffer_fill_chunk_addresses[0] == 0xffff9000ul && buffer_fill_chunk_addresses[1] == 0x00001000ul && buffer_fill_chunk_addresses[2] == 0x00009000ul);
    assert(buffer_fill_chunk_values[0] == 0x7eu && buffer_fill_chunk_values[1] == 0x7eu && buffer_fill_chunk_values[2] == 0x7eu);
    assert(buffer_fill_chunk_seen_completion[0] == 0u && buffer_fill_chunk_seen_completion[1] == 0u && buffer_fill_chunk_seen_completion[2] == 0u);
    assert(write_trace[0] == 0x14daul && write_trace[1] == 0x14daul && write_trace[2] == 0x14daul);
}

static void test_classify_media_calibration_sample_ordering_and_publish_code(void)
{
    static const struct
    {
        u8 classification;
        u8 sample0;
        u8 sample1;
        u8 sample2;
        u8 expected;
        unsigned reads;
    } cases[] = {
        { 1u, 0u,   0u,   0u,  0xffu, 0u },
        { 2u, 0u,   0u,   0u,  0xfdu, 0u },
        { 3u, 0u,   0u,   0u,  3u,    0u },
        { 4u, 0u,   10u,  15u, 3u,    2u },
        { 4u, 0u,   10u,  16u, 1u,    2u },
        { 4u, 0u,   250u, 1u,  1u,    2u },
        { 5u, 10u,  15u,  0u,  0xfdu, 2u },
        { 5u, 10u,  16u,  0u,  0xffu, 2u },
        { 5u, 250u, 1u,   0u,  0xffu, 2u }
    };
    unsigned index;

    for(index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index)
    {
        clear_memory(0u);
        sample_order_classification_result = cases[index].classification;
        firmware_memory[0x1046u] = cases[index].sample0;
        firmware_memory[0x1047u] = cases[index].sample1;
        firmware_memory[0x1048u] = cases[index].sample2;
        ClassifyMediaCalibrationSampleOrderingAndPublishCode();
        assert(sample_order_classification_call_count == 1u && firmware_memory[0x1050u] == cases[index].expected);
        assert(read_count == cases[index].reads && write_count == 1u && write_trace[0] == 0x1050ul && write_values[0] == cases[index].expected);
        if(cases[index].classification == 4u)
            assert(read_trace[0] == 0x1047ul && read_trace[1] == 0x1048ul);
        if(cases[index].classification == 5u)
            assert(read_trace[0] == 0x1046ul && read_trace[1] == 0x1047ul);
    }
}

static void test_classify_three_controller_samples_by_ordering(void)
{
    static const u8 values[] = { 0u, 1u, 2u, 0x7fu, 0x80u, 0xfeu, 0xffu };
    unsigned index0;
    unsigned index1;
    unsigned index2;

    for(index0 = 0u; index0 < sizeof(values); ++index0)
    {
        for(index1 = 0u; index1 < sizeof(values); ++index1)
        {
            for(index2 = 0u; index2 < sizeof(values); ++index2)
            {
                u8 sample0 = values[index0];
                u8 sample1 = values[index1];
                u8 sample2 = values[index2];
                u8 ordering = 0u;
                u8 expected;

                if(sample0 == sample1 && sample1 == sample2)
                {
                    expected = 1u;
                }
                else
                {
                    if(sample0 > sample1)
                        ordering = 1u;
                    if(sample2 < (ordering == 0u ? sample0 : sample1))
                        ordering = 2u;
                    if(ordering == 0u)
                        expected = 2u;
                    else if(ordering == 2u)
                        expected = 3u;
                    else
                        expected = sample0 > sample2 ? 4u : 5u;
                }

                clear_memory(0u);
                firmware_memory[0x1046u] = sample0;
                firmware_memory[0x1047u] = sample1;
                firmware_memory[0x1048u] = sample2;
                assert(ClassifyThreeControllerSamplesByOrdering() == expected);
                assert(read_count == 3u && read_trace[0] == 0x1046ul && read_trace[1] == 0x1047ul && read_trace[2] == 0x1048ul && write_count == 0u);
            }
        }
    }
}

static void test_validate_media_calibration_configuration_for_current_state(void)
{
    unsigned value;
    unsigned state;

    for(value = 0u; value != 256u; ++value)
    {
        clear_memory(0u);
        firmware_memory[0x1008u] = 1u;
        firmware_memory[0xffc02eu] = (u8)value;
        assert(ValidateMediaCalibrationConfigurationForCurrentState() == (u8)(value != 0xffu));
        assert(read_count == 2u && read_trace[0] == 0x1008ul && read_trace[1] == 0xffc02eul && write_count == 0u);

        clear_memory(0u);
        firmware_memory[0x1008u] = 2u;
        firmware_memory[0xffc030u] = (u8)value;
        assert(ValidateMediaCalibrationConfigurationForCurrentState() == (u8)(value == 1u || value == 2u));
        assert(read_count == 3u && read_trace[0] == 0x1008ul && read_trace[1] == 0x1008ul && read_trace[2] == 0xffc030ul && write_count == 0u);
    }

    for(state = 0u; state != 256u; ++state)
    {
        if(state == 1u || state == 2u)
            continue;
        clear_memory(0u);
        firmware_memory[0x1008u] = (u8)state;
        assert(ValidateMediaCalibrationConfigurationForCurrentState() == 1u);
        assert(read_count == 2u && read_trace[0] == 0x1008ul && read_trace[1] == 0x1008ul && write_count == 0u);
    }
}

static void test_service_media_state3_controller_calibration_transition(void)
{
    clear_memory(0u);
    firmware_memory[0x1045u] = 1u;
    firmware_memory[0x1302u] = 0x80u;
    firmware_memory[0x0c84u] = 0x40u;
    ServiceMediaState3ControllerCalibrationTransition();
    assert(state3_calibration_event_count == 0u && firmware_memory[0x1302u] == 0x84u && firmware_memory[0x0c84u] == 0x48u);
    assert(read_count == 4u && read_trace[0] == 0x1045ul && read_trace[1] == 0xfab0ul && read_trace[2] == 0x1302ul && read_trace[3] == 0x0c84ul);

    clear_memory(0u);
    state3_calibration_validation_result = 2u;
    firmware_memory[0xfab0u] = 1u;
    firmware_memory[0x0fafu] = 0xa5u;
    ServiceMediaState3ControllerCalibrationTransition();
    assert(state3_calibration_event_count == 2u && state3_calibration_events[0] == 1u && state3_calibration_events[1] == 5u && firmware_memory[0x0fafu] == 0u);

    clear_memory(0u);
    state3_calibration_validation_result = 0u;
    firmware_memory[0xf1b7u] = 0x80u;
    firmware_memory[0xfab0u] = 0u;
    state3_signal_mutate_fab0 = 1u;
    state3_signal_fab0 = 1u;
    ServiceMediaState3ControllerCalibrationTransition();
    assert(state3_calibration_event_count == 5u && state3_calibration_events[0] == 1u && state3_calibration_events[1] == 2u && state3_calibration_events[2] == 3u && state3_calibration_events[3] == 4u
           && state3_calibration_events[4] == 5u);
    assert(firmware_memory[0xf1b7u] == 0x8du && firmware_memory[0xf1b8u] == 1u && firmware_memory[0xfae7u] == 0x2au && firmware_memory[0x0fafu] == 0u);
    assert(write_count == 6u && write_trace[0] == 0x0faful && write_trace[1] == 0xf1b7ul && write_values[1] == 0x81u && write_trace[2] == 0xf1b8ul && write_trace[3] == 0xf1b7ul
           && write_values[3] == 0x8du && write_trace[4] == 0xfae7ul && write_trace[5] == 0x0faful);

    clear_memory(0u);
    state3_calibration_validation_result = 0u;
    firmware_memory[0xf1b7u] = 2u;
    firmware_memory[0x1302u] = 1u;
    firmware_memory[0x0c84u] = 2u;
    ServiceMediaState3ControllerCalibrationTransition();
    assert(state3_calibration_event_count == 4u && state3_calibration_events[3] == 4u);
    assert(firmware_memory[0xf1b7u] == 0x0fu && firmware_memory[0x1302u] == 5u && firmware_memory[0x0c84u] == 0x0au);
}

