static void test_controller_packet_thirty_frame_phase_match(void)
{
    clear_memory(0u);
    FirmwareWrite8(0x00fb5bul, 0x40u);
    FirmwareWrite8(0x001008ul, 1u);
    set_memory_big_endian_u32(0x1235u, 9ul);
    set_memory_big_endian_u32(0x114fu, 0ul);
    UpdateControllerPacketThirtyFramePhaseMatchFlag(1u);
    assert((firmware_memory[0x1306u] & 1u) != 0u);

    clear_memory(0u);
    FirmwareWrite8(0x00fb5bul, 0x40u);
    FirmwareWrite8(0x001008ul, 1u);
    set_memory_big_endian_u32(0x1235u, 29ul);
    set_memory_big_endian_u32(0x114fu, 0ul);
    UpdateControllerPacketThirtyFramePhaseMatchFlag(3u);
    assert((firmware_memory[0x1306u] & 1u) != 0u);

    clear_memory(0u);
    FirmwareWrite8(0x00fb5bul, 0x40u);
    FirmwareWrite8(0x001008ul, 1u);
    FirmwareWrite8(0x00fb53ul, 0u);
    FirmwareWrite8(0x00fb54ul, 0u);
    FirmwareWrite8(0x00fb55ul, 0u);
    set_memory_big_endian_u32(0x1235u, (u32)-449981l);
    UpdateControllerPacketThirtyFramePhaseMatchFlag(2u);
    assert(get_memory_big_endian_u32(0x114fu) == (u32)-450000l);
    assert(firmware_memory[0x113fu] == 0u && firmware_memory[0x1140u] == 0u && firmware_memory[0x1141u] == 0u && firmware_memory[0x102fu] == 0u && (firmware_memory[0x1306u] & 1u) != 0u);

    clear_memory(0u);
    UpdateControllerPacketThirtyFramePhaseMatchFlag(1u);
    assert(write_count == 0u);
}

