static void test_select_controller_measurement_scale_percent(void)
{
    static const u16 expected_set[] = { 110u, 118u, 126u, 135u, 144u, 154u, 164u, 175u };
    unsigned index;

    clear_memory(0u);
    set_memory_big_endian_u32(0xf1bbu, 0x2000ul);
    firmware_memory[0x2009u] = 0x5au;
    assert(SelectControllerMeasurementScalePercent(0x1234u) == 0x5au);

    firmware_memory[0x2009u] = 0u;
    firmware_memory[0xfb87u] = 0u;
    for(index = 0u; index < 8u; index++)
    {
        firmware_memory[0xfb81u] = (u8)(index << 4);
        assert(SelectControllerMeasurementScalePercent(0x1234u) == (u16)(100u + index * 5u));
    }
    firmware_memory[0xfb81u] = 0x05u;
    assert(SelectControllerMeasurementScalePercent(0x1234u) == 0x1234u);

    firmware_memory[0xfb87u] = 0x40u;
    firmware_memory[0x0e47u] = 8u;
    for(index = 0u; index < 8u; index++)
    {
        firmware_memory[0xfb81u] = (u8)(index << 4);
        assert(SelectControllerMeasurementScalePercent(0u) == expected_set[index]);
    }
    firmware_memory[0x0e47u] = 4u;
    firmware_memory[0xfb86u] = 5u;
    assert(SelectControllerMeasurementScalePercent(0u) == 154u);
    firmware_memory[0x0e47u] = 10u;
    firmware_memory[0xfb86u] = 0x38u;
    assert(SelectControllerMeasurementScalePercent(0u) == 175u);
}

