static u16 expected_device_busy_time(u8 operating_code, u16 countdown)
{
    return (u16)(((u32)countdown * 0x5be0ul) / ((u32)operating_code * 0x0002c000ul));
}

static void test_build_device_busy_event_status_descriptor(void)
{
    clear_memory(0u);
    assert(BuildDeviceBusyEventStatusDescriptor() == 0u);
    assert(write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0faeu] = 3u;
    assert(BuildDeviceBusyEventStatusDescriptor() == 0x01030014ul);
    assert(get_memory_big_endian_u16(0x1004u) == 0x0014u);
    assert(write_count == 2u && write_trace[0] == 0x1004ul && write_trace[1] == 0x1005ul);

    clear_memory(0u);
    firmware_memory[0x0faeu] = 3u;
    set_memory_big_endian_u16(0x1004u, 0x1234u);
    assert(BuildDeviceBusyEventStatusDescriptor() == 0x01031234ul);
    assert(write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0c84u] = 0x08u;
    firmware_memory[0x0e47u] = 10u;
    set_memory_big_endian_u16(0xfbb4u, 0xffffu);
    assert(BuildDeviceBusyEventStatusDescriptor() == (0x01020000ul | expected_device_busy_time(10u, 0xffffu)));
    assert(write_count == 0u && read_count == 4u && read_trace[0] == 0x0c84ul && read_trace[1] == 0xfbb4ul && read_trace[2] == 0xfbb5ul && read_trace[3] == 0x0e47ul);
}

