static void test_timing(void)
{
    unsigned scale;

    for(scale = 0u; scale != 256u; ++scale)
        BusyWaitAccumulatorTimes2300((u8)scale);

    clear_memory(0);
    sfr_memory[0x91] = 0xffu;
    timer_status_auto_signal = 1;
    DelayTimerUnits(1);
    assert(sfr_memory[0x94] == 0xc3u && sfr_memory[0x96] == 0xffu);
    assert((sfr_memory[0x91] & 0xc0u) == 0);
    sfr_memory[0x91] = 0;
    DelayTimerUnits59();
    assert(sfr_memory[0x94] == 0x2bu && sfr_memory[0x96] == 0xf2u);
    sfr_memory[0x88] = 0xffu;
    sfr_memory[0x8d] = 0x12u;
    sfr_memory[0x8b] = 0x34u;
    StopAndClearTimer1();
    assert(sfr_memory[0x88] == 0xbfu && sfr_memory[0x8d] == 0 && sfr_memory[0x8b] == 0);

    sfr_memory[0x88] = 0;
    firmware_memory[0x1039] = 0xffu;
    StartTimer1AndClearMeasurementStateBit4();
    assert(sfr_memory[0x88] == 0x40u && firmware_memory[0x1039] == 0xefu);
}

static void test_wait_timer1_scaled_duration(void)
{
    unsigned index;

    clear_memory(0u);
    WaitTimer1ScaledDuration(0u, 0u);
    assert(wait_timer_count == 1u && wait_timer_duration_trace[0] == 0u && wait_timer_yield_trace[0] == 0u);
    assert(timer1_scaled_reload_count == 1u && timer1_scaled_reload_trace[0] == 0xffffu && sfr_memory[0x8du] == 0xffu && sfr_memory[0x8bu] == 0xffu);

    clear_memory(0u);
    timer1_scaled_polls_before_overflow = 2u;
    WaitTimer1ScaledDuration(1u, 1u);
    assert(timer1_scaled_reload_count == 1u && timer1_scaled_reload_trace[0] == 0xfff6u && timer1_scaled_yield_count == 2u);
    assert(sfr_memory[0x8du] == 0xffu && sfr_memory[0x8bu] == 0xf6u);

    clear_memory(0u);
    WaitTimer1ScaledDuration(7282u, 0u);
    assert(timer1_scaled_reload_count == 2u && timer1_scaled_reload_trace[0] == 0u && timer1_scaled_reload_trace[1] == 0xfffcu && timer1_scaled_yield_count == 0u);

    clear_memory(0u);
    WaitTimer1ScaledDuration(0xffffu, 0u);
    assert(timer1_scaled_reload_count == 9u);
    for(index = 0u; index < 9u; ++index)
        assert(timer1_scaled_reload_trace[index] == 0u);
}

static u8 expected_channel3_value(u8 operating_code, u8 enabled, u8 configuration, u8 secondary)
{
    if(operating_code == 2u)
        return enabled == 0 ? 0xa5u : 0xa6u;
    if(operating_code == 4u || operating_code == 8u || operating_code == 10u || operating_code == 12u || operating_code == 16u)
    {
        if(enabled == 0)
            return 0xadu;
        return operating_code == 10u && (configuration & 0x40u) != 0 ? 0xaau : 0xa6u;
    }
    return enabled == 0 || secondary == 0xffu ? 0xaau : 0xaeu;
}

static void test_controller_mapping(void)
{
    unsigned operating_code;
    unsigned enabled;
    unsigned configuration;
    unsigned secondary;

    for(operating_code = 0; operating_code != 256; ++operating_code)
    {
        assert(IsSignedByteLessThanNegative45((u8)operating_code) == (u8)(operating_code < 0xd3u));
        assert(MapOperatingCodeToProfileIndex((u8)operating_code)
               == (operating_code == 0   ? 0
                   : operating_code < 2  ? 1
                   : operating_code < 4  ? 2
                   : operating_code < 8  ? 3
                   : operating_code < 10 ? 4
                   : operating_code < 12 ? 5
                   : operating_code < 16 ? 6
                   : operating_code < 20 ? 7
                   : operating_code < 24 ? 8
                   : operating_code < 32 ? 9
                   : operating_code < 40 ? 10
                   : operating_code < 48 ? 11
                                         : 12));
        assert(MapOperatingCodeToProfileIndexMinusSeven((u8)operating_code) == (u8)(MapOperatingCodeToProfileIndex((u8)operating_code) - 7u));
        assert(MapControllerRegisterIndexSkippingGap((u8)operating_code)
               == (u8)(((u8)(operating_code > 0x0fu ? (u8)(operating_code + 5u) : operating_code)) > 0x1au ? 0x1au : (u8)(operating_code > 0x0fu ? (u8)(operating_code + 5u) : operating_code)));
        for(enabled = 0; enabled != 2; ++enabled)
        {
            for(configuration = 0; configuration != 2; ++configuration)
            {
                for(secondary = 0; secondary != 2; ++secondary)
                {
                    clear_memory(0);
                    firmware_memory[0x1006] = (u8)enabled;
                    firmware_memory[0x103a] = configuration == 0 ? 0 : 0x40u;
                    firmware_memory[0x0e4f] = secondary == 0 ? 0 : 0xffu;
                    assert(MapOperatingCodeToControllerChannel3Value((u8)operating_code) == expected_channel3_value((u8)operating_code, (u8)enabled, firmware_memory[0x103a], firmware_memory[0x0e4f]));
                    assert(read_count
                           == ((operating_code == 10u && enabled != 0)                                                                                                    ? 2u
                               : (operating_code == 4u || operating_code == 8u || operating_code == 12u || operating_code == 16u || operating_code == 2u || enabled == 0) ? 1u
                                                                                                                                                                          : 2u));
                    assert(read_trace[0] == 0x1006ul);
                    if(read_count == 2u)
                        assert(read_trace[1] == (operating_code == 10u ? 0x103aul : 0x0e4ful));
                }
            }
        }
    }
}

static void test_apply_sfr_da_strategy_adjustment(void)
{
    static const u8 operating_codes[] = { 0x18u, 0x14u, 0x10u, 0x08u };
    static const fw_addr_t table_bases[] = { 0xf82f7aul, 0xf82e84ul, 0xf82d8eul, 0xf82c98ul };
    unsigned route;

    for(route = 0u; route < 4u; ++route)
    {
        fw_addr_t record = table_bases[route] + 3u;

        clear_memory(0u);
        firmware_memory[0x0e4fu] = operating_codes[route];
        firmware_memory[0xfb5du] = 1u;
        firmware_memory[record] = 1u;
        firmware_memory[record + 1u] = 5u;
        firmware_memory[record + 2u] = 2u;
        set_memory_big_endian_u16(0xfacfu, 100u);
        firmware_memory[0xfbd1u] = 10u;
        set_memory_big_endian_u16(0xfbc3u, 120u);
        firmware_memory[0xfbd3u] = 20u;
        ApplySfrDaStrategyAdjustment();
        assert(firmware_memory[0xfbd1u] == 15u && get_memory_big_endian_u16(0xfbc3u) == 129u);
    }

    clear_memory(0u);
    firmware_memory[0x0e4fu] = 0x08u;
    firmware_memory[0xfb5du] = 2u;
    firmware_memory[0xf82c9eu] = 0xffu;
    firmware_memory[0xf82c9fu] = 0xfbu;
    firmware_memory[0xf82ca0u] = 0xf8u;
    set_memory_big_endian_u16(0xfacfu, 500u);
    firmware_memory[0xfbd1u] = 20u;
    set_memory_big_endian_u16(0xfbc3u, 400u);
    firmware_memory[0xfbd3u] = 10u;
    ApplySfrDaStrategyAdjustment();
    assert(firmware_memory[0xfbd1u] == 15u && get_memory_big_endian_u16(0xfbc3u) == 391u);

    clear_memory(0u);
    firmware_memory[0x0e4fu] = 0x20u;
    firmware_memory[0xf82c98u] = 1u;
    firmware_memory[0xf82c99u] = 5u;
    firmware_memory[0xf82c9au] = 2u;
    set_memory_big_endian_u16(0xfbc3u, 0x1234u);
    firmware_memory[0xfbd1u] = 0x56u;
    ApplySfrDaStrategyAdjustment();
    assert(firmware_memory[0xfbd1u] == 0x56u && get_memory_big_endian_u16(0xfbc3u) == 0x1234u && write_count == 0u);
}

static u8 expected_three_field_status(u8 field_r7, u8 field_r6, u8 flags)
{
    if((flags & 0x40u) == 0)
        return 0;
    if(field_r7 == 0)
        return 0xffu;
    if(field_r7 == 1u)
        return 8u;
    if(field_r7 == 2u && field_r6 == 8u)
        return 12u;
    if(field_r7 == 2u && field_r6 == 16u)
        return 10u;
    if(field_r7 == 2u && field_r6 == 32u)
        return 9u;
    return 0;
}

static void write_u32_be(u16 address, u32 value)
{
    firmware_memory[address] = (u8)(value >> 24);
    firmware_memory[(u16)(address + 1u)] = (u8)(value >> 16);
    firmware_memory[(u16)(address + 2u)] = (u8)(value >> 8);
    firmware_memory[(u16)(address + 3u)] = (u8)value;
}

