    firmware_memory[0xf84454u + 3u] = 5u;
    firmware_memory[0xf84468u + 6u] = 0x12u;
    firmware_memory[0xf84468u + 7u] = 0x34u;
    write_u32_be(0x1598u, 100ul);
    assert(PollReadVerifyRawDescriptorStatus() == 0u);
    assert(read_verify_poll_sense_count == 1u && read_verify_poll_sense_key == 5u && read_verify_poll_sense_code == 0x1234u);
    assert(read_verify_poll_information_count == 1u && read_verify_poll_sense_information == 0xffffffceul);

    clear_memory(0u);
    reset_read_verify_descriptor_poll_observers();
    write_u32_be(0x1455u, 0x12345678ul);
    write_u32_be(0x1459u, 0x12345678ul);
    assert(PollReadVerifyRawDescriptorStatus() == 1u);

    clear_memory(0u);
    reset_read_verify_descriptor_poll_observers();
    write_u32_be(0x1455u, 1ul);
    assert(PollReadVerifyRawDescriptorStatus() == 0xfeu);
    assert(read_verify_poll_get_descriptor_count == 0u);

    clear_memory(0u);
    reset_read_verify_descriptor_poll_observers();
    write_u32_be(0x1455u, 3ul);
    write_u32_be(0x1459u, 2ul);
    firmware_memory[0x1293u] = 1u;
    read_verify_poll_descriptor_address = 0x2000u;
    assert(PollReadVerifyRawDescriptorStatus() == 0xfeu);
    assert(get_memory_big_endian_u32(0x1459u) == 3ul && read_verify_poll_get_descriptor_count == 1u && read_verify_poll_validate_count == 0u && read_verify_poll_consume_count == 1u
           && read_verify_poll_consumed_descriptors == 1u);

    clear_memory(0u);
    reset_read_verify_descriptor_poll_observers();
    write_u32_be(0x1455u, 2ul);
    write_u32_be(0x1459u, 1ul);
    firmware_memory[0x1293u] = 1u;
    firmware_memory[0x2010u] = 1u;
    firmware_memory[0x1468u] = 1u;
    read_verify_poll_descriptor_address = 0x2000u;
    read_verify_poll_validate_result = 1u;
    assert(PollReadVerifyRawDescriptorStatus() == 0u);
    assert(read_verify_poll_validate_count == 1u && read_verify_poll_validated_address == 0x2000u && read_verify_poll_consume_count == 0u);

    clear_memory(0u);
    reset_read_verify_descriptor_poll_observers();
    write_u32_be(0x1455u, 1ul);
    firmware_memory[0x1293u] = 1u;
    firmware_memory[0x2010u] = 1u;
    firmware_memory[0x2013u] = 0x0au;
    bit_000c = 1u;
    read_verify_poll_descriptor_address = 0x2000u;
    assert(PollReadVerifyRawDescriptorStatus() == 0xfeu);
    assert(read_verify_poll_validate_count == 1u && read_verify_poll_mapping_bit_count == 1u && read_verify_poll_consume_count == 1u);

    clear_memory(0u);
    reset_read_verify_descriptor_poll_observers();
    write_u32_be(0x1455u, 9ul);
    write_u32_be(0x1459u, 5ul);
    write_u32_be(0x15dcu, 100ul);
    firmware_memory[0x1293u] = 1u;
    firmware_memory[0x2010u] = 1u;
    firmware_memory[0x2013u] = 9u;
    bit_000c = 1u;
    read_verify_poll_descriptor_address = 0x2000u;
    read_verify_poll_validate_mutate_status_zero = 1u;
    read_verify_poll_map_result = -123l;
    assert(PollReadVerifyRawDescriptorStatus() == 0xfeu);
    assert(read_verify_poll_reset_count == 1u && read_verify_poll_initialize_count == 1u && read_verify_poll_coroutine_entry == 0x00f90000ul && read_verify_poll_map_count == 1u
           && read_verify_poll_map_input == 105l && get_memory_big_endian_u32(0x1598u) == 0xffffff85ul);

    clear_memory(0u);
