static void set_controller_position_bytes(u8 minute, u8 second, u8 frame, u8 auxiliary)
{
    firmware_memory[0x18004u] = minute;
    firmware_memory[0x18005u] = second;
    firmware_memory[0x18006u] = frame;
    firmware_memory[0x18007u] = auxiliary;
}

static void test_decode_controller_position_fields(void)
{
    clear_memory(0u);
    firmware_memory[0x1800fu] = 0xf0u;
    set_controller_position_bytes(0x12u, 0x34u, 0x56u, 0xa5u);
    assert(DecodeControllerPositionFields(1u) == 0u);
    assert(firmware_memory[0x15a0u] == 0u && firmware_memory[0x15a3u] == 0u && controller_position_convert_count == 0u && controller_position_bit000f_count == 0u
           && controller_position_bit0013_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1800fu] = 0xf0u;
    set_controller_position_bytes(0x12u, 0x34u, 0x56u, 0xa5u);
    firmware_memory[0x102eu] = 1u;
    firmware_memory[0x102fu] = 0x7eu;
    controller_position_convert_result = (s32)0x12345678l;
    assert(DecodeControllerPositionFields(0u) == 1u);
    assert(firmware_memory[0x15a0u] == 12u && firmware_memory[0x15a1u] == 34u && firmware_memory[0x15a2u] == 56u && firmware_memory[0x15a3u] == 0xa5u);
    assert(controller_position_convert_count == 1u && controller_position_convert_address == 0x15a0ul && controller_position_convert_seen_102f == 0x7eu && firmware_memory[0x102fu] == 0x7eu
           && get_memory_big_endian_u32(0x0f6eu) == 0x12345678ul);

    clear_memory(0u);
    set_controller_position_bytes(0xf9u, 0x59u, 0x74u, 0x11u);
    controller_position_convert_result = -2l;
    assert(DecodeControllerPositionFields(0u) == 1u);
    assert(firmware_memory[0x15a0u] == 159u && firmware_memory[0x15a1u] == 59u && firmware_memory[0x15a2u] == 74u && controller_position_convert_seen_102f == 1u && firmware_memory[0x102fu] == 0u
           && get_memory_big_endian_u32(0x0f6eu) == 0xfffffffeul);

    clear_memory(0u);
    set_controller_position_bytes(0xaau, 0x5au, 0x75u, 0x22u);
    write_u32_be(0x1598u, 0x11223344ul);
    assert(DecodeControllerPositionFields(0u) == 1u);
    assert(get_memory_big_endian_u32(0x0f6eu) == 0x11223344ul && firmware_memory[0x15a0u] == 0xaau && firmware_memory[0x15a1u] == 0x5au && firmware_memory[0x15a2u] == 0x75u
           && firmware_memory[0x15a3u] == 0x22u && controller_position_bit000f_count == 0u);

    clear_memory(0u);
    set_controller_position_bytes(0xadu, 0x5au, 0x75u, 0u);
    write_u32_be(0x1598u, 0x11223344ul);
    write_u32_be(0x1235u, 0x55667788ul);
    assert(DecodeControllerPositionFields(1u) == 1u);
    assert(get_memory_big_endian_u32(0x0f6eu) == 0x55667788ul && controller_position_bit000f_count == 1u);

    clear_memory(0u);
    set_controller_position_bytes(0xabu, 0x5au, 0x75u, 0u);
    bit_000f = 1u;
    write_u32_be(0x1598u, 0ul);
    assert(DecodeControllerPositionFields(1u) == 1u);
    assert(get_memory_big_endian_u32(0x0f6eu) == 0xfffffffful && controller_position_bit000f_count == 1u);

    clear_memory(0u);
    set_controller_position_bytes(0xaeu, 0x5au, 0x75u, 0x33u);
    write_u32_be(0x0f6eu, 0x89abcdeful);
    assert(DecodeControllerPositionFields(0u) == 0u);
    assert(get_memory_big_endian_u32(0x0f6eu) == 0x89abcdeful && controller_position_convert_count == 0u && controller_position_bit0013_count == 1u && controller_position_bit001c_count == 1u
           && controller_position_bit001d_count == 1u);

    clear_memory(0u);
    set_controller_position_bytes(0xaeu, 0x5au, 0x75u, 0u);
    bit_0013 = 1u;
    assert(DecodeControllerPositionFields(0u) == 1u);
    assert(controller_position_bit0013_count == 1u && controller_position_bit001c_count == 0u && controller_position_bit001d_count == 0u);

    clear_memory(0u);
    set_controller_position_bytes(0xaeu, 0x5au, 0x75u, 0u);
    bit_001c = 1u;
    assert(DecodeControllerPositionFields(0u) == 1u);
    assert(controller_position_bit0013_count == 1u && controller_position_bit001c_count == 1u && controller_position_bit001d_count == 0u);

    clear_memory(0u);
    set_controller_position_bytes(0xaeu, 0x5au, 0x75u, 0u);
    bit_001d = 1u;
    assert(DecodeControllerPositionFields(0u) == 1u);
    assert(controller_position_bit0013_count == 1u && controller_position_bit001c_count == 1u && controller_position_bit001d_count == 1u);
}

static void test_run_recovery_wait_and_restart_if_needed(void)
{
    clear_memory(0u);
    firmware_memory[0x15c4u] = 1u;
    RunRecoveryWaitAndRestartIfNeeded();
    assert(recovery_coroutine1_count == 1u);
    assert(recovery_coroutine1_entry == 0x00f853cful);
    assert(recovery_handshake_count == 1u);
    assert(bit_0580 == 1u);
    assert(bit_0581 == 1u);
    assert(recovery_delay_count == 300u);
    assert(recovery_bit0547_count == 0u && recovery_service_host_count == 0u && recovery_yield_count == 0u && recovery_restart_count == 0u);

    clear_memory(0u);
    recovery_ready_after_yields = 2u;
    RunRecoveryWaitAndRestartIfNeeded();
    assert(recovery_delay_count == 300u && recovery_yield_count == 2u && recovery_bit0547_count == 2u && recovery_bit0546_count == 2u && recovery_sfr_a9_bit2_count == 2u
           && recovery_service_host_count == 2u);
    assert(bit_0547 == 1u && bit_0546 == 1u && (sfr_memory[0xa9u] & 0x04u) != 0u && recovery_restart_count == 0u);

    clear_memory(0u);
    firmware_memory[0x15c4u] = 1u;
    firmware_memory[0xfaefu] = 0x04u;
    if(setjmp(recovery_restart_escape) == 0)
    {
        RunRecoveryWaitAndRestartIfNeeded();
        assert(0);
    }
    assert(recovery_delay_count == 300u && recovery_restart_count == 1u && firmware_memory[0x00fdu] == 0x98u);
}

static void test_run_controller_startup_status_handshake(void)
{
    clear_memory(0u);
    controller_startup_restart_returns = 1u;
    RunControllerStartupStatusHandshake();
    assert(controller_startup_delay_count == 1u && controller_startup_yield_count == 4u && controller_startup_restart_count == 2u);
    assert(firmware_memory[0x00feu] == 0xffu && firmware_memory[0x18041u] == 0u && firmware_memory[0x1204u] == 6u && firmware_memory[0x121eu] == 45u && firmware_memory[0x0c87u] == 4u);

    clear_memory(0u);
    firmware_memory[0x18043u] = 0x11u;
    firmware_memory[0x0c87u] = 0xffu;
    controller_startup_status_change_yield = 5u;
    controller_startup_status_after_yield = 0x01u;
    RunControllerStartupStatusHandshake();
    assert(controller_startup_delay_count == 1u && controller_startup_yield_count == 5u && controller_startup_restart_count == 0u);
    assert(firmware_memory[0x18041u] == 0u && firmware_memory[0x18046u] == 0u && firmware_memory[0x121eu] == 45u && firmware_memory[0x1204u] == 6u && firmware_memory[0x0c87u] == 0xfdu);

    clear_memory(0u);
    firmware_memory[0x18043u] = 0x21u;
    firmware_memory[0x0c87u] = 0x40u;
    controller_startup_countdown_address = 0x121eu;
    controller_startup_countdown_change_yield = 2u;
    controller_startup_countdown_after_yield = 0xffu;
    RunControllerStartupStatusHandshake();
    assert(controller_startup_delay_count == 1u && controller_startup_yield_count == 2u && controller_startup_restart_count == 0u);
    assert(firmware_memory[0x18041u] == 0u && firmware_memory[0x0c87u] == 0x42u && firmware_memory[0x1204u] == 0u);

    clear_memory(0u);
    firmware_memory[0x18043u] = 0x11u;
    firmware_memory[0x0c87u] = 0xffu;
    controller_startup_countdown_address = 0x1204u;
    controller_startup_countdown_change_yield = 4u;
    controller_startup_countdown_after_yield = 0u;
    RunControllerStartupStatusHandshake();
    assert(controller_startup_delay_count == 1u && controller_startup_yield_count == 4u && controller_startup_restart_count == 0u);
    assert(firmware_memory[0x18041u] == 0u && firmware_memory[0x0c87u] == 0xf9u);

    clear_memory(0u);
    if(setjmp(controller_startup_restart_escape) == 0)
    {
        RunControllerStartupStatusHandshake();
        assert(0);
    }
    assert(controller_startup_delay_count == 1u && controller_startup_yield_count == 2u && controller_startup_restart_count == 1u);
    assert(firmware_memory[0x00feu] == 0xffu && firmware_memory[0x18041u] == 4u);

    clear_memory(0u);
    firmware_memory[0x18043u] = 0x11u;
    controller_startup_status_change_yield = 4u;
    controller_startup_status_after_yield = 0u;
    if(setjmp(controller_startup_restart_escape) == 0)
    {
        RunControllerStartupStatusHandshake();
        assert(0);
    }
    assert(controller_startup_delay_count == 1u && controller_startup_yield_count == 4u && controller_startup_restart_count == 1u);
    assert(firmware_memory[0x00feu] == 0xffu && firmware_memory[0x18041u] == 4u && firmware_memory[0x1204u] == 6u);
}

static void test_prepare_buffer_data_transfer(void)
{
    static const u8 dispatched_events[] = { 1u, 2u, 3u, 4u };
    static const u8 suppressed_events[] = { 1u, 2u, 4u };

    clear_memory(0u);
    firmware_memory[0x0fafu] = 2u;
    PrepareBufferDataTransfer();
    assert(buffer_transfer_coroutine2_entry == 0x00f84a00ul && buffer_transfer_setup_event_count == sizeof(dispatched_events));
    assert(memcmp(buffer_transfer_setup_events, dispatched_events, sizeof(dispatched_events)) == 0);

    clear_memory(0u);
    firmware_memory[0x0fbau] = 0x04u;
    firmware_memory[0x0fafu] = 2u;
    PrepareBufferDataTransfer();
    assert(buffer_transfer_setup_event_count == sizeof(suppressed_events));
    assert(memcmp(buffer_transfer_setup_events, suppressed_events, sizeof(suppressed_events)) == 0);

    clear_memory(0u);
    firmware_memory[0x0fafu] = 3u;
    PrepareBufferDataTransfer();
    assert(buffer_transfer_setup_event_count == sizeof(suppressed_events));
    assert(memcmp(buffer_transfer_setup_events, suppressed_events, sizeof(suppressed_events)) == 0);
}

static void test_advance_main_data_ring_and_check_controller_buffer_alignment(void)
{
    clear_memory(0u);
    reset_ring_alignment_observers();
    firmware_memory[0x0f1fu] = 4u;
    write_u32_be(0x155eu, 0x10000ul);
    AdvanceMainDataRingAndCheckControllerBufferAlignment(1ul);
    assert(ring_alignment_decode_count == 1u && ring_alignment_decode_argument == 0u);
    assert(firmware_memory[0x0f1fu] == 3u && get_memory_big_endian_u32(0x126eul) == 0x930ul);
    assert(ring_alignment_initialize_count == 0u);

    clear_memory(0u);
    reset_ring_alignment_observers();
    firmware_memory[0x0f1fu] = 3u;
    write_u32_be(0x155eu, 0x10000ul);
    AdvanceMainDataRingAndCheckControllerBufferAlignment(1ul);
    assert(firmware_memory[0x0f1fu] == 2u && ring_alignment_initialize_count == 1u);

    clear_memory(0u);
    reset_ring_alignment_observers();
    firmware_memory[0x0f1fu] = 3u;
    write_u32_be(0x155eu, 0x10000ul);
    AdvanceMainDataRingAndCheckControllerBufferAlignment(0x930ul);
    assert(ring_alignment_initialize_count == 0u);

    clear_memory(0u);
    reset_ring_alignment_observers();
    firmware_memory[0x0f1fu] = 3u;
    write_u32_be(0x155eu, 0x10000ul);
    AdvanceMainDataRingAndCheckControllerBufferAlignment(0ul);
    assert(ring_alignment_initialize_count == 1u);

    clear_memory(0u);
    reset_ring_alignment_observers();
    firmware_memory[0x0f1fu] = 0u;
    write_u32_be(0x155eu, 0x10000ul);
    AdvanceMainDataRingAndCheckControllerBufferAlignment(1ul);
    assert(firmware_memory[0x0f1fu] == 0xffu && ring_alignment_initialize_count == 1u);

    clear_memory(0u);
    reset_ring_alignment_observers();
    firmware_memory[0x0f1fu] = 3u;
    write_u32_be(0x126eu, 0x800ul);
    write_u32_be(0x155eu, 0x1000ul);
    AdvanceMainDataRingAndCheckControllerBufferAlignment(0x930ul);
    assert(get_memory_big_endian_u32(0x126eul) == 0x130ul && ring_alignment_initialize_count == 1u);
}

