static void test_probe_raw_read_q_position_at_target(void)
{
    unsigned status_index;
    static const u16 terminal_statuses[] = { 0x0281u, 0x2100u, 0x0000u, 0x1234u };
    static const u8 terminal_results[] = { 7u, 7u, 1u, 4u };

    clear_memory(0u);
    reset_raw_q_target_probe_observers();
    write_u32_be(0x1598u, 100ul);
    firmware_memory[0x1132u] = 0x10u;
    assert(ProbeRawReadQPositionAtTarget() == 7u && get_memory_big_endian_u32(0x0f41u) == 100ul && raw_q_target_handshake_count == 0u);

    clear_memory(0u);
    reset_raw_q_target_probe_observers();
    write_u32_be(0x1598u, 450ul);
    bit_0017 = 1u;
    firmware_memory[0x127eu] = 1u;
    assert(ProbeRawReadQPositionAtTarget() == 7u && bit_0017 == 1u && raw_q_target_clear_bit0017_count == 0u);

    clear_memory(0u);
    reset_raw_q_target_probe_observers();
    write_u32_be(0x1598u, 451ul);
    firmware_memory[0x0faeu] = 1u;
    assert(ProbeRawReadQPositionAtTarget() == 4u && firmware_memory[0x1226u] == 0u && firmware_memory[0x0c2au] == 0x0bu && firmware_memory[0x0f07u] == 2u);
    assert(raw_q_target_reset_count == 1u && raw_q_target_initialize_count == 1u && raw_q_target_coroutine_entry == 0x00f9352dul && raw_q_target_yield_count == 1u && raw_q_target_handshake_count == 1u
           && raw_q_target_handshake_levels[0] == 0u);

    for(status_index = 0u; status_index < sizeof(terminal_statuses) / sizeof(terminal_statuses[0]); ++status_index)
    {
        clear_memory(0u);
        reset_raw_q_target_probe_observers();
        write_u32_be(0x1598u, 451ul);
        prepare_raw_q_target_descriptor(terminal_statuses[status_index], 0x1000ul);
        assert(ProbeRawReadQPositionAtTarget() == terminal_results[status_index]);
        assert(firmware_memory[0x1226u] == 4u && raw_q_target_handshake_count == 2u && raw_q_target_handshake_levels[0] == 0u && raw_q_target_handshake_levels[1] == 1u);
    }

    clear_memory(0u);
    reset_raw_q_target_probe_observers();
    write_u32_be(0x1598u, 160ul);
    write_u32_be(0x155eu, 0x2000ul);
    prepare_raw_q_target_descriptor(0x800bu, 0x1000ul);
    bit_0008 = 1u;
    raw_q_target_clear_bit0008_after_yield = 2u;
    raw_q_target_ring_byte_count = 8u;
    raw_q_target_ring_bytes[4] = 0x00u;
    raw_q_target_ring_bytes[5] = 0x02u;
    raw_q_target_ring_bytes[6] = 0x00u;
    raw_q_target_ring_bytes[7] = 0xc0u;
    assert(ProbeRawReadQPositionAtTarget() == 6u && raw_q_target_yield_count == 2u && raw_q_target_clear_bit0017_count == 1u && raw_q_target_ring_byte_index == 8u
           && get_memory_big_endian_u32(0x0f41u) == 151ul);

    clear_memory(0u);
    reset_raw_q_target_probe_observers();
    write_u32_be(0x1598u, 500ul);
    write_u32_be(0x155eu, 0x2000ul);
    prepare_raw_q_target_descriptor(0x800bu, 0x1000ul);
    raw_q_target_ring_byte_count = 4u;
    raw_q_target_ring_bytes[1] = 0x02u;
    raw_q_target_ring_bytes[3] = 0xe0u;
    assert(ProbeRawReadQPositionAtTarget() == 6u && get_memory_big_endian_u32(0x0f41u) == 501ul);

    clear_memory(0u);
    reset_raw_q_target_probe_observers();
    write_u32_be(0x1598u, 500ul);
    write_u32_be(0x155eu, 0x2000ul);
    prepare_raw_q_target_descriptor(0x800bu, 0x0100ul);
    raw_q_target_ring_byte_count = 16u;
    assert(ProbeRawReadQPositionAtTarget() == 7u && raw_q_target_ring_byte_index == 16u && get_memory_big_endian_u32(0x0f41u) == 500ul);
}

