    memset(raw_payload_signature_bit001b_levels, 0, sizeof(raw_payload_signature_bit001b_levels));
    raw_payload_signature_bit001b_count = 0u;
    raw_payload_signature_reset_count = 0u;
    memset(raw_payload_signature_coroutine_entries, 0, sizeof(raw_payload_signature_coroutine_entries));
    raw_payload_signature_coroutine_count = 0u;
    raw_payload_signature_yield_count = 0u;
    memset(raw_payload_signature_poll_results, 0, sizeof(raw_payload_signature_poll_results));
    raw_payload_signature_poll_result_count = 0u;
    raw_payload_signature_poll_count = 0u;
    memset(raw_payload_signature_poll_seen_bit001b, 0, sizeof(raw_payload_signature_poll_seen_bit001b));
    raw_payload_signature_descriptor_address = 0u;
    raw_payload_signature_descriptor_count = 0u;
    memset(raw_payload_signature_handshake_levels, 0, sizeof(raw_payload_signature_handshake_levels));
    raw_payload_signature_handshake_count = 0u;
    bit_001b = 0u;
