static void prepare_raw_payload_signature_source(const u8 signature[3], u8 seed)
{
    const fw_addr_t source_address = 0x00104018ul;
    unsigned offset;

    raw_payload_signature_descriptor_address = 0x0200u;
    write_u32_be(0x0204u, 0x00004000ul);
    for(offset = 0u; offset < 0x0800u; ++offset)
        firmware_memory[source_address + offset] = (u8)(seed + offset);
    firmware_memory[source_address] = signature[0];
    firmware_memory[source_address + 1u] = signature[1];
    firmware_memory[source_address + 2u] = signature[2];
}

static void assert_raw_payload_signature_lifecycle(void)
{
    assert(raw_payload_signature_map_count == 1u && raw_payload_signature_map_input == 850l);
    assert(raw_payload_signature_bit001b_count == 2u && raw_payload_signature_bit001b_levels[0] == 1u && raw_payload_signature_bit001b_levels[1] == 0u && bit_001b == 0u);
    assert(raw_payload_signature_reset_count == 2u && raw_payload_signature_coroutine_count == 2u && raw_payload_signature_coroutine_entries[0] == 0x00f90000ul
           && raw_payload_signature_coroutine_entries[1] == 0x00f84a00ul);
    assert(raw_payload_signature_handshake_count == 2u && raw_payload_signature_handshake_levels[0] == 0u && raw_payload_signature_handshake_levels[1] == 1u);
    assert(firmware_memory[0x1226u] == 4u && firmware_memory[0x0c2au] == 2u && firmware_memory[0x0f07u] == 0u);
    assert(get_memory_big_endian_u32(0x15dcu) == 850ul && get_memory_big_endian_u32(0x0b02u) == 0x123455e2ul && get_memory_big_endian_u32(0x1598u) == 0x12345678ul);
}

static void test_classify_raw_sector_payload_signature_at_pipeline_target(void)
{
    static const u8 signatures[][3] = {
        { 'M', 'I', 'P' },
        { 'M', 'D', 'T' },
        { 'S', 'I', 'P' },
        { 'S', 'D', 'T' }
    };
    static const u8 results[] = { 0x0fu, 0x10u, 0x11u, 0x12u };
    unsigned signature_index;

    clear_memory(0xa5u);
    reset_raw_payload_signature_observers();
    write_u32_be(0x1598u, 1000ul);
    raw_payload_signature_map_result = (s32)0x12345678ul;
    raw_payload_signature_poll_results[0] = 0xfeu;
    raw_payload_signature_poll_results[1] = 0u;
    raw_payload_signature_poll_result_count = 2u;
    assert(ClassifyRawSectorPayloadSignatureAtPipelineTarget() == 0xffu);
    assert(raw_payload_signature_yield_count == 2u && raw_payload_signature_poll_count == 2u && raw_payload_signature_poll_seen_bit001b[0] == 1u && raw_payload_signature_poll_seen_bit001b[1] == 1u
           && raw_payload_signature_descriptor_count == 0u);
    assert(firmware_memory[0x2bb919u] == 0u && firmware_memory[0x2bb91au] == 0u && firmware_memory[0x2bb91bu] == 0u && firmware_memory[0x2bb91cu] == 0u && firmware_memory[0x15d7u] == 0xa5u);
    assert_raw_payload_signature_lifecycle();

    for(signature_index = 0u; signature_index < sizeof(results) / sizeof(results[0]); ++signature_index)
    {
        clear_memory(0xa5u);
        reset_raw_payload_signature_observers();
        write_u32_be(0x1598u, 1000ul);
        raw_payload_signature_map_result = (s32)0x12345678ul;
        raw_payload_signature_poll_results[0] = 1u;
        raw_payload_signature_poll_result_count = 1u;
        prepare_raw_payload_signature_source(signatures[signature_index], (u8)(0x30u + signature_index));
        assert(ClassifyRawSectorPayloadSignatureAtPipelineTarget() == results[signature_index]);
        assert(raw_payload_signature_yield_count == 1u && raw_payload_signature_poll_count == 1u && raw_payload_signature_poll_seen_bit001b[0] == 1u && raw_payload_signature_descriptor_count == 1u);
        assert(memcmp(&firmware_memory[0x2bb919u], &firmware_memory[0x104018u], 0x0800u) == 0 && firmware_memory[0x15d7u] == 1u && firmware_memory[0x2bb918u] == 0xa5u
               && firmware_memory[0x2bc119u] == 0xa5u);
        assert_raw_payload_signature_lifecycle();
    }

    clear_memory(0xa5u);
    reset_raw_payload_signature_observers();
    write_u32_be(0x1598u, 1000ul);
    raw_payload_signature_map_result = (s32)0x12345678ul;
    raw_payload_signature_poll_results[0] = 7u;
    raw_payload_signature_poll_result_count = 1u;
    prepare_raw_payload_signature_source((const u8 *)"XYZ", 0x55u);
    assert(ClassifyRawSectorPayloadSignatureAtPipelineTarget() == 0xfeu && firmware_memory[0x15d7u] == 0u && raw_payload_signature_descriptor_count == 1u);
    assert(memcmp(&firmware_memory[0x2bb919u], &firmware_memory[0x104018u], 0x0800u) == 0);
    assert_raw_payload_signature_lifecycle();
}

