    assert(read_header_poll_validate_count == 0u && firmware_memory[0x0b2au] == 0x5au && firmware_memory[0x0b2bu] == 0u && firmware_memory[0x0b2cu] == 0u && firmware_memory[0x0b2du] == 0u
           && get_memory_big_endian_u32(0x0b2eu) == 1084ul);
