                assert(ReadBigEndianU16(0xfacfu) == (write_speed_x == 0u && ((u8)flags & 2u) != 0u ? expected : 0x1234u));
                assert(firmware_memory[0x158e] == (write_speed_x == 0u && ((u8)flags & 2u) != 0u ? (u8)(flags | 4u) : (u8)flags));
