    firmware_memory[0xdd32u] = 2u;
    firmware_memory[0xdd33u] = 8u;
    firmware_memory[0x0c71u] = 0xa1u;
    firmware_memory[0x0c72u] = 0xb2u;
    firmware_memory[0x0c73u] = 0xc3u;
    firmware_memory[0x0c74u] = 0xd4u;
