static void test_media_strategy_record_index_selection(void)
{
    static const u16 identifiers[] = { 0x0241u, 0x0244u, 0x0245u, 0x0248u, 0x0249u, 0x024au, 0x024bu, 0x024cu, 0x024fu, 0x0243u };
    unsigned identifier_index;
    unsigned mode;

    for(identifier_index = 0u; identifier_index < sizeof(identifiers) / sizeof(identifiers[0]); ++identifier_index)
    {
        for(mode = 0u; mode != 5u; ++mode)
        {
            u16 identifier = identifiers[identifier_index];
            u8 expected = 0xa5u;

            clear_memory(0);
            firmware_memory[0xfb5b] = 0xfcu;
            firmware_memory[0xfb89] = (u8)((identifier >> 7) << 2);
            firmware_memory[0xfb8a] = (u8)identifier;
            firmware_memory[0xfb88] = (u8)mode;
            firmware_memory[0xfb5d] = expected;
            switch(identifier)
            {
            case 0x0241u:
                if(mode == 2u)
                    expected = 0xd2u;
                break;
            case 0x0244u:
                if(mode == 2u)
                    expected = 0xd1u;
                else if(mode == 3u)
                    expected = 0xe1u;
                else if(mode == 1u)
                    expected = 0xb1u;
                break;
            case 0x0245u:
                if(mode == 2u)
                    expected = 0xd3u;
                else if(mode == 3u)
                    expected = 0xe4u;
                break;
            case 0x0248u:
                expected = 0xc6u;
                break;
            case 0x0249u:
                if(mode == 2u)
                    expected = 0xd5u;
                else if(mode == 3u)
                    expected = 0xe2u;
                break;
            case 0x024au:
                if(mode == 2u)
                    expected = 0xd6u;
                break;
            case 0x024bu:
                if(mode == 2u)
                    expected = 0xd4u;
                break;
            case 0x024cu:
                if(mode == 2u)
                    expected = 0xd7u;
                else if(mode == 3u)
                    expected = 0xe3u;
                break;
            case 0x024fu:
                if(mode == 2u)
                    expected = 0xd8u;
                else if(mode == 3u)
                    expected = 0xe1u;
                break;
            case 0x0243u:
                expected = mode == 2u ? 0xd0u : 0xbcu;
                break;
            }
            RefineMediaStrategyRecordIndexFromAtipIdentification();
            assert(firmware_memory[0xfb5d] == expected);
        }
    }
    clear_memory(0);
    firmware_memory[0xfb5b] = 0u;
    firmware_memory[0xfb5d] = 0xa5u;
    RefineMediaStrategyRecordIndexFromAtipIdentification();
    assert(firmware_memory[0xfb5d] == 0xa5u);

    clear_memory(0);
    write_u32_be(0x114fu, (u32)-11594l);
    SelectMediaStrategyRecordIndexFromAtipLeadIn();
    assert((firmware_memory[0x103b] & 1u) != 0u && firmware_memory[0xfb5d] == 0xd8u);
}

