static void test_write_packet_size_exact_multiple(void)
{
    unsigned packet_size;
    unsigned value;

    for(packet_size = 1u; packet_size <= 256u; ++packet_size)
    {
        write_u32_be(0x0c4bu, (u32)packet_size);
        for(value = 0u; value != 1024u; ++value)
            assert(IsWritePacketSizeExactMultiple((u32)value) == (u8)((value % packet_size) == 0u));
    }
    write_u32_be(0x0c4bu, 0x80000000ul);
    assert(IsWritePacketSizeExactMultiple(0x80000000ul) == 1u);
    assert(IsWritePacketSizeExactMultiple(0xfffffffful) == 0u);
}

static void test_configure_controller_ports_80d0_d1_d3_for_current_state(void)
{
    unsigned drive_flag, media_state, operating_code;

    clear_memory(0);
    firmware_memory[0x18015] = 0x20u;
    firmware_memory[0x180f8] = 0u;
    for(drive_flag = 0u; drive_flag != 2u; ++drive_flag)
        for(media_state = 0u; media_state != 256u; ++media_state)
            for(operating_code = 0u; operating_code != 256u; ++operating_code)
            {
                u8 state_path = (u8)(drive_flag != 0u && (media_state == 2u || media_state == 3u));
                u8 expected_d0;
                u8 expected_d3;

                firmware_memory[0x15d7] = (u8)drive_flag;
                firmware_memory[0x0faf] = (u8)media_state;
                firmware_memory[0x0e43] = (u8)operating_code;
                firmware_memory[0x180d3] = 0xa5u;
                write_count = 0u;
                ConfigureControllerPorts80D0D1D3ForCurrentState();
                assert(firmware_memory[0x180d1] == 0u);
                if(state_path != 0u)
                {
                    assert(firmware_memory[0x180d0] == 0x0bu && firmware_memory[0x180d3] == 0xa5u && write_count == 2u);
                }
                else
                {
                    expected_d0 = (u8)(operating_code < 0x18u ? (operating_code == 4u ? 0x0bu : 0u) : 0x40u);
                    expected_d3 = (u8)(operating_code < 0x18u ? 0u : 8u);
                    assert(firmware_memory[0x180d0] == expected_d0 && firmware_memory[0x180d3] == expected_d3 && write_count == 3u);
                }
            }

    clear_memory(0);
    firmware_memory[0x18015] = 0x20u;
    firmware_memory[0x15d7] = 1u;
    firmware_memory[0x0faf] = 3u;
    ConfigureControllerPorts80D0D1D3ForCurrentState();
    assert(write_count == 2u && write_trace[0] == 0x180d1ul && write_values[0] == 0u && write_trace[1] == 0x180d0ul && write_values[1] == 0x0bu);
}

