static void test_select_lowest_enabled_write_speed(void)
{
    unsigned flags;

    for(flags = 0u; flags != 65536ul; ++flags)
    {
        u16 value = (u16)flags;
        u8 expected = 52u;

        if((value & 0x1000u) != 0u)
            expected = 8u;
        else if((value & 0x0800u) != 0u)
            expected = 10u;
        else if((value & 0x0400u) != 0u)
            expected = 12u;
        else if((value & 0x0200u) != 0u)
            expected = 16u;
        else if((value & 0x0100u) != 0u)
            expected = 20u;
        else if((value & 0x0080u) != 0u)
            expected = 24u;
        else if((value & 0x0040u) != 0u)
            expected = 32u;
        else if((value & 0x0020u) != 0u)
            expected = 40u;
        firmware_memory[0x0fad7] = (u8)(value >> 8);
        firmware_memory[0x0fad8] = (u8)value;
        assert(SelectLowestEnabledWriteSpeed() == expected);
    }
}

