        set_memory_big_endian_u32(0x12c1u, 333000ul);
        assert(IsThirtySevenTrackLayoutSpacedBy9000Frames() == 1u);

        firmware_memory[(u16)(0xdd80u + 19u * 17u)] = 2u;
        assert(IsThirtySevenTrackLayoutSpacedBy9000Frames() == 0u);
        firmware_memory[(u16)(0xdd80u + 19u * 17u)] = 1u;
        firmware_memory[(u16)(0xdd80u + 19u * 17u + 3u)]++;
        assert(IsThirtySevenTrackLayoutSpacedBy9000Frames() == 0u);
