    firmware_memory[0x0e4f] = 8;
    WriteControllerParametersE8E9ForValue(5u);
    assert(sfr_write_values[3] == 0xe8u && sfr_write_values[4] == 17u);

    clear_memory(0);
    firmware_memory[0x1008] = 1;
    firmware_memory[0x0e4f] = 8;
    firmware_memory[0x0e43] = 0x29u;
    firmware_memory[0x0c46] = 0;
    firmware_memory[0xfa04] = 0x22u;
    firmware_memory[0x0faf] = 6;
    WriteControllerParametersE8E9ForValue(5u);
    assert(sfr_write_values[4] == 0x2fu);

    clear_memory(0);
    firmware_memory[0x1008] = 2;
    firmware_memory[0x0c46] = 0;
    firmware_memory[0xfb88] = 2;
    WriteControllerParametersE8E9ForValue(5u);
    assert(sfr_write_values[4] == 9u);
    firmware_memory[0xfb88] = 0;
    sfr_write_count = 0;
    WriteControllerParametersE8E9ForValue(5u);
    assert(sfr_write_values[4] == 21u);

    clear_memory(0);
    firmware_memory[0x18015] = 0x20u;
    firmware_memory[0x18098] = 0xa5u;
    sfr_memory[0xa8] = 0x81u;
    sfr_memory[0xa9] = 0x2cu;
    assert(WaitControllerPortReadyAndReadByte(0x18098ul) == 0xa5u);
    assert(sfr_memory[0xa8] == 0x81u && sfr_memory[0xa9] == 0x2cu);
    assert(sfr_read_count == 2u && sfr_read_trace[0] == 0xa8u && sfr_read_trace[1] == 0xa9u && sfr_write_count == 3u && sfr_write_trace[0] == 0xa8u && sfr_write_values[0] == 1u
           && sfr_write_trace[1] == 0xa8u && sfr_write_trace[2] == 0xa9u);

    clear_memory(0);
    WriteControllerParameterD6Value00();
    assert(sfr_write_count == 7u && sfr_write_values[3] == 0xd6u && sfr_write_values[4] == 0u);

    clear_memory(0);
    firmware_memory[0x18015] = 0x20u;
    sfr_memory[0xa8] = 0x83u;
    sfr_memory[0xa9] = 0x41u;
    WaitControllerPortReadyAndWriteByte(0x18098ul, 0x5au);
    assert(firmware_memory[0x18098] == 0x5au && sfr_memory[0xa8] == 0x83u && sfr_memory[0xa9] == 0x41u && sfr_write_count == 3u && sfr_write_trace[0] == 0xa8u && sfr_write_values[0] == 3u
           && sfr_write_trace[1] == 0xa8u && sfr_write_trace[2] == 0xa9u);

    clear_memory(0);
    firmware_memory[0xfc07] = 5u;
    for(scaled = 0; scaled <= 0xfffful; ++scaled)
    {
        u16 input = (u16)scaled;
        u16 clamped = input >= 0x5dc0u ? 0x5dc0u : input;
        u16 coarse;
        u16 remainder;
        u16 fine;

        if(clamped >= 0x4e20u)
        {
            coarse = 0x1fu;
            remainder = (u16)(clamped - 0x4e20u);
        }
        else
        {
            coarse = (u16)(clamped / 0x285u);
            remainder = (u16)(clamped % 0x285u);
        }
        fine = (u16)((u16)(remainder * 10u) / 0x9du);
        sfr_write_count = 0;
        WriteControllerParametersEAEBFromScaledValue(input);
        assert(sfr_write_values[3] == 0xeau && sfr_write_values[4] == (u8)((u16)(coarse << 3) | 5u) && sfr_write_values[10] == 0xebu && sfr_write_values[11] == (u8)fine);
    }

    clear_memory(0);
