    assert((firmware_memory[0xfc07] & 4u) != 0 && firmware_memory[0x18098] == 0x40u && sfr_write_values[sfr_write_count - 4u] == 0xd6u && sfr_write_values[sfr_write_count - 3u] == 0u);

