static void test_configure_controller_ports_for_disabled_operating_path(void)
{
    unsigned high_code;
    unsigned skip_primary_path;
    unsigned skip_shadow_update;
    unsigned state_two;

    for(high_code = 0u; high_code != 2u; ++high_code)
    {
        for(skip_primary_path = 0u; skip_primary_path != 2u; ++skip_primary_path)
        {
            for(skip_shadow_update = 0u; skip_shadow_update != 2u; ++skip_shadow_update)
            {
                for(state_two = 0u; state_two != 2u; ++state_two)
                {
                    u8 expected_kinds[10];
                    fw_addr_t expected_addresses[10];
                    u8 expected_values[10];
                    fw_addr_t expected_reads[8];
                    unsigned expected_count = 0u;
                    unsigned expected_read_count = 0u;
                    unsigned index;
                    u8 expected_shadow = 0xa5u;

#define ADD_DISABLED_PATH_EVENT(kind, address, value)                                                                                                                                                  \
    do                                                                                                                                                                                                 \
    {                                                                                                                                                                                                  \
        expected_kinds[expected_count] = (kind);                                                                                                                                                       \
        expected_addresses[expected_count] = (address);                                                                                                                                                \
        expected_values[expected_count] = (value);                                                                                                                                                     \
        ++expected_count;                                                                                                                                                                              \
    } while(0)
#define ADD_DISABLED_PATH_READ(address) expected_reads[expected_read_count++] = (address)

                    clear_memory(0u);
                    memset(disabled_operating_path_event_kinds, 0, sizeof(disabled_operating_path_event_kinds));
                    memset(disabled_operating_path_event_addresses, 0, sizeof(disabled_operating_path_event_addresses));
                    memset(disabled_operating_path_event_values, 0, sizeof(disabled_operating_path_event_values));
                    disabled_operating_path_event_count = 0u;
                    firmware_memory[0x0e43u] = high_code != 0u ? 0x18u : 0x17u;
                    firmware_memory[0xfae0u] = (u8)((skip_primary_path != 0u ? 0x80u : 0u) | (skip_shadow_update != 0u ? 0x20u : 0u));
                    firmware_memory[0x1008u] = state_two != 0u ? 2u : 1u;
                    firmware_memory[0xfbf6u] = 0xa5u;
                    firmware_memory[0xfbf7u] = 0x35u;

                    ADD_DISABLED_PATH_EVENT(1u, 0x018085ul, 0u);
                    ADD_DISABLED_PATH_READ(0x000e43ul);
                    if(high_code != 0u)
                        ADD_DISABLED_PATH_EVENT(2u, 0u, 0u);
                    ADD_DISABLED_PATH_EVENT(1u, 0x018086ul, 0u);
                    ADD_DISABLED_PATH_EVENT(1u, 0x018082ul, 0xb0u);
                    ADD_DISABLED_PATH_READ(0x00fae0ul);
                    if(skip_primary_path == 0u)
                    {
                        ADD_DISABLED_PATH_READ(0x001008ul);
                        ADD_DISABLED_PATH_EVENT(3u, 0x018079ul, state_two != 0u ? 0x94u : 0x14u);
                        expected_shadow = 0x41u;
                        ADD_DISABLED_PATH_READ(0x00fbf6ul);
                        ADD_DISABLED_PATH_EVENT(1u, 0x01809dul, expected_shadow);
                        ADD_DISABLED_PATH_READ(0x00fbf7ul);
                        ADD_DISABLED_PATH_EVENT(1u, 0x01809ful, 0xb5u);
                    }
                    ADD_DISABLED_PATH_READ(0x00fae0ul);
                    if(skip_shadow_update == 0u)
                    {
                        expected_shadow = (u8)(expected_shadow | 0x10u);
                        ADD_DISABLED_PATH_READ(0x00fbf6ul);
                        ADD_DISABLED_PATH_READ(0x00fbf6ul);
                        ADD_DISABLED_PATH_EVENT(1u, 0x01809dul, expected_shadow);
                    }
                    ADD_DISABLED_PATH_EVENT(4u, 0u, 0u);
                    ADD_DISABLED_PATH_EVENT(5u, 0u, 0u);

                    ConfigureControllerPortsForDisabledOperatingPath();

                    assert(disabled_operating_path_event_count == expected_count);
                    for(index = 0u; index != expected_count; ++index)
                    {
                        assert(disabled_operating_path_event_kinds[index] == expected_kinds[index]);
                        assert(disabled_operating_path_event_addresses[index] == expected_addresses[index]);
                        assert(disabled_operating_path_event_values[index] == expected_values[index]);
                    }
                    assert(read_count == expected_read_count);
                    for(index = 0u; index != expected_read_count; ++index)
                        assert(read_trace[index] == expected_reads[index]);
                    assert(firmware_memory[0xfbf6u] == expected_shadow);
                    assert(firmware_memory[0xfbf7u] == 0x35u);
                    assert(write_count == (skip_primary_path == 0u ? 1u : 0u) + (skip_shadow_update == 0u ? 1u : 0u));
                }
            }
        }
    }

#undef ADD_DISABLED_PATH_READ
#undef ADD_DISABLED_PATH_EVENT
}

static void test_track_table_reference(void)
{
    clear_memory(0xffu);
    firmware_memory[0x12c9] = 0u;
    UpdateTrackTableReferenceFromCurrentSessionPointB0();
    assert(firmware_memory[0xdd79] == 0u && firmware_memory[0xdd7a] == 0u && firmware_memory[0xdd7b] == 0u && firmware_memory[0xdd7c] == 0u && firmware_memory[0xdd7d] == 0u);

    clear_memory(0);
    firmware_memory[0x12c9] = 2u;
    firmware_memory[0x12ca] = 0u;
    firmware_memory[0x12cb] = 11u;
    UpdateTrackTableReferenceFromCurrentSessionPointB0();
    assert(firmware_memory[0xdd79] == 1u);

    firmware_memory[0x2b8000 + 11u] = 2u;
    firmware_memory[0x2b8000 + 14u] = 0xb0u;
    firmware_memory[0x2b8000 + 15u] = 1u;
    firmware_memory[0x2b8000 + 16u] = 2u;
    firmware_memory[0x2b8000 + 17u] = 3u;
    UpdateTrackTableReferenceFromCurrentSessionPointB0();
    assert(firmware_memory[0xdd79] == 0u && firmware_memory[0xdd7a] == 0u && firmware_memory[0xdd7b] == 0u && firmware_memory[0xdd7c] == 0x12u && firmware_memory[0xdd7d] == 0x2du);

    firmware_memory[0x2b8000 + 15u] = 0xffu;
    UpdateTrackTableReferenceFromCurrentSessionPointB0();
    assert(firmware_memory[0xdd79] == 1u);
}

