static u16 write_speed_selection_bit(u8 write_speed_x)
{
    switch(write_speed_x)
    {
    case 4u:
        return 0x2000u;
    case 8u:
        return 0x1000u;
    case 10u:
        return 0x0800u;
    case 12u:
        return 0x0400u;
    case 16u:
        return 0x0200u;
    case 20u:
        return 0x0100u;
    case 24u:
        return 0x0080u;
    case 32u:
        return 0x0040u;
    case 40u:
        return 0x0020u;
    default:
        return 0u;
    }
}

static void test_write_speed_selection(void)
{
    unsigned value;

    for(value = 0; value != 256u; ++value)
    {
        u8 write_speed_x = (u8)value;
        u16 expected_flags = 0x8015u;
        u16 selected_bit = write_speed_selection_bit(write_speed_x);

        clear_memory(0);
        firmware_memory[0xfad4] = 0xa5u;
        firmware_memory[0xfad7] = 0xafu;
        firmware_memory[0xfad8] = 0x35u;
        ReplaceWriteSpeedSelectionFlagForValue(write_speed_x);
        if(write_speed_x < 0x35u)
        {
            expected_flags = (u16)(expected_flags | selected_bit | 0x1000u);
            assert(firmware_memory[0xfad4] == write_speed_x);
            assert(write_count == (unsigned)(21u + (selected_bit != 0u ? 2u : 0u)));
        }
        else
        {
            assert(firmware_memory[0xfad4] == 0xa5u);
            assert(write_count == 18u);
        }
        assert(firmware_memory[0xfad7] == (u8)(expected_flags >> 8));
        assert(firmware_memory[0xfad8] == (u8)expected_flags);
    }

    clear_memory(0);
    firmware_memory[0xfad7] = 0xffu;
    firmware_memory[0xfad8] = 0xffu;
    ReplaceWriteSpeedSelectionFlagForValue(4u);
    assert(write_count == 23u);
    for(value = 0; value != 18u; ++value)
        assert(write_trace[value] == (value & 1u ? 0xfad8ul : 0xfad7ul));
    assert(write_trace[18] == 0xfad4ul);
    assert(write_trace[19] == 0xfad7ul && write_trace[20] == 0xfad8ul);
    assert(write_trace[21] == 0xfad7ul && write_trace[22] == 0xfad8ul);
}

