static void test_read_acquisition_frame_distance(void)
{
    clear_memory(0);
    firmware_memory[0x0ee4] = 5u;
    firmware_memory[0x0ee8] = 5u;
    assert(IsReadAcquisitionFrameDistanceAccepted() == 1u);
    firmware_memory[0x0ee8] = 6u;
    assert(IsReadAcquisitionFrameDistanceAccepted() == 0u);
    firmware_memory[0x0ed6] = 1u;
    firmware_memory[0x0ee8] = 0u;
    assert(IsReadAcquisitionFrameDistanceAccepted() == 1u);
    firmware_memory[0x0ee8] = 1u;
    assert(IsReadAcquisitionFrameDistanceAccepted() == 0u);
    firmware_memory[0x0ee3] = 1u;
    firmware_memory[0x0ee2] = 1u;
    firmware_memory[0x0ee8] = 3u;
    assert(IsReadAcquisitionFrameDistanceAccepted() == 1u);
    firmware_memory[0x0ee8] = 4u;
    assert(IsReadAcquisitionFrameDistanceAccepted() == 0u);

    firmware_memory[0x0ee3] = 0u;
    firmware_memory[0x0ed6] = 0u;
    firmware_memory[0x0ee8] = 9u;
    assert(IsReadAcquisitionFrameDistanceWithinFineTolerance() == 1u);
    firmware_memory[0x0ee8] = 10u;
    assert(IsReadAcquisitionFrameDistanceWithinFineTolerance() == 0u);
    firmware_memory[0x0ed6] = 1u;
    firmware_memory[0x0ee8] = 0u;
    assert(IsReadAcquisitionFrameDistanceWithinFineTolerance() == 1u);
    firmware_memory[0x0ee3] = 1u;
    firmware_memory[0x0ee2] = 1u;
    firmware_memory[0x0ee8] = 3u;
    assert(IsReadAcquisitionFrameDistanceWithinFineTolerance() == 1u);
    firmware_memory[0x0ee8] = 4u;
    assert(IsReadAcquisitionFrameDistanceWithinFineTolerance() == 0u);

    firmware_memory[0x0ee3] = 0u;
    firmware_memory[0x0ee8] = 12u;
    assert(UpdateReadAcquisitionNearTargetWithinTwelveFrames() == 1u && firmware_memory[0x0ee2] == 1u);
    firmware_memory[0x0ee8] = 13u;
    assert(UpdateReadAcquisitionNearTargetWithinTwelveFrames() == 0u && firmware_memory[0x0ee2] == 0u);
    firmware_memory[0x0ee3] = 1u;
    firmware_memory[0x0ee8] = 0u;
    assert(UpdateReadAcquisitionNearTargetWithinTwelveFrames() == 0u && firmware_memory[0x0ee2] == 0u);

    firmware_memory[0x0ee3] = 0u;
    firmware_memory[0x0ee4] = 5u;
    firmware_memory[0x0ee8] = 8u;
    assert(UpdateReadAcquisitionNearTargetFromDynamicTolerance() == 1u && firmware_memory[0x0ee2] == 1u);
    firmware_memory[0x0ee8] = 9u;
    assert(UpdateReadAcquisitionNearTargetFromDynamicTolerance() == 0u && firmware_memory[0x0ee2] == 0u);
    firmware_memory[0x0ee3] = 1u;
    firmware_memory[0x0ee8] = 0u;
    assert(UpdateReadAcquisitionNearTargetFromDynamicTolerance() == 0u && firmware_memory[0x0ee2] == 0u);

    clear_memory(0);
    firmware_memory[0x1238] = 20u;
    firmware_memory[0x0e3e] = 5u;
    assert(CalculateReadAcquisitionAbsoluteFrameDistance() == 15u && firmware_memory[0x0ee3] == 1u);
    firmware_memory[0x1238] = 5u;
    firmware_memory[0x0e3e] = 20u;
    assert(CalculateReadAcquisitionAbsoluteFrameDistance() == 15u && firmware_memory[0x0ee3] == 0u);
    firmware_memory[0x1238] = 0xffu;
    firmware_memory[0x1237] = 0xffu;
    firmware_memory[0x1236] = 0xffu;
    firmware_memory[0x1235] = 0xffu;
    firmware_memory[0x0e3e] = 1u;
    assert(CalculateReadAcquisitionAbsoluteFrameDistance() == 2u && firmware_memory[0x0ee3] == 0u);

    clear_memory(0);
    firmware_memory[0x1243] = 10u;
    firmware_memory[0x0ef4] = 5u;
    UpdateReadAcquisitionFrameDistanceFromMsfTuple();
    assert(firmware_memory[0x0ef4] == 10u && firmware_memory[0x0ee8] == 0x90u);
    firmware_memory[0x1006] = 1u;
    firmware_memory[0x1243] = 11u;
    UpdateReadAcquisitionFrameDistanceFromMsfTuple();
    assert(firmware_memory[0x0ef4] == 11u && firmware_memory[0x0ee7] == 9u && firmware_memory[0x0ee8] == 0x60u);
    firmware_memory[0x1243] = 5u;
    UpdateReadAcquisitionFrameDistanceFromMsfTuple();
    assert(firmware_memory[0x0ee8] == 6u);

    firmware_memory[0x1560] = 0x20u;
    assert(SetMainDataRingCursorAtSectorOffset(1u, 0x100u) == 0xa30u);
    assert(firmware_memory[0x15da] == 0x0au && firmware_memory[0x15db] == 0x30u);
    assert(SetMainDataRingCursorAtSectorOffset(1u, 0x1900u) == 0x230u);
    assert(firmware_memory[0x15da] == 2u && firmware_memory[0x15db] == 0x30u);

    firmware_memory[0x159b] = 150u;
    assert(GetReadPipelineTargetThirtyNineFrameRemainder() == 0u);
    firmware_memory[0x159b] = 190u;
    assert(GetReadPipelineTargetThirtyNineFrameRemainder() == 1u);
    firmware_memory[0x159b] = 149u;
    assert(GetReadPipelineTargetThirtyNineFrameRemainder() == 0xffu);
}

