static void test_find_track_table_entry_by_number(void)
{
    unsigned query;
    unsigned entry_index;

    clear_memory(0);
    assert(FindTrackTableEntryByNumber(0u) == 1u && read_count == 0u);

    for(query = 1u; query != 256u; query++)
    {
        u8 expected = 0u;
        u8 matched = 0u;

        clear_memory(0);
        firmware_memory[0x12c0u] = 0x55u;
        for(entry_index = 1u; entry_index < 100u; entry_index++)
        {
            u8 value = (u8)(entry_index * 7u);

            firmware_memory[(u16)(0xdd92u + entry_index * 19u)] = value;
            if(matched == 0u && value == (u8)query)
            {
                expected = (u8)entry_index;
                matched = 1u;
            }
        }
        if(matched == 0u)
            expected = 0x56u;
        assert(FindTrackTableEntryByNumber((u8)query) == expected);
        assert(read_count == (unsigned)(matched == 0u ? 100u : expected));
    }
}

