static void test_update_track_table_from_working_track(void)
{
    unsigned working_type;

    clear_memory(0xa5u);
    firmware_memory[0xdd34u] = 0u;
    UpdateTrackTableFromWorkingTrack();
    assert(write_count == 0u);
    firmware_memory[0xdd34u] = 8u;
    UpdateTrackTableFromWorkingTrack();
    assert(write_count == 0u);

    clear_memory(0);
    firmware_memory[0xdd34u] = 5u;
    firmware_memory[0xdd35u] = 2u;
    firmware_memory[0xdd36u] = 0x51u;
    firmware_memory[0xdd38u] = 0x40u;
    firmware_memory[0xdd56u] = 1u;
    firmware_memory[0xdd5fu] = 1u;
    firmware_memory[0xdd60u] = 0x5au;
    firmware_memory[0xdd7fu] = 2u;
    set_memory_big_endian_u32(0xdd3du, 4653ul);
    set_memory_big_endian_u32(0xdd41u, 4729ul);
    set_memory_big_endian_u32(0xdd45u, 0x01020304ul);
    set_memory_big_endian_u32(0xdd51u, 0x11223344ul);
    set_memory_big_endian_u32(0xdd57u, 0x55667788ul);
    UpdateTrackTableFromWorkingTrack();
    assert(firmware_memory[0xdda6u] == 0x51u && firmware_memory[0xdda7u] == 1u && firmware_memory[0xdda8u] == 2u && firmware_memory[0xdda9u] == 3u && firmware_memory[0xddaau] == 1u
           && firmware_memory[0xddabu] == 3u && firmware_memory[0xddacu] == 4u && firmware_memory[0xddadu] == 5u && firmware_memory[0xddaeu] == 0x40u && firmware_memory[0xddafu] == 3u
           && firmware_memory[0xddb0u] == 0x55u && firmware_memory[0xddb1u] == 0x66u && firmware_memory[0xddb2u] == 0x77u && firmware_memory[0xddb3u] == 0x88u && firmware_memory[0xddb4u] == 0x11u
           && firmware_memory[0xddb5u] == 0x22u && firmware_memory[0xddb6u] == 0x33u && firmware_memory[0xddb7u] == 0x44u && firmware_memory[0xddb8u] == 0x5au && firmware_memory[0xdd7fu] == 3u
           && firmware_memory[0xddc0u] == 0u);
    assert(write_count == 22u && write_trace[0] == 0xddadul && write_trace[1] == 0xdda6ul && write_trace[2] == 0xdda9ul && write_trace[4] == 0xdda8ul && write_trace[5] == 0xddacul
           && write_trace[7] == 0xddabul && write_trace[8] == 0xddaeul && write_trace[9] == 0xddaf && write_trace[10] == 0xddb8ul && write_trace[11] == 0xddaf && write_trace[12] == 0xddb4ul
           && write_trace[15] == 0xddb7ul && write_trace[16] == 0xddb0ul && write_trace[19] == 0xddb3ul && write_trace[20] == 0xdd7ful && write_trace[21] == 0xddc0ul);

    for(working_type = 1u; working_type <= 7u; working_type++)
    {
        u8 should_advance = (u8)(working_type >= 2u && working_type <= 5u);

        clear_memory(0);
        firmware_memory[0xdd34u] = (u8)working_type;
        firmware_memory[0xdd35u] = 2u;
        firmware_memory[0xdd7fu] = 2u;
        if(working_type == 7u)
            firmware_memory[0xdd5fu] = 1u;
        UpdateTrackTableFromWorkingTrack();
        if(working_type == 7u)
            should_advance = 1u;
        assert(firmware_memory[0xdd7fu] == (u8)(should_advance != 0u ? 3u : 2u));
    }
}

