static void test_decode_working_track_mode_from_tdi_record(void)
{
    unsigned record_class;
    unsigned pair;

    for(record_class = 0u; record_class < 4u; record_class++)
    {
        clear_memory(0);
        firmware_memory[0x2bb91cul] = (u8)record_class;
        DecodeWorkingTrackModeFromTdiRecord(0x00dd38ul, 0x00dd37ul);
        assert(firmware_memory[0x00dd37ul] == (u8)record_class && firmware_memory[0x00dd38ul] == (u8)(record_class == 2u ? 0x10u : 0x40u));
        assert(write_count == 2u && write_trace[0] == 0x00dd37ul && write_trace[1] == 0x00dd38ul);
        if(record_class != 2u)
            assert(read_count == 2u && read_trace[0] == 0x2bb91cul && read_trace[1] == 0x00dd37ul);
    }

    {
        static const u8 profiles[14][8] = {
            { 0x23u, 0x80u, 0xffu, 0xc0u, 0x72u, 0x00u, 0xf6u, 0x4eu },
            { 0x23u, 0x80u, 0xffu, 0xc0u, 0x72u, 0x00u, 0xf6u, 0x4eu },
            { 0x13u, 0xc0u, 0xffu, 0xc0u, 0x73u, 0x00u, 0xf6u, 0x6au },
            { 0x01u, 0x84u, 0xc8u, 0xc0u, 0xb5u, 0x00u, 0xf6u, 0x6eu },
            { 0x01u, 0x84u, 0xc8u, 0xc0u, 0xb5u, 0x00u, 0xf6u, 0x6eu },
            { 0x01u, 0x84u, 0xa8u, 0xc0u, 0xb7u, 0x00u, 0xf6u, 0x72u },
            { 0x00u, 0x84u, 0xc7u, 0xc0u, 0x9fu, 0x00u, 0xf6u, 0x8eu },
            { 0x00u, 0x84u, 0xa7u, 0xc0u, 0x9fu, 0x00u, 0xf6u, 0x6eu },
            { 0x00u, 0x84u, 0xc7u, 0xc0u, 0x9fu, 0x00u, 0xf6u, 0x8eu },
            { 0x00u, 0x84u, 0xa7u, 0xc0u, 0x9fu, 0x00u, 0xf6u, 0x6eu },
            { 0x00u, 0x84u, 0xc7u, 0xc0u, 0x9fu, 0x00u, 0xf6u, 0x8eu },
            { 0x00u, 0x84u, 0xa7u, 0xc0u, 0x9fu, 0x00u, 0xf6u, 0x6eu },
            { 0x00u, 0x84u, 0xc7u, 0xc0u, 0x9fu, 0x00u, 0xf6u, 0x8eu },
            { 0x00u, 0x84u, 0xa7u, 0xc0u, 0x9fu, 0x00u, 0xf6u, 0x6eu }
        };
        static const fw_addr_t ports[8] = { 0x18094ul, 0x18095ul, 0x18096ul, 0x18097ul, 0x18092ul, 0x18091ul, 0x18093ul, 0x18090ul };
        unsigned profile_index;
        unsigned port_index;

        for(profile_index = 0u; profile_index < 14u; profile_index++)
        {
            clear_memory(0);
            firmware_memory[0x18015] = 0x20u;
            firmware_memory[0xfab7] = 0xeeu;
            WriteControllerPorts8090Through8097FromProfile((u8)profile_index);
            assert(write_count == 8u);
            for(port_index = 0u; port_index < 8u; port_index++)
            {
                assert(write_trace[port_index] == ports[port_index]);
                assert(write_values[port_index] == (port_index == 3u && profile_index >= 6u ? 0xeeu : profiles[profile_index][port_index]));
            }
        }

        for(profile_index = 8u; profile_index <= 9u; profile_index++)
        {
            unsigned state;
            unsigned selected_profile;

            for(state = 0u; state <= 2u; state++)
            {
                clear_memory(0);
                firmware_memory[0x18015] = 0x20u;
                firmware_memory[0x0e43] = 0x34u;
                firmware_memory[0x1008] = (u8)state;
                firmware_memory[0xfab7] = 0xa5u;
                WriteControllerPorts8090Through8097FromProfile((u8)profile_index);
                selected_profile = state == 0u ? profile_index + 2u : state == 2u ? profile_index + 4u : profile_index;
                assert(write_count == 8u);
                for(port_index = 0u; port_index < 8u; port_index++)
                {
                    assert(write_trace[port_index] == ports[port_index]);
                    assert(write_values[port_index] == (port_index == 3u ? 0xa5u : profiles[selected_profile][port_index]));
                }
            }
        }
    }

    clear_memory(0);
    firmware_memory[0x2bb91cul] = 2u;
    firmware_memory[0x2bb91dul] = 1u;
    firmware_memory[0x2bb91eul] = 2u;
    firmware_memory[0x2bb91ful] = 3u;
    firmware_memory[0x2bb920ul] = 4u;
    firmware_memory[0x2bb921ul] = 1u;
    firmware_memory[0x2bb922ul] = 2u;
    firmware_memory[0x2bb923ul] = 3u;
    firmware_memory[0x2bb924ul] = 4u;
    DecodeWorkingTrackModeFromTdiRecord(0x00dd38ul, 0x00dd37ul);
    assert(read_count == 11u && firmware_memory[0x00dd38ul] == 0x10u && read_trace[0] == 0x2bb91cul && read_trace[1] == 0x00dd37ul && read_trace[2] == 0x2bb921ul && read_trace[3] == 0x2bb91dul
           && read_trace[4] == 0x2bb922ul && read_trace[5] == 0x2bb91eul && read_trace[6] == 0x2bb923ul && read_trace[7] == 0x2bb91ful);

    firmware_memory[0x2bb91ful] = 0x23u;
    firmware_memory[0x2bb923ul] = 0x23u;
    read_count = 0u;
    write_count = 0u;
    DecodeWorkingTrackModeFromTdiRecord(0x00dd38ul, 0x00dd37ul);
    assert(read_count == 11u && firmware_memory[0x00dd38ul] == 0x08u);

    for(pair = 0u; pair < 4u; pair++)
    {
        fw_addr_t left = 0x2bb91dul + (fw_addr_t)pair;
        fw_addr_t right = 0x2bb921ul + (fw_addr_t)pair;

        clear_memory(0);
        firmware_memory[0x2bb91cul] = 2u;
        firmware_memory[0x2bb91dul] = 1u;
        firmware_memory[0x2bb91eul] = 2u;
        firmware_memory[0x2bb91ful] = 3u;
        firmware_memory[0x2bb920ul] = 4u;
        firmware_memory[0x2bb921ul] = 1u;
        firmware_memory[0x2bb922ul] = 2u;
        firmware_memory[0x2bb923ul] = 3u;
        firmware_memory[0x2bb924ul] = 4u;
        firmware_memory[right] = (u8)(firmware_memory[left] + 1u);
        DecodeWorkingTrackModeFromTdiRecord(0x00dd38ul, 0x00dd37ul);
        assert(read_count == 10u && firmware_memory[0x00dd38ul] == 0x20u);
    }
}

