static void test_derive_working_track_start_frame_and_read_plan(void)
{
    struct plan_case
    {
        u8 status;
        u8 status_flags;
        u8 selected_mode;
        u8 status_class;
        u8 data_block_type;
        u16 pause;
        u8 expected_result;
        u8 expected_plan;
        u32 expected_adjustment;
    };
    static const struct plan_case cases[] = {
        { 4u, 0x40u, 4u, 0u, 4u, 0u,   1u, 8u,    150ul },
        { 4u, 0x40u, 0u, 0u, 4u, 149u, 0u, 0xa5u, 0u    },
        { 4u, 0x40u, 0u, 0u, 4u, 150u, 1u, 9u,    150ul },
        { 4u, 0u,    4u, 0u, 4u, 0u,   1u, 2u,    225ul },
        { 4u, 0u,    0u, 0u, 4u, 123u, 1u, 10u,   123ul },
        { 2u, 0u,    4u, 0u, 4u, 0u,   1u, 8u,    150ul },
        { 2u, 0u,    0u, 0u, 4u, 123u, 1u, 9u,    123ul },
        { 0u, 0x40u, 4u, 2u, 8u, 0u,   1u, 4u,    225ul },
        { 0u, 0x40u, 4u, 2u, 7u, 0u,   1u, 6u,    150ul },
        { 0u, 0x40u, 4u, 1u, 8u, 0u,   1u, 5u,    150ul },
        { 0u, 0x40u, 4u, 1u, 7u, 0u,   1u, 3u,    225ul },
        { 0u, 0x40u, 4u, 0u, 8u, 0u,   1u, 4u,    225ul },
        { 0u, 0x40u, 4u, 0u, 7u, 0u,   1u, 3u,    225ul },
        { 0u, 0x40u, 0u, 0u, 7u, 149u, 0u, 0xa5u, 0u    },
        { 0u, 0x40u, 0u, 0u, 7u, 150u, 1u, 7u,    150ul },
        { 0u, 0u,    4u, 0u, 7u, 0u,   1u, 2u,    225ul },
        { 0u, 0u,    0u, 0u, 7u, 123u, 1u, 10u,   123ul }
    };
    size_t index;
    unsigned selected_mode;
    unsigned data_block_type;

    for(selected_mode = 0u; selected_mode != 256u; ++selected_mode)
    {
        for(data_block_type = 0u; data_block_type != 4u; ++data_block_type)
        {
            clear_memory(0xa5u);
            firmware_memory[0xdd34u] = 0u;
            firmware_memory[0x0c47u] = (u8)(selected_mode | 4u);
            firmware_memory[0x0c48u] = (u8)data_block_type;
            set_memory_big_endian_u32(0xdd39u, 0xffffff80ul);
            assert(DeriveWorkingTrackStartFrameAndReadPlan() == 1u);
            assert(read_count == 7u && read_trace[0] == 0x00dd34ul && read_trace[1] == 0x0c47ul && read_trace[2] == 0x0c48ul && read_trace[3] == 0x00dd39ul && read_trace[6] == 0x00dd3cul);
            assert(write_count == 4u && write_trace[0] == 0x00dd3dul && write_trace[3] == 0x00dd40ul && firmware_memory[0xdd62u] == 0xa5u);
            assert(firmware_memory[0xdd3du] == 0u && firmware_memory[0xdd3eu] == 0u && firmware_memory[0xdd3fu] == 0u && firmware_memory[0xdd40u] == 0x16u);
        }
    }

    clear_memory(0xa5u);
    firmware_memory[0xdd34u] = 1u;
    assert(DeriveWorkingTrackStartFrameAndReadPlan() == 1u && read_count == 1u && read_trace[0] == 0x00dd34ul && write_count == 0u);

    for(index = 0; index < sizeof(cases) / sizeof(cases[0]); ++index)
    {
        const struct plan_case *test_case = &cases[index];

        clear_memory(0xa5u);
        firmware_memory[0xdd34u] = 0u;
        firmware_memory[0xdd2fu] = test_case->status;
        firmware_memory[0xdd31u] = test_case->status_flags;
        firmware_memory[0xdd32u] = test_case->status_class;
        firmware_memory[0x0c47u] = test_case->selected_mode;
        firmware_memory[0x0c48u] = test_case->data_block_type;
        set_memory_big_endian_u16(0x0c4fu, test_case->pause);
        set_memory_big_endian_u32(0xdd39u, 0xffffff80ul);
        assert(DeriveWorkingTrackStartFrameAndReadPlan() == test_case->expected_result);
        if(test_case->expected_result == 0u)
        {
            assert(firmware_memory[0x0b18u] == 0x70u && firmware_memory[0x0b1au] == 5u && firmware_memory[0x0b24u] == 0x2cu && firmware_memory[0x0b25u] == 0u);
            assert(firmware_memory[0xdd62u] == 0xa5u && firmware_memory[0xdd3du] == 0xa5u);
        }
        else
        {
            u32 expected_position = 0xffffff80ul + test_case->expected_adjustment;

            assert(firmware_memory[0xdd62u] == test_case->expected_plan);
            assert(firmware_memory[0xdd3du] == (u8)(expected_position >> 24) && firmware_memory[0xdd3eu] == (u8)(expected_position >> 16) && firmware_memory[0xdd3fu] == (u8)(expected_position >> 8)
                   && firmware_memory[0xdd40u] == (u8)expected_position);
        }
    }
}

static void test_raw_state_and_sense_leaves(void)
{
    static const fw_addr_t raw_state_writes[] = { 0x1491ul, 0x1492ul, 0x1493ul, 0x1494ul, 0x1495ul, 0x1496ul, 0x1497ul, 0x1498ul, 0x1499ul, 0x149aul, 0x142bul, 0x142aul, 0x1429ul, 0x1428ul, 0x142ful,
        0x142eul, 0x142dul, 0x142cul, 0x1434ul, 0x1435ul, 0x1436ul, 0x1437ul, 0x1430ul, 0x1431ul, 0x1432ul, 0x1433ul, 0x1439ul, 0x1438ul, 0x143aul, 0x143bul, 0x1454ul };
    static const fw_addr_t type2_reset_writes[] = { 0x2ba5a3ul, 0x2ba5a4ul, 0x2ba5a5ul, 0x2ba5a6ul, 0x2ba532ul, 0x2ba533ul, 0x2ba534ul, 0x2ba535ul, 0x2ba59ful, 0x2ba5a0ul, 0x2ba5a1ul, 0x2ba5a2ul,
        0x2ba52eul, 0x2ba52ful, 0x2ba530ul, 0x2ba531ul, 0x2ba525ul, 0x2ba526ul, 0x2ba527ul, 0x2ba528ul, 0x2ba524ul, 0x0c8aul, 0x0c89ul, 0x122cul, 0x0c89ul, 0x122bul, 0x0c8bul, 0x0c8bul, 0x0c9eul };
    size_t index;
    unsigned flags;

    clear_memory(0xa5u);
    ClearRawReadPipelineStatusState();
    assert(write_count == sizeof(raw_state_writes) / sizeof(raw_state_writes[0]));
    for(index = 0; index != write_count; ++index)
    {
        assert(write_trace[index] == raw_state_writes[index]);
        assert(write_values[index] == 0u);
    }
    assert(firmware_memory[0x1427] == 0xa5u && firmware_memory[0x143cul] == 0xa5u);

    clear_memory(0xa5u);
    SetNoSenseData();
    assert(write_count == 8u);
    assert(write_trace[0] == 0x0b18ul && write_values[0] == 0x70u);
    assert(write_trace[1] == 0x0b1aul && write_trace[2] == 0x0b24ul && write_trace[3] == 0x0b25ul && write_trace[4] == 0x0b1bul && write_trace[5] == 0x0b1cul && write_trace[6] == 0x0b1dul
           && write_trace[7] == 0x0b1eul);
    for(index = 1; index != write_count; ++index)
        assert(write_values[index] == 0u);

    for(flags = 0; flags != 256u; ++flags)
    {
        clear_memory(0);
        firmware_memory[0x0c83] = (u8)flags;
        ClearScsiCompletionBits0And1IfBit4Set();
        if((flags & 0x10u) == 0)
        {
            assert(read_count == 1u && write_count == 0u);
            assert(firmware_memory[0x0c83] == (u8)flags);
        }
        else
        {
            assert(read_count == 4u && write_count == 3u);
            assert(write_values[0] == (u8)(flags & 0xefu));
            assert(write_values[1] == (u8)(flags & 0xeeu));
            assert(write_values[2] == (u8)(flags & 0xecu));
            assert(firmware_memory[0x0c83] == (u8)(flags & 0xecu));
        }
    }

    clear_memory(0xa5u);
    firmware_memory[0x0c8a] = 0xffu;
    firmware_memory[0x0c89] = 0xffu;
    firmware_memory[0x0c8b] = 0xffu;
    firmware_memory[0x00e750ul] = 0u;
    ResetType2ControllerRecordDetectionState();
    assert(write_count == sizeof(type2_reset_writes) / sizeof(type2_reset_writes[0]));
    for(index = 0; index != write_count; ++index)
        assert(write_trace[index] == type2_reset_writes[index]);
    assert(firmware_memory[0x0c8a] == 0xfeu && firmware_memory[0x0c89] == 0x77u && firmware_memory[0x0c8b] == 0xf9u && firmware_memory[0x122c] == 10u && firmware_memory[0x122b] == 0x14u
           && firmware_memory[0x0c9e] == 0u);
    firmware_memory[0x00e750ul] = 1u;
    ResetType2ControllerRecordDetectionState();
    assert(firmware_memory[0x122b] == 0x3cu);
}

