static void test_controller_buffer_zone_presence_clear(void)
{
    unsigned page_index;

    clear_memory(0);
    firmware_memory[0xfa17] = 0xffu;
    ClearControllerBufferRecordZonePresenceBit(3u, 2u);
    assert(write_count == 9u && read_count == 9u);
    assert(write_trace[0] == 0xfa17ul && write_values[0] == 0xfbu);
    for(page_index = 0; page_index != 8u; ++page_index)
    {
        assert(write_trace[page_index + 1u] == 0x40c00ful + ((fw_addr_t)page_index << 11));
        assert(write_values[page_index + 1u] == 0xfbu);
    }

    clear_memory(0);
    firmware_memory[0xfa17] = 0xa5u;
    ClearControllerBufferRecordZonePresenceBit(0xffffu, 8u);
    assert(write_count == 8u && read_count == 8u);
    assert(firmware_memory[0xfa17] == 0xa5u);
    for(page_index = 0; page_index != 8u; ++page_index)
    {
        assert(write_trace[page_index] == ((0x3fc00ful + ((fw_addr_t)page_index << 11)) & 0xfffffful));
        assert(write_values[page_index] == 0xa5u);
    }
}

static void test_debounced_p1_bit5_predicate(void)
{
    unsigned value;
    unsigned drive_state;

    clear_memory(0);
    for(value = 0; value != 256u; ++value)
    {
        firmware_memory[0x11ed] = (u8)value;
        for(drive_state = 0; drive_state != 256u; ++drive_state)
        {
            /* Stock reads the debounced port sample, independently of the
             * control state. Equal or zero-only seeds hid the wrong address. */
            firmware_memory[0x1300] = (u8)drive_state;
            read_count = 0;
            assert(IsDebouncedP1Bit5Low() == ((value & 0x20u) != 0 ? 1u : 0u));
            assert(read_count == 1u && read_trace[0] == 0x11edul && write_count == 0u);
            read_count = 0;
            assert(IsDebouncedP1Bit6Low() == ((value & 0x40u) != 0 ? 1u : 0u));
            assert(read_count == 1u && read_trace[0] == 0x11edul && write_count == 0u);
            read_count = 0;
            assert(IsDebouncedP1Bit7Low() == ((value & 0x80u) != 0 ? 1u : 0u));
            assert(read_count == 1u && read_trace[0] == 0x11edul && write_count == 0u);
        }
    }
}

static void test_p1_bit3_stability_for_current_media_state(void)
{
    unsigned sample;

    clear_memory(0);
    assert(CheckP1Bit3StableHighForCurrentMediaState() == 1u);
    assert(read_count == 1u && read_trace[0] == 0x1008ul);
    assert(sfr_read_count == 0u);

    clear_memory(0);
    firmware_memory[0x1008] = 2u;
    firmware_memory[0x1245] = 0u;
    assert(CheckP1Bit3StableHighForCurrentMediaState() == 0u);
    assert(read_count == 2u && sfr_read_count == 0u);

    clear_memory(0);
    firmware_memory[0x1008] = 1u;
    sfr_memory[0x90] = 0x08u;
    assert(CheckP1Bit3StableHighForCurrentMediaState() == 1u);
    assert(sfr_read_count == 20u);
    for(sample = 0; sample != sfr_read_count; ++sample)
        assert(sfr_read_trace[sample] == 0x90u);

    clear_memory(0);
    firmware_memory[0x1008] = 1u;
    sfr_memory[0x90] = 0u;
    assert(CheckP1Bit3StableHighForCurrentMediaState() == 0u);
    assert(sfr_read_count == 39u);

    clear_memory(0);
    firmware_memory[0x1008] = 1u;
    p1_bit3_sample_count = 57u;
    for(sample = 0; sample != 37u; ++sample)
        p1_bit3_samples[sample] = 0u;
    for(; sample != p1_bit3_sample_count; ++sample)
        p1_bit3_samples[sample] = 0x08u;
    assert(CheckP1Bit3StableHighForCurrentMediaState() == 1u);
    assert(sfr_read_count == 57u && p1_bit3_sample_index == 57u);

    clear_memory(0);
    firmware_memory[0x1008] = 1u;
    p1_bit3_sample_count = 2u;
    p1_bit3_samples[0] = 0x08u;
    p1_bit3_samples[1] = 0u;
    assert(CheckP1Bit3StableHighForCurrentMediaState() == 0u);
    assert(sfr_read_count == 2u);
}

