static void test_write_transfer_thirty_two_block_boundaries(void)
{
    static const u32 logical_addresses[] = { 0ul, 1ul, 30ul, 31ul, 32ul, 33ul, 0x7ffffffful, 0x80000000ul, 0xffffffe0ul, 0xfffffffful };
    unsigned address_index;
    unsigned block_count;

    for(address_index = 0; address_index != sizeof(logical_addresses) / sizeof(logical_addresses[0]); ++address_index)
    {
        u32 address = logical_addresses[address_index];

        u32 expected;

        if((address & 0x80000000ul) == 0u)
        {
            expected = 0x20ul - (address & 0x1ful);
        }
        else
        {
            u32 magnitude = (u32)(~address + 1ul);
            u32 truncated_multiple = (u32)(0ul - ((magnitude >> 5) << 5));

            expected = (u32)(0x20ul - (address - truncated_multiple));
        }
        assert(ComputeBlocksThroughNextThirtyTwoBoundary(address) == expected);
    }

    clear_memory(0);
    for(address_index = 0; address_index != 64u; ++address_index)
    {
        u32 address = (u32)address_index;
        u32 remaining = ComputeBlocksThroughNextThirtyTwoBoundary(address);

        for(block_count = 0; block_count != 65u; ++block_count)
        {
            set_memory_big_endian_u32(0x0b06u, (u32)block_count);
            read_count = 0u;
            assert(DoesTransferCrossNextThirtyTwoBoundary(address) == ((u32)block_count > remaining ? 1u : 0u));
            assert(read_count == 4u && read_trace[0] == 0x0b06ul && read_trace[1] == 0x0b07ul && read_trace[2] == 0x0b08ul && read_trace[3] == 0x0b09ul);
        }
    }

    assert(ComputeBlocksThroughNextThirtyTwoBoundary(0xfffffffful) == 33ul);
    assert(ComputeBlocksThroughNextThirtyTwoBoundary(0xffffffdful) == 33ul);
    set_memory_big_endian_u32(0x0b06u, 0xfffffffful);
    assert(DoesTransferCrossNextThirtyTwoBoundary(0x80000000ul) == 1u);
    set_memory_big_endian_u32(0x0b06u, 0x20ul);
    assert(DoesTransferCrossNextThirtyTwoBoundary(0xffffffe0ul) == 0u);
}

static void test_align_write_transfer_cursor_for_block_count(void)
{
    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2bc703ul, 64ul);
    firmware_memory[0x2ba5c6ul] = 0x7au;
    write_transfer_alignment_expanded_result = 0x12345678l;
    write_transfer_alignment_initialize_result = 0x89abcdeful;
    assert(AlignWriteTransferCursorForBlockCount(32ul) == 32ul);
    assert(get_memory_big_endian_u32(0x2bc703ul) == 64ul);
    assert(write_transfer_alignment_map_input == 64ul && write_transfer_alignment_initialize_seen_start == 0x12345678ul);
    assert(write_transfer_alignment_event_count == 2u && memcmp(write_transfer_alignment_events, "EI", 2u) == 0);
    assert(get_memory_big_endian_u32(0x1598u) == 0x89abcdeful && get_memory_big_endian_u32(0x8000ul) == 0x89abcdeful);

    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2bc703ul, 64ul);
    firmware_memory[0x2ba5c6ul] = 0x7au;
    firmware_memory[0x0c8au] = 4u;
    write_transfer_alignment_fixed_result = 0x01020304ul;
    write_transfer_alignment_initialize_result = 0x05060708ul;
    assert(AlignWriteTransferCursorForBlockCount(33ul) == 0x7aul);
    assert(get_memory_big_endian_u32(0x2bc703ul) == 96ul);
    assert(write_transfer_alignment_map_input == 96ul && write_transfer_alignment_initialize_seen_start == 0x01020304ul);
    assert(write_transfer_alignment_event_count == 2u && memcmp(write_transfer_alignment_events, "FI", 2u) == 0);

    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2bc703ul, 65ul);
    set_memory_big_endian_u32(0x0b06u, 31ul);
    firmware_memory[0x2ba5c6ul] = 0x55u;
    assert(AlignWriteTransferCursorForBlockCount(1ul) == 0x55ul);
    assert(get_memory_big_endian_u32(0x2bc703ul) == 64ul);
    assert(write_transfer_alignment_map_input == 64ul);

    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2bc703ul, 65ul);
    set_memory_big_endian_u32(0x0b06u, 32ul);
    firmware_memory[0x2ba5c6ul] = 0x55u;
    assert(AlignWriteTransferCursorForBlockCount(1ul) == 0x55ul);
    assert(get_memory_big_endian_u32(0x2bc703ul) == 96ul);
    assert(write_transfer_alignment_map_input == 96ul);

    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2bc703ul, 0xfffffffful);
    set_memory_big_endian_u32(0x0b06u, 34ul);
    firmware_memory[0x2ba5c6ul] = 0xa5u;
    assert(AlignWriteTransferCursorForBlockCount(0xfffffffful) == 0xa5ul);
    assert(get_memory_big_endian_u32(0x2bc703ul) == 32ul);
    assert(write_transfer_alignment_map_input == 32ul);
}

