static void test_enqueue_thirty_two_synthetic_write_descriptors(void)
{
    static const u8 iteration_events[8] = { 'C', 'W', 'S', 'H', 'Q', 'E', 'A', 'N' };
    static const u8 initial_relative[3] = { 0x12u, 0x34u, 0x56u };
    static const u8 initial_absolute[3] = { 0x00u, 0x59u, 0x74u };
    unsigned index;

    clear_memory(0u);
    memcpy(&firmware_memory[0x1275u], initial_relative, 3u);
    memcpy(&firmware_memory[0x1279u], initial_absolute, 3u);
    firmware_memory[0x142bu] = 0x5au;
    synthetic_write_descriptor_resume_cursor = 0x1000ul;
    synthetic_write_descriptor_expanded_result = 4499l;

    EnqueueThirtyTwoSyntheticWriteDescriptorsForStartAddress(123l);

    assert(synthetic_write_descriptor_map_input == 123l);
    assert(
        synthetic_write_descriptor_event_count == 259u && synthetic_write_descriptor_events[0] == 'R' && synthetic_write_descriptor_events[1] == 'X' && synthetic_write_descriptor_events[258] == 'C');
    for(index = 0u; index != 32u; ++index)
    {
        assert(memcmp(&synthetic_write_descriptor_events[2u + index * 8u], iteration_events, sizeof(iteration_events)) == 0);
        assert(synthetic_write_descriptor_submit_cursors[index] == 0x3df0ul + (u32)index * 0x930ul);
        assert(synthetic_write_descriptor_advance_cursors[index] == synthetic_write_descriptor_submit_cursors[index]);
    }
    assert(synthetic_write_descriptor_copy_count == 33u && synthetic_write_descriptor_submit_count == 32u && synthetic_write_descriptor_advance_count == 32u);
    assert(synthetic_write_descriptor_copied_tuples[0][0] == 0x01u && synthetic_write_descriptor_copied_tuples[0][1] == 0x01u && synthetic_write_descriptor_copied_tuples[0][2] == 0x74u);
    assert(synthetic_write_descriptor_copied_tuples[1][0] == 0x01u && synthetic_write_descriptor_copied_tuples[1][1] == 0x02u && synthetic_write_descriptor_copied_tuples[1][2] == 0x00u);
    assert(synthetic_write_descriptor_copied_tuples[31][0] == 0x01u && synthetic_write_descriptor_copied_tuples[31][1] == 0x02u && synthetic_write_descriptor_copied_tuples[31][2] == 0x30u);
    assert(memcmp(&firmware_memory[0x1275u], initial_relative, 3u) == 0 && memcmp(&firmware_memory[0x1279u], initial_absolute, 3u) == 0 && memcmp(&firmware_memory[0x1428u], initial_absolute, 3u) == 0
           && firmware_memory[0x18028u] == 0x5au);

    clear_memory(0u);
    firmware_memory[0x0c88u] = 0x80u;
    synthetic_write_descriptor_fixed_result = (u32)-151l;
    EnqueueThirtyTwoSyntheticWriteDescriptorsForStartAddress(-33l);
    assert(synthetic_write_descriptor_event_count == 259u && synthetic_write_descriptor_events[1] == 'F' && synthetic_write_descriptor_map_input == -33l);
    assert(synthetic_write_descriptor_copied_tuples[0][0] == 0x99u && synthetic_write_descriptor_copied_tuples[0][1] == 0x59u && synthetic_write_descriptor_copied_tuples[0][2] == 0x74u);
    assert(firmware_memory[0x1275u] == 0u && firmware_memory[0x1276u] == 0u && firmware_memory[0x1277u] == 0u && firmware_memory[0x1279u] == 0u && firmware_memory[0x127au] == 0u
           && firmware_memory[0x127bu] == 0u);
}

