static void test_calibrate_controller_parameter_f4(void)
{
    unsigned index;

    clear_memory(0u);
    f4_calibration_measurement_count = 4u;
    memset(f4_calibration_measurements, 91, 4u);
    CalibrateControllerParameterF4();
    assert(firmware_memory[0xfc14u] == 0xd8u && firmware_memory[0xfacau] == 0xd8u && firmware_memory[0x120au] == 10u);
    assert(f4_calibration_parameter_count == 1u && f4_calibration_parameter_values[0] == 0xf4d8u && f4_calibration_measurement_index == 4u && f4_calibration_wait_count == 6u);
    assert(f4_calibration_wait_durations[0] == 7000u && f4_calibration_wait_durations[1] == 400u);
    for(index = 2u; index != 6u; ++index)
        assert(f4_calibration_wait_durations[index] == 100u && f4_calibration_wait_yields[index] == 1u);
    assert(f4_calibration_events[0] == 'C' && f4_calibration_events[1] == 'I' && f4_calibration_events[f4_calibration_event_count - 1u] == 'R');

    clear_memory(0u);
    f4_calibration_measurement_count = 4u;
    memset(f4_calibration_measurements, 107, 4u);
    CalibrateControllerParameterF4();
    assert(f4_calibration_parameter_count == 1u && firmware_memory[0xfacau] == 0xd8u);

    clear_memory(0u);
    f4_calibration_measurement_count = 8u;
    memset(f4_calibration_measurements, 108, 4u);
    memset(&f4_calibration_measurements[4], 100, 4u);
    CalibrateControllerParameterF4();
    assert(f4_calibration_parameter_count == 2u && f4_calibration_parameter_values[0] == 0xf4d8u && f4_calibration_parameter_values[1] == 0xf4b4u && firmware_memory[0xfc14u] == 0xb4u
           && firmware_memory[0xfacau] == 0xb4u);

    clear_memory(0u);
    f4_calibration_measurement_count = 4u;
    memset(f4_calibration_measurements, 90, 4u);
    CalibrateControllerParameterF4();
    assert(f4_calibration_parameter_count == 2u && f4_calibration_parameter_values[0] == 0xf4d8u && f4_calibration_parameter_values[1] == 0xf4fcu && firmware_memory[0xfc14u] == 0xfcu
           && firmware_memory[0xfacau] == 0xfcu);

    clear_memory(0u);
    f4_calibration_measurement_count = 4u;
    memset(f4_calibration_measurements, 90, 4u);
    f4_calibration_expire_after_measurements = 4u;
    CalibrateControllerParameterF4();
    assert(f4_calibration_parameter_count == 1u && firmware_memory[0x120au] == 0xffu && firmware_memory[0xfc14u] == 0xfcu && firmware_memory[0xfacau] == 0xd8u);

    clear_memory(0u);
    f4_calibration_measurement_count = 24u;
    memset(f4_calibration_measurements, 108, 24u);
    CalibrateControllerParameterF4();
    assert(f4_calibration_parameter_count == 7u && f4_calibration_parameter_values[6] == 0xf400u && f4_calibration_measurement_index == 24u && firmware_memory[0xfc14u] == 0u
           && firmware_memory[0xfacau] == 0u);
}

