    assert((firmware_memory[0x11efu] & 0x20u) == 0u);
    assert(get_memory_big_endian_u32(0x0500u) == 0x00f852ebul);

    clear_memory(0);
    firmware_memory[0x11efu] = 0x10u;
    firmware_memory[0x1300u] = 0x20u;
