    sfr_d8_countdown_after = 0u;
    for(index = 0u; index < sfr_d8_sample_count; ++index)
        sfr_d8_samples[index] = 0x1bu;
    sfr_d8_samples[0] = 0x20u;
    sfr_d8_samples[1] = 0x10u;
    assert(MeasureSfrD8RangeAtLeast16() == 1u);
    assert(yield_coroutine1_count == 1u && firmware_memory[0x1215u] == 0u);
