static u8 configuration_queue_count_only;

static void test_drive_configuration_programming_workers(void)
{
    unsigned index;

    clear_memory(0);
    recovery_configuration_program_result = 1u;
    recovery_configuration_program_copies_primary = 1u;
    firmware_memory[0x000c86u] = 0xa0u;
    firmware_memory[0x018056u] = 0x5au;
    firmware_memory[0xffc01fu] = 1u;
    set_memory_big_endian_u32(0x156au, 0x00000200ul);
    set_memory_big_endian_u32(0x1562u, 0x12345678ul);
    for(index = 0u; index != 0x60u; ++index)
        firmware_memory[0x1620u + index] = (u8)(index ^ 0x5au);
    for(index = 0u; index != 0x40u; ++index)
        firmware_memory[0x1680u + index] = (u8)(index ^ 0xa5u);
    for(index = 0u; index != 0x100u; ++index)
        firmware_memory[0xffff00u + index] = (u8)(index + 3u);

    assert(ProgramAndVerifyDriveConfiguration(0u) == 1u);
    assert(recovery_configuration_program_call_count == 1u && recovery_configuration_program_extended_only == 0u);
    assert(firmware_memory[0x000c86u] == 0xa0u && firmware_memory[0x018056u] == 0x5au);
    assert(bit_0580 == 1u && bit_0581 == 0u);
    assert(firmware_memory[0x1700u] == 3u && firmware_memory[0x17ffu] == 2u);
    assert(ReadBigEndianU16(0x129au) == 0x01ffu && ReadBigEndianU16(0x129cu) == 0x01fau && ReadBigEndianU16(0x12a0u) == 0x88bbu);
    assert(ReadBigEndianU16(0x126au) == 0x1234u && ReadBigEndianU16(0x126cu) == 0x5678u && ReadBigEndianU16(0x126eu) == 0u && ReadBigEndianU16(0x1270u) == 0u);
    if(configuration_queue_count_only != 0u)
        return;

    clear_memory(0);
    recovery_configuration_program_result = 1u;
    firmware_memory[0x000c86u] = 0xa0u;
    firmware_memory[0x018056u] = 0x5au;
    firmware_memory[0xffc01fu] = 1u;
    firmware_memory[0x1620u] = 0x11u;
    firmware_memory[0x1680u] = 0x22u;
    set_memory_big_endian_u32(0x156au, 0x00000020ul);
    firmware_memory[0x1262u] = 0x99u;
    assert(ProgramAndVerifyDriveConfiguration(0u) == 0u);
    assert(recovery_configuration_program_call_count == 1u && firmware_memory[0x000c86u] == 0xa0u && bit_0580 == 1u && bit_0581 == 0u);
    assert(firmware_memory[0x1262u] == 0x99u);

    clear_memory(0);
    recovery_configuration_program_result = 0u;
    firmware_memory[0x000c86u] = 0xa0u;
    firmware_memory[0x018056u] = 0x5au;
    firmware_memory[0xffc01fu] = 1u;
    set_memory_big_endian_u32(0x156au, 0x00000020ul);
    assert(ProgramAndVerifyDriveConfiguration(1u) == 0u);
    assert(recovery_configuration_program_call_count == 1u && recovery_configuration_program_extended_only == 1u && firmware_memory[0x000c86u] == 0xa0u && firmware_memory[0x018056u] == 0x5au);
    assert(bit_0580 == 0u && bit_0581 == 1u);

    clear_memory(0);
    recovery_configuration_program_result = 1u;
    for(index = 0u; index != 0x60u; ++index)
        firmware_memory[0xffc000u + index] = (u8)index;
    for(index = 0x60u; index != 0xa0u; ++index)
        firmware_memory[0xffa000u + index] = (u8)index;
    set_memory_big_endian_u32(0x156au, 0x00000020ul);
    firmware_memory[0x00fae7u] = 0x5au;
    UpdateDriveConfigurationByteRangeAndProgram(0x0000fae7ul, 0x77u, 1u);
    assert(bit_0547 == 0u && recovery_configuration_program_call_count == 1u && recovery_configuration_program_extended_only == 1u);
    assert(firmware_memory[0x1697u] == 0x5au && firmware_memory[0x169eu] == 0x1fu && firmware_memory[0x169fu] == 0x31u);

    clear_memory(0);
    recovery_configuration_program_result = 0u;
    firmware_memory[0xffc01fu] = 1u;
    set_memory_big_endian_u32(0x156au, 0x00000020ul);
    UpdateDriveConfigurationByteRangeAndProgram(0x00001234ul, 0u, 0u);
    assert(firmware_memory[0x001009u] == 1u && firmware_memory[0x0012f7u] == 2u);
    assert(ReadBigEndianU16(0x0500u) == 0x00f8u && ReadBigEndianU16(0x0502u) == 0x53cfu);

    clear_memory(0);
    recovery_configuration_program_result = 1u;
    firmware_memory[0x001308u] = 1u;
    firmware_memory[0x00130au] = 0x1fu;
    firmware_memory[0x001009u] = 0x44u;
    firmware_memory[0x00fad7u] = 0x08u;
    set_memory_big_endian_u32(0x156au, 0x00000020ul);
    FUN_RAM_f8f08b();
    assert(firmware_memory[0x00fae7u] == 0x66u && recovery_configuration_program_call_count == 1u);

    clear_memory(0);
    recovery_configuration_program_result = 1u;
    firmware_memory[0x00fbf1u] = 1u;
    firmware_memory[0x00fae7u] = 0x38u;
    set_memory_big_endian_u32(0x156au, 0x00000020ul);
    PersistControllerOperatingStatusByte();
    assert(recovery_configuration_program_call_count == 1u && firmware_memory[0x1692u] == 0x38u);

    clear_memory(0xa5u);
    firmware_memory[0x00fae7u] = 4u;
    PersistControllerOperatingStatusByte();
    assert(write_count == 0u && recovery_configuration_program_call_count == 0u);
    clear_memory(0xa5u);
    firmware_memory[0x00fbf1u] = 1u;
    firmware_memory[0x00fae7u] = 0x39u;
    PersistControllerOperatingStatusByte();
    assert(write_count == 0u && recovery_configuration_program_call_count == 0u);

    clear_memory(0);
    recovery_configuration_program_result = 1u;
    firmware_memory[0x001308u] = 1u;
    firmware_memory[0x00130au] = 0x20u;
    firmware_memory[0x001009u] = 0x44u;
    set_memory_big_endian_u32(0x156au, 0x00000020ul);
    FUN_RAM_f8f08b();
    assert(firmware_memory[0x00fae7u] == 0x74u && recovery_configuration_program_call_count == 1u);

    clear_memory(0xa5u);
    firmware_memory[0x001308u] = 0u;
    FUN_RAM_f8f08b();
    assert(write_count == 0u && recovery_configuration_program_call_count == 0u);
}

static void test_controller_buffer_zero_window_countdown(void)
{
    unsigned index;

    clear_memory(0xa5u);
    firmware_memory[0x1008u] = 1u;
    FUN_RAM_f93a5e();
    assert(read_count == 1u && write_count == 0u);

    clear_memory(0xa5u);
    firmware_memory[0x1008u] = 0u;
    firmware_memory[0x0f25u] = 2u;
    FUN_RAM_f93a5e();
    assert(read_count == 2u && write_count == 0u);

    clear_memory(0);
    set_memory_big_endian_u32(0x126eu, 0x00120000ul);
    firmware_memory[0x1008u] = 0u;
    firmware_memory[0x0f25u] = 1u;
    firmware_memory[0x0c3du] = 5u;
    firmware_memory[0x0f24u] = 2u;
    sfr_memory[0xa8u] = 0x80u;
    bit_0547 = 1u;
    for(index = 0u; index != 4u; ++index)
        firmware_memory[0x00120820ul + index] = 0u;
    FUN_RAM_f93a5e();
    assert(firmware_memory[0x0f24u] == 1u && bit_0547 == 1u);
    assert(sfr_read_count == 8u && sfr_write_count == 8u && sfr_read_trace[0] == 0xa8u && sfr_read_trace[1] == 0xa9u && sfr_write_trace[0] == 0xa8u && sfr_write_trace[1] == 0xa9u);

    clear_memory(0);
    set_memory_big_endian_u32(0x126eu, 0x00120000ul);
    firmware_memory[0x0f25u] = 1u;
    firmware_memory[0x0c3du] = 0xffu;
    firmware_memory[0x0f24u] = 0u;
    firmware_memory[0x00120822ul] = 1u;
    FUN_RAM_f93a5e();
    assert(firmware_memory[0x0f24u] == 0u);

    clear_memory(0);
    set_memory_big_endian_u32(0x126eu, 0x0012fff0ul);
    firmware_memory[0x0f25u] = 1u;
    firmware_memory[0x0c3du] = 4u;
    firmware_memory[0x0f24u] = 2u;
    for(index = 0u; index != 4u; ++index)
        firmware_memory[0x00120800ul + index] = 0u;
    FUN_RAM_f93a5e();
    assert(firmware_memory[0x0f24u] == 1u);
}

static void test_write_packet_progress_frame_selector(void)
{
    unsigned write_type;

    for(write_type = 0u; write_type != 256u; ++write_type)
    {
        clear_memory(0);
        firmware_memory[0x0c44u] = (u8)write_type;
        set_memory_big_endian_u32(0xdd4du, 0x12345678ul);
        set_memory_big_endian_u32(0xdd65u, 0x87654321ul);
        if(write_type == 0u || write_type == 1u)
            assert(FUN_RAM_fbc6b0() == (s32)0x123455e2ul);
        else if(write_type == 3u)
            assert(FUN_RAM_fbc6b0() == (s32)0x8765428bul);
        else
            assert(FUN_RAM_fbc6b0() == 0);
    }

    clear_memory(0);
    firmware_memory[0x0c44u] = 0u;
    firmware_memory[0xdd56u] = 1u;
    set_memory_big_endian_u32(0xdd4du, 0x00000190ul);
    set_memory_big_endian_u32(0xdd57u, 0u);
    set_memory_big_endian_u32(0xdd5bu, 0u);
    set_memory_big_endian_u32(0xdd45u, 0u);
    set_memory_big_endian_u32(0xdd4du, 0x00000190ul);
    firmware_memory[0x0c49u] = 0u;
    firmware_memory[0x0c4au] = 0u;
    firmware_memory[0x0c4bu] = 0u;
    firmware_memory[0x0c4cu] = 1u;
    assert(FUN_RAM_fbc6b0() == (s32)((u32)ComputeWorkingTrackPacketProgressFramePosition(0u) - 150ul));
}

static void test_fixed_packet_logical_address_mapping(void)
{
    static const u32 packet_sizes[] = { 1ul, 2ul, 7ul, 10ul, 0x100ul, 0xfffful };
    static const u32 offsets[] = { 0ul, 1ul, 6ul, 7ul, 9ul, 10ul, 0xfful, 0x100ul, 0x7ffffffful, 0xfffffffeul, 0xfffffffful };
    static const u32 starts[] = { 0ul, 150ul, 0x12345678ul, 0xffffff80ul };
    unsigned start_index;
    unsigned packet_index;
    unsigned offset_index;

    clear_memory(0);
    set_memory_big_endian_u32(0xdd3du, 0x12345678ul);
    set_memory_big_endian_u32(0xdd57u, 10ul);
    assert(MapFixedPacketLogicalToPhysicalAddress(0u) == 0u);
    assert(MapFixedPacketLogicalToPhysicalAddress(0xfffffffful) == 0xfffffffful);
    assert(write_count == 0u);

    for(start_index = 0u; start_index < sizeof(starts) / sizeof(starts[0]); ++start_index)
    {
        for(packet_index = 0u; packet_index < sizeof(packet_sizes) / sizeof(packet_sizes[0]); ++packet_index)
        {
            u32 start_frame = starts[start_index];
            u32 packet_size = packet_sizes[packet_index];
            u32 packet_start = start_frame - 150ul;

            for(offset_index = 0u; offset_index < sizeof(offsets) / sizeof(offsets[0]); ++offset_index)
            {
                u32 offset = offsets[offset_index];
                u32 completed_packets = offset / packet_size;
                u32 expected = packet_start + completed_packets * (packet_size + 7ul) + (offset % packet_size);

                clear_memory(0);
                bit_000b = 1u;
                firmware_memory[0x0c46u] = 2u;
                set_memory_big_endian_u32(0xdd3du, start_frame);
                set_memory_big_endian_u32(0xdd57u, packet_size);
                assert(MapFixedPacketLogicalToPhysicalAddress(packet_start + offset) == expected);
                assert(write_count == 0u && read_count == 26u);
                assert(read_trace[0] == 0x0c44ul && read_trace[1] == 0x0c46ul && read_trace[2] == 0xdd3dul && read_trace[5] == 0xdd40ul && read_trace[6] == 0xdd57ul && read_trace[9] == 0xdd5aul
                       && read_trace[10] == 0xdd57ul && read_trace[13] == 0xdd5aul && read_trace[14] == 0xdd3dul && read_trace[17] == 0xdd40ul && read_trace[18] == 0xdd3dul
                       && read_trace[21] == 0xdd40ul && read_trace[22] == 0xdd57ul && read_trace[25] == 0xdd5aul);
            }
        }
    }
}

