static void test_vendor_f5_window_selectors(void)
{
    static void (*const selectors[])(fw_addr_t, fw_addr_t) = { SelectVendorF5Mode1BufferWindow, SelectVendorF5Mode6BufferWindow, SelectVendorF5Mode7BufferWindow, SelectVendorF5Mode5BufferWindow };
    static const u16 sources[] = { 0xfb6au, 0xfb7au, 0x116eu, 0xdd2fu };
    static const u16 lengths[] = { 12u, 18u, 92u, 0u };
    static const fw_addr_t outputs[][2] = {
        { 0x2000ul,   0x2100ul   },
        { 0x12fffful, 0x34fffful },
        { 0xfffffeul, 0xfffffful },
        { 0x2000ul,   0x2000ul   },
        { 0x2000ul,   0x2001ul   },
        { 0x2000ul,   0x2002ul   },
        { 0xdd7dul,   0x2200ul   },
        { 0xdd7ful,   0x2200ul   }
    };
    unsigned mode, position, high_index, index, later, count, pointer_start;
    fw_addr_t expected_addresses[8];
    u8 expected_values[8];

    clear_memory(0xa5u);
    for(mode = 0; mode < 4u; ++mode)
    {
        for(position = 0; position < 8u; ++position)
        {
            for(high_index = 0; high_index < 256u; ++high_index)
            {
                fw_addr_t pointer = outputs[position][0];
                fw_addr_t length = outputs[position][1];
                u8 observed_index = (u8)high_index;
                u16 expected_length = lengths[mode];
                count = 0u;
                if(mode == 2u)
                {
                    expected_addresses[count] = length;
                    expected_values[count++] = 0u;
                    expected_addresses[count] = (length + 1ul) & 0xfffffful;
                    expected_values[count++] = 0u;
                }
                pointer_start = count;
                expected_addresses[count] = (pointer + 2ul) & 0xfffffful;
                expected_values[count++] = (u8)(sources[mode] >> 8);
                expected_addresses[count] = (pointer + 3ul) & 0xfffffful;
                expected_values[count++] = (u8)sources[mode];
                expected_addresses[count] = pointer;
                expected_values[count++] = 0u;
                expected_addresses[count] = (pointer + 1ul) & 0xfffffful;
                expected_values[count++] = 0u;
                if(mode == 3u)
                {
                    for(index = 0; index < count; ++index)
                        if(expected_addresses[index] == 0xdd7ful)
                            observed_index = expected_values[index];
                    expected_length = (u16)(8u * (u16)observed_index + 63u);
                }
                expected_addresses[count] = length;
                expected_values[count++] = (u8)(expected_length >> 8);
                expected_addresses[count] = (length + 1ul) & 0xfffffful;
                expected_values[count++] = (u8)expected_length;
                for(index = 0; index < count; ++index)
                    firmware_memory[expected_addresses[index]] = 0xa5u;
                firmware_memory[0xdd7f] = (u8)high_index;
                read_count = write_count = sfr_read_count = sfr_write_count = 0u;
                selectors[mode](pointer, length);
                assert(write_count == count);
                assert(read_count == (mode == 3u ? 1u : 0u));
                if(mode == 3u)
                    assert(read_trace[0] == 0xdd7ful);
                for(index = 0; index < count; ++index)
                {
                    assert(write_trace[index] == expected_addresses[index]);
                    assert(write_values[index] == expected_values[index]);
                    assert(write_read_counts[index] == (mode == 3u && index >= pointer_start + 4u ? 1u : 0u));
                    for(later = index + 1u; later < count; ++later)
                        if(expected_addresses[later] == expected_addresses[index])
                            break;
                    if(later == count)
                        assert(firmware_memory[expected_addresses[index]] == expected_values[index]);
                }
                assert(sfr_read_count == 0u && sfr_write_count == 0u);
            }
        }
    }
}

static void assert_reviewed_sense_writes(u8 key, u8 asc, u8 ascq)
{
    static const fw_addr_t addresses[] = { 0xb18ul, 0xb1aul, 0xb24ul, 0xb25ul, 0xb1bul, 0xb1cul, 0xb1dul, 0xb1eul };
    u8 values[8] = { 0x70u, key, asc, ascq, 0u, 0u, 0u, 0u };
    unsigned index;
    assert(write_count == 8u);
    for(index = 0; index < 8u; ++index)
    {
        assert(write_trace[index] == addresses[index]);
        assert(write_values[index] == values[index]);
    }
}

static void test_write_validation_and_simple_leaves(void)
{
    unsigned state, value, selector;

    clear_memory(0xa5u);
    for(value = 0; value < 256u; ++value)
    {
        int expected = value < 128u ? (int)value : 128 - (int)value;
        if(value == 255u)
            expected = 0;
        assert(DecodeControllerEncodedSignedOffset((u8)value) == expected);
    }
    assert(read_count == 0u && write_count == 0u);
    SelectMainFirmwareInterruptHandlers();
    assert(read_count == 0u && write_count == 1u && write_trace[0] == 0xfcul);
    assert(write_values[0] == 1u && sfr_read_count == 0u && sfr_write_count == 0u);
    write_count = 0u;
    HandleScsiOpcodeF7();
    assert_reviewed_sense_writes(0u, 0u, 0u);
    write_count = 0u;
    HandleScsiOpcodeF8();
    assert_reviewed_sense_writes(0u, 0u, 0u);

    for(selector = 0; selector < 2u; ++selector)
    {
        for(state = 0; state < 256u; ++state)
        {
            for(value = 0; value < 256u; ++value)
            {
                u8 result;
                u8 rejected = (u8)(state == 2u && (selector == 0u ? value > 2u : (value & 3u) != 0u));
                firmware_memory[0x1008u] = (u8)state;
                firmware_memory[0xfb88u] = firmware_memory[0xfb89u] = (u8)value;
                read_count = write_count = 0u;
                result = selector == 0u ? ValidateMediaState2ControllerCodeForWrite() : ValidateMediaState2ControllerFlagsForWrite();
                assert(result == (u8)!rejected);
                assert(read_count == (state == 2u ? 2u : 1u));
                assert(read_trace[0] == 0x1008ul);
                if(state == 2u)
                    assert(read_trace[1] == (selector == 0u ? 0xfb88ul : 0xfb89ul));
                if(rejected != 0u)
                {
                    assert_reviewed_sense_writes(2u, 0x30u, 5u);
                    assert(write_read_counts[0] == 2u);
                }
                else
                {
                    assert(write_count == 0u);
                }
            }
        }
    }
}

static void test_stop_play_scan_command(void)
{
    /* Canonical RAM:ff8d8a descriptor: count, unused byte, nine masks. */
    static const u8 descriptor[] = { 10u, 0u, 0x1fu, 0xffu, 0xffu, 0xffu, 0xffu, 0xffu, 0xffu, 0xffu, 0xfcu };
    static const u8 flags[] = { 0u, 4u, 0xffu, 0x80u };
    unsigned field, value, flag_case, index;
    clear_memory(0u);
    memcpy(firmware_memory + 0xff8d8aul, descriptor, sizeof(descriptor));
    for(field = 1u; field < 10u; ++field)
        for(value = 0u; value < 256u; ++value)
            for(flag_case = 0u; flag_case < 4u; ++flag_case)
            {
                unsigned rejected = (value & descriptor[field + 1u]) != 0u;
                unsigned reset = !rejected && (flags[flag_case] & 4u) != 0u;
                unsigned prefix = reset ? 43u : 0u;
                memset(firmware_memory + 0xb0bul, 0, 9u);
                firmware_memory[0xb0aul + field] = (u8)value;
                firmware_memory[0xfbaul] = flags[flag_case];
                firmware_memory[0xfaful] = 0x55u;
                set_memory_big_endian_u16(0x156aul, 32u);
                bit_0014 = bit_0015 = bit_000e = bit_0581 = 1u;
                bit_0580 = 0u;
                read_count = write_count = sfr_read_count = sfr_write_count = 0u;
                HandleStopPlayScanCommand();
                assert(write_count == prefix + 8u);
                assert(firmware_memory[0xb18ul] == 0x70u);
                assert(firmware_memory[0xb1aul] == (rejected ? 5u : 0u));
                assert(firmware_memory[0xb24ul] == (rejected ? 0x24u : 0u));
                assert(firmware_memory[0xb25ul] == 0u);
                assert(read_trace[0] == 0xff8d8aul);
                for(index = 1u; index <= (rejected ? field : 9u); ++index)
                {
                    assert(read_trace[2u * index - 1u] == 0xb0aul + index);
                    assert(read_trace[2u * index] == 0xff8d8bul + index);
                }
                assert(write_trace[prefix] == 0xb18ul);
                if(rejected)
                    assert(read_count == 1u + 2u * field);
                if(reset)
                {
                    assert(firmware_memory[0xfbaul] == (flags[flag_case] & 0xe3u));
                    assert(firmware_memory[0xfaful] == 0u);
                    assert(bit_000e == 0u && bit_0580 == 1u && bit_0581 == 0u);
                    assert(get_memory_big_endian_u32(0x500ul) == 0x00f85d74ul);
                    assert(get_memory_big_endian_u32(0x700ul) == 0x00f84a00ul);
                    assert(write_trace[0] == 0xfbaul && write_trace[42] == 0x1169ul);
                }
                else
                {
                    assert(firmware_memory[0xfbaul] == flags[flag_case]);
                    assert(firmware_memory[0xfaful] == 0x55u);
                    assert(bit_000e == 1u && bit_0580 == 0u && bit_0581 == 1u);
                }
                assert(sfr_read_count == 0u && sfr_write_count == 0u);
            }
}

static void test_controller_request_flag_11e5_bit1(void)
{
    unsigned request, state;

    clear_memory(0u);
    for(request = 0u; request < 256u; ++request)
        for(state = 0u; state < 256u; ++state)
        {
            firmware_memory[0x11e5ul] = (u8)request;
            firmware_memory[0x11d7ul] = (u8)state;
            read_count = write_count = sfr_read_count = sfr_write_count = 0u;
            ServiceControllerRequestFlag11E5Bit1();
            if((request & 2u) == 0u)
            {
                assert(read_count == 1u && write_count == 0u);
                assert(firmware_memory[0x11e5ul] == request);
                assert(firmware_memory[0x11d7ul] == state);
            }
            else
            {
                assert(read_count == 4u && write_count == 2u);
                assert(read_trace[0] == 0x11e5ul && read_trace[1] == 0x11e5ul);
                assert(read_trace[2] == 0x11d7ul && read_trace[3] == 0x11d7ul);
                assert(write_trace[0] == 0x11e5ul && write_values[0] == (request & 0xfdu));
                assert(write_trace[1] == 0x11d7ul && write_values[1] == ((state & 0x40u) == 0u ? (state | 0x40u) : (state & 0xbfu)));
                assert(write_read_counts[0] == 2u && write_read_counts[1] == 4u);
            }
            assert(sfr_read_count == 0u && sfr_write_count == 0u);
        }

    firmware_memory[0x11e5ul] = 2u;
    firmware_memory[0x11d7ul] = 0u;
    write_mutation_enabled = 1u;
    write_mutation_trigger = 0x11e5ul;
    write_mutation_target = 0x11d7ul;
    write_mutation_value = 0x40u;
    read_count = write_count = 0u;
    ServiceControllerRequestFlag11E5Bit1();
    assert(firmware_memory[0x11d7ul] == 0u);
}

static void test_fail_if_read_measurement_preparation_active(void)
{
    unsigned preparation_status;

    clear_memory(0u);
    for(preparation_status = 0u; preparation_status < 256u; ++preparation_status)
    {
        firmware_memory[0xfba0ul] = (u8)preparation_status;
        firmware_memory[0x1490ul] = 1u;
        firmware_memory[0x1281ul] = 1u;
        firmware_memory[0x1598ul] = 0x12u;
        firmware_memory[0x1599ul] = 0x34u;
        firmware_memory[0x159aul] = 0x56u;
        firmware_memory[0x159bul] = 0x78u;
        firmware_memory[0xb18ul] = 0x55u;
        firmware_memory[0xb1aul] = 0xa5u;
        firmware_memory[0xb24ul] = 0x5au;
        firmware_memory[0xb25ul] = 0x5au;
        read_count = write_count = sfr_read_count = sfr_write_count = 0u;
        assert(FailIfReadMeasurementPreparationActive() == (preparation_status != 0u));
        assert(read_trace[0] == 0xfba0ul);
        if(preparation_status == 0u)
        {
            assert(read_count == 1u && write_count == 0u);
            assert(firmware_memory[0xb18ul] == 0x55u);
        }
        else
        {
            assert(read_count > 1u && write_count >= 13u);
            assert((firmware_memory[0xb18ul] & 0x80u) != 0u);
            assert(get_memory_big_endian_u32(0xb1bul) == 0x12345678ul);
        }
        assert(sfr_read_count == 0u && sfr_write_count == 0u);
    }
}

static void test_rezero_unit_command(void)
{
    /* Canonical RAM:ff8dec descriptor: count, unused byte, five masks. */
    static const u8 descriptor[] = { 6u, 0u, 0x1fu, 0xffu, 0xffu, 0xffu, 0xfcu };
    unsigned field, value, index;

    clear_memory(0u);
    memcpy(firmware_memory + 0xff8decul, descriptor, sizeof(descriptor));
    for(field = 1u; field < 6u; ++field)
        for(value = 0u; value < 256u; ++value)
        {
            unsigned rejected = (value & descriptor[field + 1u]) != 0u;
            memset(firmware_memory + 0xb0bul, 0, 5u);
            firmware_memory[0xb0aul + field] = (u8)value;
            firmware_memory[0xb18ul] = 0x55u;
            firmware_memory[0xb1aul] = 0xa5u;
            firmware_memory[0xb24ul] = 0x5au;
            firmware_memory[0xb25ul] = 0x5au;
            yield_coroutine0_auto_complete_after = rejected ? 0u : 1u;
            yield_coroutine0_auto_complete_result = 0u;
            yield_coroutine0_count = 0u;
            read_count = write_count = sfr_read_count = sfr_write_count = 0u;
            HandleRezeroUnitCommand();
            assert(read_trace[0] == 0xff8decul);
            if(rejected)
            {
                assert(read_count == 1u + 2u * field && write_count == 8u);
                assert(firmware_memory[0xb18ul] == 0x70u && firmware_memory[0xb1aul] == 5u);
                assert(firmware_memory[0xb24ul] == 0x24u && firmware_memory[0xb25ul] == 0u);
            }
            else
            {
                assert(get_memory_big_endian_u32(0xc8eul) == 0x96ul);
                assert(firmware_memory[0xc8cul] == 0u);
                assert(yield_coroutine0_count == 1u);
                assert(bit_0580 == 1u && bit_0581 == 0u);
                assert(firmware_memory[0xb1aul] == 0u && firmware_memory[0xb24ul] == 0u);
                assert(write_trace[0] == 0xc8cul && write_trace[1] == 0xc8eul);
            }
            for(index = 1u; index <= (rejected ? field : 5u); ++index)
            {
                assert(read_trace[2u * index - 1u] == 0xb0aul + index);
                assert(read_trace[2u * index] == 0xff8dedul + index);
            }
            assert(sfr_read_count == 0u && sfr_write_count == 0u);
        }
}

static void test_handle_receive_diagnostic_results_command(void)
{
    static const u8 descriptor[] = { 6u, 0u, 0x1fu, 0xffu, 0u, 0u, 0xfcu };
    static const u8 payload_tail[] = { 0x11u, 0x22u, 0x33u, 0x44u, 0x55u, 0x66u };
    unsigned index;

    clear_memory(0u);
    memcpy(firmware_memory + 0xff8ddeul, descriptor, sizeof(descriptor));
    firmware_memory[0x0b0bul] = 1u;
    HandleReceiveDiagnosticResultsCommand();
    assert(read_count == 3u && read_trace[0] == 0xff8ddeul && read_trace[1] == 0x0b0bul && read_trace[2] == 0xff8de0ul);
    assert(write_count == 8u && write_trace[0] == 0x0b18ul && firmware_memory[0x0b1aul] == 5u && firmware_memory[0x0b24ul] == 0x24u);
    assert(firmware_memory[0xdcbdul] == 0u && firmware_memory[0xdcbeul] == 0u);

    clear_memory(0u);
    memcpy(firmware_memory + 0xff8ddeul, descriptor, sizeof(descriptor));
    firmware_memory[0x0b0eul] = 8u;
    HandleReceiveDiagnosticResultsCommand();
    assert(read_count == 13u && write_count == 10u);
    assert(write_trace[0] == 0xdcbdul && write_values[0] == 0u && write_trace[1] == 0xdcbeul && write_values[1] == 6u);
    assert(write_trace[2] == 0x0b18ul && firmware_memory[0x0b1aul] == 5u && firmware_memory[0x0b24ul] == 0x24u);

    clear_memory(0u);
    memcpy(firmware_memory + 0xff8ddeul, descriptor, sizeof(descriptor));
    firmware_memory[0x0b0eul] = 9u;
    memcpy(firmware_memory + 0xdcbful, payload_tail, sizeof(payload_tail));
    set_memory_big_endian_u32(0x155au, 0x200ul);
    firmware_memory[0x0b18ul] = 0xa5u;
    firmware_memory[0x0b1aul] = 0x5au;
    controller_data_in_transfer_phase = 12u;
    controller_data_in_transfer_call_count = 0u;
    HandleReceiveDiagnosticResultsCommand();
    assert(controller_data_in_transfer_call_count == 1u && controller_data_in_transfer_length == 8ul && controller_data_in_transfer_offset == 0x200ul);
    assert(read_count == 30u && write_count == 10u);
    assert(firmware_memory[0x0b18ul] == 0xa5u && firmware_memory[0x0b1aul] == 0x5au);
    assert(firmware_memory[0x100200ul] == 0u && firmware_memory[0x100201ul] == 6u);
    for(index = 0u; index < sizeof(payload_tail); ++index)
        assert(firmware_memory[0x100202ul + index] == payload_tail[index]);

    clear_memory(0u);
    memcpy(firmware_memory + 0xff8ddeul, descriptor, sizeof(descriptor));
    firmware_memory[0x0b0dul] = 1u;
    controller_data_in_transfer_call_count = 0u;
    HandleReceiveDiagnosticResultsCommand();
    assert(controller_data_in_transfer_call_count == 0u);
    assert(read_count == 13u && write_count == 10u);
    assert(firmware_memory[0x0b18ul] == 0x70u && firmware_memory[0x0b1aul] == 0u && firmware_memory[0x0b24ul] == 0u && firmware_memory[0x0b25ul] == 0u);

    clear_memory(0u);
    memcpy(firmware_memory + 0xff8ddeul, descriptor, sizeof(descriptor));
    firmware_memory[0x0b0eul] = 9u;
    set_memory_big_endian_u32(0x155au, 0x300ul);
    controller_data_in_transfer_phase = 13u;
    controller_data_in_transfer_call_count = 0u;
    HandleReceiveDiagnosticResultsCommand();
    assert(controller_data_in_transfer_call_count == 1u && controller_data_in_transfer_length == 8ul);
    assert(read_count == 30u && write_count == 18u);
    assert(firmware_memory[0x0b18ul] == 0x70u && firmware_memory[0x0b1aul] == 0u);
}

static void set_status_mapping_entry(u8 status, u8 sense_key, u16 asc_ascq)
{
    fw_addr_t asc_address = 0xf84468ul + ((fw_addr_t)status << 1);

    firmware_memory[0xf84454ul + status] = sense_key;
    firmware_memory[asc_address] = (u8)(asc_ascq >> 8);
    firmware_memory[asc_address + 1u] = (u8)asc_ascq;
}

