static void test_dispatch_vendor_f3_read_acquisition_mode(void)
{
    clear_memory(0u);
    firmware_memory[0x0faeul] = 3u;
    set_status_mapping_entry(3u, 4u, 0x4000u);
    DispatchVendorF3ReadAcquisitionMode();
    assert(read_count == 5u && read_trace[0] == 0x0faeul && read_trace[1] == 0x0faeul);
    assert(firmware_memory[0x0b1aul] == 4u && firmware_memory[0x0b24ul] == 0x40u && firmware_memory[0x0b25ul] == 0u);
    assert(vendor_f3_alternate_acquisition_call_count == 0u && vendor_f3_measurement_acquisition_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0c85ul] = 0u;
    DispatchVendorF3ReadAcquisitionMode();
    assert(read_count == 2u && read_trace[0] == 0x0faeul && read_trace[1] == 0x0c85ul);
    assert(firmware_memory[0x0b1aul] == 2u && firmware_memory[0x0b24ul] == 0x04u && firmware_memory[0x0b25ul] == 0x01u);

    clear_memory(0u);
    firmware_memory[0x0c85ul] = 0x02u;
    firmware_memory[0x0b0cul] = 0x0fu;
    DispatchVendorF3ReadAcquisitionMode();
    assert(read_count == 4u && read_trace[2] == 0x0b0cul && read_trace[3] == 0x131aul);
    assert(firmware_memory[0x0b1aul] == 5u && firmware_memory[0x0b24ul] == 0x24u && firmware_memory[0x0b25ul] == 0u);

    clear_memory(0u);
    firmware_memory[0x0c85ul] = 0x02u;
    firmware_memory[0x0b0cul] = 0x0fu;
    firmware_memory[0x131aul] = 0x80u;
    DispatchVendorF3ReadAcquisitionMode();
    assert(read_count == 4u && vendor_f3_alternate_acquisition_call_count == 1u && vendor_f3_measurement_acquisition_call_count == 0u);
    assert(write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0c85ul] = 0x02u;
    firmware_memory[0x0b0cul] = 0x10u;
    DispatchVendorF3ReadAcquisitionMode();
    assert(read_count == 4u && read_trace[2] == 0x0b0cul && read_trace[3] == 0xf7c01ful);
    assert(firmware_memory[0x0b1aul] == 5u && vendor_f3_alternate_acquisition_call_count == 0u && vendor_f3_measurement_acquisition_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0c85ul] = 0x02u;
    firmware_memory[0x0b0cul] = 0xf0u;
    firmware_memory[0xf7c01ful] = 1u;
    DispatchVendorF3ReadAcquisitionMode();
    assert(read_count == 4u && vendor_f3_alternate_acquisition_call_count == 0u && vendor_f3_measurement_acquisition_call_count == 1u);
    assert(write_count == 0u);
}

