    trace_base = read_count - 8u;
    assert(read_trace[trace_base] == 0x1235ul && read_trace[trace_base + 1u] == 0x1236ul && read_trace[trace_base + 2u] == 0x1237ul && read_trace[trace_base + 3u] == 0x1238ul
           && read_trace[trace_base + 4u] == 0x0c8eul && read_trace[trace_base + 5u] == 0x0c8ful && read_trace[trace_base + 6u] == 0x0c90ul && read_trace[trace_base + 7u] == 0x0c91ul);

    clear_memory(0u);
    firmware_memory[0x0c8cul] = 1u;
    firmware_memory[0x0c85ul] = 0x10u;
    firmware_memory[0x0fbcul] = 2u;
    set_memory_big_endian_u32(0x0c8eu, 100ul);
    set_memory_big_endian_u32(0x1235u, 90ul);
