    set_memory_big_endian_u32(0x155au, 0x12fffeul);
    firmware_memory[0x22fffeul] = 0x11u;
    firmware_memory[0x22fffful] = 0x22u;
    firmware_memory[0x230000ul] = 0x33u;
    firmware_memory[0x230001ul] = 0x44u;
    controller_data_out_transfer_phase = 13u;
    controller_data_out_transfer_call_count = 0u;
