    assert(firmware_memory[0x0700ul] == 0u && firmware_memory[0x0701ul] == 0xf9u && firmware_memory[0x0702ul] == 0u && firmware_memory[0x0703ul] == 0u);
    assert(get_memory_big_endian_u32(0x1166ul) == 0x00000707ul);
    assert(firmware_memory[0x127eul] == 1u && firmware_memory[0x1591ul] == 1u && firmware_memory[0x0c2aul] == 2u);
