static void test_finalize_media_coroutine_state2(void)
{
    unsigned value;

    for(value = 0u; value < 256u; ++value)
    {
        clear_memory(0u);
        firmware_memory[0x1306ul] = (u8)value;
        firmware_memory[0x1303ul] = (u8)value;
        firmware_memory[0x103aul] = (u8)value;
        finalize_command0e_capture_count = 0u;
        finalize_command0e_capture_mutates_state = 0u;
        read_count = write_count = 0u;
        FinalizeMediaCoroutineState2();
        assert(finalize_command0e_capture_count == 1u);
        assert(firmware_memory[0x1306ul] == (u8)(((u8)value & 0x7fu) | 0x08u));
        assert(firmware_memory[0x1303ul] == ((u8)value & 0xfdu));
        assert(firmware_memory[0x103aul] == ((u8)value & 0xdfu));
        assert(read_count == 4u && write_count == 4u);
        assert(read_trace[0] == 0x1306ul && read_trace[1] == 0x1303ul && read_trace[2] == 0x103aul && read_trace[3] == 0x1306ul);
        assert(write_trace[0] == 0x1306ul && write_trace[1] == 0x1303ul && write_trace[2] == 0x103aul && write_trace[3] == 0x1306ul);
    }

    clear_memory(0u);
    finalize_command0e_capture_count = 0u;
    finalize_command0e_capture_mutates_state = 1u;
    FinalizeMediaCoroutineState2();
    assert(finalize_command0e_capture_count == 1u);
    assert(firmware_memory[0x1306ul] == 0x7fu && firmware_memory[0x1303ul] == 0xfdu && firmware_memory[0x103aul] == 0xdfu);
    finalize_command0e_capture_mutates_state = 0u;
}

static void test_finalize_media_coroutine_state5(void)
{
    unsigned snapshot_valid, strobe_suppressed;

    for(snapshot_valid = 0u; snapshot_valid < 2u; ++snapshot_valid)
        for(strobe_suppressed = 0u; strobe_suppressed < 2u; ++strobe_suppressed)
        {
            clear_memory(0u);
            firmware_memory[0x1039ul] = 0xffu;
            firmware_memory[0x1303ul] = 0xffu;
            firmware_memory[0x1306ul] = 0xf0u;
            firmware_memory[0x1302ul] = strobe_suppressed ? 0x08u : 0u;
            firmware_memory[0x0e4ful] = 0x52u;
            firmware_memory[0x0e50ul] = 0xa5u;
            firmware_memory[0x18015ul] = 0x20u;
            firmware_memory[0x18080ul] = 0xa5u;
            firmware_memory[0x1806aul] = 0xa5u;
            sfr_memory[0xe3u] = 0xffu;
            bit_0032 = (u8)snapshot_valid;
            bit_0036 = 1u;
            read_count = write_count = 0u;
            FinalizeMediaCoroutineState5();
            assert(firmware_memory[0x1039ul] == 0x5fu);
            assert(firmware_memory[0x1303ul] == 0x7fu);
            assert(firmware_memory[0x1306ul] == 0xf8u);
            assert(firmware_memory[0x0e50ul] == (snapshot_valid ? 0x52u : 0xa5u));
            assert(firmware_memory[0x18080ul] == (strobe_suppressed ? 0xa5u : 0u));
            assert(firmware_memory[0x0e44ul] == 1u);
            assert(bit_0036 == 0u);
            assert(rxdat_bit3_clear_call_count == 1u && sfr_memory[0xe3u] == 0xf7u);
            assert(firmware_memory[0x1806aul] == 0u);
            assert(read_trace[0] == 0x1039ul && read_trace[1] == 0x1303ul && read_trace[2] == 0x1039ul);
            assert(write_trace[0] == 0x1039ul && write_trace[1] == 0x1303ul && write_trace[2] == 0x1039ul);
            assert(write_trace[write_count - 1u] == 0x1806aul);
        }
}

