    assert(firmware_memory[0x1221ul] == 0xffu && firmware_memory[0x1222ul] == 0xffu && firmware_memory[0x1223ul] == 0xffu && firmware_memory[0x121ful] == 0xffu && firmware_memory[0x1220ul] == 0xffu);
    assert(firmware_memory[0x1229ul] == 0u && controller_word0251_sweep_tick_count == 0u);
