    firmware_memory[0x1223ul] = 2u;
    firmware_memory[0x121ful] = 0x80u;
    firmware_memory[0x1220ul] = 0x7fu;
    firmware_memory[0x1301ul] = 0x04u;
    firmware_memory[0x1308ul] = 1u;
    firmware_memory[0x130aul] = 5u;
    firmware_memory[0x1225ul] = 1u;
    read_count = write_count = 0u;
