    assert(get_memory_big_endian_u32(0x11f8ul) == 1ul && get_memory_big_endian_u32(0x0fb0ul) == 0xfffffffful && get_memory_big_endian_u32(0x11fcul) == 0xfffffffeul);
    assert(firmware_memory[0x1221ul] == 0u && firmware_memory[0x1222ul] == 0xffu && firmware_memory[0x1223ul] == 1u && firmware_memory[0x121ful] == 0x7fu && firmware_memory[0x1220ul] == 0x7eu);
    assert(firmware_memory[0x1229ul] == 1u);
