static void test_configure_pickup_move_controller_for_distance(void)
{
    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    set_memory_big_endian_u16(0xfc2bul, 5u);
    firmware_memory[0xfc2dul] = 0xfeu;
    firmware_memory[0xfc2eul] = 1u;
    firmware_memory[0x0e43ul] = 4u;
    write_count = 0u;
    ConfigurePickupMoveControllerForDistance(5u, 0xfeu);
    assert(write_count == 1u && write_trace[0] == 0x180e2ul && write_values[0] == 0x52u);

    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    set_memory_big_endian_u16(0xfc2bul, 2u);
    write_count = 0u;
    ConfigurePickupMoveControllerForDistance(1u, 1u);
    assert(write_count == 6u);
    assert(write_trace[0] == 0x180e0ul && write_values[0] == 0x60u);
    assert(write_trace[1] == 0x180eeul && write_values[1] == 0x01u);
    assert(write_trace[2] == 0x180eful && write_values[2] == 0x81u);
    assert(write_trace[3] == 0x180daul && write_values[3] == 0x01u);
    assert(write_trace[4] == 0x180e3ul && write_values[4] == 0xacu);
    assert(write_trace[5] == 0x180e2ul && write_values[5] == 0x52u);

    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    set_memory_big_endian_u16(0xfc2bul, 0x1234u);
    firmware_memory[0xfc2dul] = 0u;
    firmware_memory[0xfc2eul] = 0u;
    firmware_memory[0x0e43ul] = 3u;
    write_count = 0u;
    ConfigurePickupMoveControllerForDistance(0x1234u, 1u);
    assert(write_count == 2u);
    assert(write_trace[0] == 0x180eful && write_values[0] == 0xb4u);
    assert(write_trace[1] == 0x180e2ul && write_values[1] == 0x52u);

    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    set_memory_big_endian_u16(0xfc2bul, 10u);
    firmware_memory[0xfc2dul] = 0u;
    firmware_memory[0xfc2eul] = 0xffu;
    firmware_memory[0x0e43ul] = 4u;
    write_count = 0u;
    ConfigurePickupMoveControllerForDistance(10u, 0u);
    assert(write_count == 3u);
    assert(write_trace[0] == 0x180daul && write_values[0] == 0x01u);
    assert(write_trace[1] == 0x180e3ul && write_values[1] == 0xafu);
    assert(write_trace[2] == 0x180e2ul && write_values[2] == 0x52u);
}

static void test_program_pickup_move_profile_for_distance(void)
{
    static const fw_addr_t table_bases[2][2] = {
        { 0xff8890ul, 0xff8868ul },
        { 0xff88e0ul, 0xff88b8ul }
    };
    static const u8 operating_codes[2] = { 3u, 4u };
    static const u8 directions[3] = { 0u, 1u, 0xffu };
    unsigned operating_class;
    unsigned direction_index;
    unsigned bin;
    unsigned distance;

    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    for(operating_class = 0u; operating_class < 2u; ++operating_class)
        for(direction_index = 0u; direction_index < 2u; ++direction_index)
            for(bin = 0u; bin < 10u; ++bin)
            {
                fw_addr_t address = table_bases[operating_class][direction_index] + 4ul * bin;
                set_memory_big_endian_u16((u16)address, (u16)(0x1000u + operating_class * 0x400u + direction_index * 0x200u + bin));
                set_memory_big_endian_u16((u16)(address + 2ul), (u16)(0x5000u + operating_class * 0x400u + direction_index * 0x200u + bin));
            }

    for(operating_class = 0u; operating_class < 2u; ++operating_class)
    {
        firmware_memory[0x0e43ul] = operating_codes[operating_class];
        for(direction_index = 0u; direction_index < 3u; ++direction_index)
        {
            unsigned direction_class = directions[direction_index] == 1u;

            for(distance = 0u; distance < 0x100u; ++distance)
            {
                fw_addr_t address;
                u16 expected_011d;
                u16 expected_011e;

                if(distance < 0x10u)
                    bin = 0u;
                else if(distance < 0x20u)
                    bin = 1u;
                else if(distance < 0x40u)
                    bin = 2u;
                else if(distance < 0x60u)
                    bin = 3u;
                else if(distance < 0x80u)
                    bin = 4u;
                else if(distance < 0xa0u)
                    bin = 5u;
                else if(distance < 0xc0u)
                    bin = 6u;
                else if(distance < 0xe0u)
                    bin = 7u;
                else if(distance < 0xffu)
                    bin = 8u;
                else
                    bin = 9u;
                address = table_bases[operating_class][direction_class] + 4ul * bin;
                expected_011d = get_memory_big_endian_u16(address);
                expected_011e = get_memory_big_endian_u16(address + 2ul);

                read_count = write_count = 0u;
                ProgramPickupMoveProfileForDistance(directions[direction_index], (u16)distance);
                assert(read_trace[0] == 0x0e43ul && read_trace[1] == 0x0e43ul);
                assert(write_count == 8u);
                assert(write_values[0] == (u8)expected_011d && write_values[1] == (u8)(expected_011d >> 8) && write_values[2] == 0x1du && write_values[3] == 0x01u);
                assert(write_values[4] == (u8)expected_011e && write_values[5] == (u8)(expected_011e >> 8) && write_values[6] == 0x1eu && write_values[7] == 0x01u);
            }
        }
    }

    for(operating_class = 0u; operating_class < 2u; ++operating_class)
    {
        firmware_memory[0x0e43ul] = operating_codes[operating_class];
        for(direction_index = 0u; direction_index < 3u; ++direction_index)
        {
            u16 expected_011e;

            if(operating_class == 0u)
                expected_011e = directions[direction_index] == 1u ? 0x0700u : 0x0840u;
            else
                expected_011e = directions[direction_index] == 1u ? 0x02c0u : 0x03f0u;
            read_count = write_count = 0u;
            ProgramPickupMoveProfileForDistance(directions[direction_index], 0xffffu);
            assert(read_count == 5u && read_trace[0] == 0x0e43ul);
            assert(write_count == 8u && write_values[0] == 0xb0u && write_values[1] == 0x00u && write_values[4] == (u8)expected_011e && write_values[5] == (u8)(expected_011e >> 8));
        }
    }
}

