static void test_retry_controller_measurement_evaluation(void)
{
    static const u8 repoll_then_success[] = { 0xfeu, 0xfeu, 0u };
    static const u8 success[] = { 0u };
    static const u8 repeat_after_position[] = { 0u, 0u };

    clear_memory(0u);
    measurement_evaluation_poll_results = repoll_then_success;
    measurement_evaluation_poll_result_count = sizeof(repoll_then_success);
    measurement_evaluation_poll_count = 0u;
    measurement_evaluation_start_count = measurement_evaluation_mutate_current_on_start = 0u;
    set_memory_big_endian_u32(0x103du, 100ul);
    set_memory_big_endian_u32(0x1235u, 115ul);
    RetryControllerMeasurementEvaluation();
    assert(measurement_evaluation_start_count == 1u && measurement_evaluation_poll_count == 3u && firmware_memory[0xef75ul] == 0u && firmware_memory[0xef7ful] == 1u);

    clear_memory(0u);
    measurement_evaluation_poll_results = success;
    measurement_evaluation_poll_result_count = sizeof(success);
    measurement_evaluation_poll_count = 0u;
    measurement_evaluation_start_count = measurement_evaluation_mutate_current_on_start = 0u;
    firmware_memory[0xfb94ul] = 0x4du;
    RetryControllerMeasurementEvaluation();
    assert(measurement_evaluation_start_count == 1u && firmware_memory[0xef7eul] == 0x4du && firmware_memory[0xef7ful] == 4u);

    clear_memory(0u);
    measurement_evaluation_poll_results = repeat_after_position;
    measurement_evaluation_poll_result_count = sizeof(repeat_after_position);
    measurement_evaluation_poll_count = 0u;
    measurement_evaluation_start_count = 0u;
    measurement_evaluation_mutate_current_on_start = 2u;
    set_memory_big_endian_u32(0x103du, 100ul);
    set_memory_big_endian_u32(0x1235u, 50ul);
    firmware_memory[0x1039ul] = 0x40u;
    RetryControllerMeasurementEvaluation();
    assert(measurement_evaluation_start_count == 2u && firmware_memory[0x1039ul] == 0x40u && firmware_memory[0xef7ful] == 1u);

    clear_memory(0u);
    measurement_evaluation_poll_results = repeat_after_position;
    measurement_evaluation_poll_result_count = sizeof(repeat_after_position);
    measurement_evaluation_poll_count = 0u;
    measurement_evaluation_start_count = 0u;
    measurement_evaluation_mutate_current_on_start = 2u;
    set_memory_big_endian_u32(0x103du, 100ul);
    set_memory_big_endian_u32(0x1235u, 99ul);
    RetryControllerMeasurementEvaluation();
    assert(measurement_evaluation_start_count == 2u && firmware_memory[0x1039ul] == 9u && firmware_memory[0xef7ful] == 1u);
}

