static void test_update_controller_timing_value_unless_flag4_set(void)
{
    unsigned flags;
    for(flags = 0u; flags < 65536u; ++flags)
    {
        clear_memory(0u);
        firmware_memory[0x0ff5ul] = (u8)(flags >> 8);
        firmware_memory[0x0ff6ul] = (u8)flags;
        firmware_memory[0x0fd5ul] = 0xa5u;
        firmware_memory[0x0fd6ul] = 0x5au;
        controller_timing_wait_count = controller_timing_measure_count = 0u;
        controller_timing_measure_value = (u16)flags;
        UpdateControllerTimingValueUnlessFlag4Set();
        if((flags & 0x10u) != 0u)
        {
            assert(firmware_memory[0x0fd5ul] == 0xa5u && firmware_memory[0x0fd6ul] == 0x5au);
            assert(controller_timing_wait_count == 0u && controller_timing_measure_count == 0u);
        }
        else
        {
            assert(get_memory_big_endian_u16(0x0fd5u) == (u16)(flags + 0x78u));
            assert(controller_timing_wait_count == 1u && controller_timing_measure_count == 1u);
        }
    }
}

static void test_validate_mode_select_page0e_with_timing_value(void)
{
    static const u32 raw_values[] = { 6ul, 0x1234ul };
    unsigned page, scale, raw_index, index;

    for(raw_index = 0u; raw_index < sizeof(raw_values) / sizeof(raw_values[0]); ++raw_index)
        for(page = 0u; page < 256u; ++page)
            for(scale = 0u; scale < 256u; ++scale)
            {
                u16 base = (u16)(raw_values[raw_index] - 6ul);
                u8 expected = page == 0x0eu && (scale == 0u ? base : (u16)(((u32)base * scale) >> 8)) != 0u;
                clear_memory(0u);
                firmware_memory[0xb2bul] = (u8)page;
                firmware_memory[0xb2dul] = (u8)scale;
                for(index = 0u; index < 14u; ++index)
                    firmware_memory[0xff8a24ul + index] = 0u;
                set_memory_big_endian_u32(0x156au, raw_values[raw_index]);
                assert(ValidateModeSelectPage0EWithTimingValue() == expected);
            }

    clear_memory(0u);
    firmware_memory[0xb2bul] = 0x0eu;
    firmware_memory[0xb2cul] = 1u;
    firmware_memory[0xff8a24ul] = 1u;
    set_memory_big_endian_u32(0x156au, 0x1234ul);
    assert(ValidateModeSelectPage0EWithTimingValue() == 0u);
}

