static void test_is_read_window_outside_accepted_range(void)
{
    static const s32 invalid_values[] = { -1, -150, 151, 0x7fffffff };
    unsigned value, result, index;
    for(value = 0u; value <= 150u; ++value)
        for(result = 0u; result < 256u; ++result)
        {
            clear_memory(0u);
            set_memory_big_endian_u32(0x0b02u, value);
            read_window_bound_result = (u8)result;
            read_window_bound_call_count = 0u;
            assert(IsReadWindowOutsideAcceptedRange() == (result == 2u ? 0u : 1u));
            assert(read_window_bound_call_count == 1u && read_window_upper_seen == value + 151u && read_window_lower_seen == value + 150u && read_count == 16u && read_trace[0] == 0x0b02ul
                   && read_trace[4] == 0x0b02ul && read_trace[8] == 0x0b02ul && read_trace[12] == 0x0b02ul);
        }
    for(index = 0u; index < sizeof(invalid_values) / sizeof(invalid_values[0]); ++index)
    {
        clear_memory(0u);
        set_memory_big_endian_u32(0x0b02u, (u32)invalid_values[index]);
        read_window_bound_call_count = 0u;
        assert(IsReadWindowOutsideAcceptedRange() == 1u && read_window_bound_call_count == 0u && read_count == (invalid_values[index] < 0 ? 8u : 4u));
    }
}

