{
    vendor_f6_event_count = 0u;
    vendor_f6_status_seen = 0u;
    vendor_f6_sense_key_seen = 0u;
    vendor_f6_asc_ascq_seen = 0u;
    vendor_f6_convert_count = 0u;
    vendor_f6_convert_start_result = 0;
    vendor_f6_convert_end_result = 0;
    vendor_f6_coroutine2_entry_seen = 0ul;
    vendor_f6_execute_c84_seen = 0u;
    vendor_f6_execute_c85_seen = 0u;
}

static void reset_vendor_f2_observations(void)
{
    vendor_f2_event_count = 0u;
    vendor_f2_validate_result = 1u;
    vendor_f2_opc_result = 1u;
    vendor_f2_transfer_result = 4u;
    vendor_f2_coroutine2_entry_seen = 0ul;
    vendor_f2_transfer_count_seen = 0ul;
    vendor_f2_transfer_source_seen = 0ul;
    vendor_f2_opc_c84_seen = 0u;
    vendor_f2_opc_ef72_seen = 0u;
    vendor_f2_opc_e74e_seen = 0xffu;
}

static void test_handle_scsi_opcode_f6(void)
{
    static const u8 expected_success_events[] = { 5u, 7u, 8u, 9u, 10u };
    static const u8 expected_msf_events[] = { 6u, 6u, 7u, 8u, 9u, 10u };

    clear_memory(0u);
    reset_vendor_f6_observations();
    firmware_memory[0x0fae] = 3u;
    HandleScsiOpcodeF6();
    assert(vendor_f6_event_count == 1u && vendor_f6_events[0] == 1u);
    assert(vendor_f6_status_seen == 3u);

    clear_memory(0u);
    reset_vendor_f6_observations();
    HandleScsiOpcodeF6();
    assert(vendor_f6_event_count == 1u && vendor_f6_events[0] == 2u);
    assert(vendor_f6_sense_key_seen == 2u && vendor_f6_asc_ascq_seen == 0x0401u);

    clear_memory(0u);
    reset_vendor_f6_observations();
    firmware_memory[0x0fae] = 4u;
    HandleScsiOpcodeF6();
    assert(vendor_f6_event_count == 1u && vendor_f6_events[0] == 3u);

    clear_memory(0u);
    reset_vendor_f6_observations();
    firmware_memory[0x0fae] = 4u;
    firmware_memory[0x1008] = 2u;
    set_memory_big_endian_u32(0x0b0cu, 10ul);
    set_memory_big_endian_u32(0x0b10u, 10ul);
    HandleScsiOpcodeF6();
    assert(vendor_f6_event_count == 1u && vendor_f6_events[0] == 4u);
    assert(get_memory_big_endian_u32(0x0f091u) == 10ul && get_memory_big_endian_u32(0x0f095u) == 10ul);

    clear_memory(0u);
    reset_vendor_f6_observations();
    firmware_memory[0x0fae] = 4u;
    firmware_memory[0x1008] = 2u;
    firmware_memory[0x0b0b] = 5u;
    firmware_memory[0x0b14] = 0x5au;
    firmware_memory[0x0c84] = 0xa1u;
    firmware_memory[0x0c85] = 0xa2u;
    set_memory_big_endian_u32(0x0b0cu, 0xfffffffeul);
    set_memory_big_endian_u32(0x0b10u, 5ul);
    HandleScsiOpcodeF6();
    assert(vendor_f6_event_count == sizeof(expected_success_events));
    assert(memcmp(vendor_f6_events, expected_success_events, sizeof(expected_success_events)) == 0);
    assert(get_memory_big_endian_u32(0x0f091u) == 0xfffffffeul && get_memory_big_endian_u32(0x0f095u) == 5ul);
    assert(firmware_memory[0x0f08e] == 0x5au);
    assert(vendor_f6_coroutine2_entry_seen == 0x00f84a00ul);
    assert(vendor_f6_execute_c84_seen == 0xa9u && vendor_f6_execute_c85_seen == 0xa3u);
    assert(firmware_memory[0x0c84] == 0xa1u && firmware_memory[0x0c85] == 0xa2u);

    clear_memory(0u);
    reset_vendor_f6_observations();
    firmware_memory[0x0c85] = 2u;
    firmware_memory[0x1008] = 2u;
    firmware_memory[0x0b0b] = 2u;
    firmware_memory[0x0b0d] = 1u;
    firmware_memory[0x0b11] = 2u;
    vendor_f6_convert_start_result = -100;
    vendor_f6_convert_end_result = 200;
    HandleScsiOpcodeF6();
    assert(vendor_f6_event_count == sizeof(expected_msf_events));
    assert(memcmp(vendor_f6_events, expected_msf_events, sizeof(expected_msf_events)) == 0);
    assert(vendor_f6_convert_count == 2u && vendor_f6_convert_addresses[0] == 0x000b0dul && vendor_f6_convert_addresses[1] == 0x000b11ul && vendor_f6_convert_flag_seen[0] == 1u
           && vendor_f6_convert_flag_seen[1] == 1u);
    assert(get_memory_big_endian_u32(0x0f091u) == (u32)-100 && get_memory_big_endian_u32(0x0f095u) == 200ul && firmware_memory[0x102f] == 0u);

    clear_memory(0u);
    reset_vendor_f6_observations();
    firmware_memory[0x0fae] = 4u;
    firmware_memory[0x1008] = 2u;
    firmware_memory[0x0b0b] = 2u;
    firmware_memory[0x0b0d] = 0xffu;
    firmware_memory[0x0b11] = 0xffu;
    set_memory_big_endian_u32(0x114fu, 1000ul);
    set_memory_big_endian_u32(0x1153u, 2000ul);
    HandleScsiOpcodeF6();
    assert(vendor_f6_convert_count == 0u);
    assert((s32)get_memory_big_endian_u32(0x0f091u) == -1661 && get_memory_big_endian_u32(0x0f095u) == 8751ul);
}

static void test_handle_scsi_opcode_f2(void)
{
    static const struct
    {
        u8 command_flags;
        u16 expected_media_flags;
    } media_flag_cases[] = {
        { 0x00u, 0xe07fu },
        { 0x04u, 0xf0ffu },
        { 0x08u, 0xf17fu },
        { 0x0cu, 0xf27fu },
        { 0x10u, 0xf47fu },
        { 0x14u, 0xf87fu },
        { 0x1cu, 0xf87fu }
    };
    static const u8 expected_short_events[] = { 1u, 2u, 9u, 11u };
    static const u8 expected_direct_events[] = { 1u, 2u, 8u, 10u, 12u };
    static const u8 expected_opc_events[] = { 1u, 2u, 3u, 4u, 5u, 6u, 7u, 9u, 11u };
    static const u8 expected_opc_failure_events[] = { 1u, 2u, 3u, 4u, 5u, 6u, 7u };
    unsigned index;

    clear_memory(0u);
    reset_vendor_f2_observations();
    vendor_f2_validate_result = 0u;
    HandleScsiOpcodeF2();
    assert(vendor_f2_event_count == 1u && vendor_f2_events[0] == 1u);

    for(index = 0u; index < sizeof(media_flag_cases) / sizeof(media_flag_cases[0]); ++index)
    {
        clear_memory(0u);
        reset_vendor_f2_observations();
        firmware_memory[0x0b0b] = media_flag_cases[index].command_flags;
        firmware_memory[0x0ff5] = 0xffu;
        firmware_memory[0x0ff6] = 0xffu;
        set_memory_big_endian_u16(0x0b11u, 0xffffu);
        HandleScsiOpcodeF2();
        assert(vendor_f2_event_count == sizeof(expected_short_events));
        assert(memcmp(vendor_f2_events, expected_short_events, sizeof(expected_short_events)) == 0);
        assert(get_memory_big_endian_u16(0x0ff5u) == media_flag_cases[index].expected_media_flags);
        assert(vendor_f2_transfer_source_seen == 0x000b2aul && vendor_f2_transfer_count_seen == 0x008dul);
    }

    clear_memory(0u);
    reset_vendor_f2_observations();
    firmware_memory[0x1008] = 2u;
    firmware_memory[0xef73] = 2u;
    set_memory_big_endian_u16(0x0b11u, 0x0200u);
    vendor_f2_transfer_result = 5u;
    HandleScsiOpcodeF2();
    assert(vendor_f2_event_count == sizeof(expected_direct_events));
    assert(memcmp(vendor_f2_events, expected_direct_events, sizeof(expected_direct_events)) == 0);
    assert(vendor_f2_transfer_source_seen == 0ul && vendor_f2_transfer_count_seen == 0x0176ul);

    clear_memory(0u);
    reset_vendor_f2_observations();
    firmware_memory[0x0b0b] = 3u;
    firmware_memory[0x0c84] = 0xa1u;
    firmware_memory[0xef72] = 0xb2u;
    firmware_memory[0xe74e] = 0xffu;
    set_memory_big_endian_u16(0x0b11u, 5u);
    HandleScsiOpcodeF2();
    assert(vendor_f2_event_count == sizeof(expected_opc_events));
    assert(memcmp(vendor_f2_events, expected_opc_events, sizeof(expected_opc_events)) == 0);
    assert(vendor_f2_coroutine2_entry_seen == 0x00f84a00ul);
    assert(vendor_f2_opc_c84_seen == 0xa9u && vendor_f2_opc_ef72_seen == 0xbau && vendor_f2_opc_e74e_seen == 0u);
    assert(firmware_memory[0x0c84] == 0xa1u && firmware_memory[0xef72] == 0xb2u);
    assert(vendor_f2_transfer_source_seen == 0x000b2aul && vendor_f2_transfer_count_seen == 5ul);

    clear_memory(0u);
    reset_vendor_f2_observations();
    firmware_memory[0x0b0b] = 1u;
    firmware_memory[0x0c84] = 0x18u;
    firmware_memory[0xef72] = 0x08u;
    vendor_f2_opc_result = 0u;
    HandleScsiOpcodeF2();
    assert(vendor_f2_event_count == sizeof(expected_opc_failure_events));
    assert(memcmp(vendor_f2_events, expected_opc_failure_events, sizeof(expected_opc_failure_events)) == 0);
    assert(firmware_memory[0x0c84] == 0x10u && firmware_memory[0xef72] == 0u);
}

static void test_dispatch_raw_sector_transfer_setup(void)
{
    static const u32 starts[] = { 0ul, 0x1234ul, 0xfffffffeul };
    static const u32 lengths[] = { 0ul, 0x55ul };
    static const u8 formats[] = { 0u, 0xffu };
    unsigned pending, start_index, length_index, format_index;

    for(pending = 0u; pending < 2u; ++pending)
        for(start_index = 0u; start_index < sizeof(starts) / sizeof(starts[0]); ++start_index)
            for(length_index = 0u; length_index < sizeof(lengths) / sizeof(lengths[0]); ++length_index)
                for(format_index = 0u; format_index < sizeof(formats) / sizeof(formats[0]); ++format_index)
                {
                    u32 expected_start = starts[start_index] + 150ul;
                    clear_memory(0u);
                    bit_000d = (u8)pending;
                    bit_000e = 1u;
                    bit_0018 = 1u;
                    firmware_memory[0x0c2aul] = 0xa5u;
                    firmware_memory[0x0f0bul] = 0x5au;
                    firmware_memory[0x0c34ul] = formats[format_index];
                    set_memory_big_endian_u32(0x0b02u, starts[start_index]);
                    set_memory_big_endian_u32(0x0b06u, lengths[length_index]);
                    raw_sector_call_count = 0u;
                    DispatchRawSectorTransferSetup();
                    assert(raw_sector_call_count == 1u && raw_sector_start_seen == expected_start && raw_sector_end_seen == expected_start + lengths[length_index]
                           && raw_sector_format_seen == formats[format_index] && raw_sector_flag46_seen == 1u);
                    assert(firmware_memory[0x0c2aul] == (pending != 0u ? 7u : 0xa5u) && firmware_memory[0x0f0bul] == 0u && bit_000d == 0u && bit_000e == 0u && bit_0018 == 0u && bit_0046 == 0u);
                }
}

static void test_handle_scsi_opcode_d8(void)
{
    static const struct
    {
        u8 cdb_byte1;
        u8 format;
        u8 pending;
        u32 logical_block_address;
        u32 block_count;
        unsigned expected_reads;
        unsigned expected_writes;
    } accepted[] = {
        { 0x00u, 0u, 0u, 0ul,          0ul,          13u, 1u },
        { 0xe0u, 3u, 1u, 0xfffffffeul, 5ul,          13u, 2u },
        { 0x00u, 8u, 1u, 0x12345678ul, 0xfedcba98ul, 14u, 3u }
    };
    static const struct
    {
        u8 cdb_byte1;
        u8 cdb_byte11;
        u8 format;
        unsigned expected_reads;
    } rejected[] = {
        { 0x01u, 0x00u, 0u,    2u },
        { 0x00u, 0x04u, 0u,    2u },
        { 0x00u, 0x00u, 4u,    4u },
        { 0x00u, 0x00u, 7u,    4u },
        { 0x00u, 0x00u, 9u,    4u },
        { 0x00u, 0x00u, 0xffu, 4u }
    };
    unsigned vector_index;

    for(vector_index = 0u; vector_index < sizeof(accepted) / sizeof(accepted[0]); ++vector_index)
    {
        u32 expected_start = accepted[vector_index].logical_block_address + 150ul;

        clear_memory(0u);
        firmware_memory[0x0b0b] = accepted[vector_index].cdb_byte1;
        firmware_memory[0x0b14] = accepted[vector_index].format;
        firmware_memory[0x0b15] = 0u;
        firmware_memory[0x0c2a] = 0xa5u;
        firmware_memory[0x0f0b] = 0xa5u;
        set_memory_big_endian_u32(0x0b0cu, accepted[vector_index].logical_block_address);
        set_memory_big_endian_u32(0x0b10u, accepted[vector_index].block_count);
        bit_000d = accepted[vector_index].pending;
        bit_0013 = 1u;
        bit_000e = 1u;
        bit_0018 = 1u;
        bit_0046 = 1u;
        raw_sector_call_count = 0u;

        HandleScsiOpcodeD8();

        assert(raw_sector_call_count == 1u);
        assert(raw_sector_start_seen == expected_start);
        assert(raw_sector_end_seen == expected_start + accepted[vector_index].block_count);
        assert(raw_sector_format_seen == accepted[vector_index].format);
        assert(raw_sector_flag46_seen == 1u);
        assert(firmware_memory[0x0c2a] == (accepted[vector_index].pending != 0u ? 7u : 0xa5u));
        assert(firmware_memory[0x0f0b] == (accepted[vector_index].format == 8u ? 2u : 0u));
        assert(bit_000d == 0u && bit_0013 == 0u && bit_000e == 0u && bit_0018 == 0u && bit_0046 == 0u);
        assert(read_count == accepted[vector_index].expected_reads);
        assert(write_count == accepted[vector_index].expected_writes);
        assert(read_trace[0] == 0x000b15ul && read_trace[1] == 0x000b0bul && read_trace[2] == 0x000b14ul);
    }

    for(vector_index = 0u; vector_index < sizeof(rejected) / sizeof(rejected[0]); ++vector_index)
    {
        clear_memory(0u);
        firmware_memory[0x0b0b] = rejected[vector_index].cdb_byte1;
        firmware_memory[0x0b14] = rejected[vector_index].format;
        firmware_memory[0x0b15] = rejected[vector_index].cdb_byte11;
        firmware_memory[0x0f0b] = 0xa5u;
        bit_000d = bit_0013 = bit_000e = bit_0018 = bit_0046 = 1u;
        raw_sector_call_count = 0u;

        HandleScsiOpcodeD8();

        assert(raw_sector_call_count == 0u);
        assert(read_count == rejected[vector_index].expected_reads);
        assert(firmware_memory[0x0b18] == 0x70u);
        assert(firmware_memory[0x0b1a] == 0x05u);
        assert(firmware_memory[0x0b24] == 0x24u);
        assert(firmware_memory[0x0b25] == 0u);
        assert(firmware_memory[0x0f0b] == 0xa5u);
        assert(bit_000d == 1u && bit_0013 == 1u && bit_000e == 1u && bit_0018 == 1u && bit_0046 == 1u);
    }
}

static void test_handle_scsi_opcode_d9(void)
{
    static const struct
    {
        u8 format;
        u8 pending;
        u8 start_msf[3];
        u8 end_msf[3];
        s32 expected_start;
        s32 expected_end;
        unsigned expected_writes;
    } accepted[] = {
        { 0u, 0u, { 1u, 2u, 3u }, { 2u, 3u, 4u },     4653l, 9229l,   1u },
        { 3u, 1u, { 0u, 0u, 0u }, { 149u, 59u, 74u }, 0l,    674999l, 2u }
    };
    unsigned vector_index;

    for(vector_index = 0u; vector_index < sizeof(accepted) / sizeof(accepted[0]); ++vector_index)
    {
        clear_memory(0u);
        firmware_memory[0x0b0b] = 0xe0u;
        firmware_memory[0x0b0c] = 0u;
        firmware_memory[0x0b10] = 0u;
        firmware_memory[0x0b14] = accepted[vector_index].format;
        firmware_memory[0x0b15] = 3u;
        memcpy(&firmware_memory[0x0b0d], accepted[vector_index].start_msf, 3u);
        memcpy(&firmware_memory[0x0b11], accepted[vector_index].end_msf, 3u);
        firmware_memory[0x0c2a] = 0xa5u;
        firmware_memory[0x0f0b] = 0xa5u;
        bit_000d = accepted[vector_index].pending;
        bit_0013 = bit_000e = bit_0018 = bit_0046 = 1u;
        raw_sector_call_count = 0u;

        HandleScsiOpcodeD9();

        assert(raw_sector_call_count == 1u);
        assert((s32)raw_sector_start_seen == accepted[vector_index].expected_start);
        assert((s32)raw_sector_end_seen == accepted[vector_index].expected_end);
        assert(raw_sector_format_seen == accepted[vector_index].format);
        assert(raw_sector_flag46_seen == 1u);
        assert(firmware_memory[0x0c2a] == (accepted[vector_index].pending != 0u ? 7u : 0xa5u));
        assert(firmware_memory[0x0f0b] == 0u);
        assert(bit_000d == 0u && bit_0013 == 0u && bit_000e == 0u && bit_0018 == 0u && bit_0046 == 0u);
        assert(read_count == 20u);
        assert(write_count == accepted[vector_index].expected_writes);
        assert(read_trace[0] == 0x000b0bul && read_trace[1] == 0x000b0cul && read_trace[2] == 0x000b10ul && read_trace[3] == 0x000b14ul && read_trace[4] == 0x000b15ul);
    }

    clear_memory(0u);
    firmware_memory[0x0b0c] = 1u;
    raw_sector_call_count = 0u;
    HandleScsiOpcodeD9();
    assert(raw_sector_call_count == 0u && read_count == 5u);
    assert(firmware_memory[0x0b1a] == 5u && firmware_memory[0x0b24] == 0x24u);

    clear_memory(0u);
    firmware_memory[0x0b0d] = 150u;
    raw_sector_call_count = 0u;
    HandleScsiOpcodeD9();
    assert(raw_sector_call_count == 0u && read_count == 6u);
    assert(firmware_memory[0x0b1a] == 5u && firmware_memory[0x0b24] == 0x24u);

    clear_memory(0u);
    firmware_memory[0x0b11] = 150u;
    raw_sector_call_count = 0u;
    HandleScsiOpcodeD9();
    assert(raw_sector_call_count == 0u && read_count == 9u);
    assert(firmware_memory[0x0b1a] == 5u && firmware_memory[0x0b24] == 0x24u);
}

static void test_validate_raw_sector_read_frame_range_against_media_bounds(void)
{
    clear_memory(0u);
    assert(ValidateRawSectorReadFrameRangeAgainstMediaBounds(1l, 0l) == 0u);
    assert(read_count == 0u);
    assert(firmware_memory[0x0b1a] == 5u && firmware_memory[0x0b24] == 0x24u);

    clear_memory(0u);
    firmware_memory[0x0b0a] = 0xd7u;
    firmware_memory[0x12be] = 0x02u;
    assert(ValidateRawSectorReadFrameRangeAgainstMediaBounds(0l, 0l) == 0u);
    assert(read_count == 3u);
    assert(firmware_memory[0x0b1a] == 5u);
    assert(get_memory_big_endian_u16(0x0b24u) == 0x6400u);

    clear_memory(0u);
    firmware_memory[0x0b0a] = 0xd8u;
    set_memory_big_endian_u32(0x12c1u, 1000ul);
    firmware_memory[0x12c0] = 2u;
    assert(ValidateRawSectorReadFrameRangeAgainstMediaBounds(-100l, 359999l) == 1u);
    assert(read_count == 7u && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0b0a] = 0xd8u;
    set_memory_big_endian_u32(0x12c1u, 1000ul);
    firmware_memory[0x12c0] = 2u;
    assert(ValidateRawSectorReadFrameRangeAgainstMediaBounds(-100l, 360000l) == 0u);
    assert(read_count == 7u);
    assert(get_memory_big_endian_u16(0x0b24u) == 0x2100u);

    clear_memory(0u);
    firmware_memory[0x1008] = 1u;
    firmware_memory[0x1132] = 0x10u;
    set_memory_big_endian_u32(0x0b02u, 0x89abcdeful);
    assert(ValidateRawSectorReadFrameRangeAgainstMediaBounds(224l, 225l) == 0u);
    assert(read_count == 7u);
    assert(firmware_memory[0x0b18] == 0xf0u);
    assert(get_memory_big_endian_u16(0x0b24u) == 0x2100u);
    assert(get_memory_big_endian_u32(0x0b1bu) == 0x89abcdeful);

    clear_memory(0u);
    firmware_memory[0x1008] = 1u;
    firmware_memory[0x1132] = 0x10u;
    set_memory_big_endian_u32(0x12c1u, 3000ul);
    set_memory_big_endian_u32(0x1153u, 2000ul);
    assert(ValidateRawSectorReadFrameRangeAgainstMediaBounds(225l, 3100l) == 1u);
    assert(read_count == 14u && write_count == 0u);
    assert(read_trace[2] == 0x0012c1ul && read_trace[5] == 0x0012c4ul);
    assert(read_trace[6] == 0x001153ul && read_trace[9] == 0x001156ul);
    assert(read_trace[10] == 0x0012c1ul && read_trace[13] == 0x0012c4ul);

    clear_memory(0u);
    firmware_memory[0x1008] = 1u;
    set_memory_big_endian_u32(0x12c1u, 1000ul);
    set_memory_big_endian_u32(0x1153u, 2000ul);
    assert(ValidateRawSectorReadFrameRangeAgainstMediaBounds(225l, 2101l) == 0u);
    assert(read_count == 14u);
    assert(read_trace[10] == 0x001153ul && read_trace[13] == 0x001156ul);
    assert(get_memory_big_endian_u16(0x0b24u) == 0x2100u);
}

static void test_handle_scsi_opcode_df(void)
{
    static const u8 pending_success_events[] = { 1u, 2u, 3u, 4u, 3u, 4u, 3u };
    static const u8 terminal_failure_events[] = { 1u, 2u, 3u, 5u, 6u, 4u };

    clear_memory(0u);
    reset_vendor_df_observations();
    vendor_df_validate_result = 0u;
    HandleScsiOpcodeDF();
    assert(vendor_df_mask_seen == 0x00ff8e4aul);
    assert(vendor_df_event_count == 1u && vendor_df_events[0] == 1u);
    assert(firmware_memory[0x0b1a] == 5u);
    assert(get_memory_big_endian_u16(0x0b24u) == 0x2400u);

    clear_memory(0u);
    reset_vendor_df_observations();
    firmware_memory[0x0c2a] = 4u;
    HandleScsiOpcodeDF();
    assert(vendor_df_event_count == 1u && vendor_df_events[0] == 1u);
    assert(firmware_memory[0x0b1a] == 5u);
    assert(get_memory_big_endian_u16(0x0b24u) == 0x2c00u);

    clear_memory(0u);
    reset_vendor_df_observations();
    vendor_df_audio_status = 0x15u;
    HandleScsiOpcodeDF();
    assert(vendor_df_event_count == 2u && vendor_df_events[0] == 1u && vendor_df_events[1] == 2u && vendor_df_audio_acknowledge_seen == 0u);
    assert(firmware_memory[0x0b1a] == 5u);
    assert(get_memory_big_endian_u16(0x0b24u) == 0x6400u);

    clear_memory(0xa5u);
    reset_vendor_df_observations();
    firmware_memory[0x0c2a] = 0u;
    memset(&firmware_memory[0x0b10], 0, 4u);
    HandleScsiOpcodeDF();
    assert(vendor_df_event_count == 2u && vendor_df_events[0] == 1u && vendor_df_events[1] == 2u);
    assert(get_memory_big_endian_u32(0x1455u) == 0ul);
    assert(get_memory_big_endian_u32(0x1459u) == 0xa5a5a5a5ul);
    assert(firmware_memory[0x0b1a] == 0u);

    clear_memory(0xa5u);
    reset_vendor_df_observations();
    firmware_memory[0x0c2a] = 0u;
    set_memory_big_endian_u32(0x0b10u, 0x01020304ul);
    vendor_df_poll_results[0] = 0xfeu;
    vendor_df_poll_results[1] = 0xfeu;
    vendor_df_poll_results[2] = 1u;
    vendor_df_poll_result_count = 3u;
    HandleScsiOpcodeDF();
    assert(vendor_df_event_count == sizeof(pending_success_events));
    assert(memcmp(vendor_df_events, pending_success_events, sizeof(pending_success_events)) == 0);
    assert(vendor_df_poll_index == 3u);
    assert(get_memory_big_endian_u32(0x1455u) == 0x01020304ul);
    assert(get_memory_big_endian_u32(0x1459u) == 0ul);
    assert(firmware_memory[0x0b1a] == 0u);

    clear_memory(0xa5u);
    reset_vendor_df_observations();
    firmware_memory[0x0c2a] = 0u;
    set_memory_big_endian_u32(0x0b10u, 1ul);
    vendor_df_poll_results[0] = 2u;
    vendor_df_poll_result_count = 1u;
    HandleScsiOpcodeDF();
    assert(vendor_df_event_count == sizeof(terminal_failure_events));
    assert(memcmp(vendor_df_events, terminal_failure_events, sizeof(terminal_failure_events)) == 0);
    assert(vendor_df_coroutine2_entry_seen == 0x00f84a00ul);
    assert(get_memory_big_endian_u32(0x1455u) == 1ul);
    assert(get_memory_big_endian_u32(0x1459u) == 0ul);
    assert(firmware_memory[0x0b1a] == 0xa5u);
}

static void test_poll_vendor_df_subchannel_transfer(void)
{
    u16 descriptor_address;

    clear_memory(0u);
    firmware_memory[0x0c83] = 0x10u;
    controller_data_in_transfer_call_count = 0u;
    assert(PollVendorDfSubchannelTransfer() == 0u);
    assert(read_count == 1u && controller_data_in_transfer_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0fae] = 2u;
    firmware_memory[0xf84454ul + 2u] = 3u;
    firmware_memory[0xf84468ul + 4u] = 0x12u;
    firmware_memory[0xf84468ul + 5u] = 0x34u;
    assert(PollVendorDfSubchannelTransfer() == 0u);
    assert(firmware_memory[0x0b1a] == 3u);
    assert(get_memory_big_endian_u16(0x0b24u) == 0x1234u);
    assert(read_trace[0] == 0x000c83ul && read_trace[1] == 0x000faeul && read_trace[2] == 0x000faeul && read_trace[5] == 0x000faeul && read_trace[6] == 0x00f84456ul);

    clear_memory(0u);
    assert(PollVendorDfSubchannelTransfer() == 0u);
    assert(firmware_memory[0x0b1a] == 5u);
    assert(get_memory_big_endian_u16(0x0b24u) == 0xbf00u);

    clear_memory(0u);
    firmware_memory[0x0f46] = 1u;
    bit_000e = 1u;
    assert(PollVendorDfSubchannelTransfer() == 0xfeu);
    assert(controller_data_in_transfer_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0f46] = 1u;
    firmware_memory[0x0c2a] = 3u;
    firmware_memory[0x0f06] = 2u;
    assert(PollVendorDfSubchannelTransfer() == 0u);
    assert(firmware_memory[0x0b1a] == 5u);
    assert(get_memory_big_endian_u16(0x0b24u) == 0x6400u);

    clear_memory(0u);
    firmware_memory[0x0f46] = 1u;
    set_memory_big_endian_u16(0x1298u, 1u);
    set_memory_big_endian_u32(0x129eu, 0x00002000ul);
    descriptor_address = 0x2016u;
    set_memory_big_endian_u16((u16)(descriptor_address + 8u), 3u);
    set_memory_big_endian_u32(0x1566u, 0x00100000ul);
    set_memory_big_endian_u32(0x1455u, 7ul);
    set_memory_big_endian_u32(0x1459u, 7ul);
    controller_data_in_transfer_call_count = 0u;
    controller_data_in_transfer_phase = 0u;
    assert(PollVendorDfSubchannelTransfer() == 1u);
    assert(bit_0023 == 1u);
    assert(controller_data_in_transfer_call_count == 1u);
    assert(controller_data_in_transfer_length == 0x60ul);
    assert(controller_data_in_transfer_offset == 0x00100120ul);

    clear_memory(0u);
    firmware_memory[0x0f46] = 1u;
    bit_000e = 1u;
    set_memory_big_endian_u16(0x0f4eu, 1u);
    set_memory_big_endian_u16(0x1298u, 0u);
    set_memory_big_endian_u32(0x129eu, 0x00003000ul);
    set_memory_big_endian_u16(0x3008u, 0xffffu);
    set_memory_big_endian_u32(0x1566u, 0x00ffff80ul);
    set_memory_big_endian_u32(0x1455u, 2ul);
    set_memory_big_endian_u32(0x1459u, 1ul);
    controller_data_in_transfer_call_count = 0u;
    assert(PollVendorDfSubchannelTransfer() == 0xfeu);
    assert(controller_data_in_transfer_call_count == 1u);
    assert(controller_data_in_transfer_length == 0x60ul);
    assert(controller_data_in_transfer_offset == 0x015fff20ul);
}

static s32 format2_raw_read_start_seen;
static unsigned format2_raw_read_start_call_count;
static u8 format2_raw_read_events[4];
static unsigned format2_raw_read_event_count;
static u8 format2_raw_read_range_sense_key;
static u8 format2_raw_read_range_seen_bit000e;

void ObserveStartFormat2RawSectorReadAtFramePosition(s32 frame_position)
{
    ++format2_raw_read_start_call_count;
    format2_raw_read_start_seen = frame_position;
}

void ObserveClearFormat2RawReadModeBits(void)
{
    bit_0013 = 0u;
    bit_000d = 0u;
    bit_000e = 0u;
}

void ObserveSetFormat2RawReadModeBit(void)
{
    bit_000e = 1u;
}

void ObserveClearFormat2RawReadModeBit(void)
{
    bit_000e = 0u;
}

void ObserveResetControllerPortsForFormat2RawRead(void)
{
    format2_raw_read_events[format2_raw_read_event_count++] = 1u;
}

void ObserveExecuteRawSectorReadRangeForFormat2(s32 start_frame_position, s32 end_frame_position_exclusive, u8 format_code)
{
    format2_raw_read_events[format2_raw_read_event_count++] = 2u;
    format2_raw_read_range_seen_bit000e = bit_000e;
    ExecuteRawSectorReadRange(start_frame_position, end_frame_position_exclusive, format_code);
    firmware_memory[0x000b1aul] = format2_raw_read_range_sense_key;
}

void ObserveBuildControllerShadowsForFormat2RawRead(void)
{
    format2_raw_read_events[format2_raw_read_event_count++] = 3u;
}

void ObserveApplyControllerShadowsForFormat2RawRead(void)
{
    format2_raw_read_events[format2_raw_read_event_count++] = 4u;
}

static void test_start_format2_raw_sector_read_at_frame_position(void)
{
    static const fw_addr_t expected_write_addresses[] = { 0x000f0bul, 0x018079ul, 0x01807dul, 0x01807aul, 0x018078ul, 0x01807cul, 0x018079ul, 0x01807dul, 0x000f4eul, 0x000f4ful, 0x000f50ul,
        0x000f51ul, 0x000fbaul, 0x000c2aul };
    static const u8 expected_write_values[] = { 0u, 0x44u, 0x54u, 0u, 0u, 0u, 0x40u, 0x54u, 0u, 0u, 0u, 0u, 0xfdu, 7u };
    unsigned index;

    clear_memory(0u);
    bit_0013 = bit_000d = bit_000e = 1u;
    firmware_memory[0x000fbaul] = 0xffu;
    format2_raw_read_event_count = 0u;
    format2_raw_read_range_sense_key = 0u;
    raw_sector_call_count = 0u;
    StartFormat2RawSectorReadAtFramePosition(-2);
    assert(bit_0013 == 0u && bit_000d == 0u && bit_000e == 1u);
    assert(format2_raw_read_range_seen_bit000e == 1u);
    assert(raw_sector_call_count == 1u);
    assert(raw_sector_start_seen == 0ul && raw_sector_end_seen == 1ul);
    assert(raw_sector_format_seen == 2u);
    assert(format2_raw_read_event_count == 4u);
    assert(format2_raw_read_events[0] == 1u);
    assert(format2_raw_read_events[1] == 2u);
    assert(format2_raw_read_events[2] == 3u);
    assert(format2_raw_read_events[3] == 4u);
    assert(write_count == sizeof(expected_write_addresses) / sizeof(expected_write_addresses[0]));
    for(index = 0u; index < sizeof(expected_write_addresses) / sizeof(expected_write_addresses[0]); ++index)
    {
        assert(write_trace[index] == expected_write_addresses[index]);
        assert(write_values[index] == expected_write_values[index]);
    }

    clear_memory(0u);
    bit_0013 = bit_000d = bit_000e = 1u;
    firmware_memory[0x000fbaul] = 3u;
    format2_raw_read_event_count = 0u;
    format2_raw_read_range_sense_key = 5u;
    raw_sector_call_count = 0u;
    StartFormat2RawSectorReadAtFramePosition((s32)0xfffffffful);
    assert(bit_0013 == 0u && bit_000d == 0u && bit_000e == 0u);
    assert(format2_raw_read_range_seen_bit000e == 1u);
    assert(raw_sector_call_count == 1u);
    assert(raw_sector_start_seen == 1ul && raw_sector_end_seen == 2ul);
    assert(raw_sector_format_seen == 2u);
    assert(format2_raw_read_event_count == 2u);
    assert(format2_raw_read_events[0] == 1u);
    assert(format2_raw_read_events[1] == 2u);
    assert(firmware_memory[0x000fbaul] == 1u);
}

