static void test_capture_raw_sector_using_q_msf_and_populate_subheader(void)
{
    clear_memory(0xa5u);
    reset_q_msf_sector_capture_observers();
    q_msf_capture_capacity_result = 0u;
    assert(CaptureRawSectorUsingQMsfAndPopulateSubheader(0x001234ul, 0x234567ul, 0xffu) == 0u);
    assert(q_msf_capture_event_count == 2u && q_msf_capture_events[0] == 1u && q_msf_capture_events[1] == 2u);
    assert(read_count == 0u && write_count == 0u);

    clear_memory(0u);
    reset_q_msf_sector_capture_observers();
    set_memory_big_endian_u32(0x1598u, 0x89abcdeful);
    q_msf_capture_capacity_result = 0x80u;
    q_msf_capture_result = 0u;
    assert(CaptureRawSectorUsingQMsfAndPopulateSubheader(0x12fffful, 0x234567ul, 0xe1u) == 0u);
    assert(q_msf_capture_event_count == 5u && q_msf_capture_events[0] == 1u && q_msf_capture_events[1] == 3u && q_msf_capture_events[2] == 4u && q_msf_capture_events[3] == 5u
           && q_msf_capture_events[4] == 6u);
    assert(q_msf_capture_block25_address == 0x12fffful && q_msf_capture_buffer_address == 0x234567ul && q_msf_capture_source_kind == 0xe1u);
    assert(q_msf_capture_sense_key == 4u && q_msf_capture_asc_ascq == 0x4400u && q_msf_capture_sense_information == 0x89abcdeful);
    assert(read_count == 4u && read_trace[0] == 0x001598ul && read_trace[1] == 0x001599ul && read_trace[2] == 0x00159aul && read_trace[3] == 0x00159bul && write_count == 0u);

    clear_memory(0u);
    reset_q_msf_sector_capture_observers();
    firmware_memory[0x12ffffu] = 0x12u;
    firmware_memory[0x120000u] = 0x34u;
    firmware_memory[0x120001u] = 0x56u;
    q_msf_capture_capacity_result = 2u;
    q_msf_capture_result = 0xfeu;
    assert(CaptureRawSectorUsingQMsfAndPopulateSubheader(0x12fffful, 0xabcdeful, 6u) == 1u);
    assert(q_msf_capture_event_count == 4u && q_msf_capture_events[0] == 1u && q_msf_capture_events[1] == 3u && q_msf_capture_events[2] == 4u && q_msf_capture_events[3] == 7u);
    assert(q_msf_capture_block25_address == 0x12fffful && q_msf_capture_buffer_address == 0xabcdeful && q_msf_capture_source_kind == 6u && q_msf_capture_subheader_address == 0xabcdeful
           && q_msf_capture_subheader_kind == 6u);
    assert(read_count == 3u && read_trace[0] == 0x12fffful && read_trace[1] == 0x120000ul && read_trace[2] == 0x120001ul);
    assert(write_count == 3u && write_trace[0] == 0x001279ul && write_values[0] == 0x12u && write_trace[1] == 0x00127aul && write_values[1] == 0x34u && write_trace[2] == 0x00127bul
           && write_values[2] == 0x56u);
}

static void test_lookup_controller_profile_auxiliary_value(void)
{
    static const float profile_values[] = { -1.0f, 20.0f, 20.25f };
    static const u8 auxiliary_indices[] = { 0u, 4u, 0xffu };
    unsigned family, value_index, index_index;

    for(family = 0u; family < 3u; ++family)
        for(value_index = 0u; value_index < sizeof(profile_values) / sizeof(profile_values[0]); ++value_index)
            for(index_index = 0u; index_index < sizeof(auxiliary_indices) / sizeof(auxiliary_indices[0]); ++index_index)
            {
                float profile_value = profile_values[value_index];
                u8 auxiliary_index = auxiliary_indices[index_index];
                fw_addr_t base_address;
                fw_addr_t table_entry;
                u8 table_value = (u8)(0x80u + family * 9u + value_index * 3u + index_index);

                clear_memory(0u);
                firmware_memory[0xfb5eu] = (u8)family;
                if(profile_value > 20.0f)
                    base_address = family == 1u ? 0xf83ef2ul : 0xf83ec5ul;
                else
                    base_address = family == 1u ? 0xf83ee3ul : 0xf83eb6ul;
                table_entry = FirmwareAddressIncrementLow16(base_address, auxiliary_index);
                firmware_memory[table_entry] = table_value;

                assert(LookupControllerProfileAuxiliaryValue(profile_value, auxiliary_index) == (s8)table_value);
                assert(read_count == 2u && read_trace[0] == 0x00fb5eul && read_trace[1] == table_entry && write_count == 0u);
            }

    {
        union
        {
            u32 bits;
            float value;
        } quiet_nan;

        clear_memory(0u);
        quiet_nan.bits = 0x7fc00000ul;
        firmware_memory[0xfb5eu] = 1u;
        firmware_memory[0xf83ee5u] = 0x81u;
        assert(LookupControllerProfileAuxiliaryValue(quiet_nan.value, 2u) == (s8)0x81u);
        assert(read_count == 2u && read_trace[1] == 0xf83ee5ul);
    }
}

static void test_validate_and_apply_atip_packet_for_mode(void)
{
    static const u8 capability_values[] = { 0u, 1u, 0xffu };
    static const u8 mode_values[] = { 0u, 2u, 0xffu };
    unsigned marker, packet_format, capability_index, mode_index;

    clear_memory(0u);
    for(marker = 0u; marker < 256u; ++marker)
        for(packet_format = 0u; packet_format < 8u; ++packet_format)
            for(capability_index = 0u; capability_index < sizeof(capability_values); ++capability_index)
                for(mode_index = 0u; mode_index < sizeof(mode_values); ++mode_index)
                {
                    u8 capability = capability_values[capability_index];
                    u8 mode = mode_values[mode_index];
                    u8 selector = (u8)packet_format;
                    u8 expected = 0u;
                    unsigned expected_reads;

                    firmware_memory[0xfb5bu] = (u8)marker;
                    firmware_memory[0xfb7eu] = (u8)packet_format;
                    firmware_memory[0x1306u] = capability;
                    read_count = 0u;
                    write_count = 0u;
                    atip_packet_validation_decode_count = 0u;

                    if(marker >= 0xe0u)
                    {
                        if((capability & 1u) != 0u && mode == 2u)
                            selector = 7u;
                        if(selector == 6u)
                            expected = (u8)(marker == 0xf8u);
                        else if(selector == 7u)
                            expected = (u8)(marker == 0xfcu);
                        else if(selector == 4u)
                            expected = (u8)(marker == 0xf0u);
                        else
                            expected = 1u;
                    }

                    assert(ValidateAndApplyAtipPacketForMode(mode) == expected);
                    assert(atip_packet_validation_decode_count == expected);
                    assert(write_count == 0u);
                    expected_reads = marker < 0xe0u ? 1u : (selector == 4u || selector == 6u || selector == 7u ? 4u : 3u);
                    assert(read_count == expected_reads);
                    assert(read_trace[0] == 0x00fb5bul);
                    if(marker >= 0xe0u)
                    {
                        assert(read_trace[1] == 0x00fb7eul && read_trace[2] == 0x001306ul);
                        if(expected_reads == 4u)
                            assert(read_trace[3] == 0x00fb5bul);
                    }
                }
}

static void test_decode_atip_time_fields_and_frame_positions(void)
{
    static const fw_addr_t expected_writes[] = { 0x00113ful, 0x001140ul, 0x001141ul, 0x00113bul, 0x00113cul, 0x00113dul, 0x00102ful, 0x00114ful, 0x001150ul, 0x001151ul, 0x001152ul, 0x000fe9ul,
        0x000feaul, 0x000febul, 0x000fecul, 0x00102ful, 0x001153ul, 0x001154ul, 0x001155ul, 0x001156ul, 0x00fb8cul, 0x00fb8dul, 0x00fb8eul, 0x00fb8ful };
    static const u8 expected_events[] = { 1u, 2u, 3u };
    unsigned index;

    clear_memory(0u);
    firmware_memory[0xfb53u] = 0x97u;
    firmware_memory[0xfb54u] = 0x26u;
    firmware_memory[0xfb55u] = 0x45u;
    firmware_memory[0xfb57u] = 0x79u;
    firmware_memory[0xfb58u] = 0x59u;
    firmware_memory[0xfb59u] = 0x74u;
    firmware_memory[0x1008u] = 2u;
    atip_decode_inherited_offset = 0xa6u;
    atip_decode_published_offset = 0u;
    atip_decode_event_count = 0u;
    read_count = 0u;
    write_count = 0u;

    DecodeAtipTimeFieldsAndFramePositions();

    assert(firmware_memory[0x113fu] == 97u && firmware_memory[0x1140u] == 26u && firmware_memory[0x1141u] == 45u);
    assert(firmware_memory[0x113bu] == 79u && firmware_memory[0x113cu] == 59u && firmware_memory[0x113du] == 74u);
    assert((s32)get_memory_big_endian_u32(0x114fu) == (s32)-11505L);
    assert((s32)get_memory_big_endian_u32(0x0fe9u) == (s32)-11505L);
    assert(get_memory_big_endian_u32(0x1153u) == 359999ul);
    assert(get_memory_big_endian_u32(0xfb8cu) == 359999ul);
    assert(firmware_memory[0x102fu] == 0u);
    assert(atip_decode_event_count == sizeof(expected_events));
    for(index = 0u; index < sizeof(expected_events); ++index)
        assert(atip_decode_events[index] == expected_events[index]);
    assert(atip_decode_published_offset == 0xa6u);
    assert(write_count == sizeof(expected_writes) / sizeof(expected_writes[0]));
    for(index = 0u; index < write_count; ++index)
        assert(write_trace[index] == expected_writes[index]);

    firmware_memory[0x1008u] = 1u;
    atip_decode_event_count = 0u;
    DecodeAtipTimeFieldsAndFramePositions();
    assert(atip_decode_event_count == 2u && atip_decode_events[0] == 1u && atip_decode_events[1] == 2u);
}

static void test_enqueue_raw_read_descriptor_and_advance_q_state_for_index(void)
{
    static const u8 forward_events[] = { 1u, 2u, 3u, 3u, 5u };
    static const u8 reverse_events[] = { 1u, 2u, 4u, 3u, 5u };
    unsigned index;

    clear_memory(0u);
    firmware_memory[0x0c44u] = 1u;
    set_memory_big_endian_u32(0x1598u, 0xfffffffful);
    set_memory_big_endian_u32(0x126eu, 0x00123456ul);
    indexed_descriptor_event_count = 0u;
    indexed_descriptor_msf_address_count = 0u;
    read_count = 0u;
    write_count = 0u;
    EnqueueRawReadDescriptorAndAdvanceQStateForIndex(0xffffu);
    assert(indexed_descriptor_event_count == sizeof(forward_events));
    for(index = 0u; index < sizeof(forward_events); ++index)
        assert(indexed_descriptor_events[index] == forward_events[index]);
    assert(indexed_descriptor_decrement_argument == 0u && indexed_descriptor_skip_argument == 0u);
    assert(indexed_descriptor_msf_address_count == 2u && indexed_descriptor_msf_addresses[0] == 0x001275ul && indexed_descriptor_msf_addresses[1] == 0x001279ul);
    assert(indexed_descriptor_ring_cursor == 0x00123456ul);
    assert(get_memory_big_endian_u32(0x1598u) == 0u);
    assert(firmware_memory[0x1033u] == 0u);
    assert(read_trace[0] == 0x000c44ul && read_trace[1] == 0x001030ul && read_trace[2] == 0x001030ul);
    assert(write_count == 8u && write_trace[0] == 0x001033ul && write_trace[1] == 0x001033ul && write_trace[2] == 0x001033ul && write_trace[3] == 0x001033ul);

    clear_memory(0u);
    firmware_memory[0x0c44u] = 2u;
    firmware_memory[0xb4bfu + (3u << 3)] = 0u;
    firmware_memory[0x1030u] = 1u;
    set_memory_big_endian_u32(0x1598u, 0x12345678ul);
    set_memory_big_endian_u32(0x126eu, 0x00000930ul);
    indexed_descriptor_event_count = 0u;
    indexed_descriptor_msf_address_count = 0u;
    read_count = 0u;
    write_count = 0u;
    EnqueueRawReadDescriptorAndAdvanceQStateForIndex(3u);
    assert(indexed_descriptor_event_count == sizeof(reverse_events));
    for(index = 0u; index < sizeof(reverse_events); ++index)
        assert(indexed_descriptor_events[index] == reverse_events[index]);
    assert(indexed_descriptor_decrement_argument == 1u && indexed_descriptor_skip_argument == 0u);
    assert(indexed_descriptor_msf_address_count == 2u && indexed_descriptor_msf_addresses[0] == 0x001275ul && indexed_descriptor_msf_addresses[1] == 0x001279ul);
    assert(read_trace[0] == 0x000c44ul && read_trace[1] == 0x000b4d7ul && read_trace[2] == 0x001030ul);
    assert(write_count == 5u && write_trace[0] == 0x001033ul);
    assert(get_memory_big_endian_u32(0x1598u) == 0x12345679ul);
    assert(indexed_descriptor_ring_cursor == 0x00000930ul);
}

