    write_count = 0u;
    FinalizePmaStartFramePosition();
    assert(get_memory_big_endian_u32(0x1143u) == 10000ul);
    assert(read_count == 20u && write_count == 4u);

    set_memory_big_endian_u32(0x1235u, 8000ul);
