    set_memory_big_endian_u32(0x1143u, 9985ul);
    read_count = 0u;
    write_count = 0u;
    FinalizePmaStartFramePosition();
    assert(get_memory_big_endian_u32(0x1143u) == 9980ul);
    assert(read_count == 24u && write_count == 4u);

    set_memory_big_endian_u32(0x1143u, 9990ul);
    read_count = 0u;
    write_count = 0u;
    FinalizePmaStartFramePosition();
    assert(get_memory_big_endian_u32(0x1143u) == 9990ul);
