static void test_handle_read_track_information_command(void)
{
    static const unsigned invalid_events[] = { 1u, 2u };
    static const unsigned builder_failure_events[] = { 1u, 3u, 4u, 5u };
    static const unsigned zero_length_events[] = { 1u, 3u, 4u, 5u, 9u };
    static const unsigned capacity_events[] = { 1u, 3u, 4u, 7u, 8u };
    static const unsigned track_events[] = { 1u, 3u, 4u, 6u, 8u, 9u };

    clear_memory(0u);
    reset_read_track_information_observers();
    read_track_information_validate_result = 0u;
    HandleReadTrackInformationCommand();
    assert_read_track_information_events(invalid_events, 2u);
    assert(read_track_information_seen_mask == 0xff8cf5ul && read_count == 0u && write_count == 0u);

    clear_memory(0u);
    reset_read_track_information_observers();
    read_track_information_full_toc_result = 0u;
    HandleReadTrackInformationCommand();
    assert_read_track_information_events(builder_failure_events, 4u);
    assert(read_track_information_seen_allocation_address == 0x000b11ul && read_track_information_seen_clamp_value == 0xffffu && read_track_information_seen_clamp_limit == 0x001cu);
    assert(read_count == 1u && read_trace[0] == 0x001008ul && write_count == 0u);

    clear_memory(0u);
    reset_read_track_information_observers();
    read_track_information_clamped_value = 0u;
    HandleReadTrackInformationCommand();
    assert_read_track_information_events(zero_length_events, 5u);
    assert(read_count == 1u && read_trace[0] == 0x001008ul);

    clear_memory(0u);
    reset_read_track_information_observers();
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x0c9eu] = 1u;
    read_track_information_transfer_result = 4u;
    HandleReadTrackInformationCommand();
    assert_read_track_information_events(capacity_events, 5u);
    assert(read_count == 2u && read_trace[0] == 0x001008ul && read_trace[1] == 0x000c9eul);
    assert(read_track_information_seen_transfer_source == 0x000b2aul && read_track_information_seen_transfer_count == 0x001cul);

    clear_memory(0u);
    reset_read_track_information_observers();
    firmware_memory[0x1008u] = 1u;
    read_track_information_clamped_value = 7u;
    HandleReadTrackInformationCommand();
    assert_read_track_information_events(track_events, 6u);
    assert(read_count == 2u && read_trace[0] == 0x001008ul && read_trace[1] == 0x000c9eul);
    assert(read_track_information_seen_transfer_source == 0x000b2aul && read_track_information_seen_transfer_count == 7ul);

    clear_memory(0u);
    reset_read_track_information_observers();
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x0c9eu] = 1u;
    read_track_information_capacity_result = 0u;
    HandleReadTrackInformationCommand();
    assert(read_track_information_event_count == 4u && read_track_information_events[3] == 7u && read_count == 2u);

    clear_memory(0u);
    reset_read_track_information_observers();
    firmware_memory[0x1008u] = 1u;
    read_track_information_track_state_result = 0u;
    HandleReadTrackInformationCommand();
    assert(read_track_information_event_count == 4u && read_track_information_events[3] == 6u && read_count == 2u);
}

static void test_compute_read_track_information_track_size(void)
{
    unsigned track;

    clear_memory(0u);
    for(track = 0u; track < 256u; ++track)
    {
        fw_addr_t record = 0x2bb03bul + (fw_addr_t)track * 10ul;
        u32 first_bits = 0x7fffff00ul + track;
        u32 second_bits = 0x80000080ul - track;
        s32 expected = (s32)(second_bits - first_bits - 2ul);

        firmware_memory[record + 2u] = (u8)track;
        read_count = 0u;
        write_count = 0u;
        read_track_size_conversion_count = 0u;
        read_track_size_fallback_count = 0u;
        read_track_size_conversion_results[0] = (s32)first_bits;
        read_track_size_conversion_results[1] = (s32)second_bits;

        assert(ComputeReadTrackInformationTrackSize((u8)track) == expected);
        assert(read_count == 1u && read_trace[0] == record + 2u && write_count == 0u);
        assert(read_track_size_conversion_count == 2u && read_track_size_conversion_addresses[0] == record + 7u && read_track_size_conversion_addresses[1] == record + 3u
               && read_track_size_fallback_count == 0u);

        firmware_memory[record + 2u] = (u8)(track + 1u);
        read_count = 0u;
        write_count = 0u;
        read_track_size_conversion_count = 0u;
        read_track_size_fallback_count = 0u;
        read_track_size_fallback_result = (s32)(0xa5000000ul | track);

        assert(ComputeReadTrackInformationTrackSize((u8)track) == read_track_size_fallback_result);
        assert(read_count == 1u && read_trace[0] == record + 2u && write_count == 0u);
        assert(read_track_size_conversion_count == 0u && read_track_size_fallback_count == 1u && read_track_size_fallback_track == (u8)track);
    }
}

