static void test_finalize_working_track_after_repair_or_cache_sync(void)
{
    clear_memory(0u);
    reset_working_track_finalizer_observers();
    bit_0030 = 1u;
    working_track_finalizer_ensure_result = 0u;
    FinalizeWorkingTrackAfterRepairOrCacheSync();
    assert(working_track_finalizer_event_count == 5u && working_track_finalizer_events[0] == 1u && working_track_finalizer_events[1] == 2u && working_track_finalizer_events[2] == 3u
           && working_track_finalizer_events[3] == 4u && working_track_finalizer_events[4] == 5u);
    assert(bit_0030 == 0u && working_track_finalizer_coroutine_entry == 0x00f84a00ul && read_count == 0u && write_count == 0u);

    clear_memory(0u);
    reset_working_track_finalizer_observers();
    firmware_memory[0x0c84u] = 0x80u;
    working_track_finalizer_prepare_result = 0u;
    FinalizeWorkingTrackAfterRepairOrCacheSync();
    assert(working_track_finalizer_event_count == 6u && working_track_finalizer_events[0] == 2u && working_track_finalizer_events[1] == 3u && working_track_finalizer_events[2] == 4u
           && working_track_finalizer_events[3] == 5u && working_track_finalizer_events[4] == 6u && working_track_finalizer_events[5] == 7u);
    assert(read_count == 3u && write_count == 3u);
    assert(read_trace[0] == 0x000c84ul && read_trace[1] == 0x000c84ul && read_trace[2] == 0x000c84ul);
    assert(write_trace[0] == 0x000c84ul && write_values[0] == 0xc0u && write_trace[1] == 0x000c84ul && write_values[1] == 0x40u && write_trace[2] == 0x000c84ul && write_values[2] == 0u);

    clear_memory(0u);
    reset_working_track_finalizer_observers();
    firmware_memory[0x0c84u] = 0x81u;
    set_memory_big_endian_u32(0x1488u, 0x89abcdeful);
    firmware_memory[0xdd34u] = 6u;
    FinalizeWorkingTrackAfterRepairOrCacheSync();
    assert(working_track_finalizer_event_count == 6u && working_track_finalizer_events[4] == 6u && working_track_finalizer_events[5] == 8u);
    assert(working_track_finalizer_opcode == 0x35u);
    assert(read_count == 7u && write_count == 7u);
    assert(read_trace[0] == 0x000c84ul && read_trace[1] == 0x000c84ul && read_trace[2] == 0x001488ul && read_trace[3] == 0x001489ul && read_trace[4] == 0x00148aul && read_trace[5] == 0x00148bul
           && read_trace[6] == 0x00dd34ul);
    assert(firmware_memory[0x0c84u] == 0x81u && firmware_memory[0xdd45u] == 0x89u && firmware_memory[0xdd46u] == 0xabu && firmware_memory[0xdd47u] == 0xcdu && firmware_memory[0xdd48u] == 0xefu
           && firmware_memory[0xdd34u] == 1u);

    clear_memory(0u);
    reset_working_track_finalizer_observers();
    firmware_memory[0xdd34u] = 5u;
    FinalizeWorkingTrackAfterRepairOrCacheSync();
    assert(read_count == 8u && write_count == 7u && read_trace[6] == 0x00dd34ul && read_trace[7] == 0x00dd34ul && firmware_memory[0xdd34u] == 3u);

    clear_memory(0u);
    reset_working_track_finalizer_observers();
    firmware_memory[0xdd34u] = 4u;
    FinalizeWorkingTrackAfterRepairOrCacheSync();
    assert(read_count == 8u && write_count == 6u && read_trace[6] == 0x00dd34ul && read_trace[7] == 0x00dd34ul && firmware_memory[0xdd34u] == 4u);
}

