static void test_update_working_track_after_write_failure(void)
{
    static const u8 initial_types[] = { 0u, 1u, 2u, 3u, 4u, 5u, 6u, 7u };
    static const u8 expected_types[] = { 6u, 6u, 5u, 5u, 4u, 5u, 6u, 7u };
    unsigned index;

    clear_memory(0u);
    reset_write_failure_update_observers();
    set_memory_big_endian_u16(0x0b24u, 0x1234u);
    firmware_memory[0x0c46u] = 1u;
    read_count = write_count = 0u;
    UpdateWorkingTrackAfterWriteFailure();
    assert(read_count == 3u && read_trace[0] == 0x000b24ul && read_trace[1] == 0x000b25ul && read_trace[2] == 0x000c46ul);
    assert(write_count == 2u && write_trace[0] == 0x000c3aul && write_trace[1] == 0x000c3bul && get_memory_big_endian_u16(0x0c3au) == 0x1234u);
    assert(write_failure_finalize_count == 0u && write_failure_update_track_count == 0u);

    clear_memory(0u);
    reset_write_failure_update_observers();
    set_memory_big_endian_u16(0x0b24u, 0x0c09u);
    set_memory_big_endian_u32(0xdd4du, 0x7ffffffful);
    read_count = write_count = 0u;
    UpdateWorkingTrackAfterWriteFailure();
    assert(read_count == 15u && write_count == 14u);
    assert(get_memory_big_endian_u32(0xdd4du) == 0x80000001ul && get_memory_big_endian_u32(0xdd45u) == 0x80000001ul && get_memory_big_endian_u32(0xdd5bu) == 0ul);
    assert(write_failure_finalize_count == 1u && write_failure_finalize_opcode == 0x35u && write_failure_finalize_seen_write_count == 14u && write_failure_update_track_count == 0u);

    clear_memory(0u);
    reset_write_failure_update_observers();
    set_memory_big_endian_u16(0x0b24u, 0x0c09u);
    firmware_memory[0x0c46u] = 2u;
    read_count = write_count = 0u;
    UpdateWorkingTrackAfterWriteFailure();
    assert(read_count == 8u && write_count == 2u && read_trace[2] == 0x000c46ul && read_trace[5] == 0x000c44ul && read_trace[6] == 0x000c46ul && read_trace[7] == 0x00128cul);
    assert(write_failure_finalize_count == 0u && write_failure_update_track_count == 0u);

    clear_memory(0u);
    reset_write_failure_update_observers();
    set_memory_big_endian_u16(0x0b24u, 0x0200u);
    firmware_memory[0x128cu] = 1u;
    read_count = write_count = 0u;
    UpdateWorkingTrackAfterWriteFailure();
    assert(read_count == 8u && write_count == 2u && write_failure_update_track_count == 0u);

    for(index = 0u; index != sizeof(initial_types) / sizeof(initial_types[0]); ++index)
    {
        clear_memory(0u);
        reset_write_failure_update_observers();
        set_memory_big_endian_u16(0x0b24u, 0x1234u);
        firmware_memory[0x128cu] = 1u;
        firmware_memory[0x0c84u] = 0x22u;
        firmware_memory[0xdd34u] = initial_types[index];
        set_memory_big_endian_u32(0x1484u, 0x89abcdeful);
        firmware_memory[0x0c44u] = 1u;
        firmware_memory[0x1287u] = 0x80u;
        read_count = write_count = 0u;
        UpdateWorkingTrackAfterWriteFailure();
        assert(read_count == 16u);
        assert(write_count == (initial_types[index] < 4u ? 13u : 12u));
        assert(firmware_memory[0x0c84u] == 0xa2u && firmware_memory[0xdd34u] == expected_types[index] && get_memory_big_endian_u32(0xdd51u) == 0x89abcdeful
               && get_memory_big_endian_u32(0xdd4du) == 0x89abcdeful && firmware_memory[0xdd38u] == 0x80u);
        assert(write_failure_finalize_count == 0u && write_failure_update_track_count == 1u && write_failure_update_seen_write_count == write_count);
    }

    clear_memory(0u);
    reset_write_failure_update_observers();
    set_memory_big_endian_u16(0x0b24u, 0x0200u);
    firmware_memory[0x128cu] = 1u;
    bit_0031 = 1u;
    firmware_memory[0xdd34u] = 4u;
    set_memory_big_endian_u32(0x1484u, 0x10203040ul);
    read_count = write_count = 0u;
    UpdateWorkingTrackAfterWriteFailure();
    assert(write_failure_update_track_count == 1u && get_memory_big_endian_u32(0xdd4du) == 0x10203040ul && read_count == 15u && write_count == 11u);
}

