    static const fw_addr_t expected_writes[9] = { 0x001037ul, 0x000c88ul, 0x000c89ul, 0x000c8aul, 0x000c85ul, 0x000c84ul, 0x000c85ul, 0x000c84ul, 0x000c8aul };
