static void test_initialize_then_idle_coroutine2(void)
{
    clear_memory(0xa5u);
    coroutine2_entry_reset_count = 0u;
    coroutine2_entry_yield_count = 0u;
    coroutine2_entry_escape_after = 3u;

    if(setjmp(coroutine2_entry_escape) == 0)
    {
        InitializeThenIdleCoroutine2();
        assert(0);
    }
    coroutine2_entry_escape_after = 0u;

    assert(firmware_memory[0x1591u] == 0u && firmware_memory[0x0f4au] == 0u);
    assert(read_count == 0u && write_count == 2u);
    assert(write_trace[0] == 0x001591ul && write_values[0] == 0u && write_trace[1] == 0x000f4aul && write_values[1] == 0u);
    assert(coroutine2_entry_reset_count == 1u && coroutine2_entry_yield_count == 3u);
}

