static void test_finalize_raw_read_pipeline_and_idle_coroutine2(void)
{
    clear_memory(0xa5u);
    reset_raw_read_finalizer_observers(2u);
    firmware_memory[0x0f46u] = 1u;
    bit_0008 = bit_0022 = bit_001f = 1u;
    if(setjmp(coroutine2_entry_escape) == 0)
    {
        FinalizeRawReadPipelineAndIdleCoroutine2();
        assert(0);
    }
    assert(coroutine2_finalizer_initialize_count == 1u && coroutine2_finalizer_dispatch_count == 1u && coroutine2_entry_yield_count == 2u);
    assert(firmware_memory[0x0e44u] == 1u && firmware_memory[0x0e4au] == 0u && get_memory_big_endian_u32(0x0f10u) == 0xfffffff6ul && firmware_memory[0x0f3bu] == 0u && firmware_memory[0x0f48u] == 0u
           && firmware_memory[0x0f46u] == 0u && firmware_memory[0x0f07u] == 0u && bit_0008 == 0u && bit_0022 == 0u && bit_001f == 0u);
    assert(read_count == 1u && read_trace[0] == 0x000f46ul && write_count == 10u && write_trace[0] == 0x000e44ul && write_trace[3] == 0x000f10ul && write_trace[6] == 0x000f13ul
           && write_trace[7] == 0x000f48ul && write_trace[9] == 0x000f07ul);

    clear_memory(0u);
    reset_raw_read_finalizer_observers(2u);
    firmware_memory[0x1037u] = 4u;
    firmware_memory[0x0e46u] = 0x37u;
    if(setjmp(coroutine2_entry_escape) == 0)
    {
        FinalizeRawReadPipelineAndIdleCoroutine2();
        assert(0);
    }
    assert(firmware_memory[0x0e49u] == 0x37u && read_count == 3u && read_trace[0] == 0x000f46ul && read_trace[1] == 0x001037ul && read_trace[2] == 0x000e46ul);

    clear_memory(0u);
    reset_raw_read_finalizer_observers(2u);
    firmware_memory[0x1037u] = 5u;
    firmware_memory[0x0f45u] = 0x7fu;
    if(setjmp(coroutine2_entry_escape) == 0)
    {
        FinalizeRawReadPipelineAndIdleCoroutine2();
        assert(0);
    }
    assert(firmware_memory[0x0e46u] == 0x7fu && firmware_memory[0x0e49u] == 0x7fu && read_count == 4u && read_trace[2] == 0x000f45ul && read_trace[3] == 0x000f45ul);

    clear_memory(0u);
    reset_raw_read_finalizer_observers(3u);
    coroutine2_finalizer_clear_busy_after = 2u;
    firmware_memory[0x1037u] = 5u;
    firmware_memory[0x0f45u] = 0x80u;
    firmware_memory[0x0e40u] = 1u;
    firmware_memory[0x0ff9u] = 0xa1u;
    bit_0005 = bit_0008 = bit_0022 = bit_001f = 1u;
    if(setjmp(coroutine2_entry_escape) == 0)
    {
        FinalizeRawReadPipelineAndIdleCoroutine2();
        assert(0);
    }
    assert(coroutine2_finalizer_initialize_count == 1u && coroutine2_finalizer_dispatch_count == 1u && coroutine2_entry_yield_count == 3u && firmware_memory[0x0e40u] == 0u
           && firmware_memory[0x0ff9u] == 0xa1u && bit_0008 == 0u && bit_0022 == 0u && bit_001f == 0u);
    assert(read_count == 7u && read_trace[3] == 0x000ff9ul && read_trace[4] == 0x000e40ul && read_trace[5] == 0x000e40ul && read_trace[6] == 0x000ff9ul);
    assert(write_count == 8u && write_trace[6] == 0x000ff9ul && write_values[6] == 0xa5u && write_trace[7] == 0x000ff9ul && write_values[7] == 0xa1u);

    coroutine2_entry_escape_after = 0u;
    coroutine2_finalizer_clear_busy_after = 0u;
}

