static void test_return_empty_cd_text_response(void)
{
    static const u16 counts[] = { 0u, 1u, 4u, 5u, 0xffffu };
    static const u8 phases[] = { 12u, 13u };
    unsigned count_index, phase_index;
    for(count_index = 0u; count_index < 5u; ++count_index)
        for(phase_index = 0u; phase_index < 2u; ++phase_index)
        {
            u16 transfer_count = counts[count_index] > 4u ? 4u : counts[count_index];
            u8 successful_transfer = (u8)(transfer_count != 0u && phases[phase_index] != 13u);

            clear_memory(0xa5u);
            set_memory_big_endian_u32(0x155au, 0x200ul);
            controller_data_in_transfer_phase = phases[phase_index];
            controller_data_in_transfer_call_count = 0u;
            ReturnEmptyCdTextResponse(counts[count_index]);
            assert(controller_data_in_transfer_call_count == (transfer_count == 0u ? 0u : 1u));
            if(transfer_count != 0u)
            {
                assert(controller_data_in_transfer_length == transfer_count);
                assert(controller_data_in_transfer_offset == 0x200ul);
                assert(firmware_memory[0x100200ul] == 0u);
            }
            assert(firmware_memory[0x0b2a] == 0u && firmware_memory[0x0b2b] == 2u && firmware_memory[0x0b2c] == 0u && firmware_memory[0x0b2d] == 0u && firmware_memory[0x0c2a] == 7u);
            if(successful_transfer == 0u)
                assert(firmware_memory[0x0b18] == 0x70u);
            else
                assert(firmware_memory[0x0b18] == 0xa5u);
        }
}

static void test_start_play_audio_frame_range(void)
{
    static const s32 starts[] = { 0, 0x1234, -2 };
    static const s32 ends[] = { 1, 0x1278, 0x7fffffff };
    static const u8 modes[] = { 0u, 1u, 0xffu };
    unsigned start_index, end_index, mode_index;

    for(start_index = 0u; start_index < sizeof(starts) / sizeof(starts[0]); ++start_index)
        for(end_index = 0u; end_index < sizeof(ends) / sizeof(ends[0]); ++end_index)
            for(mode_index = 0u; mode_index < sizeof(modes) / sizeof(modes[0]); ++mode_index)
            {
                clear_memory(0u);
                firmware_memory[0x0c8cu] = 0xa5u;
                firmware_memory[0x0fbau] = 0x80u;
                bit_0018 = 1u;
                format2_raw_read_start_call_count = 0u;
                StartPlayAudioFrameRange(starts[start_index], ends[end_index], modes[mode_index]);
                assert(firmware_memory[0x0c2aul] == 5u && firmware_memory[0x0fbau] == 0x84u && firmware_memory[0x0c8cu] == 0xa5u && firmware_memory[0x0c8du] == (modes[mode_index] != 0u ? 1u : 0u)
                       && get_memory_big_endian_u32(0x0f36u) == (u32)ends[end_index] - (u32)starts[start_index] && bit_0018 == 0u && format2_raw_read_start_call_count == 1u
                       && format2_raw_read_start_seen == starts[start_index]);
            }

    clear_memory(0u);
    firmware_memory[0x0c8du] = 0xa5u;
    firmware_memory[0x0fbau] = 0x80u;
    yield_coroutine0_auto_complete_after = 1u;
    yield_coroutine0_auto_complete_result = 0u;
    format2_raw_read_start_call_count = 0u;
    StartPlayAudioFrameRange(0x1234, 0x1234, 1u);
    assert(firmware_memory[0x0c2aul] == 5u && firmware_memory[0x0c8cu] == 3u && get_memory_big_endian_u32(0x0c8eu) == 0x1234ul && firmware_memory[0x0c8du] == 0xa5u
           && format2_raw_read_start_call_count == 0u && yield_coroutine0_count == 1u);
}

