static void test_validate_and_start_play_audio_msf_range(void)
{
    const fw_addr_t end_tuple = 0x0200ul;
    const fw_addr_t start_tuple = 0x0210ul;

    clear_memory(0u);
    reset_play_audio_msf_range_observers();
    play_audio_msf_validation_results[0] = 0u;
    ValidateAndStartPlayAudioMsfRangeFromCdbTuplesForTest(end_tuple, start_tuple, 1u);
    assert(play_audio_msf_validation_count == 1u && play_audio_msf_validation_trace[0] == start_tuple && play_audio_msf_reject_count == 1u && play_audio_msf_conversion_count == 0u
           && play_audio_range_event_count == 0u);

    clear_memory(0u);
    reset_play_audio_msf_range_observers();
    play_audio_msf_validation_results[1] = 0u;
    ValidateAndStartPlayAudioMsfRangeFromCdbTuplesForTest(end_tuple, start_tuple, 1u);
    assert(play_audio_msf_validation_count == 2u && play_audio_msf_validation_trace[0] == start_tuple && play_audio_msf_validation_trace[1] == end_tuple && play_audio_msf_reject_count == 1u
           && play_audio_msf_conversion_count == 0u);

    clear_memory(0u);
    reset_play_audio_msf_range_observers();
    play_audio_msf_conversion_results[0] = 123l;
    play_audio_msf_conversion_results[1] = 456l;
    play_audio_range_validation_result = 1u;
    ValidateAndStartPlayAudioMsfRangeFromCdbTuplesForTest(end_tuple, start_tuple, 0x7fu);
    assert(play_audio_msf_conversion_count == 2u && play_audio_msf_conversion_trace[0] == start_tuple && play_audio_msf_conversion_trace[1] == end_tuple);
    assert(play_audio_range_event_count == 2u && play_audio_range_events[0] == 1u && play_audio_range_events[1] == 4u && play_audio_range_validation_start == 123l
           && play_audio_range_validation_end == 456l && play_audio_range_started_start == 123l && play_audio_range_started_end == 456l && play_audio_range_started_mode == 0x7fu);

    clear_memory(0u);
    reset_play_audio_msf_range_observers();
    firmware_memory[start_tuple] = 0xffu;
    firmware_memory[start_tuple + 1u] = 0xffu;
    firmware_memory[start_tuple + 2u] = 0xffu;
    play_audio_msf_validation_results[0] = 0u;
    ValidateAndStartPlayAudioMsfRangeFromCdbTuplesForTest(end_tuple, start_tuple, 1u);
    assert(play_audio_msf_validation_count == 1u && play_audio_msf_validation_trace[0] == end_tuple && play_audio_msf_reject_count == 1u && play_audio_msf_conversion_count == 0u);

    clear_memory(0u);
    reset_play_audio_msf_range_observers();
    firmware_memory[start_tuple] = 0xffu;
    firmware_memory[start_tuple + 1u] = 0xffu;
    firmware_memory[start_tuple + 2u] = 0xffu;
    set_memory_big_endian_u32(0x1235u, 321ul);
    firmware_memory[0x0fafu] = 1u;
    firmware_memory[0x0fbau] = 0x80u;
    play_audio_msf_conversion_results[0] = 654l;
    ValidateAndStartPlayAudioMsfRangeFromCdbTuplesForTest(end_tuple, start_tuple, 1u);
    assert(play_audio_msf_validation_count == 1u && play_audio_msf_validation_trace[0] == end_tuple && play_audio_msf_conversion_count == 1u && play_audio_msf_conversion_trace[0] == end_tuple);
    assert(play_audio_range_event_count == 2u && play_audio_range_events[0] == 2u && play_audio_range_events[1] == 3u && play_audio_range_resume_end == 654l && firmware_memory[0x0fbau] == 0x88u);

    clear_memory(0u);
    reset_play_audio_msf_range_observers();
    firmware_memory[start_tuple] = 0xffu;
    firmware_memory[start_tuple + 1u] = 0xffu;
    firmware_memory[start_tuple + 2u] = 0xffu;
    set_memory_big_endian_u32(0x1235u, 321ul);
    firmware_memory[0x0fafu] = 1u;
    firmware_memory[0x0fbau] = 0x10u;
    play_audio_msf_conversion_results[0] = 654l;
    play_audio_range_validation_result = 1u;
    ValidateAndStartPlayAudioMsfRangeFromCdbTuplesForTest(end_tuple, start_tuple, 0x55u);
    assert(play_audio_range_event_count == 2u && play_audio_range_events[0] == 1u && play_audio_range_events[1] == 4u && play_audio_range_validation_start == 321l
           && play_audio_range_validation_end == 654l && play_audio_range_started_start == 321l && play_audio_range_started_end == 654l && play_audio_range_started_mode == 0x55u
           && firmware_memory[0x0fbau] == 0x10u);
}

