static void SetPlayTrackRelativeCdb(u8 track_number, s32 relative_start, u32 frame_count)
{
    set_memory_big_endian_u32(0x0b0cu, (u32)relative_start);
    set_memory_big_endian_u32(0x0b10u, frame_count);
    firmware_memory[0x0b14u] = track_number;
}

static void test_handle_play_track_relative12_command(void)
{
    clear_memory(0xa5u);
    reset_play_track_relative_observers();
    play_track_relative_cdb_result = 0u;
    HandlePlayTrackRelative12CommandForTest();
    assert(play_track_relative_cdb_count == 1u);
    assert(play_track_relative_cdb_mask == 0xff8d70ul);
    assert(play_track_relative_reject_count == 1u);
    assert(play_track_relative_range_count == 0u);

    clear_memory(0u);
    reset_play_track_relative_observers();
    SetPlayTrackRelativeCdb(2u, 10l, 50ul);
    play_track_relative_range_result = 0u;
    HandlePlayTrackRelative12CommandForTest();
    assert(play_track_relative_range_count == 1u && play_track_relative_range_args[0] == 2u && play_track_relative_range_args[1] == 2u && play_track_relative_range_args[2] == 1u
           && play_track_relative_range_args[3] == 1u && play_track_relative_conversion_count == 0u);

    clear_memory(0u);
    reset_play_track_relative_observers();
    SetPlayTrackRelativeCdb(2u, 100l, 50ul);
    play_track_relative_conversion_results[0] = 100l;
    play_track_relative_conversion_results[1] = 200l;
    HandlePlayTrackRelative12CommandForTest();
    assert(play_track_relative_reject_count == 1u && play_track_relative_conversion_trace[0] == 0x00f2c5ul && play_track_relative_conversion_trace[1] == 0x00f2cbul
           && play_track_relative_start_count == 0u);

    clear_memory(0u);
    reset_play_track_relative_observers();
    SetPlayTrackRelativeCdb(2u, 10l, 50ul);
    set_memory_big_endian_u32(0x12c1u, 1000ul);
    firmware_memory[0x0fbau] = 0x80u;
    bit_0018 = 1u;
    play_track_relative_conversion_results[0] = 100l;
    play_track_relative_conversion_results[1] = 500l;
    HandlePlayTrackRelative12CommandForTest();
    assert(firmware_memory[0x0c2au] == 5u && firmware_memory[0x0fbau] == 0x84u && firmware_memory[0x0c8du] == 0u && get_memory_big_endian_u32(0x0f36u) == 50ul
           && play_track_relative_started_frame == 110l && play_track_relative_start_count == 1u && play_track_relative_clear_bit_count == 1u && bit_0018 == 0u);

    clear_memory(0u);
    reset_play_track_relative_observers();
    SetPlayTrackRelativeCdb(2u, 10l, 20ul);
    set_memory_big_endian_u32(0x12c1u, 1000ul);
    play_track_relative_conversion_results[0] = 980l;
    play_track_relative_conversion_results[1] = 1200l;
    HandlePlayTrackRelative12CommandForTest();
    assert(play_track_relative_started_frame == 990l && get_memory_big_endian_u32(0x0f36u) == 9ul);

    clear_memory(0u);
    reset_play_track_relative_observers();
    SetPlayTrackRelativeCdb(2u, -5l, 0ul);
    set_memory_big_endian_u32(0x12c1u, 1000ul);
    play_track_relative_conversion_results[0] = 100l;
    play_track_relative_conversion_results[1] = 500l;
    HandlePlayTrackRelative12CommandForTest();
    assert(firmware_memory[0x0c2au] == 5u && firmware_memory[0x0c8cu] == 3u && get_memory_big_endian_u32(0x0c8eu) == 100ul && play_track_relative_dispatch_count == 1u
           && play_track_relative_start_count == 0u && play_track_relative_clear_bit_count == 0u);

    clear_memory(0u);
    reset_play_track_relative_observers();
    SetPlayTrackRelativeCdb(2u, 50l, 20ul);
    firmware_memory[0x1008u] = 1u;
    play_track_relative_track_starts[2] = 100l;
    play_track_relative_track_types[2] = 4u;
    play_track_relative_boundary_results[0] = 150l;
    HandlePlayTrackRelative12CommandForTest();
    assert(play_track_relative_load_count == 1u && play_track_relative_load_trace[0] == 2u && play_track_relative_boundary_count == 1u && play_track_relative_reject_count == 1u
           && play_track_relative_last_track_count == 0u);

    clear_memory(0u);
    reset_play_track_relative_observers();
    SetPlayTrackRelativeCdb(2u, 0l, 50ul);
    firmware_memory[0x1008u] = 1u;
    play_track_relative_track_starts[2] = 100l;
    play_track_relative_track_types[2] = 5u;
    play_track_relative_last_track = 4u;
    play_track_relative_track_types[4] = 4u;
    play_track_relative_boundary_results[0] = 150l;
    HandlePlayTrackRelative12CommandForTest();
    assert(play_track_relative_load_count == 2u && play_track_relative_load_trace[0] == 2u && play_track_relative_load_trace[1] == 4u && play_track_relative_boundary_count == 1u
           && play_track_relative_started_frame == 100l && get_memory_big_endian_u32(0x0f36u) == 49ul);

    clear_memory(0u);
    reset_play_track_relative_observers();
    SetPlayTrackRelativeCdb(2u, 10l, 50ul);
    firmware_memory[0x1008u] = 1u;
    play_track_relative_track_starts[2] = 100l;
    play_track_relative_track_types[2] = 5u;
    play_track_relative_last_track = 4u;
    play_track_relative_track_types[4] = 5u;
    HandlePlayTrackRelative12CommandForTest();
    assert(play_track_relative_load_count == 2u && play_track_relative_boundary_count == 0u && play_track_relative_started_frame == 110l && get_memory_big_endian_u32(0x0f36u) == 50ul);
}

