static void SetOpcodeBaCdMode(u8 positioning_mode, u8 reverse_direction)
{
    firmware_memory[0x0b13u] = (u8)(positioning_mode << 6);
    firmware_memory[0x0b0bu] = reverse_direction != 0u ? 0x10u : 0u;
}

static void test_handle_scsi_opcode_ba_cd(void)
{
    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    opcode_ba_cd_cdb_result = 0u;
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_cdb_count == 1u && opcode_ba_cd_cdb_mask == 0xff8e57ul && opcode_ba_cd_reject_count == 1u && opcode_ba_cd_start_count == 0u);

    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    SetOpcodeBaCdMode(3u, 0u);
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_reject_count == 1u && opcode_ba_cd_start_count == 0u);

    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    SetOpcodeBaCdMode(1u, 0u);
    firmware_memory[0x0b0du] = 10u;
    opcode_ba_cd_msf_result = 0u;
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_msf_count == 1u && opcode_ba_cd_msf_address == 0x000b0dul && opcode_ba_cd_reject_count == 1u && opcode_ba_cd_conversion_count == 0u);

    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    SetOpcodeBaCdMode(2u, 0u);
    firmware_memory[0x0b0fu] = 2u;
    firmware_memory[0x12c0u] = 4u;
    set_memory_big_endian_u32(0x12c1u, 500ul);
    firmware_memory[0x0fbau] = 0x80u;
    opcode_ba_cd_conversion_result = 100l;
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_conversion_count == 1u && opcode_ba_cd_conversion_address == 0x00f2c5ul && get_memory_big_endian_u32(0x0c92u) == 500ul && get_memory_big_endian_u32(0x0f36u) == 400ul
           && opcode_ba_cd_bit0018_count == 1u && opcode_ba_cd_bit0018_value == 1u && opcode_ba_cd_bit0019_count == 1u && opcode_ba_cd_bit0019_value == 0u && firmware_memory[0x0fbau] == 0x84u
           && opcode_ba_cd_started_frame == 100l);

    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    SetOpcodeBaCdMode(2u, 1u);
    firmware_memory[0x0b0fu] = 2u;
    firmware_memory[0x12c0u] = 4u;
    set_memory_big_endian_u32(0x12c1u, 500ul);
    opcode_ba_cd_conversion_result = 400l;
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_conversion_address == 0x00f2cbul && get_memory_big_endian_u32(0x0f36u) == 250ul && opcode_ba_cd_bit0019_value == 1u && opcode_ba_cd_started_frame == 382l);

    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    SetOpcodeBaCdMode(2u, 0u);
    firmware_memory[0x0b0fu] = 0u;
    firmware_memory[0x12c0u] = 4u;
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_reject_count == 1u && opcode_ba_cd_conversion_count == 0u);

    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    SetOpcodeBaCdMode(0u, 0u);
    set_memory_big_endian_u32(0x0b0cu, 100ul);
    firmware_memory[0x1008u] = 1u;
    opcode_ba_cd_last_track = 0u;
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_sense_count == 1u && opcode_ba_cd_sense_key == 5u && opcode_ba_cd_sense_code == 0x2100u && opcode_ba_cd_start_count == 0u);

    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    SetOpcodeBaCdMode(2u, 0u);
    firmware_memory[0x0b0fu] = 2u;
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x0fbau] = 0x20u;
    opcode_ba_cd_last_track = 4u;
    opcode_ba_cd_track_starts[2] = 100l;
    opcode_ba_cd_boundary_results[0] = 500l;
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_load_count == 2u && opcode_ba_cd_load_trace[0] == 2u && opcode_ba_cd_load_trace[1] == 4u && opcode_ba_cd_last_track_count == 2u && opcode_ba_cd_boundary_count == 1u
           && get_memory_big_endian_u32(0x0f36u) == 400ul && opcode_ba_cd_started_frame == 100l);

    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    SetOpcodeBaCdMode(2u, 1u);
    firmware_memory[0x0b0fu] = 2u;
    firmware_memory[0x1008u] = 1u;
    opcode_ba_cd_last_track = 4u;
    opcode_ba_cd_boundary_results[0] = 300l;
    opcode_ba_cd_boundary_results[1] = 500l;
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_boundary_count == 2u && get_memory_big_endian_u32(0x0f36u) == 150ul && opcode_ba_cd_bit0019_value == 1u && opcode_ba_cd_started_frame == 282l);

    clear_memory(0u);
    reset_opcode_ba_cd_observers();
    SetOpcodeBaCdMode(0u, 0u);
    set_memory_big_endian_u32(0x0b0cu, 851ul);
    set_memory_big_endian_u32(0x12c1u, 900ul);
    HandleScsiOpcodeBA_CD();
    assert(opcode_ba_cd_reject_count == 1u && opcode_ba_cd_start_count == 0u);
}

static void test_validate_and_start_play_audio_frame_range_body(void)
{
    clear_memory(0u);
    reset_validate_and_start_play_audio_observers();
    set_memory_big_endian_u32(0x1235u, (u32)-10l);
    ValidateAndStartPlayAudioFrameRangeForTest(-1l, 5l, 1u);
    assert(play_audio_range_event_count == 1u && play_audio_range_events[0] == 1u);
    assert(play_audio_range_validation_start == -10l && play_audio_range_validation_end == -5l);
    assert(play_audio_range_event_reads[0] == 4u && read_count == 4u && write_count == 0u);

    clear_memory(0u);
    reset_validate_and_start_play_audio_observers();
    set_memory_big_endian_u32(0x1235u, 0x7ffffffful);
    firmware_memory[0x0fafu] = 1u;
    firmware_memory[0x0fbau] = 0x80u;
    play_audio_range_validation_result = 1u;
    ValidateAndStartPlayAudioFrameRangeForTest(-1l, 2l, 1u);
    assert(play_audio_range_event_count == 3u);
    assert(play_audio_range_events[0] == 1u && play_audio_range_events[1] == 2u && play_audio_range_events[2] == 3u);
    assert(play_audio_range_validation_start == 0x7fffffffl && (u32)play_audio_range_validation_end == 0x80000001ul && (u32)play_audio_range_resume_end == 0x80000001ul);
    assert(play_audio_range_event_reads[0] == 4u && play_audio_range_event_reads[1] == 7u && play_audio_range_event_writes[1] == 1u);
    assert(read_count == 7u && write_count == 1u && write_trace[0] == 0x0fbaul && write_values[0] == 0x88u);

    clear_memory(0u);
    reset_validate_and_start_play_audio_observers();
    set_memory_big_endian_u32(0x1235u, 1000ul);
    firmware_memory[0x0fafu] = 1u;
    firmware_memory[0x0fbau] = 0u;
    play_audio_range_validation_result = 1u;
    ValidateAndStartPlayAudioFrameRangeForTest(-1l, 75l, 0u);
    assert(play_audio_range_event_count == 3u && play_audio_range_events[1] == 2u && play_audio_range_events[2] == 3u);
    assert(play_audio_range_resume_end == 1075l && read_count == 6u && write_count == 0u);

    clear_memory(0u);
    reset_validate_and_start_play_audio_observers();
    set_memory_big_endian_u32(0x1235u, 2000ul);
    firmware_memory[0x0fafu] = 2u;
    play_audio_range_validation_result = 1u;
    ValidateAndStartPlayAudioFrameRangeForTest(-1l, 150l, 0x7fu);
    assert(play_audio_range_event_count == 2u && play_audio_range_events[0] == 1u && play_audio_range_events[1] == 4u);
    assert(play_audio_range_started_start == 2000l && play_audio_range_started_end == 2150l && play_audio_range_started_mode == 0x7fu);
    assert(read_count == 5u && write_count == 0u);

    clear_memory(0u);
    reset_validate_and_start_play_audio_observers();
    set_memory_big_endian_u32(0x1235u, 3000ul);
    firmware_memory[0x0fafu] = 1u;
    firmware_memory[0x0fbau] = 0x10u;
    play_audio_range_validation_result = 1u;
    ValidateAndStartPlayAudioFrameRangeForTest(-1l, 1l, 1u);
    assert(play_audio_range_event_count == 2u && play_audio_range_events[1] == 4u);
    assert(play_audio_range_started_start == 3000l && play_audio_range_started_end == 3001l);
    assert(read_count == 6u && write_count == 0u);

    clear_memory(0u);
    reset_validate_and_start_play_audio_observers();
    play_audio_range_validation_result = 1u;
    ValidateAndStartPlayAudioFrameRangeForTest(0x7ffffffel, 4l, 0x55u);
    assert(play_audio_range_event_count == 2u && play_audio_range_events[0] == 1u && play_audio_range_events[1] == 4u);
    assert(play_audio_range_validation_start == 0x7ffffffel && (u32)play_audio_range_validation_end == 0x80000002ul && play_audio_range_started_start == 0x7ffffffel
           && (u32)play_audio_range_started_end == 0x80000002ul && play_audio_range_started_mode == 0x55u);
    assert(read_count == 0u && write_count == 0u);
}

static void test_store_playback_range_start_frame_position(void)
{
    static const s32 values[] = { 0l, 1l, (s32)0x12345678ul, (s32)0xfffffffful };
    unsigned index;

    for(index = 0u; index < sizeof(values) / sizeof(values[0]); ++index)
    {
        clear_memory(0xa5u);
        StorePlaybackRangeStartFramePosition(values[index]);
        assert(get_memory_big_endian_u32(0x000fc6ul) == (u32)values[index]);
        assert(read_count == 0u && write_count == 4u);
        assert(write_trace[0] == 0x000fc6ul && write_trace[1] == 0x000fc7ul && write_trace[2] == 0x000fc8ul && write_trace[3] == 0x000fc9ul);
        assert(write_values[0] == (u8)((u32)values[index] >> 24) && write_values[1] == (u8)((u32)values[index] >> 16) && write_values[2] == (u8)((u32)values[index] >> 8)
               && write_values[3] == (u8)values[index]);
    }
}

