    home_pickup_port_count = 0u;
    memset(home_pickup_drive_codes, 0, sizeof(home_pickup_drive_codes));
    memset(home_pickup_drive_enabled, 0, sizeof(home_pickup_drive_enabled));
    home_pickup_drive_count = 0u;
    home_pickup_yield_count = 0u;
    home_pickup_signal_after_yield = 0u;
    home_pickup_reset_count = 0u;
