static void assert_home_pickup_final_state(u8 expected_p1)
{
    assert(firmware_memory[0x1030u] == 1u && firmware_memory[0x1031u] == 0x08u && firmware_memory[0x1032u] == 0x55u);
    assert(sfr_memory[0x90u] == expected_p1);
    assert(home_pickup_reset_count == 1u);
    assert(home_pickup_port_addresses[0] == 0x01809aul && home_pickup_port_values[0] == 0x80u);
    assert(home_pickup_port_addresses[home_pickup_port_count - 1u] == 0x01849dul && home_pickup_port_values[home_pickup_port_count - 1u] == 0u);
    assert(home_pickup_drive_codes[0] == 3u && home_pickup_drive_enabled[0] == 1u && home_pickup_drive_codes[home_pickup_drive_count - 1u] == 4u
           && home_pickup_drive_enabled[home_pickup_drive_count - 1u] == 0u);
}

static void test_home_pickup_against_p1_bit2_and_reset_estimate(void)
{
    clear_memory(0u);
    reset_home_pickup_observers();
    sfr_memory[0x90u] = 0xa2u;
    firmware_memory[0x11edu] = 4u;
    HomePickupAgainstP1Bit2AndResetEstimate();
    assert(home_pickup_yield_count == 12u && home_pickup_port_count == 3u && home_pickup_drive_count == 2u);
    assert(home_pickup_port_addresses[1] == 0x01849dul && home_pickup_port_values[1] == 0u);
    assert_home_pickup_final_state(0xa2u);

    clear_memory(0u);
    reset_home_pickup_observers();
    sfr_memory[0x90u] = 0xa0u;
    HomePickupAgainstP1Bit2AndResetEstimate();
    assert(home_pickup_yield_count == 260u && home_pickup_port_count == 5u && home_pickup_drive_count == 3u);
    assert(home_pickup_drive_codes[1] == 4u && home_pickup_drive_enabled[1] == 1u);
    assert(home_pickup_port_addresses[1] == 0x01849dul && home_pickup_port_addresses[2] == 0x01849dul && home_pickup_port_addresses[3] == 0x01849dul);
    assert_home_pickup_final_state(0xa0u);

    clear_memory(0u);
    reset_home_pickup_observers();
    sfr_memory[0x90u] = 0x51u;
    home_pickup_signal_after_yield = 129u;
    HomePickupAgainstP1Bit2AndResetEstimate();
    assert(home_pickup_yield_count == 141u && home_pickup_port_count == 4u && home_pickup_drive_count == 3u);
    assert_home_pickup_final_state(0x51u);
}

