static void test_update_read_acquisition_move_distance(void)
{
    static const u32 deltas[] = { 32ul, 1600ul, 0xfffffff8ul };
    static const u16 expected[] = { 10u, 200u, 10u };
    unsigned index;

    clear_memory(0u);
    reset_read_acquisition_move_distance_observers();
    firmware_memory[0x1006u] = 1u;
    read_move_distance_radial_result = 0x1234u;
    UpdateReadAcquisitionMoveDistance();
    assert(read_move_distance_event_count == 2u && read_move_distance_events[0] == 2u && read_move_distance_events[1] == 3u);
    assert(get_memory_big_endian_u16(0x0edcu) == 0x1234u && firmware_memory[0x0ee3u] == 0u);

    clear_memory(0u);
    reset_read_acquisition_move_distance_observers();
    firmware_memory[0x12beu] = 4u;
    UpdateReadAcquisitionMoveDistance();
    assert(read_move_distance_event_count == 0u && get_memory_big_endian_u16(0x0edcu) == 50u);

    clear_memory(0u);
    reset_read_acquisition_move_distance_observers();
    read_move_distance_convert_result = -5l;
    UpdateReadAcquisitionMoveDistance();
    assert(read_move_distance_event_count == 1u && read_move_distance_events[0] == 1u && read_move_distance_convert_address == 0x1241ul);
    assert(get_memory_big_endian_u32(0x0ef1u) == (u32)-5l && get_memory_big_endian_u16(0x0edcu) == 50u);

    for(index = 0u; index != 3u; ++index)
    {
        clear_memory(0u);
        reset_read_acquisition_move_distance_observers();
        set_memory_big_endian_u32(0x0ef1u, 1ul);
        read_move_distance_frame_delta = deltas[index];
        UpdateReadAcquisitionMoveDistance();
        assert(read_move_distance_event_count == 1u && read_move_distance_events[0] == 2u);
        assert(get_memory_big_endian_u16(0x0edcu) == expected[index]);
    }
}

static u8 oracle_packed_bcd_byte(unsigned value)
{
    return (u8)((value / 10u) * 16u + value % 10u);
}

static void test_advance_raw_q_packet_tuples(void)
{
    static const unsigned positions[] = { 0u, 1u, 73u, 74u, 75u, 4499u, 4500u, 449999u };
    unsigned selector, first_case, second_case, extended;
    clear_memory(0xa5u);
    for(selector = 0u; selector < 256u; ++selector)
        for(first_case = 0u; first_case < 8u; ++first_case)
            for(second_case = 0u; second_case < 8u; ++second_case)
                for(extended = 0u; extended < 2u; ++extended)
                {
                    unsigned absolute = positions[first_case], relative = positions[second_case];
                    unsigned expected_absolute = absolute + 1u;
                    unsigned expected_relative = selector == 1u ? (relative + 449999u) % 450000u : relative + 1u;
                    unsigned second_read = absolute == 449999u ? 4u : 3u;
                    firmware_memory[0x1279ul] = oracle_packed_bcd_byte(absolute / 4500u);
                    firmware_memory[0x127aul] = oracle_packed_bcd_byte((absolute / 75u) % 60u);
                    firmware_memory[0x127bul] = oracle_packed_bcd_byte(absolute % 75u);
                    firmware_memory[0x1275ul] = oracle_packed_bcd_byte(relative / 4500u);
                    firmware_memory[0x1276ul] = oracle_packed_bcd_byte((relative / 75u) % 60u);
                    firmware_memory[0x1277ul] = oracle_packed_bcd_byte(relative % 75u);
                    firmware_memory[0x1033ul] = (u8)extended;
                    if(expected_absolute == 450000u && !extended)
                        expected_absolute = 0u;
                    if(expected_relative == 450000u && !extended)
                        expected_relative = 0u;
                    read_count = write_count = sfr_read_count = sfr_write_count = 0u;
                    AdvanceRawReadQPacketMsfTuples((u8)selector);
                    assert(firmware_memory[0x1279ul] == oracle_packed_bcd_byte(expected_absolute / 4500u));
                    assert(firmware_memory[0x127aul] == oracle_packed_bcd_byte((expected_absolute / 75u) % 60u));
                    assert(firmware_memory[0x127bul] == oracle_packed_bcd_byte(expected_absolute % 75u));
                    assert(firmware_memory[0x1275ul] == oracle_packed_bcd_byte(expected_relative / 4500u));
                    assert(firmware_memory[0x1276ul] == oracle_packed_bcd_byte((expected_relative / 75u) % 60u));
                    assert(firmware_memory[0x1277ul] == oracle_packed_bcd_byte(expected_relative % 75u));
                    assert(read_trace[0] == 0x127bul && read_trace[1] == 0x127aul && read_trace[2] == 0x1279ul);
                    assert(read_trace[second_read] == 0x1277ul && read_trace[second_read + 1u] == 0x1276ul && read_trace[second_read + 2u] == 0x1275ul);
                    assert(write_trace[0] == 0x127bul);
                    assert(firmware_memory[0x1274ul] == 0xa5u && firmware_memory[0x1278ul] == 0xa5u && firmware_memory[0x127cul] == 0xa5u);
                    assert(sfr_read_count == 0u && sfr_write_count == 0u);
                }
}

static void test_decrement_packed_bcd_full_range(void)
{
    unsigned position;
    clear_memory(0u);
    for(position = 0u; position < 450000u; ++position)
    {
        u32 address = position & 1u ? 0xfffful : 0x300ul;
        unsigned expected = (position + 449999u) % 450000u;
        unsigned stores = position % 75u != 0u ? 1u : (position % 4500u != 0u ? 2u : 3u);
        firmware_memory[address] = oracle_packed_bcd_byte(position / 4500u);
        firmware_memory[address + 1ul] = oracle_packed_bcd_byte((position / 75u) % 60u);
        firmware_memory[address + 2ul] = oracle_packed_bcd_byte(position % 75u);
        read_count = write_count = sfr_read_count = sfr_write_count = 0u;
        DecrementPackedBcdMsf((u16)address);
        assert(firmware_memory[address] == oracle_packed_bcd_byte(expected / 4500u));
        assert(firmware_memory[address + 1ul] == oracle_packed_bcd_byte((expected / 75u) % 60u));
        assert(firmware_memory[address + 2ul] == oracle_packed_bcd_byte(expected % 75u));
        assert(read_count == 3u && write_count == stores);
        assert(read_trace[0] == address + 2ul && read_trace[1] == address + 1ul && read_trace[2] == address);
        if(position == 0u)
        {
            assert(write_trace[0] == address + 2ul && write_trace[1] == address + 1ul && write_trace[2] == address);
        }
        else
        {
            assert(write_trace[stores - 1u] == address + 2ul);
            if(stores > 1u)
                assert(write_trace[stores - 2u] == address + 1ul);
            if(stores > 2u)
                assert(write_trace[0] == address);
        }
        assert(sfr_read_count == 0u && sfr_write_count == 0u);
    }
}

static void test_increment_packed_bcd_full_range(void)
{
    unsigned position, extended;
    clear_memory(0u);
    for(extended = 0u; extended < 2u; ++extended)
        for(position = 0u; position < 450000u; ++position)
        {
            u32 address = position & 1u ? 0xfffful : 0x300ul;
            unsigned expected = position + 1u;
            unsigned stores = position % 75u != 74u ? 1u : (position % 4500u != 4499u ? 2u : 3u);
            firmware_memory[address] = oracle_packed_bcd_byte(position / 4500u);
            firmware_memory[address + 1ul] = oracle_packed_bcd_byte((position / 75u) % 60u);
            firmware_memory[address + 2ul] = oracle_packed_bcd_byte(position % 75u);
            firmware_memory[0x1033ul] = (u8)extended;
            if(expected == 450000u && extended == 0u)
                expected = 0u;
            read_count = write_count = sfr_read_count = sfr_write_count = 0u;
            IncrementPackedBcdMsf((u16)address);
            assert(firmware_memory[address] == oracle_packed_bcd_byte(expected / 4500u));
            assert(firmware_memory[address + 1ul] == oracle_packed_bcd_byte((expected / 75u) % 60u));
            assert(firmware_memory[address + 2ul] == oracle_packed_bcd_byte(expected % 75u));
            assert(read_count == (position == 449999u ? 4u : 3u));
            assert(read_trace[0] == address + 2ul && read_trace[1] == address + 1ul && read_trace[2] == address);
            assert(write_count == stores);
            assert(write_trace[0] == address + 2ul);
            if(stores > 1u)
                assert(write_trace[1] == address + 1ul);
            if(stores > 2u)
                assert(write_trace[2] == address);
            assert(sfr_read_count == 0u && sfr_write_count == 0u);
        }
    firmware_memory[0x300ul] = 1u;
    firmware_memory[0x301ul] = 0x59u;
    firmware_memory[0x302ul] = 0x74u;
    write_mutation_enabled = 1u;
    write_mutation_trigger = 0x302ul;
    write_mutation_target = 0x300ul;
    write_mutation_value = 0x10u;
    read_count = write_count = 0u;
    IncrementPackedBcdMsf(0x300u);
    assert(firmware_memory[0x300ul] == 2u);
}

static void test_complete_batched_host_transfer(void)
{
    unsigned count, mode;
    clear_memory(0u);
    for(count = 0u; count < 65536u; ++count)
        for(mode = 0u; mode < 4u; ++mode)
        {
            u16 mask = mode & 1u ? 0xffffu : 0x3ffu;
            u16 cursor = (u16)((count + 0x123u) & mask);
            u16 backlog = (u16)((cursor - 0x101u) & mask);
            unsigned consume = backlog < 0x8000u && backlog > 256u;
            unsigned prefix = consume ? 10u : 4u;
            u32 total = mode < 2u ? 0xfffffff0ul : 0x7ffffffful;
            set_memory_big_endian_u16(0x1463ul, (u16)count);
            set_memory_big_endian_u16(0x1298ul, 0x123u);
            set_memory_big_endian_u16(0x1294ul, 0x101u);
            set_memory_big_endian_u16(0x129aul, mask);
            set_memory_big_endian_u16(0x1292ul, 0x40u);
            set_memory_big_endian_u32(0x156aul, 518ul);
            set_memory_big_endian_u32(0x1459ul, total);
            firmware_memory[0xf47ul] = 0xa5u;
            read_count = write_count = sfr_read_count = sfr_write_count = 0u;
            CompleteBatchedHostTransferBuffers();
            assert(get_memory_big_endian_u16(0x1298ul) == cursor);
            assert(get_memory_big_endian_u32(0x1459ul) == (u32)(total + count));
            assert(firmware_memory[0xf47ul] == 0u);
            assert(write_count == prefix + 4u && read_count == (consume ? 34u : 22u));
            assert(write_trace[0] == 0x18047ul && write_values[0] == 0x14u);
            assert(write_trace[1] == 0x1298ul && write_trace[2] == 0x1299ul);
            assert(write_trace[3] == 0xf47ul && write_values[3] == 0u);
            assert(write_trace[prefix] == 0x1459ul && write_trace[prefix + 3u] == 0x145cul);
            assert(read_trace[read_count - 6u] == 0x1463ul && read_trace[read_count - 5u] == 0x1464ul);
            assert(sfr_read_count == 0u && sfr_write_count == 0u);
        }
    set_memory_big_endian_u16(0x1463ul, 1u);
    set_memory_big_endian_u16(0x1298ul, 0u);
    set_memory_big_endian_u16(0x1294ul, 0u);
    set_memory_big_endian_u32(0x1459ul, 9ul);
    write_mutation_enabled = 1u;
    write_mutation_trigger = 0xf47ul;
    write_mutation_target = 0x1464ul;
    write_mutation_value = 3u;
    read_count = write_count = 0u;
    CompleteBatchedHostTransferBuffers();
    assert(get_memory_big_endian_u16(0x1298ul) == 1u);
    assert(get_memory_big_endian_u32(0x1459ul) == 12ul);
}

static void test_reset_raw_read_host_transfer_controller_state(void)
{
    static const fw_addr_t always_writes[] = { 0x1801ful, 0x18020ul, 0x18021ul, 0x18047ul };
    static const fw_addr_t restore_writes[] = { 0x18056ul, 0x18050ul, 0x0c33ul, 0x0c83ul, 0x18051ul, 0x1804aul };
    static const u8 restore_values[] = { 0x51u, 0xb0u, 6u, 0xa7u, 3u, 0xc0u };
    unsigned index;

    clear_memory(0xa5u);
    firmware_memory[0x1597ul] = 1u;
    ResetRawReadHostTransferControllerState();
    assert(read_count == 1u && read_trace[0] == 0x1597ul);
    assert(write_count == 4u);
    for(index = 0u; index < 4u; ++index)
    {
        assert(write_trace[index] == always_writes[index]);
        assert(write_values[index] == (index == 3u ? 0x14u : 0u));
    }
    assert(firmware_memory[0x18056ul] == 0xa5u && firmware_memory[0x18050ul] == 0xa5u && firmware_memory[0x0c33ul] == 0xa5u && firmware_memory[0x0c83ul] == 0xa5u);

    clear_memory(0u);
    firmware_memory[0x0c2ful] = 0x51u;
    firmware_memory[0x0c30ul] = 0xb0u;
    firmware_memory[0x0c83ul] = 0xa5u;
    ResetRawReadHostTransferControllerState();
    assert(read_count == 4u && read_trace[0] == 0x1597ul && read_trace[1] == 0x0c2ful && read_trace[2] == 0x0c30ul && read_trace[3] == 0x0c83ul);
    assert(write_count == 10u);
    for(index = 0u; index < 4u; ++index)
    {
        assert(write_trace[index] == always_writes[index]);
        assert(write_values[index] == (index == 3u ? 0x14u : 0u));
    }
    for(index = 0u; index < 6u; ++index)
    {
        assert(write_trace[index + 4u] == restore_writes[index]);
        assert(write_values[index + 4u] == restore_values[index]);
    }
}

