    assert(read_count == 1u && read_trace[0] == 0x0c46ul);
    assert(write_count == 0u && populate_decoded_toc_track_range_call_count == 0u && bit_003f == 1u);

    clear_memory(0u);
    firmware_memory[0x12c0u] = 4u;
    firmware_memory[0xdd87u + 5u * 19u] = 0xa5u;
