    assert(type2_track_layout_call_count == 1u);
    assert(bit_003f == 0u && firmware_memory[0xdd79u] == 0u);
    assert(firmware_memory[0xdd64u] == 1u && firmware_memory[0xdd7eu] == 5u && firmware_memory[0xdd7fu] == 5u && firmware_memory[0xdd87u + 5u * 19u] == 0u);
    assert(firmware_memory[0xe4ecu] == 5u && firmware_memory[0xe4edu] == 5u && get_memory_big_endian_u32(0xe4eeu) == 0u);

    clear_memory(0u);
    firmware_memory[0x12c9u] = 1u;
