static void test_throttle_raw_read_producer_for_queue_capacity(void)
{
    static const fw_addr_t expected_writes[] = { 0x000f72ul, 0x000e44ul, 0x000e49ul, 0x000e4aul, 0x000f10ul, 0x000f11ul, 0x000f12ul, 0x000f13ul, 0x001591ul, 0x000e44ul, 0x000e49ul, 0x000e4aul,
        0x000f72ul };
    static const u8 expected_values[] = { 1u, 1u, 0x28u, 0u, 0xffu, 0xffu, 0xffu, 0xf6u, 0u, 1u, 0x34u, 0u, 0u };
    static const u8 expected_events[] = { 1u, 2u, 3u, 4u, 4u, 5u };
    unsigned index;

    clear_memory(0u);
    write_count = 0u;
    ThrottleRawReadProducerForQueueCapacity();
    assert(producer_throttle_event_count == 1u && producer_throttle_events[0] == 1u);
    assert(write_count == 1u && write_trace[0] == 0x000f72ul && write_values[0] == 0u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 1u);
    set_memory_big_endian_u32(0x156au, 71u);
    firmware_memory[0x0f46u] = 1u;
    write_count = 0u;
    ThrottleRawReadProducerForQueueCapacity();
    assert(producer_throttle_event_count == 1u && write_count == 1u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 1u);
    set_memory_big_endian_u32(0x156au, 135u);
    bit_000e = 1u;
    write_count = 0u;
    ThrottleRawReadProducerForQueueCapacity();
    assert(producer_throttle_event_count == 1u && write_count == 1u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 90u);
    set_memory_big_endian_u32(0x156au, 100u);
    firmware_memory[0x0e46u] = 0x28u;
    firmware_memory[0x1591u] = 1u;
    producer_throttle_queue_after_yield[0] = 85u;
    producer_throttle_queue_after_yield[1] = 78u;
    producer_throttle_yield_result_count = 2u;
    producer_throttle_speed_after_dispatch = 0x34u;
    event_bit7_restored_dr12 = 0u;
    write_mutation_enabled = 1u;
    write_mutation_trigger = 0x000f72ul;
    write_mutation_target = 0x000f46ul;
    write_mutation_value = 1u;
    write_count = 0u;

    ThrottleRawReadProducerForQueueCapacity();

    assert(producer_throttle_event_count == sizeof(expected_events));
    for(index = 0u; index != sizeof(expected_events); ++index)
        assert(producer_throttle_events[index] == expected_events[index]);
    assert(producer_throttle_yield_count == 2u);
    assert(event_bit7_restored_dr12 == 0x12345678ul);
    assert(write_count == sizeof(expected_writes) / sizeof(expected_writes[0]));
    for(index = 0u; index != write_count; ++index)
    {
        assert(write_trace[index] == expected_writes[index]);
        assert(write_values[index] == expected_values[index]);
    }
    assert(get_memory_big_endian_u32(0x0f10u) == 0xfffffff6ul);
    assert(firmware_memory[0x0f72u] == 0u && firmware_memory[0x0e44u] == 1u && firmware_memory[0x0e49u] == 0x34u && firmware_memory[0x0e4au] == 0u && firmware_memory[0x1591u] == 0u);
}

static void SetOperatingTransitionCountdown(u8 current_code, u8 applied_code, u16 countdown)
{
    u8 current_class = MapOperatingCodeToTransitionClass(current_code);
    u8 applied_class = MapOperatingCodeToTransitionClass(applied_code);
    fw_addr_t address = 0xff952cul + (fw_addr_t)applied_class * 12u + (fw_addr_t)current_class * 2u;

    firmware_memory[address] = (u8)(countdown >> 8);
    firmware_memory[address + 1u] = (u8)countdown;
    firmware_memory[0x000e43u] = current_code;
    firmware_memory[0x000e4du] = applied_code;
}

static void test_wait_for_operating_code_transition_settling(void)
{
    clear_memory(0u);
    SetOperatingTransitionCountdown(4u, 8u, 0u);
    WaitForOperatingCodeTransitionSettling();
    assert(operating_settling_initial_set_count == 1u && operating_settling_final_set_count == 1u && operating_settling_yield_count == 0u && operating_settling_p0_read_count == 0u
           && operating_settling_p1_read_count == 0u);
    assert(get_memory_big_endian_u16(0x1200u) == 0u && operating_settling_restored_dr12 == 0x89abcdeful);

    clear_memory(0u);
    SetOperatingTransitionCountdown(8u, 4u, 1u);
    operating_settling_countdown_after_yield = 1;
    WaitForOperatingCodeTransitionSettling();
    assert(operating_settling_initial_set_count == 0u && operating_settling_final_set_count == 1u && operating_settling_yield_count == 19u && operating_settling_p0_read_count == 0u
           && operating_settling_p1_read_count == 20u);

    clear_memory(0u);
    SetOperatingTransitionCountdown(1u, 8u, 4u);
    operating_settling_p0_value = 1u;
    operating_settling_p1_value = 1u;
    operating_settling_countdown_after_yield = 1;
    WaitForOperatingCodeTransitionSettling();
    assert(operating_settling_initial_set_count == 1u && operating_settling_final_set_count == 1u && operating_settling_yield_count == 100u && operating_settling_p0_read_count == 100u
           && operating_settling_p1_read_count == 101u);

    clear_memory(0u);
    SetOperatingTransitionCountdown(4u, 8u, 4u);
    operating_settling_p0_value = 1u;
    operating_settling_p1_value = 0u;
    operating_settling_countdown_after_yield = 1;
    WaitForOperatingCodeTransitionSettling();
    assert(operating_settling_yield_count == 19u && operating_settling_p0_read_count == 19u && operating_settling_p1_read_count == 20u);

    clear_memory(0u);
    SetOperatingTransitionCountdown(8u, 4u, 10u);
    operating_settling_p1_value = 1u;
    operating_settling_countdown_after_yield = 0;
    WaitForOperatingCodeTransitionSettling();
    assert(operating_settling_yield_count == 1u && operating_settling_p1_read_count == 1u && operating_settling_final_set_count == 1u);
}

static void test_wait_for_controller_measurement_within_tolerance_or_expiry(void)
{
    unsigned index;

    clear_memory(0u);
    firmware_memory[0x1006u] = 1u;
    firmware_memory[0xf98fu] = 0xaau;
    WaitForControllerMeasurementWithinToleranceOrExpiry(0u, 7u);
    assert(measurement_wait_yield_count == 0u && measurement_wait_tolerance_result_index == 0u && measurement_wait_read_word_count == 0u);
    assert(measurement_wait_set_p1_count == 2u && measurement_wait_submit_count == 1u && measurement_wait_submit_value == 0x7fffu && measurement_wait_submit_selector == 0x0369u);
    assert(measurement_wait_strobe_count == 1u && measurement_wait_strobe_address == 0x018006ul && measurement_wait_strobe_value == 0xc0u);
    assert(measurement_wait_channel_count == 1u && measurement_wait_channel_index == 3u && measurement_wait_channel_value == 0xaau);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1200u, 100u);
    measurement_wait_decrement_until_yield = 4u;
    measurement_wait_tolerance_results[0] = 1u;
    measurement_wait_tolerance_result_count = 1u;
    WaitForControllerMeasurementWithinToleranceOrExpiry(1u, 1u);
    assert(measurement_wait_yield_count == 4u && get_memory_big_endian_u16(0x1200u) == 96u);
    assert(measurement_wait_tolerance_result_index == 1u && measurement_wait_tolerance_percent == 10u && measurement_wait_lower_bound_only == 1u);
    assert(measurement_wait_read_word_count == 0u && measurement_wait_set_p1_count == 2u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1200u, 100u);
    measurement_wait_decrement_until_yield = 4u;
    measurement_wait_set_countdown_on_yield = 5u;
    measurement_wait_countdown_after_yield = -1;
    measurement_wait_tolerance_result_count = 2u;
    WaitForControllerMeasurementWithinToleranceOrExpiry(1u, 0u);
    assert(measurement_wait_yield_count == 5u && measurement_wait_tolerance_result_index == 2u && get_memory_big_endian_u16(0x1200u) == 0xffffu);
    assert(measurement_wait_read_word_count == 0u && measurement_wait_set_p1_count == 2u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1200u, 300u);
    firmware_memory[0x1300u] = 2u;
    measurement_wait_decrement_until_yield = 4u;
    measurement_wait_set_countdown_on_yield = 4u;
    measurement_wait_countdown_after_yield = 60;
    measurement_wait_tolerance_results[1] = 1u;
    measurement_wait_tolerance_result_count = 2u;
    measurement_wait_read_word_result = 0x3fffu;
    WaitForControllerMeasurementWithinToleranceOrExpiry(1u, 0x5au);
    assert(measurement_wait_yield_count == 5u && measurement_wait_tolerance_result_index == 2u);
    assert(measurement_wait_read_word_count == 1u && measurement_wait_read_word_selector == 0x0253u && measurement_wait_set_p1_count == 3u);
    assert(measurement_wait_lower_bound_only == 0x5au);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1200u, 100u);
    measurement_wait_decrement_until_yield = 4u;
    measurement_wait_set_countdown_on_yield = 4u;
    measurement_wait_countdown_after_yield = 60;
    for(index = 0u; index != 40u; ++index)
        measurement_wait_tolerance_results[index] = 0u;
    measurement_wait_tolerance_results[40] = 1u;
    measurement_wait_tolerance_result_count = 41u;
    measurement_wait_read_word_result = 0x4000u;
    WaitForControllerMeasurementWithinToleranceOrExpiry(1u, 0u);
    assert(measurement_wait_yield_count == 44u && measurement_wait_tolerance_result_index == 41u);
    assert(measurement_wait_read_word_count == 40u && measurement_wait_set_p1_count == 3u);
}

