static void reset_event_bit7_transfer_observers(void)
{
    event_bit7_reset_ports_count = 0u;
    event_bit7_reset_queue_count = 0u;
    event_bit7_dispatch_count = 0u;
    event_bit7_buffer_read_count = 0u;
    event_bit7_restored_dr12 = 0u;
    memset(event_bit7_buffer_offsets, 0, sizeof(event_bit7_buffer_offsets));
}

static void test_reset_controller_event_bit7_transfer_state(void)
{
    unsigned index;

    clear_memory(0u);
    reset_event_bit7_transfer_observers();
    firmware_memory[0x0fadu] = 0xfeu;
    firmware_memory[0x0f5cu] = 2u;
    set_memory_big_endian_u32(0x156eu, 0x00123400ul);
    firmware_memory[0x0c2au] = 7u;
    set_memory_big_endian_u32(0x0f32u, 0x89abcdeful);
    bit_000e = bit_0018 = bit_0581 = 1u;
    ResetControllerEventBit7TransferState();

    assert(firmware_memory[0x0fadu] == 0x7eu && firmware_memory[0x18003u] == 0x7eu && firmware_memory[0x1802du] == 1u && firmware_memory[0x18079u] == 0x44u && firmware_memory[0x1807du] == 0x54u);
    assert(bit_000e == 0u && bit_0018 == 0u && bit_0009 == 1u && bit_0580 == 1u && bit_0581 == 0u);
    assert(get_memory_big_endian_u32(0x15d8u) == 0x0012342aul && get_memory_big_endian_u32(0x1598u) == 0x89abcdeful);
    for(index = 0u; index < 10u; ++index)
    {
        assert(event_bit7_buffer_offsets[index] == 0x00123420ul + index);
        assert(firmware_memory[0x0faf2u + index] == (u8)(0x40u + index));
    }
    assert(
        event_bit7_buffer_read_count == 10u && event_bit7_reset_ports_count == 1u && event_bit7_reset_queue_count == 1u && event_bit7_dispatch_count == 1u && event_bit7_restored_dr12 == 0x12345678ul);
    assert(read_count == 51u && write_count == 63u && read_trace[0] == 0x000fadul && read_trace[1] == 0x000f5cul && read_trace[2] == 0x00156eul && read_trace[46] == 0x000c2aul
           && read_trace[47] == 0x000f32ul);
    assert(write_trace[0] == 0x000fadul && write_trace[1] == 0x018003ul && write_trace[2] == 0x01802dul && write_trace[3] == 0x018079ul && write_trace[4] == 0x01807dul && write_trace[5] == 0x0015d8ul
           && write_trace[49] == 0x000faf2ul && write_trace[58] == 0x000fafbul && write_trace[59] == 0x001598ul);

    clear_memory(0u);
    reset_event_bit7_transfer_observers();
    firmware_memory[0x0f5cu] = 0xffu;
    set_memory_big_endian_u32(0x156eu, 0xfffff100ul);
    firmware_memory[0x0c2au] = 6u;
    ResetControllerEventBit7TransferState();
    assert(get_memory_big_endian_u32(0x15d8u) == 0x000000faul && event_bit7_reset_queue_count == 0u && event_bit7_dispatch_count == 0u && bit_0009 == 0u);
    assert(read_count == 47u && write_count == 59u);
}

static void test_handle_read_measurement_target_packet_match(void)
{
    static const u8 modes[] = { 0u, 1u, 2u, 3u, 4u, 0xffu };
    static const fw_addr_t expected_reads[] = { 0x00154eul, 0x001133ul, 0x00154ful, 0x001134ul, 0x001550ul, 0x001135ul, 0x00fb9eul, 0x000fadul };
    static const fw_addr_t expected_writes[] = { 0x00fb9ful, 0x000efbul, 0x018004ul, 0x000efcul, 0x018005ul, 0x000efdul, 0x018006ul, 0x01802dul, 0x000fadul, 0x018003ul };
    unsigned index;

    clear_memory(0xa5u);
    HandleReadMeasurementTargetPacketMatch();
    assert(read_count == 0u && write_count == 0u && bit_0043 == 0u);

    clear_memory(0u);
    bit_0034 = 1u;
    firmware_memory[0x154eu] = 1u;
    firmware_memory[0x1133u] = 2u;
    HandleReadMeasurementTargetPacketMatch();
    assert(read_count == 2u && write_count == 0u && bit_0034 == 1u);

    clear_memory(0u);
    bit_0034 = 1u;
    firmware_memory[0x154eu] = firmware_memory[0x1133u] = 1u;
    firmware_memory[0x154fu] = 2u;
    firmware_memory[0x1134u] = 3u;
    HandleReadMeasurementTargetPacketMatch();
    assert(read_count == 4u && write_count == 0u && bit_0034 == 1u);

    clear_memory(0u);
    bit_0034 = 1u;
    firmware_memory[0x154eu] = firmware_memory[0x1133u] = 1u;
    firmware_memory[0x154fu] = firmware_memory[0x1134u] = 2u;
    firmware_memory[0x1550u] = 3u;
    firmware_memory[0x1135u] = 4u;
    HandleReadMeasurementTargetPacketMatch();
    assert(read_count == 6u && write_count == 0u && bit_0034 == 1u);

    for(index = 0u; index != sizeof(modes); ++index)
    {
        u8 expected_profile = modes[index] <= 3u ? 0x47u : 0x40u;

        clear_memory(0u);
        bit_0034 = 1u;
        firmware_memory[0x154eu] = firmware_memory[0x1133u] = 0x12u;
        firmware_memory[0x154fu] = firmware_memory[0x1134u] = 0x34u;
        firmware_memory[0x1550u] = firmware_memory[0x1135u] = 0x56u;
        firmware_memory[0xfb9eu] = modes[index];
        firmware_memory[0x0fadu] = 0xa5u;
        HandleReadMeasurementTargetPacketMatch();

        assert(read_count == sizeof(expected_reads) / sizeof(expected_reads[0]) && memcmp(read_trace, expected_reads, sizeof(expected_reads)) == 0);
        assert(write_count == sizeof(expected_writes) / sizeof(expected_writes[0]) && memcmp(write_trace, expected_writes, sizeof(expected_writes)) == 0);
        assert(firmware_memory[0xfb9fu] == 1u && firmware_memory[0x0efbu] == 2u && firmware_memory[0x18004u] == 2u && firmware_memory[0x0efcu] == expected_profile
               && firmware_memory[0x18005u] == expected_profile && firmware_memory[0x0efdu] == 0u && firmware_memory[0x18006u] == 0u && firmware_memory[0x1802du] == 0x30u
               && firmware_memory[0x0fadu] == 0xb5u && firmware_memory[0x18003u] == 0xb5u);
        assert(bit_0043 == 1u && bit_0034 == 0u);
    }
}

static void test_prepare_read_measurement_for_high_descriptor_mode(void)
{
    unsigned mode;

    clear_memory(0xa5u);
    for(mode = 0u; mode != 256u; ++mode)
    {
        u8 valid = (u8)(mode == 0u || mode == 8u || mode == 9u || (mode >= 10u && mode <= 13u));
        u8 target_offset = (u8)(mode == 0u || mode == 9u ? 2u : 3u);
        u32 expected_target = 1ul - (u32)target_offset;
        unsigned index;

        firmware_memory[0xfb9eu] = (u8)mode;
        firmware_memory[0xfba0u] = 0xa5u;
        firmware_memory[0xfba2u] = 0u;
        firmware_memory[0xfba3u] = 0u;
        firmware_memory[0xfba4u] = 0u;
        firmware_memory[0xfba5u] = 1u;
        firmware_memory[0xfba6u] = 0xa5u;
        firmware_memory[0xfba7u] = 0xa5u;
        firmware_memory[0xfba8u] = 0xa5u;
        firmware_memory[0xfba9u] = 0xa5u;
        adjusted_target_prepare_call_count = 0u;
        adjusted_target_prepare_seen_target = 0u;
        read_count = 0u;
        write_count = 0u;

        PrepareReadMeasurementForHighDescriptorMode();

        assert(read_count == (valid != 0u ? 5u : 1u) && read_trace[0] == 0x00fb9eul);
        if(valid != 0u)
        {
            for(index = 0u; index != 4u; ++index)
            {
                assert(read_trace[1u + index] == 0x00fba2ul + index);
                assert(write_trace[index] == 0x00fba6ul + index);
            }
            assert(write_count == 4u && get_memory_big_endian_u32(0xfba6u) == expected_target && adjusted_target_prepare_call_count == 1u && adjusted_target_prepare_seen_target == expected_target);
        }
        else
        {
            assert(write_count == 1u && write_trace[0] == 0x00fba0ul && firmware_memory[0xfba0u] == 7u && adjusted_target_prepare_call_count == 0u && firmware_memory[0xfba6u] == 0xa5u);
        }
    }
}

static void test_advance_raw_read_ring_position(void)
{
    clear_memory(0u);
    set_memory_big_endian_u32(0x156au, 4ul);
    AdvanceRawReadRingPosition(0ul);
    assert(get_memory_big_endian_u32(0x1262u) == 0ul);
    assert(get_memory_big_endian_u32(0x1266u) == 0ul);
    assert(get_memory_big_endian_u32(0x126eu) == 0x930ul);

    clear_memory(0u);
    set_memory_big_endian_u32(0x156au, 4ul);
    set_memory_big_endian_u32(0x1266u, 3ul);
    firmware_memory[0x1285u] = 1u;
    AdvanceRawReadRingPosition(3ul * 0x930ul);
    assert(get_memory_big_endian_u32(0x1262u) == 0ul);
    assert(get_memory_big_endian_u32(0x1266u) == 0ul);

    clear_memory(0u);
    set_memory_big_endian_u32(0x156au, 4ul);
    firmware_memory[0x1285u] = 2u;
    AdvanceRawReadRingPosition(0x930ul);
    assert(get_memory_big_endian_u32(0x1262u) == 1ul);
    assert(get_memory_big_endian_u32(0x126eu) == 0x1260ul);

    clear_memory(0u);
    set_memory_big_endian_u32(0x156au, 4ul);
    set_memory_big_endian_u32(0x1262u, 3ul);
    firmware_memory[0x1285u] = 3u;
    AdvanceRawReadRingPosition(0ul);
    assert(get_memory_big_endian_u32(0x1262u) == 0ul);
    assert(get_memory_big_endian_u32(0x126eu) == 0x930ul);

    clear_memory(0u);
    set_memory_big_endian_u32(0x156au, 4ul);
    firmware_memory[0x1285u] = 7u;
    firmware_memory[0x14a6u] = 1u;
    AdvanceRawReadRingPosition(0ul);
    assert(get_memory_big_endian_u32(0x1262u) == 1ul);
    assert(get_memory_big_endian_u32(0x126eu) == 0x930ul);

    clear_memory(0u);
    AdvanceRawReadRingPosition(0ul);
    assert(get_memory_big_endian_u32(0x126eu) == 0x930ul);
}

