static void test_compute_bounded_controller_adjustment_code(void)
{
    clear_memory(0u);
    set_memory_big_endian_u16(0x00f074ul, 1000u);
    firmware_memory[0xf06au] = 5u;
    assert(ComputeBoundedControllerAdjustmentCode(10.0f, 1000u) == 19u);
    assert(ComputeBoundedControllerAdjustmentCode(11.0f, 1100u) == 13u);

    firmware_memory[0xf06au] = 0u;
    assert(ComputeBoundedControllerAdjustmentCode(20.0f, 1000u) == 126u);

    set_memory_big_endian_u16(0x00f074ul, 1u);
    assert(ComputeBoundedControllerAdjustmentCode(0.0f, 0u) == 13u);

    set_memory_big_endian_u16(0x00f074ul, 0u);
    firmware_memory[0xf06au] = 127u;
    assert(ComputeBoundedControllerAdjustmentCode(0.0f, 0u) == 126u);
}

static void test_run_disc_recognition_and_toc_initialization(void)
{
    static const u8 retained_events[] = { 1u, 2u };
    static const u8 initial_failure_events[] = { 1u, 3u, 4u };
    static const u8 full_toc_failure_events[] = { 1u, 3u, 4u, 5u, 6u };
    static const u8 pma_failure_events[] = { 1u, 3u, 4u, 5u, 7u };
    static const u8 full_success_events[] = { 1u, 3u, 4u, 5u, 6u, 8u, 9u, 10u, 11u };
    static const u8 skip_toc_events[] = { 1u, 3u, 4u, 5u, 7u, 9u, 10u, 11u };

    clear_memory(0u);
    disc_recognition_snapshot_result = 1u;
    disc_recognition_post_toc_result = 2u;
    assert(RunDiscRecognitionAndTocInitialization() == 2u);
    assert(disc_recognition_event_count == sizeof(retained_events) && memcmp(disc_recognition_events, retained_events, sizeof(retained_events)) == 0);

    clear_memory(0u);
    firmware_memory[0x1301u] = 0xffu;
    disc_recognition_initial_toc_result = 3u;
    assert(RunDiscRecognitionAndTocInitialization() == 3u);
    assert(firmware_memory[0x1301u] == 0xfeu && disc_recognition_event_count == sizeof(initial_failure_events)
           && memcmp(disc_recognition_events, initial_failure_events, sizeof(initial_failure_events)) == 0);

    clear_memory(0u);
    disc_recognition_full_toc_result = 4u;
    assert(RunDiscRecognitionAndTocInitialization() == 4u);
    assert(disc_recognition_event_count == sizeof(full_toc_failure_events) && memcmp(disc_recognition_events, full_toc_failure_events, sizeof(full_toc_failure_events)) == 0);

    clear_memory(0u);
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x1132u] = 0x40u;
    firmware_memory[0x1304u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    disc_recognition_pma_result = 5u;
    assert(RunDiscRecognitionAndTocInitialization() == 5u);
    assert(firmware_memory[0x1304u] == 0xfdu && firmware_memory[0x1301u] == 0xfeu && disc_recognition_event_count == sizeof(pma_failure_events)
           && memcmp(disc_recognition_events, pma_failure_events, sizeof(pma_failure_events)) == 0);

    clear_memory(0u);
    firmware_memory[0x0c88u] = 4u;
    firmware_memory[0xfc1fu] = 0x34u;
    assert(RunDiscRecognitionAndTocInitialization() == 0u);
    assert(disc_recognition_event_count == sizeof(full_success_events) && memcmp(disc_recognition_events, full_success_events, sizeof(full_success_events)) == 0 && firmware_memory[0x0c37u] == 0x34u
           && firmware_memory[0x0e46u] == 0x34u);

    clear_memory(0u);
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x1132u] = 0x40u;
    firmware_memory[0xf9e9u] = 4u;
    firmware_memory[0xfaedu] = 4u;
    firmware_memory[0xfc21u] = 4u;
    firmware_memory[0xfc1fu] = 0x56u;
    firmware_memory[0x0c37u] = 0xaau;
    firmware_memory[0x0e46u] = 0xbbu;
    assert(RunDiscRecognitionAndTocInitialization() == 0u);
    assert(disc_recognition_event_count == sizeof(skip_toc_events) && memcmp(disc_recognition_events, skip_toc_events, sizeof(skip_toc_events)) == 0 && firmware_memory[0x0c37u] == 0xaau
           && firmware_memory[0x0e46u] == 0xbbu);
}

