    firmware_memory[0x124eu] = 2u;
    firmware_memory[0x102fu] = 0xffu;
    assert(AccumulateCurrentQPacketIntoInitialToc() == 1u);
    assert(firmware_memory[0xfc18u] == 7u && firmware_memory[0x102eu] == 1u && firmware_memory[0x102fu] == 0u && get_memory_big_endian_u32(0x12c1u) == 427577ul);
    assert(memcmp(&firmware_memory[0xf53cu], &firmware_memory[0x1245u], 10u) == 0);

    clear_memory(0u);
