    firmware_memory[0xdd79u] = 0u;
    firmware_memory[0x0faeu] = 0u;
    firmware_memory[0xdd63u] = 0u;
    firmware_memory[0x1008u] = 2u;
    firmware_memory[0x0c9eu] = 0u;
    firmware_memory[0xe625u] = 0xc0u;
    firmware_memory[0xff8a0cul] = 0x12u;
    firmware_memory[0x0c37u] = 8u;
    firmware_memory[0x0c38u] = 12u;
    firmware_memory[0x12beu] = 1u;
    firmware_memory[0x1305u] = 1u;
    firmware_memory[0x1306u] = 0xffu;
    firmware_memory[0x158eu] = 0xffu;
    firmware_memory[0xf9e9u] = 0xffu;
    media_read_init_layout_result = 1u;
    InitializeMediaReadTrackModelAndPipelineState();
    assert(media_read_init_event_count == sizeof(full_initialization_events) && memcmp(media_read_init_events, full_initialization_events, sizeof(full_initialization_events)) == 0);
    assert(firmware_memory[0xdd7fu] == 0u && firmware_memory[0xdd7eu] == 0u && firmware_memory[0xdd55u] == 0u && firmware_memory[0xdd5fu] == 0u && firmware_memory[0xe625u] == 0x12u
           && firmware_memory[0x0c3cu] == 0x12u && bit_003f == 1u && media_read_init_layout_bit == 1u);
    assert(firmware_memory[0x0e46u] == 8u && firmware_memory[0x0e47u] == 12u && firmware_memory[0x1305u] == 0x41u && firmware_memory[0x1306u] == 0xf7u
           && media_read_init_coroutine_entry == 0x00f84a00ul && firmware_memory[0x0e44u] == 4u && firmware_memory[0x0e3fu] == 1u && firmware_memory[0x0fafu] == 3u
           && get_memory_big_endian_u32(0x0e3bu) == 150ul);
    assert(firmware_memory[0x158eu] == 0xf0u && firmware_memory[0x158bu] == 0u && get_memory_big_endian_u16(0x1589u) == 0u && firmware_memory[0xf9e8u] == 100u && firmware_memory[0xf9e7u] == 100u
           && firmware_memory[0xf9e9u] == 0xf8u);

    clear_memory(0u);
