    firmware_memory[0x0c9eu] = 1u;
    firmware_memory[0x0c37u] = 16u;
    firmware_memory[0x0c38u] = 20u;
    set_memory_big_endian_u32(0x1153u, 300000ul);
    set_memory_big_endian_u32_far(0x2b9704ul, 0x11223344ul);
    set_memory_big_endian_u32_far(0x2b970cul, 0x55667788ul);
    media_read_init_scan_result = 2u;
    InitializeMediaReadTrackModelAndPipelineState();
    assert(media_read_init_event_count == sizeof(retained_pipeline_events) && memcmp(media_read_init_events, retained_pipeline_events, sizeof(retained_pipeline_events)) == 0);
    assert(media_read_init_scan_force == 1u && media_read_init_scan_frame_count == 300000ul && media_read_init_scan_start == 0l && get_memory_big_endian_u32(0x0ce1u) == 0x11223344ul
           && get_memory_big_endian_u32(0x0ce5u) == 0x55667788ul && firmware_memory[0x0e46u] == 16u && firmware_memory[0x0e47u] == 20u && media_read_init_coroutine_entry == 0ul);

    clear_memory(0u);
