    assert(decoded_position_wait_event_count == 2u && decoded_position_wait_events[0] == 1u && decoded_position_wait_events[1] == 2u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1235u, 100u);
    decoded_position_wait_parse_results[0] = 0xfeu;
    decoded_position_wait_parse_results[1] = 0xfeu;
    decoded_position_wait_parse_results[2] = 1u;
    decoded_position_wait_parse_count = 3u;
    decoded_position_wait_mutate_after_parse = 3u;
    decoded_position_wait_mutated_position = 101u;
    decoded_position_wait_mutated_countdown = 38u;
    assert(WaitForDecodedFramePositionPastTarget(100) == 1u);
    assert(decoded_position_wait_event_count == sizeof(pending_events));
    for(index = 0u; index < sizeof(pending_events); ++index)
        assert(decoded_position_wait_events[index] == pending_events[index]);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1235u, 100u);
    firmware_memory[0x1301u] = 0xffu;
    decoded_position_wait_parse_results[0] = 1u;
    decoded_position_wait_parse_count = 1u;
    decoded_position_wait_mutate_after_parse = 1u;
    decoded_position_wait_mutated_position = 200u;
    decoded_position_wait_mutated_countdown = 0u;
    assert(WaitForDecodedFramePositionPastTarget(100) == 0u);
    assert(firmware_memory[0x1301u] == 0xfeu && firmware_memory[0x0e41u] == 5u);
    assert(decoded_position_wait_event_count == 3u && decoded_position_wait_events[2] == 4u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1235u, 100u);
    firmware_memory[0x1301u] = 0x81u;
    decoded_position_wait_parse_results[0] = 5u;
    decoded_position_wait_parse_count = 1u;
    decoded_position_wait_initialize_result = 1u;
    assert(WaitForDecodedFramePositionPastTarget(100) == 0u);
    assert(firmware_memory[0x1301u] == 0x80u && firmware_memory[0x0e41u] == 5u);
    assert(decoded_position_wait_event_count == sizeof(recovery_events));
    for(index = 0u; index < sizeof(recovery_events); ++index)
        assert(decoded_position_wait_events[index] == recovery_events[index]);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1235u, 100u);
