static void test_probe_and_classify_working_track_before_start(void)
{
    static const u8 fallback_statuses[] = { 2u, 4u, 8u };
    unsigned case_index;
    unsigned probe_index;

    for(case_index = 0u; case_index != sizeof(fallback_statuses); ++case_index)
    {
        clear_memory(0u);
        set_memory_big_endian_u32(0xdd3du, 1000ul);
        for(probe_index = 0u; probe_index != 6u; ++probe_index)
            working_track_raw_q_probe_results[probe_index] = fallback_statuses[case_index];
        working_track_raw_q_probe_result_count = 6u;
        assert(ProbeAndClassifyWorkingTrackBeforeStart() == 1u);
        assert(working_track_raw_q_probe_call_count == 6u);
        assert(working_track_raw_q_probe_targets[0] == 910ul && working_track_raw_q_probe_targets[5] == 960ul);
        assert(firmware_memory[0xdd38u] == 15u && firmware_memory[0xdd37u] == 15u && firmware_memory[0xdd34u] == 7u);
    }

    clear_memory(0u);
    set_memory_big_endian_u32(0xdd3du, 50ul);
    working_track_raw_q_probe_results[0] = 3u;
    working_track_raw_q_probe_result_count = 1u;
    assert(ProbeAndClassifyWorkingTrackBeforeStart() == 1u);
    assert(working_track_raw_q_probe_targets[0] == 0xffffffd8ul);
    assert(firmware_memory[0xdd34u] == 0u);

    clear_memory(0u);
    for(probe_index = 0u; probe_index != 6u; ++probe_index)
        working_track_raw_q_probe_results[probe_index] = 5u;
    working_track_raw_q_probe_result_count = 6u;
    assert(ProbeAndClassifyWorkingTrackBeforeStart() == 0u);

    clear_memory(0u);
    for(probe_index = 0u; probe_index != 6u; ++probe_index)
        working_track_raw_q_probe_results[probe_index] = 9u;
    working_track_raw_q_probe_result_count = 6u;
    assert(ProbeAndClassifyWorkingTrackBeforeStart() == 0u);

    clear_memory(0u);
    working_track_raw_q_probe_results[0] = 1u;
    working_track_raw_q_probe_result_count = 1u;
    firmware_memory[0x2bb91cu] = 1u;
    assert(ProbeAndClassifyWorkingTrackBeforeStart() == 1u);
    assert(firmware_memory[0xdd37u] == 1u && firmware_memory[0xdd38u] == 0x40u);

    clear_memory(0u);
    working_track_raw_q_probe_results[0] = 1u;
    working_track_raw_q_probe_result_count = 1u;
    firmware_memory[0x0f64u] = 0x50u;
    firmware_memory[0x2bb91cu] = 1u;
    assert(ProbeAndClassifyWorkingTrackBeforeStart() == 0u);
    assert(firmware_memory[0xdd37u] == 1u && firmware_memory[0xdd38u] == 0x40u);
}

