static void test_apply_raw_q_probe_status_to_working_track_state(void)
{
    unsigned status;

    for(status = 0u; status < 256u; ++status)
    {
        u8 result;
        u8 expected_result = 0xa5u;
        unsigned expected_reads = 12u;
        unsigned expected_writes = 0u;

        clear_memory(0xa5u);
        set_memory_big_endian_u32(0x1153u, 0x11111111ul);
        set_memory_big_endian_u32(0xdd3du, 0x12345678ul);
        set_memory_big_endian_u32(0x0f41u, 0x44444444ul);
        working_track_probe_state_inherited_r15 = 0xa5u;
        working_track_probe_state_refined_frame = (s32)0x87654321ul;
        working_track_probe_state_status = (u8)status;
        working_track_probe_state_capture_count = 0u;
        working_track_probe_state_refine_count = 0u;
        working_track_probe_state_probe_count = 0u;
        read_count = write_count = 0u;

        result = ApplyRawQProbeStatusToWorkingTrackState();

        if(status == 1u || status == 6u)
        {
            expected_result = 1u;
            expected_reads = 16u;
            expected_writes = 4u;
        }
        else if(status == 4u || status == 7u)
        {
            expected_result = 1u;
            expected_reads = 16u;
            expected_writes = 5u;
        }
        else if(status == 5u)
        {
            expected_result = 0u;
        }
        assert(result == expected_result);
        assert(working_track_probe_state_capture_count == 1u);
        assert(working_track_probe_state_refine_count == 1u);
        assert(working_track_probe_state_probe_count == 1u);
        assert((u32)working_track_probe_state_refine_initial == 0x12345678ul);
        assert((u32)working_track_probe_state_refine_upper == 0x11111111ul);
        assert((u32)working_track_probe_state_probe_initial == 0x87654321ul);
        assert((u32)working_track_probe_state_probe_reference == 0x22222222ul);
        assert(read_count == expected_reads && write_count == expected_writes);
        assert(read_trace[0] == 0x1153ul && read_trace[3] == 0x1156ul);
        assert(read_trace[4] == 0xdd3dul && read_trace[7] == 0xdd40ul);
        assert(read_trace[8] == 0x1153ul && read_trace[11] == 0x1156ul);

        if(status == 1u)
        {
            assert(get_memory_big_endian_u32(0xdd45u) == 0x33333333ul);
            assert(write_trace[0] == 0xdd45ul && write_trace[3] == 0xdd48ul);
        }
        else if(status == 6u)
        {
            assert(get_memory_big_endian_u32(0xdd45u) == 0x44444444ul);
            assert(write_trace[0] == 0xdd45ul && write_trace[3] == 0xdd48ul);
        }
        else if(status == 4u || status == 7u)
        {
            assert(firmware_memory[0xdd34u] == 6u);
            assert(get_memory_big_endian_u32(0xdd51u) == 0x44444444ul);
            assert(write_trace[0] == 0xdd34ul && write_trace[1] == 0xdd51ul && write_trace[4] == 0xdd54ul);
        }
    }
}

static void test_apply_raw_q_probe_status_to_working_track_tail(void)
{
    unsigned status;

    for(status = 0u; status < 256u; ++status)
    {
        u8 result;
        u8 expected_result = 0x5au;
        unsigned expected_reads = 12u;
        unsigned expected_writes = 0u;

        clear_memory(0xa5u);
        set_memory_big_endian_u32(0x1153u, 0x11111111ul);
        set_memory_big_endian_u32(0xdd3du, 0x12345678ul);
        set_memory_big_endian_u32(0x0f41u, 0x44444444ul);
        working_track_probe_state_inherited_r15 = 0x5au;
        working_track_probe_state_refined_frame = (s32)0x87654321ul;
        working_track_probe_state_status = (u8)status;
        working_track_probe_state_capture_count = 0u;
        working_track_probe_state_refine_count = 0u;
        working_track_probe_state_probe_count = 0u;
        read_count = write_count = 0u;

        result = ApplyRawQProbeStatusToWorkingTrackTail();

        if(status == 1u || status == 4u || status == 6u || status == 7u)
        {
            expected_result = 1u;
            expected_reads = 16u;
            expected_writes = 4u;
        }
        else if(status == 5u)
        {
            expected_result = 0u;
        }
        assert(result == expected_result);
        assert(working_track_probe_state_capture_count == 1u);
        assert(working_track_probe_state_refine_count == 1u);
        assert(working_track_probe_state_probe_count == 1u);
        assert((u32)working_track_probe_state_refine_initial == 0x12345678ul);
        assert((u32)working_track_probe_state_refine_upper == 0x11111111ul);
        assert((u32)working_track_probe_state_probe_initial == 0x87654321ul);
        assert((u32)working_track_probe_state_probe_reference == 0x22222222ul);
        assert(read_count == expected_reads && write_count == expected_writes);

        if(status == 1u)
        {
            assert(get_memory_big_endian_u32(0xdd45u) == 0x33333333ul);
            assert(write_trace[0] == 0xdd45ul && write_trace[3] == 0xdd48ul);
        }
        else if(status == 4u || status == 6u || status == 7u)
        {
            assert(get_memory_big_endian_u32(0xdd51u) == 0x44444444ul);
            assert(write_trace[0] == 0xdd51ul && write_trace[3] == 0xdd54ul);
        }
    }
}

static void test_process_indexed_state_group(void)
{
    static const struct
    {
        u8 layout;
        u8 cursor;
        u8 terminal_flag;
        u8 inherited_r15;
        u8 expected_result;
        u8 expected_track;
        u32 expected_target;
        u8 writes_target;
    } cases[] = {
        { 0x0fu, 1u,    1u,    0x42u, 0u, 0x0fu, 0x0002df5ful, 1u },
        { 0x0fu, 0u,    1u,    0x42u, 0u, 1u,    0x00000096ul, 1u },
        { 0x0fu, 2u,    1u,    0x42u, 1u, 0u,    0ul,          0u },
        { 0x0fu, 2u,    2u,    0x42u, 0u, 1u,    0x00000096ul, 1u },
        { 0x10u, 1u,    0u,    0x42u, 0u, 0x0du, 0x00030525ul, 1u },
        { 0x10u, 2u,    1u,    0x42u, 1u, 0u,    0ul,          0u },
        { 0x18u, 0x0fu, 0u,    0x42u, 0u, 0x13u, 0x00031eb1ul, 1u },
        { 0x18u, 9u,    0u,    0x42u, 0u, 0x0fu, 0x000281bful, 1u },
        { 0x18u, 0x13u, 1u,    0x42u, 1u, 0u,    0ul,          0u },
        { 0x18u, 0x13u, 0u,    0x42u, 0u, 9u,    0x00016839ul, 1u },
        { 0x18u, 7u,    0xffu, 0x42u, 0u, 9u,    0x00016839ul, 1u },
        { 0x12u, 0x55u, 1u,    0x42u, 0u, 0x42u, 0xa5a5a5a5ul, 0u }
    };
    unsigned case_index;

    for(case_index = 0u; case_index != sizeof(cases) / sizeof(cases[0]); ++case_index)
    {
        u8 result;

        clear_memory(0xa5u);
        firmware_memory[0x12c0u] = cases[case_index].layout;
        firmware_memory[0x0fbbu] = cases[case_index].cursor;
        set_memory_big_endian_u32(0xfbf8u, 0xa5a5a5a5ul);
        bit_0018 = 1u;
        indexed_state_group_inherited_r15 = cases[case_index].inherited_r15;
        indexed_state_group_capture_count = 0u;
        indexed_state_group_clear_count = 0u;
        indexed_state_group_initialize_count = 0u;
        indexed_state_group_initialize_entry = 0ul;
        read_count = write_count = 0u;

        result = ProcessIndexedStateGroup(cases[case_index].terminal_flag);

        assert(result == cases[case_index].expected_result);
        assert(indexed_state_group_capture_count == 1u);
        if(cases[case_index].expected_result != 0u)
        {
            assert(write_count == 1u && write_trace[0] == 0x0faful);
            assert(firmware_memory[0x0fafu] == 3u);
            assert(indexed_state_group_clear_count == 0u);
            assert(indexed_state_group_initialize_count == 0u);
            assert(bit_0018 == 1u);
            continue;
        }

        assert(get_memory_big_endian_u32(0xfbf8u) == cases[case_index].expected_target);
        assert(get_memory_big_endian_u32(0x0f36u) == 0x000002eeul);
        assert(firmware_memory[0x0fbbu] == cases[case_index].expected_track);
        assert(firmware_memory[0x0e42u] == cases[case_index].expected_track);
        assert(indexed_state_group_clear_count == 1u && bit_0018 == 0u);
        assert(indexed_state_group_initialize_count == 1u);
        assert(indexed_state_group_initialize_entry == 0x00fd4f8eul);
        assert(write_count == (cases[case_index].writes_target != 0u ? 10u : 6u));
    }
}

