    raw_q_offset_probe_results[0] = 6u;
    raw_q_offset_probe_result_count = 1u;
    assert(ProbeWorkingTrackEndAndUpdateState() == 1u);
    assert(raw_q_offset_probe_targets[0] == 125ul && get_memory_big_endian_u32(0xdd45u) == 150ul);

    clear_memory(0u);
    set_memory_big_endian_u32(0xdd39u, 0ul);
    set_memory_big_endian_u32(0xdd41u, 200ul);
    raw_q_target_acquire_result = 1u;
