    assert(ProbeWorkingTrackEndAndUpdateState() == 1u);
    assert(raw_q_refine_probe_candidates[0] == 147 && raw_q_offset_probe_targets[0] == 68ul && firmware_memory[0xdd34u] == 5u && get_memory_big_endian_u32(0xdd51u) == 180ul);

    clear_memory(0u);
