    raw_q_offset_probe_results[0] = 5u;
    raw_q_offset_probe_results[1] = 5u;
    raw_q_offset_probe_results[2] = 5u;
    raw_q_offset_probe_result_count = 3u;
    assert(ProbeWorkingTrackEndAndUpdateState() == 0u);

    clear_memory(0u);
    set_memory_big_endian_u32(0xdd41u, 75ul);
    set_memory_big_endian_u32(0x0f41u, 75ul);
    firmware_memory[0xdd36u] = 0x50u;
    raw_q_offset_probe_results[0] = 6u;
    raw_q_offset_probe_result_count = 1u;
    assert(ProbeWorkingTrackEndAndUpdateState() == 1u);
    assert(firmware_memory[0xdd34u] == 4u);

    clear_memory(0u);
    set_memory_big_endian_u32(0xdd41u, 75ul);
    set_memory_big_endian_u32(0x0f41u, 70ul);
    raw_q_offset_probe_results[0] = 7u;
    raw_q_offset_probe_results[1] = 7u;
    raw_q_offset_probe_results[2] = 7u;
    raw_q_offset_probe_result_count = 3u;
    assert(ProbeWorkingTrackEndAndUpdateState() == 1u);
    assert(firmware_memory[0xdd34u] == 5u && get_memory_big_endian_u32(0xdd51u) == 70ul);

    clear_memory(0u);
