    firmware_memory[descriptor1] = 5u;
    firmware_memory[descriptor1 + 3u] = 2u;
    firmware_memory[descriptor2] = 5u;
    firmware_memory[descriptor2 + 3u] = 0xa1u;
    firmware_memory[descriptor2 + 8u] = 3u;
    firmware_memory[descriptor3] = 5u;
    firmware_memory[descriptor3 + 3u] = 0xa2u;
    firmware_memory[descriptor3 + 9u] = 10u;
    firmware_memory[0xf2cbu + 1u] = 4u;
    DeriveWorkingTrackEndFrameFromPmaOrToc(2u);
    assert(get_memory_big_endian_u32(0xdd41u) == 300ul && firmware_memory[0xdd5fu] == 0u);
    assert(firmware_memory[0xfe30u] == 0u && firmware_memory[0xfe31u] == 10u && firmware_memory[0xfe32u] == 0u);

    clear_memory(0u);
