    firmware_memory[0x00dd34u] = 0xa5u;
    write_prefix_frames_result = 0u;
    assert(PrepareWriteCommandRawReadPrefix() == 0u);
    assert(get_memory_big_endian_u32(0x001598u) == 0xfffffffcul && firmware_memory[0x0014b4u] == 0u && firmware_memory[0x00dd34u] == 1u && firmware_memory[0x0014b5u] == 0u);
    assert(write_prefix_frames_call_count == 1u && write_prefix_frames_omit == 1u && write_prefix_frames_wait == 0u && write_prefix_plan_call_count == 0u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x00dd4du, 100ul);
    set_memory_big_endian_u32(0x001598u, 107ul);
    firmware_memory[0x00dd34u] = 0x5au;
    write_prefix_plan_result = 0u;
    assert(PrepareWriteCommandRawReadPrefix() == 0u);
    assert(get_memory_big_endian_u32(0x001598u) == 100ul && firmware_memory[0x0014b6u] == 1u && firmware_memory[0x00dd34u] == 1u);
    assert(write_prefix_frames_call_count == 1u && write_prefix_plan_call_count == 1u && write_prefix_plan_alternate == 0u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x00dd4du, 100ul);
    set_memory_big_endian_u32(0x001598u, 107ul);
    firmware_memory[0x00dd34u] = 0x5au;
    assert(PrepareWriteCommandRawReadPrefix() == 1u);
    assert(get_memory_big_endian_u32(0x001598u) == 100ul && firmware_memory[0x0014b6u] == 0u && firmware_memory[0x00dd34u] == 0x5au);

    clear_memory(0u);
    firmware_memory[0x000c44u] = 2u;
    firmware_memory[0x0088b5u] = 1u;
    set_memory_big_endian_u32(0x001598u, 0ul);
    assert(PrepareWriteCommandRawReadPrefix() == 1u);
    assert(firmware_memory[0x000c2au] == 6u && firmware_memory[0x00127eu] == 0u && firmware_memory[0x0088b5u] == 0u);
    assert(write_prefix_advance_call_count == 1u && write_prefix_refresh_call_count == 1u && write_prefix_event_count == 2u && write_prefix_events[0] == 1u && write_prefix_events[1] == 2u);

    clear_memory(0u);
