static void test_handle_read6_command(void)
{
    static const u8 transfer_lengths[2] = { 0u, 0xfeu };
    static const u32 expected_counts[2] = { 0x100ul, 0xfeul };
    unsigned case_index;

    clear_memory(0u);
    firmware_memory[0x0b0ful] = 0xfcu;
    HandleRead6Command();
    assert(read_command_transfer_call_count == 0u && read_verify_event_count == 0u && bit_0046 == 0u);
    assert(read_count == 1u && read_trace[0] == 0x0b0ful);
    assert(firmware_memory[0x0b1aul] == 5u && firmware_memory[0x0b24ul] == 0x24u && firmware_memory[0x0b25ul] == 0u);

    for(case_index = 0u; case_index < 2u; ++case_index)
    {
        clear_memory(0u);
        firmware_memory[0x0b0aul] = 0xe1u;
        firmware_memory[0x0b0bul] = 0x23u;
        firmware_memory[0x0b0cul] = 0x45u;
        firmware_memory[0x0b0dul] = 0x67u;
        firmware_memory[0x0b0eul] = transfer_lengths[case_index];
        firmware_memory[0x0b0ful] = 3u;
        HandleRead6Command();

        assert(get_memory_big_endian_u32(0x0b02u) == 0x00034567ul);
        assert(get_memory_big_endian_u32(0x0b06u) == expected_counts[case_index]);
        assert(read_verify_event_count == 3u && read_verify_events[0] == 1u && read_verify_events[1] == 2u && read_verify_events[2] == 3u);
        assert(read_command_transfer_call_count == 1u && read_command_transfer_seen_bit0046 == 1u && bit_0046 == 0u);
        assert(read_command_transfer_seen_read_count == 8u && read_command_transfer_seen_write_count == 8u);
        assert(read_count == 8u && read_trace[0] == 0x0b0ful && read_trace[1] == 0x0b0aul && read_trace[4] == 0x0b0dul && read_trace[5] == 0x0b0eul && read_trace[6] == 0x0c9eul
               && read_trace[7] == 0x15d7ul);
        assert(write_count == 8u && write_trace[0] == 0x0b02ul && write_trace[3] == 0x0b05ul && write_trace[4] == 0x0b06ul && write_trace[7] == 0x0b09ul);
    }
}

