    assert(read_verify_event_count == 3u && read_verify_events[0] == 1u && read_verify_events[1] == 2u && read_verify_events[2] == 3u);
    assert(read_cd_command_call_count == 1u && read_cd_command_seen_bit0021 == 0u && read_cd_command_seen_bit0046 == 1u && bit_0046 == 0u);
    assert(read_cd_command_seen_read_count == 14u && read_cd_command_seen_write_count == 12u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x0b0cu, 0x80000010ul);
    set_memory_big_endian_u32(0x0b10u, 0x000001fful);
