    assert(get_memory_big_endian_u32(0x0b02u) == 0x12345678ul && get_memory_big_endian_u32(0x0b06u) == 0x9abcdef0ul);
    assert(read_or_seek_dispatch_call_count == 0u && read_verify_event_count == 3u && read_verify_events[0] == 1u && read_verify_events[1] == 2u && read_verify_events[2] == 3u);
