    clear_memory(0u);
    firmware_memory[0x0b0bu] = 8u;
    firmware_memory[0x1292u] = 0xa5u;
    firmware_memory[0x1293u] = 0xa5u;
    firmware_memory[0x156au] = 0u;
    firmware_memory[0x156bu] = 0x20u;
