    firmware_memory[0x0c2au] = 2u;
    HandleReadCdMsfCommand();
    assert((s32)get_memory_big_endian_u32(0x0b02u) == -150l && get_memory_big_endian_u32(0x0b06u) == 10ul && get_memory_big_endian_u32(0x1455u) == 10ul);
    assert(read_cd_command_call_count == 1u && read_cd_command_seen_bit0021 == 1u && read_cd_command_seen_bit0002 == 1u && read_cd_command_seen_bit001b == 1u && read_cd_command_seen_bit0046 == 1u);
    assert(bit_0021 == 1u && bit_0002 == 0u && bit_001b == 0u && bit_0046 == 0u);

    clear_memory(0u);
