    firmware_memory[0x9010u] = 0u;
    set_memory_big_endian_u16(0x129cu, 2u);
    assert((u8)ValidateLatestCdTextRawSectorPackBatch() == 0xfeu);
    set_memory_big_endian_u16(0x129cu, 1u);
    assert(ValidateLatestCdTextRawSectorPackBatch() == 0);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 1u);
    set_memory_big_endian_u16(0x1296u, 1u);
    set_memory_big_endian_u16(0x129au, 0u);
