static void test_handle_write_and_verify10_command(void)
{
    reset_write_and_verify_command_observers();
    firmware_memory[0x0c8au] = 0xc0u;
    firmware_memory[0x0b0bu] = 1u;
    HandleWriteAndVerify10CommandForTest();
    assert(firmware_memory[0x0c8au] == 0xa0u);
    assert(write_and_verify_unsupported_count == 1u && write_and_verify_prepare_count == 0u);
    assert(bit_0002 == 1u && write_and_verify_active_count == 1u && write_and_verify_active_history[0] == 1u);

    reset_write_and_verify_command_observers();
    firmware_memory[0x0b10u] = 1u;
    HandleWriteAndVerify10CommandForTest();
    assert(write_and_verify_unsupported_count == 1u && bit_0002 == 1u);

    reset_write_and_verify_command_observers();
    write_and_verify_length_form = 1u;
    firmware_memory[0x0b14u] = 1u;
    HandleWriteAndVerify10CommandForTest();
    assert(write_and_verify_unsupported_count == 1u && bit_0002 == 1u);

    reset_write_and_verify_command_observers();
    set_memory_big_endian_u32(0x0b0cu, 0x89abcdeful);
    set_memory_big_endian_u16(0x0b11u, 0x1234u);
    firmware_memory[0x0b13u] = 3u;
    HandleWriteAndVerify10CommandForTest();
    assert(write_and_verify_prepare_count == 1u && write_and_verify_start_count == 1u);
    assert(write_and_verify_start_address == 0x89abcdeful && write_and_verify_block_count == 0x1234ul);
    assert(bit_0002 == 1u && write_and_verify_active_count == 1u);

    reset_write_and_verify_command_observers();
    write_and_verify_length_form = 1u;
    write_and_verify_start_result = 1u;
    write_and_verify_start_c8a_or = 0x40u;
    set_memory_big_endian_u32(0x0b0cu, 0x01234567ul);
    set_memory_big_endian_u32(0x0b10u, 0x0000007ful);
    HandleWriteAndVerify10CommandForTest();
    assert(write_and_verify_block_count == 0x7ful);
    assert(write_and_verify_no_sense_count == 1u && write_and_verify_range_count == 0u);
    assert(bit_0002 == 0u && write_and_verify_active_count == 2u && write_and_verify_active_history[0] == 1u && write_and_verify_active_history[1] == 0u);

    reset_write_and_verify_command_observers();
    write_and_verify_start_result = 1u;
    set_memory_big_endian_u16(0x1292u, 0x0248u);
    HandleWriteAndVerify10CommandForTest();
    assert(write_and_verify_no_sense_count == 1u && write_and_verify_range_count == 0u && bit_0002 == 0u);

    reset_write_and_verify_command_observers();
    write_and_verify_start_result = 1u;
    set_memory_big_endian_u16(0x1292u, 0x0249u);
    set_memory_big_endian_u16(0x0b11u, 0x0203u);
    HandleWriteAndVerify10CommandForTest();
    assert(write_and_verify_range_count == 1u && write_and_verify_block_count == 0x0203ul);
    assert(write_and_verify_readback_count == 0u && bit_0002 == 0u);

    reset_write_and_verify_command_observers();
    write_and_verify_start_result = 1u;
    write_and_verify_range_result = 1u;
    set_memory_big_endian_u16(0x1292u, 0xffffu);
    firmware_memory[0x0c85u] = 0xffu;
    firmware_memory[0x0c84u] = 0xffu;
    HandleWriteAndVerify10CommandForTest();
    assert(write_and_verify_range_count == 1u && write_and_verify_readback_count == 1u);
    assert(firmware_memory[0x0c85u] == 0xfeu && firmware_memory[0x0c84u] == 0xf7u && bit_0002 == 0u);
}

static void test_finalize_read_verify_command_state(void)
{
    clear_memory(0u);
    FinalizeReadVerifyCommandStateForTest();
    assert(read_count == 1u && read_trace[0] == 0x000c9eul && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x000c9eu] = 1u;
    firmware_memory[0x2ba5b1u] = 1u;
    FinalizeReadVerifyCommandStateForTest();
    assert(read_count == 2u && read_trace[1] == 0x2ba5b1ul && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x000c9eu] = 2u;
    firmware_memory[0x000c89u] = 0x81u;
    FinalizeReadVerifyCommandStateForTest();
    assert(firmware_memory[0x000c89u] == 0x89u && firmware_memory[0x00122bu] == 20u);
    assert(read_count == 5u && read_trace[0] == 0x000c9eul && read_trace[1] == 0x2ba5b1ul && read_trace[2] == 0x2ba5aful && read_trace[3] == 0x000c89ul && read_trace[4] == 0x00e750ul);

    clear_memory(0u);
    firmware_memory[0x000c9eu] = 1u;
    firmware_memory[0x00e750u] = 1u;
    FinalizeReadVerifyCommandStateForTest();
    assert(firmware_memory[0x00122bu] == 60u);

    clear_memory(0u);
    firmware_memory[0x000c9eu] = 1u;
    firmware_memory[0x2ba5afu] = 1u;
    firmware_memory[0x000c89u] = 0x7fu;
    FinalizeReadVerifyCommandStateForTest();
    assert(write_count == 0u && read_count == 4u);

    clear_memory(0u);
    firmware_memory[0x000c9eu] = 1u;
    firmware_memory[0x2ba5afu] = 1u;
    firmware_memory[0x000c89u] = 0x80u;
    firmware_memory[0x000c8au] = 0x20u;
    FinalizeReadVerifyCommandStateForTest();
    assert(firmware_memory[0x000c8au] == 0x21u && firmware_memory[0x00122cu] == 10u);

    clear_memory(0u);
    firmware_memory[0x000c9eu] = 2u;
    firmware_memory[0x2ba5afu] = 1u;
    firmware_memory[0x000c89u] = 0x80u;
    firmware_memory[0x000c8bu] = 8u;
    FinalizeReadVerifyCommandStateForTest();
    assert(firmware_memory[0x00122cu] == 60u);

    clear_memory(0u);
    firmware_memory[0x000c9eu] = 3u;
    firmware_memory[0x000c89u] = 0x7fu;
    FinalizeReadVerifyCommandStateForTest();
    assert(write_count == 0u && read_count == 2u);

    clear_memory(0u);
    firmware_memory[0x000c9eu] = 3u;
    firmware_memory[0x000c89u] = 0x80u;
    firmware_memory[0x000c8au] = 0x40u;
    firmware_memory[0x000c8bu] = 8u;
    FinalizeReadVerifyCommandStateForTest();
    assert(firmware_memory[0x000c8au] == 0x41u && firmware_memory[0x00122cu] == 60u);

    clear_memory(0u);
    invalid_read_verify_finalize_mode_count = 0u;
    firmware_memory[0x000c9eu] = 4u;
    FinalizeReadVerifyCommandStateForTest();
    assert(invalid_read_verify_finalize_mode_count == 1u);
}

