    assert(position_probe_event_count == 7u && write_count == 17u);
    for(index = 0u; index < 7u; ++index)
        assert(position_probe_events[index] == ordinary_events[index]);
    assert(firmware_memory[0xefdu] == 0x21u && firmware_memory[0x18006u] == 0x21u && firmware_memory[0xefcu] == 0x4cu && firmware_memory[0x18005u] == 0x4cu && firmware_memory[0xfadu] == 0x23u
           && firmware_memory[0x18003u] == 0x23u && firmware_memory[0xf76u] == 0x7du);
    assert(write_trace[4] == 0x18002ul && write_values[4] == 0u && write_trace[6] == 0x18004ul && write_values[6] == 0u && write_trace[8] == 0x18006ul && write_values[8] == 0x21u
           && write_trace[10] == 0x18005ul && write_values[10] == 0x4cu && write_trace[11] == 0x1802dul && write_values[11] == 0x28u && write_trace[13] == 0x18019ul && write_values[13] == 0u
           && write_trace[15] == 0x18003ul && write_values[15] == 0x23u);

    clear_memory(0u);
    position_probe_special_bits = 2u;
    firmware_memory[0xf06u] = 1u;
    firmware_memory[0xefeu] = 0xf3u;
    firmware_memory[0xfadu] = 1u;
    InitializeRawReadControllerForPositionProbe();
    assert(position_probe_event_count == 6u && write_count == 22u);
    for(index = 0u; index < 6u; ++index)
        assert(position_probe_events[index] == short_circuit_events[index]);
    assert(firmware_memory[0xefcu] == 0xccu && firmware_memory[0x18005u] == 0xccu && firmware_memory[0x18019u] == 0x60u && firmware_memory[0xefeu] == 0x97u && firmware_memory[0x18018u] == 0x97u
           && firmware_memory[0xfadu] == 0x29u && firmware_memory[0x18003u] == 0x29u);
    assert(write_trace[15] == 0xefeul && write_values[15] == 0x13u && write_trace[16] == 0x18018ul && write_values[16] == 0x13u && write_trace[17] == 0xefeul && write_values[17] == 0x97u
           && write_trace[18] == 0x18018ul && write_values[18] == 0x97u);

