static void test_increment_type2_controller_record_slot_value(void)
{
    static const u8 slot_indices[] = { 0u, 1u, 7u, 0xffu };
    static const u32 initial_values[] = { 0ul, 1ul, 0x00fffffful, 0x7ffffffful, 0xfffffffful };
    unsigned slot_index;
    unsigned value_index;

    for(slot_index = 0u; slot_index < sizeof(slot_indices); ++slot_index)
    {
        u32 controller_offset = 0x00094004ul + ((u32)slot_indices[slot_index] << 14);
        fw_addr_t mapped_address = controller_offset + 0x00100000ul;

        for(value_index = 0u; value_index < sizeof(initial_values) / sizeof(initial_values[0]); ++value_index)
        {
            u32 expected = initial_values[value_index] + 1ul;

            clear_memory(0xa5u);
            set_memory_big_endian_u32_far(mapped_address, initial_values[value_index]);
            IncrementType2ControllerRecordSlotValue(slot_indices[slot_index]);
            assert(get_memory_big_endian_u32(mapped_address) == expected);
            assert(get_memory_big_endian_u32(0x2ba633ul) == expected);
            assert(get_memory_big_endian_u32(0x2ba584ul) == expected);
        }
    }
}

static void set_primary_type2_packed_position(u8 descriptor_index, u32 value)
{
    fw_addr_t address = 0x2bb938ul + (u16)descriptor_index * 3u;

    firmware_memory[address + 1u] = (u8)(value >> 16);
    firmware_memory[address + 2u] = (u8)(value >> 8);
    firmware_memory[address + 3u] = (u8)value;
}

static void test_initialize_primary_type2_controller_record_descriptors(void)
{
    u8 index;

    clear_memory(0xa5u);
    for(index = 0u; index < 8u; ++index)
        set_primary_type2_packed_position(index, (u32)(7u - index));
    InitializePrimaryType2ControllerRecordDescriptorsAndBounds();
    for(index = 0u; index < 8u; ++index)
    {
        u32 expected = 0xfff00000ul | (u32)(7u - index);

        assert(get_memory_big_endian_u32(0x2bfb04ul + (u16)index * 5u) == expected);
        assert(firmware_memory[0x2bfb08ul + (u16)index * 5u] == 0xa5u);
        assert(get_memory_big_endian_u32(0x2ba537ul + (u16)index * 4u) == expected);
    }
    assert(get_memory_big_endian_u32(0x2ba577ul) == 0xfff00000ul);
    assert(read_count == 124u && write_count == 92u);
    assert(read_trace[0] == 0x2bb93aul && read_trace[1] == 0x2bb93bul && read_trace[2] == 0x2bb938ul && read_trace[3] == 0x2bb939ul);
    assert(write_trace[0] == 0x2bfb06ul && write_trace[1] == 0x2bfb07ul && write_trace[2] == 0x2bfb04ul && write_trace[3] == 0x2bfb05ul && write_trace[4] == 0x2ba539ul && write_trace[5] == 0x2ba53aul
           && write_trace[6] == 0x2ba537ul && write_trace[7] == 0x2ba538ul);

    clear_memory(0x5au);
    for(index = 0u; index < 8u; ++index)
    {
        set_memory_big_endian_u32_far(0x2bfb04ul + (u16)index * 5u, 0xfff00010ul + index);
        set_memory_big_endian_u32_far(0x2ba537ul + (u16)index * 4u, 0x11223300ul + index);
        set_primary_type2_packed_position(index, 0x000100ul + index);
    }
    set_primary_type2_packed_position(6u, 0x000002ul);
    set_primary_type2_packed_position(7u, 0x000001ul);
    InitializePrimaryType2ControllerRecordDescriptorsAndBoundsFromIndex(6u);
    for(index = 0u; index < 6u; ++index)
    {
        assert(get_memory_big_endian_u32(0x2bfb04ul + (u16)index * 5u) == 0xfff00010ul + index);
        assert(get_memory_big_endian_u32(0x2ba537ul + (u16)index * 4u) == 0x11223300ul + index);
    }
    assert(get_memory_big_endian_u32(0x2bfb22ul) == 0xfff00002ul);
    assert(get_memory_big_endian_u32(0x2bfb27ul) == 0xfff00001ul);
    assert(get_memory_big_endian_u32(0x2ba54ful) == 0xfff00002ul);
    assert(get_memory_big_endian_u32(0x2ba553ul) == 0xfff00001ul);
    assert(get_memory_big_endian_u32(0x2ba577ul) == 0xfff00001ul);

    clear_memory(0x3cu);
    for(index = 0u; index < 8u; ++index)
        set_memory_big_endian_u32_far(0x2bfb04ul + (u16)index * 5u, 0xfff00020ul + index);
    InitializePrimaryType2ControllerRecordDescriptorsAndBoundsFromIndex(8u);
    assert(get_memory_big_endian_u32(0x2ba577ul) == 0xfff00020ul);
    assert(read_trace[0] == 0x2bfb06ul && write_count == 4u);
}

