    assert(reset_range_capture_count == 1u && reset_range_acquire_count == 1u && reset_range_acquire_frame_count == 0x12345678ul && reset_range_acquire_mode == 0u && reset_range_acquire_preserve == 1u
           && reset_range_poll_count == 1u && reset_range_poll_argument == 1u);
    assert(get_memory_big_endian_u16(0x1298ul) == 0u && get_memory_big_endian_u16(0x1294ul) == 0u && get_memory_big_endian_u16(0x1296ul) == 0u && get_memory_big_endian_u16(0x1292ul) == 0u
           && get_memory_big_endian_u16(0x129aul) == 3u && get_memory_big_endian_u16(0x129cul) == 0xfffeu);
    assert(get_memory_big_endian_u32(0x129eul) == 0x000088bbul && get_memory_big_endian_u32(0x1262ul) == 0ul && get_memory_big_endian_u32(0x1266ul) == 0ul
           && get_memory_big_endian_u32(0x126aul) == 0x89abcdeful && get_memory_big_endian_u32(0x126eul) == 0ul && get_memory_big_endian_u32(0x1598ul) == 0xffffff85ul
           && firmware_memory[0x127dul] == 0u);

    clear_memory(0u);
    reset_range_inherited_r15 = 0x5au;
    firmware_memory[0xfb9au] = 1u;
    reset_range_release_after_yields = 2u;
    assert(ResetAndAcquireRawReadRange(0x10203l, 7ul, 2u) == 1u);
    assert(reset_range_event_count == sizeof(waited_success_events) && memcmp(reset_range_events, waited_success_events, sizeof(waited_success_events)) == 0);
    assert(reset_range_acquire_frame_count == 7ul && reset_range_acquire_mode == 2u && reset_range_acquire_preserve == 0x5au && reset_range_yield_count == 2u
           && get_memory_big_endian_u32(0x1598ul) == 0x10203ul);

    clear_memory(0u);
