    assert(ResetAndAcquireRawReadRange(1l, 2ul, 1u) == 0u);
    assert(reset_range_event_count == sizeof(acquisition_failure_events) && memcmp(reset_range_events, acquisition_failure_events, sizeof(acquisition_failure_events)) == 0
           && reset_range_poll_count == 0u);

    clear_memory(0u);
    reset_range_poll_result = 0u;
    firmware_memory[0x0c84ul] = 0x40u;
    assert(ResetAndAcquireRawReadRange(1l, 2ul, 1u) == 0u);
    assert(reset_range_event_count == sizeof(pipeline_failure_events) && memcmp(reset_range_events, pipeline_failure_events, sizeof(pipeline_failure_events)) == 0 && reset_range_failure_count == 1u
           && reset_range_failure_code == 8u && reset_range_sense030c09_count == 0u);

    clear_memory(0u);
    reset_range_poll_result = 0u;
    assert(ResetAndAcquireRawReadRange(1l, 2ul, 1u) == 0u);
    assert(reset_range_event_count == sizeof(sense_failure_events) && memcmp(reset_range_events, sense_failure_events, sizeof(sense_failure_events)) == 0 && reset_range_failure_count == 0u
           && reset_range_sense030c09_count == 1u);

    clear_memory(0u);
