static void test_adjust_encoded_media_calibration_offset_for_current_write_speed(void)
{
    static const u8 write_speeds[] = { 1u, 4u, 8u, 16u, 20u, 24u, 32u, 40u, 52u };
    static const fw_addr_t slot_addresses[] = { 0xfadcul, 0xfaddul, 0xfadeul, 0xfadful, 0xfadful, 0xfadful, 0xfadful, 0xfadful, 0xfadful };
    unsigned speed_index;
    unsigned slot_index;

    for(speed_index = 0u; speed_index < sizeof(write_speeds) / sizeof(write_speeds[0]); ++speed_index)
    {
        clear_memory(0u);
        set_memory_big_endian_u16(0xfaacul, 0x0002u);
        firmware_memory[0x0e47ul] = write_speeds[speed_index];
        firmware_memory[0x0ff2ul] = 3u;
        firmware_memory[0xfadcul] = 10u;
        firmware_memory[0xfaddul] = 10u;
        firmware_memory[0xfadeul] = 10u;
        firmware_memory[0xfadful] = 10u;

        AdjustEncodedMediaCalibrationOffsetForCurrentWriteSpeed();

        for(slot_index = 0u; slot_index < 4u; ++slot_index)
        {
            fw_addr_t slot = 0xfadcul + slot_index;
            assert(firmware_memory[slot] == (slot == slot_addresses[speed_index] ? 11u : 10u));
        }
    }

    clear_memory(0u);
    firmware_memory[0x0e47ul] = 1u;
    firmware_memory[0x0ff2ul] = 2u;
    firmware_memory[0xfadcul] = EncodeSignedByteAsSignMagnitude(-5);
    AdjustEncodedMediaCalibrationOffsetForCurrentWriteSpeed();
    assert(firmware_memory[0xfadcul] == EncodeSignedByteAsSignMagnitude(-7));

    clear_memory(0u);
    firmware_memory[0x0e47ul] = 4u;
    firmware_memory[0x0ff2ul] = 0u;
    firmware_memory[0xfaddul] = 0xffu;
    AdjustEncodedMediaCalibrationOffsetForCurrentWriteSpeed();
    assert(firmware_memory[0xfaddul] == 0u);

    clear_memory(0u);
    firmware_memory[0x0e47ul] = 8u;
    firmware_memory[0x0ff2ul] = 3u;
    firmware_memory[0xfadeul] = 127u;
    AdjustEncodedMediaCalibrationOffsetForCurrentWriteSpeed();
    assert(firmware_memory[0xfadeul] == 0xffu);

    clear_memory(0u);
    firmware_memory[0x0e47ul] = 16u;
    firmware_memory[0x0ff2ul] = 2u;
    firmware_memory[0xfadful] = EncodeSignedByteAsSignMagnitude(-126);
    AdjustEncodedMediaCalibrationOffsetForCurrentWriteSpeed();
    assert(firmware_memory[0xfadful] == 0x80u);

    clear_memory(0u);
    firmware_memory[0x0e47ul] = 12u;
    firmware_memory[0x0ff2ul] = 3u;
    firmware_memory[0xfadcul] = 0x11u;
    firmware_memory[0xfaddul] = 0x22u;
    firmware_memory[0xfadeul] = 0x33u;
    firmware_memory[0xfadful] = 0x44u;
    AdjustEncodedMediaCalibrationOffsetForCurrentWriteSpeed();
    assert(firmware_memory[0xfadcul] == 0x11u && firmware_memory[0xfaddul] == 0x22u && firmware_memory[0xfadeul] == 0x33u && firmware_memory[0xfadful] == 0x44u);
}

