    firmware_memory[0x0ff3u] = 3u;
    firmware_memory[0x0e47u] = 16u;
    state6_calibration_retry_flag_result = 1u;
    assert(EvaluateMediaState6CalibrationResultAndRetry() == 1u);
    assert(state6_calibration_retry_flag_count == 1u && state6_calibration_retry_initialize_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0ff2u] = 2u;
    firmware_memory[0x0ff3u] = 2u;
    firmware_memory[0x1304u] = 0x20u;
    set_memory_big_endian_u16(0xfad7u, 0xa501u);
    assert(EvaluateMediaState6CalibrationResultAndRetry() == 0u);
    assert(get_memory_big_endian_u16(0xfad7u) == 0xa509u && state6_calibration_retry_initialize_count == 1u);

    clear_memory(0u);
    firmware_memory[0x0ff2u] = 2u;
    firmware_memory[0x0ff3u] = 3u;
    firmware_memory[0x0ff1u] = 4u;
    assert(EvaluateMediaState6CalibrationResultAndRetry() == 0u);
    assert(firmware_memory[0x0fafu] == 6u && firmware_memory[0x0ff1u] == 5u && state6_calibration_offset_adjust_count == 1u && state6_calibration_retry_initialize_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0ff2u] = 2u;
    firmware_memory[0x0ff3u] = 3u;
    firmware_memory[0x0ff1u] = 5u;
    assert(EvaluateMediaState6CalibrationResultAndRetry() == 0u);
    assert(state6_calibration_offset_adjust_count == 0u && state6_calibration_retry_initialize_count == 1u);

    clear_memory(0u);
