    assert(send_opc_event_count == sizeof(threshold_events) && memcmp(send_opc_events, threshold_events, sizeof(threshold_events)) == 0 && send_opc_sense_key == 3u && send_opc_sense_code == 0x7302u);

    clear_memory(0u);
    firmware_memory[0x0b0bu] = 1u;
    firmware_memory[0x0b12u] = 8u;
    firmware_memory[0xe74eu] = 1u;
    firmware_memory[0x0feeu] = 96u;
    HandleSendOpcInformationCommand();
