    clear_memory(0u);
    firmware_memory[0x0b0bu] = 1u;
    firmware_memory[0x0b12u] = 8u;
    firmware_memory[0xe74eu] = 1u;
    firmware_memory[0x0feeu] = 95u;
    firmware_memory[0x0c84u] = 0xa1u;
    send_opc_run_result = 0u;
    HandleSendOpcInformationCommand();
    assert(send_opc_event_count == sizeof(opc_failure_events) && memcmp(send_opc_events, opc_failure_events, sizeof(opc_failure_events)) == 0 && send_opc_run_seen_flags == 0xa9u
           && firmware_memory[0x0c84u] == 0xa1u && firmware_memory[0xe74eu] == 0u);

    clear_memory(0u);
