static void test_handle_get_configuration_command(void)
{
    static const u8 invalid_events[] = { 1u, 2u };
    static const u8 success_events[] = { 1u, 3u, 4u, 5u };
    static const u8 no_sense_events[] = { 1u, 3u, 4u, 5u, 6u };
    static const u8 media_states[] = { 0u, 1u, 2u, 3u };
    static const u8 expected_profiles[] = { 8u, 9u, 10u, 8u };
    unsigned index;

    clear_memory(0u);
    get_configuration_validate_result = 0u;
    HandleGetConfigurationCommand();
    assert(get_configuration_mask == 0xff8ea2ul && get_configuration_event_count == sizeof(invalid_events) && memcmp(get_configuration_events, invalid_events, sizeof(invalid_events)) == 0
           && read_count == 0u && write_count == 0u);

    for(index = 0u; index < sizeof(media_states); ++index)
    {
        clear_memory(0u);
        firmware_memory[0x0b0bu] = 0xfeu;
        firmware_memory[0x0b0cu] = 0x12u;
        firmware_memory[0x0b0du] = 0x34u;
        firmware_memory[0x0b11u] = 0u;
        firmware_memory[0x0b12u] = 12u;
        firmware_memory[0x1008u] = media_states[index];
        set_memory_big_endian_u32(0x155au, 0x01234567ul);
        get_configuration_builder_result = 16u;

        HandleGetConfigurationCommand();

        assert(get_configuration_event_count == sizeof(success_events) && memcmp(get_configuration_events, success_events, sizeof(success_events)) == 0 && get_configuration_request_type == 2u
               && get_configuration_starting_feature == 0x1234u && get_configuration_initial_length == 8u && get_configuration_stage_source == 0x000b2aul
               && get_configuration_stage_offset == 0x01234567ul && get_configuration_stage_count == 16ul && get_configuration_transfer_length == 12ul && get_memory_big_endian_u32(0x0b2au) == 12ul
               && firmware_memory[0x0b2eu] == 0u && firmware_memory[0x0b2fu] == 0u && firmware_memory[0x0b30u] == 0u && firmware_memory[0x0b31u] == expected_profiles[index]);
        assert(read_count == 12u && write_count == 8u && read_trace[0] == 0x0b11ul && read_trace[1] == 0x0b12ul && read_trace[2] == 0x0faeul && read_trace[3] == 0x1008ul && read_trace[4] == 0xdd79ul
               && read_trace[5] == 0x0b0bul && read_trace[6] == 0x0b0cul && read_trace[7] == 0x0b0dul && write_trace[0] == 0x0b2eul && write_trace[1] == 0x0b2ful && write_trace[2] == 0x0b30ul
               && write_trace[3] == 0x0b31ul);
    }

    clear_memory(0u);
    firmware_memory[0x0b0bu] = 3u;
    firmware_memory[0x0b0cu] = 0xabu;
    firmware_memory[0x0b0du] = 0xcdu;
    firmware_memory[0x0b11u] = 0u;
    firmware_memory[0x0b12u] = 32u;
    firmware_memory[0x1008u] = 2u;
    firmware_memory[0xdd79u] = 1u;
    firmware_memory[0x0c88u] = 2u;
    set_memory_big_endian_u32(0x155au, 0x89abcdeful);
    get_configuration_builder_result = 2u;
    get_configuration_data_in_result = 5u;
    HandleGetConfigurationCommand();
    assert(get_configuration_event_count == sizeof(no_sense_events) && memcmp(get_configuration_events, no_sense_events, sizeof(no_sense_events)) == 0 && firmware_memory[0x0b31u] == 8u
           && get_memory_big_endian_u32(0x0b2au) == 0x0000fffeul && get_configuration_stage_offset == 0x89abcdeful && get_configuration_stage_count == 2ul && get_configuration_transfer_length == 2ul
           && write_count == 9u && write_trace[3] == 0x0b31ul && write_values[3] == 10u && write_trace[4] == 0x0b31ul && write_values[4] == 8u);

    clear_memory(0u);
    firmware_memory[0x0faeu] = 1u;
    firmware_memory[0x1008u] = 2u;
    firmware_memory[0xdd79u] = 1u;
    firmware_memory[0x0c88u] = 2u;
    HandleGetConfigurationCommand();
    assert(firmware_memory[0x0b31u] == 0u && read_count == 10u && read_trace[2] == 0x0faeul && read_trace[3] == 0x0b0bul);
}

static void test_acquire_supplemental_atip_capacity_state(void)
{
    static const u8 early_success_events[] = { 1u, 1u, 2u, 3u, 4u, 5u, 6u };
    static const u8 packet_failure_events[] = { 1u, 2u, 3u, 4u, 3u, 5u, 6u, 4u, 5u, 6u, 8u };
    static const u8 capacity_events[] = { 1u, 2u, 3u, 4u, 5u, 6u, 7u };
    unsigned index;

    clear_memory(0u);
    set_memory_big_endian_u32(0x114fu, 0x12345678ul);
    supplemental_atip_acquire_result_count = 10u;
    supplemental_atip_decrement_on_acquire = 1u;
    assert(AcquireSupplementalAtipCapacityState() == 0u);
    assert(supplemental_atip_acquire_call_count == 10u && supplemental_atip_event_count == 11u && supplemental_atip_events[10] == 8u && get_memory_big_endian_u32(0x0e3bu) == 0x12344949ul
           && firmware_memory[0x1203u] == 0u && firmware_memory[0x0ed6u] == 0u);
    for(index = 0u; index != 10u; ++index)
        assert(supplemental_atip_events[index] == 1u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x114fu, 0x1000ul);
    supplemental_atip_acquire_results[1] = 1u;
    supplemental_atip_acquire_result_count = 2u;
    supplemental_atip_decrement_on_acquire = 1u;
    supplemental_atip_parse_results[0] = 0xfeu;
    supplemental_atip_parse_result_count = 1u;
    supplemental_atip_validate_result_count = 1u;
    supplemental_atip_decrement_on_yield = 3u;
    firmware_memory[0xfb5bu] = 0xe0u;
    firmware_memory[0x1301u] = 0xa0u;
    assert(AcquireSupplementalAtipCapacityState() == 1u);
    assert(supplemental_atip_event_count == sizeof(early_success_events) && memcmp(supplemental_atip_events, early_success_events, sizeof(early_success_events)) == 0
           && supplemental_atip_parse_call_count == 1u && supplemental_atip_validate_call_count == 1u && supplemental_atip_yield_count == 1u && firmware_memory[0x1301u] == 0xa2u
           && firmware_memory[0x1802bu] == 0u);

    clear_memory(0u);
    supplemental_atip_acquire_results[0] = 1u;
    supplemental_atip_acquire_result_count = 1u;
    supplemental_atip_parse_results[0] = 0u;
    supplemental_atip_parse_results[1] = 0xfeu;
    supplemental_atip_parse_result_count = 2u;
    supplemental_atip_validate_result_count = 2u;
    supplemental_atip_decrement_on_yield = 5u;
    assert(AcquireSupplementalAtipCapacityState() == 0u);
    assert(supplemental_atip_event_count == sizeof(packet_failure_events) && memcmp(supplemental_atip_events, packet_failure_events, sizeof(packet_failure_events)) == 0
           && supplemental_atip_parse_call_count == 2u && supplemental_atip_validate_call_count == 2u && supplemental_atip_yield_count == 2u);

    clear_memory(0u);
    supplemental_atip_acquire_results[0] = 1u;
    supplemental_atip_acquire_result_count = 1u;
    supplemental_atip_parse_results[0] = 0xfeu;
    supplemental_atip_parse_result_count = 1u;
    supplemental_atip_validate_results[0] = 1u;
    supplemental_atip_validate_result_count = 1u;
    firmware_memory[0x1306u] = 2u;
    firmware_memory[0xfb84u] = 0xffu;
    set_memory_big_endian_u32(0xfb8cu, 0x7ffff000ul);
    assert(AcquireSupplementalAtipCapacityState() == 1u);
    assert(supplemental_atip_event_count == sizeof(capacity_events) && memcmp(supplemental_atip_events, capacity_events, sizeof(capacity_events)) == 0 && supplemental_atip_multiply_count == 1u
           && supplemental_atip_multiply_left == 0x1194ul && supplemental_atip_multiply_right == 512ul && get_memory_big_endian_u32(0xfb90u) == 0x00232800ul
           && get_memory_big_endian_u32(0x1153u) == 0x8022fdA2ul);

    clear_memory(0u);
    supplemental_atip_acquire_results[0] = 1u;
    supplemental_atip_acquire_result_count = 1u;
    supplemental_atip_parse_results[0] = 0xfeu;
    supplemental_atip_parse_result_count = 1u;
    supplemental_atip_validate_results[0] = 1u;
    supplemental_atip_validate_result_count = 1u;
    firmware_memory[0x1306u] = 0xfdu;
    set_memory_big_endian_u32(0xfb90u, 0xaaaaaaaaul);
    set_memory_big_endian_u32(0x1153u, 0xbbbbbbbbul);
    assert(AcquireSupplementalAtipCapacityState() == 1u && supplemental_atip_multiply_count == 0u && get_memory_big_endian_u32(0xfb90u) == 0xaaaaaaaaul
           && get_memory_big_endian_u32(0x1153u) == 0xbbbbbbbbul);
}

static void test_run_opc_for_current_write_speed(void)
{
    static const u8 direct_failure_events[] = { 1u, 2u };
    static const u8 acquisition_failure_events[] = { 1u, 3u, 4u };
    static const u8 success_events[] = { 1u, 3u, 5u, 3u, 5u, 3u, 6u, 7u };
    static const u8 result_failure_events[] = { 1u, 3u, 5u, 3u, 6u };

    clear_memory(0u);
    firmware_memory[0x0faeu] = 3u;
    firmware_memory[0xf84454u + 3u] = 5u;
    firmware_memory[0xf84468u + 6u] = 0x12u;
    firmware_memory[0xf84469u + 6u] = 0x34u;
    assert(RunOpcForCurrentWriteSpeed() == 0u && opc_worker_event_count == sizeof(direct_failure_events) && memcmp(opc_worker_events, direct_failure_events, sizeof(direct_failure_events)) == 0
           && opc_worker_direct_sense_key == 5u && opc_worker_direct_sense_code == 0x1234u && bit_0580 == 1u && bit_0581 == 0u);

    clear_memory(0u);
    firmware_memory[0x0e41u] = 7u;
    firmware_memory[0x158eu] = 0xffu;
    assert(RunOpcForCurrentWriteSpeed() == 0u && opc_worker_event_count == sizeof(acquisition_failure_events)
           && memcmp(opc_worker_events, acquisition_failure_events, sizeof(acquisition_failure_events)) == 0 && opc_worker_status_sense == 7u && firmware_memory[0x0e3fu] == 1u
           && firmware_memory[0x0e40u] == 0u && firmware_memory[0x15b2u] == 1u && firmware_memory[0x158eu] == 0xf7u && firmware_memory[0x0fafu] == 6u);

    clear_memory(0u);
    firmware_memory[0xfaabu] = 0x11u;
    firmware_memory[0x0e47u] = 24u;
    opc_worker_result_change_after = 2u;
    opc_worker_changed_result = 0x12u;
    assert(RunOpcForCurrentWriteSpeed() == 1u && opc_worker_event_count == sizeof(success_events) && memcmp(opc_worker_events, success_events, sizeof(success_events)) == 0
           && opc_worker_service_count == 2u && firmware_memory[0xe74eu] == 1u && opc_worker_speed_class_argument == 24u);

    clear_memory(0u);
    firmware_memory[0xfaabu] = 3u;
    firmware_memory[0x0e47u] = 8u;
    firmware_memory[0x1302u] = 0xa0u;
    firmware_memory[0xf84416u + 6u] = 0xabu;
    firmware_memory[0xf84417u + 6u] = 0xcdu;
    assert(RunOpcForCurrentWriteSpeed() == 0u && opc_worker_event_count == sizeof(result_failure_events) && memcmp(opc_worker_events, result_failure_events, sizeof(result_failure_events)) == 0
           && firmware_memory[0xfaeau] == 8u && firmware_memory[0x1302u] == 0xa1u && firmware_memory[0x0c3au] == 0xabu && firmware_memory[0x0c3bu] == 0xcdu);

    clear_memory(0u);
    firmware_memory[0xfaabu] = 4u;
    firmware_memory[0x0e47u] = 32u;
    firmware_memory[0xf84416u + 8u] = 0x55u;
    firmware_memory[0xf84417u + 8u] = 0xaau;
    assert(RunOpcForCurrentWriteSpeed() == 0u && firmware_memory[0xfaeau] == 0x10u && firmware_memory[0x0c3au] == 0x55u && firmware_memory[0x0c3bu] == 0xaau);
}

static void test_run_startup_debounced_input_sequence(void)
{
    clear_memory(0u);
    startup_bit7_results[0] = 1u;
    startup_bit7_count = 1u;
    firmware_memory[0x1301u] = 0x81u;
    RunStartupDebouncedInputSequence();
    assert(firmware_memory[0x1301u] == 0xa1u && startup_bit7_index == 1u && startup_yield_count == 0u && startup_clear_count == 0u);

    clear_memory(0u);
    startup_bit7_results[0] = 0u;
    startup_bit7_results[1] = 1u;
    startup_bit7_count = 2u;
    firmware_memory[0x1301u] = 0x02u;
    RunStartupDebouncedInputSequence();
    assert(firmware_memory[0x1301u] == 0x22u && startup_yield_count == 10u && firmware_memory[0x1214u] == 0u && startup_clear_count == 0u);

    clear_memory(0u);
    startup_bit7_count = 2u;
    startup_bit5_count = 1u;
    RunStartupDebouncedInputSequence();
    assert(startup_yield_count == 10u && startup_clear_count == 1u && startup_apply_count == 1u && startup_p3_count == 1u && startup_p3_arguments[0] == 1u && startup_bit5_index == 1u);

    clear_memory(0u);
    startup_bit7_count = 2u;
    startup_bit5_results[0] = 1u;
    startup_bit5_count = 1u;
    startup_take_flag_results[0] = 1u;
    startup_take_flag_count = 1u;
    startup_bit6_results[0] = 1u;
    startup_bit6_results[1] = 1u;
    startup_bit6_results[2] = 0u;
    startup_bit6_count = 3u;
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x130au] = 0x0eu;
    set_memory_big_endian_u32(0xfae2u, 0xfffffffful);
    RunStartupDebouncedInputSequence();
    assert(startup_yield_count == 43u && startup_p3_count == 2u && startup_p3_arguments[0] == 1u && startup_p3_arguments[1] == 0u && startup_take_flag_index == 1u && startup_bit6_index == 3u
           && firmware_memory[0x120au] == 0u && get_memory_big_endian_u32(0xfae2u) == 0u);

    clear_memory(0u);
    startup_bit7_count = 2u;
    startup_bit5_results[0] = 1u;
    startup_bit5_count = 1u;
    startup_take_flag_count = 1u;
    startup_bit6_count = 1u;
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x130au] = 0x0bu;
    set_memory_big_endian_u32(0xfae2u, 200000ul);
    RunStartupDebouncedInputSequence();
    assert(startup_yield_count == 16u && get_memory_big_endian_u32(0xfae2u) == 200001ul);

    clear_memory(0u);
    startup_bit7_count = 2u;
    startup_bit5_results[0] = 1u;
    startup_bit5_results[1] = 1u;
    startup_bit5_results[2] = 0u;
    startup_bit5_count = 3u;
    startup_take_flag_count = 2u;
    RunStartupDebouncedInputSequence();
    assert(startup_yield_count == 12u && startup_p3_count == 3u && startup_p3_arguments[0] == 1u && startup_p3_arguments[1] == 0u && startup_p3_arguments[2] == 0u && startup_take_flag_index == 2u);
}

static void test_probe_controller_signal_and_initialize_drive_control(void)
{
    unsigned index;

    clear_memory(0u);
    controller_probe_samples[0] = 0x5000u;
    controller_probe_sample_count = 1u;
    ProbeControllerSignalAndInitializeDriveControl();
    assert(controller_probe_p1_count == 1u && controller_probe_wait_count == 1u && controller_probe_wait_duration == 8000u && controller_probe_wait_yield == 0u && controller_probe_sample_index == 1u
           && controller_probe_resolve_count == 0u);
    assert(controller_probe_write_count == 4u && controller_probe_write_ports[0] == 0x018006ul && controller_probe_write_values[0] == 0x80u && controller_probe_write_ports[1] == 0x0180a8ul
           && controller_probe_write_values[1] == 0u && controller_probe_write_ports[2] == 0x0180ccul && controller_probe_write_values[2] == 0x12u && controller_probe_write_ports[3] == 0x0180aaul
           && controller_probe_write_values[3] == 2u);
    assert(controller_probe_read_count == 2u && controller_probe_read_ports[0] == 0x0180a9ul && controller_probe_read_ports[1] == 0x0180a8ul && firmware_memory[0x1300u] == 0u
           && firmware_memory[0xfbecu] == 0u);

    clear_memory(0u);
    for(index = 0u; index < 50u; ++index)
        controller_probe_samples[index] = 0x1000u;
    controller_probe_sample_count = 50u;
    firmware_memory[0x180ccu] = 0x10u;
    ProbeControllerSignalAndInitializeDriveControl();
    assert(controller_probe_sample_index == 50u && controller_probe_write_count == 53u && controller_probe_read_count == 100u && firmware_memory[0x1221u] == 0u && controller_probe_p1_count == 1u
           && controller_probe_resolve_count == 0u && get_memory_big_endian_u32(0x0cf5u) == 0ul);
    for(index = 3u; index < controller_probe_write_count; ++index)
        assert(controller_probe_write_ports[index] == 0x0180aaul && controller_probe_write_values[index] == 2u);

    clear_memory(0u);
    for(index = 0u; index < 50u; ++index)
        controller_probe_samples[index] = 0x1001u;
    controller_probe_sample_count = 50u;
    firmware_memory[0x180ccu] = 0x10u;
    ProbeControllerSignalAndInitializeDriveControl();
    assert(controller_probe_sample_index == 50u && controller_probe_p1_count == 2u && controller_probe_resolve_count == 1u && get_memory_big_endian_u32(0x0cf5u) == 0x00014cccul
           && get_memory_big_endian_u16(0x0cf9u) == 0x0640u && firmware_memory[0x1300u] == 1u && firmware_memory[0xfbecu] == 1u);
    assert(controller_probe_event_count == 157u && controller_probe_events[0] == 1u && controller_probe_events[1] == 2u && controller_probe_events[2] == 3u && controller_probe_events[3] == 3u
           && controller_probe_events[4] == 4u && controller_probe_events[154] == 6u && controller_probe_events[155] == 1u && controller_probe_events[156] == 7u);

    clear_memory(0u);
    controller_probe_samples[0] = 0x4fffu;
    controller_probe_sample_count = 1u;
    ProbeControllerSignalAndInitializeDriveControl();
    assert(controller_probe_sample_index == 50u && controller_probe_resolve_count == 1u && get_memory_big_endian_u32(0x0cf5u) == 0x00014cccul);
}

