static void test_initialize_post_toc_controller_state(void)
{
    static const u8 state0_events[] = { 1u, 2u, 3u, 4u, 5u, 6u, 7u, 8u, 11u, 12u, 13u, 13u, 14u };
    static const u8 state1_events[] = { 1u, 2u, 3u, 4u, 5u, 6u, 7u, 8u, 10u, 11u, 12u, 13u, 13u, 14u };
    static const u8 state2_events[] = { 1u, 2u, 3u, 4u, 5u, 6u, 7u, 8u, 9u, 10u, 11u, 12u, 13u, 13u, 14u };

    clear_memory(0u);
    firmware_memory[0x1304u] = 0xa4u;
    firmware_memory[0x1305u] = 0xffu;
    set_memory_big_endian_u32(0x0cf5u, 0x12345678ul);
    set_memory_big_endian_u16(0x0cf9u, 0x9abcu);
    set_memory_big_endian_u16(0xfab8u, 0xdef0u);
    set_memory_big_endian_u16(0xfbdeu, 0x1111u);
    set_memory_big_endian_u16(0xfbe0u, 0x2222u);
    post_toc_log_results[0] = -2l;
    post_toc_log_results[1] = 0x12345678l;
    assert(InitializePostTocControllerState() == 2u);
    assert(firmware_memory[0x0e43u] == 1u && firmware_memory[0x0e4fu] == 1u && firmware_memory[0x0e44u] == 1u && firmware_memory[0x0e3fu] == 0u && firmware_memory[0x1304u] == 0xa4u
           && firmware_memory[0x1305u] == 0xe7u && firmware_memory[0x1006u] == 0u);
    assert(get_memory_big_endian_u32(0xfbe6u) == 0x12345678ul && get_memory_big_endian_u16(0xfbeau) == 0x9abcu && get_memory_big_endian_u16(0xf990u) == 0xdef0u
           && get_memory_big_endian_u16(0xf984u) == 0xfffeu && get_memory_big_endian_u16(0xf988u) == 0x5678u);
    assert(post_toc_log_count == 2u && post_toc_log_arguments[0] == 0x1111u && post_toc_log_arguments[1] == 0x2222u && post_toc_event_count == sizeof(state0_events)
           && memcmp(post_toc_events, state0_events, sizeof(state0_events)) == 0);

    clear_memory(0u);
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x1305u] = 0xffu;
    post_toc_initialization_result = 2u;
    assert(InitializePostTocControllerState() == 0u);
    assert(firmware_memory[0x1305u] == 0xe7u && post_toc_event_count == sizeof(state1_events) && memcmp(post_toc_events, state1_events, sizeof(state1_events)) == 0);

    clear_memory(0u);
    firmware_memory[0x1008u] = 2u;
    firmware_memory[0x1305u] = 0xffu;
    firmware_memory[0xfc0fu] = 0x5au;
    post_toc_initialization_result = 0xa5u;
    assert(InitializePostTocControllerState() == 0u);
    assert(
        firmware_memory[0xfc0fu] == 0x5au && firmware_memory[0x1305u] == 0xefu && post_toc_event_count == sizeof(state2_events) && memcmp(post_toc_events, state2_events, sizeof(state2_events)) == 0);
}

static void test_reduce_read_speed_for_acquisition_recovery(void)
{
    static const u8 speeds[5] = { 52u, 40u, 32u, 24u, 8u };
    static const u8 reduced[5] = { 40u, 32u, 24u, 8u, 4u };
    u8 index;

    clear_memory(0u);
    firmware_memory[0x000c89u] = 1u;
    firmware_memory[0x000e46u] = 52u;
    assert(ReduceReadSpeedForAcquisitionRecovery(0u) == 0u && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x000e46u] = 4u;
    assert(ReduceReadSpeedForAcquisitionRecovery(0u) == 0u && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x000e46u] = 52u;
    firmware_memory[0x001037u] = 6u;
    assert(ReduceReadSpeedForAcquisitionRecovery(0u) == 0u && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x000e46u] = 52u;
    firmware_memory[0x001006u] = 2u;
    assert(ReduceReadSpeedForAcquisitionRecovery(0u) == 0u && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x000e46u] = 52u;
    firmware_memory[0x001006u] = 1u;
    firmware_memory[0x000e41u] = 6u;
    assert(ReduceReadSpeedForAcquisitionRecovery(0u) == 0u && write_count == 0u);

    for(index = 0u; index < 5u; ++index)
    {
        clear_memory(0u);
        firmware_memory[0x000e46u] = speeds[index];
        firmware_memory[0x001037u] = 1u;
        firmware_memory[0x001305u] = 0x80u;
        assert(ReduceReadSpeedForAcquisitionRecovery(0u) == 1u);
        assert(firmware_memory[0x000e46u] == reduced[index] && firmware_memory[0x000e49u] == reduced[index] && firmware_memory[0x000f45u] == reduced[index] && firmware_memory[0x001037u] == 2u
               && firmware_memory[0x001305u] == 0x84u);
    }

    clear_memory(0u);
    firmware_memory[0x000e46u] = 52u;
    firmware_memory[0x001037u] = 1u;
    firmware_memory[0x00fc3eu] = 5u;
    assert(ReduceReadSpeedForAcquisitionRecovery(1u) == 1u);
    assert(firmware_memory[0x000e46u] == 4u && firmware_memory[0x000e4bu] == 4u && firmware_memory[0x000e49u] == 4u && firmware_memory[0x000f45u] == 4u && firmware_memory[0x001037u] == 5u);

    clear_memory(0u);
    firmware_memory[0x000e46u] = 52u;
    firmware_memory[0x001006u] = 1u;
    firmware_memory[0x000e41u] = 7u;
    firmware_memory[0x000fafu] = 4u;
    assert(ReduceReadSpeedForAcquisitionRecovery(2u) == 1u);
    assert(firmware_memory[0x000e46u] == 40u && firmware_memory[0x000e4bu] == 0u && firmware_memory[0x001037u] == 5u);
}

static void prepare_complete_pma_q_record_state(void)
{
    firmware_memory[0x001149u] = 3u;
    firmware_memory[0x0012bfu] = 0u;
    firmware_memory[0x001147u] = 1u;
    firmware_memory[0x2bb03du + 10u] = 1u;
    firmware_memory[0x00f2b6u + 12u] = 2u;
    firmware_memory[0x2bb03du + 30u] = 1u;
    firmware_memory[0x00114au] = 1u;
    firmware_memory[0x00114bu] = 1u;
    firmware_memory[0x00114cu] = 1u;
    firmware_memory[0x00114du] = 1u;
    firmware_memory[0x2bb42fu] = 1u;
    firmware_memory[0x2bb50bu] = 1u;
    firmware_memory[0x2bb5f1u] = 1u;
    firmware_memory[0x2bb78bu] = 1u;
}

static void test_is_pma_q_record_state_complete(void)
{
    static const fw_addr_t counted_records[4] = { 0x2bb42ful, 0x2bb50bul, 0x2bb5f1ul, 0x2bb78bul };
    u8 table;

    clear_memory(0u);
    firmware_memory[0x001132u] = 0x80u;
    set_memory_big_endian_u32(0x114fu, 10000ul);
    set_memory_big_endian_u32(0x1143u, 9009ul);
    assert(IsPmaQRecordStateComplete() == 0u && firmware_memory[0x001132u] == 0x80u);

    clear_memory(0u);
    firmware_memory[0x001132u] = 1u;
    set_memory_big_endian_u32(0x114fu, 10000ul);
    set_memory_big_endian_u32(0x1143u, 9008ul);
    assert(IsPmaQRecordStateComplete() == 1u && firmware_memory[0x001132u] == 0x81u);

    clear_memory(0u);
    firmware_memory[0x001132u] = 0x80u;
    prepare_complete_pma_q_record_state();
    assert(IsPmaQRecordStateComplete() == 1u && firmware_memory[0x001132u] == 0u);

    clear_memory(0u);
    firmware_memory[0x001132u] = 0xffu;
    prepare_complete_pma_q_record_state();
    firmware_memory[0x00f2b6u + 12u] = 0u;
    assert(IsPmaQRecordStateComplete() == 0u && firmware_memory[0x001132u] == 0x7fu);

    clear_memory(0u);
    firmware_memory[0x001132u] = 0x80u;
    prepare_complete_pma_q_record_state();
    firmware_memory[0x00f2b6u + 12u] = 0xaau;
    assert(IsPmaQRecordStateComplete() == 0u && firmware_memory[0x001132u] == 0u);

    for(table = 0u; table < 4u; ++table)
    {
        clear_memory(0u);
        firmware_memory[0x001132u] = 0x80u;
        prepare_complete_pma_q_record_state();
        firmware_memory[counted_records[table]] = 0u;
        assert(IsPmaQRecordStateComplete() == 0u && firmware_memory[0x001132u] == 0x80u);
    }
}

static void test_handle_scsi_opcode_f1(void)
{
    clear_memory(0u);
    set_memory_big_endian_u32(0x0b0cu, 0x12340020ul);
    set_memory_big_endian_u16(0x0b12u, 0x0090u);
    set_memory_big_endian_u32(0x155au, 0x200ul);
    firmware_memory[0xffc020u] = 0x11u;
    firmware_memory[0xffc05fu] = 0x22u;
    firmware_memory[0xffa060u] = 0x33u;
    firmware_memory[0xffa09fu] = 0x44u;
    firmware_memory[0x0b1au] = 5u;
    controller_data_in_transfer_phase = 12u;
    controller_data_in_transfer_call_count = 0u;
    HandleScsiOpcodeF1();
    assert(firmware_memory[0x0b2au] == 0x11u && firmware_memory[0x0b69u] == 0x22u && firmware_memory[0x0b6au] == 0x33u && firmware_memory[0x0ba9u] == 0x44u);
    assert(controller_data_in_transfer_call_count == 1u && controller_data_in_transfer_length == 0x80ul && firmware_memory[0x0b1au] == 5u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x0b0cu, 0xffff00a1ul);
    set_memory_big_endian_u16(0x0b12u, 2u);
    set_memory_big_endian_u32(0x155au, 0x300ul);
    firmware_memory[0xffa0a1u] = 0x5au;
    firmware_memory[0xffa0a2u] = 0xa5u;
    firmware_memory[0x0b1au] = 5u;
    controller_data_in_transfer_phase = 13u;
    controller_data_in_transfer_call_count = 0u;
    HandleScsiOpcodeF1();
    assert(controller_data_in_transfer_length == 2ul && firmware_memory[0x0b2au] == 0x5au && firmware_memory[0x0b2bu] == 0xa5u && firmware_memory[0x0b1au] == 0u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x0b0cu, 0xabcdef20ul);
    controller_data_in_transfer_call_count = 0u;
    HandleScsiOpcodeF1();
    assert(controller_data_in_transfer_call_count == 0u && firmware_memory[0x0b1au] == 0u);
}

