static void test_build_vendor_f2_controller_measurement_response(void)
{
    static const u16 expected_lengths[8] = { 0u, 0x0134u, 0x0169u, 0x00c6u, 0x007cu, 0u, 0x0169u, 0u };
    static const u8 expected_event_counts[8] = { 0u, 1u, 1u, 2u, 2u, 0u, 1u, 0u };
    static const u8 expected_events[8][2] = {
        { 0u,  0u  },
        { '1', 0u  },
        { '2', 0u  },
        { 'C', 'S' },
        { 'C', 'A' },
        { 0u,  0u  },
        { '2', 0u  },
        { 0u,  0u  }
    };
    static const fw_addr_t expected_reads[13] = { 0xf9a0u, 0xf9a1u, 0xf9a2u, 0xf9a3u, 0x1008u, 0xf05fu, 0xef74u, 0x0e47u, 0xef73u, 0xef72u, 0xef72u, 0xf076u, 0xef73u };
    unsigned mode;

    for(mode = 0u; mode != 8u; ++mode)
    {
        u8 ef72 = (u8)((mode & 3u) << 4);
        u8 expected_flags = (u8)(0x05u | ((ef72 & 0x20u) << 1) | ((ef72 & 0x10u) << 3));

        clear_memory(0u);
        memset(firmware_memory + 0x0b2au, 0xa5u, 0x100u);
        set_memory_big_endian_u16(0xf9a0u, 0x1234u);
        set_memory_big_endian_u16(0xf9a2u, 0x5678u);
        firmware_memory[0x1008u] = 0x09u;
        firmware_memory[0xf05fu] = 0x0au;
        firmware_memory[0xef74u] = 0x0bu;
        firmware_memory[0x0e47u] = 0x0cu;
        firmware_memory[0xef73u] = (u8)(0xf8u | mode);
        firmware_memory[0xef72u] = ef72;
        firmware_memory[0xf076u] = 0x05u;

        BuildVendorF2ControllerMeasurementResponse();

        assert(get_memory_big_endian_u16(0x0b2au) == 0x1234u && get_memory_big_endian_u16(0x0b2cu) == 0x5678u);
        assert(firmware_memory[0x0b2eu] == 0x09u && firmware_memory[0x0b2fu] == 0x0au && firmware_memory[0x0b30u] == 0x0bu && firmware_memory[0x0b31u] == 0x0fu && firmware_memory[0x0b32u] == 0x0cu
               && firmware_memory[0x0b33u] == mode && firmware_memory[0x0b34u] == expected_flags);
        assert(get_memory_big_endian_u16(0x0b36u) == expected_lengths[mode]);
        assert(firmware_memory[0x0c28u] == 0u && firmware_memory[0x0c29u] == 0xa5u);
        assert(vendor_f2_response_event_count == expected_event_counts[mode]);
        assert(memcmp(vendor_f2_response_events, expected_events[mode], expected_event_counts[mode]) == 0);
        assert(read_count == 13u);
        assert(memcmp(read_trace, expected_reads, sizeof(expected_reads)) == 0);
        assert(write_count == (expected_lengths[mode] != 0u ? 268u : 266u));
    }
}

static void test_build_vendor_f2_mode2_or6_measurement_response(void)
{
    static const fw_addr_t first_sources[4] = { 0x00f09dul, 0x00f0bbul, 0x00f0d9ul, 0x00f0f7ul };
    static const fw_addr_t second_sources[4] = { 0x00ef89ul, 0x00efa7ul, 0x00efc5ul, 0x00efe3ul };
    static const fw_addr_t fifth_sources[2] = { 0x00f03ful, 0x00f01ful };
    static const u8 modes[2] = { 2u, 6u };
    static u8 expected_first[0xd4];
    static u8 expected_second[0xa1];
    unsigned vector;
    unsigned block;
    unsigned index;

    for(vector = 0u; vector < 2u; ++vector)
    {
        clear_memory(0xa5u);
        set_memory_big_endian_u32_far(0x00155aul, 0x00020000ul);
        firmware_memory[0x00ef73u] = modes[vector];
        set_memory_big_endian_u16(0xef85u, 0x1234u);
        set_memory_big_endian_u16(0xef87u, 0x5678u);
        set_memory_big_endian_u16(0xf062u, 0x9abcu);
        set_memory_big_endian_u16(0xf064u, 0xdef0u);

        for(index = 0u; index < 0xd4u; ++index)
        {
            u8 value = (u8)(index * 13u + 7u);

            firmware_memory[0x000b2au + index] = value;
            expected_first[index] = value;
        }
        for(block = 0u; block < 4u; ++block)
        {
            for(index = 0u; index < 0x1eu; ++index)
            {
                u8 first_value = (u8)(0x10u + block * 0x20u + index);
                u8 second_value = (u8)(0x90u + block * 0x10u + index);

                firmware_memory[first_sources[block] + index] = first_value;
                firmware_memory[second_sources[block] + index] = second_value;
                expected_first[0x0eu + block * 0x1eu + index] = first_value;
            }
        }
        for(block = 0u; block < 2u; ++block)
            for(index = 0u; index < 0x1eu; ++index)
                firmware_memory[fifth_sources[block] + index] = (u8)(0xd0u + block * 0x10u + index);

        memcpy(expected_second, expected_first, sizeof(expected_second));
        for(block = 0u; block < 4u; ++block)
            for(index = 0u; index < 0x1eu; ++index)
                expected_second[block * 0x1eu + index] = firmware_memory[second_sources[block] + index];
        for(index = 0u; index < 0x1eu; ++index)
            expected_second[0x78u + index] = firmware_memory[fifth_sources[vector] + index];
        expected_second[0x96u] = 0x12u;
        expected_second[0x97u] = 0x34u;
        expected_second[0x98u] = 0x56u;
        expected_second[0x99u] = 0x78u;
        expected_second[0x9au] = 0x9au;
        expected_second[0x9bu] = 0xbcu;
        expected_second[0x9eu] = 0xdeu;
        expected_second[0x9fu] = 0xf0u;

        BuildVendorF2Mode2Or6MeasurementResponse();

        assert(vendor_f2_response_event_count == 1u && vendor_f2_response_events[0] == 'S');
        for(index = 0u; index < sizeof(expected_first); ++index)
            assert(firmware_memory[0x00120000ul + index] == expected_first[index]);
        for(index = 0u; index < sizeof(expected_second); ++index)
        {
            assert(firmware_memory[0x001200d4ul + index] == expected_second[index]);
            assert(firmware_memory[0x000b2aul + index] == expected_second[index]);
        }
        assert(firmware_memory[0x00120175ul] == 0xa5u);
        assert(firmware_memory[0x000bc6ul] == expected_first[0x9cu] && firmware_memory[0x000bc7ul] == expected_first[0x9du]);
    }
}

static void test_probe_controller_record_at_frame_and_map_status(void)
{
    clear_memory(0u);
    raw_payload_signature_result = 0x11u;
    assert(ProbeControllerRecordAtFrameAndMapStatus(-123l) == 0x11u);
    assert(raw_payload_signature_call_count == 1u);
    assert(get_memory_big_endian_u32(0x1598u) == (u32)-123l);
    assert(write_count == 4u && write_trace[0] == 0x1598ul && write_trace[3] == 0x159bul);
    assert(read_count == 1u && read_trace[0] == 0x0faeul);

    clear_memory(0u);
    raw_payload_signature_result = 0xfeu;
    firmware_memory[0x0faeu] = 0x80u;
    assert(ProbeControllerRecordAtFrameAndMapStatus(0x12345678l) == 5u);
    assert(raw_payload_signature_call_count == 1u);
    assert(get_memory_big_endian_u32(0x1598u) == 0x12345678ul);
    assert(read_count == 1u && read_trace[0] == 0x0faeul);
}

