static void test_probe_type2_tdi_record_near_track_start(void)
{
    unsigned index;

    clear_memory(0u);
    reset_type2_tdi_probe_observer();
    set_memory_big_endian_u32(0xdd3du, 1000ul);
    read_count = write_count = 0u;
    type2_tdi_probe_statuses[0] = 5u;
    assert(ProbeType2TdiRecordNearTrackStart(1u) == 0u);
    assert(type2_tdi_probe_call_count == 1u && type2_tdi_probe_arguments[0] == 786l);
    assert(read_count == 4u && write_count == 0u);
    for(index = 0u; index != 4u; ++index)
        assert(read_trace[index] == 0x00dd3dul + index);

    clear_memory(0u);
    reset_type2_tdi_probe_observer();
    set_memory_big_endian_u32(0xfb04u, (u32)-20l);
    set_memory_big_endian_u32(0xdd3du, 100ul);
    read_count = write_count = 0u;
    type2_tdi_probe_flags[0] = 0x49u;
    assert(ProbeType2TdiRecordNearTrackStart(2u) == 1u);
    assert(type2_tdi_probe_call_count == 1u && type2_tdi_probe_arguments[0] == 80l);
    assert(read_count == 11u && read_trace[0] == 0x00fb04ul && read_trace[3] == 0x00fb07ul && read_trace[4] == 0x00dd3dul && read_trace[7] == 0x00dd40ul && read_trace[8] == 0x2bb91cul
           && read_trace[9] == 0x2bb91cul && read_trace[10] == 0x2bb927ul);
    assert(write_count == 1u && write_trace[0] == 0x000c9ful && write_values[0] == 1u);

    clear_memory(0u);
    reset_type2_tdi_probe_observer();
    set_memory_big_endian_u32(0xdd3du, 500ul);
    read_count = write_count = 0u;
    type2_tdi_probe_statuses[0] = 0xfeu;
    type2_tdi_probe_statuses[1] = 0xffu;
    type2_tdi_probe_statuses[2] = 0x0fu;
    type2_tdi_probe_statuses[3] = 0xfeu;
    assert(ProbeType2TdiRecordNearTrackStart(1u) == 0u);
    assert(type2_tdi_probe_call_count == 4u && read_count == 16u && write_count == 0u);
    for(index = 0u; index != 4u; ++index)
        assert(type2_tdi_probe_arguments[index] == 286l);

    clear_memory(0u);
    reset_type2_tdi_probe_observer();
    set_memory_big_endian_u32(0xdd3du, (u32)-1000l);
    read_count = write_count = 0u;
    type2_tdi_probe_record_classes[0] = 0x10u;
    type2_tdi_probe_record_classes[1] = 0x01u;
    type2_tdi_probe_record_classes[2] = 0xf0u;
    type2_tdi_probe_record_classes[3] = 0u;
    type2_tdi_probe_flags[3] = 0x49u;
    assert(ProbeType2TdiRecordNearTrackStart(1u) == 1u);
    assert(type2_tdi_probe_call_count == 4u && read_count == 23u && write_count == 1u && write_trace[0] == 0x000c9ful && write_values[0] == 1u);
    for(index = 0u; index != 4u; ++index)
        assert(type2_tdi_probe_arguments[index] == -1214l);
}

