static void test_service_controller_command0e_measurement_capture(void)
{
    clear_memory(0u);
    ServiceControllerCommand0EMeasurementCapture();
    assert(read_count == 2u && read_trace[0] == 0x1098ul && read_trace[1] == 0x1098ul);
    assert(write_count == 0u && command0e_accumulator_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1098u] = 1u;
    firmware_memory[0x1006u] = 2u;
    ServiceControllerCommand0EMeasurementCapture();
    assert(read_count == 2u && read_trace[0] == 0x1098ul && read_trace[1] == 0x1006ul);
    assert(write_count == 0u && command0e_accumulator_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1098u] = 2u;
    firmware_memory[0x1006u] = 1u;
    ServiceControllerCommand0EMeasurementCapture();
    assert(read_count == 3u && read_trace[0] == 0x1098ul && read_trace[1] == 0x1098ul && read_trace[2] == 0x1006ul);
    assert(write_count == 0u && command0e_accumulator_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1098u] = 5u;
    set_memory_big_endian_u32(0x1099u, 10ul);
    set_memory_big_endian_u32(0x1235u, 9ul);
    ServiceControllerCommand0EMeasurementCapture();
    assert(read_count == 12u);
    assert(read_trace[0] == 0x1098ul && read_trace[1] == 0x1006ul && read_trace[2] == 0x1098ul && read_trace[3] == 0x1098ul);
    assert(read_trace[4] == 0x1099ul && read_trace[7] == 0x109cul && read_trace[8] == 0x1235ul && read_trace[11] == 0x1238ul);
    assert(write_count == 0u && command0e_accumulator_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1098u] = 5u;
    set_memory_big_endian_u32(0x1099u, 0xfffffffful);
    set_memory_big_endian_u32(0x1235u, 0xfffffffful);
    sfr_memory[0xa8u] = 0xd5u;
    sfr_memory[0xa9u] = 0x6au;
    bit_0547 = 1u;
    command0e_accumulator_mutate_sfrs = 1u;
    ServiceControllerCommand0EMeasurementCapture();
    assert(firmware_memory[0x1098u] == 0x0du);
    assert(write_count == 1u && write_trace[0] == 0x1098ul && write_values[0] == 0x0du);
    assert(command0e_accumulator_call_count == 1u);
    assert(command0e_accumulator_seen_bit_0547 == 0u && command0e_accumulator_seen_ie == 0xd5u && command0e_accumulator_seen_a9 == 0x6au);
    assert(sfr_memory[0xa8u] == 0xd5u && sfr_memory[0xa9u] == 0x6au && bit_0547 == 1u);
    assert(sfr_read_count == 2u && sfr_read_trace[0] == 0xa8u && sfr_read_trace[1] == 0xa9u);
    assert(sfr_write_count == 2u && sfr_write_trace[0] == 0xa8u && sfr_write_values[0] == 0xd5u && sfr_write_trace[1] == 0xa9u && sfr_write_values[1] == 0x6au);

    clear_memory(0u);
    firmware_memory[0x1098u] = 9u;
    sfr_memory[0xa8u] = 0x35u;
    sfr_memory[0xa9u] = 0xc3u;
    bit_0547 = 0u;
    ServiceControllerCommand0EMeasurementCapture();
    assert(read_count == 3u && write_count == 0u);
    assert(command0e_accumulator_call_count == 1u && command0e_accumulator_seen_bit_0547 == 0u);
    assert(sfr_memory[0xa8u] == 0x35u && sfr_memory[0xa9u] == 0xc3u && bit_0547 == 0u);
}

