    synthetic_operation_range_result = 0u;
    assert(PrepareSyntheticRawReadOperationState() == 0u);
    assert(synthetic_operation_event_count == 1u && synthetic_operation_events[0] == 1u && synthetic_operation_clear_count == 0u);

    clear_memory(0u);
