static void test_apply_fixed_controller_register_profile_for_operating_code(void)
{
    static const u8 operating_codes[5] = { 0x14u, 0x18u, 0x20u, 0x28u, 0x34u };
    static const fw_addr_t payload_addresses[5] = { 0x00e75cul, 0x00e77eul, 0x00e7a0ul, 0x00e7c2ul, 0x00e7e4ul };
    static const fw_addr_t auxiliary_ports[5] = { 0x0180aaul, 0x0180a9ul, 0x0180a6ul, 0x0180a7ul, 0x0180a8ul };
    unsigned profile_index;
    unsigned index;

    for(profile_index = 0u; profile_index != 5u; ++profile_index)
    {
        fw_addr_t payload = payload_addresses[profile_index];

        clear_memory(0u);
        firmware_memory[0xfcau] = 0x52u;
        for(index = 0u; index != 0x21u; ++index)
            firmware_memory[payload + index] = (u8)(0x20u + profile_index * 0x21u + index);
        ApplyFixedControllerRegisterProfileForOperatingCode(operating_codes[profile_index]);
        assert(fixed_controller_profile_event_count == 4u && fixed_controller_profile_events[0] == 1u && fixed_controller_profile_events[1] == 2u && fixed_controller_profile_events[2] == 3u
               && fixed_controller_profile_events[3] == 4u && write_count == 37u && firmware_memory[0xfcau] == 0x42u && firmware_memory[0x18002u] == 0x42u);
        assert(write_trace[0] == 0x000fcaul && write_values[0] == 0x5au && write_trace[1] == 0x018002ul && write_values[1] == 0x5au && write_trace[35] == 0x000fcaul && write_values[35] == 0x42u
               && write_trace[36] == 0x018002ul && write_values[36] == 0x42u);
        for(index = 0u; index != 5u; ++index)
            assert(write_trace[2u + index] == auxiliary_ports[index] && write_values[2u + index] == firmware_memory[payload + 0x1cu + index]);
        for(index = 0u; index != 0x1cu; ++index)
        {
            assert(
                write_trace[7u + index] == 0x018081ul + index && write_values[7u + index] == firmware_memory[payload + index] && firmware_memory[0x18081u + index] == firmware_memory[payload + index]);
        }
    }

    clear_memory(0u);
    firmware_memory[0xfcau] = 0x52u;
    ApplyFixedControllerRegisterProfileForOperatingCode(0x10u);
    assert(write_count == 4u && fixed_controller_profile_event_count == 4u && write_trace[0] == 0x000fcaul && write_values[0] == 0x5au && write_trace[1] == 0x018002ul && write_values[1] == 0x5au
           && write_trace[2] == 0x000fcaul && write_values[2] == 0x42u && write_trace[3] == 0x018002ul && write_values[3] == 0x42u);
}

