static void test_controller_buffer_memory_addressing(void)
{
    static const u8 successful_events[] = { 1u, 1u, 2u, 1u, 2u, 1u, 2u, 2u, 3u, 3u };
    static const unsigned failure_event_counts[] = { 3u, 5u, 7u, 8u, 9u, 10u };
    static const unsigned failure_base_read_counts[] = { 12u, 20u, 28u, 32u, 32u, 32u };
    const fw_addr_t base = 0x00a123ul;
    unsigned failure_stage;
    unsigned index;

    clear_memory(0u);
    reset_controller_buffer_addressing_observers();
    set_memory_big_endian_u32(0x155au, base);
    read_count = write_count = 0u;
    assert(TestControllerBufferMemoryAddressing() == 1u);
    assert(controller_buffer_addressing_event_count == 10u);
    for(index = 0u; index != 10u; ++index)
        assert(controller_buffer_addressing_events[index] == successful_events[index]);
    assert(controller_buffer_addressing_write_count == 4u && controller_buffer_addressing_write_offsets[0] == base + 0x500ul && controller_buffer_addressing_write_values[0] == 0xabu
           && controller_buffer_addressing_write_offsets[1] == base + 0x700ul && controller_buffer_addressing_write_values[1] == 0xcdu && controller_buffer_addressing_write_offsets[2] == base
           && controller_buffer_addressing_write_values[2] == 0x55u && controller_buffer_addressing_write_offsets[3] == base + 0x20000ul && controller_buffer_addressing_write_values[3] == 0xaau);
    assert(controller_buffer_addressing_read_count == 4u && controller_buffer_addressing_read_offsets[0] == base + 0x500ul && controller_buffer_addressing_read_offsets[1] == base
           && controller_buffer_addressing_read_offsets[2] == base && controller_buffer_addressing_read_offsets[3] == base + 0x20000ul);
    assert(controller_buffer_addressing_stride_count == 2u && controller_buffer_addressing_stride_arguments[0] == 0x55u && controller_buffer_addressing_stride_arguments[1] == 0xaau);
    assert(read_count == 32u && write_count == 0u);
    for(index = 0u; index != 32u; ++index)
        assert(read_trace[index] == 0x00155aul + index % 4u);

    for(failure_stage = 0u; failure_stage != 6u; ++failure_stage)
    {
        clear_memory(0u);
        reset_controller_buffer_addressing_observers();
        set_memory_big_endian_u32(0x155au, base);
        read_count = write_count = 0u;
        if(failure_stage < 4u)
            controller_buffer_addressing_read_results[failure_stage] ^= 1u;
        else
            controller_buffer_addressing_stride_results[failure_stage - 4u] = 0u;
        assert(TestControllerBufferMemoryAddressing() == 0u);
        assert(controller_buffer_addressing_event_count == failure_event_counts[failure_stage]);
        for(index = 0u; index != controller_buffer_addressing_event_count; ++index)
            assert(controller_buffer_addressing_events[index] == successful_events[index]);
        assert(read_count == failure_base_read_counts[failure_stage] && write_count == 0u);
    }
}

static void test_controller_buffer_bank_stride_pattern(void)
{
    static const u8 successful_reads[] = { 0x50u, 0x51u, 0x52u, 0u };
    const fw_addr_t base = 0x00198000ul;
    unsigned index;

    clear_memory(0u);
    reset_controller_buffer_addressing_observers();
    memcpy(controller_buffer_addressing_read_results, successful_reads, sizeof(successful_reads));
    set_memory_big_endian_u32(0x155au, base);
    read_count = write_count = 0u;
    assert(TestControllerBufferBankStridePattern(0x50u) == 1u);
    assert(controller_buffer_addressing_write_count == 3u && controller_buffer_addressing_read_count == 3u);
    for(index = 0u; index < 3u; ++index)
    {
        assert(controller_buffer_addressing_write_offsets[index] == base + (fw_addr_t)index * 0x8000ul);
        assert(controller_buffer_addressing_write_values[index] == (u8)(0x50u + index));
        assert(controller_buffer_addressing_read_offsets[index] == base + (fw_addr_t)index * 0x8000ul);
        assert(controller_buffer_addressing_events[index] == 1u && controller_buffer_addressing_events[index + 3u] == 2u);
    }

    clear_memory(0u);
    reset_controller_buffer_addressing_observers();
    memcpy(controller_buffer_addressing_read_results, successful_reads, sizeof(successful_reads));
    controller_buffer_addressing_read_results[1] ^= 1u;
    set_memory_big_endian_u32(0x155au, base);
    assert(TestControllerBufferBankStridePattern(0x50u) == 0u);
    assert(controller_buffer_addressing_write_count == 3u && controller_buffer_addressing_read_count == 2u);

    clear_memory(0u);
    reset_controller_buffer_addressing_observers();
    set_memory_big_endian_u32(0x155au, 0x001b0000ul);
    assert(TestControllerBufferBankStridePattern(0xa5u) == 1u);
    assert(controller_buffer_addressing_write_count == 0u && controller_buffer_addressing_read_count == 0u);
}

