static void test_validate_close_session_track_table_state(void)
{
    static const u8 rejected_states[] = { 3u, 2u, 5u, 6u, 7u };
    unsigned state_case;

    clear_memory(0u);
    firmware_memory[0x0c46u] = 1u;
    firmware_memory[0xe4ecu] = 7u;
    firmware_memory[0xdd7fu] = 7u;
    assert(ValidateCloseSessionTrackTableState() == 0u);
    assert(firmware_memory[0x0b1au] == 5u && firmware_memory[0x0b24u] == 0x2cu && firmware_memory[0x0b25u] == 4u);

    clear_memory(0u);
    firmware_memory[0x0c46u] = 1u;
    firmware_memory[0xe4ecu] = 6u;
    firmware_memory[0xdd7fu] = 7u;
    assert(ValidateCloseSessionTrackTableState() == 1u);

    for(state_case = 0u; state_case < sizeof(rejected_states) / sizeof(rejected_states[0]); ++state_case)
    {
        u8 state = rejected_states[state_case];

        clear_memory(0u);
        firmware_memory[0xdd7eu] = 1u;
        firmware_memory[0xdd7fu] = 2u;
        firmware_memory[0xdd87u + 19u] = state;
        assert(ValidateCloseSessionTrackTableState() == 0u);
        assert(firmware_memory[0x0b1au] == (state <= 3u ? 5u : 2u));
        assert(firmware_memory[0x0b24u] == (state <= 3u ? 0x72u : 0x30u));
        assert(firmware_memory[0x0b25u] == 4u);
    }

    clear_memory(0u);
    firmware_memory[0xdd7eu] = 1u;
    firmware_memory[0xdd7fu] = 2u;
    firmware_memory[0xdd87u + 2u * 19u] = 1u;
    assert(ValidateCloseSessionTrackTableState() == 0u);
    assert(firmware_memory[0x0b1au] == 5u && firmware_memory[0x0b24u] == 0x2cu && firmware_memory[0x0b25u] == 0u);

    clear_memory(0u);
    firmware_memory[0xdd7eu] = 2u;
    firmware_memory[0xdd7fu] = 2u;
    assert(ValidateCloseSessionTrackTableState() == 0u);
    assert(firmware_memory[0x0b1au] == 5u && firmware_memory[0x0b24u] == 0x2cu && firmware_memory[0x0b25u] == 4u);

    clear_memory(0u);
    firmware_memory[0xdd7eu] = 1u;
    firmware_memory[0xdd7fu] = 2u;
    assert(ValidateCloseSessionTrackTableState() == 1u);

    clear_memory(0u);
    firmware_memory[0xdd7eu] = 99u;
    firmware_memory[0xdd7fu] = 100u;
    assert(ValidateCloseSessionTrackTableState() == 1u);
}

