static void test_apply_fixed_controller_parameter_table_for_operating_code_class(void)
{
    unsigned operating_code;

    for(operating_code = 0u; operating_code < 256u; ++operating_code)
    {
        u8 table_index = operating_code < 4u ? 0u : 5u;
        fw_addr_t pointer_entry = 0xff857cul + (fw_addr_t)table_index * 4u;
        fw_addr_t table_address = table_index == 0u ? 0x001000ul : 0x002000ul;

        clear_memory(0u);
        firmware_memory[0x0e43u] = (u8)operating_code;
        set_memory_big_endian_u32_far(pointer_entry, table_address);
        set_memory_big_endian_u16((u16)table_address, 0xffffu);
        read_count = 0u;
        ApplyFixedControllerParameterTableForOperatingCodeClass();
        assert(read_count == 7u && read_trace[0] == 0x0e43ul && read_trace[1] == pointer_entry && read_trace[5] == table_address && read_trace[6] == table_address + 1u);
        assert(write_count == 0u);
    }
}

