static void test_refresh_toc_state_from_raw_read_q_record_table(void)
{
    clear_memory(0xa5u);
    firmware_memory[0x0c44u] = 2u;
    firmware_memory[0x0c45u] = 0u;
    firmware_memory[0x12c9u] = 1u;
    RefreshTocStateFromRawReadQRecordTable();
    assert(mode0_toc_refresh_call_count == 1u && mode0_toc_refresh_seen_read_count == 0u);
    assert(raw_q_toc_parse_call_count == 0u && read_count == 3u && write_count == 0u);
    assert(read_trace[0] == 0x0c44ul && read_trace[1] == 0x0c45ul && read_trace[2] == 0x12c9ul);

    clear_memory(0u);
    firmware_memory[0x0c44u] = 1u;
    firmware_memory[0x0c45u] = 0x5au;
    firmware_memory[0x12c9u] = 0x5au;
    firmware_memory[0x0c46u] = 1u;
    set_memory_big_endian_u32(0x14deu, 0x89abcdeful);
    read_count = 0u;
    write_count = 0u;
    RefreshTocStateFromRawReadQRecordTable();
    assert(raw_q_toc_parse_call_count == 1u && raw_q_toc_parse_seen_start == 0x89abcdeful && raw_q_toc_parse_seen_first_track == 1u);
    assert(get_memory_big_endian_u32(0x1143u) == 0x89abcdeful && firmware_memory[0x1147u] == 1u);
    assert(read_count == 6u && read_trace[0] == 0x0c44ul && read_trace[1] == 0x14deul && read_trace[4] == 0x14e1ul && read_trace[5] == 0x0c46ul);
    assert(write_count == 5u && write_trace[0] == 0x1143ul && write_trace[3] == 0x1146ul && write_trace[4] == 0x1147ul);

    clear_memory(0u);
    firmware_memory[0x0c44u] = 2u;
    firmware_memory[0x0c45u] = 0xc0u;
    firmware_memory[0x12c9u] = 0u;
    firmware_memory[0x0c46u] = 1u;
    set_memory_big_endian_u32(0x14deu, 0x01020304ul);
    read_count = 0u;
    write_count = 0u;
    RefreshTocStateFromRawReadQRecordTable();
    assert(raw_q_toc_parse_call_count == 1u && read_count == 7u);
    assert(read_trace[0] == 0x0c44ul && read_trace[1] == 0x0c45ul && read_trace[2] == 0x14deul && read_trace[6] == 0x0c46ul);

    clear_memory(0u);
    firmware_memory[0x0c44u] = 2u;
    firmware_memory[0x0c45u] = 0u;
    firmware_memory[0x12c9u] = 2u;
    firmware_memory[0x0c46u] = 1u;
    firmware_memory[0x1132u] = 0xffu;
    set_memory_big_endian_u32(0x14deu, 0x76543210ul);
    raw_q_toc_parse_mutate_option_flags = 1u;
    raw_q_toc_parse_option_flags = 0u;
    raw_q_toc_parse_mutate_state = 1u;
    raw_q_toc_parse_state = 0x81u;
    read_count = 0u;
    write_count = 0u;
    RefreshTocStateFromRawReadQRecordTable();
    assert(raw_q_toc_parse_call_count == 1u && raw_q_toc_parse_seen_start == 0x76543210ul);
    assert(firmware_memory[0x1132u] == 0x21u);
    assert(read_count == 10u && read_trace[0] == 0x0c44ul && read_trace[1] == 0x0c45ul && read_trace[2] == 0x12c9ul && read_trace[7] == 0x0c46ul && read_trace[8] == 0x1132ul
           && read_trace[9] == 0x1132ul);
    assert(write_count == 7u && write_trace[5] == 0x1132ul && write_trace[6] == 0x1132ul);
}

static void test_submit_controller_buffer_command40_and_wait_coroutine0(void)
{
    static const fw_addr_t expected_writes[] = { 0x001038ul, 0x01807eul, 0x01806ful, 0x018070ul, 0x018071ul, 0x018072ul, 0x018073ul, 0x018074ul, 0x018075ul, 0x2ba5c1ul, 0x01806ful };
    static const u8 expected_values[] = { 0xa6u, 0xa6u, 1u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0x40u };
    unsigned index;

    clear_memory(0u);
    firmware_memory[0x1038u] = 0xa4u;
    firmware_memory[0x2ba5c1u] = 0xffu;
    yield_coroutine0_command40_complete_after = 2u;
    yield_coroutine0_command40_completion = 0x7eu;
    SubmitControllerBufferCommand40AndWaitCoroutine0();

    assert(yield_coroutine0_count == 2u);
    assert(firmware_memory[0x1038u] == 0xa6u && firmware_memory[0x1807eu] == 0xa6u && firmware_memory[0x1806fu] == 0x40u && firmware_memory[0x2ba5c1u] == 0x7eu);
    for(index = 0u; index != 6u; ++index)
        assert(firmware_memory[0x18070u + index] == 0u);
    assert(read_count == 4u && read_trace[0] == 0x1038ul && read_trace[1] == 0x2ba5c1ul && read_trace[2] == 0x2ba5c1ul && read_trace[3] == 0x2ba5c1ul);
    assert(write_count == sizeof(expected_writes) / sizeof(expected_writes[0]));
    for(index = 0u; index != write_count; ++index)
    {
        assert(write_trace[index] == expected_writes[index]);
        assert(write_values[index] == expected_values[index]);
    }
}

