static void test_prepare_read_measurement_for_low_descriptor_mode(void)
{
    static const u8 modes[] = { 1u, 2u, 3u };
    unsigned index;

    for(index = 0u; index < sizeof(modes) / sizeof(modes[0]); ++index)
    {
        u32 offset = modes[index] == 2u ? 4ul : 2ul;

        clear_memory(0u);
        firmware_memory[0xfb9eu] = modes[index];
        set_memory_big_endian_u32(0xfba2u, index == 2u ? 1ul : 100ul);
        write_count = 0u;
        read_count = 0u;
        PrepareReadMeasurementForLowDescriptorMode();
        assert(adjusted_target_prepare_call_count == 1u);
        assert(adjusted_target_prepare_seen_target == (index == 2u ? 0xfffffffful : 100ul - offset));
        assert(read_count == 5u && read_trace[0] == 0xfb9eul && read_trace[1] == 0xfba2ul && read_trace[4] == 0xfba5ul);
        assert(write_count == 4u && write_trace[0] == 0xfba6ul && write_trace[3] == 0xfba9ul);
    }

    for(index = 0u; index < 2u; ++index)
    {
        clear_memory(0xa5u);
        firmware_memory[0xfb9eu] = index == 0u ? 0u : 0xffu;
        write_count = 0u;
        read_count = 0u;
        PrepareReadMeasurementForLowDescriptorMode();
        assert(read_count == 1u && write_count == 1u && adjusted_target_prepare_call_count == 0u && firmware_memory[0xfba0u] == 7u);
    }
}

