    assert(firmware_memory[0x18010ul] == 0xefu && firmware_memory[0x18011ul] == 0xcdu && firmware_memory[0x18012ul] == 0xabu);
    assert(firmware_memory[0x18056ul] == 0x50u && firmware_memory[0x18022ul] == 0x80u && firmware_memory[0x18051ul] == 2u && firmware_memory[0x1805eul] == 0x97u);
    assert(firmware_memory[0x1801ful] == 0u && firmware_memory[0x18020ul] == 0u && firmware_memory[0x18021ul] == 0u && firmware_memory[0x18047ul] == 0x14u);

