static void test_process_indexed_state_completion(void)
{
    unsigned state;
    unsigned flags;

    for(state = 0u; state < 256u; ++state)
    {
        for(flags = 0u; flags < 256u; ++flags)
        {
            u8 expected = (u8)(state == 1u && (flags & 0x20u) != 0u);

            clear_memory(0u);
            firmware_memory[0x1309u] = (u8)state;
            firmware_memory[0x11efu] = (u8)flags;
            firmware_memory[0x0fbbu] = 1u;
            firmware_memory[0x1132u] = 0u;
            firmware_memory[0x12c0u] = 10u;
            read_count = write_count = 0u;

            assert(ProcessIndexedStateCompletion() == expected);
            if(state != 1u)
            {
                assert(read_count == 1u && read_trace[0] == 0x1309ul);
                assert(write_count == 0u && load_read_acquisition_target_call_count == 0u);
            }
            else if((flags & 0x20u) == 0u)
            {
                assert(read_count == 2u && read_trace[0] == 0x1309ul && read_trace[1] == 0x11eful);
                assert(write_count == 0u && load_read_acquisition_target_call_count == 0u);
            }
            else
            {
                assert(firmware_memory[0x11efu] == (u8)(flags & 0xdfu));
                assert(firmware_memory[0x0fbbu] == 2u && firmware_memory[0x0e42u] == 2u);
                assert(read_count == 6u && read_trace[0] == 0x1309ul && read_trace[1] == 0x11eful && read_trace[2] == 0x11eful && read_trace[3] == 0x0fbbul && read_trace[4] == 0x1132ul
                       && read_trace[5] == 0x12c0ul);
                assert(write_count == 3u && write_trace[0] == 0x11eful && write_trace[1] == 0x0fbbul && write_trace[2] == 0x0e42ul);
                assert(load_read_acquisition_target_call_count == 1u && load_read_acquisition_target_seen_write_count == 3u && load_read_acquisition_target_seen_track_number == 2u);
            }
        }
    }
}

