        assert(firmware_memory[0x0efeu] == (u8)(255u - initial));
        assert(read_count == 1u && read_trace[0] == 0x11d9ul);
        assert(write_count == 1u && write_trace[0] == 0x11d9ul);

        clear_memory(0u);
