    command0e_accumulator_primary_sample = -1;
    command0e_finalizer_count_after_signed = 5u;
    AccumulateControllerCommand0EMeasurementCapture();
    assert(command0e_accumulator_event_count == 2u && command0e_accumulator_events[0] == 1u && command0e_accumulator_events[1] == 2u);
    assert(firmware_memory[0x10a2u] == 3u && firmware_memory[0x1098u] == 0x60u && firmware_memory[0x10a3u] == 2u && get_memory_big_endian_u32(0x10a4u) == 0xffffffb8ul);
    assert(
        command0e_finalizer_signed_dividend == -1l && command0e_finalizer_signed_divisor == 2l && command0e_finalizer_unsigned_dividend == 0xf0000000ul && command0e_finalizer_unsigned_divisor == 5ul);
