    assert(firmware_memory[0x103au] == 0xefu);

    clear_memory(0u);
    firmware_memory[0x1046u] = 10u;
    firmware_memory[0x1047u] = 20u;
    firmware_memory[0x1048u] = 30u;
    firmware_memory[0x1049u] = 40u;
    firmware_memory[0x104du] = 0x91u;
    assert(SelectControllerCalibrationCandidateFromFourSamples() == 1u);
    assert(firmware_memory[0x1042u] == 0x91u && firmware_memory[0x1054u] == 0u);

    clear_memory(0u);
    firmware_memory[0x1046u] = 10u;
    firmware_memory[0x1047u] = 10u;
    firmware_memory[0x1048u] = 30u;
    firmware_memory[0x1049u] = 40u;
    firmware_memory[0x104eu] = 0x92u;
    assert(SelectControllerCalibrationCandidateFromFourSamples() == 1u);
    assert(firmware_memory[0x1042u] == 0x92u && firmware_memory[0x1054u] == 1u);

    clear_memory(0u);
    firmware_memory[0x1046u] = 20u;
    firmware_memory[0x1047u] = 14u;
    firmware_memory[0x1048u] = 30u;
    firmware_memory[0x1049u] = 10u;
    firmware_memory[0x104fu] = 0xa2u;
    firmware_memory[0x1050u] = 3u;
    assert(SelectControllerCalibrationCandidateFromFourSamples() == 1u);
    assert(firmware_memory[0x1042u] == 0xa2u && firmware_memory[0x1054u] == 2u);

    clear_memory(0u);
    firmware_memory[0x1046u] = 20u;
    firmware_memory[0x1047u] = 14u;
    firmware_memory[0x1048u] = 30u;
    firmware_memory[0x1049u] = 10u;
    firmware_memory[0x104du] = 0xa0u;
    firmware_memory[0x1050u] = 0xfdu;
    assert(SelectControllerCalibrationCandidateFromFourSamples() == 1u);
    assert(firmware_memory[0x1042u] == 0xa0u && firmware_memory[0x1054u] == 0u);

    clear_memory(0u);
    firmware_memory[0x1008u] = 2u;
    firmware_memory[0x1046u] = 10u;
    firmware_memory[0x1047u] = 20u;
    firmware_memory[0x1048u] = 30u;
    firmware_memory[0x1049u] = 40u;
    firmware_memory[0x104du] = 1u;
    assert(SelectControllerCalibrationCandidateFromFourSamples() == 1u);
    assert(firmware_memory[0x1042u] == 1u && firmware_memory[0x1051u] == 0xffu && firmware_memory[0x1052u] == 1u && firmware_memory[0x1053u] == 3u);

    clear_memory(0u);
    memset(&firmware_memory[0x1046u], 0xff, 4u);
    firmware_memory[0x103au] = 0x85u;
    assert(SelectControllerCalibrationCandidateFromFourSamplesBody() == 0u);
    assert(firmware_memory[0x103au] == 0x95u);

    clear_memory(0u);
    firmware_memory[0x1008u] = 2u;
    firmware_memory[0x1046u] = 20u;
    firmware_memory[0x1047u] = 14u;
    firmware_memory[0x1048u] = 30u;
    firmware_memory[0x1049u] = 10u;
    firmware_memory[0x104fu] = 1u;
    firmware_memory[0x1050u] = 3u;
    assert(SelectControllerCalibrationCandidateFromFourSamplesBody() == 1u);
    assert(firmware_memory[0x1042u] == 1u && firmware_memory[0x1054u] == 2u && firmware_memory[0x1051u] == 0xffu && firmware_memory[0x1052u] == 1u && firmware_memory[0x1053u] == 3u);
