static void test_sample_controller_port80c0_bit3_with_handshake(void)
{
    unsigned initial_shadow;

    for(initial_shadow = 0u; initial_shadow < 256u; ++initial_shadow)
    {
        u8 first_shadow = (u8)(initial_shadow | 0x08u);
        u8 final_shadow = (u8)(initial_shadow & 0xe7u);

        clear_memory(0u);
        firmware_memory[0x0fcau] = (u8)initial_shadow;
        firmware_memory[0x80c0u] = (u8)initial_shadow;
        sfr_memory[0xa9u] = (u8)(255u - initial_shadow);
        bit_0547 = 1u;
        bit_0546 = 0u;
        assert(SampleControllerPort80C0Bit3WithHandshake() == (u8)((initial_shadow & 0x08u) != 0u));
        assert(read_count == 3u && read_trace[0] == 0x0fcaul && read_trace[1] == 0x80c0ul && read_trace[2] == 0x0fcaul);
        assert(write_count == 4u && write_trace[0] == 0x0fcaul && write_values[0] == first_shadow && write_trace[1] == 0x8002ul && write_values[1] == first_shadow && write_trace[2] == 0x0fcaul
               && write_values[2] == final_shadow && write_trace[3] == 0x8002ul && write_values[3] == final_shadow);
        assert(firmware_memory[0x0fcau] == final_shadow && firmware_memory[0x8002u] == final_shadow);
        assert(bit_0547 == 1u && bit_0546 == 1u);
        assert(sfr_memory[0xa9u] == (u8)((255u - initial_shadow) | 0x04u));
    }
}

