static void test_consume_raw_read_descriptors_focused(void)
{
    static const struct
    {
        u16 consumer;
        u16 mask;
        u16 queued;
        u16 count;
    } cases[] = {
        { 6u,      7u,      3u,   3u },
        { 0xfffeu, 0x00ffu, 0u,   3u },
        { 0x1234u, 0x0f0fu, 100u, 0u }
    };
    static const fw_addr_t expected_reads[] = { 0x1294ul, 0x1295ul, 0x129aul, 0x129bul, 0x1294ul, 0x1295ul, 0x1292ul, 0x1293ul };
    static const fw_addr_t expected_writes[] = { 0x1294ul, 0x1295ul, 0x1294ul, 0x1295ul, 0x1292ul, 0x1293ul };
    unsigned case_index;
    unsigned trace_index;

    for(case_index = 0u; case_index < sizeof(cases) / sizeof(cases[0]); ++case_index)
    {
        u16 advanced = (u16)(cases[case_index].consumer + cases[case_index].count);
        u16 expected_consumer = (u16)(advanced & cases[case_index].mask);
        u16 expected_queued = (u16)(cases[case_index].queued - cases[case_index].count);

        clear_memory(0u);
        set_memory_big_endian_u16(0x1294u, cases[case_index].consumer);
        set_memory_big_endian_u16(0x129au, cases[case_index].mask);
        set_memory_big_endian_u16(0x1292u, cases[case_index].queued);
        bit_0547 = 1u;
        ConsumeRawReadDescriptors(cases[case_index].count);
        assert(get_memory_big_endian_u16(0x1294u) == expected_consumer);
        assert(get_memory_big_endian_u16(0x1292u) == expected_queued);
        assert(bit_0547 == 1u && read_count == 8u && write_count == 6u);
        for(trace_index = 0u; trace_index < 8u; ++trace_index)
            assert(read_trace[trace_index] == expected_reads[trace_index]);
        for(trace_index = 0u; trace_index < 6u; ++trace_index)
            assert(write_trace[trace_index] == expected_writes[trace_index]);
    }
}

