static void test_calibrate_controller_port8097_with_command08(void)
{
    unsigned attempt;

    clear_memory(0u);
    controller_f8_wait500_result = 0u;
    CalibrateControllerPort8097WithCommand08ForTest();
    assert(controller_f8_wait500_call_count == 1u);
    assert(controller_f8_wait_call_count == 1u);
    assert(port8097_calibration_wait_count == 1u && port8097_calibration_wait_durations[0] == 4000u && port8097_calibration_wait_yields[0] == 1u);
    assert(port8097_calibration_read_count == 0u);
    assert(port8097_calibration_write_count == 8u);
    assert(port8097_calibration_write_addresses[0] == 0x0180c0ul && port8097_calibration_write_values[0] == 2u);
    assert(port8097_calibration_write_addresses[1] == 0x018097ul && port8097_calibration_write_values[1] == 0x18u);
    assert(port8097_calibration_write_addresses[5] == 0x0180c4ul && port8097_calibration_write_values[5] == 0u);
    assert(port8097_calibration_write_addresses[6] == 0x0180c0ul && port8097_calibration_write_values[6] == 0u);
    assert(port8097_calibration_write_addresses[7] == 0x018097ul && port8097_calibration_write_values[7] == 0xc0u);
    assert(firmware_memory[0xfab7u] == 0xc0u);

    clear_memory(0u);
    controller_f8_wait500_result = 1u;
    port8097_calibration_read_values[0] = 0x9fu;
    CalibrateControllerPort8097WithCommand08ForTest();
    assert(controller_f8_wait500_call_count == 2u);
    assert(controller_f8_wait_call_count == 0u);
    assert(port8097_calibration_wait_count == 1u);
    assert(port8097_calibration_read_count == 1u && port8097_calibration_read_addresses[0] == 0x0180c7ul);
    assert(port8097_calibration_write_count == 10u);
    assert(port8097_calibration_write_addresses[8] == 0x0180c0ul && port8097_calibration_write_values[8] == 2u);
    assert(port8097_calibration_write_addresses[9] == 0x0180c0ul && port8097_calibration_write_values[9] == 0u);
    assert(firmware_memory[0xfab7u] == 0x18u);

    clear_memory(0u);
    controller_f8_wait500_result = 1u;
    port8097_calibration_read_values[0] = 0x9eu;
    port8097_calibration_read_values[1] = 0x9fu;
    CalibrateControllerPort8097WithCommand08ForTest();
    assert(controller_f8_wait500_call_count == 4u);
    assert(port8097_calibration_wait_count == 2u);
    assert(port8097_calibration_read_count == 2u);
    assert(port8097_calibration_write_count == 18u);
    assert(port8097_calibration_write_values[1] == 0x18u && port8097_calibration_write_values[9] == 0x19u);
    assert(firmware_memory[0xfab7u] == 0x19u);

    clear_memory(0u);
    controller_f8_wait500_result = 1u;
    memset(port8097_calibration_read_values, 0x80, sizeof(port8097_calibration_read_values));
    CalibrateControllerPort8097WithCommand08ForTest();
    assert(controller_f8_wait500_call_count == 36u);
    assert(port8097_calibration_wait_count == 18u);
    assert(port8097_calibration_read_count == 18u);
    assert(port8097_calibration_write_count == 147u);
    for(attempt = 0u; attempt != 18u; ++attempt)
    {
        u8 expected_candidate = attempt < 8u ? (u8)(0x18u + attempt) : (u8)(attempt - 8u);

        assert(port8097_calibration_write_addresses[1u + attempt * 8u] == 0x018097ul);
        assert(port8097_calibration_write_values[1u + attempt * 8u] == expected_candidate);
    }
    assert(port8097_calibration_write_addresses[146] == 0x018097ul && port8097_calibration_write_values[146] == 0xc0u);
    assert(firmware_memory[0xfab7u] == 0xc0u);
}

