    firmware_memory[0xfbecu] = 1u;
    firmware_memory[0x1305u] = 0xffu;
    service_disable_countdown_clear_after = 2u;
    ServiceConditionalControllerOperatingDisable();
    assert(firmware_memory[0x1006u] == 0u && service_disable_countdown_read_count == 2u);
    assert(firmware_memory[0x1215u] == 0u && firmware_memory[0x1305u] == 0xbfu);
    assert(write_trace[write_count - 3u] == 0x001215ul && write_values[write_count - 3u] == 0x28u && write_trace[write_count - 2u] == 0x001215ul && write_values[write_count - 2u] == 0x14u
           && write_trace[write_count - 1u] == 0x001305ul);

