    firmware_memory[0xf553u] = 0u;
    firmware_memory[0x1132u] = 0x40u;
    firmware_memory[0x1305u] = 0xffu;
    ServiceConditionalControllerOperatingDisable();
    assert(firmware_memory[0x1215u] == 0u && firmware_memory[0x1305u] == 0xbfu && write_count == 1u);
