static void test_update_controller_measurement_reference(void)
{
    static const fw_addr_t expected_reads[] = { 0x0cf5ul, 0x0cf6ul, 0x0cf7ul, 0x0cf8ul, 0x0e3bul, 0x0e3cul, 0x0e3dul, 0x0e3eul, 0x0e4ful };
    unsigned index;

    clear_memory(0u);
    set_memory_big_endian_u32(0x0cf5u, 65ul * 0x11234ul);
    set_memory_big_endian_u32(0x0e3bu, 0x00123456ul);
    firmware_memory[0x0e4ful] = 0x28u;
    controller_measurement_reference_compute_result = 0x89abcdeful;

    UpdateControllerMeasurementReference();

    assert(controller_measurement_reference_compute_count == 1u);
    assert(controller_measurement_reference_value_seen == 0x00123456ul);
    assert(controller_measurement_radial_quotient_seen == 0x1234u);
    assert(controller_measurement_operating_code_seen == 0x28u);
    assert(get_memory_big_endian_u16(0xfc27u) == 0xcdefu);
    assert(read_count == sizeof(expected_reads) / sizeof(expected_reads[0]));
    for(index = 0u; index < read_count; ++index)
        assert(read_trace[index] == expected_reads[index]);
    assert(write_count == 2u);
    assert(write_trace[0] == 0xfc27ul && write_values[0] == 0xcdu);
    assert(write_trace[1] == 0xfc28ul && write_values[1] == 0xefu);
}

static u16 run_read_acquisition_tolerance_case(s32 current_position, s32 target_position, u8 speed)
{
    clear_memory(0u);
    set_memory_big_endian_u32(0x0cf5u, 65ul);
    set_memory_big_endian_u32(0x0e3bu, (u32)current_position);
    set_memory_big_endian_u32(0x1235u, (u32)target_position);
    firmware_memory[0x0e46u] = speed;
    firmware_memory[0x0e4fu] = 4u;
    controller_measurement_reference_compute_result = 1000u;
    return ComputeReadAcquisitionDynamicToleranceFrames();
}

static void test_compute_read_acquisition_dynamic_tolerance_frames(void)
{
    assert(run_read_acquisition_tolerance_case(0, 60000, 4u) == 20u);
    assert(controller_measurement_reference_compute_count == 1u);
    assert(read_count == 27u);

    assert(run_read_acquisition_tolerance_case(60000, 0, 4u) == 20u);
    assert(read_count == 35u);

    assert(run_read_acquisition_tolerance_case(0, 3000, 4u) == 15u);
    assert(run_read_acquisition_tolerance_case(0, 363000, 4u) == 120u);
    assert(run_read_acquisition_tolerance_case(12345, 12345, 4u) == 15u);
    assert(run_read_acquisition_tolerance_case(0, 60000, 0x18u) == 180u);
    assert(run_read_acquisition_tolerance_case(0, 60000, 0x20u) == 250u);
    assert(read_trace[read_count - 1u] == 0x0e46ul);
}

static void test_check_controller_measurement_tolerance_or_timeout(void)
{
    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    controller_measurement_reference_compute_result = 1000u;
    firmware_memory[0x180a9ul] = 3u;
    firmware_memory[0x180a8ul] = 0xe8u;
    set_memory_big_endian_u16(0x1034u, 0x1234u);
    assert(CheckControllerMeasurementToleranceOrTimeout(1u) == 1u);
    assert(get_memory_big_endian_u16(0x1034u) == 0x1234u);
    assert(controller_measurement_reference_compute_count == 1u);

    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    controller_measurement_reference_compute_result = 1000u;
    assert(CheckControllerMeasurementToleranceOrTimeout(1u) == 0u);
    assert(get_memory_big_endian_u16(0x1034u) == 500u);
    assert(write_trace[3] == 0x1034ul && write_values[3] == 1u);
    assert(write_trace[4] == 0x1035ul && write_values[4] == 0xf4u);
    assert(controller_measurement_reference_compute_count == 1u);

    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    controller_measurement_reference_compute_result = 1000u;
    set_memory_big_endian_u16(0x1034u, 1u);
    assert(CheckControllerMeasurementToleranceOrTimeout(0u) == 0u);
    assert(get_memory_big_endian_u16(0x1034u) == 1u);
    assert(controller_measurement_reference_compute_count == 1u);

    set_memory_big_endian_u16(0x1034u, 0u);
    assert(CheckControllerMeasurementToleranceOrTimeout(0u) == 1u);
    set_memory_big_endian_u16(0x1034u, 0xffffu);
    assert(CheckControllerMeasurementToleranceOrTimeout(0u) == 1u);
    assert(controller_measurement_reference_compute_count == 3u);
}

static void test_apply_fixed_controller_parameter_tables_1_and_2(void)
{
    static const u8 operating_codes[] = { 3u, 4u, 0xffu };
    static const u8 selector_values[] = { 0xa5u, 0u, 1u };
    unsigned test_index;

    for(test_index = 0u; test_index < sizeof(operating_codes); ++test_index)
    {
        unsigned prefix_reads;

        clear_memory(0u);
        firmware_memory[0x0e43ul] = operating_codes[test_index];
        firmware_memory[0x1006ul] = selector_values[test_index];
        set_memory_big_endian_u32_far(0xff8580ul, 0x00122000ul);
        set_memory_big_endian_u32_far(0xff8584ul, 0x00122002ul);
        firmware_memory[0x122000ul] = 0xffu;
        firmware_memory[0x122001ul] = 0xffu;
        firmware_memory[0x122002ul] = 0xffu;
        firmware_memory[0x122003ul] = 0xffu;
        ApplyFixedControllerParameterTables1And2();
        prefix_reads = operating_codes[test_index] < 4u ? 1u : 2u;
        assert(read_count == prefix_reads + 12u);
        assert(read_trace[0] == 0x0e43ul);
        if(operating_codes[test_index] >= 4u)
            assert(read_trace[1] == 0x1006ul);
        assert(read_trace[prefix_reads] == 0xff8580ul);
        assert(read_trace[prefix_reads + 4u] == 0x122000ul);
        assert(read_trace[prefix_reads + 6u] == 0xff8584ul);
        assert(read_trace[prefix_reads + 10u] == 0x122002ul);
        assert(write_count == 0u);
    }
}

