    set_memory_big_endian_u32(0x0b06u, 0x89abcdeful);
    set_memory_big_endian_u32(0x0b02u, 0xffffff80ul);
    bit_0011 = 1u;

    assert(ResetRawReadTransferState() == 0x00000016ul);
    assert(get_memory_big_endian_u32(0x1459u) == 0ul);
    assert(firmware_memory[0x0f0bul] == 0u);
    assert(firmware_memory[0x0f06ul] == 0u);
