static void test_is_controller_read_path_within_operating_window(void)
{
    clear_memory(0u);
    controller_operating_sample_capture_count = 0u;
    bit_0031 = 0u;
    firmware_memory[0x18032u] = 0x1fu;
    assert(IsControllerReadPathWithinOperatingWindow(0u) == 1u);
    firmware_memory[0x18032u] = 0x20u;
    assert(IsControllerReadPathWithinOperatingWindow(1u) == 0u);
    assert(controller_operating_sample_capture_count == 0u);

    clear_memory(0u);
    controller_operating_sample_capture_count = 0u;
    bit_0031 = 1u;
    firmware_memory[0x0e51u] = 16u;
    controller_operating_sample = 1763;
    assert(IsControllerReadPathWithinOperatingWindow(1u) == 1u);
    controller_operating_sample = 1764;
    assert(IsControllerReadPathWithinOperatingWindow(1u) == 0u);
    controller_operating_sample = -1763;
    assert(IsControllerReadPathWithinOperatingWindow(1u) == 1u);
    controller_operating_sample = -1764;
    assert(IsControllerReadPathWithinOperatingWindow(1u) == 0u);

    clear_memory(0u);
    controller_operating_sample_capture_count = 0u;
    bit_0031 = 1u;
    firmware_memory[0x0e51u] = 16u;
    controller_operating_sample = 57;
    assert(IsControllerReadPathWithinOperatingWindow(0u) == 1u);
    controller_operating_sample = 58;
    assert(IsControllerReadPathWithinOperatingWindow(0u) == 0u);

    clear_memory(0u);
    controller_operating_sample_capture_count = 0u;
    bit_0031 = 1u;
    firmware_memory[0x0e51u] = 20u;
    controller_operating_sample = 2218;
    assert(IsControllerReadPathWithinOperatingWindow(1u) == 1u);
    controller_operating_sample = 2219;
    assert(IsControllerReadPathWithinOperatingWindow(1u) == 0u);
    controller_operating_sample = 72;
    assert(IsControllerReadPathWithinOperatingWindow(2u) == 1u);
    controller_operating_sample = 73;
    assert(IsControllerReadPathWithinOperatingWindow(2u) == 0u);
    assert(controller_operating_sample_capture_count == 4u);
    assert(read_count == 8u && read_trace[0] == 0x0e51ul && read_trace[1] == 0x0e51ul && read_trace[6] == 0x0e51ul && read_trace[7] == 0x0e51ul);
}

