static void test_compute_controller_profile_scaled_word(void)
{
    clear_memory(0xa5u);
    set_memory_big_endian_u16(0x00f9faul, 0u);
    set_memory_big_endian_u16(0x000ffeul, 0xffffu);
    assert(ComputeControllerProfileScaledWord(123.0f) == 0u);

    set_memory_big_endian_u16(0x00f9faul, 100u);
    set_memory_big_endian_u16(0x000ffeul, 32u);
    assert(ComputeControllerProfileScaledWord(20.0f) == 4u);
    assert(ComputeControllerProfileScaledWord(15.0f) == 0xffffu);
    assert(ComputeControllerProfileScaledWord(3.5f) == 0xfff4u);

    set_memory_big_endian_u16(0x00f9faul, 25u);
    set_memory_big_endian_u16(0x000ffeul, 64u);
    assert(ComputeControllerProfileScaledWord(18.5f) == 1u);
}

