static void test_write_scaled_operating_profile_word_via_sfr8b8d(void)
{
    u16 expected_reload;

    clear_memory(0u);
    reset_operating_profile_timer_observer();
    firmware_memory[0x0e4fu] = 0u;
    firmware_memory[0xff9212u] = 0x12u;
    firmware_memory[0xff9213u] = 0x34u;
    WriteScaledOperatingProfileWordViaSfr8B8D(3u);
    assert(sfr_memory[0x8du] == 0xc9u && sfr_memory[0x8bu] == 0x63u);
    assert(sfr_write_count == 2u && sfr_write_trace[0] == 0x8du && sfr_write_values[0] == 0xc9u && sfr_write_trace[1] == 0x8bu && sfr_write_values[1] == 0x63u);
    assert(read_count == 4u && read_trace[0] == 0x000e4ful && read_trace[1] == 0xff9212ul && read_trace[2] == 0xff9213ul && read_trace[3] == 0x01807ful);
    assert(operating_profile_timer_overflow_reads == 0u);
    assert(operating_profile_timer_event_count == 4u && operating_profile_timer_events[0] == 1u && operating_profile_timer_events[1] == 2u && operating_profile_timer_events[2] == 3u
           && operating_profile_timer_events[3] == 1u);

    clear_memory(0u);
    reset_operating_profile_timer_observer();
    firmware_memory[0x0e4fu] = 0x20u;
    firmware_memory[0xff9226u] = 0x80u;
    firmware_memory[0xff9227u] = 0x01u;
    firmware_memory[0x1807fu] = 0x08u;
    operating_profile_timer_overflow_after = 3u;
    WriteScaledOperatingProfileWordViaSfr8B8D(0xffu);
    expected_reload = (u16)(0xffffu - (u16)((u16)0xffu * (u16)0x8001u));
    assert(sfr_memory[0x8du] == (u8)(expected_reload >> 8) && sfr_memory[0x8bu] == (u8)expected_reload);
    assert(operating_profile_timer_overflow_reads == 3u);
    assert(read_count == 6u && read_trace[0] == 0x000e4ful && read_trace[1] == 0xff9226ul && read_trace[2] == 0xff9227ul && read_trace[3] == 0x01807ful && read_trace[4] == 0x01807ful
           && read_trace[5] == 0x01807ful);
    assert(operating_profile_timer_event_count == 4u && operating_profile_timer_events[2] == 3u && operating_profile_timer_events[3] == 1u);

    clear_memory(0u);
    reset_operating_profile_timer_observer();
    firmware_memory[0x0e4fu] = 0x30u;
    firmware_memory[0xff922au] = 0xffu;
    firmware_memory[0xff922bu] = 0xffu;
    firmware_memory[0x1807fu] = 0x08u;
    operating_profile_timer_clear_port_after = 1u;
    WriteScaledOperatingProfileWordViaSfr8B8D(0u);
    assert(sfr_memory[0x8du] == 0xffu && sfr_memory[0x8bu] == 0xffu);
    assert(operating_profile_timer_overflow_reads == 1u);
    assert(read_count == 5u && read_trace[3] == 0x01807ful && read_trace[4] == 0x01807ful);
    assert(operating_profile_timer_event_count == 4u);
}

