static void assert_operating_response_case(u8 media_state, u8 selector_bit, fw_addr_t code_address, u8 operating_code, fw_addr_t table_base, u8 delay, u8 bit_0044)
{
    u8 profile_index = MapOperatingCodeToProfileIndex(operating_code);
    fw_addr_t table_address = FirmwareAddressIncrement24(table_base, profile_index);
    u16 reload_value = (u16)(0xffffu - (u16)delay);
    unsigned event = 0u;

    clear_memory(0u);
    reset_operating_response_observers();
    firmware_memory[0x1008u] = media_state;
    firmware_memory[0x1055u] = 0x5au;
    firmware_memory[code_address] = operating_code;
    firmware_memory[table_address] = delay;
    firmware_memory[0xfc0du] = 0x33u;
    firmware_memory[0xfc15u] = 0x44u;
    firmware_memory[0xfad9u] = 0xffu;
    firmware_memory[0xfadau] = 0xffu;
    firmware_memory[0x0fd0u] = 0xf8u;
    bit_0031 = selector_bit;
    bit_0038 = 0u;
    bit_003a = 1u;
    operating_response_bit_0044 = bit_0044;

    ApplyControllerOperatingProfileAfterResponse();

    assert(read_count >= 10u && read_trace[0] == 0x001055ul && read_trace[1] == 0x001008ul && read_trace[2] == code_address && read_trace[3] == table_address);
    assert(write_count == 10u && write_trace[0] == 0x01807ful && write_values[0] == 0u && write_trace[1] == 0x01807ful && write_values[1] == 0x5au && write_trace[2] == 0x01807ful
           && write_values[2] == 0u && write_trace[3] == 0x01802eul && write_values[3] == 8u && write_trace[4] == 0x00fad9ul && write_values[4] == 0xffu && write_trace[5] == 0x00fadaul
           && write_values[5] == 0xfdu && write_trace[6] == 0x00121cul && write_values[6] == 10u && write_trace[7] == 0x000fd0ul && write_values[7] == 0xf9u && write_trace[8] == 0x000fd0ul
           && write_values[8] == 0xffu && write_trace[9] == 0x000fd0ul && write_values[9] == 0xefu);
    assert(sfr_write_count == 2u && sfr_write_trace[0] == 0x8du && sfr_write_values[0] == (u8)(reload_value >> 8) && sfr_write_trace[1] == 0x8bu && sfr_write_values[1] == (u8)reload_value);
    assert(operating_response_scale_count == 1u && operating_response_scale == 10u && operating_response_timer_reads == 3u);
    assert(operating_response_bit_0044_count == 1u && operating_response_d4_e2_count == 1u && operating_response_d4_e2_code == (bit_0044 == 0u ? 0x14u : 0xffu));
    if(media_state == 1u)
        assert(operating_response_parameter_count == 1u && operating_response_parameters[0] == 0xe764u);
    else
        assert(operating_response_parameter_count == 2u && operating_response_parameters[0] == 0xfa33u && operating_response_parameters[1] == 0xe764u);
    assert(bit_0038 == 1u && bit_003a == 0u && firmware_memory[0xfad9u] == 0xffu && firmware_memory[0xfadau] == 0xfdu && firmware_memory[0x121cu] == 10u && firmware_memory[0x0fd0u] == 0xefu);

    assert(operating_response_events[event++] == 1u);
    assert(operating_response_events[event++] == 2u);
    assert(operating_response_events[event++] == 3u);
    assert(operating_response_events[event++] == 4u);
    assert(operating_response_events[event++] == 4u);
    assert(operating_response_events[event++] == 4u);
    assert(operating_response_events[event++] == 5u);
    assert(operating_response_events[event++] == 2u);
    if(media_state != 1u)
        assert(operating_response_events[event++] == 6u);
    assert(operating_response_events[event++] == 7u);
    assert(operating_response_events[event++] == 8u);
    assert(operating_response_events[event++] == 6u);
    assert(operating_response_events[event++] == 9u);
    assert(operating_response_events[event++] == 10u);
    assert(operating_response_event_count == event);
}

static void test_apply_controller_operating_profile_after_response(void)
{
    assert_operating_response_case(1u, 0u, 0x000e51ul, 0x14u, 0xff91deul, 0x21u, 0u);
    assert_operating_response_case(1u, 1u, 0x000e51ul, 0x20u, 0xff91ebul, 0x43u, 1u);
    assert_operating_response_case(0u, 0u, 0x000e4ful, 0x08u, 0xff91aaul, 0x65u, 0u);
    assert_operating_response_case(2u, 1u, 0x000e4ful, 0x30u, 0xff91b7ul, 0x87u, 1u);
}

