static void test_select_raw_sector_capture_mode_and_length(void)
{
    static const struct
    {
        u8 track_code;
        u8 capture_mode;
        u16 transfer_length;
        u8 q_type;
    } track_cases[] = {
        { 0x00u, 0xc2u, 0x0930u, 0u  },
        { 0x01u, 0xc2u, 0x0930u, 0u  },
        { 0x10u, 0xc2u, 0x0800u, 8u  },
        { 0x11u, 0xc2u, 0x0930u, 8u  },
        { 0x12u, 0xc2u, 0x0800u, 8u  },
        { 0x13u, 0xc2u, 0x0930u, 8u  },
        { 0x20u, 0xc3u, 0x0920u, 13u },
        { 0x21u, 0xc3u, 0x0930u, 13u },
        { 0x22u, 0xc3u, 0x0920u, 13u },
        { 0x23u, 0xc3u, 0x0930u, 13u },
        { 0x24u, 0xc3u, 0x0914u, 13u },
        { 0x30u, 0xceu, 0x0920u, 9u  },
        { 0x31u, 0xceu, 0x0930u, 9u  },
        { 0x32u, 0xceu, 0x0920u, 9u  },
        { 0x33u, 0xceu, 0x0930u, 9u  },
        { 0x34u, 0xceu, 0x0930u, 9u  }
    };
    u8 capture_mode;
    u16 transfer_length;
    unsigned index;

    clear_memory(0u);
    capture_mode = 0xa5u;
    transfer_length = 0x5a5au;
    firmware_memory[0x2bc139u] = 0x40u;
    SelectRawSectorCaptureModeAndLength(&transfer_length, &capture_mode, 7u);
    assert(capture_mode == 0xc2u && transfer_length == 0x0930u);

    clear_memory(0u);
    capture_mode = 0xa5u;
    transfer_length = 0x5a5au;
    firmware_memory[0x2bc119u] = 2u;
    firmware_memory[0x2bc125u] = 0u;
    SelectRawSectorCaptureModeAndLength(&transfer_length, &capture_mode, 8u);
    assert(capture_mode == 0xcbu && transfer_length == 0x0930u);

    clear_memory(0u);
    capture_mode = 0xa5u;
    transfer_length = 0x5a5au;
    firmware_memory[0x1285u] = 9u;
    SelectRawSectorCaptureModeAndLength(&transfer_length, &capture_mode, 10u);
    assert(capture_mode == 0xceu && transfer_length == 0x0930u);

    clear_memory(0u);
    capture_mode = 0xa5u;
    transfer_length = 0x5a5au;
    SelectRawSectorCaptureModeAndLength(&transfer_length, &capture_mode, 5u);
    assert(capture_mode == 0xcbu && transfer_length == 0x0930u);

    clear_memory(0u);
    capture_mode = 0xa5u;
    transfer_length = 0x5a5au;
    firmware_memory[0x0c48u] = 0x55u;
    SelectRawSectorCaptureModeAndLength(&transfer_length, &capture_mode, 4u);
    assert(capture_mode == 0xa5u && transfer_length == 0x5a5au);

    for(index = 0u; index < sizeof(track_cases) / sizeof(track_cases[0]); index++)
    {
        clear_memory(0u);
        capture_mode = 0xa5u;
        transfer_length = 0x5a5au;
        firmware_memory[0x1283u] = 2u;
        set_memory_big_endian_u16(0x149bu, 2u);
        set_memory_big_endian_u16(0x149du, 2u);
        firmware_memory[0xb4d5u] = 1u;
        firmware_memory[0xb4d8u] = track_cases[index].track_code;
        firmware_memory[0x1285u] = 0x55u;
        SelectRawSectorCaptureModeAndLength(&transfer_length, &capture_mode, 4u);
        assert(capture_mode == track_cases[index].capture_mode && transfer_length == track_cases[index].transfer_length && firmware_memory[0x1285u] == track_cases[index].q_type);
        if(track_cases[index].q_type == 13u)
            assert(firmware_memory[0x0c73u] == 0x20u);
    }

    clear_memory(0u);
    capture_mode = 0xa5u;
    transfer_length = 0x5a5au;
    firmware_memory[0x1283u] = 2u;
    set_memory_big_endian_u16(0x149bu, 2u);
    set_memory_big_endian_u16(0x149du, 1u);
    firmware_memory[0xb4c5u] = 0u;
    firmware_memory[0xb4bdu] = 1u;
    firmware_memory[0xb4c0u] = 0x24u;
    SelectRawSectorCaptureModeAndLength(&transfer_length, &capture_mode, 4u);
    assert(capture_mode == 0xc3u && transfer_length == 0x0914u && firmware_memory[0x1285u] == 13u);

    clear_memory(0u);
    capture_mode = 0xa5u;
    transfer_length = 0x5a5au;
    firmware_memory[0x1283u] = 2u;
    set_memory_big_endian_u16(0x149bu, 2u);
    set_memory_big_endian_u16(0x149du, 2u);
    firmware_memory[0xb4d5u] = 1u;
    SelectRawSectorCaptureModeAndLength(&transfer_length, &capture_mode, 10u);
    assert(capture_mode == 0xc2u && transfer_length == 0x0800u && firmware_memory[0x1285u] == 8u && firmware_memory[0x0c73u] == 0u);

    clear_memory(0u);
    capture_mode = 0xa5u;
    transfer_length = 0x5a5au;
    firmware_memory[0x1283u] = 2u;
    firmware_memory[0x1285u] = 0x41u;
    set_memory_big_endian_u16(0x149bu, 2u);
    set_memory_big_endian_u16(0x149du, 2u);
    firmware_memory[0xb4d5u] = 1u;
    firmware_memory[0xb4d8u] = 0u;
    SelectRawSectorCaptureModeAndLength(&transfer_length, &capture_mode, 4u);
    assert(firmware_memory[0x1285u] == 0x41u);
}

