static void test_wait_for_raw_read_producer_capacity_and_check_status(void)
{
    unsigned index;

    clear_memory(0u);
    reset_producer_capacity_wait_observers();
    firmware_memory[0x1555u] = 1u;
    assert(WaitForRawReadProducerCapacityAndCheckStatus() == 1u);
    assert(producer_capacity_event_count == 0u);

    clear_memory(0u);
    reset_producer_capacity_wait_observers();
    firmware_memory[0x88b7u] = 1u;
    set_memory_big_endian_u16(0x1296u, 0x0010u);
    producer_capacity_should_wait_results[0] = 2u;
    assert(WaitForRawReadProducerCapacityAndCheckStatus() == 1u);
    assert(producer_capacity_event_count == 3u && producer_capacity_events[0] == 2u && producer_capacity_events[1] == 3u && producer_capacity_events[2] == 1u);

    clear_memory(0u);
    reset_producer_capacity_wait_observers();
    producer_capacity_should_wait_results[0] = 1u;
    firmware_memory[0x127du] = 1u;
    firmware_memory[0xfba0u] = 1u;
    firmware_memory[0x1281u] = 3u;
    firmware_memory[0x1283u] = 2u;
    bit_0028 = 1u;
    assert(WaitForRawReadProducerCapacityAndCheckStatus() == 0u);
    assert(producer_capacity_latch_count == 1u && producer_capacity_report_count == 0u && producer_capacity_clear_bit28_count == 0u);

    clear_memory(0u);
    reset_producer_capacity_wait_observers();
    producer_capacity_should_wait_results[0] = 1u;
    firmware_memory[0xfba0u] = 1u;
    bit_0028 = 1u;
    assert(WaitForRawReadProducerCapacityAndCheckStatus() == 0u);
    assert(producer_capacity_report_count == 1u && producer_capacity_report_code == 1u && producer_capacity_clear_bit28_count == 1u && bit_0028 == 0u);

    clear_memory(0u);
    reset_producer_capacity_wait_observers();
    producer_capacity_should_wait_results[0] = 1u;
    producer_capacity_restart_results[0] = 0u;
    assert(WaitForRawReadProducerCapacityAndCheckStatus() == 0u);
    assert(producer_capacity_restart_index == 1u && producer_capacity_report_count == 0u);

    clear_memory(0u);
    reset_producer_capacity_wait_observers();
    producer_capacity_should_wait_results[0] = 1u;
    producer_capacity_should_wait_results[1] = 0u;
    producer_capacity_restart_results[0] = 2u;
    firmware_memory[0xfba0u] = 1u;
    set_memory_big_endian_u16(0x1292u, 1u);
    bit_0031 = 1u;
    assert(WaitForRawReadProducerCapacityAndCheckStatus() == 1u);
    assert(producer_capacity_restart_index == 1u && firmware_memory[0x127du] == 0u && firmware_memory[0x128cu] == 1u);

    clear_memory(0u);
    reset_producer_capacity_wait_observers();
    for(index = 0u; index < 4u; index++)
    {
        producer_capacity_should_wait_results[index] = 1u;
        producer_capacity_restart_results[index] = 1u;
    }
    firmware_memory[0xfba0u] = 1u;
    set_memory_big_endian_u16(0x1292u, 1u);
    assert(WaitForRawReadProducerCapacityAndCheckStatus() == 0u);
    assert(producer_capacity_restart_index == 3u && producer_capacity_report_count == 1u && producer_capacity_report_code == 1u);

    clear_memory(0u);
    reset_producer_capacity_wait_observers();
    producer_capacity_should_wait_results[0] = 1u;
    firmware_memory[0xfb9au] = 1u;
    producer_capacity_yield_clear_fb9a_after = 2u;
    assert(WaitForRawReadProducerCapacityAndCheckStatus() == 0u);
    assert(producer_capacity_service_count == 2u && producer_capacity_yield_count == 2u && producer_capacity_sense_count == 1u);

    clear_memory(0u);
    reset_producer_capacity_wait_observers();
    producer_capacity_should_wait_results[0] = 1u;
    firmware_memory[0xfb9au] = 1u;
    firmware_memory[0xfba0u] = 1u;
    firmware_memory[0x1281u] = 1u;
    firmware_memory[0x1282u] = 1u;
    producer_capacity_yield_clear_fb9a_after = 2u;
    assert(WaitForRawReadProducerCapacityAndCheckStatus() == 0u);
    assert(producer_capacity_latch_count == 1u && producer_capacity_sense_count == 0u);
}

