static void test_acquire_fixed_raw_read_frame_prefix_window(void)
{
    unsigned index;

    clear_memory(0u);
    reset_fixed_raw_prefix_observers();
    fixed_raw_prefix_resume_address = 0x1000ul;
    assert(AcquireFixedRawReadFramePrefixWindow(3u, 4u) == 1u);
    assert(fixed_raw_prefix_event_count == 2u && fixed_raw_prefix_events[0] == 1u && fixed_raw_prefix_events[1] == 2u && fixed_raw_prefix_wait_count == 0u);

    clear_memory(0u);
    reset_fixed_raw_prefix_observers();
    fixed_raw_prefix_resume_address = 0x2000ul;
    fixed_raw_prefix_wait_results[0] = 0u;
    assert(AcquireFixedRawReadFramePrefixWindow(2u, 4u) == 0u);
    assert(fixed_raw_prefix_event_count == 4u && fixed_raw_prefix_events[0] == 1u && fixed_raw_prefix_events[1] == 2u && fixed_raw_prefix_events[2] == 3u && fixed_raw_prefix_events[3] == 13u
           && fixed_raw_prefix_failure_count == 1u && fixed_raw_prefix_failure_code == 0u);

    clear_memory(0u);
    reset_fixed_raw_prefix_observers();
    fixed_raw_prefix_resume_address = 0x3000ul;
    fixed_raw_prefix_wait_results[0] = 2u;
    fixed_raw_prefix_capture_results[0] = 0u;
    firmware_memory[0x142bu] = 0x1bu;
    set_memory_big_endian_u32(0x1598u, 0x12345678ul);
    assert(AcquireFixedRawReadFramePrefixWindow(2u, 4u) == 0u);
    assert(fixed_raw_prefix_copy_count == 1u && fixed_raw_prefix_copy_destinations[0] == 0x1428u && fixed_raw_prefix_copy_sources[0] == 0x1279u && fixed_raw_prefix_increment_count == 0u
           && fixed_raw_prefix_controller_count == 1u && fixed_raw_prefix_controller_sources[0] == 0x1428ul && firmware_memory[0x18028u] == 0x1bu);
    assert(fixed_raw_prefix_capture_count == 1u && fixed_raw_prefix_capture_addresses[0] == 0x3000ul && fixed_raw_prefix_capture_kinds[0] == 4u && fixed_raw_prefix_sense_count == 1u
           && fixed_raw_prefix_sense_key == 4u && fixed_raw_prefix_sense_code == 0x4400u && fixed_raw_prefix_information_count == 1u && fixed_raw_prefix_information == 0x12345678ul
           && fixed_raw_prefix_subheader_count == 0u);

    clear_memory(0u);
    reset_fixed_raw_prefix_observers();
    fixed_raw_prefix_resume_address = 0x4000ul;
    for(index = 0u; index < 5u; index++)
    {
        fixed_raw_prefix_wait_results[index] = (u8)(index + 1u);
        fixed_raw_prefix_ring_results[index] = 0x4000ul + (fw_addr_t)(index + 1u) * 0x930ul;
    }
    firmware_memory[0x1405u] = 1u;
    firmware_memory[0x142bu] = 3u;
    firmware_memory[0x88b5u] = 1u;
    firmware_memory[0xf848f7u] = 5u;
    firmware_memory[0xf848f8u] = 4u;
    firmware_memory[0xf848f9u] = 3u;
    firmware_memory[0xf848fau] = 2u;
    firmware_memory[0xf848fbu] = 1u;
    set_memory_big_endian_u32(0x1598u, 10ul);
    assert(AcquireFixedRawReadFramePrefixWindow(0u, 9u) == 1u);
    assert(fixed_raw_prefix_wait_count == 5u && fixed_raw_prefix_copy_count == 5u && fixed_raw_prefix_increment_count == 5u && fixed_raw_prefix_controller_count == 5u
           && fixed_raw_prefix_capture_count == 0u && fixed_raw_prefix_subheader_count == 5u && fixed_raw_prefix_q_count == 5u && fixed_raw_prefix_enqueue_count == 5u
           && fixed_raw_prefix_msf_count == 5u && fixed_raw_prefix_ring_count == 5u);
    for(index = 0u; index < 5u; index++)
    {
        assert(fixed_raw_prefix_copy_sources[index] == 0x1498u && fixed_raw_prefix_increment_addresses[index] == 0x1428u && fixed_raw_prefix_subheader_kinds[index] == 9u
               && fixed_raw_prefix_q_skip[index] == 0u && fixed_raw_prefix_q_reverse[index] == 1u && fixed_raw_prefix_msf_reverse[index] == 0u
               && fixed_raw_prefix_ring_inputs[index] == 0x4000ul + (fw_addr_t)index * 0x930ul);
    }
    assert(firmware_memory[0x18028u] == 0x23u && get_memory_big_endian_u32(0x1598u) == 15ul);

    clear_memory(0u);
    reset_fixed_raw_prefix_observers();
    fixed_raw_prefix_resume_address = 0x7000ul;
    fixed_raw_prefix_wait_results[0] = 2u;
    fixed_raw_prefix_wait_results[1] = 3u;
    fixed_raw_prefix_capture_results[0] = 2u;
    fixed_raw_prefix_capture_results[1] = 1u;
    fixed_raw_prefix_ring_results[0] = 0x7930ul;
    fixed_raw_prefix_ring_results[1] = 0x8260ul;
    firmware_memory[0x142bu] = 2u;
    firmware_memory[0x0c46u] = 2u;
    firmware_memory[0xf848fcu] = 7u;
    firmware_memory[0xf848fdu] = 6u;
    set_memory_big_endian_u32(0x1598u, 100ul);
    set_memory_big_endian_u32(0xdd3du, 50ul);
    set_memory_big_endian_u32(0x1459u, 8ul);
    set_memory_big_endian_u32(0x1455u, 8ul);
    assert(AcquireFixedRawReadFramePrefixWindow(1u, 6u) == 1u);
    assert(fixed_raw_prefix_copy_count == 2u && fixed_raw_prefix_copy_sources[0] == 0x1279u && fixed_raw_prefix_copy_sources[1] == 0x1279u && fixed_raw_prefix_increment_count == 0u);
    assert(fixed_raw_prefix_capture_count == 2u && fixed_raw_prefix_capture_addresses[0] == 0x7000ul && fixed_raw_prefix_capture_addresses[1] == 0x7930ul && fixed_raw_prefix_capture_kinds[0] == 6u
           && fixed_raw_prefix_capture_kinds[1] == 6u);
    assert(fixed_raw_prefix_q_reverse[0] == 1u && fixed_raw_prefix_q_reverse[1] == 1u && fixed_raw_prefix_msf_reverse[0] == 0u && fixed_raw_prefix_msf_reverse[1] == 0u
           && firmware_memory[0x18028u] == 0xc2u && get_memory_big_endian_u32(0x1598u) == 102ul);
    assert(fixed_raw_prefix_clear_completion_count == 1u && get_memory_big_endian_u32(0x14bcu) == 102ul);

    clear_memory(0u);
    reset_fixed_raw_prefix_observers();
    fixed_raw_prefix_resume_address = 0x9000ul;
    fixed_raw_prefix_wait_results[0] = 1u;
    fixed_raw_prefix_capture_results[0] = 1u;
    fixed_raw_prefix_ring_results[0] = 0x9930ul;
    firmware_memory[0x142bu] = 4u;
    set_memory_big_endian_u32(0x1598u, 50ul);
    set_memory_big_endian_u32(0xdd3du, 60ul);
    assert(AcquireFixedRawReadFramePrefixWindow(2u, 6u) == 1u);
    assert(fixed_raw_prefix_msf_count == 1u && fixed_raw_prefix_msf_reverse[0] == 1u && fixed_raw_prefix_q_reverse[0] == 1u && firmware_memory[0x18028u] == 4u);

    clear_memory(0u);
    reset_fixed_raw_prefix_observers();
    fixed_raw_prefix_resume_address = 0xa000ul;
    fixed_raw_prefix_wait_results[0] = 1u;
    fixed_raw_prefix_capture_results[0] = 1u;
    fixed_raw_prefix_ring_results[0] = 0xa930ul;
    firmware_memory[0x0c44u] = 1u;
    assert(AcquireFixedRawReadFramePrefixWindow(2u, 6u) == 1u);
    assert(fixed_raw_prefix_msf_reverse[0] == 1u);
}

static void reset_prefix_target_observers(void)
{
    memset(prefix_target_events, 0, sizeof(prefix_target_events));
    prefix_target_event_count = 0u;
    prefix_target_select_result = 0u;
    prefix_target_find_result = 0u;
    prefix_target_find_index = 0xffffu;
    prefix_target_find_forward = 0xffu;
    prefix_target_decode_result = 0u;
    prefix_target_decode_index = 0xffffu;
    memset(prefix_target_q_counts, 0, sizeof(prefix_target_q_counts));
    memset(prefix_target_q_reverse, 0xff, sizeof(prefix_target_q_reverse));
    memset(prefix_target_q_results, 1, sizeof(prefix_target_q_results));
    prefix_target_q_count = 0u;
    memset(prefix_target_fixed_modes, 0xff, sizeof(prefix_target_fixed_modes));
    memset(prefix_target_fixed_sources, 0xff, sizeof(prefix_target_fixed_sources));
    memset(prefix_target_fixed_results, 1, sizeof(prefix_target_fixed_results));
    prefix_target_fixed_count = 0u;
}

static void prepare_prefix_target_type2_record(u8 byte3)
{
    set_memory_big_endian_u16(0x149bu, 5u);
    firmware_memory[0xb4bdu + 4u * 8u] = 0u;
    firmware_memory[0xb4bdu + 3u * 8u] = 1u;
    firmware_memory[0xb4bfu + 3u * 8u] = byte3;
}

static void test_acquire_raw_read_prefix_at_current_pipeline_target(void)
{
    static const u8 type2_q_events[] = { 2u, 3u, 4u };
    static const u8 type2_fixed_events[] = { 2u, 3u, 5u, 5u };

    clear_memory(0xa5u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 4u;
    set_memory_big_endian_u32(0x1598u, 4500ul);
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_event_count == 0u);
    assert(firmware_memory[0x1284u] == 1u && firmware_memory[0x127eu] == 0u && firmware_memory[0x7000u] == 1u && firmware_memory[0x7001u] == 0u && firmware_memory[0x7002u] == 0u
           && firmware_memory[0x14b3u] == 0u);
    assert(get_memory_big_endian_u32(0x1598u) == 4500ul);

    clear_memory(0u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 0u;
    firmware_memory[0x0c48u] = 3u;
    firmware_memory[0x14b3u] = 0xa5u;
    set_memory_big_endian_u32(0x1598u, 0ul);
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_event_count == 2u && prefix_target_events[0] == 1u && prefix_target_events[1] == 4u);
    assert(prefix_target_q_count == 1u && prefix_target_q_counts[0] == 3l && prefix_target_q_reverse[0] == 0u);
    assert(firmware_memory[0x1285u] == 3u && get_memory_big_endian_u32(0x1598u) == 0xfffffffful && get_memory_big_endian_u32(0x8000u) == 0xfffffffful && firmware_memory[0x14b3u] == 0u);

    clear_memory(0u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 0u;
    firmware_memory[0x0c48u] = 2u;
    firmware_memory[0x14b3u] = 0xa5u;
    prefix_target_q_results[0] = 0u;
    set_memory_big_endian_u32(0x1598u, 100ul);
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_q_count == 1u && get_memory_big_endian_u32(0x1598u) == 100ul && get_memory_big_endian_u32(0x8000u) == 0ul && firmware_memory[0x14b3u] == 0xa5u);

    clear_memory(0u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 2u;
    prepare_prefix_target_type2_record(0u);
    prefix_target_decode_result = 2u;
    set_memory_big_endian_u32(0x1598u, 20ul);
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_event_count == sizeof(type2_q_events) && memcmp(prefix_target_events, type2_q_events, sizeof(type2_q_events)) == 0);
    assert(prefix_target_find_index == 3u && prefix_target_find_forward == 0u && prefix_target_decode_index == 3u && prefix_target_q_counts[0] == 3l && prefix_target_q_reverse[0] == 1u
           && firmware_memory[0x1285u] == 2u && get_memory_big_endian_u32(0x1598u) == 19ul);

    clear_memory(0u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 2u;
    prepare_prefix_target_type2_record(1u);
    prefix_target_decode_result = 1u;
    set_memory_big_endian_u32(0x1598u, 20ul);
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_q_reverse[0] == 0u);

    clear_memory(0u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 2u;
    prepare_prefix_target_type2_record(0u);
    firmware_memory[0x1273u] = 0xaau;
    firmware_memory[0x1272u] = 1u;
    firmware_memory[0x14b3u] = 0xa5u;
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_event_count == 1u && prefix_target_events[0] == 2u && prefix_target_q_count == 0u && prefix_target_fixed_count == 0u && firmware_memory[0x14b3u] == 0u);

    clear_memory(0u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 2u;
    prepare_prefix_target_type2_record(0u);
    prefix_target_decode_result = 8u;
    set_memory_big_endian_u32(0x1598u, 50ul);
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_event_count == sizeof(type2_fixed_events) && memcmp(prefix_target_events, type2_fixed_events, sizeof(type2_fixed_events)) == 0);
    assert(prefix_target_fixed_count == 2u && prefix_target_fixed_modes[0] == 1u && prefix_target_fixed_modes[1] == 2u && prefix_target_fixed_sources[0] == 6u && prefix_target_fixed_sources[1] == 6u
           && get_memory_big_endian_u32(0x1598u) == 49ul && get_memory_big_endian_u32(0x8000u) == 49ul);

    clear_memory(0u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 2u;
    prepare_prefix_target_type2_record(1u);
    prefix_target_decode_result = 8u;
    prefix_target_fixed_results[0] = 1u;
    prefix_target_fixed_results[1] = 0u;
    firmware_memory[0x14b3u] = 0xa5u;
    set_memory_big_endian_u32(0x1598u, 50ul);
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_fixed_count == 2u && prefix_target_fixed_sources[0] == 4u && prefix_target_fixed_sources[1] == 4u && get_memory_big_endian_u32(0x1598u) == 50ul
           && firmware_memory[0x14b3u] == 0xa5u);

    clear_memory(0u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 0u;
    firmware_memory[0x0c48u] = 8u;
    firmware_memory[0x0c46u] = 2u;
    firmware_memory[0x0c84u] = 0x40u;
    set_memory_big_endian_u32(0x14b8u, 0ul);
    set_memory_big_endian_u32(0x1598u, 70ul);
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_event_count == 2u && prefix_target_events[0] == 1u && prefix_target_events[1] == 5u && prefix_target_fixed_count == 1u && prefix_target_fixed_modes[0] == 2u
           && prefix_target_fixed_sources[0] == 4u && get_memory_big_endian_u32(0x1598u) == 70ul && firmware_memory[0x14b3u] == 0u);

    clear_memory(0u);
    reset_prefix_target_observers();
    firmware_memory[0x0c44u] = 0u;
    firmware_memory[0x0c48u] = 8u;
    set_memory_big_endian_u32(0x1598u, 70ul);
    AcquireRawReadPrefixAtCurrentPipelineTarget();
    assert(prefix_target_fixed_count == 2u && prefix_target_fixed_modes[0] == 1u && prefix_target_fixed_modes[1] == 2u && get_memory_big_endian_u32(0x1598u) == 69ul
           && get_memory_big_endian_u32(0x8000u) == 69ul);
}

static void test_try_release_raw_read_producer_capacity_wait(void)
{
    clear_memory(0u);
    bit_0036 = 1u;
    bit_0032 = 1u;
    firmware_memory[0x88b4ul] = 0u;
    assert(TryReleaseRawReadProducerCapacityWait() == 1u);
    assert(restart_read_acquisition_coroutine_count == 0u);
    assert(read_count == 1u && read_trace[0] == 0x88b4ul);
    assert(write_count == 1u && write_trace[0] == 0x88b4ul);

    clear_memory(0u);
    bit_0032 = 1u;
    set_memory_big_endian_u16(0x129cu, 100u);
    set_memory_big_endian_u16(0x1552u, 10u);
    set_memory_big_endian_u32(0x1455u, 20ul);
    set_memory_big_endian_u16(0x1292u, 70u);
    firmware_memory[0x88b4ul] = 1u;
    set_memory_big_endian_u16(0x0c41u, 69u);
    assert(TryReleaseRawReadProducerCapacityWait() == 0u);
    assert(restart_read_acquisition_coroutine_count == 1u);
    assert(firmware_memory[0x88b4ul] == 1u && write_count == 0u);
    assert(read_count == 15u);
    assert(read_trace[0] == 0x129cul && read_trace[2] == 0x1552ul);
    assert(read_trace[4] == 0x1455ul && read_trace[8] == 0x1292ul);
    assert(read_trace[10] == 0x88b4ul && read_trace[11] == 0x0c41ul);
    assert(read_trace[13] == 0x1292ul);

    clear_memory(0u);
    bit_0032 = 1u;
    set_memory_big_endian_u16(0x129cu, 100u);
    set_memory_big_endian_u16(0x1552u, 10u);
    set_memory_big_endian_u32(0x1455u, 20ul);
    set_memory_big_endian_u16(0x1292u, 69u);
    firmware_memory[0x88b4ul] = 1u;
    set_memory_big_endian_u16(0x0c41u, 69u);
    assert(TryReleaseRawReadProducerCapacityWait() == 1u);
    assert(restart_read_acquisition_coroutine_count == 0u);
    assert(firmware_memory[0x88b4ul] == 0u && write_count == 1u);

    clear_memory(0u);
    bit_0032 = 1u;
    set_memory_big_endian_u16(0x129cu, 5u);
    set_memory_big_endian_u16(0x1552u, 10u);
    set_memory_big_endian_u32(0x1455u, 65531ul);
    set_memory_big_endian_u16(0x1292u, 0u);
    firmware_memory[0x88b4ul] = 0u;
    assert(TryReleaseRawReadProducerCapacityWait() == 1u);
    assert(restart_read_acquisition_coroutine_count == 1u);

    clear_memory(0u);
    bit_0032 = 1u;
    set_memory_big_endian_u16(0x129cu, 5u);
    set_memory_big_endian_u16(0x1552u, 10u);
    set_memory_big_endian_u32(0x1455u, 65532ul);
    set_memory_big_endian_u16(0x1292u, 0xffffu);
    firmware_memory[0x88b4ul] = 0u;
    assert(TryReleaseRawReadProducerCapacityWait() == 1u);
    assert(restart_read_acquisition_coroutine_count == 0u);
}

static void test_acquire_disc_position_at_target_with_retry_budget(void)
{
    clear_memory(0u);
    acquire_disc_position_result_count = acquire_disc_position_call_count = 0u;
    reset_drive_calibration_result_count = reset_drive_calibration_call_count = 0u;
    assert(AcquireDiscPositionAtTargetWithRetryBudget(12345l) == 0u);
    assert(read_count == 1u && read_trace[0] == 0x1203ul);
    assert(write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1203ul] = 0xffu;
    acquire_disc_position_result_count = acquire_disc_position_call_count = 0u;
    reset_drive_calibration_result_count = reset_drive_calibration_call_count = 0u;
    assert(AcquireDiscPositionAtTargetWithRetryBudget(12345l) == 0u);
    assert(read_count == 1u && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1203ul] = 1u;
    acquire_disc_position_results[0] = 1u;
    acquire_disc_position_result_count = 1u;
    acquire_disc_position_call_count = 0u;
    reset_drive_calibration_result_count = reset_drive_calibration_call_count = 0u;
    assert(AcquireDiscPositionAtTargetWithRetryBudget((s32)0x89abcdeful) == 1u);
    assert(get_memory_big_endian_u32(0x0e3bu) == 0x89abcdeful);
    assert(firmware_memory[0x0ed6ul] == 1u);
    assert(write_count == 5u && write_trace[0] == 0x0e3bul && write_trace[4] == 0x0ed6ul);
    assert(acquire_disc_position_call_count == 1u);
    assert(reset_drive_calibration_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1203ul] = 1u;
    acquire_disc_position_results[0] = 0u;
    acquire_disc_position_result_count = 1u;
    acquire_disc_position_call_count = 0u;
    reset_drive_calibration_results[0] = 0u;
    reset_drive_calibration_result_count = 1u;
    reset_drive_calibration_call_count = 0u;
    assert(AcquireDiscPositionAtTargetWithRetryBudget(-1l) == 0u);
    assert(acquire_disc_position_call_count == 1u);
    assert(reset_drive_calibration_call_count == 1u);

    clear_memory(0u);
    firmware_memory[0x1203ul] = 1u;
    acquire_disc_position_results[0] = 0u;
    acquire_disc_position_results[1] = 1u;
    acquire_disc_position_result_count = 2u;
    acquire_disc_position_call_count = 0u;
    reset_drive_calibration_results[0] = 1u;
    reset_drive_calibration_result_count = 1u;
    reset_drive_calibration_call_count = 0u;
    assert(AcquireDiscPositionAtTargetWithRetryBudget(0x10203040l) == 1u);
    assert(acquire_disc_position_call_count == 2u);
    assert(reset_drive_calibration_call_count == 1u);
    assert(write_count == 10u);
    assert(read_count == 2u && read_trace[0] == 0x1203ul && read_trace[1] == 0x1203ul);
}

