static fw_addr_t indexed_state0f_reference_address(unsigned index)
{
    if(index < 44u)
        return 0x002b800bul + index;
    if(index < 54u)
        return 0x002bb045ul + (index - 44u);
    return 0x0000dd93ul + (index - 54u);
}

static void initialize_indexed_state0f_reference_payloads(void)
{
    unsigned index;

    for(index = 0u; index != 73u; ++index)
    {
        u8 value = (u8)(0x55u + index * 37u);

        firmware_memory[0xf894e3ul + index] = value;
        firmware_memory[indexed_state0f_reference_address(index)] = value;
    }
}

static void test_validate_indexed_state0f_reference_payloads(void)
{
    unsigned mismatch_index;
    unsigned index;

    clear_memory(0u);
    initialize_indexed_state0f_reference_payloads();
    assert(ValidateIndexedState0FReferencePayloads() == 1u);
    assert(read_count == 146u && write_count == 0u);
    for(index = 0u; index != 73u; ++index)
    {
        assert(read_trace[index * 2u] == 0x00f894e3ul + index);
        assert(read_trace[index * 2u + 1u] == indexed_state0f_reference_address(index));
    }

    for(mismatch_index = 0u; mismatch_index != 73u; ++mismatch_index)
    {
        clear_memory(0u);
        initialize_indexed_state0f_reference_payloads();
        firmware_memory[indexed_state0f_reference_address(mismatch_index)] ^= 0x80u;
        assert(ValidateIndexedState0FReferencePayloads() == 0u);
        assert(read_count == (mismatch_index + 1u) * 2u && write_count == 0u);
        for(index = 0u; index <= mismatch_index; ++index)
        {
            assert(read_trace[index * 2u] == 0x00f894e3ul + index);
            assert(read_trace[index * 2u + 1u] == indexed_state0f_reference_address(index));
        }
    }
}

