static void test_copy_controller_buffer_page_to_upper_banked_region(void)
{
    static const struct
    {
        u8 bank_index;
        u8 page_index;
        u8 write_marker;
    } cases[] = {
        { 0u, 0u, 0u    },
        { 1u, 3u, 1u    },
        { 7u, 7u, 0xffu }
    };
    unsigned case_index;

    for(case_index = 0u; case_index != sizeof(cases) / sizeof(cases[0]); ++case_index)
    {
        fw_addr_t source = 0x002ba62ful;
        fw_addr_t destination = 0x00104009ul + ((fw_addr_t)cases[case_index].bank_index << 14) + ((fw_addr_t)cases[case_index].page_index << 11);
        unsigned byte_index;

        clear_memory(0xa5u);
        for(byte_index = 0u; byte_index != 0x800u; ++byte_index)
            firmware_memory[source + byte_index] = (u8)(byte_index * 37u + 11u);
        firmware_memory[destination + 0x800u] = 0x6cu;
        read_count = write_count = 0u;

        CopyControllerBuffer512BytePageToUpperBankedRegion(source, cases[case_index].bank_index, cases[case_index].page_index, cases[case_index].write_marker);

        assert(read_count == 0x800u);
        assert(write_count == (cases[case_index].write_marker == 0u ? 0x800u : 0x801u));
        assert(firmware_memory[source] == (cases[case_index].write_marker == 0u ? 11u : 0x4du));
        assert(memcmp(&firmware_memory[destination], &firmware_memory[source], 0x800u) == 0);
        assert(firmware_memory[destination + 0x800u] == 0x6cu);
    }
}

static void test_copy_controller_record_workspace_page_from_banked_region(void)
{
    static const struct
    {
        u8 bank_index;
        u8 page_index;
        u32 inherited_dr12;
        u32 expected_bank_base;
    } cases[] = {
        { 0u,    0u,    0x00020000ul, 0x00000000ul },
        { 1u,    3u,    0x00020000ul, 0x00004000ul },
        { 2u,    7u,    0x00020000ul, 0x00008000ul },
        { 3u,    0xffu, 0x00020000ul, 0x0000c000ul },
        { 4u,    4u,    0x00020000ul, 0x00010000ul },
        { 5u,    5u,    0x00020000ul, 0x00014000ul },
        { 6u,    6u,    0x00020000ul, 0x00018000ul },
        { 7u,    7u,    0x00020000ul, 0x0001c000ul },
        { 8u,    2u,    0x00024000ul, 0x00024000ul },
        { 0xffu, 1u,    0x00124000ul, 0x00124000ul }
    };
    unsigned case_index;

    for(case_index = 0u; case_index != sizeof(cases) / sizeof(cases[0]); ++case_index)
    {
        fw_addr_t destination = 0x002ba62ful;
        u32 controller_offset = cases[case_index].expected_bank_base + 0x00094000ul + ((u32)cases[case_index].page_index << 11);
        fw_addr_t source = FirmwareAddressIncrement24(controller_offset, 0x00100000ul);
        unsigned byte_index;

        clear_memory(0xa5u);
        for(byte_index = 0u; byte_index != 0x800u; ++byte_index)
            firmware_memory[(source + byte_index) & 0xfffffful] = (u8)(byte_index * 53u + case_index);
        firmware_memory[destination + 0x800u] = 0x6cu;
        controller_record_page_copy_inherited_dr12 = cases[case_index].inherited_dr12;
        controller_record_page_copy_restored_dr12 = 0xfffffffful;
        read_count = write_count = 0u;

        CopyControllerRecordWorkspacePageToBankedRegion(cases[case_index].bank_index, cases[case_index].page_index);

        assert(read_count == 0x800u && write_count == 0x800u);
        assert(memcmp(&firmware_memory[destination], &firmware_memory[source], 0x800u) == 0);
        assert(firmware_memory[destination + 0x800u] == 0x6cu);
        assert(read_trace[0] == source);
        assert(write_trace[0] == destination);
        assert(read_trace[511] == source + 511u);
        assert(write_trace[511] == destination + 511u);
        assert(controller_record_page_copy_restored_dr12 == cases[case_index].inherited_dr12);
    }
}

static void test_raw_read_host_transfer_descriptor_completion(void)
{
    static const struct
    {
        u8 equal_positions;
        u8 status_1467;
        u8 status_1466;
        u8 status_1468;
        u8 expected_helper_count;
        u8 expected_helpers[4];
    } cases[] = {
        { 1u, 0u,    0u, 0u, 4u, { 0u, 1u, 2u, 3u } },
        { 1u, 0x80u, 0u, 0u, 1u, { 3u, 0u, 0u, 0u } },
        { 0u, 0u,    0u, 0u, 1u, { 3u, 0u, 0u, 0u } },
        { 0u, 0u,    0u, 1u, 0u, { 0u, 0u, 0u, 0u } }
    };
    unsigned case_index;

    for(case_index = 0u; case_index != sizeof(cases) / sizeof(cases[0]); ++case_index)
    {
        static const fw_addr_t common_reads[] = { 0x4022ul, 0x4023ul, 0x1298ul, 0x1299ul, 0x129aul, 0x129bul, 0x2202ul, 0x2203ul, 0x3000ul, 0x3001ul, 0x2206ul, 0x2207ul, 0x1238ul, 0x1239ul };
        unsigned index;

        clear_memory(0xa5u);
        raw_descriptor_completion_inherited_b = 0x40u;
        raw_descriptor_completion_inherited_wr2 = 0x2200u;
        raw_descriptor_completion_inherited_dr4 = 0x12342200ul;
        set_memory_big_endian_u16(0x4022u, 0x5000u);
        set_memory_big_endian_u16(0x1298u, 3u);
        set_memory_big_endian_u16(0x129au, 0x00ffu);
        set_memory_big_endian_u16(0x2202u, 0x3000u);
        set_memory_big_endian_u16(0x3000u, cases[case_index].equal_positions != 0u ? 0x1234u : 0x5678u);
        set_memory_big_endian_u16(0x2206u, 0xabcdu);
        set_memory_big_endian_u16(0x1238u, 0xef01u);
        firmware_memory[0x1467u] = cases[case_index].status_1467;
        firmware_memory[0x1466u] = cases[case_index].status_1466;
        firmware_memory[0x1468u] = cases[case_index].status_1468;
        raw_descriptor_completion_capture_count = 0u;
        raw_descriptor_completion_helper_count = 0u;
        read_count = write_count = 0u;

        HandleRawReadHostTransferDescriptorCompletion();

        assert(raw_descriptor_completion_capture_count == 3u);
        assert(raw_descriptor_completion_capture_events[0] == 0u && raw_descriptor_completion_capture_events[1] == 1u && raw_descriptor_completion_capture_events[2] == 2u);
        assert(raw_descriptor_completion_helper_count == cases[case_index].expected_helper_count);
        assert(memcmp(raw_descriptor_completion_helper_events, cases[case_index].expected_helpers, cases[case_index].expected_helper_count) == 0);
        assert(write_count == 4u && write_trace[0] == 0x18047ul && write_values[0] == 0x14u && write_trace[1] == 0x1298ul && write_values[1] == 0u && write_trace[2] == 0x1299ul
               && write_values[2] == 3u && write_trace[3] == 0x500dul && write_values[3] == 0u);
        assert(get_memory_big_endian_u16(0x1298u) == 3u && firmware_memory[0x500du] == 0u);
        assert(read_count == (cases[case_index].equal_positions != 0u ? 17u : 15u));
        for(index = 0u; index != sizeof(common_reads) / sizeof(common_reads[0]); ++index)
            assert(read_trace[index] == common_reads[index]);
        if(cases[case_index].equal_positions != 0u)
            assert(read_trace[14] == 0x1467ul && read_trace[15] == 0x1466ul && read_trace[16] == 0x1468ul);
        else
            assert(read_trace[14] == 0x1468ul);
    }
}

