static void test_process_media_coroutine_state0(void)
{
    static const u8 states[] = { 1u, 2u, 3u, 3u, 3u, 4u, 1u };
    static const u8 state_1008[] = { 1u, 0u, 1u, 1u, 1u, 1u, 1u };
    static const u8 state_f553[] = { 0xffu, 0xffu, 0u, 0u, 0u, 0xffu, 0xffu };
    static const u8 state_1132[] = { 0u, 0u, 0x40u, 0u, 0u, 0u, 0u };
    static const u8 state_12be[] = { 0u, 0u, 0u, 4u, 0u, 0u, 0u };
    static const u8 state_c89[] = { 0u, 0u, 0u, 0u, 0u, 0u, 1u };
    static const u8 expected_flag4[] = { 1u, 0u, 0u, 0u, 1u, 0u, 0u };
    unsigned index;

    clear_memory(0u);
    reset_media_state0_observers(1u);
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x0e3fu] = 1u;
    firmware_memory[0x0fafu] = 1u;
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0xf553u] = 0xffu;
    firmware_memory[0xfbecu] = 1u;
    firmware_memory[0x1304u] = 0u;
    ProcessMediaCoroutineState0();
    assert(media_state0_event_count == 7u && memcmp(media_state0_events, "PR7LH0C", 7u) == 0);
    assert(bit_0580 == 1u && bit_0581 == 0u && media_state0_p1_timer_pins_high == 1u && firmware_memory[0x15c3u] == 1u && firmware_memory[0x0e3fu] == 0u && media_state0_calibration_seen_flag4 == 1u
           && media_state0_calibration_seen_operating_code == 1u && (firmware_memory[0x1304u] & 0x10u) == 0u);

    clear_memory(0u);
    reset_media_state0_observers(0u);
    media_state0_release_after_yields = 2u;
    firmware_memory[0x0fafu] = 2u;
    firmware_memory[0x1008u] = 0u;
    firmware_memory[0xfbecu] = 0u;
    firmware_memory[0x0fb9u] = 0xffu;
    firmware_memory[0x1300u] = 8u;
    firmware_memory[0x0e40u] = 1u;
    ProcessMediaCoroutineState0();
    assert(media_state0_event_count == 13u && memcmp(media_state0_events, "R7LYSAYSAH0CY", 13u) == 0);
    assert(media_state0_yield_count == 3u && media_state0_calibration_seen_operating_code == 8u && firmware_memory[0x0fb9u] == 0xfdu && firmware_memory[0x1300u] == 0u && firmware_memory[0x0e40u] == 0u
           && firmware_memory[0x0e41u] == 7u && firmware_memory[0x0fafu] == 0u);

    for(index = 0u; index < sizeof(states); ++index)
    {
        clear_memory(0u);
        reset_media_state0_observers(1u);
        firmware_memory[0x0e3fu] = 1u;
        firmware_memory[0x0fafu] = states[index];
        firmware_memory[0x1008u] = state_1008[index];
        firmware_memory[0xf553u] = state_f553[index];
        firmware_memory[0x1132u] = state_1132[index];
        firmware_memory[0x12beu] = state_12be[index];
        firmware_memory[0x0c89u] = state_c89[index];
        firmware_memory[0x1304u] = 0u;
        firmware_memory[0xfbecu] = 1u;
        ProcessMediaCoroutineState0();
        assert(media_state0_calibration_seen_flag4 == expected_flag4[index] && (firmware_memory[0x1304u] & 0x10u) == 0u);
    }
}

