    assert(media_state3_service_event_count == 0u);
    assert(read_count == 3u && read_trace[0] == 0x0ff9ul && read_trace[1] == 0x1008ul && read_trace[2] == 0x1305ul);

    clear_memory(0u);
    firmware_memory[0x1008ul] = 1u;
    firmware_memory[0x1006ul] = 2u;
    media_state3_service_event_count = 0u;
    ServiceMediaState3ControllerAndQCapture();
