    clear_memory(0xa5u);
    reset_state3_q_capture_observers();
    firmware_memory[0x1006u] = 0u;
    firmware_memory[0xf79au] = 1u;
    state3_q_packet_results[0] = 0x11u;
    state3_q_packet_result_count = 1u;
    state3_q_calibration_result = 2u;
    AttemptMediaState3QCaptureAndControllerReinitialization();
    assert(state3_q_capture_event_count == 4u && state3_q_capture_events[0] == 1u && state3_q_capture_events[1] == 2u && state3_q_capture_events[2] == 5u && state3_q_capture_events[3] == 6u
           && firmware_memory[0x0fbcu] == 0xa5u && firmware_memory[0x0fafu] == 0xa5u);

    clear_memory(0xa5u);
    reset_state3_q_capture_observers();
    firmware_memory[0x1006u] = 0u;
    firmware_memory[0xf79au] = 1u;
    state3_q_packet_results[0] = 0u;
    state3_q_packet_result_count = 1u;
    state3_q_calibration_result = 0u;
    AttemptMediaState3QCaptureAndControllerReinitialization();
    assert(state3_q_reset_call_count == 1u && state3_q_calibration_call_count == 1u && firmware_memory[0x0fbcu] == 7u && firmware_memory[0x0fafu] == 0u);
    assert(write_count == 3u && write_trace[0] == 0x1217ul && write_trace[1] == 0x0fbcul && write_values[1] == 7u && write_trace[2] == 0x0faful && write_values[2] == 0u);

