static void test_initialize_media_state5_controller_path(void)
{
    static const u16 flag_values[] = { 0u, 1u, 2u, 3u, 0x1000u, 0x1001u, 0x1002u, 0x1003u };
    static const u8 media_states[] = { 0u, 2u, 3u };
    unsigned flag_index;
    unsigned state_index;
    unsigned event_index;

    for(flag_index = 0u; flag_index != sizeof(flag_values) / sizeof(flag_values[0]); ++flag_index)
    {
        for(state_index = 0u; state_index != sizeof(media_states) / sizeof(media_states[0]); ++state_index)
        {
            u16 flags = flag_values[flag_index];
            u8 state = media_states[state_index];
            u8 propagate_flag = (u8)((flag_index + state_index) & 1u);
            u8 expected_reduce = (u8)((flags & 3u) == 3u || state == 2u || (flags & 0x1000u) != 0u);

            clear_memory(0u);
            reset_media_state5_path_observers();
            set_memory_big_endian_u16(0xfad7u, flags);
            firmware_memory[0x1008u] = state;
            firmware_memory[0xf971u] = propagate_flag;
            firmware_memory[0x1305u] = 0x84u;
            media_state5_path_command_result = (u8)(0x40u + flag_index * 3u + state_index);

            InitializeMediaState5ControllerPath();

            assert(media_state5_path_event_count == 7u);
            for(event_index = 0u; event_index != 7u; ++event_index)
                assert(media_state5_path_events[event_index] == event_index + 1u);
            assert(media_state5_path_reduce_enabled == expected_reduce && media_state5_path_controller_enabled == 1u && media_state5_path_command_selector == 0x10u);
            assert(firmware_memory[0x0fcdu] == media_state5_path_command_result);
            assert(firmware_memory[0x1305u] == (propagate_flag != 0u ? 0xa4u : 0x84u));
            assert(write_count == (propagate_flag != 0u ? 2u : 1u));
            assert(write_trace[0] == 0x0fcdul && write_values[0] == media_state5_path_command_result);
            if(propagate_flag != 0u)
                assert(write_trace[1] == 0x1305ul && write_values[1] == 0xa4u);
        }
    }
}

