static void test_initialize_media_state5_position_and_controller_state(void)
{
    static const fw_addr_t ordinary_reads[] = { 0x00fba2ul, 0x00fba3ul, 0x00fba4ul, 0x00fba5ul, 0x00103aul, 0x001308ul, 0x000c46ul, 0x00103aul, 0x00103bul, 0x001008ul };
    static const fw_addr_t ordinary_writes[] = { 0x00103dul, 0x00103eul, 0x00103ful, 0x001040ul, 0x00103aul, 0x00103aul, 0x00103bul };
    unsigned index;

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0xfba2u] = 0x12u;
    firmware_memory[0xfba3u] = 0x34u;
    firmware_memory[0xfba4u] = 0x56u;
    firmware_memory[0xfba5u] = 0x78u;
    firmware_memory[0x103au] = 0x84u;
    firmware_memory[0x103bu] = 0xffu;
    InitializeMediaState5PositionAndControllerState();
    assert(media_state5_position_bit33_read_count == 1u);
    assert(read_count == sizeof(ordinary_reads) / sizeof(ordinary_reads[0]));
    for(index = 0u; index != read_count; ++index)
        assert(read_trace[index] == ordinary_reads[index]);
    assert(write_count == sizeof(ordinary_writes) / sizeof(ordinary_writes[0]));
    for(index = 0u; index != write_count; ++index)
        assert(write_trace[index] == ordinary_writes[index]);
    assert(firmware_memory[0x103du] == 0x12u && firmware_memory[0x103eu] == 0x34u && firmware_memory[0x103fu] == 0x56u && firmware_memory[0x1040u] == 0x78u);
    assert(firmware_memory[0x103au] == 0x81u && firmware_memory[0x103bu] == 0xbfu);
    assert(media_state5_update_event_count == 0u);

    clear_memory(0u);
    reset_media_state5_update_observers();
    bit_0033 = 1u;
    firmware_memory[0xfba2u] = 0xffu;
    firmware_memory[0xfba3u] = 0xffu;
    firmware_memory[0xfba4u] = 0xffu;
    firmware_memory[0xfba5u] = 0xfdu;
    InitializeMediaState5PositionAndControllerState();
    assert(firmware_memory[0x103du] == 0u && firmware_memory[0x103eu] == 0u && firmware_memory[0x103fu] == 0u && firmware_memory[0x1040u] == 1u);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x103au] = 0xffu;
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x130au] = 0xf6u;
    InitializeMediaState5PositionAndControllerState();
    assert(read_count == 12u && read_trace[6] == 0x00130aul && read_trace[7] == 0x00103aul);
    assert(write_count == 8u && write_trace[5] == 0x00103aul && write_values[5] == 0xfeu && firmware_memory[0x103au] == 0xfau);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x103au] = 0x05u;
    firmware_memory[0x0c46u] = 1u;
    InitializeMediaState5PositionAndControllerState();
    assert(read_count == 11u && read_trace[7] == 0x00103aul);
    assert(write_count == 8u && write_trace[5] == 0x00103aul && write_values[5] == 0x04u && firmware_memory[0x103au] == 0u);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x1008u] = 2u;
    firmware_memory[0x103au] = 0x44u;
    firmware_memory[0x103bu] = 0xffu;
    firmware_memory[0x103cu] = 0xaau;
    InitializeMediaState5PositionAndControllerState();
    assert(firmware_memory[0x103au] == 0x41u && firmware_memory[0x103bu] == 0xbbu && firmware_memory[0x103cu] == 0xa9u);
    assert(write_count == 9u && read_count == 12u);
    assert(write_trace[7] == 0x00103bul && write_values[7] == 0xbbu && write_trace[8] == 0x00103cul && write_values[8] == 0xa9u);
    assert(media_state5_update_event_count == 2u && media_state5_update_events[0] == 13u && media_state5_update_events[1] == 14u && media_state5_update_event_reads[0] == 12u
           && media_state5_update_event_writes[0] == 9u && media_state5_position_parameter_argument == 0u);
}

static void test_build_media_state5_adjacent_packed_bcd_msf_tuples(void)
{
    static const fw_addr_t expected_reads[] = { 0x000e51ul, 0x00103dul, 0x00103eul, 0x00103ful, 0x001040ul, 0x00103dul, 0x00103eul, 0x00103ful, 0x001040ul, 0x0010b6ul, 0x0010b7ul, 0x0010b8ul,
        0x0010baul, 0x0010bbul, 0x0010bcul };
    static const fw_addr_t expected_writes[] = { 0x0010b6ul, 0x0010b7ul, 0x0010b8ul, 0x0010baul, 0x0010bbul, 0x0010bcul };
    static const u8 expected_bcd_inputs[] = { 44u, 55u, 66u, 11u, 22u, 33u };
    unsigned index;

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x0e51u] = 12u;
    firmware_memory[0x1040u] = 1u;
    media_state5_tuple_mutate_target = 9u;
    BuildMediaState5AdjacentPackedBcdMsfTuples();
    assert(media_state5_position_bit33_read_count == 1u);
    assert(media_state5_tuple_convert_count == 2u && media_state5_tuple_convert_addresses[0] == 0x10bau && media_state5_tuple_convert_addresses[1] == 0x10b6u
           && media_state5_tuple_convert_positions[0] == -1l && media_state5_tuple_convert_positions[1] == 8l);
    assert(read_count == sizeof(expected_reads) / sizeof(expected_reads[0]));
    for(index = 0u; index != read_count; ++index)
        assert(read_trace[index] == expected_reads[index]);
    assert(write_count == sizeof(expected_writes) / sizeof(expected_writes[0]));
    for(index = 0u; index != write_count; ++index)
        assert(write_trace[index] == expected_writes[index]);
    assert(media_state5_tuple_bcd_count == 6u);
    for(index = 0u; index != 6u; ++index)
        assert(media_state5_tuple_bcd_inputs[index] == expected_bcd_inputs[index]);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x0e51u] = 13u;
    firmware_memory[0x1040u] = 1u;
    BuildMediaState5AdjacentPackedBcdMsfTuples();
    assert(media_state5_position_bit33_read_count == 0u && media_state5_tuple_convert_positions[0] == -2l && media_state5_tuple_convert_positions[1] == -1l);

    clear_memory(0u);
    reset_media_state5_update_observers();
    bit_0033 = 1u;
    firmware_memory[0x0e51u] = 0u;
    firmware_memory[0x1040u] = 1u;
    BuildMediaState5AdjacentPackedBcdMsfTuples();
    assert(media_state5_position_bit33_read_count == 1u && media_state5_tuple_convert_positions[0] == -2l && media_state5_tuple_convert_positions[1] == -1l);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x0e51u] = 0xffu;
    firmware_memory[0x1040u] = 4u;
    BuildMediaState5AdjacentPackedBcdMsfTuples();
    assert(media_state5_position_bit33_read_count == 0u && media_state5_tuple_convert_positions[0] == 1l && media_state5_tuple_convert_positions[1] == 2l);
}

