static void test_service_media_state5_controller_and_operating_updates(void)
{
    static const fw_addr_t full_path_reads[] = { 0x1008ul, 0x0fd0ul, 0xfb69ul, 0x0fd0ul, 0x0fd0ul, 0x0fd0ul, 0xfb9bul, 0x1008ul, 0x1008ul };
    unsigned index;

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x1008u] = 2u;
    firmware_memory[0x0fd0u] = 0x0fu;
    firmware_memory[0xfb69u] = 0u;
    firmware_memory[0xfb9bu] = 1u;
    ServiceMediaState5ControllerAndOperatingUpdates();
    assert(media_state5_update_event_count == 5u);
    assert(media_state5_update_events[0] == 1u && media_state5_update_events[1] == 2u && media_state5_update_events[2] == 3u && media_state5_update_events[3] == 4u
           && media_state5_update_events[4] == 7u);
    assert(media_state5_update_event_reads[0] == 2u && media_state5_update_event_reads[1] == 3u && media_state5_update_event_reads[2] == 3u && media_state5_update_event_reads[3] == 7u
           && media_state5_update_event_reads[4] == 9u);
    assert(media_state5_update_event_writes[0] == 0u && media_state5_update_event_writes[3] == 1u);
    assert(read_count == sizeof(full_path_reads) / sizeof(full_path_reads[0]));
    for(index = 0u; index != read_count; ++index)
        assert(read_trace[index] == full_path_reads[index]);
    assert(write_count == 1u && write_trace[0] == 0x0fd0ul && write_values[0] == 7u);
    assert(bit_003b == 1u && bit_0039 == 1u && bit_003a == 1u && bit_0036 == 1u);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0xfb69u] = 2u;
    firmware_memory[0x0fd0u] = 0u;
    firmware_memory[0x0e4fu] = 0xffu;
    firmware_memory[0xfa00u] = 0x11u;
    firmware_memory[0x1137u] = 0x22u;
    media_state5_update_recompute_mutation = 0x33u;
    media_state5_update_apply_mutation = 0x44u;
    ServiceMediaState5ControllerAndOperatingUpdates();
    assert(media_state5_update_event_count == 3u);
    assert(media_state5_update_events[0] == 3u && media_state5_update_events[1] == 5u && media_state5_update_events[2] == 6u);
    assert(media_state5_update_profile_coordinate == 0x33u && media_state5_update_profile_code == 0xffu);
    assert(firmware_memory[0xfa00u] == 0x44u);
    assert(write_count == 1u && write_trace[0] == 0xfa00ul && write_values[0] == 0x44u);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0xfb69u] = 2u;
    firmware_memory[0x0e4fu] = 0x34u;
    ServiceMediaState5ControllerAndOperatingUpdates();
    assert(media_state5_update_event_count == 1u && media_state5_update_events[0] == 3u);
    assert(read_count == 6u && read_trace[5] == 0x0e4ful);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0xfb69u] = 2u;
    firmware_memory[0x0e4fu] = 0xffu;
    firmware_memory[0xfa00u] = 0x5au;
    firmware_memory[0x1137u] = 0x5au;
    ServiceMediaState5ControllerAndOperatingUpdates();
    assert(media_state5_update_event_count == 1u && media_state5_update_events[0] == 3u);
    assert(write_count == 0u);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x1008u] = 0u;
    firmware_memory[0xfb69u] = 2u;
    ServiceMediaState5ControllerAndOperatingUpdates();
    assert(media_state5_update_event_count == 1u && media_state5_update_events[0] == 3u);
    assert(read_count == 6u && write_count == 0u);
}

