    assert(media_state5_update_events[0] == 6u && media_state5_update_events[1] == 8u && media_state5_update_events[2] == 10u);
    assert(media_state5_update_profile_coordinate == 2u && media_state5_update_profile_code == 0x34u);
    assert(read_target_eaeb_value == 0xabcdu && read_target_e8e9_value == 0x78u);
    assert(read_count == 9u && read_trace[3] == 0x0e43ul && read_trace[4] == 0x0e43ul);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x0e4fu] = 0x10u;
    firmware_memory[0x0e43u] = 0x13u;
