    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x0c46u] = 1u;
    firmware_memory[0xfab5u] = 0xbcu;
    ConfigureControllerForReadAcquisitionTarget(123l);
    assert(media_state5_update_event_count == 3u);
    assert(media_state5_update_events[0] == 9u && media_state5_update_events[1] == 8u && media_state5_update_events[2] == 10u);
    assert(read_target_bit_0044_count == 1u && read_target_d4e2_code == 0x14u && read_target_eaeb_value == 0u && read_target_e8e9_value == 0xbcu);

    clear_memory(0u);
    reset_media_state5_update_observers();
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x0c46u] = 1u;
    firmware_memory[0xfab5u] = 0xdeu;
