static void configure_raw_read_header_link(u32 descriptor_handle, u16 linked_address, u16 linked_window)
{
    u16 descriptor_address = (u16)descriptor_handle;

    firmware_memory[(u16)(descriptor_address + 2u)] = (u8)(linked_address >> 8);
    firmware_memory[(u16)(descriptor_address + 3u)] = (u8)linked_address;
    firmware_memory[linked_address] = (u8)(linked_window >> 8);
    firmware_memory[(u16)(linked_address + 1u)] = (u8)linked_window;
}

static void test_copy_and_normalize_raw_read_header_to_linked_buffer(void)
{
    static const u8 source_header[12] = { 0x41u, 0x12u, 0x34u, 0x56u, 0x78u, 0x09u, 0x10u, 0x11u, 0x22u, 0x33u, 0xabu, 0xcdu };
    static const u8 normalized_header[16] = { 0x41u, 12u, 34u, 56u, 78u, 9u, 10u, 11u, 22u, 33u, 0xabu, 0xcdu, 0u, 0x1au, 0xffu, 0xe0u };
    const u32 descriptor_handle = 0x00201234ul;
    const fw_addr_t source_address = 0x00301234ul;
    const fw_addr_t destination_address = 0x00501234ul;
    unsigned index;

    clear_memory(0u);
    memcpy(firmware_memory + source_address, source_header, sizeof(source_header));
    configure_raw_read_header_link(descriptor_handle, 0x2200u, 0x0040u);
    sfr_memory[0xa8u] = 0xd5u;
    sfr_memory[0xa9u] = 0xa6u;
    CopyAndNormalizeRawReadHeaderToLinkedBuffer(descriptor_handle, 0x1au);
    assert(raw_read_header_interrupt_violation_count == 0u);
    assert(raw_read_header_bcd_count == 9u);
    assert(raw_read_header_read_count == 16u);
    assert(raw_read_header_write_count == 16u);
    for(index = 0u; index < 12u; ++index)
        assert(raw_read_header_read_addresses[index] == source_address + index);
    assert(raw_read_header_read_addresses[12] == 0x1236u && raw_read_header_read_addresses[13] == 0x1237u && raw_read_header_read_addresses[14] == 0x2200u
           && raw_read_header_read_addresses[15] == 0x2201u);
    for(index = 0u; index < 16u; ++index)
    {
        assert(raw_read_header_write_addresses[index] == destination_address + index);
        assert(raw_read_header_write_values[index] == normalized_header[index]);
        assert(firmware_memory[destination_address + index] == normalized_header[index]);
    }
    assert(sfr_memory[0xa8u] == 0xd5u && sfr_memory[0xa9u] == 0xa6u);

    clear_memory(0u);
    memcpy(firmware_memory + source_address, source_header, sizeof(source_header));
    firmware_memory[source_address + 1u] = 0xaau;
    configure_raw_read_header_link(descriptor_handle, 0x2200u, 0x0040u);
    sfr_memory[0xa8u] = 0x80u;
    CopyAndNormalizeRawReadHeaderToLinkedBuffer(descriptor_handle, 0x55u);
    assert(raw_read_header_bcd_count == 8u);
    assert(firmware_memory[destination_address + 1u] == 0xaau);
    assert(firmware_memory[destination_address + 2u] == 34u);
    assert(firmware_memory[destination_address + 13u] == 0x55u);
    assert(sfr_memory[0xa8u] == 0x80u);

    clear_memory(0u);
    memcpy(firmware_memory + source_address, source_header, sizeof(source_header));
    configure_raw_read_header_link(descriptor_handle, 0x2200u, 0x0040u);
    bit_0013 = 1u;
    CopyAndNormalizeRawReadHeaderToLinkedBuffer(descriptor_handle, 0x1au);
    assert(raw_read_header_bcd_count == 0u);
    assert(memcmp(firmware_memory + destination_address, source_header, sizeof(source_header)) == 0);
    assert(raw_read_header_interrupt_violation_count == 0u);

    clear_memory(0u);
    memcpy(firmware_memory + source_address, source_header, sizeof(source_header));
    firmware_memory[source_address] = 0x42u;
    configure_raw_read_header_link(descriptor_handle, 0x2200u, 0x0040u);
    CopyAndNormalizeRawReadHeaderToLinkedBuffer(descriptor_handle, 0x1au);
    assert(raw_read_header_bcd_count == 0u);
    assert(firmware_memory[destination_address + 1u] == 0x12u);
}

static void test_execute_vendor_f3_indexed_drive_cycle_sequence(void)
{
    static const u8 expected_countdowns_for_maximum_one[7] = { 30u, 120u, 5u, 6u, 2u, 2u, 2u };
    unsigned index;

    clear_memory(0u);
    ExecuteVendorF3IndexedDriveCycleSequence(0u);
    assert(vendor_f3_cycle_port_count == 0u && vendor_f3_cycle_profile_count == 0u && vendor_f3_cycle_drive_count == 0u && write_count == 0u);

    clear_memory(0u);
    ExecuteVendorF3IndexedDriveCycleSequence(1u);
    assert(vendor_f3_cycle_port_count == 7u);
    for(index = 0u; index < 6u; ++index)
    {
        assert(vendor_f3_cycle_port_addresses[index] == 0x01849dul);
        assert(vendor_f3_cycle_port_values[index] == 0u);
    }
    assert(vendor_f3_cycle_port_addresses[6] == 0x01809aul && vendor_f3_cycle_port_values[6] == 0u);
    assert(vendor_f3_cycle_profile_count == 2u && vendor_f3_cycle_profile_enabled[0] == 0u && vendor_f3_cycle_profile_enabled[1] == 1u && vendor_f3_cycle_profile_values[0] == 0x0b54u
           && vendor_f3_cycle_profile_values[1] == 0x0b54u);
    assert(vendor_f3_cycle_drive_count == 2u && vendor_f3_cycle_drive_codes[0] == 3u && vendor_f3_cycle_drive_enabled[0] == 1u && vendor_f3_cycle_drive_codes[1] == 4u
           && vendor_f3_cycle_drive_enabled[1] == 0u);
    assert(vendor_f3_cycle_input_read_count == 1u && write_count == 7u);
    for(index = 0u; index < 7u; ++index)
    {
        assert(write_trace[index] == 0x001216ul);
        assert(write_values[index] == expected_countdowns_for_maximum_one[index]);
    }

    clear_memory(0u);
    ExecuteVendorF3IndexedDriveCycleSequence(10u);
    assert(vendor_f3_cycle_port_count == 26u);
    assert(vendor_f3_cycle_profile_count == 20u);
    assert(vendor_f3_cycle_drive_count == 4u);
    assert(vendor_f3_cycle_input_read_count == 2u);

    clear_memory(0u);
    ExecuteVendorF3IndexedDriveCycleSequence(0xffu);
    assert(vendor_f3_cycle_port_count == 540u);
    assert(vendor_f3_cycle_profile_count == 510u);
    assert(vendor_f3_cycle_drive_count == 52u);
    assert(vendor_f3_cycle_input_read_count == 26u);
    assert(write_count == 615u);
    assert(vendor_f3_cycle_port_addresses[539] == 0x01809aul);

    clear_memory(0u);
    vendor_f3_cycle_signal_after_read = 0u;
    ExecuteVendorF3IndexedDriveCycleSequence(1u);
    assert(vendor_f3_cycle_port_count == 8u);
    assert(vendor_f3_cycle_input_read_count == 122u);
    assert(vendor_f3_cycle_drive_count == 2u);
}

static void test_append_mode_sense_page_to_controller_buffer(void)
{
    static const u8 all_pages[11] = { 0x01u, 0x02u, 0x03u, 0x05u, 0x07u, 0x08u, 0x0du, 0x0eu, 0x1au, 0x1du, 0x2au };
    static const u8 all_page_lengths[11] = { 0x0cu, 0x10u, 0x08u, 0x34u, 0x08u, 0x0cu, 0x08u, 0x10u, 0x0cu, 0x0au, 0x40u };
    static const char all_page_events[35] = { 'L', 'S', 'C', 'L', 'S', 'C', 'L', 'S', 'C', 'L', 'S', 'C', 'L', 'S', 'C', 'L', 'S', 'C', 'L', 'S', 'C', 'L', 'S', 'C', 'L', 'S', 'A', 'C', 'L', 'S', 'C',
        'L', 'S', 'T', 'C' };
    u32 response_address;
    unsigned index;

    clear_memory(0u);
    response_address = AppendModeSensePageToControllerBuffer(0x12345670ul, 0x2au, 0u);
    assert(response_address == 0x123456b0ul);
    assert(mode_sense_page_event_count == 4u && memcmp(mode_sense_page_events, "LSTC", 4u) == 0);
    assert(mode_sense_page2a_refresh_count == 1u && mode_sense_page1a_refresh_count == 0u);
    assert(mode_sense_page_copy_sources[0] == 0x222a00ul && mode_sense_page_copy_destinations[0] == 0x12345670ul && mode_sense_page_copy_lengths[0] == 0x40ul);

    clear_memory(0u);
    response_address = AppendModeSensePageToControllerBuffer(0xfffffff0ul, 0x1au, 0u);
    assert(response_address == 0xfffffffcul);
    assert(mode_sense_page_event_count == 4u && memcmp(mode_sense_page_events, "LSAC", 4u) == 0);
    assert(mode_sense_page1a_refresh_count == 1u && mode_sense_page2a_refresh_count == 0u);

    clear_memory(0u);
    response_address = AppendModeSensePageToControllerBuffer(0x1000ul, 0x2au, 2u);
    assert(response_address == 0x1040ul);
    assert(mode_sense_page_event_count == 3u && memcmp(mode_sense_page_events, "LSC", 3u) == 0);
    assert(mode_sense_page1a_refresh_count == 0u && mode_sense_page2a_refresh_count == 0u);
    assert(mode_sense_page_select_controls[0] == 2u);

    clear_memory(0u);
    response_address = AppendModeSensePageToControllerBuffer(0x2000ul, 0x55u, 1u);
    assert(response_address == 0x2001ul);
    assert(mode_sense_page_copy_lengths[0] == 1ul);

    clear_memory(0u);
    response_address = AppendModeSensePageToControllerBuffer(0x4000ul, 0x3fu, 0u);
    assert(mode_sense_page_length_count == 11u && mode_sense_page_select_count == 11u && mode_sense_page_copy_count == 11u);
    assert(mode_sense_page_event_count == sizeof(all_page_events));
    assert(memcmp(mode_sense_page_events, all_page_events, sizeof(all_page_events)) == 0);
    assert(mode_sense_page1a_refresh_count == 1u && mode_sense_page2a_refresh_count == 1u);
    for(index = 0u; index < 11u; ++index)
    {
        assert(mode_sense_page_length_codes[index] == all_pages[index]);
        assert(mode_sense_page_select_codes[index] == all_pages[index]);
        assert(mode_sense_page_select_controls[index] == 0u);
        assert(mode_sense_page_copy_sources[index] == 0x220000ul + (fw_addr_t)all_pages[index] * 0x100ul);
        assert(mode_sense_page_copy_lengths[index] == all_page_lengths[index]);
        if(index != 0u)
            assert(mode_sense_page_copy_destinations[index] == mode_sense_page_copy_destinations[index - 1u] + mode_sense_page_copy_lengths[index - 1u]);
    }
    assert(mode_sense_page_copy_destinations[0] == 0x4000ul);
    assert(response_address == 0x40daul);
}

