static void test_compute_controller_word0255_target_from_calibration_byte(void)
{
    unsigned code;
    unsigned calibration;
    unsigned feedback;

    clear_memory(0u);
    for(code = 1u; code <= 4u; ++code)
    {
        firmware_memory[0x0e43ul] = (u8)code;
        for(calibration = 0u; calibration < 0xffu; ++calibration)
        {
            s16 initial = (s16)((u16)calibration - 0x80u);
            s16 step = (s16)(4u / code);

            firmware_memory[0xfac2ul] = (u8)calibration;
            for(feedback = 0u; feedback <= 0xffu; ++feedback)
            {
                s16 expected = initial;

                firmware_memory[0xf9a8ul] = (u8)feedback;
                if(expected <= (s16)feedback)
                {
                    expected = (s16)(expected + step);
                    if(expected >= (s16)feedback)
                        expected = (s16)feedback;
                }
                else
                {
                    expected = (s16)(expected - step);
                    if(expected <= (s16)feedback)
                        expected = (s16)feedback;
                }
                assert(ComputeControllerWord0255TargetFromCalibrationByte() == expected);
            }
        }
    }

    firmware_memory[0xfac2ul] = 0x21u;
    firmware_memory[0xf9a8ul] = 0xffu;
    firmware_memory[0x0e43ul] = 5u;
    assert(ComputeControllerWord0255TargetFromCalibrationByte() == -95);
    firmware_memory[0x0e43ul] = 0xffu;
    assert(ComputeControllerWord0255TargetFromCalibrationByte() == -95);

    firmware_memory[0xfac2ul] = 0xffu;
    firmware_memory[0x0e43ul] = 1u;
    assert(ComputeControllerWord0255TargetFromCalibrationByte() == (s16)0x8000u);
    firmware_memory[0x0e43ul] = 5u;
    assert(ComputeControllerWord0255TargetFromCalibrationByte() == (s16)0x8000u);

    firmware_memory[0xfac2ul] = 0x80u;
    firmware_memory[0xf9a8ul] = 2u;
    firmware_memory[0x0e43ul] = 1u;
    read_count = 0u;
    assert(ComputeControllerWord0255TargetFromCalibrationByte() == 2);
    assert(read_count == 8u);
    assert(read_trace[0] == 0xfac2ul && read_trace[1] == 0x0e43ul && read_trace[2] == 0xfac2ul && read_trace[3] == 0x0e43ul && read_trace[4] == 0xf9a8ul && read_trace[5] == 0xf9a8ul
           && read_trace[6] == 0xf9a8ul && read_trace[7] == 0xfac2ul);
}

