static void test_configure_controller_ports_and_parameters_for_operating_code(void)
{
    static const struct
    {
        u8 operating_code;
        u8 state_1008;
        u8 flags_103a;
        s32 frame_position;
        u8 port_806a;
        u16 operating_pair;
    } cases[] = {
        { 1u,  0u, 0u,    0,      0u, 0x1c00u },
        { 2u,  0u, 0u,    0,      0u, 0x1c10u },
        { 4u,  0u, 0u,    0,      0u, 0x1c24u },
        { 8u,  0u, 0u,    0,      0u, 0x2848u },
        { 10u, 1u, 0x40u, 0,      0u, 0x2058u },
        { 10u, 2u, 0x40u, 0,      3u, 0x2028u },
        { 12u, 0u, 0u,    0,      0u, 0x2058u },
        { 16u, 0u, 0u,    0,      0u, 0x346au },
        { 20u, 0u, 0u,    0,      4u, 0x3c8au },
        { 24u, 0u, 0u,    0,      4u, 0x488au },
        { 32u, 0u, 0u,    0,      5u, 0x548au },
        { 40u, 0u, 0u,    0,      5u, 0x648au },
        { 52u, 0u, 0u,    224999, 7u, 0x588au },
        { 52u, 0u, 0u,    225000, 7u, 0x589au }
    };
    unsigned index;

    for(index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index)
    {
        u16 expected_f0 = (u16)(0xf001u | (u8)cases[index].operating_pair);
        u16 expected_d5 = (u16)(0xd500u | (cases[index].operating_pair >> 8));

        clear_memory(0u);
        firmware_memory[0x18015ul] = 0x20u;
        firmware_memory[0xfae0ul] = 0xa0u;
        firmware_memory[0xfc15ul] = 0xa5u;
        firmware_memory[0x0e43ul] = cases[index].operating_code;
        firmware_memory[0x1008ul] = cases[index].state_1008;
        firmware_memory[0x103aul] = cases[index].flags_103a;
        set_memory_big_endian_u32(0x1235u, (u32)cases[index].frame_position);
        controller_port_setup_event_count = 0u;
        ConfigureControllerPortsAndParametersForCurrentOperatingCode(0u);
        assert(firmware_memory[0x1806aul] == cases[index].port_806a);
        assert(controller_parameter_count == 3u);
        assert(controller_parameter_trace[0] == 0xe7a5u && controller_parameter_trace[1] == expected_f0 && controller_parameter_trace[2] == expected_d5);
        assert(write_count == 14u);
        assert(write_trace[2] == 0x18007ul && write_values[2] == 8u && write_trace[7] == 0x1806aul && write_values[7] == cases[index].port_806a && write_trace[12] == 0x18086ul
               && write_values[12] == 0u && write_trace[13] == 0x18082ul && write_values[13] == 0xb0u);
        assert(controller_port_setup_event_count == 2u);
        assert(controller_port_setup_events[0] == 2u && controller_port_setup_events[1] == 3u && controller_port_setup_seen_write_count[0] == 14u && controller_port_setup_seen_write_count[1] == 14u);
    }

    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    firmware_memory[0x0e43ul] = 1u;
    controller_port_setup_event_count = 0u;
    ConfigureControllerPortsAndParametersForCurrentOperatingCode(1u);
    assert(write_count == 18u && firmware_memory[0xfbf6ul] == 0x43u);
    assert(write_trace[14] == 0xfbf6ul && write_values[14] == 0x43u && write_trace[15] == 0x1809dul && write_values[15] == 0x43u && write_trace[16] == 0xfbf6ul && write_values[16] == 0x43u
           && write_trace[17] == 0x1809dul && write_values[17] == 0x43u);
    assert(controller_port_setup_event_count == 3u);
    assert(controller_port_setup_events[0] == 2u && controller_port_setup_events[1] == 3u && controller_port_setup_events[2] == 4u);
    assert(controller_port_setup_seen_write_count[0] == 18u && controller_port_setup_seen_write_count[1] == 18u && controller_port_setup_seen_write_count[2] == 18u);

    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    firmware_memory[0xfae0ul] = 0xa0u;
    firmware_memory[0x0e43ul] = 1u;
    controller_port_setup_event_count = 0u;
    ConfigureControllerPortsAndParametersForCurrentOperatingCode(2u);
    assert(controller_port_setup_event_count == 2u && controller_port_setup_events[0] == 2u && controller_port_setup_events[1] == 3u);
}

