static void test_apply_fixed_controller_parameter_table(void)
{
    fw_addr_t pointer_entry;

    clear_memory(0u);
    firmware_memory[0x18015ul] = 0x20u;
    pointer_entry = 0xff857cul + 255ul * 4ul;
    set_memory_big_endian_u32_far(pointer_entry, 0x0012fffcul);
    firmware_memory[0x12fffcul] = 0xabu;
    firmware_memory[0x12fffdul] = 0xcdu;
    firmware_memory[0x12fffeul] = 0x12u;
    firmware_memory[0x12fffful] = 0x34u;
    firmware_memory[0x120000ul] = 0xffu;
    firmware_memory[0x120001ul] = 0xffu;
    ApplyFixedControllerParameterTable(255u);
    assert(write_count == 4u);
    assert(write_trace[0] == 0x180f0ul && write_values[0] == 0x34u);
    assert(write_trace[1] == 0x180f1ul && write_values[1] == 0x12u);
    assert(write_trace[2] == 0x180f2ul && write_values[2] == 0xcdu);
    assert(write_trace[3] == 0x180f3ul && write_values[3] == 0xabu);
    assert(read_count == 12u);
    assert(read_trace[0] == pointer_entry);
    assert(read_trace[1] == pointer_entry + 1u);
    assert(read_trace[2] == pointer_entry + 2u);
    assert(read_trace[3] == pointer_entry + 3u);
    assert(read_trace[4] == 0x12fffcul);
    assert(read_trace[5] == 0x12fffdul);
    assert(read_trace[6] == 0x12fffeul);
    assert(read_trace[7] == 0x12fffful);
    assert(read_trace[10] == 0x120000ul);
    assert(read_trace[11] == 0x120001ul);

    clear_memory(0u);
    pointer_entry = 0xff857cul + 5ul * 4ul;
    set_memory_big_endian_u32_far(pointer_entry, 0x0034abcdul);
    firmware_memory[0x34abcdul] = 0xffu;
    firmware_memory[0x34abceul] = 0xffu;
    ApplyFixedControllerParameterTable(5u);
    assert(read_count == 6u);
    assert(read_trace[4] == 0x34abcdul);
    assert(read_trace[5] == 0x34abceul);
    assert(write_count == 0u);
    assert(sfr_read_count == 0u && sfr_write_count == 0u);
}

