static void test_poll_write_preservation_descriptor_batch(void)
{
    u16 descriptor;
    unsigned cursor;

    clear_memory(0u);
    assert(PollWritePreservationDescriptorBatch() == 0xfeu);
    assert(write_preservation_enqueue_count == 0u && write_preservation_batch_yields == 0u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 5u);
    set_memory_big_endian_u16(0x1296u, 4u);
    set_memory_big_endian_u16(0x129au, 0xffu);
    set_memory_big_endian_u32_far(0x129eul, 0x3000ul);
    descriptor = (u16)(0x3000u + 3u * 0x16u);
    set_memory_big_endian_u16((u16)(descriptor + 2u), 0x4000u);
    set_memory_big_endian_u16(0x4000u, 0x1234u);
    bit_0008 = 0u;
    assert(PollWritePreservationDescriptorBatch() == 0u);
    assert(get_memory_big_endian_u16(0x1296u) == 3u);
    assert(get_memory_big_endian_u16(0x1292u) == 4u);
    assert(write_preservation_enqueue_count == 1u);
    assert(write_preservation_enqueue_cursors[0] == 3ul * 0x930ul + 0x2df0ul);
    assert((u32)write_preservation_enqueue_positions[0] == (0x12340000ul | descriptor));
    assert(write_preservation_enqueue_counts[0] == 0x1du);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 0x1fu);
    set_memory_big_endian_u16(0x1296u, 1u);
    set_memory_big_endian_u16(0x129au, 0xffu);
    set_memory_big_endian_u32_far(0x129eul, 0x3000ul);
    bit_0008 = 1u;
    assert(PollWritePreservationDescriptorBatch() == 0xfeu);
    assert(write_preservation_enqueue_count == 0u && write_preservation_batch_yields == 0u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 0x20u);
    set_memory_big_endian_u16(0x1294u, 2u);
    set_memory_big_endian_u16(0x1296u, 34u);
    set_memory_big_endian_u16(0x129au, 0xffu);
    set_memory_big_endian_u32_far(0x129eul, 0x5000ul);
    bit_0008 = 1u;
    for(cursor = 2u; cursor < 34u; ++cursor)
    {
        descriptor = (u16)(0x5000u + cursor * 0x16u);
        firmware_memory[descriptor + 0x10u] = 0u;
    }

    descriptor = (u16)(0x5000u + 4u * 0x16u);
    firmware_memory[descriptor + 0x10u] = 1u;
    set_memory_big_endian_u16((u16)(descriptor + 0x0eu), 0x7000u);
    firmware_memory[0x7013u] = 0x0bu;
    set_memory_big_endian_u16((u16)(descriptor + 2u), 0x7200u);
    set_memory_big_endian_u16(0x7200u, 0x1111u);

    descriptor = (u16)(0x5000u + 5u * 0x16u);
    firmware_memory[descriptor + 0x10u] = 1u;
    set_memory_big_endian_u16((u16)(descriptor + 0x0eu), 0x7020u);
    firmware_memory[0x7033u] = 0x0bu;
    set_memory_big_endian_u16((u16)(descriptor + 2u), 0x7202u);
    set_memory_big_endian_u16(0x7202u, 0x2222u);

    descriptor = (u16)(0x5000u + 6u * 0x16u);
    firmware_memory[descriptor + 0x10u] = 1u;
    set_memory_big_endian_u16((u16)(descriptor + 0x0eu), 0x1804u);

    assert(PollWritePreservationDescriptorBatch() == 1u);
    assert(write_preservation_batch_yields == 1u);
    assert(write_preservation_enqueue_count == 2u);
    assert(write_preservation_enqueue_cursors[0] == 4ul * 0x930ul + 0x2df0ul);
    assert(write_preservation_enqueue_cursors[1] == 5ul * 0x930ul + 0x2df0ul);
    assert((u32)write_preservation_enqueue_positions[0] == (0x11110000ul | (0x5000u + 4u * 0x16u)));
    assert((u32)write_preservation_enqueue_positions[1] == (0x22220000ul | (0x5000u + 5u * 0x16u)));
    assert(write_preservation_enqueue_counts[0] == 1u && write_preservation_enqueue_counts[1] == 1u);
    assert(get_memory_big_endian_u16(0x1298u) == 34u);

    firmware_memory[0x7033u] = 0x0cu;
    write_preservation_batch_yields = 0u;
    write_preservation_enqueue_count = 0u;
    assert(PollWritePreservationDescriptorBatch() == 0u);
    assert(write_preservation_batch_yields == 1u && write_preservation_enqueue_count == 2u);
}

