static void initialize_write_pipeline_finalize_type2(void)
{
    u16 record_address = (u16)(0xb4c1u + 2u * 8u);

    firmware_memory[0x0c44u] = 2u;
    set_memory_big_endian_u16(0x1292u, 1u);
    firmware_memory[0xfba0u] = 4u;
    set_memory_big_endian_u32(0x1598u, 0x81234567ul);
    set_memory_big_endian_u16(0x149fu, 2u);
    firmware_memory[record_address] = 0x11u;
    firmware_memory[(u16)(record_address + 1u)] = 0xeeu;
    firmware_memory[(u16)(record_address + 2u)] = 0x22u;
    firmware_memory[(u16)(record_address + 3u)] = 0x33u;
    write_pipeline_finalize_converted_tuple[0] = 0x44u;
    write_pipeline_finalize_converted_tuple[1] = 0x55u;
    write_pipeline_finalize_converted_tuple[2] = 0x66u;
}

static void test_finalize_write_command_raw_read_pipeline_preparation(void)
{
    unsigned index;

    clear_memory(0u);
    reset_write_pipeline_finalize_observation();
    set_memory_big_endian_u32(0x1598u, 0ul);
    set_memory_big_endian_u32(0x8000u, 0x12345678ul);
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 1u);
    assert(get_memory_big_endian_u32(0x8000u) == 0xfffffffful && firmware_memory[0x1554u] == 1u && write_pipeline_finalize_event_count == 0u);

    clear_memory(0u);
    reset_write_pipeline_finalize_observation();
    firmware_memory[0x0c46u] = 2u;
    set_memory_big_endian_u32(0x8000u, 0x12345678ul);
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 1u);
    assert(get_memory_big_endian_u32(0x8000u) == 0x12345678ul && firmware_memory[0x1554u] == 1u);

    clear_memory(0u);
    reset_write_pipeline_finalize_observation();
    firmware_memory[0x0c44u] = 1u;
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 1u && firmware_memory[0x1554u] == 1u);
    firmware_memory[0x0c44u] = 3u;
    firmware_memory[0x1554u] = 0u;
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 1u && firmware_memory[0x1554u] == 1u);
    firmware_memory[0x0c44u] = 4u;
    firmware_memory[0x1554u] = 0u;
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 1u && firmware_memory[0x1554u] == 0u);

    clear_memory(0u);
    reset_write_pipeline_finalize_observation();
    firmware_memory[0x0c44u] = 2u;
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 0u);
    assert(write_pipeline_finalize_sense030c09_count == 1u && write_pipeline_finalize_event_count == 1u && write_pipeline_finalize_events[0] == 'S');

    clear_memory(0u);
    reset_write_pipeline_finalize_observation();
    initialize_write_pipeline_finalize_type2();
    write_pipeline_finalize_isrc_result = 1u;
    write_pipeline_finalize_compare_result = 2u;
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 1u);
    assert(write_pipeline_finalize_event_count == 5u && memcmp(write_pipeline_finalize_events, "ILCPM", 5u) == 0);
    assert(write_pipeline_finalize_isrc_count == 1u && write_pipeline_finalize_load_isrc_count == 1u && write_pipeline_finalize_convert_frame == (s32)0x81234567ul);
    assert(memcmp(write_pipeline_finalize_copied_source, "\x11\x22\x33", 3u) == 0 && memcmp(write_pipeline_finalize_compare_left, "\x44\x55\x66", 3u) == 0
           && memcmp(write_pipeline_finalize_compare_right, "\x11\x22\x33", 3u) == 0);
    assert(firmware_memory[0x1554u] == 1u && write_pipeline_finalize_acquire_count == 0u);

    clear_memory(0u);
    reset_write_pipeline_finalize_observation();
    initialize_write_pipeline_finalize_type2();
    write_pipeline_finalize_acquire_results[0] = 1u;
    write_pipeline_finalize_acquire_result_count = 1u;
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 1u);
    assert(memcmp(write_pipeline_finalize_events, "ICPMAN", 6u) == 0 && write_pipeline_finalize_event_count == 6u && firmware_memory[0x1281u] == 3u
           && write_pipeline_finalize_acquire_arguments[0] == 0u && write_pipeline_finalize_no_sense_count == 1u);

    clear_memory(0u);
    reset_write_pipeline_finalize_observation();
    initialize_write_pipeline_finalize_type2();
    write_pipeline_finalize_acquire_results[0] = 0u;
    write_pipeline_finalize_acquire_results[1] = 0u;
    write_pipeline_finalize_acquire_results[2] = 1u;
    write_pipeline_finalize_acquire_result_count = 3u;
    firmware_memory[0x0e47u] = 52u;
    firmware_memory[0x1490u] = 0xa5u;
    firmware_memory[0x127du] = 0x5au;
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 1u);
    assert(write_pipeline_finalize_event_count == 8u && memcmp(write_pipeline_finalize_events, "ICPMAAAN", 8u) == 0);
    assert(write_pipeline_finalize_acquire_arguments[0] == 0u && write_pipeline_finalize_acquire_arguments[1] == 1u && write_pipeline_finalize_acquire_arguments[2] == 1u
           && firmware_memory[0x1490u] == 0u && firmware_memory[0x127du] == 0u && firmware_memory[0x0e47u] == 16u);

    clear_memory(0u);
    reset_write_pipeline_finalize_observation();
    initialize_write_pipeline_finalize_type2();
    firmware_memory[0xfbecu] = 2u;
    write_pipeline_finalize_acquire_result_count = 1u;
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 0u);
    assert(write_pipeline_finalize_event_count == 6u && memcmp(write_pipeline_finalize_events, "ICPMAF", 6u) == 0 && write_pipeline_finalize_failure_count == 1u
           && write_pipeline_finalize_failure_code == 5u && firmware_memory[0x1490u] == 0u);

    clear_memory(0u);
    reset_write_pipeline_finalize_observation();
    initialize_write_pipeline_finalize_type2();
    write_pipeline_finalize_acquire_result_count = 10u;
    firmware_memory[0x0e47u] = 17u;
    assert(FinalizeWriteCommandRawReadPipelinePreparation() == 0u);
    assert(write_pipeline_finalize_acquire_count == 10u && write_pipeline_finalize_failure_count == 1u && write_pipeline_finalize_failure_code == 5u && firmware_memory[0x0e47u] == 16u);
    assert(write_pipeline_finalize_acquire_arguments[0] == 0u);
    for(index = 1u; index < 10u; index++)
        assert(write_pipeline_finalize_acquire_arguments[index] == 1u);
}

static void test_initialize_read_acquisition_controller_registers(void)
{
    static const fw_addr_t expected_addresses[42] = { 0x0fcaul, 0x18002ul, 0x0fadul, 0x18003ul, 0x1802dul, 0x0fcaul, 0x18002ul, 0x18031ul, 0x18008ul, 0x18009ul, 0x1800aul, 0x1803aul, 0x1806eul,
        0x1800ful, 0x1800cul, 0x0fcaul, 0x18002ul, 0x0efbul, 0x18004ul, 0x0fcaul, 0x18002ul, 0x1800bul, 0x18001ul, 0x18023ul, 0x1800cul, 0x0fcaul, 0x18002ul, 0x0efdul, 0x18006ul, 0x0efbul, 0x18004ul,
        0x0efcul, 0x18005ul, 0x18007ul, 0x18008ul, 0x18009ul, 0x0efeul, 0x18018ul, 0x0efful, 0x18019ul, 0x1801cul, 0x1801dul };
    static const u8 expected_values[42] = { 0xa5u, 0xa5u, 0u, 0u, 0x7fu, 0xadu, 0xadu, 0x40u, 0x41u, 0u, 0xa0u, 0x83u, 2u, 4u, 0x7fu, 0xa5u, 0xa5u, 0u, 0u, 0xadu, 0xadu, 0xd2u, 0x71u, 0x10u, 0xffu,
        0xa5u, 0xa5u, 1u, 1u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 6u, 6u, 0x60u, 0x60u, 0u, 0u };
    unsigned index;

    clear_memory(0u);
    memset(read_acquisition_controller_init_events, 0, sizeof(read_acquisition_controller_init_events));
    read_acquisition_controller_init_event_count = 0u;
    firmware_memory[0x0fcau] = 0xbdu;
    firmware_memory[0x1158u] = 5u;
    sfr_memory[0xa9u] = 0xa1u;
    bit_0547 = 1u;
    bit_0546 = 0u;
    InitializeReadAcquisitionControllerRegisters();

    assert(write_count == 42u);
    for(index = 0u; index < 42u; index++)
    {
        assert(write_trace[index] == expected_addresses[index]);
        assert(write_values[index] == expected_values[index]);
    }
    assert(read_acquisition_controller_init_event_count == 4u && memcmp(read_acquisition_controller_init_events, "gGCA", 4u) == 0);
    assert(bit_0547 == 1u && bit_0546 == 1u && sfr_memory[0xa9u] == 0xa5u);
    assert(firmware_memory[0x0fcau] == 0xa5u && firmware_memory[0x18002u] == 0xa5u && firmware_memory[0x18008u] == 0u && firmware_memory[0x18009u] == 0u);

    clear_memory(0u);
    memset(read_acquisition_controller_init_events, 0, sizeof(read_acquisition_controller_init_events));
    read_acquisition_controller_init_event_count = 0u;
    firmware_memory[0x0fcau] = 0x18u;
    firmware_memory[0x1158u] = 4u;
    firmware_memory[0x18031u] = 0x5au;
    InitializeReadAcquisitionControllerRegisters();
    assert(write_count == 41u && firmware_memory[0x18031u] == 0x5au && firmware_memory[0x0fcau] == 0u && firmware_memory[0x18002u] == 0u);
}

