static void test_initialize_type2_controller_record_state_from_mip_payload(void)
{
    static const u8 active_payload_flags[3] = { 0x40u, 0x80u, 0xc0u };
    static const u8 active_layout_modes[3] = { 1u, 3u, 3u };
    unsigned index;

    clear_memory(0u);
    reset_type2_mip_state_observation();
    firmware_memory[0x2bb921u] = 0x11u;
    firmware_memory[0x2bb922u] = 0x22u;
    firmware_memory[0x2bb923u] = 0x33u;
    firmware_memory[0x2bb924u] = 0x44u;
    firmware_memory[0x2bb931u] = 0x10u;
    firmware_memory[0x0c88u] = 0xffu;
    firmware_memory[0x0c86u] = 0xffu;
    memset(&firmware_memory[0x2bb4bbu], 0xaau, 7u);
    type2_mip_state_geometry_position = 0x00000120ul;
    type2_mip_state_geometry_record_count = 5u;
    type2_mip_state_divide_result = 2l;
    InitializeType2ControllerRecordStateFromMipPayload();

    assert(type2_mip_state_event_count == 4u && memcmp(type2_mip_state_events, "DQFB", 4u) == 0);
    assert(
        firmware_memory[0x2ba524u] == 1u && firmware_memory[0x2ba525u] == 0x11u && firmware_memory[0x2ba526u] == 0x22u && firmware_memory[0x2ba527u] == 0x33u && firmware_memory[0x2ba528u] == 0x44u);
    assert(firmware_memory[0x0c9eu] == 0u && firmware_memory[0x0c88u] == 0xffu && firmware_memory[0x0c86u] == 0xffu);
    assert(get_memory_big_endian_u32(0xfaffu) == 0x0000b4bbul && type2_mip_state_dividend == 0x8el && type2_mip_state_divisor == 39l && firmware_memory[0x2ba5dbu] == 0u
           && firmware_memory[0x2ba5dcu] == 2u);
    assert(firmware_memory[0x2bb4bbu] == 5u && firmware_memory[0x2bb4bcu] == 5u && firmware_memory[0x2bb4bdu] == 5u && firmware_memory[0x2bb4beu] == 0u && firmware_memory[0x2bb4bfu] == 0u
           && firmware_memory[0x2bb4c0u] == 0xaau);
    assert(type2_mip_state_finalize_matched == 1u && type2_mip_state_finalize_residual == 5u && type2_mip_state_boundary_count == 5u);

    for(index = 0u; index < 3u; index++)
    {
        clear_memory(0u);
        reset_type2_mip_state_observation();
        firmware_memory[0x2bb931u] = active_payload_flags[index];
        firmware_memory[0x0c88u] = 0xffu;
        firmware_memory[0x0c86u] = 0xffu;
        type2_mip_state_geometry_position = 0x92ul;
        type2_mip_state_geometry_record_count = 1u;
        type2_mip_state_finalize_result = 0x7au;
        InitializeType2ControllerRecordStateFromMipPayload();
        assert(firmware_memory[0x0c9eu] == active_layout_modes[index] && firmware_memory[0xe625u] == 0x80u && firmware_memory[0x0c3cu] == 0x80u && firmware_memory[0x2ba5afu] == 1u
               && firmware_memory[0x0c88u] == 0x7fu && firmware_memory[0x0c86u] == 0xbfu);
        assert(type2_mip_state_finalize_matched == 0u && type2_mip_state_finalize_residual == 1u && type2_mip_state_boundary_count == 0x7au && firmware_memory[0x2bb4bbu] == 5u);
    }
}

