static void test_issue_read_acquisition_pickup_move(void)
{
    clear_memory(0u);
    reset_acquisition_move_observation();
    set_memory_big_endian_u16(0x0edeu, 149u);
    firmware_memory[0x0ee3u] = 0x7eu;
    assert(IssueReadAcquisitionPickupMove() == 0u);
    assert(acquisition_fine_move_call_count == 0u);
    assert(acquisition_move_dispatch_count == 1u && acquisition_move_dispatch_kind == 'C' && acquisition_move_dispatch_direction == 0x7eu && acquisition_move_dispatch_distance == 149u);

    clear_memory(0u);
    reset_acquisition_move_observation();
    set_memory_big_endian_u16(0x0edeu, 49u);
    firmware_memory[0x0ee3u] = 2u;
    acquisition_fine_move_result = 10u;
    assert(IssueReadAcquisitionPickupMove() == 0u);
    assert(acquisition_fine_move_call_count == 1u);
    assert(get_memory_big_endian_u16(0x0edcu) == 10u);
    assert(acquisition_move_dispatch_count == 1u && acquisition_move_dispatch_kind == 'C' && acquisition_move_dispatch_direction == 2u && acquisition_move_dispatch_distance == 10u);
    assert(firmware_memory[0x1300u] == 0u);

    clear_memory(0u);
    reset_acquisition_move_observation();
    set_memory_big_endian_u16(0x0edeu, 0u);
    firmware_memory[0x0ee3u] = 1u;
    acquisition_fine_move_result = 9u;
    assert(IssueReadAcquisitionPickupMove() == 0u);
    assert(acquisition_fine_move_call_count == 1u);
    assert(get_memory_big_endian_u16(0x0edcu) == 9u);
    assert(acquisition_move_dispatch_count == 1u && acquisition_move_dispatch_kind == 'B' && acquisition_move_dispatch_direction == 1u && acquisition_move_dispatch_distance == 9u);
    assert(firmware_memory[0x1300u] == 1u);

    clear_memory(0u);
    reset_acquisition_move_observation();
    set_memory_big_endian_u16(0x0edeu, 500u);
    set_memory_big_endian_u16(0x0edcu, 4000u);
    set_memory_big_endian_u16(0x0ff7u, 4201u);
    set_memory_big_endian_u32(0x0ee9u, 2001u);
    firmware_memory[0x0ed7u] = 2u;
    firmware_memory[0x1006u] = 2u;
    firmware_memory[0x0ee3u] = 3u;
    assert(IssueReadAcquisitionPickupMove() == 0u);
    assert(get_memory_big_endian_u16(0x0edeu) == 500u);
    assert(acquisition_move_dispatch_kind == 'S' && acquisition_move_dispatch_direction == 3u && acquisition_move_dispatch_distance == 500u);

    clear_memory(0u);
    reset_acquisition_move_observation();
    set_memory_big_endian_u16(0x0edeu, 250u);
    set_memory_big_endian_u16(0x0edcu, 4000u);
    set_memory_big_endian_u16(0x0ff7u, 4200u);
    set_memory_big_endian_u32(0x0ee9u, 2001u);
    firmware_memory[0x0ed7u] = 1u;
    firmware_memory[0x1006u] = 1u;
    assert(IssueReadAcquisitionPickupMove() == 0u);
    assert(get_memory_big_endian_u16(0x0edeu) == 0u);
    assert(acquisition_move_dispatch_count == 1u && acquisition_move_dispatch_kind == 'S' && acquisition_move_dispatch_distance == 0u);

    clear_memory(0u);
    reset_acquisition_move_observation();
    set_memory_big_endian_u16(0x0edeu, 150u);
    set_memory_big_endian_u16(0x0edcu, 800u);
    firmware_memory[0x0ed7u] = 1u;
    firmware_memory[0x1006u] = 1u;
    assert(IssueReadAcquisitionPickupMove() == 0u);
    assert(get_memory_big_endian_u16(0x0edeu) == 0xffceu);
    assert(acquisition_move_dispatch_distance == 0xffceu);

    clear_memory(0u);
    reset_acquisition_move_observation();
    set_memory_big_endian_u16(0x0edeu, 500u);
    set_memory_big_endian_u16(0x0edcu, 15000u);
    set_memory_big_endian_u16(0x0ff7u, 15401u);
    set_memory_big_endian_u32(0x0ee9u, 4001u);
    assert(IssueReadAcquisitionPickupMove() == 0u);
    assert(get_memory_big_endian_u16(0x0edeu) == 500u);
    assert(acquisition_move_dispatch_distance == 500u);

    clear_memory(0u);
    reset_acquisition_move_observation();
    set_memory_big_endian_u16(0x0edeu, 500u);
    set_memory_big_endian_u16(0x0edcu, 15000u);
    set_memory_big_endian_u16(0x0ff7u, 15400u);
    set_memory_big_endian_u32(0x0ee9u, 4001u);
    assert(IssueReadAcquisitionPickupMove() == 0u);
    assert(get_memory_big_endian_u16(0x0edeu) == 450u);
    assert(acquisition_move_dispatch_distance == 450u);

    clear_memory(0u);
    reset_acquisition_move_observation();
    set_memory_big_endian_u16(0x0edeu, 500u);
    set_memory_big_endian_u16(0x0edcu, 4000u);
    set_memory_big_endian_u16(0x0ff7u, 0xffffu);
    set_memory_big_endian_u32(0x0ee9u, 0xfffffffful);
    assert(IssueReadAcquisitionPickupMove() == 0u);
    assert(get_memory_big_endian_u16(0x0edeu) == 450u);
    assert(acquisition_move_dispatch_distance == 450u);
}

