static void test_calculate_radial_model_distance_to_read_target(void)
{
    clear_memory(0u);
    reset_radial_distance_observation();
    set_memory_big_endian_u32(0x1235u, 750ul);
    set_memory_big_endian_u32(0x0e3bu, 1500ul);
    assert(CalculateRadialModelDistanceToReadTarget() == 10u);
    assert(get_memory_big_endian_u32(0x0eedu) == 1500ul);
    assert(get_memory_big_endian_u16(0x0ed3u) == 1010u);
    assert(radial_distance_divide_count == 2u && radial_distance_dividend_trace[0] == 750l && radial_distance_dividend_trace[1] == 1500l);
    assert(radial_distance_map_count == 2u && radial_distance_map_kind[0] == 'P' && radial_distance_map_kind[1] == 'P' && radial_distance_map_input[0] == 10u && radial_distance_map_input[1] == 20u);

    clear_memory(0u);
    reset_radial_distance_observation();
    set_memory_big_endian_u32(0x1235u, (u32)-750l);
    set_memory_big_endian_u32(0x0e3bu, (u32)-2250l);
    assert(CalculateRadialModelDistanceToReadTarget() == 20u);
    assert(get_memory_big_endian_u32(0x0eedu) == (u32)-2250l);
    assert(get_memory_big_endian_u16(0x0ed3u) == 0xffffu);
    assert(radial_distance_dividend_trace[0] == 750l && radial_distance_dividend_trace[1] == 2250l);
    assert(radial_distance_map_kind[0] == 'L' && radial_distance_map_kind[1] == 'L' && radial_distance_map_input[0] == 10u && radial_distance_map_input[1] == 30u);

    clear_memory(0u);
    reset_radial_distance_observation();
    set_memory_big_endian_u32(0x1235u, (u32)-750l);
    set_memory_big_endian_u32(0x0e3bu, 1500ul);
    assert(CalculateRadialModelDistanceToReadTarget() == 3030u);
    assert(get_memory_big_endian_u16(0x0ed3u) == 0xffffu);
    assert(radial_distance_map_kind[0] == 'L' && radial_distance_map_kind[1] == 'P');

    clear_memory(0u);
    reset_radial_distance_observation();
    set_memory_big_endian_u32(0x1235u, 750ul);
    set_memory_big_endian_u32(0x0e3bu, (u32)-1500l);
    assert(CalculateRadialModelDistanceToReadTarget() == 3030u);
    assert(get_memory_big_endian_u16(0x0ed3u) == 0xffffu);
    assert(radial_distance_map_kind[0] == 'P' && radial_distance_map_kind[1] == 'L');
}

