static void test_recalculate_radial_operating_threshold_state(void)
{
    volatile float first_scaled;
    volatile float second_scaled;
    volatile float numerator;

    clear_memory(0u);
    reset_radial_operating_threshold_observers(100.0f);
    set_memory_big_endian_u16(0x0cf3u, 2000u);
    RecalculateRadialOperatingThresholdState();
    first_scaled = 100.0f * 48.6f;
    second_scaled = 100.0f * 53.0f;
    numerator = 28224.0f * 500.0f;
    assert(radial_threshold_map_count == 1u && radial_threshold_endpoint == 0x000514c8l);
    assert(get_memory_big_endian_u16(0xf9fcu) == (u16)(s32)first_scaled && get_memory_big_endian_u16(0x0cf1u) == (u16)(s32)(numerator / first_scaled)
           && get_memory_big_endian_u16(0xf9feu) == (u16)(s32)second_scaled && get_memory_big_endian_u16(0x0cf3u) == (u16)(s32)(numerator / second_scaled));
    assert(radial_threshold_operating_code_count == 1u && radial_threshold_operating_code == 0x34u);

    clear_memory(0u);
    reset_radial_operating_threshold_observers(100.0f);
    set_memory_big_endian_u32(0x12c1u, 123456ul);
    set_memory_big_endian_u16(0x0cf3u, 2000u);
    RecalculateRadialOperatingThresholdState();
    assert(radial_threshold_endpoint == 123456l);

    clear_memory(0u);
    reset_radial_operating_threshold_observers(100.0f);
    firmware_memory[0x1008u] = 1u;
    set_memory_big_endian_u32(0x1153u, 400000ul);
    set_memory_big_endian_u32(0x12c1u, 382500ul);
    firmware_memory[0x0fafu] = 4u;
    firmware_memory[0xf553u] = 0xffu;
    set_memory_big_endian_u16(0x0cf3u, 2000u);
    RecalculateRadialOperatingThresholdState();
    assert(radial_threshold_endpoint == 382500l);

    clear_memory(0u);
    reset_radial_operating_threshold_observers(100.0f);
    firmware_memory[0x1008u] = 1u;
    set_memory_big_endian_u32(0x1153u, 400000ul);
    set_memory_big_endian_u32(0x12c1u, 382499ul);
    firmware_memory[0x0fafu] = 4u;
    firmware_memory[0xf553u] = 0xffu;
    set_memory_big_endian_u16(0x0cf3u, 2000u);
    RecalculateRadialOperatingThresholdState();
    assert(radial_threshold_endpoint == 400000l);

    clear_memory(0u);
    reset_radial_operating_threshold_observers(100.0f);
    set_memory_big_endian_u16(0x0cf3u, 0x05beu);
    RecalculateRadialOperatingThresholdState();
    assert(get_memory_big_endian_u16(0xf9fcu) == 0x2580u && get_memory_big_endian_u16(0x0cf3u) > 0x0540u);

    clear_memory(0u);
    reset_radial_operating_threshold_observers(200.0f);
    set_memory_big_endian_u16(0x0cf3u, 2000u);
    RecalculateRadialOperatingThresholdState();
    assert(get_memory_big_endian_u16(0xf9fcu) == 9720u && get_memory_big_endian_u16(0xf9feu) == 0x2904u && get_memory_big_endian_u16(0x0cf3u) == 0x0540u);
}

