static void test_calibrate_radial_model_span_at_frame90000(void)
{
    clear_memory(0u);
    reset_radial_span_observers();
    set_memory_big_endian_u32(0x12c1u, 89999ul);
    assert(CalibrateRadialModelSpanAtFrame90000() == 0u);
    assert(get_memory_big_endian_u16(0x0cf9u) == 1500u && radial_span_position_index == 0u);

    clear_memory(0u);
    reset_radial_span_observers();
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0xfbecu] = 0u;
    set_memory_big_endian_u32(0x12c1u, 100000ul);
    set_memory_big_endian_u32(0x1153u, 89999ul);
    assert(CalibrateRadialModelSpanAtFrame90000() == 0u);
    assert(get_memory_big_endian_u16(0x0cf9u) == 1500u && radial_span_target_count == 0u);

    clear_memory(0u);
    reset_radial_span_observers();
    prepare_radial_span_success(1500u);
    assert(CalibrateRadialModelSpanAtFrame90000() == 0u);
    assert(firmware_memory[0x0e44u] == 4u && get_memory_big_endian_u32(0x0e3bu) == 90000ul && firmware_memory[0x0ed6u] == 1u && radial_span_measure_count == 1u && radial_span_calculate_count == 1u
           && radial_span_calculate_input == 0x1234u && get_memory_big_endian_u16(0x0cf9u) == 1500u);

    clear_memory(0u);
    reset_radial_span_observers();
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0xfbecu] = 1u;
    firmware_memory[0xfb57u] = 0xffu;
    firmware_memory[0x1306u] = 2u;
    set_memory_big_endian_u32(0x12c1u, 100000ul);
    set_memory_big_endian_u32(0x1153u, 400000ul);
    set_memory_big_endian_u32(0xfb8cu, 350000ul);
    set_memory_big_endian_u32(0xfb90u, 20000ul);
    radial_span_target_result = 0u;
    radial_span_target_countdown_after_call = 0xffu;
    assert(CalibrateRadialModelSpanAtFrame90000() == 0u);
    assert(radial_span_target_count == 1u && radial_span_decode_count == 1u && firmware_memory[0xfb57u] == 0x7fu && get_memory_big_endian_u32(0x1153u) == 363250ul
           && get_memory_big_endian_u16(0x0cf9u) == 1500u);

    clear_memory(0u);
    reset_radial_span_observers();
    set_memory_big_endian_u32(0x12c1u, 100000ul);
    set_memory_big_endian_u32(0x1153u, 100000ul);
    radial_span_position_results[0] = 0u;
    radial_span_position_count = 1u;
    radial_span_reset_result = 0u;
    assert(CalibrateRadialModelSpanAtFrame90000() == 0x11u);
    assert(radial_span_reset_count == 1u);

    clear_memory(0u);
    reset_radial_span_observers();
    set_memory_big_endian_u32(0x12c1u, 100000ul);
    set_memory_big_endian_u32(0x1153u, 100000ul);
    radial_span_position_results[0] = 0u;
    radial_span_position_count = 1u;
    radial_span_position_countdown_after_call = 0u;
    assert(CalibrateRadialModelSpanAtFrame90000() == 0u);
    assert(radial_span_reset_count == 1u && get_memory_big_endian_u16(0x0cf9u) == 1500u);

    clear_memory(0u);
    reset_radial_span_observers();
    prepare_radial_span_success(1800u);
    radial_span_position_results[1] = 1u;
    radial_span_position_count = 2u;
    radial_span_test_results[0] = 0u;
    radial_span_test_results[1] = 1u;
    radial_span_test_count = 2u;
    assert(CalibrateRadialModelSpanAtFrame90000() == 0u);
    assert(radial_span_position_index == 2u && get_memory_big_endian_u16(0x0cf9u) == 1800u);

    clear_memory(0u);
    reset_radial_span_observers();
    prepare_radial_span_success(1199u);
    assert(CalibrateRadialModelSpanAtFrame90000() == 0u);
    assert(get_memory_big_endian_u16(0x0cf9u) == 1200u);
}

