    set_memory_big_endian_u16(0x1292u, 1u);
    firmware_memory[0x1285u] = 0x40u;
    firmware_memory[0x0c44u] = 2u;
    write_raw_pipeline_service_results[0] = 0xfeu;
    write_raw_pipeline_service_results[1] = 0xfeu;
    write_raw_pipeline_service_results[2] = 1u;
