static void test_refine_radial_calibration_at_frame150(void)
{
    clear_memory(0u);
    prepare_radial_refinement_success(1000ul, 1000ul);
    firmware_memory[0xf9e9u] = 0x80u;
    RefineRadialCalibrationAtFrame150();
    assert(radial_refinement_acquire_index == 3u && radial_refinement_yield_count == 1u && radial_refinement_target_count == 1u && radial_refinement_measure_count == 1u
           && radial_refinement_set_count == 1u && radial_refinement_rebuild_count == 1u);
    assert(firmware_memory[0xf9e8u] == 0x64u && firmware_memory[0xf9e9u] == 0x80u && get_memory_big_endian_u32(0xfc33u) == 1000ul && get_memory_big_endian_u32(0x0cf5u) == 980ul
           && get_memory_big_endian_u32(0xfc37u) == 980ul && get_memory_big_endian_u32(0x0e3bu) == 150ul);
    assert(radial_refinement_operating_count == 3u && radial_refinement_operating_values[0] == 0u && radial_refinement_operating_values[1] == 0u && radial_refinement_operating_values[2] == 1u
           && firmware_memory[0x0ed6u] == 1u);

    clear_memory(0u);
    prepare_radial_refinement_success(500ul, 1000ul);
    RefineRadialCalibrationAtFrame150();
    assert(firmware_memory[0xf9e8u] == 0x3cu && firmware_memory[0xf9e9u] == 0x04u);

    clear_memory(0u);
    reset_radial_refinement_observers();
    radial_refinement_acquire_results[0] = 0u;
    radial_refinement_acquire_count = 1u;
    radial_refinement_reset_result = 0u;
    RefineRadialCalibrationAtFrame150();
    assert(radial_refinement_reset_count == 1u && radial_refinement_operating_count == 0u);

    clear_memory(0u);
    reset_radial_refinement_observers();
    radial_refinement_acquire_results[0] = 1u;
    radial_refinement_acquire_results[1] = 1u;
    radial_refinement_acquire_results[2] = 1u;
    radial_refinement_acquire_count = 3u;
    radial_refinement_target_result = 0u;
    set_memory_big_endian_u32_far(0x0cf5ul, 1000ul);
    RefineRadialCalibrationAtFrame150();
    assert(radial_refinement_target_count == 1u && radial_refinement_rebuild_count == 0u && radial_refinement_operating_values[radial_refinement_operating_count - 1u] == 1u);
}

static void test_initialize_read_acquisition_radial_state(void)
{
    static const struct
    {
        s32 target;
        u8 drive_flag;
        u8 media_state;
        u16 expected_radial_value;
        u8 expected_radial_high;
        u8 expected_retry_limit;
        u8 expected_timer;
        unsigned expected_map_count;
    } vectors[] = {
        { -76l,        0u, 0u, 0x3456u, 0x34u, 3u, 0x3cu, 1u },
        { -76l,        1u, 2u, 0x3456u, 0x34u, 1u, 0x50u, 1u },
        { 0x10000000l, 1u, 1u, 0x9abcu, 0x9au, 1u, 0x50u, 2u }
    };
    static const fw_addr_t expected_reads[] = { 0x0011eful, 0x001305ul, 0x000e3bul, 0x000e3cul, 0x000e3dul, 0x000e3eul, 0x000e3bul, 0x000e3cul, 0x000e3dul, 0x000e3eul, 0x000ee0ul, 0x000ee1ul,
        0x000c89ul, 0x001008ul };
    unsigned vector_index;
    unsigned trace_index;

    for(vector_index = 0u; vector_index < sizeof(vectors) / sizeof(vectors[0]); ++vector_index)
    {
        clear_memory(0xa5u);
        radial_initialization_call_count = 0u;
        radial_initialization_map_count = 0u;
        set_memory_big_endian_u32(0x0e3bu, (u32)vectors[vector_index].target);
        firmware_memory[0x11ef] = 0xffu;
        firmware_memory[0x1305] = 0xffu;
        firmware_memory[0x0c89] = vectors[vector_index].drive_flag;
        firmware_memory[0x1008] = vectors[vector_index].media_state;

        InitializeReadAcquisitionRadialState();

        assert(firmware_memory[0xfc3e] == 0u);
        assert(firmware_memory[0xfc3f] == 0u);
        assert(firmware_memory[0x11ef] == 0x7fu);
        assert(firmware_memory[0x1305] == 0xfbu);
        assert(firmware_memory[0x0ef9] == 0u);
        assert(firmware_memory[0xfc3b] == 0u);
        assert(firmware_memory[0xfc3c] == 0u);
        assert(get_memory_big_endian_u16(0x0ee0u) == vectors[vector_index].expected_radial_value);
        assert(firmware_memory[0x0ee4] == vectors[vector_index].expected_radial_high);
        assert(firmware_memory[0xfc3d] == vectors[vector_index].expected_retry_limit);
        assert(firmware_memory[0x1207] == vectors[vector_index].expected_timer);
        assert(firmware_memory[0x0ee2] == 0u);

        assert(radial_initialization_map_count == vectors[vector_index].expected_map_count);
        assert(radial_initialization_map_arguments[0] == vectors[vector_index].target / 75l);
        if(vectors[vector_index].expected_map_count == 2u)
            assert(radial_initialization_map_arguments[1] == 0l);
        assert(radial_initialization_call_trace[0] == 'R');
        assert(radial_initialization_call_trace[1] == 'M');
        assert(radial_initialization_call_trace[radial_initialization_call_count - 1u] == 'C');
        assert(radial_initialization_call_count == vectors[vector_index].expected_map_count + 2u);

        assert(read_count == sizeof(expected_reads) / sizeof(expected_reads[0]));
        for(trace_index = 0u; trace_index < sizeof(expected_reads) / sizeof(expected_reads[0]); ++trace_index)
            assert(read_trace[trace_index] == expected_reads[trace_index]);
        assert(write_count == (vector_index == 2u ? 16u : 14u));
    }
}

static void test_map_frame_seconds_to_radial_model_value(void)
{
    static const struct
    {
        u32 scale;
        u16 frame_seconds;
        u16 calibration_span;
        u16 expected;
    } vectors[] = {
        { 1ul,          1u,      1u,      0u      },
        { 10000ul,      100u,    100u,    0x005au },
        { 0xfffffffful, 0xffffu, 0xffffu, 0x0161u },
        { 0x12345678ul, 300u,    0x3456u, 0x0436u },
        { 0x00100000ul, 1000u,   250u,    0x424cu },
        { 0ul,          0xffffu, 1u,      0u      },
        { 0x04cbul,     1234u,   0x1000u, 0x0091u }
    };
    unsigned vector_index;

    for(vector_index = 0u; vector_index < sizeof(vectors) / sizeof(vectors[0]); ++vector_index)
    {
        clear_memory(0u);
        set_memory_big_endian_u32(0x0cf5u, vectors[vector_index].scale);
        set_memory_big_endian_u16(0x0cf9u, vectors[vector_index].calibration_span);
        assert(MapFrameSecondsToRadialModelValue(vectors[vector_index].frame_seconds) == vectors[vector_index].expected);
        assert(read_count == 8u && write_count == 0u);
        assert(read_trace[0] == 0x0cf5ul && read_trace[3] == 0x0cf8ul && read_trace[4] == 0x0cf9ul && read_trace[5] == 0x0cfaul && read_trace[6] == 0x0cf9ul && read_trace[7] == 0x0cfaul);
    }
}

static void test_calculate_positive_radial_model_distance_to_read_target(void)
{
    static const struct
    {
        s32 current_frame;
        s32 target_frame;
        u16 expected_reference;
        u16 expected_distance;
    } vectors[] = {
        { 7500l,  15000l, 90u,    100u   },
        { 15000l, 7500l,  190u,   100u   },
        { 7500l,  7500l,  90u,    0u     },
        { -75l,   0l,     57100u, 57100u }
    };
    unsigned vector_index;

    for(vector_index = 0u; vector_index < sizeof(vectors) / sizeof(vectors[0]); ++vector_index)
    {
        clear_memory(0u);
        set_memory_big_endian_u32(0x0cf5u, 10000ul);
        set_memory_big_endian_u16(0x0cf9u, 100u);
        set_memory_big_endian_u32(0x1235u, (u32)vectors[vector_index].current_frame);
        set_memory_big_endian_u32(0x0e3bu, (u32)vectors[vector_index].target_frame);
        assert(CalculatePositiveRadialModelDistanceToReadTarget() == vectors[vector_index].expected_distance);
        assert(get_memory_big_endian_u16(0x0ed3u) == vectors[vector_index].expected_reference);
        assert(read_count == 24u && write_count == 2u);
        assert(read_trace[0] == 0x1235ul && read_trace[3] == 0x1238ul && read_trace[4] == 0x0cf5ul && read_trace[11] == 0x0cfaul && read_trace[12] == 0x0e3bul && read_trace[15] == 0x0e3eul
               && read_trace[16] == 0x0cf5ul && read_trace[23] == 0x0cfaul);
        assert(write_trace[0] == 0x0ed3ul && write_trace[1] == 0x0ed4ul);
    }
}

static void test_acquire_raw_read_frames_and_populate_tdi_payload(void)
{
    clear_memory(0u);
    assert(AcquireRawReadFramesAndPopulateTdiPayload(-1l) == 1u);
    assert(raw_tdi_event_count == 0u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 1u);
    set_memory_big_endian_u16(0x1296u, 1u);
    set_memory_big_endian_u16(0x129au, 0x000fu);
    set_memory_big_endian_u32(0x129eu, 0x000080a4ul);
    set_memory_big_endian_u32(0x80a8u, 0x0012f6c0ul);
    set_memory_big_endian_u32(0x156au, 0x00000300ul);
    raw_tdi_acquire_intercept_enabled = 1u;
    raw_tdi_acquire_result = 0x7eu;
    assert(AcquireRawReadFramesAndPopulateTdiPayload(0x12345678l) == 1u);
    assert(raw_tdi_event_count == 3u);
    assert(raw_tdi_events[0] == 1u && raw_tdi_events[1] == 2u && raw_tdi_events[2] == 3u);
    assert(raw_tdi_acquire_frame_count == 0x12345678l);
    assert(raw_tdi_acquire_source_kind == 6u);
    assert(raw_tdi_populate_address == 0x12fff0ul);
    assert(raw_tdi_populate_sector_count == 0x12345678ul);
    assert(get_memory_big_endian_u32(0x126eu) == 0x12fff0ul);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 1u);
    set_memory_big_endian_u16(0x1296u, 1u);
    set_memory_big_endian_u16(0x129au, 0x000fu);
    set_memory_big_endian_u32(0x129eu, 0x000080a4ul);
    set_memory_big_endian_u32(0x80a8u, 0x00000904ul);
    set_memory_big_endian_u32(0x156au, 0x00000100ul);
    raw_tdi_acquire_intercept_enabled = 1u;
    raw_tdi_acquire_result = 0u;
    assert(AcquireRawReadFramesAndPopulateTdiPayload(0l) == 0u);
    assert(raw_tdi_event_count == 2u);
    assert(raw_tdi_events[0] == 1u && raw_tdi_events[1] == 2u);
    assert(raw_tdi_acquire_frame_count == 0l);
    assert(raw_tdi_acquire_source_kind == 6u);
    assert(raw_tdi_populate_address == 0u);
}

static void test_resume_main_data_ring_cursor_from_latest_descriptor(void)
{
    clear_memory(0xa5u);
    set_memory_big_endian_u16(0x1292u, 0u);
    set_memory_big_endian_u32(0x156au, 4u);
    assert(ResumeMainDataRingCursorFromLatestDescriptor() == 0u);
    assert(get_memory_big_endian_u32(0x126eu) == 0u);
    assert(raw_tdi_event_count == 1u && raw_tdi_events[0] == 1u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x1292u, 1u);
    set_memory_big_endian_u16(0x1296u, 1u);
    set_memory_big_endian_u16(0x129au, 0x000fu);
    set_memory_big_endian_u32(0x129eu, 0x000080a4ul);
    set_memory_big_endian_u32(0x80a8u, 0x00001200ul);
    set_memory_big_endian_u32(0x156au, 4u);
    assert(ResumeMainDataRingCursorFromLatestDescriptor() == 0x1b30ul);
    assert(get_memory_big_endian_u32(0x126eu) == 0x1b30ul);

    set_memory_big_endian_u32(0x80a8u, 0x00002000ul);
    assert(ResumeMainDataRingCursorFromLatestDescriptor() == 0u);
    assert(get_memory_big_endian_u32(0x126eu) == 0u);

    set_memory_big_endian_u32(0x80a8u, 0xfffffff0ul);
    assert(ResumeMainDataRingCursorFromLatestDescriptor() == 0x920ul);
    assert(get_memory_big_endian_u32(0x126eu) == 0x920ul);

    set_memory_big_endian_u32(0x80a8u, 1u);
    set_memory_big_endian_u32(0x156au, 0u);
    assert(ResumeMainDataRingCursorFromLatestDescriptor() == 0x931ul);
    assert(get_memory_big_endian_u32(0x126eu) == 0x931ul);
}

