static void test_initialize_and_acquire_raw_q_sequence_from_index1(void)
{
    unsigned result;

    for(result = 0u; result < 256u; ++result)
    {
        clear_memory(0xa5u);
        raw_q_sequence_test_active = 1u;
        raw_q_sequence_result = (u8)result;
        assert(InitializeAndAcquireRawQSequenceFromIndex1() == (u8)(result != 0u));
        assert(raw_q_sequence_call_count == 1u);
        assert(raw_q_sequence_first_index == 1u);
        assert(raw_q_sequence_saw_initialized_state == 1u);
        assert(firmware_memory[0x88b9ul] == 0u);
        assert(get_memory_big_endian_u16(0x8010u) == 10u);
        assert(firmware_memory[0x1281ul] == 0u);
        assert(firmware_memory[0x1282ul] == 0u);
        assert(firmware_memory[0x127eul] == 0u);
        assert(firmware_memory[0x1285ul] == 8u);
        if(result == 0u)
        {
            assert(firmware_memory[0x88b7ul] == 0u);
            assert(write_count == 9u);
            assert(write_trace[7] == 0x88b9ul);
            assert(write_trace[8] == 0x88b7ul);
        }
        else
        {
            assert(firmware_memory[0x88b7ul] == 0xa5u);
            assert(write_count == 8u);
            assert(write_trace[7] == 0x88b9ul);
        }
        assert(read_count == (result == 0u ? 0u : 6u));
    }
}

