static void test_apply_controller_progress_profile_transition(void)
{
    clear_memory(0u);
    controller_progress_transition_bypass = 0u;
    firmware_memory[0x0e43u] = 0x18u;
    firmware_memory[0x1302u] = 0xa5u;
    ApplyControllerProgressProfileTransition(7u, 0u, 1u);
    assert(controller_progress_transition_write_count == 1u && controller_progress_transition_written_profiles[0] == 7u && firmware_memory[0x1302u] == 0x25u);

    clear_memory(0u);
    controller_progress_transition_bypass = 0u;
    firmware_memory[0x0e43u] = 0x34u;
    firmware_memory[0x1302u] = 0x80u;
    ApplyControllerProgressProfileTransition(0u, 0u, 1u);
    assert(controller_progress_transition_write_count == 0u && firmware_memory[0x1302u] == 0x80u);

    clear_memory(0u);
    controller_progress_transition_bypass = 0u;
    firmware_memory[0x0e43u] = 0x28u;
    firmware_memory[0x1302u] = 0x80u;
    ApplyControllerProgressProfileTransition(2u, 1u, 0u);
    assert(controller_progress_transition_write_count == 0u && firmware_memory[0x1302u] == 0x80u);

    clear_memory(0u);
    controller_progress_transition_bypass = 0u;
    firmware_memory[0x0e43u] = 0x28u;
    firmware_memory[0x1302u] = 0x80u;
    ApplyControllerProgressProfileTransition(1u, 1u, 0u);
    assert(controller_progress_transition_write_count == 1u && controller_progress_transition_written_profiles[0] == 1u && firmware_memory[0x1302u] == 0u);

    clear_memory(0u);
    controller_progress_transition_bypass = 0u;
    firmware_memory[0x0e43u] = 0x34u;
    firmware_memory[0xff907fu] = 0xa7u;
    ApplyControllerProgressProfileTransition(5u, 0u, 0u);
    assert(controller_progress_transition_write_count == 1u && controller_progress_transition_written_profiles[0] == 0xa7u && firmware_memory[0x1302u] == 0x80u
           && controller_progress_transition_wait_count == 0u);

    clear_memory(0u);
    controller_progress_transition_bypass = 0u;
    firmware_memory[0x0e43u] = 0x28u;
    ApplyControllerProgressProfileTransition(7u, 2u, 0u);
    assert(controller_progress_transition_write_count == 1u && controller_progress_transition_written_profiles[0] == 8u && firmware_memory[0x1302u] == 0x80u);

    clear_memory(0u);
    controller_progress_transition_bypass = 0u;
    firmware_memory[0x0e43u] = 0x28u;
    firmware_memory[0x0e4du] = 0x20u;
    firmware_memory[0x103au] = 0x20u;
    controller_progress_transition_complete_after_yields = 2u;
    ApplyControllerProgressProfileTransition(9u, 3u, 1u);
    assert(controller_progress_transition_yield_count == 2u && firmware_memory[0x1220u] == 3u && firmware_memory[0x0e3fu] == 1u);
    assert(controller_progress_transition_write_count == 1u && controller_progress_transition_written_profiles[0] == 9u && controller_progress_transition_wait_count == 1u
           && controller_progress_transition_wait_duration == 200u && controller_progress_transition_wait_yield == 0u && controller_progress_transition_event_count == 4u
           && memcmp(controller_progress_transition_events, "YYPW", 4u) == 0);

    clear_memory(0u);
    controller_progress_transition_bypass = 0u;
    firmware_memory[0x0e43u] = 0x28u;
    firmware_memory[0x0e4du] = 0x20u;
    firmware_memory[0x1302u] = 0x80u;
    ApplyControllerProgressProfileTransition(6u, 3u, 1u);
    assert(
        controller_progress_transition_yield_count == 0u && controller_progress_transition_write_count == 1u && controller_progress_transition_wait_count == 0u && firmware_memory[0x1302u] == 0x80u);

    clear_memory(0u);
    controller_progress_transition_bypass = 0u;
    firmware_memory[0x0e43u] = 0x28u;
    firmware_memory[0x0e4du] = 0x20u;
    ApplyControllerProgressProfileTransition(6u, 3u, 1u);
    assert(controller_progress_transition_yield_count == 0u && controller_progress_transition_write_count == 1u && controller_progress_transition_wait_count == 1u);
}

static void test_update_controller_profile_from_read_acquisition_target(void)
{
    static const struct profile_case
    {
        u8 operating_code;
        fw_addr_t table;
    } cases[] = {
        { 0x18u, 0x00ff904eul },
        { 0x20u, 0x00ff905eul },
        { 0x28u, 0x00ff906eul },
        { 0x34u, 0x00ff907eul }
    };
    unsigned index;

    for(index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index)
    {
        clear_memory(0u);
        set_memory_big_endian_u32(0x0e3bu, 25ul * 4500ul);
        firmware_memory[0x125cu] = 24u;
        firmware_memory[0x0e43u] = cases[index].operating_code;
        firmware_memory[cases[index].table + 5u] = (u8)(0x80u + index);
        UpdateControllerProfileFromReadAcquisitionTarget();
        assert(controller_progress_transition_call_count == 1u && controller_progress_transition_profile == (u8)(0x80u + index) && controller_progress_transition_bucket == 5u
               && controller_progress_transition_mode == 0u);
        assert(read_count == 11u && read_trace[0] == 0x0e3bul && read_trace[3] == 0x0e3eul && read_trace[4] == 0x0e3bul && read_trace[7] == 0x0e3eul && read_trace[8] == 0x125cul
               && read_trace[9] == 0x0e43ul && read_trace[10] == cases[index].table + 5u);
    }

    clear_memory(0u);
    set_memory_big_endian_u32(0x0e3bu, 25ul * 4500ul);
    firmware_memory[0x125cu] = 25u;
    UpdateControllerProfileFromReadAcquisitionTarget();
    assert(controller_progress_transition_call_count == 0u && read_count == 9u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x0e3bu, 0xfffffffful);
    firmware_memory[0x125cu] = 1u;
    firmware_memory[0x0e43u] = 0x18u;
    firmware_memory[0x00ff904eul] = 0x42u;
    UpdateControllerProfileFromReadAcquisitionTarget();
    assert(controller_progress_transition_call_count == 1u && controller_progress_transition_profile == 0x42u && controller_progress_transition_bucket == 0u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x0e3bu, 250ul * 4500ul);
    firmware_memory[0x125cu] = 0u;
    firmware_memory[0x0e43u] = 0x20u;
    firmware_memory[0x00ff905eul + 15u] = 0x77u;
    UpdateControllerProfileFromReadAcquisitionTarget();
    assert(controller_progress_transition_call_count == 1u && controller_progress_transition_profile == 0x77u && controller_progress_transition_bucket == 15u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x0e3bu, 256ul * 4500ul);
    firmware_memory[0x125cu] = 1u;
    firmware_memory[0x0e43u] = 0x34u;
    firmware_memory[0x00ff907eul] = 0x99u;
    UpdateControllerProfileFromReadAcquisitionTarget();
    assert(controller_progress_transition_call_count == 1u && controller_progress_transition_profile == 0x99u && controller_progress_transition_bucket == 0u);
}

static void test_update_controller_word035f_from_progress_bucket(void)
{
    static const struct progress_case
    {
        u8 operating_code;
        u8 progress;
        u8 bucket;
        fw_addr_t word_address;
        fw_addr_t table_address;
        u16 word;
        u8 profile;
    } cases[] = {
        { 0x18u, 0u,  0u,  0x0cebul, 0xff904eul, 0x1234u, 0x81u },
        { 0x20u, 25u, 5u,  0x0cedul, 0xff905eul, 0x2345u, 0x82u },
        { 0x28u, 74u, 14u, 0x0ceful, 0xff906eul, 0x3456u, 0x83u },
        { 0x34u, 80u, 15u, 0x0cf3ul, 0xff907eul, 0x4567u, 0x84u }
    };
    unsigned index;

    clear_memory(0u);
    firmware_memory[0x1006u] = 1u;
    firmware_memory[0x0e43u] = 0x20u;
    UpdateControllerWord035FFromProgressBucket();
    assert(controller_progress_word_submit_count == 0u && controller_progress_transition_call_count == 0u && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0e43u] = 0x17u;
    UpdateControllerWord035FFromProgressBucket();
    assert(controller_progress_word_submit_count == 0u && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0e43u] = 0x20u;
    firmware_memory[0x0e4du] = 0x20u;
    firmware_memory[0x125cu] = 25u;
    firmware_memory[0x125du] = 25u;
    UpdateControllerWord035FFromProgressBucket();
    assert(controller_progress_word_submit_count == 0u && write_count == 0u);

    for(index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index)
    {
        clear_memory(0u);
        firmware_memory[0x0e43u] = cases[index].operating_code;
        firmware_memory[0x0e4du] = 0u;
        firmware_memory[0x125cu] = cases[index].progress;
        firmware_memory[0x125du] = 0xffu;
        set_memory_big_endian_u16((u16)cases[index].word_address, cases[index].word);
        firmware_memory[cases[index].table_address + cases[index].bucket] = cases[index].profile;
        UpdateControllerWord035FFromProgressBucket();
        assert(controller_progress_word_submit_count == 1u && controller_progress_word_value == cases[index].word && controller_progress_word_selector == 0x035fu);
        assert(controller_progress_transition_call_count == 1u && controller_progress_transition_profile == cases[index].profile && controller_progress_transition_bucket == cases[index].bucket
               && controller_progress_transition_mode == 1u);
        assert(firmware_memory[0x125du] == cases[index].progress);
    }

    clear_memory(0u);
    controller_progress_inherited_dr12 = 0xbeef00ccul;
    firmware_memory[0x0e43u] = 0x19u;
    firmware_memory[0x0e4du] = 0x18u;
    firmware_memory[0x125cu] = 10u;
    firmware_memory[0x125du] = 9u;
    UpdateControllerWord035FFromProgressBucket();
    assert(controller_progress_word_submit_count == 1u && controller_progress_word_value == 0xbeefu && controller_progress_word_selector == 0x035fu);
    assert(controller_progress_transition_call_count == 1u && controller_progress_transition_profile == 0xccu && controller_progress_transition_bucket == 2u
           && controller_progress_transition_mode == 1u && firmware_memory[0x125du] == 10u);
}

static void test_map_logical_block_address_to_controller_frame_position(void)
{
    s32 result;

    clear_memory(0u);
    bit_001b = 1u;
    result = MapLogicalBlockAddressToControllerFramePositionForTest(-5l);
    assert(result == lba_mapping_track_result && lba_mapping_route == 1u && lba_mapping_route_input == -5l && bit_001b == 0u && read_count == 1u && read_trace[0] == 0x0015d7ul);

    clear_memory(0u);
    firmware_memory[0x15d7u] = 1u;
    firmware_memory[0x0c88u] = 0x80u;
    result = MapLogicalBlockAddressToControllerFramePositionForTest(-1l);
    assert(result == lba_mapping_negative_result && lba_mapping_route == 2u && lba_mapping_route_input == -1l && bit_001b == 1u);

    clear_memory(0u);
    bit_001b = 1u;
    firmware_memory[0x15d7u] = 1u;
    firmware_memory[0x0c88u] = 0x80u;
    result = MapLogicalBlockAddressToControllerFramePositionForTest(0l);
    assert(result == lba_mapping_track_result && lba_mapping_route == 1u && bit_001b == 0u);

    clear_memory(0u);
    firmware_memory[0x15d7u] = 1u;
    firmware_memory[0x0c88u] = 0u;
    result = MapLogicalBlockAddressToControllerFramePositionForTest(-1l);
    assert(result == lba_mapping_track_result && lba_mapping_route == 1u && bit_001b == 0u && read_count == 2u);

    clear_memory(0u);
    firmware_memory[0x15d7u] = 1u;
    firmware_memory[0x0c88u] = 0u;
    set_memory_big_endian_u32_far(0x2ba529ul, 100ul);
    result = MapLogicalBlockAddressToControllerFramePositionForTest(101l);
    assert(result == lba_mapping_track_result && lba_mapping_route == 1u && lba_mapping_route_input == 101l && bit_001b == 0u);

    clear_memory(0u);
    firmware_memory[0x15d7u] = 1u;
    firmware_memory[0x0c88u] = 0u;
    set_memory_big_endian_u32_far(0x2ba529ul, 100ul);
    result = MapLogicalBlockAddressToControllerFramePositionForTest(100l);
    assert(result == lba_mapping_alternate_result && lba_mapping_route == 3u && lba_mapping_route_input == 100l && bit_001b == 0u);

    clear_memory(0u);
    firmware_memory[0x15d7u] = 1u;
    firmware_memory[0x0c88u] = 0u;
    set_memory_big_endian_u32_far(0x2ba529ul, 0x7ffffffful);
    result = MapLogicalBlockAddressToControllerFramePositionForTest(0l);
    assert(result == lba_mapping_alternate_result && lba_mapping_route == 3u && read_count == 6u && read_trace[2] == 0x2ba529ul && read_trace[5] == 0x2ba52cul);
}

static void test_handle_read_master_cue_command(void)
{
    u32 base_position;
    u32 start_position;

    clear_memory(0u);
    firmware_memory[0xff8d21ul] = 2u;
    firmware_memory[0xff8d23ul] = 1u;
    firmware_memory[0x000b0bul] = 1u;
    HandleReadMasterCueCommand();
    assert(firmware_memory[0x000b18ul] == 0x70u);
    assert(firmware_memory[0x000b1aul] == 5u);
    assert(firmware_memory[0x000b24ul] == 0x24u);
    assert(get_memory_big_endian_u32(0x000b06ul) == 0ul);
    assert(read_master_cue_response_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0xff8d21ul] = 2u;
    firmware_memory[0xff8d23ul] = 0u;
    set_memory_big_endian_u32(0x0b10u, 0x00000700ul);
    HandleReadMasterCueCommand();
    assert(get_memory_big_endian_u32(0x000b06ul) == 7ul);
    assert(firmware_memory[0x000b24ul] == 0x24u);
    assert(read_master_cue_response_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0xff8d21ul] = 2u;
    firmware_memory[0xff8d23ul] = 0u;
    set_memory_big_endian_u32(0x0b10u, 0x000008fful);
    base_position = 100ul;
    start_position = base_position + 0x1b76ul;
    set_memory_big_endian_u32(0x12c1u, base_position);
    set_memory_big_endian_u32(0x1153u, base_position + 0x1c0cul);
    HandleReadMasterCueCommand();
    assert(get_memory_big_endian_u32(0x000b06ul) == 8ul);
    assert(get_memory_big_endian_u32(0x000b02ul) == start_position);
    assert(read_master_cue_response_call_count == 1u);
    assert(firmware_memory[0x000b18ul] == 0u);

    clear_memory(0u);
    firmware_memory[0xff8d21ul] = 2u;
    firmware_memory[0xff8d23ul] = 0u;
    set_memory_big_endian_u32(0x0b10u, 0xffffff00ul);
    base_position = 0x12345678ul;
    start_position = base_position + 0x1b76ul;
    set_memory_big_endian_u32(0x12c1u, base_position);
    set_memory_big_endian_u32(0x1153u, base_position + 0x1c0bul);
    HandleReadMasterCueCommand();
    assert(get_memory_big_endian_u32(0x000b06ul) == 0x00fffffful);
    assert(get_memory_big_endian_u32(0x000b02ul) == start_position);
    assert(firmware_memory[0x000b18ul] == 0xf0u);
    assert(firmware_memory[0x000b1aul] == 5u);
    assert(firmware_memory[0x000b24ul] == 0x21u);
    assert(firmware_memory[0x000b25ul] == 0u);
    assert(get_memory_big_endian_u32(0x000b1bul) == start_position + 20ul);
    assert(read_master_cue_response_call_count == 0u);

    clear_memory(0u);
    firmware_memory[0xff8d21ul] = 2u;
    firmware_memory[0xff8d23ul] = 0u;
    set_memory_big_endian_u32(0x0b10u, 0x00000800ul);
    base_position = 0x7fffe400ul;
    set_memory_big_endian_u32(0x12c1u, base_position);
    set_memory_big_endian_u32(0x1153u, 0x7ffffffful);
    HandleReadMasterCueCommand();
    assert(get_memory_big_endian_u32(0x000b02ul) == base_position + 0x1b76ul);
    assert(read_master_cue_response_call_count == 1u);
}

static void test_finalize_decoded_toc_lead_out_record(void)
{
    static const u8 last_tracks[] = { 0u, 0xfeu, 0xffu };
    unsigned track_case;

    for(track_case = 0u; track_case < sizeof(last_tracks); ++track_case)
    {
        u8 last_track = last_tracks[track_case];
        fw_addr_t record = 0xf2b6ul + (fw_addr_t)((u8)(last_track + 1u) * 6u);

        clear_memory(0xa5u);
        set_memory_big_endian_u32(0x12d4u, 0x12345678ul);
        firmware_memory[0xfc1au] = last_track;
        firmware_memory[0xf546u] = 0x91u;
        firmware_memory[0xf54du] = 0x22u;
        firmware_memory[0xf54eu] = 0x33u;
        firmware_memory[0xf54fu] = 0x44u;
        read_count = write_count = 0u;
        FinalizeDecodedTocLeadOutRecord();
        assert(get_memory_big_endian_u32(0x12c1u) == 0x12345678ul);
        assert(firmware_memory[0x12c0u] == last_track);
        assert(firmware_memory[record] == 0xaau);
        assert(firmware_memory[record + 1u] == 0x91u);
        assert(firmware_memory[record + 2u] == 0u);
        assert(firmware_memory[record + 3u] == 0x22u);
        assert(firmware_memory[record + 4u] == 0x33u);
        assert(firmware_memory[record + 5u] == 0x44u);
        assert(read_count == 10u && write_count == 11u);
        assert(read_trace[0] == 0x12d4u && read_trace[3] == 0x12d7u);
        assert(read_trace[4] == 0xfc1au && read_trace[5] == 0xfc1au);
        assert(write_trace[4] == 0x12c0u && write_trace[5] == record);
        assert(write_trace[10] == record + 5u);
    }

    clear_memory(0xa5u);
    firmware_memory[0xfc1au] = 2u;
    write_mutation_enabled = 1u;
    write_mutation_trigger = 0x12c0u;
    write_mutation_target = 0xfc1au;
    write_mutation_value = 4u;
    FinalizeDecodedTocLeadOutRecord();
    assert(firmware_memory[0x12c0u] == 2u);
    assert(firmware_memory[0xf2d4u] == 0xaau);
    assert(firmware_memory[0xf2c8u] == 0xa5u);
}

static void test_append_get_performance_descriptor_from_four_u32_values(void)
{
    static const u16 cursors[] = { 0u, 0x10u, 0xfff8u };
    static const u32 values[] = { 0x11223344ul, 0x55667788ul, 0x99aabbccul, 0xddeeff00ul };
    unsigned cursor_case;

    for(cursor_case = 0u; cursor_case < sizeof(cursors) / sizeof(cursors[0]); ++cursor_case)
    {
        u16 cursor = cursors[cursor_case];
        u16 base = (u16)(0x0b2au + cursor);
        unsigned field;

        clear_memory(0xa5u);
        assert(AppendGetPerformanceDescriptorFromFourU32Values(cursor, values[0], values[1], values[2], values[3]) == (u16)(cursor + 16u));
        assert(read_count == 0u && write_count == 16u);
        for(field = 0u; field < 4u; ++field)
        {
            u16 address = (u16)(base + (u16)(field * 4u));
            unsigned trace = field * 4u;

            assert(get_memory_big_endian_u32(address) == values[field]);
            assert(write_trace[trace] == (u16)(address + 2u));
            assert(write_values[trace] == (u8)(values[field] >> 8));
            assert(write_trace[trace + 1u] == (u16)(address + 3u));
            assert(write_values[trace + 1u] == (u8)values[field]);
            assert(write_trace[trace + 2u] == address);
            assert(write_values[trace + 2u] == (u8)(values[field] >> 24));
            assert(write_trace[trace + 3u] == (u16)(address + 1u));
            assert(write_values[trace + 3u] == (u8)(values[field] >> 16));
        }
    }
}

static void test_append_get_performance_nominal_speed_descriptor(void)
{
    static const u8 speed_codes[] = { 4u, 8u, 24u, 32u, 40u, 52u };
    static const u32 start_rates[] = { 0x02c2ul, 0x0583ul, 0x06e4ul, 0x09a6ul, 0x0bb7ul, 0x0f29ul };
    static const u32 end_rates[] = { 0x02c2ul, 0x0583ul, 0x108aul, 0x160dul, 0x1b90ul, 0x23d5ul };
    unsigned speed_case;

    for(speed_case = 0u; speed_case < sizeof(speed_codes); ++speed_case)
    {
        clear_memory(0xa5u);
        assert(AppendGetPerformanceNominalSpeedDescriptor(speed_codes[speed_case], 1u, 0x20u) == 0x30u);
        assert(get_memory_big_endian_u32(0x0b4au) == 0ul);
        assert(get_memory_big_endian_u32(0x0b4eu) == start_rates[speed_case]);
        assert(get_memory_big_endian_u32(0x0b52u) == 359999ul);
        assert(get_memory_big_endian_u32(0x0b56u) == end_rates[speed_case]);
        assert(read_count == 0u && write_count == 16u);
    }

    clear_memory(0xa5u);
    assert(AppendGetPerformanceNominalSpeedDescriptor(0xffu, 0u, 0xfff8u) == 0xfff8u);
    assert(read_count == 0u && write_count == 0u);

    clear_memory(0u);
    assert(AppendGetPerformanceNominalSpeedDescriptor(0xffu, 1u, 0u) == 16u);
    assert(get_memory_big_endian_u32(0x0b2eu) == 0x0bb7ul && get_memory_big_endian_u32(0x0b36u) == 0x1b90ul);
    assert(read_count == 2u);

    clear_memory(0u);
    firmware_memory[0x0c88u] = 4u;
    assert(AppendGetPerformanceNominalSpeedDescriptor(0u, 1u, 0u) == 16u);
    assert(get_memory_big_endian_u32(0x0b2eu) == 0x0f29ul && get_memory_big_endian_u32(0x0b36u) == 0x23d5ul);
    assert(read_count == 1u);

    clear_memory(0u);
    firmware_memory[0xfaedu] = 4u;
    assert(AppendGetPerformanceNominalSpeedDescriptor(1u, 1u, 0u) == 16u);
    assert(get_memory_big_endian_u32(0x0b2eu) == 0x0f29ul && get_memory_big_endian_u32(0x0b36u) == 0x23d5ul);
    assert(read_count == 2u);
}

static void test_append_get_performance_write_speed_descriptors(void)
{
    static const u8 speed_codes[] = { 4u, 8u, 10u, 12u, 16u, 0u, 52u, 99u };
    static const u32 start_rates[] = { 0x02c2ul, 0x0583ul, 0x06e4ul, 0x0845ul, 0x0b06ul, 0x0f29ul, 0x0f29ul, 0x0f29ul };
    static const u32 end_rates[] = { 0x02c2ul, 0x0583ul, 0x06e4ul, 0x0845ul, 0x0b06ul, 0x23d5ul, 0x23d5ul, 0x23d5ul };
    unsigned speed_case;

    clear_memory(0xa5u);
    assert(AppendGetPerformanceWriteSpeedDescriptorsForSpeed(24u, 0xfff8u, 0u) == 0xfff8u);
    assert(read_count == 0u && write_count == 0u);

    for(speed_case = 0u; speed_case < sizeof(speed_codes); ++speed_case)
    {
        clear_memory(0xa5u);
        assert(AppendGetPerformanceWriteSpeedDescriptorsForSpeed(speed_codes[speed_case], 0x20u, 1u) == 0x30u);
        assert(get_memory_big_endian_u32(0x0b4au) == 0ul);
        assert(get_memory_big_endian_u32(0x0b4eu) == start_rates[speed_case]);
        assert(get_memory_big_endian_u32(0x0b52u) == 359999ul);
        assert(get_memory_big_endian_u32(0x0b56u) == end_rates[speed_case]);
        assert(read_count == 0u && write_count == 16u);
    }

    clear_memory(0u);
    set_memory_big_endian_u32(0xf9eeu, 0x00123456ul);
    read_count = write_count = 0u;
    assert(AppendGetPerformanceWriteSpeedDescriptorsForSpeed(24u, 0u, 1u) == 16u);
    assert(get_memory_big_endian_u32(0x0b2au) == 0ul);
    assert(get_memory_big_endian_u32(0x0b2eu) == 0x0e78ul);
    assert(get_memory_big_endian_u32(0x0b32u) == 0x00123455ul);
    assert(get_memory_big_endian_u32(0x0b36u) == 0x108aul);
    assert(read_count == 4u && write_count == 16u);

    clear_memory(0u);
    set_memory_big_endian_u32(0xf9f2u, 0ul);
    read_count = write_count = 0u;
    assert(AppendGetPerformanceWriteSpeedDescriptorsForSpeed(32u, 0u, 2u) == 32u);
    assert(get_memory_big_endian_u32(0x0b32u) == 0xfffffffful);
    assert(get_memory_big_endian_u32(0x0b3au) == 0ul);
    assert(get_memory_big_endian_u32(0x0b3eu) == 0x160dul);
    assert(get_memory_big_endian_u32(0x0b42u) == 359999ul);
    assert(get_memory_big_endian_u32(0x0b46u) == 0x160dul);
    assert(read_count == 8u && write_count == 32u);

    clear_memory(0u);
    set_memory_big_endian_u32(0xf9eeu, 0x12345678ul);
    read_count = write_count = 0u;
    assert(AppendGetPerformanceWriteSpeedDescriptorsForSpeed(24u, 0xeec4u, 2u) == 0xeee4u);
    assert(get_memory_big_endian_u32(0xf9feu) == 0ul);
    assert(read_count == 8u && write_count == 32u);
}

static void test_append_get_performance_descriptor_from_table_record(void)
{
    fw_addr_t record = 0x12fffeul;

    clear_memory(0u);
    firmware_memory[0x120000u] = 0x81u;
    firmware_memory[0x120001u] = 0x12u;
    firmware_memory[0x120002u] = 0x34u;
    firmware_memory[0x0c43u] = 8u;
    firmware_memory[0x0c85u] = 2u;
    firmware_memory[0x0faeu] = 0u;
    firmware_memory[0x1008u] = 2u;
    set_memory_big_endian_u32(0x1153u, 0x12345678ul);
    read_count = write_count = 0u;
    assert(AppendGetPerformanceDescriptorFromTableRecord(record, 0x20u, 0u) == 0x30u);
    assert(firmware_memory[0x0b4au] == 8u);
    assert(get_memory_big_endian_u32(0x0b4eu) == 0x12345678ul);
    assert(get_memory_big_endian_u32(0x0b52u) == 0x1234ul);
    assert(get_memory_big_endian_u32(0x0b56u) == 0x0583ul);
    assert(read_trace[0] == 0x120001ul && read_trace[1] == 0x120002ul && read_trace[2] == 0x120000ul);

    clear_memory(0u);
    firmware_memory[0x2002u] = 0u;
    firmware_memory[0x2003u] = 0x02u;
    firmware_memory[0x2004u] = 0xc3u;
    firmware_memory[0x158eu] = 1u;
    firmware_memory[0x158du] = 1u;
    assert(AppendGetPerformanceDescriptorFromTableRecord(0x2000ul, 7u, 0xffffu) == 7u);
    assert(write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x2003u] = 0x05u;
    firmware_memory[0x2004u] = 0x83u;
    firmware_memory[0x158eu] = 1u;
    firmware_memory[0x158du] = 2u;
    assert(AppendGetPerformanceDescriptorFromTableRecord(0x2000ul, 0u, 0u) == 16u);

    clear_memory(0u);
    firmware_memory[0x2003u] = 0x05u;
    firmware_memory[0x2004u] = 0x83u;
    firmware_memory[0x158eu] = 1u;
    firmware_memory[0x158du] = 2u;
    firmware_memory[0xf9e9u] = 1u;
    assert(AppendGetPerformanceDescriptorFromTableRecord(0x2000ul, 9u, 0xffffu) == 9u);
    assert(write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x2003u] = 0x0fu;
    firmware_memory[0x2004u] = 0xffu;
    assert(AppendGetPerformanceDescriptorFromTableRecord(0x2000ul, 0u, 0x1000u) == 16u);

    clear_memory(0u);
    firmware_memory[0x2003u] = 0x10u;
    firmware_memory[0x2004u] = 0x01u;
    assert(AppendGetPerformanceDescriptorFromTableRecord(0x2000ul, 5u, 0x1000u) == 5u);
    assert(write_count == 0u);
}

static void test_append_get_performance_descriptor_with_flags(void)
{
    static const u8 flags[] = { 0u, 1u, 0x1fu, 0x20u, 0xffu };
    static const u32 values[] = { 0x12345678ul, 0x90abcdeful, 0x55aa00fful };
    unsigned flag_case;

    for(flag_case = 0u; flag_case < sizeof(flags); ++flag_case)
    {
        u16 cursor = flag_case == sizeof(flags) - 1u ? 0xfff8u : 0x20u;
        u16 base = (u16)(0x0b2au + cursor);
        unsigned field;

        clear_memory(0xa5u);
        assert(AppendGetPerformanceDescriptorWithFlagsAndThreeU32Values(flags[flag_case], cursor, values[0], values[1], values[2]) == (u16)(cursor + 16u));
        assert(read_count == 0u && write_count == 17u);
        assert(firmware_memory[base] == (u8)(flags[flag_case] << 3));
        assert(firmware_memory[(u16)(base + 1u)] == 0u);
        assert(firmware_memory[(u16)(base + 2u)] == 0u);
        assert(firmware_memory[(u16)(base + 3u)] == 0u);
        assert(write_trace[0] == (u16)(base + 2u));
        assert(write_trace[1] == (u16)(base + 3u));
        assert(write_trace[2] == base);
        assert(write_trace[3] == (u16)(base + 1u));
        assert(write_trace[4] == base);
        assert(write_values[4] == (u8)(flags[flag_case] << 3));
        for(field = 0u; field < 3u; ++field)
        {
            u16 address = (u16)(base + 4u + (u16)(field * 4u));
            unsigned trace = 5u + field * 4u;

            assert(get_memory_big_endian_u32(address) == values[field]);
            assert(write_trace[trace] == (u16)(address + 2u));
            assert(write_trace[trace + 1u] == (u16)(address + 3u));
            assert(write_trace[trace + 2u] == address);
            assert(write_trace[trace + 3u] == (u16)(address + 1u));
        }
    }
}

static void test_find_first_track_number_for_last_full_toc_session(void)
{
    fw_addr_t descriptor1 = 0x2b800bul;
    fw_addr_t descriptor2 = 0x2b8016ul;
    fw_addr_t descriptor3 = 0x2b8021ul;

    clear_memory(0u);
    assert(FindFirstTrackNumberForLastFullTocSession() == 1u);
    assert(read_count == 2u && read_trace[0] == 0x12caul && read_trace[1] == 0x12cbul && write_count == 0u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x12cau, 33u);
    firmware_memory[0x12c9u] = 3u;
    firmware_memory[descriptor1] = 2u;
    firmware_memory[descriptor2] = 3u;
    firmware_memory[descriptor2 + 3u] = 100u;
    firmware_memory[descriptor3] = 3u;
    firmware_memory[descriptor3 + 3u] = 7u;
    read_count = write_count = 0u;
    assert(FindFirstTrackNumberForLastFullTocSession() == 7u);
    assert(read_count == 11u && write_count == 0u);
    assert(read_trace[2] == descriptor1 && read_trace[3] == 0x12c9ul);
    assert(read_trace[4] == descriptor2 && read_trace[5] == 0x12c9ul && read_trace[6] == descriptor2 + 3u);
    assert(read_trace[7] == descriptor3 && read_trace[8] == 0x12c9ul && read_trace[9] == descriptor3 + 3u && read_trace[10] == descriptor3 + 3u);

    clear_memory(0u);
    set_memory_big_endian_u16(0x12cau, 32u);
    firmware_memory[0x12c9u] = 1u;
    firmware_memory[descriptor3] = 1u;
    firmware_memory[descriptor3 + 3u] = 9u;
    read_count = write_count = 0u;
    assert(FindFirstTrackNumberForLastFullTocSession() == 1u);
    assert(read_count == 6u && write_count == 0u);
}

static void assert_eleven_byte_runtime_record_cleared(u8 record_index)
{
    fw_addr_t record = 0x0ccbul + (fw_addr_t)(record_index * 11u);
    unsigned offset;

    for(offset = 0u; offset < 11u; ++offset)
        assert(firmware_memory[record + offset] == (offset == 9u ? 0xa4u : 0u));
}

static void test_clear_eleven_byte_runtime_state_records(void)
{
    static const u8 write_offsets[] = { 7u, 9u, 10u, 8u, 6u, 5u, 4u, 3u, 2u, 1u, 0u };
    fw_addr_t record;
    unsigned index;

    clear_memory(0xa5u);
    ClearElevenByteRuntimeStateRecordAndAdvanceIndex(2u);
    record = 0x0ccbu + 22u;
    assert_eleven_byte_runtime_record_cleared(2u);
    assert(read_count == 1u && read_trace[0] == record + 9u);
    assert(write_count == 11u);
    for(index = 0u; index < 11u; ++index)
        assert(write_trace[index] == record + write_offsets[index]);

    clear_memory(0xa5u);
    ClearElevenByteRuntimeStateRecordAndAdvanceIndex(255u);
    assert_eleven_byte_runtime_record_cleared(255u);
    assert_eleven_byte_runtime_record_cleared(0u);
    assert_eleven_byte_runtime_record_cleared(1u);
    assert(read_count == 3u && write_count == 33u);

    clear_memory(0xa5u);
    ClearTwoElevenByteRuntimeStateRecordsFromIndex(2u);
    assert(read_count == 0u && write_count == 0u);
    ClearTwoElevenByteRuntimeStateRecordsFromIndex(1u);
    assert_eleven_byte_runtime_record_cleared(1u);
    assert(read_count == 1u && write_count == 11u);

    clear_memory(0xa5u);
    ClearTwoElevenByteRuntimeStateRecords();
    assert_eleven_byte_runtime_record_cleared(0u);
    assert_eleven_byte_runtime_record_cleared(1u);
    assert(read_count == 2u && write_count == 22u);
}

static void test_prepare_controller_event_bit4_operating_update(void)
{
    clear_memory(0u);
    firmware_memory[0xfadu] = 0xffu;
    firmware_memory[0xefeu] = 0xffu;
    firmware_memory[0xeffu] = 0xffu;
    firmware_memory[0x154du] = 1u;
    bit_0032 = 1u;
    PrepareControllerEventBit4OperatingUpdate();
    assert(firmware_memory[0xfadu] == 0xefu && firmware_memory[0x18003u] == 0xefu);
    assert(firmware_memory[0xefeu] == 0x1fu && firmware_memory[0x18018u] == 0x1fu);
    assert(firmware_memory[0xeffu] == 0xefu && firmware_memory[0x18019u] == 0xefu);
    assert(firmware_memory[0xfb9fu] == 2u);
    assert(read_count == 4u && write_count == 7u);

    clear_memory(0u);
    firmware_memory[0xfadu] = 0x5au;
    firmware_memory[0xefeu] = 0xa5u;
    firmware_memory[0xeffu] = 0x3cu;
    firmware_memory[0xfcau] = 0xa5u;
    firmware_memory[0x1157u] = 2u;
    PrepareControllerEventBit4OperatingUpdate();
    assert(firmware_memory[0xfb9fu] == 0u);
    assert(firmware_memory[0x180c0u] == 0u);
    assert(firmware_memory[0x180cfu] == 4u);
    assert(firmware_memory[0x180c3u] == 0x60u);
    assert(firmware_memory[0xfcau] == 0xa5u && firmware_memory[0x8002u] == 0xa5u);
    assert(read_count == 8u && write_count == 14u);
    assert(write_trace[7] == 0xfcau && write_values[7] == 0xadu);
    assert(write_trace[8] == 0x8002u && write_values[8] == 0xadu);
    assert(write_trace[9] == 0x180c0u);
    assert(write_trace[10] == 0x180cfu && write_values[10] == 4u);
    assert(write_trace[11] == 0x180c3u && write_values[11] == 0x60u);
    assert(write_trace[12] == 0xfcau && write_values[12] == 0xa5u);
    assert(write_trace[13] == 0x8002u && write_values[13] == 0xa5u);
}

static void test_finalize_type2_mip_record_comparison_state(void)
{
    clear_memory(0u);
    firmware_memory[0x0c89u] = 0x12u;
    firmware_memory[0x0c8au] = 0xffu;
    firmware_memory[0x0c8bu] = 0xffu;
    FinalizeType2MipRecordComparisonState(1u);
    assert(firmware_memory[0x0c89u] == 0x92u);
    assert(firmware_memory[0x0c8au] == 0xfeu && firmware_memory[0x122cu] == 10u && firmware_memory[0x0c8bu] == 0xfbu);
    assert(read_count == 3u && write_count == 4u);

    clear_memory(0u);
    firmware_memory[0x0c89u] = 0x55u;
    firmware_memory[0x0c8au] = 0xffu;
    firmware_memory[0x0c8bu] = 0xffu;
    FinalizeType2MipRecordComparisonState(2u);
    assert(firmware_memory[0x0c89u] == 0x55u);
    assert(read_count == 2u && write_count == 3u);

    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2ba5a3ul, 0ul);
    firmware_memory[0x0c89u] = 0x01u;
    FinalizeType2MipRecordComparisonState(0u);
    assert(firmware_memory[0x0c89u] == 0x81u);
    assert(read_count == 7u && write_count == 4u);
    assert(read_trace[0] == 0x2ba5a5ul && read_trace[1] == 0x2ba5a6ul && read_trace[2] == 0x2ba5a3ul && read_trace[3] == 0x2ba5a4ul);

    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2ba5a3ul, 0x12345678ul);
    set_memory_big_endian_u32_far(0x2ba59ful, 0x12345678ul);
    firmware_memory[0x0c89u] = 0xffu;
    FinalizeType2MipRecordComparisonState(0u);
    assert(firmware_memory[0x0c89u] == 0x7fu);
    assert(read_count == 15u && write_count == 4u);
    assert(read_trace[4] == 0x2ba5a1ul && read_trace[7] == 0x2ba5a0ul);
    assert(read_trace[8] == 0x2ba5a5ul && read_trace[11] == 0x2ba5a4ul);

    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2ba5a3ul, 1ul);
    set_memory_big_endian_u32_far(0x2ba59ful, 2ul);
    FinalizeType2MipRecordComparisonState(0u);
    assert((firmware_memory[0x0c89u] & 0x80u) != 0u);

    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2ba5a3ul, 0x12345678ul);
    set_memory_big_endian_u32_far(0x2ba59ful, 0x12345678ul);
    assert(FinalizeType2MipRecordComparisonStateForBoundaryBuild(0u, 9u) == 0x78u);
    clear_memory(0u);
    assert(FinalizeType2MipRecordComparisonStateForBoundaryBuild(1u, 9u) == 9u);
}

