    assert(firmware_memory[0x18014u] == 0u && firmware_memory[0x18015u] == 0u && firmware_memory[0x18016u] == 0x0cu && firmware_memory[0x18017u] == 0u && firmware_memory[0x18030u] == 0u
           && firmware_memory[0x18031u] == 0u);
