static void test_validate_staged_firmware_checksum(void)
{
    clear_memory(0u);
    firmware_memory[0x100000ul] = 1u;
    firmware_memory[0x178000ul] = 2u;
    firmware_memory[0x179ffdul] = 3u;
    firmware_memory[0x179ffeul] = 0u;
    firmware_memory[0x179ffful] = 6u;
    read_count = 0u;
    assert(ValidateStagedFirmwareChecksum(0x00079ffeul, 0x0006fffful) == 1u);
    assert(read_trace[0] == 0x100000ul && read_trace[1] == 0x178000ul);
    assert(read_count == 0x2001u);
    firmware_memory[0x179ffful] = 7u;
    assert(ValidateStagedFirmwareChecksum(0x00079ffeul, 0x0006fffful) == 0u);

    clear_memory(0u);
    firmware_memory[0x100000ul] = 0xfeu;
    firmware_memory[0x10ff00ul] = 1u;
    firmware_memory[0x10fffdul] = 2u;
    firmware_memory[0x10fffeul] = 1u;
    firmware_memory[0x10fffful] = 1u;
    assert(ValidateStagedFirmwareChecksum(0x0000fffeul, 0x00007ffful) == 1u);

    clear_memory(0u);
    assert(ValidateStagedFirmwareChecksum(0x55ul, 0x00001234ul) == 1u);
    firmware_memory[0x1235u] = 1u;
    assert(ValidateStagedFirmwareChecksum(0x55ul, 0x00001234ul) == 0u);
}

static void test_validate_staged_firmware_checksum_full_range(void)
{
    u32 offset;
    u16 expected = 0u;

    clear_memory(0xa5u);
    for(offset = 0u; offset < 0x70000ul; ++offset)
    {
        u8 value = (u8)(offset * 29ul + 7ul);
        firmware_memory[0x100000ul + offset] = value;
        expected = (u16)(expected + value);
    }
    for(offset = 0u; offset < 0x1ffeul; ++offset)
    {
        u8 value = (u8)(offset * 13ul + 0x53ul);
        firmware_memory[0x178000ul + offset] = value;
        expected = (u16)(expected + value);
    }
    firmware_memory[0x179ffeul] = (u8)(expected >> 8);
    firmware_memory[0x179ffful] = (u8)expected;
    read_count = 0u;
    assert(ValidateStagedFirmwareChecksum(0x79ffeul, 0u) == 1u);
    assert(read_count == 0x72000u);
    assert(read_trace[0] == 0x100000ul);
    firmware_memory[0x16fffful] ^= 1u;
    assert(ValidateStagedFirmwareChecksum(0x79ffeul, 0u) == 0u);

    clear_memory(0xa5u);
    expected = 0u;
    for(offset = 0u; offset < 0x8000ul; ++offset)
    {
        u8 value = (u8)(offset * 11ul + 3ul);
        firmware_memory[0x100000ul + offset] = value;
        expected = (u16)(expected + value);
    }
    for(offset = 0u; offset < 0xfeul; ++offset)
    {
        u8 value = (u8)(offset * 17ul + 0x31ul);
        firmware_memory[0x10ff00ul + offset] = value;
        expected = (u16)(expected + value);
    }
    firmware_memory[0x10fffeul] = (u8)(expected >> 8);
    firmware_memory[0x10fffful] = (u8)expected;
    read_count = 0u;
    assert(ValidateStagedFirmwareChecksum(0xfffeul, 0u) == 1u);
    assert(read_count == 0x8100u);
    firmware_memory[0x10fffdul] ^= 1u;
    assert(ValidateStagedFirmwareChecksum(0xfffeul, 0u) == 0u);
}

static void test_update_opc_calibration_speed_class(void)
{
    unsigned mode;
    unsigned speed;

    for(mode = 0u; mode < 4u; ++mode)
    {
        for(speed = 0u; speed < 256u; ++speed)
        {
            u8 expected_class;
            u8 invalid;

            clear_memory(0u);
            firmware_memory[0x1008u] = mode == 0u ? 1u : 0u;
            firmware_memory[0xfb88u] = mode == 1u ? 2u : mode == 2u ? 1u : 0u;
            firmware_memory[0xe74eu] = 0xa5u;
            if(mode == 0u)
                expected_class = speed >= 16u ? 16u : speed >= 8u ? 8u : speed >= 4u ? 4u : 0u;
            else if(mode == 1u)
                expected_class = speed >= 24u ? 16u : 0u;
            else if(mode == 2u)
                expected_class = speed >= 10u ? 10u : speed >= 4u ? 4u : 0u;
            else
                expected_class = speed >= 4u ? 4u : 0u;
            invalid = (u8)(expected_class == 0u);
            UpdateOpcCalibrationSpeedClass((u8)speed);
            assert(firmware_memory[0xe74du] == expected_class);
            assert(firmware_memory[0xe74eu] == (invalid != 0u ? 0u : 0xa5u));
            assert(write_count == (invalid != 0u ? 2u : 1u));
        }
    }
}

static void test_raw_read_batch_transfer_product(void)
{
    static const u16 factors[] = { 0u, 1u, 2u, 255u, 256u, 0x7fffu, 0x8000u, 0xffffu };
    unsigned value, factor_case;
    clear_memory(0u);
    for(value = 0u; value < 65536u; ++value)
        for(factor_case = 0u; factor_case < 8u; ++factor_case)
        {
            set_memory_big_endian_u16(0x1463ul, factors[factor_case]);
            read_count = write_count = sfr_read_count = sfr_write_count = 0u;
            assert(FUN_RAM_fde9cf((u16)value) == (u32)((uint64_t)value * factors[factor_case]));
            assert(write_count == 2u && read_count == (value == 0u ? 0u : 2u));
            assert(write_trace[0] == 0xf18ul && write_values[0] == (u8)(value >> 8));
            assert(write_trace[1] == 0xf19ul && write_values[1] == (u8)value);
            assert(write_read_counts[0] == 0u && write_read_counts[1] == 0u);
            if(value != 0u)
                assert(read_trace[0] == 0x1463ul && read_trace[1] == 0x1464ul);
            assert(sfr_read_count == 0u && sfr_write_count == 0u);
        }
    set_memory_big_endian_u16(0x1463ul, 1u);
    write_mutation_enabled = 1u;
    write_mutation_trigger = 0xf19ul;
    write_mutation_target = 0x1464ul;
    write_mutation_value = 3u;
    read_count = write_count = 0u;
    assert(FUN_RAM_fde9cf(7u) == 21ul);
}

