static void test_validate_working_track_raw_q_state(void)
{
    static const u8 markers[] = { 0u, 0x90u, 0x91u, 0xffu };
    unsigned raw_class, mismatches, marker_case, signature, index;
    clear_memory(0u);
    for(raw_class = 0u; raw_class < 256u; ++raw_class)
        for(mismatches = 0u; mismatches < 16u; ++mismatches)
            for(marker_case = 0u; marker_case < 4u; ++marker_case)
                for(signature = 0u; signature < 4u; ++signature)
                {
                    unsigned class_code = raw_class & 3u;
                    u8 expected_mode = class_code != 2u ? 0x40u : (mismatches ? 0x20u : 0x10u);
                    u32 record = expected_mode == 0x10u ? 0x2bb925ul : 0x2bb91dul;
                    unsigned accepted = signature == 0u && (marker_case == 1u || marker_case == 2u);
                    unsigned expected_writes = 2u + (accepted ? (marker_case == 2u ? 6u : 2u) : 0u);
                    memset(firmware_memory + 0x2bb919ul, 0xa5, 32u);
                    firmware_memory[0x2bb91cul] = (u8)raw_class;
                    firmware_memory[0x2bb91dul] = 0x54u;
                    firmware_memory[0x2bb91eul] = 0x44u;
                    firmware_memory[0x2bb91ful] = 0x49u;
                    firmware_memory[0x2bb920ul] = 0x12u;
                    for(index = 0u; index < 4u; ++index)
                        firmware_memory[0x2bb921ul + index] = (u8)(firmware_memory[0x2bb91dul + index] ^ ((mismatches >> index) & 1u));
                    firmware_memory[record] = 0x54u;
                    firmware_memory[record + 1ul] = 0x44u;
                    firmware_memory[record + 2ul] = 0x49u;
                    if(signature != 0u)
                        firmware_memory[record + signature - 1ul] ^= 0x80u;
                    firmware_memory[record + 9ul] = markers[marker_case];
                    firmware_memory[record + 10ul] = 0x12u;
                    firmware_memory[record + 11ul] = 0x34u;
                    firmware_memory[record + 12ul] = 0x56u;
                    firmware_memory[0xdd55ul] = 0xa5u;
                    firmware_memory[0xdd56ul] = 0x5au;
                    set_memory_big_endian_u32(0xdd57ul, 0xdeadbeeful);
                    read_count = write_count = sfr_read_count = sfr_write_count = 0u;
                    assert(ValidateWorkingTrackRawQState() == accepted);
                    assert(firmware_memory[0xdd37ul] == class_code);
                    assert(firmware_memory[0xdd38ul] == expected_mode);
                    assert(write_count == expected_writes);
                    assert(write_trace[0] == 0xdd37ul && write_trace[1] == 0xdd38ul);
                    assert(sfr_read_count == 0u && sfr_write_count == 0u);
                    assert(firmware_memory[0xdd55ul] == (accepted ? 1u : 0xa5u));
                    assert(firmware_memory[0xdd56ul] == (accepted ? (marker_case == 2u) : 0x5au));
                    assert(get_memory_big_endian_u32(0xdd57ul) == (accepted && marker_case == 2u ? 123456ul : 0xdeadbeeful));
                    if(accepted && marker_case == 2u)
                    {
                        assert(read_trace[read_count - 4u] == record + 11ul);
                        assert(read_trace[read_count - 3u] == record + 12ul);
                        assert(read_trace[read_count - 2u] == record + 9ul);
                        assert(read_trace[read_count - 1u] == record + 10ul);
                    }
                }
    /* Equal class-two pairs with bit five set select mode eight. */
    firmware_memory[0x2bb91cul] = 2u;
    for(index = 0u; index < 4u; ++index)
    {
        firmware_memory[0x2bb91dul + index] = 0x20u;
        firmware_memory[0x2bb921ul + index] = 0x20u;
    }
    firmware_memory[0x2bb925ul] = 0x54u;
    firmware_memory[0x2bb926ul] = 0x44u;
    firmware_memory[0x2bb927ul] = 0x49u;
    firmware_memory[0x2bb92eul] = 0x91u;
    write_mutation_enabled = 1u;
    write_mutation_trigger = 0xdd55ul;
    write_mutation_target = 0x2bb92eul;
    write_mutation_value = 0x90u;
    read_count = write_count = 0u;
    assert(ValidateWorkingTrackRawQState() == 1u);
    assert(firmware_memory[0xdd38ul] == 8u);
    assert(firmware_memory[0xdd56ul] == 0u);
}

static void test_reject_incompatible_write_command(void)
{
    static const u32 sense_addresses[] = { 0xb18ul, 0xb1aul, 0xb24ul, 0xb25ul, 0xb1bul, 0xb1cul, 0xb1dul, 0xb1eul };
    static const u8 sense_values[] = { 0x70u, 5u, 0x30u, 0u, 0u, 0u, 0u, 0u };
    static const int deltas[] = { 214, -4, 249, 218, 177, 160 };
    unsigned opcode, initial, index;
    clear_memory(0u);
    for(opcode = 0u; opcode < 256u; ++opcode)
        for(initial = 0u; initial < 256u; ++initial)
        {
            u8 accumulator = (u8)opcode;
            unsigned reject = 0u;
            for(index = 0u; index < 6u; ++index)
            {
                accumulator = (u8)(accumulator + deltas[index]);
                if(accumulator == 0u)
                {
                    reject = 1u;
                    break;
                }
            }
            for(index = 0u; index < 8u; ++index)
                firmware_memory[sense_addresses[index]] = (u8)initial;
            firmware_memory[0xb0aul] = (u8)opcode;
            read_count = write_count = sfr_read_count = sfr_write_count = 0u;
            assert(RejectIncompatibleMediumWriteCommand() == !reject);
            assert(read_count == 1u && read_trace[0] == 0xb0aul);
            assert(write_count == (reject ? 8u : 0u));
            assert(sfr_read_count == 0u && sfr_write_count == 0u);
            for(index = 0u; index < 8u; ++index)
            {
                assert(firmware_memory[sense_addresses[index]] == (reject ? sense_values[index] : initial));
                if(reject)
                {
                    assert(write_trace[index] == sense_addresses[index]);
                    assert(write_values[index] == sense_values[index]);
                    assert(write_read_counts[index] == 1u);
                }
            }
        }
}

