static void test_limit_secondary_cursor_backlog(void)
{
    static const u32 raw_sizes[] = { 0ul, 5ul, 6ul, 7ul, 8ul, 10ul, 1024ul, 0x8006ul, 0x10005ul, 0xfffffffful };
    static const u16 masks[] = { 0xffffu, 0x7fffu, 0x3ffu };
    unsigned size_case, mask_case, cursor;
    clear_memory(0u);
    for(size_case = 0u; size_case < sizeof(raw_sizes) / sizeof(raw_sizes[0]); ++size_case)
        for(mask_case = 0u; mask_case < 3u; ++mask_case)
            for(cursor = 0u; cursor < 65536u; ++cursor)
            {
                u16 capacity = (u16)(raw_sizes[size_case] - 6ul);
                u16 consumer = 0x4321u;
                u16 backlog = (u16)((u16)(cursor - consumer) & masks[mask_case]);
                int signed_backlog = backlog > 32767u ? (int)backlog - 65536 : backlog;
                unsigned consume = signed_backlog > (int)(capacity / 2u);
                u16 count = (u16)(capacity / 4u);
                set_memory_big_endian_u16(0x1298ul, (u16)cursor);
                set_memory_big_endian_u16(0x1294ul, consumer);
                set_memory_big_endian_u16(0x129aul, masks[mask_case]);
                set_memory_big_endian_u16(0x1292ul, 0x1234u);
                set_memory_big_endian_u32(0x156aul, raw_sizes[size_case]);
                bit_0547 = 0u;
                read_count = write_count = sfr_read_count = sfr_write_count = 0u;
                LimitRawReadSecondaryCursorBacklog();
                assert(read_count == (consume ? 22u : 10u));
                assert(write_count == (consume ? 6u : 0u));
                assert(sfr_read_count == 0u && sfr_write_count == 0u);
                assert(bit_0547 == consume);
                assert(get_memory_big_endian_u16(0x1298ul) == cursor);
                if(consume)
                {
                    assert(read_trace[10] == 0x156aul && read_trace[13] == 0x156dul);
                    assert(write_trace[0] == 0x1294ul && write_trace[1] == 0x1295ul);
                    assert(write_trace[2] == 0x1294ul && write_trace[3] == 0x1295ul);
                    assert(write_trace[4] == 0x1292ul && write_trace[5] == 0x1293ul);
                    assert((((u16)write_values[0] << 8) | write_values[1]) == (u16)(consumer + count));
                    assert(get_memory_big_endian_u16(0x1294ul) == ((u16)(consumer + count) & masks[mask_case]));
                    assert(get_memory_big_endian_u16(0x1292ul) == (u16)(0x1234u - count));
                    assert(write_read_counts[0] == 16u && write_read_counts[2] == 20u && write_read_counts[4] == 22u);
                }
            }
}

static void test_initialize_write_controller_transfer(void)
{
    static const u32 addresses[] = { 0x18021ul, 0x18020ul, 0x1801ful, 0x1801ful, 0x18020ul, 0x18021ul };
    static const u8 values[] = { 0u, 0u, 0u, 0u, 0xc0u, 0x43u };
    unsigned mode, protocol, command, index;
    clear_memory(0u);
    for(mode = 0u; mode < 4u; ++mode)
        for(protocol = 0u; protocol < 256u; ++protocol)
            for(command = 0u; command < 256u; ++command)
            {
                unsigned prefix = mode == 0u ? 0u : (mode > 1u && protocol == 7u ? 3u : 1u);
                u8 expected = 0x14u;
                firmware_memory[0xc78ul] = mode == 0u ? 0u : 0xffu;
                firmware_memory[0x18050ul] = mode < 2u ? 0xfeu : 0xffu;
                firmware_memory[0xc2bul] = (u8)protocol;
                firmware_memory[0xb0aul] = (u8)command;
                firmware_memory[0xc38ul] = mode == 3u ? 16u : 15u;
                firmware_memory[0xc2cul] = (u8)command;
                firmware_memory[0x1805dul] = (u8)~command;
                if(mode > 1u)
                {
                    if(protocol == 7u)
                        expected = 1u;
                    else if(command == 0xbeu || command == 0x28u)
                        expected = (u8)(protocol | 12u);
                    else if(mode == 3u && (command == 0xaau || command == 0x2au))
                        expected = (u8)protocol;
                    else
                        expected = (u8)(protocol | 4u);
                }
                read_count = write_count = sfr_read_count = sfr_write_count = 0u;
                InitializeWriteControllerBufferTransferRegisters();
                assert(write_count == prefix + 6u);
                assert(sfr_read_count == 0u && sfr_write_count == 0u);
                if(prefix != 0u)
                    assert(write_trace[0] == 0x18047ul && write_values[0] == expected);
                if(prefix == 3u)
                {
                    assert(write_trace[1] == 0x18049ul && write_values[1] == (u8)(command + 1u));
                    assert(write_trace[2] == 0x1805dul && write_values[2] == (u8)((u8)~command | 8u));
                    assert(read_count == 5u);
                }
                for(index = 0u; index < 6u; ++index)
                {
                    assert(write_trace[prefix + index] == addresses[index]);
                    assert(write_values[prefix + index] == values[index]);
                    assert(write_read_counts[prefix + index] == read_count);
                }
                if(mode == 0u)
                    assert(read_count == 1u);
                else if(mode == 1u)
                    assert(read_count == 2u);
                else if(protocol != 7u)
                {
                    unsigned expected_reads = 4u + (command == 0xbeu ? 1u : 2u);
                    if(command != 0xbeu && command != 0x28u)
                    {
                        expected_reads++;
                        if(mode == 3u)
                            expected_reads += command == 0xaau ? 1u : 2u;
                    }
                    assert(read_count == expected_reads);
                    assert(read_trace[read_count - 1u] == 0xc2bul);
                }
            }
}

static void test_start_write_controller_buffer_transfer(void)
{
    static const u8 block_counts[] = { 5u, 0x1fu, 0x20u };
    static const u8 controller_modes[] = { 0u, 1u, 1u };
    static const u8 expected_commands[] = { 0x88u, 0xd8u, 0x8au };
    unsigned index;

    for(index = 0u; index < 3u; ++index)
    {
        u8 block_count = block_counts[index];
        u32 initial_cursor = index == 0u ? 0xfffffffeul : 0x12345670ul;
        u32 expected_cursor = initial_cursor + block_count;

        clear_memory(0u);
        set_memory_big_endian_u32_far(0x2ba5d4ul, initial_cursor);
        firmware_memory[0x2ba5c6u] = index == 0u ? 0xfeu : 0x10u;
        firmware_memory[0x18050u] = controller_modes[index];
        StartWriteControllerBufferTransfer(block_count, 0x12abcdeful);

        assert(get_memory_big_endian_u32(0x2ba5d4ul) == expected_cursor);
        assert(firmware_memory[0x2ba5c6u] == (u8)((index == 0u ? 0xfeu : 0x10u) + block_count));
        assert(firmware_memory[0x2ba5c7u] == firmware_memory[0x2ba5c6u]);
        assert(firmware_memory[0x18010u] == 0xefu);
        assert(firmware_memory[0x18011u] == 0xcdu);
        assert(firmware_memory[0x18012u] == 0xabu);
        assert(firmware_memory[0x1800du] == 0u);
        assert(firmware_memory[0x1800eu] == (u8)(block_count << 3));
        assert(firmware_memory[0x1462u] == 1u);
        assert(firmware_memory[0x18056u] == 0x50u);
        assert(firmware_memory[0x18022u] == expected_commands[index]);
        assert(firmware_memory[0x18051u] == 0u);
        assert(firmware_memory[0x1805eu] == 0x87u);
        assert(firmware_memory[0x1801fu] == 0u);
        assert(firmware_memory[0x18020u] == 0xc0u);
        assert(firmware_memory[0x18021u] == 0x43u);
    }
}

static void test_controller_buffer_lookahead(void)
{
    unsigned pointer, index;
    clear_memory(0u);
    for(index = 0u; index < 0x10020u; ++index)
        firmware_memory[index] = (u8)(index * 17u + (index >> 8));
    for(pointer = 0u; pointer < 65536u; ++pointer)
    {
        u8 field, high, low;
        set_memory_big_endian_u16(0x1292ul, 1u);
        set_memory_big_endian_u16(0x1294ul, 0xffffu);
        set_memory_big_endian_u16(0x129aul, 0xffffu);
        set_memory_big_endian_u32(0x129eul, 0xdead0000ul | pointer);
        field = firmware_memory[pointer + 0x15u];
        high = pointer + 8u == 0xfbbaul ? field : firmware_memory[pointer + 8u];
        low = pointer + 9u == 0xfbbaul ? field : firmware_memory[pointer + 9u];
        read_count = write_count = sfr_read_count = sfr_write_count = 0u;
        LoadControllerBufferLookaheadFromNextRawDescriptor();
        assert(read_count == 13u && write_count == 3u);
        assert(sfr_read_count == 0u && sfr_write_count == 0u);
        assert(read_trace[10] == pointer + 0x15ul);
        assert(read_trace[11] == pointer + 8ul && read_trace[12] == pointer + 9ul);
        assert(write_trace[0] == 0xfbbaul && write_values[0] == field);
        assert(write_trace[1] == 0xfbbbul && write_values[1] == high);
        assert(write_trace[2] == 0xfbbcul && write_values[2] == low);
        assert(write_read_counts[0] == 11u && write_read_counts[1] == 13u && write_read_counts[2] == 13u);
    }
    set_memory_big_endian_u16(0x1292ul, 0u);
    firmware_memory[0x15ul] = 0x21u;
    firmware_memory[8ul] = 0x34u;
    firmware_memory[9ul] = 0x56u;
    read_count = write_count = 0u;
    LoadControllerBufferLookaheadFromNextRawDescriptor();
    assert(read_count == 5u && write_count == 3u);
    assert(firmware_memory[0xfbbaul] == 0x21u);
    assert(get_memory_big_endian_u16(0xfbbbul) == 0x3456u);
}

static void test_publish_controller_operating_response(void)
{
    unsigned code, flags;
    clear_memory(0u);
    for(code = 0u; code < 256u; ++code)
        for(flags = 0u; flags < 256u; ++flags)
        {
            u8 expected = (u8)(code % 128u);
            expected = (u8)(0x80u + (expected < 10u ? expected + 88u : expected - 10u));
            firmware_memory[0x1039u] = (u8)flags;
            firmware_memory[0x1038u] = (u8)~flags;
            firmware_memory[0x1055u] = (u8)code;
            read_count = write_count = sfr_read_count = sfr_write_count = 0u;
            PublishControllerOperatingResponse();
            assert(read_count == 3u && write_count == 3u);
            assert(sfr_read_count == 0u && sfr_write_count == 0u);
            assert(read_trace[0] == 0x1039ul && read_trace[1] == 0x1055ul && read_trace[2] == 0x1038ul);
            assert(write_trace[0] == 0x1039ul && write_values[0] == (flags & 0x7fu));
            assert(write_trace[1] == 0x1807ful && write_values[1] == expected);
            assert(write_trace[2] == 0x1038ul && write_values[2] == (u8)((u8)~flags | 8u));
            assert(write_read_counts[0] == 1u && write_read_counts[1] == 2u && write_read_counts[2] == 3u);
            assert(firmware_memory[0x1055ul] == code);
        }
    write_mutation_enabled = 1u;
    write_mutation_trigger = 0x1807ful;
    write_mutation_target = 0x1038ul;
    write_mutation_value = 0xc1u;
    read_count = write_count = 0u;
    PublishControllerOperatingResponse();
    assert(firmware_memory[0x1038ul] == 0xc9u);
}

