static void test_copy_from_controller_buffer_window(void)
{
    static u8 expected_memory[0x1000000ul];
    static const u16 counts[] = { 0u, 1u, 2u, 3u, 255u, 256u, 257u, 2048u, 65535u };
    static const u32 cases[][2] = {
        { 0x2000ul,   0ul          },
        { 0x12fffful, 0x1fffful    },
        { 0x55fffful, 0xeffffful   },
        { 0x2000ul,   0xfffffff0ul },
        { 0x101001ul, 0x1000ul     },
        { 0x100ffful, 0x1000ul     },
        { 0x101000ul, 0x1000ul     },
        { 0xfffffful, 0xdeadfffeul }
    };
    unsigned test_case, length_case;
    u32 index;
    clear_memory(0xa5u);
    for(test_case = 0; test_case < 8u; ++test_case)
        for(length_case = 0; length_case < sizeof(counts) / sizeof(counts[0]); ++length_case)
        {
            u32 destination = cases[test_case][0];
            u32 offset = cases[test_case][1];
            u32 source = (offset + 0x100000ul) & 0xfffffful;
            u16 count = counts[length_case];
            u32 returned_offset;
            for(index = 0; index < count; ++index)
                firmware_memory[(source + index) & 0xfffffful] = (u8)(index * 7ul + test_case);
            memcpy(expected_memory, firmware_memory, sizeof(expected_memory));
            for(index = 0; index < count; ++index)
            {
                u32 target = (destination & 0xff0000ul) | ((destination + index) & 0xfffful);
                expected_memory[target] = expected_memory[(source + index) & 0xfffffful];
            }
            read_count = write_count = sfr_read_count = sfr_write_count = 0u;
            returned_offset = CopyFromControllerBufferWindow(offset, destination, count);
            assert(returned_offset == (u32)(offset + count));
            assert(read_count == count && write_count == count);
            assert(sfr_read_count == 0u && sfr_write_count == 0u);
            assert(memcmp(firmware_memory, expected_memory, sizeof(expected_memory)) == 0);
            for(index = 0; index < count && index < 512ul; ++index)
            {
                assert(read_trace[index] == ((source + index) & 0xfffffful));
                assert(write_trace[index] == ((destination & 0xff0000ul) | ((destination + index) & 0xfffful)));
                assert(write_read_counts[index] == index + 1u);
            }
        }
}

