static void test_mode_page02_runtime_timing(void)
{
    unsigned first, second, index;
    static const fw_addr_t reads[] = { 0xe631ul, 0x156aul, 0x156bul, 0x156cul, 0x156dul, 0xe632ul, 0x156aul, 0x156bul, 0x156cul, 0x156dul };
    clear_memory(0u);
    set_memory_big_endian_u32(0x156au, 0x12345678ul);
    for(first = 0; first < 256u; ++first)
        for(second = 0; second < 256u; ++second)
        {
            u16 first_expected = (u16)((0x5672ul * (first == 0u ? 256u : first)) >> 8);
            u16 second_expected = (u16)((0x5672ul * (second == 0u ? 256u : second)) >> 8);
            firmware_memory[0xe631u] = (u8)first;
            firmware_memory[0xe632u] = (u8)second;
            read_count = write_count = 0u;
            ApplyModePage02RuntimeTimingParameters();
            assert(read_count == 10u && write_count == 4u);
            for(index = 0; index < 10u; ++index)
                assert(read_trace[index] == reads[index]);
            for(index = 0; index < 4u; ++index)
            {
                assert(write_trace[index] == 0xc3ful + index);
                assert(write_read_counts[index] == (index < 2u ? 5u : 10u));
            }
            assert(get_memory_big_endian_u16(0xc3fu) == first_expected);
            assert(get_memory_big_endian_u16(0xc41u) == second_expected);
        }
    firmware_memory[0xe631u] = firmware_memory[0xe632u] = 128u;
    write_mutation_enabled = 1u;
    write_mutation_trigger = 0xc40ul;
    write_mutation_target = 0xe632ul;
    write_mutation_value = 0u;
    ApplyModePage02RuntimeTimingParameters();
    assert(get_memory_big_endian_u16(0xc3fu) == 0x2b39u);
    assert(get_memory_big_endian_u16(0xc41u) == 0x5672u);
    write_mutation_enabled = 1u;
    write_mutation_target = 0x156dul;
    write_mutation_value = 0x80u;
    ApplyModePage02RuntimeTimingParameters();
    assert(get_memory_big_endian_u16(0xc41u) == 0x567au);
}

