static void test_persist_configuration_failure_code(void)
{
    unsigned code, outcome, index;
    clear_memory(0u);
    for(code = 0; code < 256u; ++code)
        for(outcome = 0; outcome < 2u; ++outcome)
        {
            u16 primary = 0u, extended = 0u;
            for(index = 0; index < 0xa0u; ++index)
                firmware_memory[0x1620u + index] = (u8)(index * 7u + code);
            for(index = 0; index < 0x5eu; ++index)
                primary = (u16)(primary + firmware_memory[0x1620u + index]);
            for(index = 0; index < 0x7eu; ++index)
            {
                u8 value = firmware_memory[0x1620u + index];
                if(index == 0x5eu)
                    value = (u8)(primary >> 8);
                if(index == 0x5fu)
                    value = (u8)primary;
                if(index == 0x72u)
                    value = (u8)code;
                extended = (u16)(extended + value);
            }
            recovery_configuration_program_result = (u8)outcome;
            recovery_configuration_program_copies_primary = 1u;
            recovery_configuration_program_call_count = 0u;
            read_count = write_count = 0u;
            PersistDriveConfigurationValidationFailureCode((u8)code);
            assert(write_trace[0] == 0x1692ul && write_values[0] == code);
            assert(write_read_counts[0] == 0u);
            assert(recovery_configuration_program_call_count == 1u);
            assert(recovery_configuration_program_extended_only == 0u);
            assert(recovery_failure_code_seen == code);
            assert(recovery_primary_checksum_seen == primary);
            assert(recovery_extended_checksum_seen == extended);
            assert(get_memory_big_endian_u16(0x167eu) == primary);
            assert(get_memory_big_endian_u16(0x169eu) == extended);
        }
}

static void test_controller_d1_after_pulse_test(void)
{
    static const unsigned patterns[] = { 0u, 3u, 7u, 0x380u };
    unsigned pattern, shadow, mode, sample;
    clear_memory(0u);
    timer_status_auto_signal = 1u;
    for(pattern = 0; pattern < 4u; ++pattern)
        for(shadow = 0; shadow < 256u; ++shadow)
            for(mode = 0; mode < 2u; ++mode)
            {
                u8 expected = (u8)(shadow | (mode == 0u ? 0xc0u : 0xa0u));
                firmware_memory[0xfc13u] = (u8)shadow;
                firmware_memory[0x1303u] = mode == 0u ? 0xdfu : 0xffu;
                for(sample = 0; sample < 10u; ++sample)
                    p1_bit3_samples[sample] = (patterns[pattern] & (1u << sample)) != 0u ? 8u : 0u;
                p1_bit3_sample_count = 10u;
                p1_bit3_sample_index = 0u;
                read_count = write_count = sfr_read_count = sfr_write_count = 0u;
                controller_parameter_count = 0u;
                ApplyControllerD1ModeBitsAfterPulseTest();
                assert(p1_bit3_sample_index == 10u);
                if(pattern < 2u)
                {
                    assert(read_count == 0u && write_count == 0u);
                    assert(controller_parameter_count == 0u);
                    assert(firmware_memory[0xfc13u] == shadow);
                }
                else
                {
                    assert(read_count == 5u && read_trace[0] == 0x1303ul && read_trace[1] == 0xfc13ul && read_trace[2] == 0xfc13ul && read_trace[3] == 0x1301ul && read_trace[4] == 0x1301ul);
                    assert(write_count == 3u && write_trace[0] == 0xfc13ul && write_trace[1] == 0x1301ul && write_trace[2] == 0x1301ul);
                    assert(write_values[0] == expected);
                    assert(controller_parameter_count == 1u);
                    assert(controller_parameter_trace[0] == (u16)(0xd100u | expected));
                }
            }
    clear_memory(0u);
    timer_status_auto_signal = 1u;
    sfr_memory[0x90u] = 8u;
    write_mutation_enabled = 1u;
    write_mutation_trigger = write_mutation_target = 0xfc13ul;
    write_mutation_value = 0x55u;
    ApplyControllerD1ModeBitsAfterPulseTest();
    assert(controller_parameter_trace[0] == 0xd155u);
}

static void test_pulse_calibration_status(void)
{
    unsigned pattern, initial_flags, sample, successes;
    clear_memory(0u);
    firmware_memory[0x1132u] = 0xffu;
    UpdateP1Cex0PulseCalibrationStatus();
    assert(read_count == 1u && write_count == 0u && sfr_write_count == 0u);
    assert(firmware_memory[0x1132u] == 0xffu);
    timer_status_auto_signal = 1u;
    for(pattern = 0; pattern < 1024u; ++pattern)
    {
        for(initial_flags = 0; initial_flags < 256u; initial_flags += 17u)
        {
            firmware_memory[0x1008u] = (u8)(1u + pattern % 255u);
            firmware_memory[0x1132u] = (u8)initial_flags;
            successes = 0u;
            for(sample = 0; sample < 10u; ++sample)
            {
                u8 high = (u8)((pattern >> sample) & 1u);
                successes += high;
                p1_bit3_samples[sample] = (u8)(high << 3);
            }
            p1_bit3_sample_count = 10u;
            p1_bit3_sample_index = 0u;
            read_count = write_count = sfr_read_count = sfr_write_count = 0u;
            UpdateP1Cex0PulseCalibrationStatus();
            assert(p1_bit3_sample_index == 10u && sfr_write_count == 60u);
            assert(read_count == 2u && read_trace[0] == 0x1008ul && read_trace[1] == 0x1132ul);
            assert(write_count == 1u && write_trace[0] == 0x1132ul);
            assert(write_values[0] == (u8)((initial_flags & 0xdfu) | (successes >= 3u ? 0x20u : 0u)));
        }
    }
}

static void test_refresh_fc_and_f6_parameters(void)
{
    unsigned code, state, flags, override;
    clear_memory(0u);
    for(code = 0; code < 256u; ++code)
        for(state = 0; state < 3u; ++state)
            for(flags = 0; flags < 2u; ++flags)
                for(override = 0; override < 2u; ++override)
                {
                    u8 fc = override != 0u ? 0x95u : (state == 0u ? 0xa0u : 0x68u);
                    u8 f6 = state == 2u ? (code >= 32u ? 0xa3u : 0xb3u) : 0xc3u;
                    if(state == 2u && code >= 32u && flags != 0u)
                        fc = (u8)(fc - 0x10u);
                    firmware_memory[0xe43u] = (u8)code;
                    firmware_memory[0x1008u] = (u8)state;
                    firmware_memory[0x1307u] = (u8)flags;
                    firmware_memory[0xfc0fu] = override != 0u ? 0x95u : 0u;
                    read_count = write_count = sfr_read_count = sfr_write_count = 0u;
                    controller_parameter_count = 0u;
                    RefreshControllerParametersFCAndF6ForCurrentOperatingCode();
                    assert(controller_parameter_count == 2u);
                    assert(controller_parameter_trace[0] == (u16)(0xfc00u | fc));
                    assert(controller_parameter_trace[1] == (u16)(0xf600u | f6));
                    assert(read_trace[0] == 0xe43ul);
                }
    clear_memory(0u);
    firmware_memory[0xe43u] = 4u;
    firmware_memory[0x1008u] = 2u;
    mutate_operating_code_after_parameter = 1u;
    next_parameter_operating_code = 0x34u;
    RefreshControllerParametersFCAndF6ForCurrentOperatingCode();
    assert(controller_parameter_trace[0] == 0xfc68u);
    assert(controller_parameter_trace[1] == 0xf6a3u);
}
