static void test_premium_disc_firmware_update_coroutine_step(void)
{
    static const struct
    {
        u8 signature_result;
        u8 payload_result;
        u8 programmer_result;
        unsigned payload_calls;
        unsigned programmer_calls;
        unsigned recovery_calls;
        u8 recovery_status;
    } vectors[] = {
        { 2u, 1u, 1u, 0u, 0u, 1u, 1u },
        { 1u, 0u, 1u, 1u, 0u, 1u, 2u },
        { 1u, 1u, 0u, 1u, 1u, 1u, 2u },
        { 1u, 1u, 1u, 1u, 1u, 0u, 0u }
    };
    unsigned vector_index;

    for(vector_index = 0u; vector_index < sizeof(vectors) / sizeof(vectors[0]); ++vector_index)
    {
        clear_memory(0xa5u);
        bit_0580 = 1u;
        bit_0581 = 0u;
        premium_signature_result = vectors[vector_index].signature_result;
        premium_payload_result = vectors[vector_index].payload_result;
        premium_programmer_result = vectors[vector_index].programmer_result;
        RunPremiumDiscFirmwareUpdateCoroutineStep();
        assert(bit_0580 == 0u && bit_0581 == 1u);
        assert(premium_signature_call_count == 1u && premium_payload_call_count == vectors[vector_index].payload_calls && premium_programmer_call_count == vectors[vector_index].programmer_calls
               && premium_recovery_call_count == vectors[vector_index].recovery_calls && premium_recovery_status_seen == vectors[vector_index].recovery_status);
        assert(firmware_memory[0xfaf1u] == 0u && firmware_memory[0x1226u] == 0u && firmware_memory[0xfaefu] == 0xa0u);
        assert(yield_coroutine0_count == 1u);
    }
}

