    assert(read_trace[0] == 0x0f46ul && read_trace[1] == 0x159cul && read_trace[2] == 0x159dul && read_trace[3] == 0x159eul && read_trace[4] == 0x159ful && read_trace[5] == 0x1598ul
           && read_trace[6] == 0x1599ul && read_trace[7] == 0x159aul && read_trace[8] == 0x159bul && read_trace[9] == 0x0f10ul && read_trace[10] == 0x0f11ul && read_trace[11] == 0x0f12ul
           && read_trace[12] == 0x0f13ul);
    assert(write_trace[0] == 0x0c8cul && write_trace[1] == 0x0c8eul && write_trace[2] == 0x0c8ful && write_trace[3] == 0x0c90ul && write_trace[4] == 0x0c91ul);

    clear_memory(0u);
