    assert(firmware_memory[0x1490u] == 1u && get_memory_big_endian_u32(0x1484u) == 0x01020304ul);
    assert(firmware_memory[0x0b1au] == 3u && firmware_memory[0x0b24u] == 0x0cu && firmware_memory[0x0b25u] == 9u && get_memory_big_endian_u32(0x0b1bu) == 0x11223344ul);

    clear_memory(0u);
    firmware_memory[0x1490u] = 1u;
    set_memory_big_endian_u16(0x1292u, 2u);
    set_memory_big_endian_u16(0x1296u, 1u);
    set_memory_big_endian_u16(0x129au, 0x000fu);
    set_memory_big_endian_u32(0x129eu, 0x00002000ul);
    set_memory_big_endian_u16(0x2002u, 0x2000u);
    set_memory_big_endian_u16(0x2000u, 0x1234u);
    ReportSense030C09FromRawReadQueue();
    assert(get_memory_big_endian_u32(0x0b1bu) == 0x12341ffeul);

