static void test_track_model_lookup_leaves(void)
{
    unsigned value;
    u16 record;

    clear_memory(0);
    set_memory_big_endian_u16(0xb4bbu, 3u);
    for(value = 0u; value <= 3u; value++)
    {
        record = (u16)(0xb4bdu + (u16)value * 8u);
        firmware_memory[record] = 1u;
        firmware_memory[(u16)(record + 1u)] = 0u;
    }
    assert(FindFirstType1TrackRecordNumberOrOne() == 1u);
    firmware_memory[0xb4be] = 100u;
    firmware_memory[0xb4c6] = 99u;
    assert(FindFirstType1TrackRecordNumberOrOne() == 99u);
    firmware_memory[0xb4c5] = 2u;
    firmware_memory[0xb4c6] = 33u;
    assert(FindFirstType1TrackRecordNumberOrOne() == 1u);

    for(value = 0u; value != 256u; value++)
    {
        clear_memory(0);
        firmware_memory[0xdd79] = 1u;
        firmware_memory[0x12c0] = (u8)value;
        assert(GetEffectiveLastTrackNumber() == (u8)value);
    }
    clear_memory(0);
    firmware_memory[0xdd7f] = 100u;
    assert(GetEffectiveLastTrackNumber() == 99u);
    firmware_memory[0xdd7f] = 8u;
    firmware_memory[0xde1ful] = 0u;
    assert(GetEffectiveLastTrackNumber() == 7u);
    firmware_memory[0xde1ful] = 1u;
    assert(GetEffectiveLastTrackNumber() == 8u);

    clear_memory(0);
    firmware_memory[0xdd7e] = 2u;
    firmware_memory[0xdd7f] = 2u;
    UpdateTrackTableControlBit6Intersection();
    assert(firmware_memory[0x15f7] == 0x40u);
    firmware_memory[0xdd7f] = 5u;
    firmware_memory[0xdda6] = 0x40u;
    firmware_memory[0xddb9] = 0xc0u;
    firmware_memory[0xddcc] = 0x40u;
    UpdateTrackTableControlBit6Intersection();
    assert(firmware_memory[0x15f7] == 0x40u);
    firmware_memory[0xddb9] = 0u;
    UpdateTrackTableControlBit6Intersection();
    assert(firmware_memory[0x15f7] == 0u);

    clear_memory(0);
    firmware_memory[0xb4c5] = 1u;
    assert(FindAdjacentType1TrackRecordIndex(1u, 0x0100u) == 1u);
    firmware_memory[0xb4bd] = 1u;
    assert(FindAdjacentType1TrackRecordIndex(0u, 1u) == 0u);
    clear_memory(0);
    firmware_memory[0xbcb5] = 1u;
    assert(FindAdjacentType1TrackRecordIndex(0u, 0u) == 0xffu);
}

