static void test_find_adjacent_raw_read_q_record_class(void)
{
    unsigned field;
    unsigned record_type;

    /* A matching record maps only its bits 4 and 5, after ordered type/data reads. */
    for(field = 0u; field != 256u; ++field)
    {
        clear_memory(0);
        firmware_memory[0xb4c5u] = 0x51u;
        firmware_memory[0xb4c8u] = (u8)field;
        assert(FindAdjacentRawReadQRecordClass(1u, 0u) == ((field & 0x30u) == 0x10u ? 1u : (field & 0x30u) == 0x20u || (field & 0x30u) == 0x30u ? 2u : 0u));
        assert(read_count == 2u && read_trace[0] == 0x00b4c5ul && read_trace[1] == 0x00b4c8ul);
    }

    /* Every nonmatching type advances once before reading the adjacent record. */
    for(record_type = 0u; record_type != 256u; ++record_type)
    {
        if(((u8)record_type & 0x0fu) == 1u)
            continue;
        clear_memory(0);
        firmware_memory[0xb4c5u] = (u8)record_type;
        firmware_memory[0xb4cdu] = 1u;
        firmware_memory[0xb4d0u] = 0x20u;
        assert(FindAdjacentRawReadQRecordClass(1u, 1u) == 2u);
        assert(read_count == 3u && read_trace[0] == 0x00b4c5ul && read_trace[1] == 0x00b4cdul && read_trace[2] == 0x00b4d0ul);
    }

    clear_memory(0);
    firmware_memory[0xb4cdu] = 0u;
    firmware_memory[0xb4c5u] = 1u;
    firmware_memory[0xb4c8u] = 0x10u;
    assert(FindAdjacentRawReadQRecordClass(2u, 0u) == 1u);
    assert(read_count == 3u && read_trace[0] == 0x00b4cdul && read_trace[1] == 0x00b4c5ul && read_trace[2] == 0x00b4c8ul);

    clear_memory(0);
    firmware_memory[0xb4bdu] = 0u;
    assert(FindAdjacentRawReadQRecordClass(0u, 0u) == 0u);
    assert(read_count == 1u && read_trace[0] == 0x00b4bdul);

    clear_memory(0);
    firmware_memory[0xb4b5u] = 0u;
    firmware_memory[0xb4bdu] = 1u;
    firmware_memory[0xb4c0u] = 0x30u;
    assert(FindAdjacentRawReadQRecordClass(0x1fffu, 1u) == 2u);
    assert(read_count == 3u && read_trace[0] == 0x00b4b5ul && read_trace[1] == 0x00b4bdul && read_trace[2] == 0x00b4c0ul);
}

static void set_raw_read_track_record(u16 record_index, u8 flags, u8 q_class, u8 minute, u8 second, u8 frame)
{
    u16 address = (u16)(0xb4bdu + (u16)(record_index << 3));

    firmware_memory[address] = (u8)((flags & 0xf0u) | 1u);
    firmware_memory[(u16)(address + 3u)] = q_class;
    firmware_memory[(u16)(address + 4u)] = minute;
    firmware_memory[(u16)(address + 6u)] = second;
    firmware_memory[(u16)(address + 7u)] = frame;
}

static void assert_raw_read_preparation_segments(u32 first_count, u8 first_mode, u32 second_count, u8 second_mode);

static void prepare_raw_read_preparation_track_records(u8 previous_flags, u8 current_flags, u8 previous_class, u8 current_class, u8 next_second)
{
    set_raw_read_track_record(1u, previous_flags, previous_class, 1u, 0u, 0u);
    set_raw_read_track_record(2u, current_flags, current_class, 1u, 0u, 0u);
    set_raw_read_track_record(3u, 0u, 0u, 1u, next_second, 0u);
}

static void test_raw_read_preparation_segments_from_track_record_index(void)
{
    clear_memory(0);
    prepare_raw_read_preparation_track_records(0u, 0u, 0u, 0u, 2u);
    set_memory_big_endian_u16(0x149du, 1u);
    InitializeRawReadPreparationSegmentsFromTrackRecordIndex(2u);
    assert_raw_read_preparation_segments(0ul, 0u, 150ul, 1u);
    assert(read_trace[0] == 0x00b4c5ul && read_trace[1] == 0x00b4cdul && read_trace[2] == 0x00b4c5ul && read_trace[4] == 0x00b4cdul && read_trace[6] == 0x00149dul && read_trace[7] == 0x00149eul);

    clear_memory(0);
    prepare_raw_read_preparation_track_records(0u, 0u, 0u, 0x10u, 2u);
    set_memory_big_endian_u16(0x149du, 1u);
    InitializeRawReadPreparationSegmentsFromTrackRecordIndex(2u);
    assert_raw_read_preparation_segments(0ul, 0u, 150ul, 2u);

    clear_memory(0);
    prepare_raw_read_preparation_track_records(0u, 0u, 0u, 0u, 2u);
    set_memory_big_endian_u16(0x149du, 0u);
    InitializeRawReadPreparationSegmentsFromTrackRecordIndex(2u);
    assert_raw_read_preparation_segments(0ul, 0u, 150ul, 1u);

    clear_memory(0);
    prepare_raw_read_preparation_track_records(0u, 0x40u, 0u, 0u, 2u);
    set_memory_big_endian_u16(0x149du, 0u);
    InitializeRawReadPreparationSegmentsFromTrackRecordIndex(2u);
    assert_raw_read_preparation_segments(75ul, 1u, 75ul, 2u);

    clear_memory(0);
    prepare_raw_read_preparation_track_records(0x40u, 0u, 0x10u, 0x10u, 2u);
    set_memory_big_endian_u16(0x149du, 0u);
    InitializeRawReadPreparationSegmentsFromTrackRecordIndex(2u);
    assert_raw_read_preparation_segments(0ul, 0u, 150ul, 2u);

    clear_memory(0);
    prepare_raw_read_preparation_track_records(0x40u, 0x40u, 0x10u, 0x10u, 2u);
    set_memory_big_endian_u16(0x149du, 0u);
    InitializeRawReadPreparationSegmentsFromTrackRecordIndex(2u);
    assert_raw_read_preparation_segments(0ul, 0u, 150ul, 2u);

    clear_memory(0);
    prepare_raw_read_preparation_track_records(0x40u, 0x40u, 0x10u, 0x20u, 1u);
    set_memory_big_endian_u16(0x149du, 0u);
    InitializeRawReadPreparationSegmentsFromTrackRecordIndex(2u);
    assert_raw_read_preparation_segments(75ul, 3u, 0xffffffe7ul, 2u);
}

static void assert_raw_read_preparation_segments(u32 first_count, u8 first_mode, u32 second_count, u8 second_mode)
{
    assert(get_memory_big_endian_u32(0x1430u) == first_count);
    assert(firmware_memory[0x1438u] == first_mode);
    assert(get_memory_big_endian_u32(0x1434u) == second_count);
    assert(firmware_memory[0x1439u] == second_mode);
}

static void test_raw_read_preparation_segments_from_plan_code(void)
{
    unsigned plan;
    static const u8 override_sources[] = { 1u, 3u, 0u, 0u };
    unsigned source_index;

    /* Initial plan dispatch: all other plan values leave the fields untouched. */
    for(plan = 0u; plan != 256u; ++plan)
    {
        clear_memory(0);
        firmware_memory[0x0c44u] = 1u;
        firmware_memory[0xdd34u] = 0u;
        set_memory_big_endian_u16(0x0c4fu, 0x1234u);
        set_memory_big_endian_u32(0x1430u, 0x11223344ul);
        firmware_memory[0x1438u] = 0x55u;
        set_memory_big_endian_u32(0x1434u, 0x66778899ul);
        firmware_memory[0x1439u] = 0xaau;
        InitializeRawReadPreparationSegmentsFromPlanCode((u8)plan);
        if(plan == 2u)
            assert_raw_read_preparation_segments(75ul, 1u, 150ul, 2u);
        else if(plan == 3u || plan == 4u)
            assert_raw_read_preparation_segments(75ul, 3u, 150ul, 2u);
        else if(plan == 5u || plan == 6u || plan == 8u)
            assert_raw_read_preparation_segments(0ul, 0u, 150ul, 2u);
        else if(plan == 7u)
            assert_raw_read_preparation_segments(0ul, 0u, 5ul, 2u);
        else if(plan == 10u || plan == 11u)
            assert_raw_read_preparation_segments(0ul, 0u, 0x1234ul, 1u);
        else
            assert_raw_read_preparation_segments(0x11223344ul, 0x55u, 0x66778899ul, 0xaau);
    }

    /* The c44-zero override is entered by four independent source predicates. */
    for(source_index = 0u; source_index < sizeof(override_sources); ++source_index)
    {
        clear_memory(0);
        firmware_memory[0x0c44u] = 0u;
        firmware_memory[0xdd34u] = override_sources[source_index];
        if(source_index == 2u)
            firmware_memory[0x14b3u] = 1u;
        if(source_index == 3u)
            firmware_memory[0x14b7u] = 1u;
        firmware_memory[0x0c48u] = source_index == 0u ? 5u : 4u;
        InitializeRawReadPreparationSegmentsFromPlanCode(0u);
        assert_raw_read_preparation_segments(0ul, 0u, 5ul, source_index == 0u ? 2u : 3u);
    }
    clear_memory(0);
    firmware_memory[0x0c44u] = 0u;
    firmware_memory[0xdd34u] = 1u;
    firmware_memory[0x0c48u] = 0x80u;
    InitializeRawReadPreparationSegmentsFromPlanCode(0u);
    assert_raw_read_preparation_segments(0ul, 0u, 5ul, 3u);

    clear_memory(0);
    firmware_memory[0x0c44u] = 1u;
    firmware_memory[0x0c9eu] = 1u;
    InitializeRawReadPreparationSegmentsFromPlanCode(2u);
    assert_raw_read_preparation_segments(0ul, 0u, 5ul, 2u);

    /* dd34 type two refines counts using a signed 32-bit source difference. */
    clear_memory(0);
    firmware_memory[0x0c44u] = 1u;
    firmware_memory[0xdd34u] = 2u;
    set_memory_big_endian_u32(0xdd39u, 1000ul);
    set_memory_big_endian_u32(0xdd3du, 1151ul);
    InitializeRawReadPreparationSegmentsFromPlanCode(3u);
    assert_raw_read_preparation_segments(1ul, 0u, 150ul, 2u);

    clear_memory(0);
    firmware_memory[0x0c44u] = 1u;
    firmware_memory[0xdd34u] = 2u;
    set_memory_big_endian_u32(0xdd39u, 1000ul);
    set_memory_big_endian_u32(0xdd3du, 1151ul);
    firmware_memory[0x1438u] = 0xa5u;
    InitializeRawReadPreparationSegmentsFromPlanCode(9u);
    assert_raw_read_preparation_segments(0ul, 0xa5u, 151ul, 1u);

    clear_memory(0);
    firmware_memory[0x0c44u] = 1u;
    firmware_memory[0xdd34u] = 2u;
    set_memory_big_endian_u32(0xdd39u, 1000ul);
    set_memory_big_endian_u32(0xdd3du, 1150ul);
    InitializeRawReadPreparationSegmentsFromPlanCode(8u);
    assert_raw_read_preparation_segments(0ul, 0u, 150ul, 2u);

    clear_memory(0);
    firmware_memory[0x0c44u] = 1u;
    firmware_memory[0xdd34u] = 2u;
    set_memory_big_endian_u32(0xdd39u, 1000ul);
    set_memory_big_endian_u32(0xdd3du, 999ul);
    firmware_memory[0x1439u] = 0xa5u;
    InitializeRawReadPreparationSegmentsFromPlanCode(11u);
    assert_raw_read_preparation_segments(0ul, 0u, 0xfffffffful, 1u);

    clear_memory(0);
    firmware_memory[0x0c44u] = 1u;
    firmware_memory[0xdd34u] = 2u;
    set_memory_big_endian_u32(0xdd39u, 0ul);
    set_memory_big_endian_u32(0xdd3du, 0x80000000ul);
    firmware_memory[0x1439u] = 0xa5u;
    InitializeRawReadPreparationSegmentsFromPlanCode(1u);
    assert_raw_read_preparation_segments(0ul, 0u, 0x80000000ul, 0xa5u);
}

static void test_raw_read_target_position_match_counter(void)
{
    static const s32 positions[] = { -1l, 0l, 1l, 0x7fffffffl, (s32)0x80000000ul };
    unsigned target_index;
    unsigned current_index;

    clear_memory(0);
    firmware_memory[0x0c89] = 0u;
    firmware_memory[0x18015] = 0x20u;
    firmware_memory[0x180f9] = 4u;
    set_memory_big_endian_u16(0x122fu, 0x1234u);
    CountRawReadTargetPositionMatch();
    assert((((u16)firmware_memory[0x122f] << 8) | firmware_memory[0x1230]) == 0x1234u);

    for(target_index = 0u; target_index < sizeof(positions) / sizeof(positions[0]); target_index++)
    {
        for(current_index = 0u; current_index < sizeof(positions) / sizeof(positions[0]); current_index++)
        {
            clear_memory(0);
            firmware_memory[0x0c89] = 1u;
            firmware_memory[0x18015] = 0x20u;
            firmware_memory[0x180f9] = 4u;
            set_memory_big_endian_u32(0x1598u, (u32)positions[target_index]);
            set_memory_big_endian_u32(0x1235u, (u32)positions[current_index]);
            set_memory_big_endian_u16(0x122fu, 0xffffu);
            CountRawReadTargetPositionMatch();
            assert((((u16)firmware_memory[0x122f] << 8) | firmware_memory[0x1230]) == (positions[current_index] == positions[target_index] ? 0u : 0xffffu));
        }
    }
}

static void test_raw_read_matched_target_cursor_advance(void)
{
    static const u16 low_words[] = { 0u, 1u, 0x7fffu, 0xffffu };
    unsigned index;

    clear_memory(0);
    set_memory_big_endian_u16(0x122fu, 0u);
    FirmwareWrite8(0x2bc6fful, 0x2bu);
    FirmwareWrite8(0x2bc700ul, 0xa5u);
    FirmwareWrite8(0x2bc701ul, 0x5au);
    FirmwareWrite8(0x2bc702ul, 0xa5u);
    assert(AdvanceRawReadMatchedTargetCursorIfAvailable() == 1u);
    assert(firmware_memory[0x2bc6fful] == 0x2bu && firmware_memory[0x2bc700ul] == 0xa5u && firmware_memory[0x2bc701ul] == 0x5au && firmware_memory[0x2bc702ul] == 0xa5u);

    for(index = 0u; index < sizeof(low_words) / sizeof(low_words[0]); index++)
    {
        clear_memory(0);
        set_memory_big_endian_u16(0x122fu, 1u);
        FirmwareWrite8(0x2bc6fful, 0x2bu);
        FirmwareWrite8(0x2bc700ul, 0xa5u);
        FirmwareWrite8(0x2bc701ul, (u8)(low_words[index] >> 8));
        FirmwareWrite8(0x2bc702ul, (u8)low_words[index]);
        assert(AdvanceRawReadMatchedTargetCursorIfAvailable() == 0u);
        assert(firmware_memory[0x2bc6fful] == 0x2bu && firmware_memory[0x2bc700ul] == 0xa5u && (((u16)firmware_memory[0x2bc701ul] << 8) | firmware_memory[0x2bc702ul]) == (u16)(low_words[index] + 1u));
    }
}

static void test_raw_read_controller_capture_port_clear(void)
{
    clear_memory(0);
    firmware_memory[0x18015] = 0x20u;
    firmware_memory[0x0c89] = 0u;
    firmware_memory[0x180f8] = 0xa5u;
    firmware_memory[0x180fa] = 0x5au;
    ClearControllerPorts80F8And80FAIfRawReadEnabled();
    assert(firmware_memory[0x180f8] == 0xa5u);
    assert(firmware_memory[0x180fa] == 0x5au);

    firmware_memory[0x0c89] = 1u;
    ClearControllerPorts80F8And80FAIfRawReadEnabled();
    assert(firmware_memory[0x180fa] == 4u);
    assert(firmware_memory[0x180f8] == 0u);
}

static void test_measurement_snapshot_record(void)
{
    const fw_addr_t output = 0x1c1234ul;

    clear_memory(0xccu);
    firmware_memory[0xfb9b] = 2u;
    firmware_memory[0x123d] = 12u;
    firmware_memory[0x123e] = 34u;
    firmware_memory[0x123f] = 56u;
    firmware_memory[0x1520] = 11u;
    set_memory_big_endian_u32(0x1517u, 0x00001234ul);
    firmware_memory[0xfbd3] = 0xa3u;
    firmware_memory[0xfbd0] = 0xb0u;
    set_memory_big_endian_u16(0x1521u, 0xc1d2u);
    set_memory_big_endian_u16(0x1523u, 0xe3f4u);
    firmware_memory[0xfbd1] = 0x55u;
    set_memory_big_endian_u16(0xfbc3u, 0x6677u);
    AppendMeasurementSnapshotRecord();
    assert(firmware_memory[0x151f] == 12u && firmware_memory[0x1520] == 12u);
    assert(firmware_memory[output] == 0x12u && firmware_memory[output + 1u] == 0x34u && firmware_memory[output + 2u] == 0x56u && firmware_memory[output + 3u] == 0xccu
           && firmware_memory[output + 4u] == 0xccu && firmware_memory[output + 5u] == 0xa3u && firmware_memory[output + 6u] == 0xccu && firmware_memory[output + 7u] == 0xb0u
           && firmware_memory[output + 8u] == 0xc1u && firmware_memory[output + 9u] == 0xd2u && firmware_memory[output + 10u] == 0xe3u && firmware_memory[output + 11u] == 0xf4u
           && firmware_memory[output + 12u] == 0xccu && firmware_memory[output + 13u] == 0x55u && firmware_memory[output + 14u] == 0x66u && firmware_memory[output + 15u] == 0x77u);
    assert((((u32)firmware_memory[0x1517] << 24) | ((u32)firmware_memory[0x1518] << 16) | ((u32)firmware_memory[0x1519] << 8) | firmware_memory[0x151a]) == 0x00001244ul);
    assert((((u32)firmware_memory[0x151b] << 24) | ((u32)firmware_memory[0x151c] << 16) | ((u32)firmware_memory[0x151d] << 8) | firmware_memory[0x151e]) == 0x001c1242ul);

    clear_memory(0u);
    firmware_memory[0xfb9b] = 1u;
    firmware_memory[0x123d] = 9u;
    firmware_memory[0x151f] = 0xa5u;
    AppendMeasurementSnapshotRecord();
    assert(firmware_memory[0x151f] == 0xa5u);

    firmware_memory[0xfb9b] = 2u;
    firmware_memory[0x1520] = 9u;
    AppendMeasurementSnapshotRecord();
    assert(firmware_memory[0x151f] == 9u && firmware_memory[0x1520] == 9u);
}

static void test_controller_byte_read_transaction(void)
{
    clear_memory(0u);
    sfr_memory[0xa8] = 0x83u;
    sfr_memory[0xa9] = 0x41u;
    firmware_memory[0x18030] = 0x5au;
    assert(ReadControllerByteAtAddress(0x00128056ul) == 0x5au);
    assert(firmware_memory[0x18014] == 0x56u && firmware_memory[0x18015] == 0x80u && firmware_memory[0x18016] == 0x12u && firmware_memory[0x18017] == 0u);
    assert(write_count == 5u && write_trace[0] == 0x18014ul && write_values[0] == 0x56u && write_trace[1] == 0x18015ul && write_values[1] == 0x80u && write_trace[2] == 0x18016ul
           && write_values[2] == 0x12u && write_trace[3] == 0x18017ul && write_values[3] == 0x80u && write_trace[4] == 0x18017ul && write_values[4] == 0u);
    assert(sfr_memory[0xa8] == 0x83u && sfr_memory[0xa9] == 0x41u && sfr_write_count == 3u && sfr_write_trace[0] == 0xa8u && sfr_write_values[0] == 3u && sfr_write_trace[1] == 0xa8u
           && sfr_write_values[1] == 0x83u && sfr_write_trace[2] == 0xa9u && sfr_write_values[2] == 0x41u);
}

static void test_controller_buffer_byte_atomic(void)
{
    static const fw_addr_t offsets[] = { 0x002345ul, 0xf00010ul };
    static const fw_addr_t physical_addresses[] = { 0x102345ul, 0x000010ul };
    size_t index;

    for(index = 0u; index != sizeof(offsets) / sizeof(offsets[0]); ++index)
    {
        clear_memory(0u);
        sfr_memory[0xa8u] = 0xd5u;
        sfr_memory[0xa9u] = 0x5au;
        firmware_memory[physical_addresses[index]] = (u8)(0xa0u + index);

        assert(ReadControllerBufferByteAtomic(offsets[index]) == (u8)(0xa0u + index));
        assert(read_count == 1u && read_trace[0] == physical_addresses[index]);
        assert(sfr_read_count == 2u && sfr_read_trace[0] == 0xa8u && sfr_read_trace[1] == 0xa9u);
        assert(sfr_write_count == 3u && sfr_write_trace[0] == 0xa8u && sfr_write_values[0] == 0x55u && sfr_write_trace[1] == 0xa8u && sfr_write_values[1] == 0xd5u && sfr_write_trace[2] == 0xa9u
               && sfr_write_values[2] == 0x5au);
        assert(sfr_memory[0xa8u] == 0xd5u && sfr_memory[0xa9u] == 0x5au);
    }
}

static void test_submit_controller_command80_at_buffer_address_and_wait(void)
{
    static const fw_addr_t expected_addresses[18] = { 0x018021ul, 0x018020ul, 0x01801ful, 0x0014daul, 0x018020ul, 0x018021ul, 0x018010ul, 0x018011ul, 0x018012ul, 0x018029ul, 0x000fabul, 0x018003ul,
        0x018022ul, 0x000fabul, 0x018003ul, 0x018021ul, 0x018020ul, 0x01801ful };
    static const u8 expected_values[18] = { 0x00u, 0x00u, 0x00u, 0x00u, 0xe0u, 0xc3u, 0x56u, 0x34u, 0x12u, 0x7cu, 0xe5u, 0xe5u, 0x80u, 0xa5u, 0xa5u, 0x00u, 0x00u, 0x00u };
    static const fw_addr_t expected_reads[5] = { 0x000fabul, 0x0014daul, 0x0014daul, 0x0014daul, 0x000fabul };
    size_t index;

    clear_memory(0u);
    firmware_memory[0x000fabul] = 0xa5u;
    controller_command80_complete_after = 3u;

    SubmitControllerCommand80AtBufferAddressAndWait(0xab123456ul, 0x7cu);

    assert(write_count == 18u);
    for(index = 0u; index != 18u; ++index)
    {
        assert(write_trace[index] == expected_addresses[index]);
        assert(write_values[index] == expected_values[index]);
    }
    assert(read_count == 5u);
    for(index = 0u; index != 5u; ++index)
        assert(read_trace[index] == expected_reads[index]);
    assert(controller_command80_completion_reads == 3u);
    assert(firmware_memory[0x018010ul] == 0x56u);
    assert(firmware_memory[0x018011ul] == 0x34u);
    assert(firmware_memory[0x018012ul] == 0x12u);
    assert(firmware_memory[0x018029ul] == 0x7cu);
    assert(firmware_memory[0x000fabul] == 0xa5u);
    assert(firmware_memory[0x018003ul] == 0xa5u);
    assert(firmware_memory[0x018021ul] == 0u);
    assert(firmware_memory[0x018020ul] == 0u);
    assert(firmware_memory[0x01801ful] == 0u);

    clear_memory(0u);
    controller_command80_complete_after = 1u;
    SubmitControllerCommand80AtBufferAddressAndWait(0xfffffffful, 0u);
    assert(firmware_memory[0x018010ul] == 0xffu);
    assert(firmware_memory[0x018011ul] == 0xffu);
    assert(firmware_memory[0x018012ul] == 0xffu);
}

static void test_acquire_zero_state_controller_record_index_runs(void)
{
    static const u8 index_states[8] = { 1u, 0u, 0u, 2u, 0u, 0u, 0u, 0u };
    static const u16 expected_read_indices[10] = { 0u, 1u, 1u, 2u, 3u, 4u, 4u, 5u, 6u, 7u };
    fw_addr_t table_address = 0x002b4000ul;
    unsigned table_read_index = 0u;
    unsigned read_index;
    size_t index;

    clear_memory(0u);
    firmware_memory[0x00fafful] = 0x00u;
    firmware_memory[0x00fb00ul] = 0x2bu;
    firmware_memory[0x00fb01ul] = 0x40u;
    firmware_memory[0x00fb02ul] = 0x00u;
    for(index = 0u; index != 8u; ++index)
        firmware_memory[table_address + index] = index_states[index];

    assert(AcquireZeroStateControllerRecordIndexRuns(7u, 0x5au) == 0u);
    assert(controller_zero_run_call_count == 2u);
    assert(controller_zero_run_first_indices[0] == 1u && controller_zero_run_last_indices[0] == 2u && controller_zero_run_modes[0] == 0x5au);
    assert(controller_zero_run_first_indices[1] == 4u && controller_zero_run_last_indices[1] == 7u && controller_zero_run_modes[1] == 0x5au);
    assert(read_count == 50u);
    for(read_index = 0u; read_index != read_count; read_index += 5u)
    {
        assert(read_trace[read_index] == 0x00fafful);
        assert(read_trace[read_index + 1u] == 0x00fb00ul);
        assert(read_trace[read_index + 2u] == 0x00fb01ul);
        assert(read_trace[read_index + 3u] == 0x00fb02ul);
        assert(read_trace[read_index + 4u] == table_address + expected_read_indices[table_read_index]);
        table_read_index++;
    }
    assert(table_read_index == 10u);

    clear_memory(0u);
    firmware_memory[0x00fafful] = 0x00u;
    firmware_memory[0x00fb00ul] = 0x2bu;
    firmware_memory[0x00fb01ul] = 0x40u;
    firmware_memory[0x00fb02ul] = 0x00u;
    firmware_memory[table_address] = 0u;
    firmware_memory[table_address + 1u] = 1u;
    controller_zero_run_abort_on_call = 1u;
    assert(AcquireZeroStateControllerRecordIndexRuns(4u, 3u) == 1u);
    assert(controller_zero_run_call_count == 1u);
    assert(controller_zero_run_first_indices[0] == 0u && controller_zero_run_last_indices[0] == 0u && controller_zero_run_modes[0] == 3u);
}

static void reset_controller_state_profile_observers(void)
{
    controller_state_profile_write_count = 0u;
    controller_state_profile_read_count = 0u;
    controller_state_profile_read_value_count = 0u;
    controller_state_profile_word_count = 0u;
    controller_state_profile_configure_count = 0u;
}

static void assert_controller_state_profile_prefix(u8 range_low, u8 range_high)
{
    static const fw_addr_t addresses[12] = { 0x01809aul, 0x018496ul, 0x018497ul, 0x018498ul, 0x018499ul, 0x01849aul, 0x01849bul, 0x01849cul, 0x01849eul, 0x0180eeul, 0x0180eful, 0x01849dul };
    static const u8 values[12] = { 0x80u, 0xc0u, 0x80u, 0x7fu, 0x81u, 0x19u, 0x33u, 0x91u, 0x04u, 0u, 0u, 0xc0u };
    static const u16 words[7] = { 0x0098u, 0x00a3u, 0x00a6u, 0x00a3u, 0x0090u, 0x0050u, 0x000au };
    unsigned index;

    assert(controller_state_profile_write_count >= 12u);
    for(index = 0u; index != 12u; ++index)
    {
        assert(controller_state_profile_write_addresses[index] == addresses[index]);
        assert(controller_state_profile_write_values[index] == (index == 9u ? range_low : index == 10u ? range_high : values[index]));
    }
    assert(controller_state_profile_word_count == 7u);
    for(index = 0u; index != 7u; ++index)
    {
        assert(controller_state_profile_words[index] == words[index]);
        assert(controller_state_profile_selectors[index] == (u16)(0x0180u + index));
    }
    assert(controller_state_profile_configure_count == 1u);
}

static void test_configure_controller_state_profile_from_firmware_defaults(void)
{
    unsigned index;

    clear_memory(0u);
    reset_controller_state_profile_observers();
    firmware_memory[0x0180f8ul] = 0x7fu;
    ConfigureControllerStateProfileFromFirmwareDefaults(0u, 0x1234u);
    assert_controller_state_profile_prefix(0x34u, 0x12u);
    assert(controller_state_profile_write_count == 12u);
    assert(controller_state_profile_read_count == 0u);
    assert(read_count == 1u && read_trace[0] == 0x0180f8ul);

    clear_memory(0u);
    reset_controller_state_profile_observers();
    firmware_memory[0x0180f8ul] = 0x80u;
    controller_state_profile_read_values[0] = 0u;
    controller_state_profile_read_values[1] = 2u;
    controller_state_profile_read_values[2] = 1u;
    controller_state_profile_read_value_count = 3u;
    ConfigureControllerStateProfileFromFirmwareDefaults(1u, 0x4567u);
    assert_controller_state_profile_prefix(0x67u, 0xc5u);
    assert(controller_state_profile_write_count == 13u);
    assert(controller_state_profile_write_addresses[12] == 0x01849dul && controller_state_profile_write_values[12] == 0u);
    assert(controller_state_profile_read_count == 3u);
    assert(read_count == 3u);
    for(index = 0u; index != read_count; ++index)
        assert(read_trace[index] == 0x0180f8ul);
}

