static void set_radial_pickup_parameter_record(fw_addr_t address, u16 selector, u16 value)
{
    firmware_memory[address] = (u8)(selector >> 8);
    firmware_memory[address + 1ul] = (u8)selector;
    firmware_memory[address + 2ul] = (u8)(value >> 8);
    firmware_memory[address + 3ul] = (u8)value;
}

static void test_program_radial_pickup_move_parameter_sequence(void)
{
    static const u16 magnitudes[10] = { 99u, 100u, 249u, 250u, 499u, 500u, 999u, 1000u, 1499u, 1500u };
    static const u8 selected_tables[10] = { 0u, 1u, 1u, 2u, 2u, 3u, 3u, 4u, 4u, 5u };
    unsigned case_index;

    for(case_index = 0u; case_index != 10u; ++case_index)
    {
        u8 table_index;

        clear_memory(0u);
        reset_radial_pickup_parameter_observers();
        for(table_index = 0u; table_index != 6u; ++table_index)
        {
            set_memory_big_endian_u32_far(0x00ff85a8ul + (fw_addr_t)table_index * 4ul, 0x00fe0000ul + (fw_addr_t)table_index * 0x10ul);
            set_radial_pickup_parameter_record(0x00fe0000ul + (fw_addr_t)table_index * 0x10ul, (u16)(0x0200u + table_index), (u16)(0x1000u + table_index));
            set_radial_pickup_parameter_record(0x00fe0004ul + (fw_addr_t)table_index * 0x10ul, 0xffffu, 0xffffu);
        }

        ProgramRadialPickupMoveParameterSequenceForMagnitude(magnitudes[case_index]);
        assert(radial_pickup_parameter_word_count == 1u);
        assert(radial_pickup_parameter_words[0] == (u16)(0x1000u + selected_tables[case_index]));
        assert(radial_pickup_parameter_selectors[0] == (u16)(0x0200u + selected_tables[case_index]));
        assert(radial_pickup_parameter_port_count == 0u);
    }

    for(case_index = 0u; case_index != 4u; ++case_index)
    {
        static const u8 state_1130[4] = { 1u, 1u, 0u, 1u };
        static const u8 state_1131[4] = { 1u, 0u, 1u, 1u };
        static const u8 error_fae[4] = { 0u, 0u, 0u, 3u };
        static const u8 expected_value[4] = { 0xabu, 0x0fu, 9u, 0xabu };

        clear_memory(0u);
        reset_radial_pickup_parameter_observers();
        set_memory_big_endian_u32_far(0x00ff85a8ul, 0x00fe0100ul);
        set_radial_pickup_parameter_record(0x00fe0100ul, 0x0180u, 0x1234u);
        set_radial_pickup_parameter_record(0x00fe0104ul, 0xf000u, 0x00abu);
        set_radial_pickup_parameter_record(0x00fe0108ul, 0x0181u, 0x5678u);
        set_radial_pickup_parameter_record(0x00fe010cul, 0xffffu, 0xffffu);
        firmware_memory[0x001130ul] = state_1130[case_index];
        firmware_memory[0x001131ul] = state_1131[case_index];
        firmware_memory[0x000faeul] = error_fae[case_index];

        ProgramRadialPickupMoveParameterSequenceForMagnitude(0u);
        assert(radial_pickup_parameter_word_count == 2u);
        assert(radial_pickup_parameter_words[0] == 0x1234u && radial_pickup_parameter_selectors[0] == 0x0180u);
        assert(radial_pickup_parameter_words[1] == 0x5678u && radial_pickup_parameter_selectors[1] == 0x0181u);
        assert(radial_pickup_parameter_port_count == (error_fae[case_index] == 3u ? 2u : 1u));
        assert(radial_pickup_parameter_port_addresses[0] == 0x01849eul && radial_pickup_parameter_port_values[0] == expected_value[case_index]);
        assert(radial_pickup_parameter_events[0] == 1u && radial_pickup_parameter_events[1] == 2u);
        if(error_fae[case_index] == 3u)
        {
            assert(radial_pickup_parameter_port_addresses[1] == 0x01849eul && radial_pickup_parameter_port_values[1] == 1u);
            assert(radial_pickup_parameter_events[2] == 2u && radial_pickup_parameter_events[3] == 1u);
        }
        else
        {
            assert(radial_pickup_parameter_events[2] == 1u);
        }
    }
}

