static void test_restore_controller_state_after_scaled_radial_pickup_move(void)
{
    clear_memory(0u);
    reset_radial_pickup_restore_observers();
    initialize_radial_pickup_restore_common();
    firmware_memory[0x001006ul] = 1u;
    set_memory_big_endian_u16(0x112eu, 61u);
    firmware_memory[0x001130ul] = 1u;
    RestoreControllerStateAfterScaledRadialPickupMove();
    assert_radial_pickup_restore_common(600u);
    assert(radial_pickup_restore_tolerance_count == 1u && radial_pickup_restore_tolerance_first[0] == 0u && radial_pickup_restore_tolerance_second[0] == 0u);
    assert(radial_pickup_restore_step_count == 4u && radial_pickup_restore_steps[0] == 1u && radial_pickup_restore_steps[1] == 2u && radial_pickup_restore_steps[2] == 3u
           && radial_pickup_restore_steps[3] == 4u);

    clear_memory(0u);
    reset_radial_pickup_restore_observers();
    initialize_radial_pickup_restore_common();
    radial_pickup_restore_read_values[0] = 0u;
    radial_pickup_restore_read_value_count = 1u;
    firmware_memory[0x001006ul] = 1u;
    firmware_memory[0x000e43ul] = 24u;
    set_memory_big_endian_u16(0x112eu, 62u);
    set_memory_big_endian_u16(0x10c0u, 620u);
    RestoreControllerStateAfterScaledRadialPickupMove();
    assert_radial_pickup_restore_common(800u);
    assert(radial_pickup_restore_tolerance_count == 1u && radial_pickup_restore_tolerance_first[0] == 1u && radial_pickup_restore_tolerance_second[0] == 1u);
    assert(get_memory_big_endian_u16(0x1200u) == 100u);

    clear_memory(0u);
    reset_radial_pickup_restore_observers();
    initialize_radial_pickup_restore_common();
    radial_pickup_restore_read_values[0] = 0u;
    radial_pickup_restore_read_value_count = 1u;
    firmware_memory[0x001006ul] = 1u;
    firmware_memory[0x000e43ul] = 9u;
    set_memory_big_endian_u16(0x112eu, 124u);
    set_memory_big_endian_u16(0x10c0u, 619u);
    firmware_memory[0x001306ul] = 0xadu;
    RestoreControllerStateAfterScaledRadialPickupMove();
    assert(get_memory_big_endian_u16(0x1200u) == 30u);
    assert(firmware_memory[0x001306ul] == 0xa9u);

    clear_memory(0u);
    reset_radial_pickup_restore_observers();
    initialize_radial_pickup_restore_common();
    radial_pickup_restore_read_values[0] = 0u;
    radial_pickup_restore_read_value_count = 1u;
    firmware_memory[0x001006ul] = 0u;
    firmware_memory[0x000e43ul] = 8u;
    set_memory_big_endian_u16(0x112eu, 124u);
    RestoreControllerStateAfterScaledRadialPickupMove();
    assert(get_memory_big_endian_u16(0x1200u) == 30u);
    assert(radial_pickup_restore_step_count == 3u && radial_pickup_restore_steps[0] == 1u && radial_pickup_restore_steps[1] == 2u && radial_pickup_restore_steps[2] == 4u);
}

