static void test_select_controller_profile_for_operating_code(void)
{
    unsigned inherited_profile;

    clear_memory(0u);
    firmware_memory[0x0e47u] = 23u;
    firmware_memory[0x1058u] = 10u;
    firmware_memory[0x1059u] = 20u;
    for(inherited_profile = 0u; inherited_profile < 256u; ++inherited_profile)
    {
        u8 expected = (u8)inherited_profile;
        u8 coordinate = (u8)(inherited_profile ^ 0xa5u);

        if(expected < 10u)
            expected = 10u;
        else if(expected > 20u)
            expected = 20u;
        read_count = 0u;
        write_count = 0u;
        reset_controller_profile_selector_observers((u8)inherited_profile, 0xffu);
        assert(SelectControllerProfileForOperatingCode(coordinate) == expected);
        assert(controller_profile_selector_capture_count == 1u && controller_profile_selector_captured_coordinate == coordinate);
        assert(controller_profile_selector_compute_count == 0u);
        assert(write_count == 0u);
    }

    clear_memory(0u);
    firmware_memory[0x0e47u] = 24u;
    firmware_memory[0x1058u] = 10u;
    firmware_memory[0x1059u] = 20u;
    set_memory_big_endian_u16(0xf9fcu, 0x9abcu);
    reset_controller_profile_selector_observers(0xfeu, 17u);
    assert(SelectControllerProfileForOperatingCode(0x34u) == 17u);
    assert(controller_profile_selector_capture_count == 1u && controller_profile_selector_captured_coordinate == 0x34u);
    assert(controller_profile_selector_compute_count == 1u && controller_profile_selector_computed_coordinate == 0x34u && controller_profile_selector_computed_endpoint == 0x9abcu);
    assert(read_count == 7u && read_trace[0] == 0x000e47ul && read_trace[1] == 0x00f9fcul && read_trace[2] == 0x00f9fdul && read_trace[3] == 0x001058ul && read_trace[4] == 0x001059ul
           && read_trace[5] == 0x00fb88ul && read_trace[6] == 0x00fb88ul && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0e47u] = 24u;
    firmware_memory[0x1058u] = 10u;
    firmware_memory[0x1059u] = 20u;
    firmware_memory[0xfb88u] = 2u;
    reset_controller_profile_selector_observers(0u, 0xffu);
    assert(SelectControllerProfileForOperatingCode(0x78u) == 0x10u);
    assert(controller_profile_selector_compute_count == 1u && read_trace[read_count - 2u] == 0x00fb88ul && read_trace[read_count - 1u] == 0x00fb9bul);

    clear_memory(0u);
    firmware_memory[0x0e47u] = 24u;
    firmware_memory[0x1058u] = 10u;
    firmware_memory[0x1059u] = 20u;
    firmware_memory[0xfb88u] = 3u;
    reset_controller_profile_selector_observers(0u, 12u);
    assert(SelectControllerProfileForOperatingCode(0x56u) == 0x10u);
    assert(controller_profile_selector_compute_count == 1u && read_trace[read_count - 3u] == 0x00fb88ul && read_trace[read_count - 2u] == 0x00fb88ul && read_trace[read_count - 1u] == 0x00fb9bul);

    firmware_memory[0xfb9bu] = 1u;
    read_count = 0u;
    reset_controller_profile_selector_observers(0u, 12u);
    assert(SelectControllerProfileForOperatingCode(0x56u) == 12u);
}

