static void test_update_secondary_controller_operating_profile(void)
{
    static const u8 capture_only[] = { 1u };
    static const u8 selected_only[] = { 1u, 2u };
    static const u8 changed_no_interpolation[] = { 1u, 2u, 3u, 4u };
    static const u8 changed_with_interpolation[] = { 1u, 2u, 3u, 4u, 5u };
    static const u8 changed_with_parameter[] = { 1u, 2u, 3u, 4u, 6u };

    clear_memory(0u);
    firmware_memory[0xfa03u] = 0x11u;
    firmware_memory[0x0e51u] = 0x22u;
    firmware_memory[0x0e4fu] = 0x33u;
    reset_secondary_profile_update_observers(0xa5u, 9u);
    UpdateSecondaryControllerOperatingProfile();
    assert_secondary_profile_update_events(capture_only, 1u);
    assert(read_count == 1u && read_trace[0] == 0x00103aul && write_count == 0u);
    assert(firmware_memory[0xfa03u] == 0x11u && firmware_memory[0x0e51u] == 0x22u && firmware_memory[0x0e4fu] == 0x33u);

    clear_memory(0u);
    firmware_memory[0x103au] = 0x80u;
    firmware_memory[0x1137u] = 0x44u;
    firmware_memory[0xfa03u] = 9u;
    reset_secondary_profile_update_observers(0xa5u, 9u);
    UpdateSecondaryControllerOperatingProfile();
    assert_secondary_profile_update_events(selected_only, 2u);
    assert(secondary_profile_update_coordinate == 0x44u && secondary_profile_update_selector_input == 0xa5u);
    assert(read_count == 3u && read_trace[0] == 0x00103aul && read_trace[1] == 0x001137ul && read_trace[2] == 0x00fa03ul && write_count == 0u);

    clear_memory(0u);
    firmware_memory[0x103au] = 0x80u;
    firmware_memory[0x1137u] = 0x5au;
    firmware_memory[0xfa03u] = 1u;
    firmware_memory[0x0e47u] = 9u;
    reset_secondary_profile_update_observers(0xc3u, 7u);
    UpdateSecondaryControllerOperatingProfile();
    assert_secondary_profile_update_events(changed_no_interpolation, 4u);
    assert(secondary_profile_update_coordinate == 0x5au && secondary_profile_update_selector_input == 0xc3u && secondary_profile_update_applied_profile == 7u);
    assert(read_count == 4u && read_trace[3] == 0x000e47ul);
    assert(
        write_count == 3u && write_trace[0] == 0x00fa03ul && write_trace[1] == 0x000e51ul && write_trace[2] == 0x000e4ful && write_values[0] == 7u && write_values[1] == 7u && write_values[2] == 7u);

    clear_memory(0u);
    firmware_memory[0x103au] = 0x80u;
    firmware_memory[0xfa03u] = 1u;
    firmware_memory[0x0e47u] = 9u;
    bit_0038 = 1u;
    reset_secondary_profile_update_observers(0x11u, 12u);
    UpdateSecondaryControllerOperatingProfile();
    assert_secondary_profile_update_events(changed_with_interpolation, 5u);
    assert(secondary_profile_update_interpolated_profile == 12u && secondary_profile_update_parameter == 0u);

    clear_memory(0u);
    firmware_memory[0x103au] = 0x80u;
    firmware_memory[0xfa03u] = 1u;
    firmware_memory[0x0e47u] = 10u;
    reset_secondary_profile_update_observers(0x22u, 8u);
    UpdateSecondaryControllerOperatingProfile();
    assert_secondary_profile_update_events(changed_with_parameter, 5u);
    assert(secondary_profile_update_parameter == 0xf049u && write_count == 3u);

    clear_memory(0u);
    firmware_memory[0x103au] = 0x80u;
    firmware_memory[0xfa03u] = 1u;
    firmware_memory[0x0e47u] = 10u;
    reset_secondary_profile_update_observers(0x33u, 7u);
    UpdateSecondaryControllerOperatingProfile();
    assert_secondary_profile_update_events(changed_no_interpolation, 4u);
    assert(secondary_profile_update_parameter == 0u && write_count == 3u);
}

