    assert(read_count == 13u && write_count == 11u && read_trace[9] == 0x00ef85ul && read_trace[10] == 0x00ef86ul && read_trace[11] == 0x00ef87ul && read_trace[12] == 0x00ef88ul);

    clear_memory(0u);
