    assert(firmware_memory[0x0c83u] == 0xdfu);
    assert(bit_0547 == 1u && bit_0546 == 1u && sfr_memory[0xa9u] == 0x85u);
    assert(runtime_main_programmer_checksum_start == 0xfffffffful && runtime_main_programmer_service_count == 0u && runtime_main_programmer_invoke_count == 0u);

    clear_memory(0u);
    reset_runtime_main_programmer_observers();
    runtime_main_programmer_revision_result = 1u;
    runtime_main_programmer_header_result = 1u;
    firmware_memory[0x0c83u] = 0x3fu;
    sfr_memory[0xa9u] = 0x20u;
    assert(ValidateAndInvokeRuntimeMainFirmwareProgrammer() == 0u);
    assert(runtime_main_programmer_event_count == 3u && runtime_main_programmer_events[0] == 1u && runtime_main_programmer_events[1] == 2u && runtime_main_programmer_events[2] == 3u);
    assert(runtime_main_programmer_checksum_start == 0ul && runtime_main_programmer_checksum_end == 0x00079ffeul);
    assert(firmware_memory[0x0c83u] == 0x1fu && bit_0547 == 1u && bit_0546 == 1u && sfr_memory[0xa9u] == 0x24u);
    assert(runtime_main_programmer_service_count == 0u && runtime_main_programmer_invoke_count == 0u);

    clear_memory(0u);
    reset_runtime_main_programmer_observers();
