    firmware_memory[0x1312u] = 0xdeu;
    firmware_memory[0x1313u] = 0xadu;
    firmware_memory[0x1314u] = 0xbeu;
    firmware_memory[0x1315u] = 0xefu;
    bit_0547 = 1u;
    bit_0546 = 0u;
    sfr_memory[0xa9u] = 0x81u;
    assert(ValidateAndInvokeRuntimeMainFirmwareProgrammer() == 1u);
    assert(runtime_main_programmer_event_count == 5u && runtime_main_programmer_events[0] == 1u && runtime_main_programmer_events[1] == 2u && runtime_main_programmer_events[2] == 3u
           && runtime_main_programmer_events[3] == 4u && runtime_main_programmer_events[4] == 5u);
    assert(runtime_main_programmer_service_count == 1u && runtime_main_programmer_service_ea == 1u && runtime_main_programmer_service_ec == 1u && runtime_main_programmer_service_a9 == 0x85u
           && runtime_main_programmer_service_fa == 0x12u && runtime_main_programmer_service_entry == 0xdeadbeeful);
    assert(runtime_main_programmer_invoke_count == 1u && runtime_main_programmer_invoke_ea == 0u && runtime_main_programmer_invoke_ec == 1u && runtime_main_programmer_invoke_a9 == 0x85u
           && runtime_main_programmer_invoke_fa == 0xffu && runtime_main_programmer_invoke_entry == 0x00ff4000ul);
    assert(firmware_memory[0x0c83u] == 0xdfu && bit_0547 == 0u && bit_0546 == 1u && sfr_memory[0xa9u] == 0x85u && firmware_memory[0xfau] == 0xffu && runtime_main_programmer_checksum_start == 0ul
           && runtime_main_programmer_checksum_end == 0x00079ffeul);
