static void test_prepare_media_write_pipeline_state(void)
{
    static const u8 failure_events[] = { 1u, 2u, 3u, 4u, 5u };
    static const u8 success_events[] = { 1u, 2u, 3u, 4u, 5u, 6u, 7u, 8u, 9u, 10u, 11u };

    clear_memory(0u);
    reset_prepare_write_pipeline_observers(0u);
    firmware_memory[0x0fafu] = 2u;
    firmware_memory[0x0c84u] = 0xa5u;
    firmware_memory[0x0c89u] = 0x40u;
    firmware_memory[0x1037u] = 0xffu;
    PrepareMediaWritePipelineState();
    assert(firmware_memory[0x0e3fu] == 1u && firmware_memory[0x0fafu] == 3u && firmware_memory[0x1037u] == 0u && firmware_memory[0x0c84u] == 0xa5u && firmware_memory[0x0c89u] == 0x42u
           && prepare_write_pipeline_coroutine_entry == 0x00f84a00ul);
    assert(prepare_write_pipeline_event_count == sizeof(failure_events) && memcmp(prepare_write_pipeline_events, failure_events, sizeof(failure_events)) == 0);

    clear_memory(0xa5u);
    reset_prepare_write_pipeline_observers(1u);
    firmware_memory[0x0fafu] = 1u;
    firmware_memory[0x0c84u] = 0xafu;
    firmware_memory[0x0c89u] = 0xffu;
    firmware_memory[0x0c8au] = 0xffu;
    firmware_memory[0x0c8bu] = 0xffu;
    set_memory_big_endian_u32(0x156au, 10ul);
    set_memory_big_endian_u32(0x1562u, 0x12345678ul);
    PrepareMediaWritePipelineState();
    assert(firmware_memory[0x0fafu] == 1u && firmware_memory[0x0e3fu] == 0xa5u && get_memory_big_endian_u16(0x1298u) == 0u && get_memory_big_endian_u16(0x1294u) == 0u
           && get_memory_big_endian_u16(0x1296u) == 0u && get_memory_big_endian_u16(0x1292u) == 0u && get_memory_big_endian_u16(0x129au) == 9u && get_memory_big_endian_u16(0x129cu) == 4u
           && get_memory_big_endian_u32(0x129eu) == 0x000088bbul && get_memory_big_endian_u32(0x1262u) == 0ul && get_memory_big_endian_u32(0x1266u) == 0ul
           && get_memory_big_endian_u32(0x126au) == 0x12345678ul && get_memory_big_endian_u32(0x126eu) == 0ul);
    assert(get_memory_big_endian_u32(0x1488u) == 0ul && get_memory_big_endian_u32(0x148cu) == 0ul && firmware_memory[0x1490u] == 0u && firmware_memory[0x88b7u] == 0u
           && firmware_memory[0x0c84u] == 0xa7u && firmware_memory[0x0c89u] == 0xfdu && firmware_memory[0x0c8au] == 0xf7u && firmware_memory[0x0c8bu] == 0xfeu);
    assert(prepare_write_pipeline_event_count == sizeof(success_events) && memcmp(prepare_write_pipeline_events, success_events, sizeof(success_events)) == 0);
}

