static void test_ensure_opc_calibration_for_raw_read_operation(void)
{
    clear_memory(0u);
    reset_raw_read_opc_observers();
    firmware_memory[0x0c84u] = 0x80u;
    firmware_memory[0x0c38u] = 8u;
    assert(EnsureOpcCalibrationForRawReadOperation() == 1u);
    assert(raw_read_opc_event_count == 1u && raw_read_opc_events[0] == 1u && raw_read_opc_speed_argument == 8u && firmware_memory[0x0c84u] == 0x80u);

    clear_memory(0u);
    reset_raw_read_opc_observers();
    raw_read_opc_required_result = 1u;
    raw_read_opc_clear_busy_on_yield = 2u;
    raw_read_opc_clear_status_on_yield = 3u;
    firmware_memory[raw_read_opc_status_address] = 0x11u;
    firmware_memory[0x0c38u] = 12u;
    assert(EnsureOpcCalibrationForRawReadOperation() == 1u);
    assert(raw_read_opc_coroutine_entry == 0x00f84a00ul && raw_read_opc_yield_count == 3u && raw_read_opc_update_speed_argument == 12u);
    assert(firmware_memory[0x00e74eu] == 1u && firmware_memory[0x00e74fu] == 0u && firmware_memory[0x000e3fu] == 1u && firmware_memory[0x0015b2u] == 0u && firmware_memory[0x000fafu] == 6u
           && firmware_memory[0x000c84u] == 0u);
    assert(raw_read_opc_event_count == 8u && raw_read_opc_events[0] == 1u && raw_read_opc_events[1] == 2u && raw_read_opc_events[2] == 3u && raw_read_opc_events[3] == 4u
           && raw_read_opc_events[4] == 4u && raw_read_opc_events[5] == 4u && raw_read_opc_events[6] == 5u && raw_read_opc_events[7] == 6u);

    clear_memory(0u);
    reset_raw_read_opc_observers();
    raw_read_opc_required_result = 2u;
    raw_read_opc_sense_key_result = 3u;
    firmware_memory[0x00e74fu] = 1u;
    firmware_memory[0x0015b2u] = 0u;
    firmware_memory[raw_read_opc_status_address] = 0u;
    firmware_memory[0x000c84u] = 0x80u;
    assert(EnsureOpcCalibrationForRawReadOperation() == 0u);
    assert(raw_read_opc_yield_count == 1u && raw_read_opc_coroutine_entry == 0xfffffffful && raw_read_opc_update_speed_argument == 0xffu && firmware_memory[0x000c84u] == 0x80u);

    clear_memory(0u);
    reset_raw_read_opc_observers();
    firmware_memory[0x00fbf1u] = 1u;
    firmware_memory[0x000c84u] = 0x20u;
    assert(EnsureOpcCalibrationForRawReadOperation() == 1u);
    assert(firmware_memory[0x000c84u] == 0x28u);
}

