static void test_set_vendor_f3_state_words_and_flag(void)
{
    static const u16 values[] = { 0u, 1u, 0x1234u, 0xffffu };
    unsigned index;

    for(index = 0u; index != sizeof(values) / sizeof(values[0]); ++index)
    {
        u16 value = values[index];

        clear_memory(0xa5u);
        bit_0039 = 0u;
        SetVendorF3StateWordsAndFlag(value);
        assert(bit_0039 == 1u && firmware_memory[0xfacfu] == (u8)(value >> 8) && firmware_memory[0xfad0u] == (u8)value && firmware_memory[0xf96eu] == (u8)(value >> 8)
               && firmware_memory[0xf96fu] == (u8)value && firmware_memory[0xf971u] == 0xa7u && read_count == 1u && read_trace[0] == 0xf971ul && write_count == 5u && write_trace[0] == 0xfacful
               && write_trace[1] == 0xfad0ul && write_trace[2] == 0xf96eul && write_trace[3] == 0xf96ful && write_trace[4] == 0xf971ul);
    }
}

static void test_load_or_calibrate_controller_parameter_fc(void)
{
    static const u8 state_two_events[9] = { 2u, 3u, 3u, 4u, 5u, 6u, 7u, 4u, 8u };
    static const u8 indexed_state_events[10] = { 1u, 1u, 2u, 3u, 4u, 5u, 6u, 7u, 4u, 8u };
    static const u8 stored_events[3] = { 1u, 1u, 9u };

    clear_memory(0u);
    reset_parameter_fc_load_observers();
    firmware_memory[0x1008u] = 2u;
    parameter_fc_port_read_results[0] = 0xffu;
    parameter_fc_port_read_results[1] = 0x80u;
    parameter_fc_port_read_count = 2u;
    parameter_fc_calibration_result = 0x5au;
    assert(LoadOrCalibrateControllerParameterFC() == 0x5au);
    assert_parameter_fc_load_events(state_two_events, 9u);
    assert(parameter_fc_indexed_call_count == 0u && parameter_fc_port_write_address == 0x0180acul && parameter_fc_port_write_value == 2u && parameter_fc_port_read_index == 2u
           && parameter_fc_reset_count == 2u && parameter_fc_reset_channels[0] == 2u && parameter_fc_reset_channels[1] == 2u && parameter_fc_wait_duration == 4000u && parameter_fc_wait_yield == 0u);

    clear_memory(0u);
    reset_parameter_fc_load_observers();
    firmware_memory[0x1008u] = 1u;
    parameter_fc_indexed_results[0] = 2u;
    parameter_fc_indexed_results[1] = 1u;
    parameter_fc_port_read_results[0] = 0u;
    parameter_fc_port_read_count = 1u;
    parameter_fc_calibration_result = 1u;
    assert(LoadOrCalibrateControllerParameterFC() == 1u);
    assert_parameter_fc_load_events(indexed_state_events, 10u);
    assert(parameter_fc_indexed_call_count == 2u && parameter_fc_indexed_arguments[0] == 5u && parameter_fc_indexed_arguments[1] == 8u);

    clear_memory(0u);
    reset_parameter_fc_load_observers();
    firmware_memory[0x1008u] = 0u;
    firmware_memory[0xfac0u] = 0xa5u;
    assert(LoadOrCalibrateControllerParameterFC() == 1u);
    assert_parameter_fc_load_events(stored_events, 3u);
    assert(firmware_memory[0xfc0fu] == 0xa5u && parameter_fc_select_code == 4u && read_count == 4u && write_count == 1u && read_trace[0] == 0x1008ul && read_trace[1] == 0x1008ul
           && read_trace[2] == 0xfac0ul && read_trace[3] == 0xfac0ul && write_trace[0] == 0xfc0ful);

    clear_memory(0u);
    reset_parameter_fc_load_observers();
    firmware_memory[0x1008u] = 3u;
    firmware_memory[0xfac1u] = 0xffu;
    assert(LoadOrCalibrateControllerParameterFC() == 1u);
    assert_parameter_fc_load_events(stored_events, 3u);
    assert(firmware_memory[0xfc0fu] == 0u && parameter_fc_select_code == 4u && read_count == 4u && write_count == 2u && read_trace[2] == 0xfac1ul && read_trace[3] == 0xfac1ul
           && write_trace[0] == 0xfc0ful && write_trace[1] == 0xfc0ful);
}

