static void test_probe_controller_read_path_at_current_frame(void)
{
    static const fw_addr_t success_addresses[9] = { 0x0180c0ul, 0x0180cful, 0x0180c0ul, 0x0180cful, 0x0180c0ul, 0x0180cful, 0x0180c0ul, 0x0180cful, 0x018006ul };
    static const u8 success_values[9] = { 0u, 0xc4u, 0x20u, 0xc0u, 0x70u, 0xc0u, 0x20u, 0xc0u, 0xc8u };
    unsigned index;

    clear_memory(0u);
    reset_current_frame_probe_observers();
    set_memory_big_endian_u32(0x1235u, 100ul);
    firmware_memory[0x1157u] = 2u;
    current_frame_probe_mode_change_after_strobe = 2u;
    current_frame_probe_mode_after_strobe = 0u;
    current_frame_probe_sample_results[0] = 0u;
    current_frame_probe_sample_results[1] = 2u;
    current_frame_probe_sample_results[2] = 1u;
    current_frame_probe_sample_count = 3u;
    assert(ProbeControllerReadPathAtCurrentFrame() == 1u);
    assert(current_frame_probe_wait_count == 3u && current_frame_probe_wait_targets[0] == 101l && current_frame_probe_wait_targets[1] == 100l && current_frame_probe_wait_targets[2] == 100l);
    assert(current_frame_probe_sample_index == 3u && current_frame_probe_yield_count == 2u && firmware_memory[0x1217u] == 0x12u);
    assert(current_frame_probe_strobe_count == 9u);
    for(index = 0u; index != 9u; ++index)
    {
        assert(current_frame_probe_strobe_addresses[index] == success_addresses[index]);
        assert(current_frame_probe_strobe_values[index] == success_values[index]);
    }

    clear_memory(0u);
    reset_current_frame_probe_observers();
    set_memory_big_endian_u32(0x1235u, 0xfffffffful);
    current_frame_probe_sample_results[0] = 0u;
    current_frame_probe_sample_results[1] = 2u;
    current_frame_probe_sample_count = 2u;
    current_frame_probe_expire_on_yield = 2u;
    assert(ProbeControllerReadPathAtCurrentFrame() == 0u);
    assert(current_frame_probe_wait_targets[0] == 0l && current_frame_probe_wait_targets[1] == -1l && current_frame_probe_wait_targets[2] == -1l);
    assert(current_frame_probe_sample_index == 2u && current_frame_probe_yield_count == 2u && current_frame_probe_strobe_count == 6u && firmware_memory[0x1217u] == 0xffu);
}

