static void test_run_controller_read_path_calibration_at_target(void)
{
    static const u8 success_events[11] = { 1u, 2u, 3u, 4u, 2u, 5u, 6u, 3u, 7u, 3u, 8u };
    static const u8 first_wait_events[3] = { 1u, 2u, 3u };
    static const u8 second_wait_events[8] = { 1u, 2u, 3u, 4u, 2u, 5u, 6u, 3u };
    static const u8 restore_events[12] = { 1u, 2u, 3u, 4u, 2u, 5u, 6u, 3u, 7u, 3u, 8u, 9u };

    clear_memory(0u);
    reset_read_path_calibration_observers();
    firmware_memory[0x0e4fu] = 0xffu;
    read_path_calibration_readiness_result = 2u;
    read_path_calibration_window_result = 2u;
    assert(RunControllerReadPathCalibrationAtTarget(100000l) == 0u);
    assert_read_path_calibration_events(success_events, 11u);
    assert(read_count == 1u && read_trace[0] == 0x0e4ful && read_path_calibration_wait_count == 3u && read_path_calibration_wait_targets[0] == 97400l && read_path_calibration_wait_targets[1] == 98200l
           && read_path_calibration_wait_targets[2] == 99200l && read_path_calibration_configure_argument == 1u && read_path_calibration_window_argument == 1u);

    clear_memory(0u);
    reset_read_path_calibration_observers();
    firmware_memory[0x0e4fu] = 4u;
    read_path_calibration_wait_results[0] = 2u;
    assert(RunControllerReadPathCalibrationAtTarget(1000l) == 2u);
    assert_read_path_calibration_events(first_wait_events, 3u);
    assert(read_path_calibration_wait_targets[0] == 740l);

    clear_memory(0u);
    reset_read_path_calibration_observers();
    firmware_memory[0x0e4fu] = 4u;
    read_path_calibration_wait_results[1] = 0u;
    assert(RunControllerReadPathCalibrationAtTarget(1000l) == 2u);
    assert_read_path_calibration_events(second_wait_events, 8u);
    assert(read_path_calibration_wait_targets[1] == 820l);

    clear_memory(0u);
    reset_read_path_calibration_observers();
    firmware_memory[0x0e4fu] = 4u;
    read_path_calibration_window_result = 0u;
    assert(RunControllerReadPathCalibrationAtTarget(1000l) == 2u);
    assert_read_path_calibration_events(restore_events, 12u);
    assert(read_path_calibration_wait_targets[2] == 920l && read_path_calibration_restore_argument == 1u);
}

static void assert_write_and_verify_readback(u32 start, u32 end, u8 c88, u8 c8a, u8 expected_during_verify, unsigned expected_mode_writes)
{
    clear_memory(0u);
    set_memory_big_endian_u32_far(0x2bc707ul, start);
    set_memory_big_endian_u32_far(0x2bc70bul, end);
    firmware_memory[0x0c88u] = c88;
    firmware_memory[0x0c8au] = c8a;
    ExecuteWriteAndVerifyReadback();

    assert(get_memory_big_endian_u32(0x0b02u) == start && get_memory_big_endian_u32(0x0b06u) == end - start && firmware_memory[0x0c88u] == c88 && read_verify_seen_c88 == expected_during_verify
           && read_verify_event_count == 3u && read_verify_events[0] == 1u && read_verify_events[1] == 2u && read_verify_events[2] == 3u);
    assert(write_count == 8u + expected_mode_writes);
}

static void test_execute_write_and_verify_readback(void)
{
    assert_write_and_verify_readback(0x12345678ul, 0x12345688ul, 0x25u, 0x00u, 0x25u, 0u);
    assert_write_and_verify_readback(0x00000100ul, 0x00000103ul, 0xa5u, 0x00u, 0x25u, 2u);
    assert_write_and_verify_readback(0xfffffff0ul, 0x00000010ul, 0x25u, 0x04u, 0xa5u, 2u);
}

