static void test_acquire_read_track_information_flags_from_raw_descriptor(void)
{
    static const u8 active_events[] = { 1u, 5u };
    static const u8 start_events[] = { 2u, 3u, 4u, 5u, 4u, 5u, 4u, 5u };
    static const u8 failure_events[] = { 1u, 5u, 2u, 6u, 7u, 4u };

    clear_memory(0u);
    firmware_memory[0xf2c5u] = 0u;
    firmware_memory[0xf2c6u] = 1u;
    firmware_memory[0xf2c7u] = 0u;
    firmware_memory[0x0c2au] = 2u;
    firmware_memory[0x1455u] = 0xffu;
    firmware_memory[0x1459u] = 0xffu;
    firmware_memory[0x1466u] = 0xffu;
    firmware_memory[0x1467u] = 0xffu;
    firmware_memory[0x1468u] = 0xffu;
    firmware_memory[0x0f06u] = 0xffu;
    firmware_memory[0x0f0cu] = 0xffu;
    bit_0008 = 1u;
    bit_001b = bit_001c = bit_001d = bit_0013 = 1u;
    bit_0580 = bit_0581 = 1u;
    read_track_flags_poll_results[0] = 1u;
    read_track_flags_poll_outputs[0] = 0xa5u;
    read_track_flags_poll_count = 1u;
    assert(AcquireReadTrackInformationFlagsFromRawDescriptor(2u) == 0xa5u);
    assert(read_track_flags_position_target == 75l && read_track_flags_poll_index == 1u && read_track_flags_event_count == sizeof(active_events)
           && memcmp(read_track_flags_events, active_events, sizeof(active_events)) == 0);
    assert(get_memory_big_endian_u32(0x1455u) == 1ul && get_memory_big_endian_u32(0x1459u) == 0ul && firmware_memory[0x1466u] == 0u && firmware_memory[0x1467u] == 0u && firmware_memory[0x1468u] == 0u
           && firmware_memory[0x0f06u] == 0u && get_memory_big_endian_u32(0x0f0cu) == 0ul);
    assert(bit_001b == 0u && bit_001c == 0u && bit_001d == 0u && bit_0013 == 0u && bit_0580 == 1u && bit_0581 == 0u);

    clear_memory(0u);
    firmware_memory[0x0c2au] = 0u;
    read_track_flags_poll_results[0] = 0xfeu;
    read_track_flags_poll_results[1] = 0xfeu;
    read_track_flags_poll_results[2] = 1u;
    read_track_flags_poll_outputs[2] = 0x5au;
    read_track_flags_poll_count = 3u;
    assert(AcquireReadTrackInformationFlagsFromRawDescriptor(0u) == 0x5au);
    assert(firmware_memory[0x0c2au] == 2u && get_memory_big_endian_u32(0x1598u) == 150ul && read_track_flags_poll_index == 3u && read_track_flags_event_count == sizeof(start_events)
           && memcmp(read_track_flags_events, start_events, sizeof(start_events)) == 0);
    assert(bit_0580 == 1u && bit_0581 == 0u);

    clear_memory(0u);
    firmware_memory[0xf2b9u] = 0u;
    firmware_memory[0xf2bau] = 2u;
    firmware_memory[0xf2bbu] = 0u;
    firmware_memory[0x0c2au] = 2u;
    bit_0008 = 1u;
    read_track_flags_poll_results[0] = 0u;
    read_track_flags_poll_count = 1u;
    assert(AcquireReadTrackInformationFlagsFromRawDescriptor(0u) == 0x0fu);
    assert(read_track_flags_position_target == 150l && read_track_flags_event_count == sizeof(failure_events) && memcmp(read_track_flags_events, failure_events, sizeof(failure_events)) == 0);
    assert(bit_0580 == 1u && bit_0581 == 0u);
}

