static void test_select_read_track_information_next_writable_frame_position(void)
{
    unsigned mode;
    unsigned write_type;

    for(mode = 0u; mode != 2u; ++mode)
    {
        for(write_type = 0u; write_type != 256u; ++write_type)
        {
            s32 expected;

            clear_memory(0u);
            firmware_memory[0x0c84u] = mode != 0u ? 8u : 0u;
            firmware_memory[0x0c44u] = (u8)write_type;
            firmware_memory[0xdd56u] = 1u;
            set_memory_big_endian_u32(0xdd39u, 0x80000010ul);
            set_memory_big_endian_u32(0xdd69u, 200ul);
            set_memory_big_endian_u32(0xdd4du, 300ul);
            set_memory_big_endian_u32(0x140au, 400ul);
            set_memory_big_endian_u32(0xdd65u, 500ul);
            read_track_next_writable_fallback = 0x12345678l;
            read_track_next_writable_result = -123l;
            read_track_packet_progress_result = 1000l;

            if(mode == 0u)
                expected = write_type < 2u ? -123l : write_type == 2u ? (s32)0x7fffff7aul : write_type == 3u ? 50l : 0x12345678l;
            else
                expected = write_type == 0u ? 850l : write_type == 1u ? 150l : write_type == 2u ? 250l : write_type == 3u ? 350l : 0x12345678l;
            assert(SelectReadTrackInformationNextWritableFramePosition() == expected);
            assert(read_track_next_writable_capture_count == 1u);
            assert(read_track_next_writable_count == (unsigned)(mode == 0u && write_type < 2u));
            assert(read_track_packet_progress_count == (unsigned)(mode != 0u && write_type == 0u));
            if(read_track_packet_progress_count != 0u)
                assert(read_track_packet_progress_argument == 1u);
        }
    }

    clear_memory(0u);
    firmware_memory[0x0c84u] = 8u;
    firmware_memory[0x0c44u] = 0u;
    firmware_memory[0xdd56u] = 0u;
    set_memory_big_endian_u32(0xdd4du, 300ul);
    read_track_next_writable_fallback = -1l;
    assert(SelectReadTrackInformationNextWritableFramePosition() == 150l);
    assert(read_track_next_writable_capture_count == 1u && read_track_next_writable_count == 0u && read_track_packet_progress_count == 0u);
}

static void test_resolve_read_track_information_track_start_frame(void)
{
    fw_addr_t record_address;

    clear_memory(0u);
    set_memory_big_endian_u32(0x00dd3dul, 0x80000010ul);
    assert(ResolveReadTrackInformationTrackStartFrame() == (s32)0x80000010ul);

    clear_memory(0u);
    firmware_memory[0x0c85u] = 4u;
    set_memory_big_endian_u16(0x00b4bbul, 4u);

    record_address = 0x00b4bdul;
    firmware_memory[record_address] = 0x12u;
    firmware_memory[record_address + 1u] = 1u;
    firmware_memory[record_address + 2u] = 1u;

    record_address += 8u;
    firmware_memory[record_address] = 0xf1u;
    firmware_memory[record_address + 2u] = 1u;

    record_address += 8u;
    firmware_memory[record_address] = 0x81u;
    firmware_memory[record_address + 1u] = 2u;

    record_address += 8u;
    firmware_memory[record_address] = 0xa1u;
    firmware_memory[record_address + 1u] = 2u;
    firmware_memory[record_address + 2u] = 1u;
    firmware_memory[record_address + 4u] = 1u;
    firmware_memory[record_address + 5u] = 2u;
    firmware_memory[record_address + 6u] = 3u;
    assert(ResolveReadTrackInformationTrackStartFrame() == 4653l);

    clear_memory(0u);
    firmware_memory[0x0c85u] = 4u;
    set_memory_big_endian_u16(0x00b4bbul, 2u);
    set_memory_big_endian_u32(0x00dd3dul, 12345ul);
    assert(ResolveReadTrackInformationTrackStartFrame() == 12345l);
}

