{
    clear_memory(0u);
    firmware_memory[0x0e41u] = 0x5au;
    assert(RequestReadAcquisitionAndWait(10l, 5l) == 0x5au);
    assert(firmware_memory[0x0c8cu] == 1u && get_memory_big_endian_u32(0x0c8eu) == 15ul && read_acquisition_wait_event_count == 1u && read_acquisition_wait_events[0] == 3u && read_count == 2u
           && write_count == 5u);

    clear_memory(0u);
    firmware_memory[0x0e41u] = 1u;
    assert(RequestReadAcquisitionAndWait(-5l, 1l) == 1u);
    assert(get_memory_big_endian_u32(0x0c8eu) == 1ul && read_acquisition_wait_event_count == 3u && read_acquisition_wait_events[0] == 1u && read_acquisition_wait_events[1] == 2u
           && read_acquisition_wait_events[2] == 3u);

    clear_memory(0u);
    bit_001b = 1u;
    assert(RequestReadAcquisitionAndWait(-5l, 1l) == 0u);
    assert(get_memory_big_endian_u32(0x0c8eu) == 0xfffffffcul && read_acquisition_wait_event_count == 2u && read_acquisition_wait_events[0] == 1u && read_acquisition_wait_events[1] == 3u);

    clear_memory(0u);
    bit_0021 = 1u;
    assert(RequestReadAcquisitionAndWait(0l, 0l) == 0u);
    assert(get_memory_big_endian_u32(0x0c8eu) == 0ul && read_acquisition_wait_event_count == 3u && read_acquisition_wait_events[0] == 1u && read_acquisition_wait_events[1] == 2u
           && read_acquisition_wait_events[2] == 3u);

    clear_memory(0u);
    firmware_memory[0x0e40u] = 1u;
    firmware_memory[0x0e41u] = 0xfeu;
    read_acquisition_wait_clear_after = 3u;
    assert(RequestReadAcquisitionAndWait(0x7fffffffl, 1l) == 0xfeu);
    assert(get_memory_big_endian_u32(0x0c8eu) == 1ul && read_acquisition_wait_yield_count == 3u && read_acquisition_wait_event_count == 6u && read_acquisition_wait_events[0] == 1u
           && read_acquisition_wait_events[1] == 2u && read_acquisition_wait_events[2] == 3u && read_acquisition_wait_events[3] == 4u && read_acquisition_wait_events[4] == 4u
           && read_acquisition_wait_events[5] == 4u && read_count == 5u);
}

static void test_prepare_and_dispatch_read_or_seek_acquisition_at_lba(void)
{
    static const s32 reuse_targets[] = { 97l, 100l, 110l };
    static const s32 dispatch_targets[] = { 96l, 111l };
    unsigned index;

    clear_memory(0u);
    firmware_memory[0x1008u] = 0u;
    set_memory_big_endian_u32(0x12c1u, 1000ul);
    PrepareAndDispatchReadOrSeekAcquisitionAtLba(926l);
    assert(read_or_seek_event_count == 2u && read_or_seek_events[0] == 1u && read_or_seek_events[1] == 2u && read_or_seek_sense_key == 5u && read_or_seek_asc_ascq == 0x2100u
           && read_or_seek_information == 926ul && firmware_memory[0x15e2u] == 0u);

    clear_memory(0u);
    firmware_memory[0x1008u] = 1u;
    set_memory_big_endian_u32(0x12c1u, 1000ul);
    set_memory_big_endian_u32(0x1153u, 2000ul);
    PrepareAndDispatchReadOrSeekAcquisitionAtLba(1851l);
    assert(read_or_seek_event_count == 2u && read_or_seek_sense_key == 5u && read_or_seek_information == 1851ul);

    clear_memory(0u);
    firmware_memory[0x1008u] = 1u;
    firmware_memory[0x0fafu] = 2u;
    set_memory_big_endian_u32(0x12c1u, 1000ul);
    set_memory_big_endian_u32(0x1153u, 2000ul);
    PrepareAndDispatchReadOrSeekAcquisitionAtLba(-200l);
    assert(read_or_seek_event_count == 1u && read_or_seek_events[0] == 3u && firmware_memory[0x0c8cu] == 0u && get_memory_big_endian_u32(0x0c8eu) == 1ul);

    for(index = 0u; index < sizeof(reuse_targets) / sizeof(reuse_targets[0]); ++index)
    {
        clear_memory(0u);
        firmware_memory[0x1008u] = 1u;
        firmware_memory[0x0fafu] = 3u;
        set_memory_big_endian_u32(0x12c1u, 1000ul);
        set_memory_big_endian_u32(0x1153u, 2000ul);
        set_memory_big_endian_u32(0x103du, 100ul);
        PrepareAndDispatchReadOrSeekAcquisitionAtLba(reuse_targets[index] - 150l);
        assert(read_or_seek_event_count == 3u && read_or_seek_events[0] == 4u && read_or_seek_events[1] == 5u && read_or_seek_events[2] == 6u && read_or_seek_coroutine_entry == 0x00f84a00ul);
    }

    for(index = 0u; index < sizeof(dispatch_targets) / sizeof(dispatch_targets[0]); ++index)
    {
        clear_memory(0u);
        firmware_memory[0x1008u] = 1u;
        firmware_memory[0x0fafu] = 3u;
        set_memory_big_endian_u32(0x12c1u, 1000ul);
        set_memory_big_endian_u32(0x1153u, 2000ul);
        set_memory_big_endian_u32(0x103du, 100ul);
        PrepareAndDispatchReadOrSeekAcquisitionAtLba(dispatch_targets[index] - 150l);
        assert(read_or_seek_event_count == 1u && read_or_seek_events[0] == 3u && get_memory_big_endian_u32(0x0c8eu) == (u32)dispatch_targets[index]);
    }
}

static u8 is_common_initial_coroutine_state(u8 state)
{
    switch(state)
    {
    case 1u:
    case 2u:
    case 3u:
    case 4u:
    case 6u:
    case 7u:
    case 17u:
    case 20u:
    case 21u:
    case 22u:
    case 23u:
    case 0xf2u:
    case 0xfdu:
    case 0xffu:
        return 1u;
    default:
        return 0u;
    }
}

static void assert_initial_coroutine_standard_prefix(void)
{
    assert(initial_coroutine_event_count >= 4u && initial_coroutine_events[0] == 1u && initial_coroutine_entries[0] == 0x00fdbe7dul && initial_coroutine_events[1] == 4u
           && initial_coroutine_entries[1] == 0x00f84b00ul && initial_coroutine_events[2] == 3u && initial_coroutine_entries[2] == 0x00f84a00ul && initial_coroutine_events[3] == 2u
           && initial_coroutine_entries[3] == 0x00f84c30ul && initial_coroutine_countdown_reads == 6u && firmware_memory[0x1214u] == 0u);
}

static void test_configure_initial_coroutines(void)
{
    unsigned state;

    for(state = 0u; state != 256u; ++state)
    {
        clear_memory(0u);
        firmware_memory[0x1308u] = 1u;
        firmware_memory[0x130au] = (u8)state;
        ConfigureInitialCoroutines();
        assert_initial_coroutine_standard_prefix();

        if(state == 0u || state == 8u || state == 16u)
        {
            assert(initial_coroutine_event_count == 4u);
        }
        else if(state == 5u)
        {
            assert(initial_coroutine_event_count == 5u && initial_coroutine_events[4] == 2u && initial_coroutine_entries[4] == 0x00f84b0bul);
        }
        else if(state == 15u)
        {
            assert(initial_coroutine_event_count == 5u && initial_coroutine_events[4] == 1u && initial_coroutine_entries[4] == 0x00fb3ed6ul);
        }
        else if(state == 31u)
        {
            assert(initial_coroutine_event_count == 6u && initial_coroutine_events[4] == 2u && initial_coroutine_entries[4] == 0x00f84b0bul && initial_coroutine_events[5] == 1u
                   && initial_coroutine_entries[5] == 0x00feb6bbul);
        }
        else if(is_common_initial_coroutine_state((u8)state) != 0u)
        {
            assert(initial_coroutine_event_count == 5u && initial_coroutine_events[4] == 1u && initial_coroutine_entries[4] == 0x00feb6bbul);
        }
        else
        {
            assert(initial_coroutine_event_count == 5u && initial_coroutine_events[4] == 1u && initial_coroutine_entries[4] == 0x00fdc225ul);
        }
    }

    clear_memory(0u);
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x130au] = 4u;
    firmware_memory[0xf7c01fu] = 1u;
    ConfigureInitialCoroutines();
    assert_initial_coroutine_standard_prefix();
    assert(initial_coroutine_event_count == 4u);

    clear_memory(0u);
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x130au] = 1u;
    firmware_memory[0xfbf1u] = 1u;
    ConfigureInitialCoroutines();
    assert_initial_coroutine_standard_prefix();
    assert(initial_coroutine_event_count == 4u);

    clear_memory(0u);
    firmware_memory[0x1308u] = 2u;
    ConfigureInitialCoroutines();
    assert_initial_coroutine_standard_prefix();
    assert(initial_coroutine_event_count == 4u);

    clear_memory(0u);
    firmware_memory[0x1009u] = 1u;
    initial_coroutine_escape_on_resume1 = 1u;
    if(setjmp(initial_coroutine_escape) == 0)
        ConfigureInitialCoroutines();
    assert(initial_coroutine_event_count == 4u && initial_coroutine_events[0] == 1u && initial_coroutine_entries[0] == 0x00fdbe7dul && initial_coroutine_events[1] == 2u
           && initial_coroutine_entries[1] == 0x00f853cful && initial_coroutine_events[2] == 5u && initial_coroutine_events[3] == 6u);
}

static void run_firmware_main_loop_iteration(void)
{
    if(setjmp(firmware_main_escape) == 0)
        FirmwareMainLoop();
}

static void test_firmware_main_loop(void)
{
    static const u8 cold_events[] = { 1u, 2u, 3u, 4u, 6u, 8u, 9u, 10u, 11u, 12u, 13u, 14u, 5u };
    static const u8 warm_events[] = { 4u, 7u, 11u, 12u };

    clear_memory(0u);
    firmware_memory[0x1157u] = 1u;
    firmware_memory[0x18040u] = 0x5au;
    firmware_memory[0x1302u] = 0x40u;
    firmware_memory[0x15f6u] = 1u;
    firmware_memory[0x0c88u] = 0x20u;
    firmware_main_indexed_results[0] = 1u;
    firmware_main_indexed_results[1] = 0u;
    run_firmware_main_loop_iteration();
    assert(firmware_main_event_count == sizeof(cold_events));
    assert(memcmp(firmware_main_events, cold_events, sizeof(cold_events)) == 0);
    assert(firmware_main_arguments[4] == 0x00f853cful && firmware_main_arguments[12] == 0x00fdbe7dul);
    assert(firmware_main_indexed_call_count == 2u && firmware_main_indexed_states[0] == 5u && firmware_main_indexed_states[1] == 8u);
    assert(firmware_main_configuration_call_count == 1u && firmware_main_configuration_source == 0x001157ul && firmware_main_configuration_offset == 0x47u && firmware_main_configuration_count == 1u);
    assert(firmware_main_bit0029_read_count == 1u && firmware_main_bit0046_read_count == 1u);
    assert(firmware_memory[0x1157u] == 0x5au && firmware_memory[0xfaebu] == 0u);

    clear_memory(0u);
    firmware_memory[0x00fbu] = 1u;
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x1157u] = 1u;
    firmware_memory[0xfaefu] = 0x80u;
    firmware_memory[0xfc48u] = 1u;
    firmware_memory[0x15f6u] = 1u;
    firmware_memory[0x11efu] = 0x08u;
    firmware_main_indexed_results[0] = 2u;
    firmware_main_indexed_results[1] = 1u;
    firmware_main_bit0029 = 1u;
    firmware_main_bit0046 = 1u;
    run_firmware_main_loop_iteration();
    assert(firmware_main_event_count == sizeof(warm_events));
    assert(memcmp(firmware_main_events, warm_events, sizeof(warm_events)) == 0);
    assert(firmware_main_indexed_call_count == 2u && firmware_main_indexed_states[0] == 5u && firmware_main_indexed_states[1] == 8u);
    assert(firmware_main_configuration_call_count == 0u && firmware_main_bit0029_read_count == 1u && firmware_main_bit0046_read_count == 1u);
    assert(firmware_memory[0xfaebu] == 1u);
}

