    assert_read_measurement_mode1_events(reset_events, sizeof(reset_events));

    clear_memory(0u);
    firmware_memory[0x88b7u] = 1u;
    firmware_memory[0xe5fbu] = 1u;
    PrepareReadMeasurementForAcquisitionMode1();
    assert_read_measurement_mode1_events(rebuild_events, sizeof(rebuild_events));

    clear_memory(0u);
