static void test_service_drive_initialization_state_transition(void)
{
    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x1009u] = 0xa5u;
    ServiceDriveInitializationStateTransition();
    assert_immediate_drive_initialization_restart();

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x0c35u] = 1u;
    ServiceDriveInitializationStateTransition();
    assert_drive_initialization_transition_prefix();
    assert(resume_coroutine1_count == 0u && write_count == 2u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x0c84u] = 0x08u;
    ServiceDriveInitializationStateTransition();
    assert_drive_initialization_transition_prefix();
    assert(resume_coroutine1_count == 0u && write_count == 2u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x130au] = 5u;
    ServiceDriveInitializationStateTransition();
    assert_drive_initialization_transition_prefix();
    assert(resume_coroutine1_count == 0u && write_count == 2u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x130au] = 5u;
    firmware_memory[0x11efu] = 0xc0u;
    ServiceDriveInitializationStateTransition();
    assert(firmware_memory[0x11efu] == 0x80u);
    assert_immediate_drive_initialization_restart();

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x1309u] = 1u;
    firmware_memory[0x11efu] = 0x40u;
    ServiceDriveInitializationStateTransition();
    assert(firmware_memory[0x11efu] == 0u);
    assert_immediate_drive_initialization_restart();

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x1308u] = 1u;
    firmware_memory[0x130au] = 12u;
    firmware_memory[0x1309u] = 1u;
    firmware_memory[0x11efu] = 0x40u;
    ServiceDriveInitializationStateTransition();
    assert(firmware_memory[0x11efu] == 0u && resume_coroutine1_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x130au] = 0x12u;
    firmware_memory[0x0faeu] = 1u;
    ServiceDriveInitializationStateTransition();
    assert(firmware_memory[0x18032u] == 0x80u && firmware_memory[0x18033u] == 0u && firmware_memory[0x18035u] == 0u && resume_coroutine1_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x1300u] = 9u;
    ServiceDriveInitializationStateTransition();
    assert(resume_coroutine1_count == 0u);
    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x1300u] = 10u;
    ServiceDriveInitializationStateTransition();
    assert(resume_coroutine1_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x0c9eu] = 1u;
    firmware_memory[0x0c89u] = 1u;
    firmware_memory[0x0c8bu] = 1u;
    ServiceDriveInitializationStateTransition();
    assert(firmware_memory[0xfc48u] == 1u && firmware_memory[0xfc49u] == 2u && firmware_memory[0x2ba5b0u] == 1u && resume_coroutine1_count == 0u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x0c9eu] = 3u;
    firmware_memory[0x0c8bu] = 1u;
    ServiceDriveInitializationStateTransition();
    assert(firmware_memory[0xfc48u] == 1u && firmware_memory[0xfc49u] == 3u && firmware_memory[0x2ba5b0u] == 0u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x0c9eu] = 2u;
    firmware_memory[0x0c89u] = 3u;
    firmware_memory[0x0c8au] = 0x12u;
    ServiceDriveInitializationStateTransition();
    assert(firmware_memory[0xfc48u] == 1u && firmware_memory[0xfc49u] == 0u && firmware_memory[0x2ba5b0u] == 1u && firmware_memory[0x0c8au] == 0x92u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x0c9eu] = 2u;
    firmware_memory[0x0c89u] = 1u;
    firmware_memory[0x0c8au] = 0x12u;
    ServiceDriveInitializationStateTransition();
    assert(firmware_memory[0xfc48u] == 1u && firmware_memory[0xfc49u] == 2u && firmware_memory[0x2ba5b0u] == 1u && firmware_memory[0x0c8au] == 0x12u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x0c9eu] = 2u;
    firmware_memory[0x0c8au] = 0x12u;
    ServiceDriveInitializationStateTransition();
    assert(firmware_memory[0xfc48u] == 1u && firmware_memory[0xfc49u] == 1u && firmware_memory[0x2ba5b0u] == 0u && firmware_memory[0x0c8au] == 0x92u);

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x0c9eu] = 1u;
    ServiceDriveInitializationStateTransition();
    assert_immediate_drive_initialization_restart();

    clear_memory(0u);
    firmware_memory[0x1302u] = 0xffu;
    firmware_memory[0x1301u] = 0xffu;
    firmware_memory[0x0c9eu] = 4u;
    ServiceDriveInitializationStateTransition();
    assert_immediate_drive_initialization_restart();
}

static void run_indexed_state04_coroutine_until_idle(void)
{
    raw_read_idle_escape_after = 1u;
    if(setjmp(raw_read_idle_escape) == 0)
    {
        RunIndexedState04MediaReadCoroutine0();
        assert(0);
    }
    raw_read_idle_escape_after = 0u;
}

