    assert(media_read_control_initial_read_speed == 7u && media_read_control_initial_write_speed == 9u && media_read_control_initial_state1591 == 0u && firmware_memory[0x0e46u] == 7u
           && firmware_memory[0x0e47u] == 9u && firmware_memory[0x1588u] == 0xb0u && firmware_memory[0x0c87u] == 0xbfu);
    assert(memcmp(&firmware_memory[0xfad3u], &firmware_memory[0xe4f2u], 8u) == 0);

    clear_memory(0u);
    firmware_memory[0x0c37u] = 12u;
    firmware_memory[0x0c38u] = 6u;
    firmware_memory[0x1591u] = 0xa5u;
    firmware_memory[0x1588u] = 0x04u;
    firmware_memory[0x1584u] = 0xa0u;
    firmware_memory[0x0c85u] = 1u;
    firmware_memory[0xfaefu] = 0x80u;
