    assert(media_read_control_event_count == sizeof(reset_events) && memcmp(media_read_coroutine_events, reset_events, sizeof(reset_events)) == 0);
    assert(media_read_control_initial_read_speed == 8u && media_read_control_initial_write_speed == 6u && media_read_control_initial_state1591 == 0xa5u && firmware_memory[0x0e46u] == 12u
           && firmware_memory[0x0e47u] == 6u && firmware_memory[0x0c85u] == 0x83u && firmware_memory[0xfaefu] == 0x82u && firmware_memory[0x1584u] == 0xa1u && firmware_memory[0x1588u] == 0x10u);

