    assert(media_read_control_initial_read_speed == 4u && media_read_control_initial_write_speed == 4u && firmware_memory[0x0e46u] == 12u && firmware_memory[0x0e47u] == 6u
           && firmware_memory[0x0c83u] == 0x10u && firmware_memory[0x0c85u] == 3u && firmware_memory[0x0c2au] == 7u);
