static void test_handle_request_sense_command(void)
{
    static const u8 invalid_events[2] = { 1u, 2u };
    static const u8 pending_events[2] = { 1u, 5u };
    static const u8 status_events[3] = { 1u, 4u, 5u };
    static const u8 set_events[3] = { 1u, 3u, 5u };
    static const u8 clear_events[3] = { 1u, 5u, 6u };

    clear_memory(0u);
    request_sense_validate_result = 0u;
    HandleRequestSenseCommand();
    assert(request_sense_event_count == 2u && memcmp(request_sense_events, invalid_events, 2u) == 0 && read_count == 0u);

    clear_memory(0u);
    firmware_memory[0x0b1au] = 3u;
    firmware_memory[0x0b0eu] = 0xffu;
    HandleRequestSenseCommand();
    assert(request_sense_event_count == 2u && memcmp(request_sense_events, pending_events, 2u) == 0 && request_sense_transfer_source == 0x000b18ul && request_sense_transfer_count == 18ul
           && read_count == 2u && read_trace[0] == 0x0b1aul && read_trace[1] == 0x0b0eul);

    clear_memory(0u);
    firmware_memory[0x0faeu] = 7u;
    firmware_memory[0x0b0eu] = 8u;
    HandleRequestSenseCommand();
    assert(request_sense_event_count == 3u && memcmp(request_sense_events, status_events, 3u) == 0 && request_sense_status_code == 7u && request_sense_transfer_count == 8ul && read_count == 6u
           && read_trace[1] == 0x0faeul && read_trace[2] == 0x0faeul);

    clear_memory(0u);
    firmware_memory[0x0b0eu] = 18u;
    HandleRequestSenseCommand();
    assert(request_sense_event_count == 3u && memcmp(request_sense_events, set_events, 3u) == 0 && request_sense_key == 2u && request_sense_asc_ascq == 0x0401u);

    clear_memory(0u);
    firmware_memory[0x0c85u] = 3u;
    firmware_memory[0x0c84u] = 8u;
    HandleRequestSenseCommand();
    assert(request_sense_key == 2u && request_sense_asc_ascq == 0x0408u && request_sense_event_count == 3u);

    clear_memory(0u);
    firmware_memory[0x0c85u] = 3u;
    firmware_memory[0x0c84u] = 8u;
    firmware_memory[0x0c87u] = 0x20u;
    HandleRequestSenseCommand();
    assert(request_sense_key == 2u && request_sense_asc_ascq == 0x0404u && request_sense_event_count == 3u);

    clear_memory(0u);
    firmware_memory[0x0c85u] = 2u;
    firmware_memory[0x0c9eu] = 2u;
    firmware_memory[0x0c89u] = 2u;
    HandleRequestSenseCommand();
    assert(request_sense_key == 0u && request_sense_asc_ascq == 0x0404u && request_sense_event_count == 3u);

    clear_memory(0u);
    firmware_memory[0x0b1au] = 1u;
    firmware_memory[0x0b0eu] = 6u;
    request_sense_transfer_result = 5u;
    HandleRequestSenseCommand();
    assert(request_sense_event_count == 3u && memcmp(request_sense_events, clear_events, 3u) == 0 && request_sense_transfer_count == 6ul);
}

static void assert_write_pipeline_q_packet(s32 target, u8 expected_state, u8 expected_index, u8 relative_minute, u8 relative_second, u8 relative_frame, u8 absolute_minute, u8 absolute_second,
    u8 absolute_frame)
{
    static const fw_addr_t expected_writes[11] = { 0x127cul, 0x1274ul, 0x1272ul, 0x1273ul, 0x1275ul, 0x1276ul, 0x1277ul, 0x1278ul, 0x1279ul, 0x127aul, 0x127bul };
    unsigned index;

    clear_memory(0xa5u);
    set_memory_big_endian_u32(0x1598u, (u32)target);
    read_count = 0u;
    write_count = 0u;
    BuildWritePipelineQPacketForTargetAddress();
    assert(firmware_memory[0x127cu] == expected_state && firmware_memory[0x1272u] == 0x71u && firmware_memory[0x1273u] == 1u && firmware_memory[0x1274u] == expected_index
           && firmware_memory[0x1275u] == relative_minute && firmware_memory[0x1276u] == relative_second && firmware_memory[0x1277u] == relative_frame && firmware_memory[0x1278u] == 0u
           && firmware_memory[0x1279u] == absolute_minute && firmware_memory[0x127au] == absolute_second && firmware_memory[0x127bu] == absolute_frame);
    assert(read_count == 4u && write_count == 11u);
    for(index = 0u; index != 4u; ++index)
        assert(read_trace[index] == 0x1598ul + index);
    for(index = 0u; index != 11u; ++index)
        assert(write_trace[index] == expected_writes[index]);
}

static void test_build_write_pipeline_q_packet_for_target_address(void)
{
    assert_write_pipeline_q_packet(149l, 1u, 0u, 0x00u, 0x00u, 0x04u, 0x00u, 0x01u, 0x74u);
    assert_write_pipeline_q_packet(150l, 0u, 1u, 0x00u, 0x00u, 0x00u, 0x00u, 0x02u, 0x00u);
    assert_write_pipeline_q_packet(-1l, 1u, 0u, 0x00u, 0x00u, 0x04u, 0x99u, 0x59u, 0x74u);
}

