static void test_reset_controller_hardware_registers(void)
{
    static const fw_addr_t expected_writes[24] = { 0x0fcaul, 0x18002ul, 0x1804bul, 0x18005ul, 0x18006ul, 0x1800eul, 0x18005ul, 0x18006ul, 0x18007ul, 0x1800eul, 0x131cul, 0x18080ul, 0x180bcul,
        0x180bbul, 0x180baul, 0x180b9ul, 0x180bdul, 0x0fcaul, 0x18002ul, 0x1806aul, 0x0fadul, 0x18003ul, 0x1802dul, 0x1802bul };
    static const u8 expected_values[24] = { 0xffu, 0xffu, 0x2au, 0u, 0u, 0x08u, 0x82u, 0x80u, 1u, 0x88u, 0u, 0u, 0u, 0u, 0u, 0u, 1u, 0xe7u, 0xe7u, 0u, 0x80u, 0x80u, 0x7fu, 0x80u };
    unsigned index;

    clear_memory(0u);
    firmware_memory[0x0fcau] = 0xf7u;
    firmware_memory[0x0fadu] = 0xa5u;
    sfr_memory[0xa8u] = 0x81u;
    sfr_memory[0xa9u] = 0x20u;
    bit_000e = 1u;
    ResetControllerHardwareRegisters();
    assert(write_count == 24u && read_count == 4u);
    for(index = 0u; index != 24u; ++index)
    {
        assert(write_trace[index] == expected_writes[index]);
        assert(write_values[index] == expected_values[index]);
    }
    assert(global_interrupt_disable_call_count == 1u && firmware_interrupt_enable_call_count == 1u && interrupt_enable_seen_write_count == 19u && sfr_memory[0xa8u] == 0xc1u
           && sfr_memory[0xa9u] == 0x24u && hardware_reset_register01_call_count == 1u && hardware_reset_register01_value == 1u);

    clear_memory(0xa5u);
    firmware_memory[0x1302u] = 0x08u;
    firmware_memory[0x0fcau] = 0x18u;
    bit_000e = 0u;
    ResetControllerHardwareRegisters();
    assert(write_count == 22u && read_count == 3u && firmware_memory[0x131cu] == 0xa5u && firmware_memory[0x18080u] == 0xa5u && firmware_memory[0x0fadu] == 0u && firmware_memory[0x18003u] == 0u
           && firmware_memory[0x0fcau] == 0u && firmware_memory[0x18002u] == 0u);
    for(index = 0u; index != write_count; ++index)
        assert(write_trace[index] != 0x131cul && write_trace[index] != 0x18080ul);
}

