static void test_isrc_available_for_current_track(void)
{
    clear_memory(0);
    firmware_memory[0x0c44] = 0u;
    firmware_memory[0x0c61] = 0x80u;
    assert(IsIsrcAvailableForCurrentTrack() == 1u);
    firmware_memory[0x0c61] = 0u;
    assert(IsIsrcAvailableForCurrentTrack() == 0u);
    firmware_memory[0x0c44] = 3u;
    firmware_memory[0x0c61] = 0x80u;
    assert(IsIsrcAvailableForCurrentTrack() == 0u);

    clear_memory(0);
    firmware_memory[0x0c44] = 2u;
    set_memory_big_endian_u16(0x14a3u, 1u);
    set_memory_big_endian_u16(0x14b0u, 0u);
    set_memory_big_endian_u16(0xb4bbu, 4u);
    firmware_memory[0x14a8] = 5u;
    firmware_memory[0xb4c6] = 5u;
    firmware_memory[0xb4c5] = 3u;
    assert(IsIsrcAvailableForCurrentTrack() == 1u);
    assert(((u16)firmware_memory[0x14b0] << 8 | firmware_memory[0x14b1]) == 1u);

    clear_memory(0);
    firmware_memory[0x0c44] = 2u;
    set_memory_big_endian_u16(0x14a3u, 1u);
    set_memory_big_endian_u16(0x14b0u, 0u);
    set_memory_big_endian_u16(0xb4bbu, 4u);
    firmware_memory[0x14a8] = 5u;
    firmware_memory[0xb4c6] = 4u;
    firmware_memory[0xb4cd] = 3u;
    firmware_memory[0xb4ce] = 5u;
    assert(IsIsrcAvailableForCurrentTrack() == 1u);
    assert(((u16)firmware_memory[0x14b0] << 8 | firmware_memory[0x14b1]) == 2u);

    firmware_memory[0x14a8] = 2u;
    set_memory_big_endian_u16(0x14b0u, 1u);
    assert(IsIsrcAvailableForCurrentTrack() == 0u);
    assert(((u16)firmware_memory[0x14b0] << 8 | firmware_memory[0x14b1]) == 1u);
}

static void test_media_catalog_number_character_load(void)
{
    unsigned index;

    clear_memory(0xccu);
    firmware_memory[0x0c44] = 0u;
    for(index = 0u; index < 13u; index++)
        firmware_memory[0x0c51u + index] = (u8)(0x30u + index);
    LoadMediaCatalogNumberCharacters();
    assert(read_count == 14u && read_trace[0] == 0x0c44ul);
    assert(write_count == 26u && write_trace[0] == 0x141aul && write_values[0] == 0u && write_trace[12] == 0x1426ul && write_values[12] == 0u && write_trace[13] == 0x141aul);
    for(index = 0u; index < 13u; index++)
        assert(firmware_memory[0x141au + index] == (u8)(0x30u + index));
    assert(firmware_memory[0x1427] == 0xccu);

    clear_memory(0xccu);
    firmware_memory[0x0c44] = 2u;
    for(index = 0u; index < 16u; index++)
        firmware_memory[0xb4bdu + index] = (u8)(0x80u + index);
    LoadMediaCatalogNumberCharacters();
    assert(firmware_memory[0x141a] == 0x80u);
    for(index = 1u; index < 7u; index++)
        assert(firmware_memory[0x141au + index] == (u8)(0x81u + index));
    assert(firmware_memory[0x1421] == 0x88u);
    for(index = 8u; index < 14u; index++)
        assert(firmware_memory[0x141au + index] == (u8)(0x82u + index));

    clear_memory(0xccu);
    firmware_memory[0x0c44] = 3u;
    LoadMediaCatalogNumberCharacters();
    assert(read_count == 1u && read_trace[0] == 0x0c44ul);
    assert(write_count == 13u && write_trace[0] == 0x141aul && write_trace[12] == 0x1426ul);
    for(index = 0u; index < 13u; index++)
        assert(firmware_memory[0x141au + index] == 0u);
    assert(firmware_memory[0x1427] == 0xccu);

    clear_memory(0xccu);
    firmware_memory[0x0c44] = 3u;
    LoadMediaCatalogNumberCharactersFromBIndex(7u);
    assert(read_count == 1u && read_trace[0] == 0x0c44ul);
    assert(write_count == 6u && write_trace[0] == 0x1421ul && write_trace[5] == 0x1426ul);
    for(index = 0u; index < 7u; index++)
        assert(firmware_memory[0x141au + index] == 0xccu);
    for(index = 7u; index < 13u; index++)
        assert(firmware_memory[0x141au + index] == 0u);
    assert(firmware_memory[0x1427] == 0xccu);
}

static void test_media_catalog_number_q_packet(void)
{
    unsigned index;

    clear_memory(0xccu);
    set_memory_big_endian_u32(0x1598u, 101u);
    firmware_memory[0x14cd] = 2u;
    assert(BuildMediaCatalogNumberQPacket() == 0u);
    assert(write_count == 0u);

    clear_memory(0xccu);
    set_memory_big_endian_u32(0x1598u, 1u);
    firmware_memory[0x14cd] = 1u;
    firmware_memory[0x1275] = 0u;
    firmware_memory[0x1276] = 0u;
    firmware_memory[0x1277] = 4u;
    firmware_memory[0x1274] = 1u;
    assert(BuildMediaCatalogNumberQPacket() == 0u);
    assert(firmware_memory[0x14cd] == 6u && write_count == 1u && write_trace[0] == 0x14cdul && write_values[0] == 6u);

    clear_memory(0xccu);
    set_memory_big_endian_u32(0x1598u, 0u);
    firmware_memory[0x14cd] = 0u;
    firmware_memory[0x1272] = 0xa5u;
    firmware_memory[0x1275] = 0u;
    firmware_memory[0x1276] = 0u;
    firmware_memory[0x1277] = 5u;
    firmware_memory[0x0c44] = 2u;
    for(index = 0u; index < 14u; index++)
        firmware_memory[0x141au + index] = (u8)(0x30u + index);
    assert(BuildMediaCatalogNumberQPacket() == 1u);
    assert(firmware_memory[0x14cd] == 0x21u && firmware_memory[0x1272] == 0xa2u);
    for(index = 0u; index < 7u; index++)
        assert(firmware_memory[0x1273u + index] == (u8)((index * 0x22u) + 1u));
    assert(firmware_memory[0x127a] == 0u && write_count == 10u && write_trace[0] == 0x14cdul && write_trace[1] == 0x1272ul && write_trace[2] == 0x1273ul && write_trace[8] == 0x1279ul
           && write_trace[9] == 0x127aul);

    clear_memory(0xccu);
    set_memory_big_endian_u32(0x1598u, 0xffffff9cul);
    firmware_memory[0x14cd] = 0u;
    firmware_memory[0x1275] = 0u;
    firmware_memory[0x1276] = 0u;
    firmware_memory[0x1277] = 5u;
    firmware_memory[0x0c44] = 0u;
    for(index = 0u; index < 14u; index++)
        firmware_memory[0x0c52u + index] = (u8)(0x41u + index);
    assert(BuildMediaCatalogNumberQPacket() == 1u);
    assert(firmware_memory[0x1273] == 0x12u && firmware_memory[0x1279] == 0xdeu);

    clear_memory(0xccu);
    set_memory_big_endian_u32(0x1598u, 0xfffffffful);
    firmware_memory[0x14cd] = 0xffu;
    assert(BuildMediaCatalogNumberQPacket() == 0u);
    assert(write_count == 0u);
}

static void test_isrc_q_packet(void)
{
    static const u8 isrc_characters[13] = { 0x41u, 0x42u, 0x43u, 0x44u, 0x45u, 0x31u, 0x32u, 0x33u, 0x34u, 0x35u, 0x36u, 0x37u, 0x38u };
    static const u8 expected_packet[8] = { 0x45u, 0x24u, 0xd4u, 0x54u, 0x23u, 0x45u, 0x67u, 0x80u };
    unsigned index;

    clear_memory(0xccu);
    set_memory_big_endian_u32(0x1598u, 101u);
    firmware_memory[0x14ce] = 2u;
    assert(BuildIsrcQPacket() == 0u);
    assert(write_count == 0u);

    clear_memory(0xccu);
    set_memory_big_endian_u32(0x1598u, 1u);
    firmware_memory[0x14ce] = 1u;
    firmware_memory[0x1275] = 0u;
    firmware_memory[0x1276] = 0u;
    firmware_memory[0x1277] = 4u;
    firmware_memory[0x1274] = 1u;
    assert(BuildIsrcQPacket() == 0u);
    assert(firmware_memory[0x14ce] == 6u && write_count == 1u && write_trace[0] == 0x14ceul && write_values[0] == 6u);

    clear_memory(0);
    set_memory_big_endian_u32(0x1598u, 0u);
    firmware_memory[0x14ce] = 0u;
    firmware_memory[0x1272] = 0xa5u;
    firmware_memory[0x1275] = 0u;
    firmware_memory[0x1276] = 0u;
    firmware_memory[0x1277] = 5u;
    firmware_memory[0x0c44] = 2u;
    for(index = 0u; index < 13u; index++)
        firmware_memory[0x140eu + index] = isrc_characters[index];
    assert(BuildIsrcQPacket() == 1u);
    assert(firmware_memory[0x14ce] == 0x42u && firmware_memory[0x1272] == 0xa3u);
    for(index = 0u; index < 5u; index++)
        assert(firmware_memory[0x140eu + index] == (u8)(0x11u + index));
    for(index = 5u; index < 13u; index++)
        assert(firmware_memory[0x140eu + index] == (u8)(index - 4u));
    for(index = 0u; index < 8u; index++)
        assert(firmware_memory[0x1273u + index] == expected_packet[index]);
    assert(write_count == 30u && write_trace[0] == 0x14ceul && write_trace[1] == 0x1272ul && write_trace[2] == 0x140eul && write_trace[29] == 0x127aul);

    clear_memory(0);
    set_memory_big_endian_u32(0x1598u, 0u);
    firmware_memory[0x14ce] = 0u;
    firmware_memory[0x1275] = 0u;
    firmware_memory[0x1276] = 0u;
    firmware_memory[0x1277] = 5u;
    firmware_memory[0x0c44] = 2u;
    firmware_memory[0x140e] = 0x41u;
    firmware_memory[0x140f] = 0x7au;
    firmware_memory[0x1410] = 0x5bu;
    firmware_memory[0x1411] = 0x7bu;
    firmware_memory[0x1412] = 0x80u;
    assert(BuildIsrcQPacket() == 1u);
    assert(firmware_memory[0x140e] == 0x11u && firmware_memory[0x140f] == 0x2au && firmware_memory[0x1410] == 0x5bu && firmware_memory[0x1411] == 0u && firmware_memory[0x1412] == 0x50u);

    clear_memory(0);
    set_memory_big_endian_u32(0x1598u, 0xffffff9cul);
    firmware_memory[0x14ce] = 0u;
    firmware_memory[0x1275] = 0u;
    firmware_memory[0x1276] = 0u;
    firmware_memory[0x1277] = 5u;
    firmware_memory[0x0c44] = 0u;
    for(index = 0u; index < 13u; index++)
        firmware_memory[0x0c62u + index] = isrc_characters[index];
    assert(BuildIsrcQPacket() == 1u);
    assert(firmware_memory[0x0c62] == 0x11u && firmware_memory[0x1273] == 0x45u);

    clear_memory(0);
    set_memory_big_endian_u32(0x1598u, 0xfffffffful);
    firmware_memory[0x14ce] = 0xffu;
    assert(BuildIsrcQPacket() == 0u);
    assert(write_count == 0u);
}

static void test_isrc_character_load(void)
{
    unsigned index;

    clear_memory(0xccu);
    firmware_memory[0x0c44] = 2u;
    firmware_memory[0x14a8] = 0u;
    LoadIsrcCharactersForCurrentTrack();
    for(index = 0u; index < 12u; index++)
        assert(firmware_memory[0x140eu + index] == 0xccu);

    firmware_memory[0x0c44] = 1u;
    LoadIsrcCharactersForCurrentTrack();
    for(index = 0u; index < 12u; index++)
        assert(firmware_memory[0x140eu + index] == 0u);

    clear_memory(0u);
    firmware_memory[0x0c44] = 2u;
    firmware_memory[0x14a8] = 1u;
    set_memory_big_endian_u16(0x14a3u, 1u);
    for(index = 0u; index < 6u; index++)
    {
        firmware_memory[0xb4c7u + index] = (u8)(0x40u + index);
        firmware_memory[0xb4cfu + index] = (u8)(0x50u + index);
    }
    LoadIsrcCharactersForCurrentTrack();
    for(index = 0u; index < 6u; index++)
    {
        assert(firmware_memory[0x140eu + index] == (u8)(0x40u + index));
        assert(firmware_memory[0x1414u + index] == (u8)(0x50u + index));
    }
}

