static void test_working_track_status_code_map(void)
{
    static const u8 flags[] = { 0u, 1u, 2u, 0xffu };
    static const u8 status_class[] = { 0u, 1u, 2u, 8u, 13u, 0xffu };
    static const u8 detail[] = { 0u, 1u, 0x40u, 0xffu };
    unsigned flag_index;
    unsigned class_index;
    unsigned detail_index;

    for(flag_index = 0u; flag_index < sizeof(flags); flag_index++)
    {
        for(class_index = 0u; class_index < sizeof(status_class); class_index++)
        {
            for(detail_index = 0u; detail_index < sizeof(detail); detail_index++)
            {
                clear_memory(0);
                firmware_memory[0xdd31] = flags[flag_index];
                firmware_memory[0xdd32] = status_class[class_index];
                firmware_memory[0xdd33] = detail[detail_index];
                assert(MapWorkingTrackFieldsToStatusCode() == MapThreeFieldStatusCode(flags[flag_index], status_class[class_index], detail[detail_index]));
            }
        }
    }
}

