static void test_reset_type2_controller_record_pipeline_state(void)
{
    static const fw_addr_t zero_dwords[] = { 0x000c96ul, 0x2ba59ful, 0x2ba5abul, 0x2ba5a7ul, 0x2ba52eul, 0x2ba532ul, 0x2ba5a3ul, 0x000ce5ul, 0x000ce1ul };
    unsigned index;

    clear_memory(0xa5u);
    set_memory_big_endian_u32(0x155au, 0x001a8000ul);
    firmware_memory[0x0c8bu] = 0xffu;
    firmware_memory[0x0c8au] = 0xffu;
    firmware_memory[0x0c89u] = 0xffu;
    firmware_memory[0xe750u] = 0u;
    ResetType2ControllerRecordPipelineState();

    assert(type2_reset_geometry_call_count == 1u && type2_reset_geometry_seen_slots_clear == 1u);
    assert(buffer_fill_chunk_call_count == 1u && buffer_fill_chunk_addresses[0] == 0x001a8000ul && buffer_fill_chunk_counts[0] == 0x8000u && buffer_fill_chunk_values[0] == 0u);
    for(index = 0u; index < 8u; ++index)
    {
        unsigned byte_index;

        for(byte_index = 0u; byte_index < 5u; ++byte_index)
        {
            assert(firmware_memory[0xfb03u + index * 5u + byte_index] == 0u);
            assert(firmware_memory[0xfb2bu + index * 5u + byte_index] == 0u);
        }
    }
    for(index = 0u; index < sizeof(zero_dwords) / sizeof(zero_dwords[0]); ++index)
        assert(get_memory_big_endian_u32(zero_dwords[index]) == 0ul);
    assert(firmware_memory[0x0c9fu] == 0u && firmware_memory[0x0c9eu] == 0u);
    assert(firmware_memory[0x0ca6u] == 0u && firmware_memory[0x0cc9u] == 0u);
    assert(firmware_memory[0x0ccbu] == 0u && firmware_memory[0x0cd4u] == 0xa4u && firmware_memory[0x0cd5u] == 0u && firmware_memory[0x0cd6u] == 0u && firmware_memory[0x0cdfu] == 0xa4u
           && firmware_memory[0x0ce0u] == 0u);
    assert(get_memory_big_endian_u32(0x2bae33ul) == 0x000006a9ul && get_memory_big_endian_u32(0x2baf2ful) == 0x00056cb9ul && get_memory_big_endian_u32(0x2bae2ful) == 145ul);
    assert(firmware_memory[0x0c8bu] == 0xf8u && firmware_memory[0x0c8au] == 0xfeu && firmware_memory[0x0c89u] == 0x77u && firmware_memory[0x122cu] == 10u && firmware_memory[0x122bu] == 20u
           && firmware_memory[0x2ba5d8u] == 0u && firmware_memory[0x15d7u] == 0u);

    clear_memory(0xa5u);
    set_memory_big_endian_u32(0x155au, 0x001b0000ul);
    firmware_memory[0xe750u] = 1u;
    ResetType2ControllerRecordPipelineState();
    assert(type2_reset_geometry_call_count == 1u && buffer_fill_chunk_call_count == 0u && firmware_memory[0x122bu] == 60u);
}

static void reset_write_pipeline_record_prepare_observers(void)
{
    memset(write_prepare_stage_results, 1, sizeof(write_prepare_stage_results));
    memset(write_prepare_stage_events, 0, sizeof(write_prepare_stage_events));
    memset(write_prepare_stage_arguments, 0, sizeof(write_prepare_stage_arguments));
    write_prepare_stage_event_count = 0u;
}

static void test_prepare_write_pipeline_controller_record_state(void)
{
    static const u8 failure_stages[] = { 3u, 4u, 5u, 6u, 7u, 8u, 10u, 11u };
    unsigned failure_index;
    unsigned index;

    clear_memory(0u);
    reset_write_pipeline_record_prepare_observers();
    firmware_memory[0x0c89u] = 0xffu;
    firmware_memory[0x0c8bu] = 0xffu;
    set_memory_big_endian_u32_far(0x2ba589ul, 0x00000200ul);
    set_memory_big_endian_u32_far(0x2ba59ful, 0x00000100ul);
    read_count = write_count = 0u;
    assert(PrepareWritePipelineControllerRecordState() == 1u);
    assert(write_prepare_stage_event_count == 13u);
    for(index = 0u; index != 13u; ++index)
        assert(write_prepare_stage_events[index] == index);
    assert(write_prepare_stage_arguments[0] == 3u && write_prepare_stage_arguments[2] == 0u && write_prepare_stage_arguments[3] == 1u && write_prepare_stage_arguments[5] == 1u
           && write_prepare_stage_arguments[9] == 0u);
    assert(read_count == 10u && read_trace[0] == 0x000c89ul && read_trace[1] == 0x2ba58bul && read_trace[2] == 0x2ba58cul && read_trace[3] == 0x2ba589ul && read_trace[4] == 0x2ba58aul
           && read_trace[5] == 0x2ba5a1ul && read_trace[6] == 0x2ba5a2ul && read_trace[7] == 0x2ba59ful && read_trace[8] == 0x2ba5a0ul && read_trace[9] == 0x000c8bul);
    assert(write_count == 5u && write_trace[0] == 0x2ba5b0ul && write_values[0] == 0u && write_trace[1] == 0x000c89ul && write_values[1] == 0x7fu && write_trace[2] == 0x000c9eul
           && write_values[2] == 1u && write_trace[3] == 0x000c8bul && write_values[3] == 0xfeu && write_trace[4] == 0x2ba5aful && write_values[4] == 1u);

    clear_memory(0u);
    reset_write_pipeline_record_prepare_observers();
    firmware_memory[0x0c89u] = 0x80u;
    firmware_memory[0x0c8bu] = 1u;
    set_memory_big_endian_u32_far(0x2ba589ul, 0x12345678ul);
    set_memory_big_endian_u32_far(0x2ba59ful, 0x12345678ul);
    read_count = write_count = 0u;
    assert(PrepareWritePipelineControllerRecordState() == 1u);
    assert(write_count == 6u && write_trace[2] == 0x001587ul && write_values[2] == 1u && write_trace[3] == 0x000c9eul && write_values[3] == 3u && firmware_memory[0x1587u] == 1u
           && firmware_memory[0x0c9eu] == 3u);

    for(failure_index = 0u; failure_index != sizeof(failure_stages) / sizeof(failure_stages[0]); ++failure_index)
    {
        u8 failure_stage = failure_stages[failure_index];

        clear_memory(0u);
        reset_write_pipeline_record_prepare_observers();
        firmware_memory[0x0c89u] = 0xffu;
        firmware_memory[0x0c8bu] = 0xffu;
        set_memory_big_endian_u32_far(0x2ba589ul, 2ul);
        set_memory_big_endian_u32_far(0x2ba59ful, 1ul);
        read_count = write_count = 0u;
        write_prepare_stage_results[failure_stage] = 0u;
        assert(PrepareWritePipelineControllerRecordState() == 0u);
        assert(write_prepare_stage_event_count == (unsigned)failure_stage + 1u);
        for(index = 0u; index != write_prepare_stage_event_count; ++index)
            assert(write_prepare_stage_events[index] == index);
        assert(read_count == 9u && write_count == 3u && firmware_memory[0x0c8bu] == 0xffu && firmware_memory[0x2ba5afu] == 0u);
    }
}

