    set_memory_big_endian_u32(0x155au, 0x00123456ul);
    vendor_ec_build_result = 100u;
    vendor_ec_data_in_result = 5u;
    HandleScsiOpcodeEC();
    assert(vendor_ec_build_call_count == 1u && vendor_ec_build_include_all == 0u && vendor_ec_build_alternate == 0u);
    assert(vendor_ec_copy_call_count == 1u && vendor_ec_copy_source == 0x0b2aul && vendor_ec_copy_offset == 0x00123456ul && vendor_ec_copy_count == 100u);
    assert(vendor_ec_data_in_call_count == 1u && vendor_ec_data_in_length == 50u && firmware_memory[0x0b18u] == 0x70u && firmware_memory[0x0b1au] == 0u);

