static void test_map_negative_lba_through_thirty_two_plus_seven_layout(void)
{
    clear_memory(0u);
    bit_000c = 1u;
    set_memory_big_endian_u32(0x0f0cu, 0xa5a5a5a5ul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(-200l) == -50l && bit_000c == 0u && get_memory_big_endian_u32(0x0f0cu) == 0xa5a5a5a5ul);

    clear_memory(0u);
    bit_000b = 1u;
    set_memory_big_endian_u32(0x0f0cu, 0xa5a5a5a5ul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(0l) == 0l && bit_000c == 0u && get_memory_big_endian_u32(0x0f0cu) == 0xa5a5a5a5ul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(149l) == 149l && bit_000c == 0u && get_memory_big_endian_u32(0x0f0cu) == 0xa5a5a5a5ul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(150l) == 298l && bit_000c == 1u && get_memory_big_endian_u32(0x0f0cu) == 0xfffffffeul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(-1l) == 147l && get_memory_big_endian_u32(0x0f0cu) == 0xfffffffeul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(-181l) == -33l && get_memory_big_endian_u32(0x0f0cu) == 0xfffffffeul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(-182l) == -34l && get_memory_big_endian_u32(0x0f0cu) == 0xfffffffeul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(-183l) == -42l && get_memory_big_endian_u32(0x0f0cu) == 0xfffffff7ul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(-214l) == -73l && get_memory_big_endian_u32(0x0f0cu) == 0xfffffff7ul);
    assert(MapNegativeLogicalBlockAddressThroughThirtyTwoPlusSevenLayout(-215l) == -81l && get_memory_big_endian_u32(0x0f0cu) == 0xfffffff0ul);
}

