    firmware_memory[0xfbecu] = 1u;
    ConfigureControllerOperatingCode4AndChannel3();
    assert(firmware_memory[0x1006u] == 0u && operating_code4_strobe_value == 0x80u && operating_code4_threshold_call_count == 0u && operating_code4_pulse_duration == 400u);

