static void test_execute_pending_raw_read_preparation_range(void)
{
    clear_memory(0u);
    assert(ExecutePendingRawReadPreparationRange(1u) == 1u && pending_range_event_count == 0u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1430u, 7u);
    firmware_memory[0x0c44u] = 2u;
    assert(ExecutePendingRawReadPreparationRange(1u) == 1u && pending_range_event_count == 0u);
    firmware_memory[0x0c44u] = 3u;
    assert(ExecutePendingRawReadPreparationRange(0u) == 1u && pending_range_event_count == 0u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1430u, 4u);
    pending_range_current_q_result = 2u;
    assert(ExecutePendingRawReadPreparationRange(1u) == 1u && pending_range_event_count == 1u && pending_range_events[0] == 1u && pending_range_current_q_count == 4l
           && pending_range_current_q_source == 5u);
    pending_range_current_q_result = 0u;
    assert(ExecutePendingRawReadPreparationRange(1u) == 0u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1430u, 0xfffffffful);
    assert(ExecutePendingRawReadPreparationRange(1u) == 1u && pending_range_current_q_count == -1l && pending_range_current_q_source == 5u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1430u, 5u);
    assert(ExecutePendingRawReadPreparationRange(1u) == 1u && pending_range_event_count == 2u && pending_range_events[0] == 2u && pending_range_events[1] == 1u && pending_range_prefix_start == 0u
           && pending_range_prefix_count == 5u && pending_range_current_q_count == 0l && pending_range_current_q_source == 5u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1430u, 8u);
    pending_range_prefix_result = 0u;
    assert(ExecutePendingRawReadPreparationRange(1u) == 0u && pending_range_event_count == 1u && pending_range_events[0] == 2u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1430u, 8u);
    pending_range_current_q_result = 0u;
    assert(ExecutePendingRawReadPreparationRange(1u) == 0u && pending_range_event_count == 2u && pending_range_events[0] == 2u && pending_range_events[1] == 1u && pending_range_current_q_count == 3l);

    clear_memory(0u);
    firmware_memory[0x0c44u] = 1u;
    set_memory_big_endian_u32(0x1430u, 9u);
    pending_range_q_updates_result = 2u;
    assert(ExecutePendingRawReadPreparationRange(0u) == 1u && pending_range_event_count == 1u && pending_range_events[0] == 3u && pending_range_q_updates_count == 9l
           && pending_range_q_updates_enabled == 1u);

    clear_memory(0u);
    set_memory_big_endian_u32(0x1430u, 9u);
    pending_range_q_updates_result = 0u;
    assert(ExecutePendingRawReadPreparationRange(2u) == 0u && pending_range_event_count == 1u && pending_range_events[0] == 3u && pending_range_q_updates_count == 9l
           && pending_range_q_updates_enabled == 1u);
}

