    firmware_memory[0x12c0u] = 0x0fu;
    firmware_memory[0x11efu] = 0x20u;
    bit_000e = 1u;
    assert(HandleIndexedState0C() == 1u && firmware_memory[0x11efu] == 0u && indexed_state0c_call_count == 1u && indexed_state0c_arguments[0] == 0u);

    clear_memory(0u);
