    firmware_memory[0x12c0u] = 0x10u;
    firmware_memory[0x11efu] = 0x60u;
    assert(HandleIndexedState0C() == 1u && firmware_memory[0x11efu] == 0x40u && indexed_state0c_call_count == 1u && indexed_state0c_arguments[0] == 0u);

    clear_memory(0u);
