static void test_select_drive_numeric_table0_interval_for_read_pipeline_target(void)
{
    u8 table_index;

    clear_memory(0);
    for(table_index = 0u; table_index <= 64u; table_index++)
        set_memory_big_endian_u32_far(0xf84490ul + (u32)table_index * 4ul, (u32)table_index * 100ul);

    set_memory_big_endian_u32(0x1598u, 0ul);
    assert(SelectDriveNumericTable0IntervalForReadPipelineTarget() == 0u);
    assert(get_memory_big_endian_u32(0x159cu) == 100ul);

    set_memory_big_endian_u32(0x1598u, 100ul);
    assert(SelectDriveNumericTable0IntervalForReadPipelineTarget() == 1u);
    assert(get_memory_big_endian_u32(0x159cu) == 200ul);

    set_memory_big_endian_u32(0x1598u, 1550ul);
    assert(SelectDriveNumericTable0IntervalForReadPipelineTarget() == 0u);
    assert(get_memory_big_endian_u32(0x159cu) == 1600ul);

    set_memory_big_endian_u32(0x1598u, 1650ul);
    assert(SelectDriveNumericTable0IntervalForReadPipelineTarget() == 0u);
    assert(get_memory_big_endian_u32(0x159cu) == 1700ul);

    set_memory_big_endian_u32(0x1598u, 3250ul);
    assert(SelectDriveNumericTable0IntervalForReadPipelineTarget() == 0u);
    assert(get_memory_big_endian_u32(0x159cu) == 3300ul);

    set_memory_big_endian_u32(0x1598u, 4850ul);
    assert(SelectDriveNumericTable0IntervalForReadPipelineTarget() == 0u);
    assert(get_memory_big_endian_u32(0x159cu) == 4900ul);

    set_memory_big_endian_u32(0x159cu, 0xdeadbeeful);
    set_memory_big_endian_u32(0x1598u, 6400ul);
    assert(SelectDriveNumericTable0IntervalForReadPipelineTarget() == 0u);
    assert(get_memory_big_endian_u32(0x159cu) == 0xdeadbeeful);

    set_memory_big_endian_u32_far(0xf84550ul, 0x80000000ul);
    set_memory_big_endian_u32_far(0xf84554ul, 0x80000100ul);
    set_memory_big_endian_u32(0x1598u, 0x80000050ul);
    assert(SelectDriveNumericTable0IntervalForReadPipelineTarget() == 0u);
    assert(get_memory_big_endian_u32(0x159cu) == 0x80000100ul);
}

