static void test_fun_ram_fdcbdf(void)
{
    u8 state;

    for(state = 0u; state < 4u; state++)
    {
        clear_memory(0xa5u);
        firmware_memory[0x0fae] = state;
        firmware_memory[0x0c84] = 0x80u;
        FUN_RAM_fdcbdf();
        if(state == 1u)
        {
            assert(read_count == 5u && read_trace[0] == 0x0faeul && read_trace[1] == 0x0faeul && read_trace[2] == 0x0faeul && read_trace[3] == 0x0fbaul && read_trace[4] == 0x0fbaul);
            assert(firmware_memory[0x0fba] == 0xa5u && ReadBigEndianU16(0x0500u) == 0x00f8u && ReadBigEndianU16(0x0502u) == 0x52ebu);
            assert(write_count == 10u && write_trace[0] == 0x0fbaul && write_trace[1] == 0x0fbaul && write_trace[2] == 0x0500ul && write_trace[9] == 0x1165ul);
        }
        else
        {
            assert(read_count == (state == 0u ? 2u : (state == 2u ? 3u : 4u)) && read_trace[0] == 0x0faeul && read_trace[read_count - 1u] == 0x0c84ul);
            assert(firmware_memory[0x0c84] == 0x82u && write_count == 1u && write_trace[0] == 0x0c84ul);
        }
    }
    clear_memory(0xa5u);
    firmware_memory[0x0fae] = 4u;
    firmware_memory[0x0fba] = 0xffu;
    FUN_RAM_fdcbdf();
    assert(read_count == 5u && read_trace[0] == 0x0faeul && read_trace[2] == 0x0faeul && read_trace[3] == 0x0fbaul && read_trace[4] == 0x0fbaul);
    assert(firmware_memory[0x0fba] == 0xe7u && ReadBigEndianU16(0x0502u) == 0x52ebu && write_count == 10u);
}

