static void test_validate_pma_start_before_atip_lead_in_for_write(void)
{
    static const u8 checked_track_types[] = { 0u, 1u, 6u };
    unsigned index;

    clear_memory(0);
    assert(ValidatePmaStartBeforeAtipLeadInForWrite() == 1u);

    clear_memory(0);
    firmware_memory[0xe74cu] = 1u;
    firmware_memory[0x0c44u] = 2u;
    assert(ValidatePmaStartBeforeAtipLeadInForWrite() == 1u);
    firmware_memory[0x0c44u] = 3u;
    assert(ValidatePmaStartBeforeAtipLeadInForWrite() == 1u);

    for(index = 0u; index < sizeof(checked_track_types); index++)
    {
        clear_memory(0);
        firmware_memory[0xe74cu] = 1u;
        firmware_memory[0x0c44u] = 0u;
        firmware_memory[0xdd34u] = checked_track_types[index];
        set_memory_big_endian_u32(0x1143u, 0xfffffffful);
        set_memory_big_endian_u32(0x114fu, 0x00000000ul);
        assert(ValidatePmaStartBeforeAtipLeadInForWrite() == 1u);

        set_memory_big_endian_u32(0x1143u, 0x00000000ul);
        set_memory_big_endian_u32(0x114fu, 0xfffffffful);
        assert(ValidatePmaStartBeforeAtipLeadInForWrite() == 0u);
        assert(firmware_memory[0x0b1au] == 3u && firmware_memory[0x0b24u] == 0x73u && firmware_memory[0x0b25u] == 0x05u);
    }

    clear_memory(0);
    firmware_memory[0xe74cu] = 1u;
    firmware_memory[0x0c44u] = 0xffu;
    firmware_memory[0xdd34u] = 2u;
    assert(ValidatePmaStartBeforeAtipLeadInForWrite() == 1u);
}

