static void test_prevent_allow_medium_removal_command(void)
{
    clear_memory(0);
    firmware_memory[0xff8d95u] = 1u;
    firmware_memory[0x000b0eu] = 0u;
    firmware_memory[0x000c35u] = 1u;
    firmware_memory[0x000c36u] = 1u;
    HandlePreventAllowMediumRemovalCommand();
    assert(firmware_memory[0x000c35u] == 0u && firmware_memory[0x000c36u] == 0u);
    assert(firmware_memory[0x000b1au] == 0u);

    clear_memory(0);
    firmware_memory[0xff8d95u] = 1u;
    firmware_memory[0x000b0eu] = 2u;
    HandlePreventAllowMediumRemovalCommand();
    assert(firmware_memory[0x000c35u] == 0u && firmware_memory[0x000c36u] == 1u);

    clear_memory(0);
    firmware_memory[0xff8d95u] = 1u;
    firmware_memory[0x000b0eu] = 1u;
    firmware_memory[0x000c85u] = 2u;
    firmware_memory[0x001588u] = 0xffu;
    HandlePreventAllowMediumRemovalCommand();
    assert(firmware_memory[0x000c35u] == 1u && firmware_memory[0x000c36u] == 0u);
    assert(firmware_memory[0x001588u] == 0xfbu && firmware_memory[0x000b1au] == 0u);

    clear_memory(0);
    firmware_memory[0xff8d95u] = 1u;
    firmware_memory[0x000b0eu] = 3u;
    firmware_memory[0x000c85u] = 2u;
    HandlePreventAllowMediumRemovalCommand();
    assert(firmware_memory[0x000c35u] == 1u && firmware_memory[0x000c36u] == 1u);

    clear_memory(0);
    firmware_memory[0xff8d95u] = 1u;
    firmware_memory[0x000b0eu] = 1u;
    HandlePreventAllowMediumRemovalCommand();
    assert(firmware_memory[0x000b1au] == 2u && firmware_memory[0x000b24u] == 4u && firmware_memory[0x000b25u] == 1u);

    clear_memory(0);
    firmware_memory[0xff8d95u] = 1u;
    firmware_memory[0x000b0eu] = 1u;
    firmware_memory[0x000faeu] = 3u;
    firmware_memory[0xf84457u] = 6u;
    firmware_memory[0xf8446eu] = 0x12u;
    firmware_memory[0xf8446fu] = 0x34u;
    HandlePreventAllowMediumRemovalCommand();
    assert(firmware_memory[0x000b1au] == 6u && firmware_memory[0x000b24u] == 0x12u && firmware_memory[0x000b25u] == 0x34u);

    clear_memory(0);
    firmware_memory[0xff8d95u] = 2u;
    firmware_memory[0xff8d97u] = 1u;
    firmware_memory[0x000b0bu] = 1u;
    HandlePreventAllowMediumRemovalCommand();
    assert(firmware_memory[0x000b1au] == 5u && firmware_memory[0x000b24u] == 0x24u && firmware_memory[0x000b25u] == 0u);
}

