static void test_mode_sense_page_image_selector(void)
{
    static const struct
    {
        u8 page_code;
        fw_addr_t images[3];
    } cases[] = {
        { 0x01u, { 0x00e623ul, 0xff8a16ul, 0xff8a0aul } },
        { 0x02u, { 0x00e62ful, 0xff8a42ul, 0xff8a32ul } },
        { 0x03u, { 0x2bc6eful, 0xff8a62ul, 0xff8a5aul } },
        { 0x05u, { 0x00e63ful, 0xff8ad2ul, 0xff8a9eul } },
        { 0x0au, { 0x00e687ul, 0xff8b52ul, 0xff8b4aul } },
        { 0x0bu, { 0x00e67bul, 0xff8b36ul, 0xff8b2aul } },
        { 0x0du, { 0x00e673ul, 0xff8b16ul, 0xff8b0eul } },
        { 0x0eu, { 0x00e68ful, 0xff8b7aul, 0xff8b6aul } },
        { 0x1au, { 0x00e69ful, 0xff8ba2ul, 0xff8b96ul } },
        { 0x1du, { 0xff8bb8ul, 0xff8bc2ul, 0xff8bb8ul } },
        { 0x2au, { 0x00e6abul, 0xff8c10ul, 0x00e6ebul } }
    };
    unsigned case_index;
    unsigned control;

    for(case_index = 0u; case_index < sizeof(cases) / sizeof(cases[0]); ++case_index)
    {
        for(control = 0u; control < 3u; ++control)
        {
            clear_memory(0);
            firmware_memory[0x0c43u] = 4u;
            assert(SelectModePageImageAddressForPageControl(cases[case_index].page_code, (u8)control) == cases[case_index].images[control]);
            if(cases[case_index].page_code == 0x2au && control == 2u)
            {
                assert(read_count == 1u && read_trace[0] == 0x0c43ul);
                assert(write_count == 2u && write_trace[0] == 0xe6f3ul && write_trace[1] == 0xe6f4ul);
                assert(firmware_memory[0xe6f3u] == 0x02u && firmware_memory[0xe6f4u] == 0xc2u);
            }
            else
            {
                assert(read_count == 0u && write_count == 0u);
            }
        }
        clear_memory(0);
        assert(SelectModePageImageAddressForPageControl(cases[case_index].page_code, 3u) == 0ul);
        assert(read_count == 0u && write_count == 0u);
    }
    clear_memory(0);
    assert(SelectModePageImageAddressForPageControl(0u, 0u) == 0ul);
    assert(SelectModePageImageAddressForPageControl(0xffu, 2u) == 0ul);
    assert(read_count == 0u && write_count == 0u);
}

static void test_mode_page1a_selection_state(void)
{
    clear_memory(0);
    firmware_memory[0x00e6a2u] = 0x03u;
    set_memory_big_endian_u32(0xe6a3u, 3ul);
    firmware_memory[0x00e6a7u] = 0xa1u;
    firmware_memory[0x00e6a8u] = 0xa2u;
    firmware_memory[0x00e6a9u] = 0xa3u;
    firmware_memory[0x00e6aau] = 0xa4u;
    ApplyModePage1ASelectionState();
    assert(firmware_memory[0x0fb0u] == 0u && firmware_memory[0x0fb1u] == 0u);
    assert(firmware_memory[0x0fb2u] == 0u && firmware_memory[0x0fb3u] == 0x96u);
    assert(firmware_memory[0x00e6a2u] == 0x02u);
    assert(firmware_memory[0x00e6a7u] == 0u && firmware_memory[0x00e6a8u] == 0u);
    assert(firmware_memory[0x00e6a9u] == 0u && firmware_memory[0x00e6aau] == 0u);
    assert(read_count == 7u);
    assert(read_trace[0] == 0x00e6a2ul && read_trace[1] == 0x00e6a3ul);
    assert(read_trace[2] == 0x00e6a4ul && read_trace[3] == 0x00e6a5ul);
    assert(read_trace[4] == 0x00e6a6ul && read_trace[5] == 0x00e6a2ul);
    assert(read_trace[6] == 0x00e6a2ul);
    assert(write_count == 9u);
    assert(write_trace[0] == 0x000fb0ul && write_trace[1] == 0x000fb1ul);
    assert(write_trace[2] == 0x000fb2ul && write_trace[3] == 0x000fb3ul);
    assert(write_trace[4] == 0x00e6a2ul && write_trace[5] == 0x00e6a7ul);
    assert(write_trace[6] == 0x00e6a8ul && write_trace[7] == 0x00e6a9ul);
    assert(write_trace[8] == 0x00e6aaul);

    clear_memory(0);
    firmware_memory[0x000fb0u] = 0x5au;
    firmware_memory[0x00e6a7u] = 1u;
    firmware_memory[0x00e6a8u] = 2u;
    firmware_memory[0x00e6a9u] = 3u;
    firmware_memory[0x00e6aau] = 4u;
    ApplyModePage1ASelectionState();
    assert(firmware_memory[0x000fb0u] == 0x5au);
    assert(read_count == 2u && read_trace[0] == 0x00e6a2ul && read_trace[1] == 0x00e6a2ul);
    assert(write_count == 4u && write_trace[0] == 0x00e6a7ul && write_trace[1] == 0x00e6a8ul && write_trace[2] == 0x00e6a9ul && write_trace[3] == 0x00e6aaul);

    clear_memory(0);
    firmware_memory[0x00e6a2u] = 0xfdu;
    ApplyModePage1ASelectionState();
    assert(firmware_memory[0x00e6a2u] == 0xfcu);
    assert(read_count == 3u && read_trace[0] == 0x00e6a2ul && read_trace[1] == 0x00e6a2ul && read_trace[2] == 0x00e6a2ul);
    assert(write_count == 5u && write_trace[0] == 0x00e6a2ul && write_trace[1] == 0x00e6a7ul && write_trace[2] == 0x00e6a8ul && write_trace[3] == 0x00e6a9ul && write_trace[4] == 0x00e6aaul);
}

static void test_update_mode_page1a_runtime_image_for_current_media_state(void)
{
    static const struct
    {
        u32 countdown;
        u32 expected_scaled;
    } scaled_cases[] = {
        { 0ul,          1ul          },
        { 50ul,         1ul          },
        { 99ul,         1ul          },
        { 100ul,        2ul          },
        { 0xffffff9cul, 0xfffffffeul },
        { 0x80000000ul, 1ul          }
    };
    unsigned index;

    clear_memory(0u);
    for(index = 0u; index != 12u; ++index)
    {
        firmware_memory[0xff8b96ul + index] = (u8)(0x30u + index);
        firmware_memory[0x00e69ful + index] = 0xa5u;
    }
    UpdateModePage1ARuntimeImageForCurrentMediaState();
    for(index = 0u; index != 12u; ++index)
        assert(firmware_memory[0x00e69ful + index] == (u8)(0x30u + index));

    clear_memory(0xa5u);
    firmware_memory[0xe751u] = 0u;
    firmware_memory[0x0faeu] = 3u;
    set_memory_big_endian_u32(0x0fb4u, 0ul);
    UpdateModePage1ARuntimeImageForCurrentMediaState();
    assert(firmware_memory[0x00e6a2u] == 0u && get_memory_big_endian_u32(0x00e6a3u) == 0ul);

    for(index = 0u; index != sizeof(scaled_cases) / sizeof(scaled_cases[0]); ++index)
    {
        clear_memory(0u);
        firmware_memory[0x0faeu] = 3u;
        set_memory_big_endian_u32(0x0fb4u, 1ul);
        set_memory_big_endian_u32(0x0fb0u, scaled_cases[index].countdown);
        firmware_memory[0x00e6a2u] = 0xa5u;
        set_memory_big_endian_u32(0x00e6a3u, 0xa5a5a5a5ul);

        UpdateModePage1ARuntimeImageForCurrentMediaState();

        assert(firmware_memory[0x00e6a2u] == 2u);
        assert(get_memory_big_endian_u32(0x00e6a3u) == scaled_cases[index].expected_scaled);
    }
}

static void test_mode_select_page_wrapper_validators(void)
{
    typedef u8 (*validator_fn)(void);
    static validator_fn validators[] = { ValidateModeSelectPage03ParameterList, ValidateModeSelectPage07ParameterList, ValidateModeSelectPage1AParameterList, ValidateModeSelectPage1DParameterList };
    static const u8 pages[] = { 3u, 7u, 0x1au, 0x1du };
    static const fw_addr_t mask_addresses[] = { 0xff8a52ul, 0xff8b1eul, 0xff8b8aul, 0xff8baeul };
    unsigned index;

    for(index = 0u; index < sizeof(pages); index++)
    {
        clear_memory(0);
        firmware_memory[0x0b2bu] = pages[index];
        firmware_memory[0x0b2bu] = pages[index];
        assert(validators[index]() == 1u);
        firmware_memory[0x0b2bu] = 0u;
        assert(validators[index]() == 0u);
        firmware_memory[0x0b2bu] = pages[index];
        firmware_memory[0x0b2bu + 1u] = 1u;
        firmware_memory[0x0b2cu] = 0x80u;
        firmware_memory[mask_addresses[index] + 2u] = 0x80u;
        assert(validators[index]() == 0u);
    }
}

