static void test_apply_ata_set_features_command(void)
{
    static const u8 always_accepted[] = { 0x5du, 0x5eu, 0x66u, 0xccu, 0xddu, 0xdeu };
    unsigned feature, mode, capability;

    for(feature = 0u; feature < 256u; feature++)
    {
        clear_memory(0xa5u);
        firmware_memory[0x18050u] = (u8)feature;
        if(feature != 3u)
        {
            u8 expected = 0u;
            unsigned i;
            for(i = 0u; i < sizeof(always_accepted); i++)
                if((u8)feature == always_accepted[i])
                    expected = 1u;
            assert(ApplyAtaSetFeaturesCommand() == expected);
            assert(write_count == 0u);
        }
    }
    for(mode = 0u; mode < 256u; mode++)
        for(capability = 0u; capability < 2u; capability++)
        {
            u8 mode_class = (u8)mode & 0xf8u, index = (u8)mode & 7u;
            u8 expected = (u8)(mode_class == 0u || mode_class == 8u || mode_class == 0x20u || (mode_class == 0x40u && capability != 0u && index <= 2u));
            clear_memory(0xa5u);
            firmware_memory[0x18050u] = 3u;
            firmware_memory[0x18051u] = (u8)mode;
            firmware_memory[0x0c86u] = capability == 0u ? 0u : 8u;
            write_count = 0u;
            assert(ApplyAtaSetFeaturesCommand() == expected);
            if(mode_class == 8u)
            {
                assert(firmware_memory[0x0c2eu] == (index <= 4u ? index : 4u));
                assert(write_count == 1u);
            }
            else if(expected != 0u && mode_class != 0u)
            {
                assert(firmware_memory[0xfeu] == (u8)mode);
            }
            else
                assert(write_count == 0u);
        }
}

static void test_configure_ata_data_transfer_status(void)
{
    static const u8 commands[] = { 0x00u, 0x28u, 0xbeu, 0x2au, 0xaau };
    static const u8 speeds[] = { 0x0fu, 0x10u };
    unsigned active, ready, protocol, command_index, speed_index;

    for(active = 0u; active < 2u; active++)
        for(ready = 0u; ready < 2u; ready++)
            for(protocol = 0u; protocol < 8u; protocol++)
                for(command_index = 0u; command_index < sizeof(commands); command_index++)
                    for(speed_index = 0u; speed_index < sizeof(speeds); speed_index++)
                    {
                        u8 command = commands[command_index], speed = speeds[speed_index];
                        u8 expected = 0xa5u;
                        clear_memory(0xa5u);
                        firmware_memory[0x0c78u] = (u8)active;
                        firmware_memory[0x18050u] = (u8)ready;
                        firmware_memory[0x0c2bu] = (u8)protocol;
                        firmware_memory[0x0c2cu] = 0x22u;
                        firmware_memory[0x1805du] = 0x40u;
                        firmware_memory[0x0b0au] = command;
                        firmware_memory[0x0c38u] = speed;
                        write_count = 0u;
                        ConfigureAtaDataTransferStatus();
                        if(active == 0u)
                            assert(write_count == 0u);
                        else if(ready == 0u)
                            expected = 0x14u;
                        else if(protocol == 7u)
                        {
                            expected = 1u;
                            assert(write_count == 3u && write_trace[0] == 0x18047ul && write_trace[1] == 0x18049ul && write_trace[2] == 0x1805dul);
                            assert(firmware_memory[0x18049u] == 0x23u && firmware_memory[0x1805du] == 0x48u);
                        }
                        else if(command == 0xbeu || command == 0x28u)
                            expected = (u8)(protocol | 0x0cu);
                        else if(speed >= 0x10u && (command == 0xaau || command == 0x2au))
                            expected = (u8)protocol;
                        else
                            expected = (u8)(protocol | 4u);
                        if(active != 0u)
                            assert(firmware_memory[0x18047u] == expected);
                    }
}

static void test_publish_ata_command_completion(void)
{
    static const u8 statuses[] = { 0x50u, 0x51u };
    static const u8 flags[] = { 0u, 0x20u };
    static const u8 active_states[] = { 0u, 1u };
    unsigned status_index, flag_index, active_index;

    for(status_index = 0u; status_index < sizeof(statuses); status_index++)
    {
        for(flag_index = 0u; flag_index < sizeof(flags); flag_index++)
        {
            for(active_index = 0u; active_index < sizeof(active_states); active_index++)
            {
                u8 status = statuses[status_index];
                u8 flags_value = flags[flag_index];
                u8 active = active_states[active_index];
                clear_memory(0xa5u);
                firmware_memory[0x0c2fu] = status;
                firmware_memory[0x0c30u] = 0x32u;
                firmware_memory[0x0c86u] = flags_value;
                firmware_memory[0x0c78u] = active;
                write_count = 0u;
                PublishAtaCommandCompletion();
                assert(firmware_memory[0x18056u] == status);
                assert(firmware_memory[0x18050u] == ((status == 0x50u || flags_value != 0u) ? 0x32u : 0x36u));
                assert(firmware_memory[0x1804au] == (active == 0u ? 0x80u : 0xc0u));
                assert(firmware_memory[0x0c33u] == 5u);
                if(active == 0u)
                    assert(write_count == 4u && write_trace[2] == 0x1804aul);
                else
                    assert(write_count == 5u && write_trace[2] == 0x18051ul && write_trace[3] == 0x1804aul);
            }
        }
    }
}

static void test_prepare_ata_completion_status_from_sense(void)
{
    static const u8 sense_keys[] = { 0u, 1u, 5u, 0x0fu };
    unsigned protocol;
    unsigned index;

    for(protocol = 0u; protocol < 8u; protocol++)
    {
        for(index = 0u; index < sizeof(sense_keys); index++)
        {
            u8 sense_key = sense_keys[index];
            clear_memory(0xa5u);
            firmware_memory[0x0c2bu] = (u8)protocol;
            firmware_memory[0x0b1au] = sense_key;
            write_count = 0u;
            PrepareAtaCompletionStatusFromSense();
            assert(firmware_memory[0x0c2fu] == (sense_key == 0u ? 0x50u : 0x51u));
            assert(firmware_memory[0x0c30u] == (u8)(sense_key << 4));
            if(protocol == 7u)
            {
                assert(write_count == 3u && write_trace[0] == 0x018049ul && write_trace[1] == 0x0c2ful && write_trace[2] == 0x0c30ul);
                assert(firmware_memory[0x18049u] == 0u);
            }
            else
            {
                assert(write_count == 2u && write_trace[0] == 0x0c2ful && write_trace[1] == 0x0c30ul);
            }
        }
    }
}

