    assert(controller_command03_event_argument0[13] == 0xffffu && controller_command03_event_argument1[13] == 0x0339u);
    assert(controller_command03_event_argument0[14] == 1u && controller_command03_event_argument1[14] == 0x7au);
    assert(controller_command03_event_argument0[15] == 1u && controller_command03_event_argument1[15] == 0x035du);
    assert(controller_command03_event_argument0[16] == 2u && controller_command03_event_argument1[16] == 0xc3u);
    assert(read_count == 2u && read_trace[0] == 0x00f98eul && read_trace[1] == 0x00f98dul);
